148: 
149: fn camera(options: &Options, p: &Recipe) -> (Vec3, Vec3) {
150:     let (height, target, extent) = p.framing();
151:     if matches!(options.view, View::Underside) {
152:         (target + Vec3::new(0.7, -0.8, 1.5) * extent, target)
153:     } else if matches!(options.view, View::Head) {
154:         (target + Vec3::new(0.7, 0.95, 1.5) * extent, target)
155:     } else {
156:         let target = Vec3::Y * height * 0.52;
157:         (target + Vec3::new(0.6, 0.35, 1.65) * height, target)
158:     }
159: }
