183: fn rebuild(
184:     mut commands: Commands,
185:     mut editor: ResMut<Editor>,
186:     options: Res<Options>,
187:     old: Query<Entity, With<Specimen>>,
188:     mut meshes: ResMut<Assets<Mesh>>,
