479: /// The share of `geometry`'s triangles whose centre lies under the skin.
480: fn buried_share(geometry: &HairGeometry, skin: &MeshCollider) -> f32 {
481:     let buried = geometry
482:         .faces
483:         .iter()
484:         .filter(|face| {
485:             let centre = face
486:                 .iter()
487:                 .map(|&vertex| HairVec3::from_array(geometry.positions[vertex as usize]))
488:                 .fold(HairVec3::new(0.0, 0.0, 0.0), |sum, point| sum + point)
489:                 / 3.0;
490:             skin.distance(centre) < 0.0
491:         })
492:         .count();
493:     buried as f32 / geometry.faces.len().max(1) as f32
494: }
