411: fn census_terrain(
412:     meshes: &Query<
413:         (
414:             &ViewVisibility,
415:             &TerrainTriangleCount,
416:             Has<TerrainDetailPatch>,
417:             Has<TerrainMaterialPresentation>,
418:             Option<&VistaTerrainMesh>,
419:         ),
420:         With<Mesh3d>,
421:     >,
422: ) -> BTreeMap<String, MeshTierCensus> {
423:     let mut result = BTreeMap::<String, MeshTierCensus>::new();
424:     for (visibility, triangles, detail, playable, vista) in meshes {
425:         let tier = if detail {
426:             "detail patch".to_owned()
427:         } else if playable {
428:             "playable terrain".to_owned()
429:         } else if let Some(vista) = vista {
430:             format!("vista LOD{}", vista.0)
431:         } else {
432:             continue;
433:         };
434:         record_mesh(result.entry(tier).or_default(), visibility, triangles.0);
435:     }
436:     result
