439: fn census_buildings(
440:     meshes: &Query<(&ViewVisibility, &PresentedBuildingMesh), With<Mesh3d>>,
441: ) -> BTreeMap<String, MeshTierCensus> {
442:     let mut result = BTreeMap::<String, MeshTierCensus>::new();
443:     for (visibility, building) in meshes {
444:         let tier = format!("{:?}/{:?}", building.level, building.material);
445:         record_mesh(
446:             result.entry(tier).or_default(),
