453: 
454: fn census_grass(
455:     chunks: &Query<
456:         (
457:             &GroundScatterLayer,
458:             &InstanceChunk,
459:             &ViewVisibility,
460:             &GrassTriangleCount,
461:         ),
462:         Without<TacticalGameplayCamera>,
463:     >,
464:     camera_position: Vec3,
465: ) -> BTreeMap<String, GrassTierCensus> {
466:     let mut result = BTreeMap::<String, GrassTierCensus>::new();
467:     for (layer, chunk, visibility, triangle_count) in chunks {
468:         if *layer != GroundScatterLayer::Grass {
469:             continue;
470:         }
471:         let triangles_per_tuft = triangle_count.0;
472:         let band = chunk.band.shader_range();
473:         let tier = result
474:             .entry(format!("{:.3}-{:.3} metres", band.x, band.w))
475:             .or_default();
476:         let resident_tufts = chunk.instances.len();
477:         let drawn_tufts = if visibility.get() {
478:             chunk
479:                 .instances
480:                 .iter()
481:                 .filter(|instance| {
482:                     let distance = instance.position.distance(camera_position);
483:                     distance >= band.x && distance <= band.w
484:                 })
485:                 .count()
486:         } else {
487:             0
488:         };
489:         tier.resident_chunks += 1;
490:         tier.resident_tufts += resident_tufts;
491:         tier.drawn_tufts += drawn_tufts;
492:         tier.resident_triangles += resident_tufts * triangles_per_tuft;
493:         tier.drawn_triangles += drawn_tufts * triangles_per_tuft;
494:     }
495:     result
496: }
497: 
498: fn record_mesh(tier: &mut MeshTierCensus, visibility: &ViewVisibility, triangles: usize) {
499:     tier.resident_meshes += 1;
500:     tier.resident_triangles += triangles;
501:     if visibility.get() {
502:         tier.view_visible_meshes += 1;
503:         tier.view_visible_triangles += triangles;
504:     }
505: }

