127: fn command_output<const N: usize>(args: [&str; N]) -> String {
128:     let crate_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
129:     let repository_root = crate_dir
130:         .ancestors()
131:         .nth(2)
132:         .expect("building-generator crate lives below the repository root");
133:     let safe_directory = format!(
134:         "safe.directory={}",
135:         repository_root.display().to_string().replace('\\', "/")
136:     );
137:     Command::new("git")
138:         .current_dir(repository_root)
139:         .args(["-c", &safe_directory])
140:         .args(args)
141:         .output()
142:         .map(|output| {
143:             if output.status.success() {
144:                 String::from_utf8_lossy(&output.stdout).trim().to_owned()
145:             } else {
146:                 format!(
147:                     "UNAVAILABLE: git exited {:?}: {}",
148:                     output.status.code(),
149:                     String::from_utf8_lossy(&output.stderr).trim()
150:                 )
151:             }
152:         })
153:         .unwrap_or_else(|error| format!("UNAVAILABLE: {error}"))
154: }
