156: fn camera_path(dimensions: Vec2, maximum_height: f32) -> Vec<CameraPose> {
157:     let target = Vec3::new(0.0, maximum_height * 0.72, 0.0);
158:     let base_distance = dimensions.length().max(maximum_height) * 1.05;
159:     (0..CAMERA_SAMPLE_COUNT)
160:         .map(|index| {
161:             let t = index as f32 / (CAMERA_SAMPLE_COUNT - 1) as f32;
162:             let factor = START_DISTANCE_FACTOR.lerp(END_DISTANCE_FACTOR, t);
163:             let azimuth_degrees = START_AZIMUTH_DEGREES.lerp(END_AZIMUTH_DEGREES, t);
164:             let distance = base_distance * factor;
165:             let azimuth = azimuth_degrees.to_radians();
166:             let elevation = 0.18_f32;
167:             let horizontal = distance * elevation.cos();
168:             let position = target
169:                 + Vec3::new(
170:                     horizontal * azimuth.cos(),
171:                     distance * elevation.sin(),
172:                     horizontal * azimuth.sin(),
173:                 );
174:             CameraPose {
175:                 position,
176:                 target,
177:                 distance_metres: position.distance(target),
178:                 azimuth_degrees,
179:             }
180:         })

