58:     let mut fixtures = std::collections::HashMap::<&str, (&str, &str)>::new();
59:     for ((actual_name, manifest), (expected_name, expected_fixture, expected_view)) in
60:         records.iter().zip(CROWN_PROOF_SUITE)
