95:         .collect::<Vec<_>>();
96:     let regression_names = ROOF_REGRESSION_FIXTURES
97:         .iter()
98:         .map(|fixture| (format!("roof-{fixture}-regression"), "exterior".to_owned()))
99:         .collect::<Vec<_>>();
100:     let actual_count = fs::read_dir(directory)
101:         .map_err(|error| format!("read {}: {error}", directory.display()))?
102:         .filter_map(Result::ok)
103:         .filter(|entry| {
104:             entry
105:                 .file_name()
106:                 .to_string_lossy()
107:                 .ends_with(".capture.json")
108:         })
109:         .count();
110:     if actual_count != expected.len() + regression_names.len() {
111:         return Err(format!(
112:             "expected exactly 59 roof manifests, found {actual_count}"
113:         ));
114:     }
115:     let mut records = Vec::new();
116:     for (basename, view) in expected.drain(..) {
117:         let path = directory.join(format!("{basename}.capture.json"));
118:         let manifest: RoofSuiteManifest = serde_json::from_slice(
119:             &fs::read(&path).map_err(|error| format!("read {}: {error}", path.display()))?,
120:         )
121:         .map_err(|error| format!("parse {}: {error}", path.display()))?;
122:         records.push((basename.to_owned(), view.to_owned(), true, manifest));
123:     }
124:     for (basename, view) in regression_names {
125:         let path = directory.join(format!("{basename}.capture.json"));
126:         let manifest: RoofSuiteManifest = serde_json::from_slice(
127:             &fs::read(&path).map_err(|error| format!("read {}: {error}", path.display()))?,
128:         )
129:         .map_err(|error| format!("parse {}: {error}", path.display()))?;
130:         records.push((basename, view, false, manifest));
131:     }
132:     validate_roof_suite_records(&records)
133: }
