135: fn validate_roof_suite_records(
136:     records: &[(String, String, bool, RoofSuiteManifest)],
137: ) -> Result<(), String> {
138:     if records.len() != 59 {
139:         return Err(format!("expected 59 roof records, found {}", records.len()));
140:     }
141:     let first = &records[0].3;
142:     let mut fixture_hashes = std::collections::HashMap::new();
143:     let mut pitch_state_hashes = std::collections::HashSet::new();
144:     for (basename, expected_view, focused, manifest) in records {
145:         if manifest.view != *expected_view || !manifest.validation_passed {
146:             return Err(format!("{basename} has invalid view or failed capture QA"));
147:         }
148:         if manifest.resolver_schema_version != first.resolver_schema_version
149:             || manifest.source_revision != first.source_revision
150:             || manifest.source_dirty_fingerprint != first.source_dirty_fingerprint
151:         {
152:             return Err(format!("{basename} comes from a mixed source build"));
153:         }
154:         if manifest.roof_render_item_count != manifest.rendered_roof_item_count
155:             || manifest.roof_render_multiset_hash != manifest.rendered_roof_hash
156:         {
157:             return Err(format!("{basename} has roof renderer correspondence drift"));
158:         }
159:         if *focused
160:             && (manifest.focused_roof_item_ids.is_empty()
161:                 || manifest.visible_focused_roof_item_count
162:                     + manifest.section_removed_roof_item_ids.len()
163:                     != manifest.focused_roof_item_ids.len()
164:                 || !manifest.section_annotation_visible)
165:         {
166:             return Err(format!(
167:                 "{basename} lacks exact visible focused roof authority"
168:             ));
169:         }
170:         if manifest.roof_graph_hash.is_empty() {
171:             return Err(format!("{basename} lacks roof graph hash"));
172:         }
173:         if basename.ends_with("-drainage")
174:             && (manifest.roof_drainage_network_ids.is_empty()
175:                 || manifest.roof_drainage_channel_ids.is_empty()
176:                 || manifest.roof_drainage_outlet_ids.is_empty()
177:                 || manifest.roof_drainage_route_ids.is_empty()
178:                 || manifest.focused_resolved_void_ids.is_empty())
179:         {
180:             return Err(format!(
181:                 "{basename} lacks exact focused face-channel-outlet drainage authority"
182:             ));
183:         }
184:         let pitch_state = basename.contains("-low-pitch")
185:             || basename.contains("-mid-pitch")
186:             || basename.contains("-high-pitch");
187:         let demonstrator_state = pitch_state || basename.contains("roof-round-tower-");
188:         if pitch_state {
189:             pitch_state_hashes.insert(manifest.roof_graph_hash.clone());
190:         }
191:         if demonstrator_state {
192:             continue;
193:         } else if let Some((plan_hash, roof_hash)) = fixture_hashes.get(&manifest.fixture) {
194:             if plan_hash != &manifest.plan_hash || roof_hash != &manifest.roof_graph_hash {
195:                 return Err(format!(
196:                     "{basename} has fixture-inconsistent plan/roof hash"
197:                 ));
198:             }
199:         } else {
200:             fixture_hashes.insert(
201:                 manifest.fixture.clone(),
202:                 (manifest.plan_hash.clone(), manifest.roof_graph_hash.clone()),
203:             );
204:         }
205:     }
206:     if pitch_state_hashes.len() != 3 {
207:         return Err("low/mid/high pitch handles did not produce three roof graphs".to_owned());
208:     }
209:     Ok(())
210: }

