561: fn request_continuous_readbacks(
562:     commands: &mut Commands,
563:     state: &mut ShellCaptureConfig,
564:     camera: &mut Transform,
565:     diagnostic_camera: &mut Transform,
566:     diagnostic_target: &Handle<Image>,
567: ) {
568:     if state.continuous_index >= state.poses.len() {
569:         state.phase = CapturePhase::ContinuousDrain;
570:         return;
571:     }
572:     let sample_index = state.continuous_index;
573:     let pose = state.poses[sample_index];
574:     *camera = Transform::from_translation(pose.position).looking_at(pose.target, Vec3::Y);
