47:     let camera = |position, target| BuildingReviewCamera {
48:         position,
49:         target,
50:         plaster_raking_light: None,
51:     };
52:     let mut cameras = FurnitureKind::OUTDOOR
53:         .into_iter()
54:         .map(|kind| {
55:             let mut matching = layout
56:                 .instances
57:                 .iter()
58:                 .filter(|instance| instance.scene.key.kind() == kind);
59:             // Review the stable's last accepted group rather than the inn's
60:             // first group so the smaller frontage frames these low objects.
61:             let instance = if matches!(
62:                 kind,
63:                 FurnitureKind::TableBenchSet | FurnitureKind::HitchingTrough
64:             ) {
65:                 matching.next_back()
66:             } else {
67:                 matching.next()
68:             }
69:             .ok_or_else(|| format!("furniture review lacks {kind:?}"))?;
70:             let bounds = instance.scene.key.recipe()?.bounds;
71:             let distance =
72:                 bounds.plan_half_extents()?.metres().max_element() + CAMERA_OBJECT_CLEARANCE_METRES;
73:             let offset = instance
74:                 .orientation
75:                 .local_to_world(Vec2::new(distance * 0.6, -distance));
76:             let point = ScenePlanPoint::try_from(instance.position_metres.metres().xz() + offset)?;
77:             let height = terrain.required_height_at(point)?;
78:             Ok(camera(
