80:                     point.metres().x,
81:                     height.metres() + EYE_HEIGHT_METRES,
82:                     point.metres().y,
83:                 ))?,
84:                 Position::from_metres(
85:                     instance.position_metres.metres() + Vec3::Y * bounds.centre()?.metres().y,
86:                 )?,
87:             ))
88:         })
89:         .collect::<Result<Vec<_>>>()?;
