241: fn chunk_intersects_bounds(
242:     south: i16,
243:     west: i16,
244:     tile_width: u32,
245:     tile_height: u32,
246:     chunk_x: u32,
247:     chunk_y: u32,
248:     chunk_width: u32,
249:     chunk_height: u32,
250:     bounds: [f64; 4],
251: ) -> bool {
252:     let x = chunk_x * u32::from(CHUNK_SIDE);
253:     let y = chunk_y * u32::from(CHUNK_SIDE);
254:     let chunk_bounds = [
255:         f64::from(west) + f64::from(x) / f64::from(tile_width),
256:         f64::from(south + 1) - f64::from(y + chunk_height) / f64::from(tile_height),
257:         f64::from(west) + f64::from(x + chunk_width) / f64::from(tile_width),
258:         f64::from(south + 1) - f64::from(y) / f64::from(tile_height),
259:     ];
260:     chunk_bounds[2] > bounds[0]
261:         && chunk_bounds[0] < bounds[2]
262:         && chunk_bounds[3] > bounds[1]
263:         && chunk_bounds[1] < bounds[3]
264: }
