297: fn native_cell_is_hilly(
298:     elevations: &[f32],
299:     x: u32,
300:     y: u32,
301:     width: u32,
302:     height: u32,
303:     south: i16,
304: ) -> bool {
305:     const TAN_FIFTEEN_DEGREES: f64 = 0.267_949_192_431_122_7;
306:     const METRES_PER_DEGREE: f64 = 111_320.0;
307:     let center = elevations[y as usize * width as usize + x as usize];
308:     if !center.is_finite() || !(-500.0..=9_000.0).contains(&center) {
309:         return false;
310:     }
311:     let latitude = f64::from(south + 1) - (f64::from(y) + 0.5) / f64::from(height);
312:     let north_step = METRES_PER_DEGREE / f64::from(height);
313:     let east_step = METRES_PER_DEGREE * latitude.to_radians().cos() / f64::from(width);
314:     for offset_y in -1_i32..=1 {
315:         for offset_x in -1_i32..=1 {
316:             if offset_x == 0 && offset_y == 0 {
317:                 continue;
318:             }
319:             let neighbour_x = x as i32 + offset_x;
320:             let neighbour_y = y as i32 + offset_y;
321:             if neighbour_x < 0
322:                 || neighbour_y < 0
323:                 || neighbour_x >= width as i32
324:                 || neighbour_y >= height as i32
325:             {
326:                 continue;
327:             }
328:             let neighbour =
329:                 elevations[neighbour_y as usize * width as usize + neighbour_x as usize];
330:             if !neighbour.is_finite() || !(-500.0..=9_000.0).contains(&neighbour) {
331:                 continue;
332:             }
333:             let run = (f64::from(offset_x).powi(2) * east_step.powi(2)
334:                 + f64::from(offset_y).powi(2) * north_step.powi(2))
335:             .sqrt();
336:             if f64::from((center - neighbour).abs()) > run * TAN_FIFTEEN_DEGREES {
337:                 return true;
338:             }
339:         }
340:     }
341:     false
342: }
