344: type RoadMask = HashSet<(u16, u16)>;
345: type Mask = Vec<u8>;
346: 
347: fn masks(
348:     features: &Features,
349:     south: i16,
350:     west: i16,
351:     width: u32,
352:     height: u32,
353: ) -> (RoadMask, Mask, Mask, Mask) {
354:     let mut roads = HashSet::new();
355:     let to_pixel = |point: [f64; 2]| -> (i32, i32) {
356:         (
357:             ((point[0] - f64::from(west)) * f64::from(width)).round() as i32,
358:             ((f64::from(south + 1) - point[1]) * f64::from(height)).round() as i32,
359:         )
360:     };
361:     for line in &features.roads {
362:         for pair in line.windows(2) {
363:             let Some((clipped_a, clipped_b)) = clip_segment(
364:                 pair[0],
365:                 pair[1],
366:                 f64::from(west),
367:                 f64::from(south),
368:                 f64::from(west + 1),
369:                 f64::from(south + 1),
370:             ) else {
371:                 continue;
372:             };
373:             let a = to_pixel(clipped_a);
374:             let b = to_pixel(clipped_b);
375:             let steps = (a.0.abs_diff(b.0).max(a.1.abs_diff(b.1))).max(1);
376:             for step in 0..=steps {
377:                 let t = f64::from(step) / f64::from(steps);
378:                 let x = (f64::from(a.0) + (f64::from(b.0 - a.0)) * t).round() as i32;
379:                 let y = (f64::from(a.1) + (f64::from(b.1 - a.1)) * t).round() as i32;
380:                 for oy in -1..=1 {
381:                     for ox in -1..=1 {
382:                         let px = x + ox;
383:                         let py = y + oy;
384:                         if px >= 0 && py >= 0 && px < width as i32 && py < height as i32 {
385:                             roads.insert((px as u16, py as u16));
386:                         }
387:                     }
388:                 }
389:             }
390:         }
391:     }
392:     let water = polygon_mask(&features.water, south, west, width, height);
393:     let wetlands = polygon_mask(&features.wetlands, south, west, width, height);
394:     let cultivated = polygon_mask(&features.cultivated, south, west, width, height);
395:     (roads, water, wetlands, cultivated)
396: }
