398: fn polygon_mask(
399:     polygons: &[Vec<Vec<[f64; 2]>>],
400:     south: i16,
401:     west: i16,
402:     width: u32,
403:     height: u32,
404: ) -> Vec<u8> {
405:     let mut mask = vec![0_u8; width as usize * height as usize];
406:     for polygon in polygons {
407:         let Some([min_x, min_y, max_x, max_y]) = polygon_bounds(polygon) else {
408:             continue;
409:         };
410:         if max_x < f64::from(west)
411:             || min_x > f64::from(west + 1)
412:             || max_y < f64::from(south)
413:             || min_y > f64::from(south + 1)
414:         {
415:             continue;
416:         }
417:         let first_y = ((f64::from(south + 1) - max_y) * f64::from(height))
418:             .floor()
419:             .clamp(0.0, f64::from(height)) as u32;
420:         let last_y = ((f64::from(south + 1) - min_y) * f64::from(height))
421:             .ceil()
422:             .clamp(0.0, f64::from(height)) as u32;
423:         for y in first_y..last_y {
424:             let latitude = f64::from(south + 1) - (f64::from(y) + 0.5) / f64::from(height);
425:             let mut intersections = Vec::new();
426:             for ring in polygon {
427:                 for pair in ring.windows(2) {
428:                     let (a, b) = (pair[0], pair[1]);
429:                     if (a[1] > latitude) != (b[1] > latitude) {
430:                         intersections
431:                             .push(a[0] + (latitude - a[1]) * (b[0] - a[0]) / (b[1] - a[1]));
432:                     }
433:                 }
434:             }
435:             intersections.sort_by(f64::total_cmp);
436:             for pair in intersections.as_chunks::<2>().0 {
437:                 let start = ((pair[0] - f64::from(west)) * f64::from(width))
438:                     .floor()
439:                     .max(0.0) as usize;
440:                 let end = ((pair[1] - f64::from(west)) * f64::from(width))

441:                     .ceil()
442:                     .min(f64::from(width)) as usize;
443:                 for x in start.min(width as usize)..end.min(width as usize) {
444:                     mask[y as usize * width as usize + x] ^= 1;
445:                 }
446:             }
447:         }
448:     }
449:     mask
450: }
