465: fn clip_segment(
466:     a: [f64; 2],
467:     b: [f64; 2],
468:     min_x: f64,
469:     min_y: f64,
470:     max_x: f64,
471:     max_y: f64,
472: ) -> Option<([f64; 2], [f64; 2])> {
473:     let dx = b[0] - a[0];
474:     let dy = b[1] - a[1];
475:     let mut enter = 0.0_f64;
476:     let mut leave = 1.0_f64;
477:     for (p, q) in [
478:         (-dx, a[0] - min_x),
479:         (dx, max_x - a[0]),
480:         (-dy, a[1] - min_y),
481:         (dy, max_y - a[1]),
482:     ] {
483:         if p == 0.0 {
484:             if q < 0.0 {
485:                 return None;
486:             }
487:             continue;
488:         }
489:         let ratio = q / p;
490:         if p < 0.0 {
491:             enter = enter.max(ratio);
492:         } else {
493:             leave = leave.min(ratio);
494:         }
495:         if enter > leave {
496:             return None;
497:         }
498:     }
499:     Some((
500:         [a[0] + enter * dx, a[1] + enter * dy],
501:         [a[0] + leave * dx, a[1] + leave * dy],
502:     ))
503: }
