245: #[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
246: pub struct WorldEventEnvelope {
247:     pub schema_revision: u16,
248:     pub id: String,
249:     pub source: WorldEventSource,
250:     pub actor: WorldEventActor,
251:     /// Directed affected entities, in canonical enum/value order.
252:     pub subjects: Vec<WorldEventSubject>,
253:     /// Canonical occurrence place and legal jurisdiction. This is not proof
254:     /// that any character observed or learned about the event.
255:     pub place: WorldEventPlace,
256:     pub occurred_at_minute: StrategicMinute,
257:     pub payload: WorldEventPayloadRef,
258: }
259: 
260: impl WorldEventEnvelope {
261:     pub fn validate(&self) -> Result<(), WorldEventError> {
262:         if self.schema_revision != WORLD_EVENT_SCHEMA_REVISION {
263:             return Err(WorldEventError::UnsupportedSchemaRevision);
264:         }
265:         validate_id(&self.id)?;
266:         match &self.source {
267:             WorldEventSource::ForagingAction { request_id } => validate_id(request_id)?,
268:             WorldEventSource::GeneratedCaseFinale {
269:                 finale_id,
270:                 source_id,
271:             } => {
272:                 validate_id(finale_id)?;
273:                 validate_id(source_id)?;
274:             }
275:             WorldEventSource::FoodWaterExposure { consumption_id } => validate_id(consumption_id)?,
276:         }
277:         match &self.actor {
278:             WorldEventActor::Character { character_id } if *character_id == 0 => {
279:                 return Err(WorldEventError::ZeroCharacterId);
280:             }
281:             WorldEventActor::Party { party_id } => validate_id(party_id)?,
282:             WorldEventActor::Character { .. } => {}
283:         }
284:         if self.subjects.is_empty() || self.subjects.len() > MAX_WORLD_EVENT_SUBJECTS {
285:             return Err(WorldEventError::SubjectCountOutOfBounds);
286:         }
287:         let mut prior = None;
288:         let mut unique = BTreeSet::new();
289:         for subject in &self.subjects {
290:             match subject {
291:                 WorldEventSubject::Character { character_id } if *character_id == 0 => {
292:                     return Err(WorldEventError::ZeroCharacterId);
293:                 }
294:                 WorldEventSubject::Case { canonical_case_id } => validate_id(canonical_case_id)?,
295:                 WorldEventSubject::LocalProblem { problem_id } => validate_id(problem_id)?,
296:                 WorldEventSubject::Character { .. } => {}
297:             }
298:             if prior.is_some_and(|value| value >= subject) {
299:                 return Err(WorldEventError::SubjectsNotCanonical);
300:             }
301:             if !unique.insert(subject) {
302:                 return Err(WorldEventError::DuplicateSubject);
303:             }
304:             prior = Some(subject);
305:         }
306:         match &self.place {
307:             WorldEventPlace::Settlement { settlement_id } => validate_id(settlement_id)?,
308:             WorldEventPlace::Strategic { place_id } => validate_id(place_id)?,
309:         }
310:         match (&self.source, &self.actor, &self.payload) {
311:             (
312:                 WorldEventSource::ForagingAction { request_id: source },
313:                 WorldEventActor::Character { character_id },
314:                 WorldEventPayloadRef::NoticedIllegalForaging { request_id: payload },
315:             ) if source == payload
316:                 && self.subjects
317:                     == [WorldEventSubject::Character {
318:                         character_id: *character_id,
319:                     }] => {}
320:             (
321:                 WorldEventSource::GeneratedCaseFinale { finale_id: source, .. },
322:                 WorldEventActor::Party { .. },
323:                 WorldEventPayloadRef::GeneratedCaseResolution {
324:                     canonical_case_id,
325:                     finale_id: payload,
326:                 },
327:             ) if source == payload
328:                 && self.subjects.iter().any(|subject| matches!(subject,
329:                     WorldEventSubject::Case { canonical_case_id: subject_id } if subject_id == canonical_case_id
330:                 )) => {}
331:             (
332:                 WorldEventSource::FoodWaterExposure { .. },
333:                 WorldEventActor::Character { character_id },
334:                 WorldEventPayloadRef::FoodWaterInfection {
335:                     carrier_id,
336:                     contribution_digest,
337:                     dose_microunits,
338:                     protected_dose_microunits,
339:                     immunity_milli,
340:                     prior_immunity_milli,
341:                     consumed_fraction_bps,
342:                     disease_id,
343:                 },
344:             ) if *carrier_id != 0
345:                 && *dose_microunits != 0
346:                 && *protected_dose_microunits <= *dose_microunits
347:                 && *immunity_milli <= 100_000
348:                 && *prior_immunity_milli <= 100_000
349:                 && *consumed_fraction_bps <= BASIS_POINTS_PER_WHOLE
350:                 && validate_id(contribution_digest).is_ok()
351:                 && validate_id(disease_id).is_ok()
352:                 && self.subjects == [WorldEventSubject::Character { character_id: *character_id }] => {}
353:             _ => return Err(WorldEventError::InconsistentDomainReference),
354:         }
355:         Ok(())
356:     }
357: }
358: 
359: fn validate_id(value: &str) -> Result<(), WorldEventError> {
360:     if value.is_empty()
361:         || value.len() > MAX_WORLD_EVENT_ID_BYTES
362:         || value.chars().any(char::is_control)
363:     {
364:         Err(WorldEventError::InvalidIdentity)
365:     } else {
366:         Ok(())
367:     }
368: }
