372:     UnsupportedSchemaRevision,
373:     InvalidIdentity,
374:     ZeroCharacterId,
375:     SubjectCountOutOfBounds,
376:     SubjectsNotCanonical,
377:     DuplicateSubject,
378:     InconsistentDomainReference,
379: }
