388: /// Classify retry identity before consulting mutable domain state.
389: pub fn classify_world_event_retry(
390:     existing: Option<&WorldEventEnvelope>,
391:     proposed: &WorldEventEnvelope,
392: ) -> WorldEventReplayDecision {
393:     match existing {
394:         None => WorldEventReplayDecision::Apply,
395:         Some(existing) if existing == proposed => WorldEventReplayDecision::Replay,
396:         Some(_) => WorldEventReplayDecision::Collision,
397:     }
398: }

