35: /// Exact source identity is private; public subscribers receive only origin.
36: #[derive(Clone, Debug)]
37: #[table(accessor = filth_provenance)]
38: pub struct FilthProvenance {
39:     #[primary_key]
40:     pub filth_id: u64,
41:     pub source_character_id: Option<u64>,
42: }
