44: /// Private snapshot of source infection provenance at the instant of deposition.
45: #[derive(Clone, Debug)]
46: #[table(accessor = filth_disease_snapshot)]
47: pub struct FilthDiseaseSnapshot {
48:     #[primary_key]
49:     #[auto_inc]
50:     pub id: u64,
51:     #[index(btree)]
52:     pub filth_id: u64,
53:     pub disease_id: String,
54:     pub episode_id: u64,
55: }
56: 
57: /// Exact fractional travel-dirt accumulator. Eight dirt per 1,440 movement
58: /// minutes is represented as integer dirt-minute numerator for chunk invariance.
59: #[derive(Clone, Debug)]
60: #[table(accessor = travel_filth_progress)]
61: pub struct TravelFilthProgress {
62:     #[primary_key]
63:     pub character_id: u64,
64:     pub remainder_numerator: u16,
