67: /// Private deterministic exposure cursor. Absolute-minute seeds plus this
68: /// cursor prevent split intervals from rerolling already evaluated blood.
69: #[derive(Clone, Debug)]
70: #[table(accessor = blood_exposure_checkpoint)]
71: pub struct BloodExposureCheckpoint {
72:     #[primary_key]
73:     pub id: String,
74:     pub character_id: u64,
75:     pub disease_id: String,
76:     pub evaluated_through: StrategicMinute,
77: }
78: 
79: fn predicted_wound_routes(
80:     ctx: &ReducerContext,
81:     character_id: u64,
82:     allow_healing: bool,
83: ) -> Result<Vec<filth::TimedCutRoute>, String> {
84:     let natural = if allow_healing {
85:         crate::time::health_recovered_per_day(crate::time::party_physiology_check(
86:             ctx,
87:             character_id,
88:         )?)
89:     } else {
90:         0.0
91:     };
92:     Ok(ctx
93:         .db
94:         .limb_injury()
95:         .character_id()
96:         .filter(character_id)
97:         .filter(|injury| injury.cut_damage > 0.0)
98:         .map(|injury| {
99:             let state = if injury.stitched {
100:                 filth::CutRouteState::Stitched
101:             } else if injury.bandaged {
102:                 filth::CutRouteState::Bandaged
103:             } else {
104:                 filth::CutRouteState::Open
105:             };
106:             let active_minutes = if allow_healing && injury.bandaged {
107:                 let stitch_bonus = if injury.stitched {
108:                     injury.stitch_quality.max(0.0) * crate::surgery::STITCH_HEALING_BONUS_PER_LEVEL
109:                 } else {
110:                     0.0
111:                 };
112:                 let projectile_term = if ctx
113:                     .db
114:                     .retained_projectile()
115:                     .character_id()
116:                     .filter(character_id)
117:                     .any(|projectile| projectile.limb == injury.limb)
118:                 {
119:                     crate::surgery::RETAINED_PROJECTILE_HEALING_MULTIPLIER
120:                 } else {
121:                     1.0
122:                 };
123:                 let per_day = (natural + 0.01 + stitch_bonus) * projectile_term;
124:                 Some(
125:                     ((injury.cut_damage / per_day) * MINUTES_PER_DAY as f32)
126:                         .ceil()
127:                         .max(1.0) as u64,
128:                 )
129:             } else {
130:                 None
131:             };
132:             filth::TimedCutRoute {
133:                 state,
134:                 active_minutes,
135:             }
136:         })
137:         .collect())
138: }
