141: 
142: pub fn next_travel_dirt_boundary(ctx: &ReducerContext, character_id: u64) -> u64 {
143:     let remainder = ctx
144:         .db
145:         .travel_filth_progress()
146:         .character_id()
147:         .find(character_id)
148:         .map_or(0, |row| u64::from(row.remainder_numerator));
149:     (MINUTES_PER_DAY - remainder).div_ceil(8).max(1)
150: }

