1: //! Framework-neutral strategic filth, exposure, and automatic washing rules.
2: 
3: use crate::disease::{DiseaseId, TransmissionVector, definition};
4: use adventuresim_world_schema::calendar::{MINUTES_PER_DAY, StrategicMinute};
5: use serde::{Deserialize, Serialize};
6: 
7: /// The character sheet meter is deliberately bounded and deposits are clipped.
8: pub const MAX_FILTH: u16 = 100;
9: /// One whole unit of soft soap removes this much filth. Unused capacity is lost.
10: pub const SOAP_CLEANSING_CAPACITY: u16 = 25;
11: /// Blood remains visible, but its disease exposure falls linearly to zero after two days.
12: pub const BLOOD_INFECTIOUS_MINUTES: u64 = 2 * MINUTES_PER_DAY;
13: pub const TRAVEL_DIRT_PER_DAY: f32 = 8.0;
14: pub const COMBAT_DIRT: u16 = 10;
15: 
16: #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
17: #[cfg_attr(feature = "spacetimedb", derive(spacetimedb::SpacetimeType))]
18: pub enum FilthSubstance {
19:     Dirt,
20:     Blood,
21: }
22: 
23: #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
24: #[cfg_attr(feature = "spacetimedb", derive(spacetimedb::SpacetimeType))]
25: pub enum FilthOrigin {
26:     Own,
27:     Foreign,
28:     Unknown,
29: }
30: 
31: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
32: pub struct DiseaseSnapshot {
33:     pub disease_id: DiseaseId,
34:     pub episode_id: u64,
35: }
36: 
37: #[derive(Clone, Debug, PartialEq, Eq)]
38: pub struct Deposit {
39:     pub id: u64,
40:     pub character_id: u64,
41:     pub substance: FilthSubstance,
42:     pub source_character_id: Option<u64>,
43:     pub amount: u16,
44:     pub deposited_at: StrategicMinute,
45:     pub diseases: Vec<DiseaseSnapshot>,
46: }
47: 
48: impl Deposit {
49:     pub fn foreign_blood(&self) -> bool {
50:         self.substance == FilthSubstance::Blood
51:             && self.source_character_id != Some(self.character_id)
52:     }
53: 
54:     pub fn compatible_diseased_blood(&self) -> bool {
55:         self.substance == FilthSubstance::Blood
56:             && self
57:                 .diseases
58:                 .iter()
59:                 .any(|d| definition(d.disease_id).supports(TransmissionVector::Blood))
60:     }
61: }
62: 
63: pub fn bounded_deposit_amount(existing: u16, requested: u16) -> u16 {
64:     requested.min(MAX_FILTH.saturating_sub(existing.min(MAX_FILTH)))
65: }
66: 
67: pub fn travel_dirt(minutes: u64) -> u16 {
68:     ((minutes as f32 / MINUTES_PER_DAY as f32) * TRAVEL_DIRT_PER_DAY).round() as u16
69: }
70: 
71: /// Carries exact travel-dirt progress between movement chunks. The remainder is
72: /// measured in dirt-minutes over a denominator of 1,440.
73: pub fn travel_dirt_accrual(remainder_numerator: u16, minutes: u64) -> (u16, u16) {
74:     let numerator =
75:         u128::from(remainder_numerator).saturating_add(u128::from(minutes).saturating_mul(8));
76:     let minutes_per_day = u128::from(MINUTES_PER_DAY);
77:     let dirt = u16::try_from(numerator / minutes_per_day).unwrap_or(u16::MAX);
78:     (dirt, (numerator % minutes_per_day) as u16)
79: }
80: 
81: pub fn infectious_fraction(deposited_at: StrategicMinute, now: StrategicMinute) -> f32 {
82:     let age = now.elapsed_since(deposited_at);
83:     if age >= BLOOD_INFECTIOUS_MINUTES {
84:         0.0
85:     } else {
86:         1.0 - age as f32 / BLOOD_INFECTIOUS_MINUTES as f32
87:     }
88: }
89: 
90: /// Inclusive absolute-minute windows in which compatible foreign blood can
91: /// transmit. `from` is the already-committed cursor and is therefore excluded.
92: pub fn blood_infectious_windows(
93:     deposits: &[Deposit],
94:     disease_id: DiseaseId,
95:     from: StrategicMinute,
96:     to: StrategicMinute,
97: ) -> Vec<(StrategicMinute, StrategicMinute)> {
98:     if to <= from {
99:         return Vec::new();
100:     }
101:     let first_uncommitted = from.saturating_add_minutes(1);
102:     let mut windows = deposits
103:         .iter()
104:         .filter(|deposit| deposit.foreign_blood() && deposit.amount > 0)
105:         .filter(|deposit| {
106:             deposit
107:                 .diseases
108:                 .iter()
109:                 .any(|snapshot| snapshot.disease_id == disease_id)
110:         })
111:         .filter_map(|deposit| {
112:             let infectious_end = deposit
113:                 .deposited_at
114:                 .saturating_add_minutes(BLOOD_INFECTIOUS_MINUTES)
115:                 .saturating_sub_minutes(1);
116:             let start = first_uncommitted.max(deposit.deposited_at);
117:             let end = to.min(infectious_end);
118:             (start <= end).then_some((start, end))
119:         })
120:         .collect::<Vec<_>>();
121:     windows.sort_unstable();
122:     let mut merged: Vec<(StrategicMinute, StrategicMinute)> = Vec::new();
123:     for (start, end) in windows {
124:         if let Some(last) = merged.last_mut()
125:             && start <= last.1.saturating_add_minutes(1)
126:         {
127:             last.1 = last.1.max(end);
128:         } else {
129:             merged.push((start, end));
130:         }
131:     }
132:     merged
133: }
