135: /// Combines cut routes with diminishing returns. Open cuts are most vulnerable;
136: /// bandaging helps substantially and stitching helps further.
137: pub fn cut_exposure(open: u32, bandaged: u32, stitched: u32) -> f32 {
138:     let raw = open as f32 + bandaged as f32 * 0.40 + stitched as f32 * 0.18;
139:     1.0 - (-raw).exp()
140: }
141: 
142: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
143: pub enum CutRouteState {
144:     Open,
145:     Bandaged,
146:     Stitched,
147: }
148: 
149: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
150: pub struct TimedCutRoute {
151:     pub state: CutRouteState,
152:     /// None means the route remains active for the whole predicted interval.
153:     pub active_minutes: Option<u64>,
154: }
155: 
156: pub fn timed_cut_exposure(routes: &[TimedCutRoute], elapsed: u64) -> f32 {
157:     let (mut open, mut bandaged, mut stitched) = (0, 0, 0);
158:     for route in routes
159:         .iter()
160:         .filter(|route| route.active_minutes.is_none_or(|minutes| elapsed < minutes))
161:     {
162:         match route.state {
163:             CutRouteState::Open => open += 1,
164:             CutRouteState::Bandaged => bandaged += 1,
165:             CutRouteState::Stitched => stitched += 1,
166:         }
167:     }
168:     cut_exposure(open, bandaged, stitched)
169: }
