425: fn take_units(pool: &mut [WashStack], mut wanted: u32) -> Vec<WashStack> {
426:     let mut assigned = Vec::new();
427:     pool.sort_by_key(|stack| stack.key);
428:     for stack in pool {
429:         if wanted == 0 {
430:             break;
431:         }
432:         let quantity = stack.quantity.min(wanted);
433:         stack.quantity -= quantity;
434:         wanted -= quantity;
435:         if quantity > 0 {
436:             assigned.push(WashStack {
437:                 key: stack.key,
438:                 quantity,
439:             });
440:         }
441:     }
442:     assigned
443: }
