235: fn cleaning_rank(d: &Deposit, has_cut: bool) -> u8 {
236:     if d.compatible_diseased_blood() {
237:         0
238:     } else if d.foreign_blood() && has_cut {
239:         1
240:     } else if d.foreign_blood() {
241:         2
242:     } else if d.substance == FilthSubstance::Blood {
243:         3
