252:     pub best_substance_rank: u8,
253:     pub exposure: f32,
254:     pub total_filth: u32,
255: }
256: 
257: pub fn wash_priority(
258:     character_id: u64,
259:     deposits: &[Deposit],
260:     has_cut: bool,
261:     exposure: f32,
262: ) -> WashPriority {
263:     WashPriority {
264:         character_id,
265:         best_substance_rank: deposits
266:             .iter()
267:             .map(|d| cleaning_rank(d, has_cut))
268:             .min()
269:             .unwrap_or(5),
270:         exposure: exposure.max(0.0),
271:         total_filth: deposits.iter().map(|d| u32::from(d.amount)).sum(),
272:     }
273: }
274: 
275: pub fn sort_wash_priorities(priorities: &mut [WashPriority]) {
276:     priorities.sort_by(|left, right| {
277:         left.best_substance_rank
278:             .cmp(&right.best_substance_rank)
279:             .then_with(|| right.exposure.total_cmp(&left.exposure))
280:             .then_with(|| right.total_filth.cmp(&left.total_filth))
281:             .then_with(|| left.character_id.cmp(&right.character_id))
282:     });
283: }
