285: /// Plans a stable, personal-first wash in cleansing-capacity points.
286: ///
287: /// One full soap unit supplies [`SOAP_CLEANSING_CAPACITY`] points. Keeping the
288: /// plan in points lets persistence consume only the fraction actually needed.
289: pub fn plan_wash(deposits: &[Deposit], stacks: &[WashStack], has_cut: bool) -> WashPlan {
290:     let total: u32 = deposits.iter().map(|d| u32::from(d.amount)).sum();
291:     if total == 0 {
292:         return WashPlan {
293:             soap_stacks: vec![],
294:             cleaned_deposits: vec![],
295:         };
296:     }
297:     let needed = total;
298:     let mut ordered_stacks = stacks.to_vec();
299:     ordered_stacks.sort_by_key(|s| (s.key.source, s.key.id));
300:     let mut remaining_units = needed;
301:     let mut soap_stacks = Vec::new();
302:     for stack in ordered_stacks {
303:         let used = stack.quantity.min(remaining_units);
304:         if used > 0 {
305:             soap_stacks.push((stack.key, used));
306:             remaining_units -= used;
307:         }
308:         if remaining_units == 0 {
309:             break;
310:         }
311:     }
312:     let units: u32 = soap_stacks.iter().map(|(_, q)| *q).sum();
313:     let mut capacity = units;
314:     let mut ordered = deposits.to_vec();
315:     ordered.sort_by_key(|d| (cleaning_rank(d, has_cut), d.deposited_at, d.id));
316:     let mut cleaned_deposits = Vec::new();
317:     for d in ordered {
318:         if capacity == 0 {
319:             break;
320:         }
321:         let removed = u32::from(d.amount).min(capacity) as u16;
322:         capacity -= u32::from(removed);
323:         cleaned_deposits.push((d.id, removed));
324:     }
325:     WashPlan {
326:         soap_stacks,
327:         cleaned_deposits,
328:     }
329: }
