445: fn plan_party_wash(
446:     ctx: &ReducerContext,
447:     character_ids: &[u64],
448: ) -> Result<(Vec<PlannedCharacterWash>, WashSummary), String> {
449:     struct Subject {
450:         id: u64,
451:         dirty: Vec<Deposit>,
452:         cut: bool,
453:         assigned: Vec<WashStack>,
454:         remaining: u32,
455:     }
456:     let mut subjects = Vec::new();
457:     let mut party_id = None;
458:     for id in character_ids.iter().copied() {
459:         let character = ctx
460:             .db
461:             .character()
462:             .id()
463:             .find(id)
464:             .ok_or("Character not found")?;
465:         if !character.alive {
466:             continue;
467:         }
468:         party_id = party_id.or(character.party_id.clone());
469:         let dirty = deposits(ctx, id)?;
470:         if dirty.is_empty() {
471:             continue;
472:         }
473:         let needed = dirty.iter().map(|d| u32::from(d.amount)).sum::<u32>();
474:         let mut personal = ctx
475:             .db
476:             .inventory_item()
477:             .character_and_item_id()
478:             .filter((id, SOFT_SOAP_ID))
479:             .map(|stack| WashStack {
480:                 key: SoapStackId {
481:                     source: SoapSource::Personal,
482:                     id: stack.id,
483:                 },
484:                 quantity: crate::inventory_amount::personal_fraction(ctx, stack.id)
485:                     .unwrap_or_default()
486:                     .get()
487:                     / SOAP_FRACTION_PER_CLEANSING_POINT.get(),
488:             })
489:             .collect::<Vec<_>>();
490:         let assigned = take_units(&mut personal, needed);
491:         let personal_used = assigned.iter().map(|stack| stack.quantity).sum::<u32>();
492:         subjects.push(Subject {
493:             id,
494:             cut: has_cut(ctx, id),
495:             dirty,
496:             assigned,
497:             remaining: needed.saturating_sub(personal_used),
498:         });
499:     }
500:     let mut shared = party_id.as_ref().map_or_else(Vec::new, |party_id| {
501:         ctx.db
502:             .party_inventory_item()
503:             .party_id()
504:             .filter(party_id)
505:             .filter(|stack| stack.item_id == SOFT_SOAP_ID)
506:             .map(|stack| WashStack {
507:                 key: SoapStackId {
508:                     source: SoapSource::Party,
509:                     id: stack.id,
510:                 },
511:                 quantity: crate::inventory_amount::party_fraction(ctx, stack.id)
512:                     .unwrap_or_default()
513:                     .get()
514:                     / SOAP_FRACTION_PER_CLEANSING_POINT.get(),
515:             })
516:             .collect::<Vec<_>>()
517:     });
518:     let mut priorities = subjects
519:         .iter()
520:         .map(|subject| {
521:             let now = ctx
522:                 .db
523:                 .character_time()
524:                 .character_id()
525:                 .find(subject.id)
526:                 .map_or(StrategicMinute::ZERO, |t| t.minutes);
527:             let exposure = filth::blood_exposure(
528:                 &subject.dirty,
529:                 adventuresim_core::disease::DiseaseId::Plague,
530:                 now,
531:                 filth::timed_cut_exposure(&predicted_wound_routes(ctx, subject.id, false)?, 0),
532:             );
533:             Ok::<_, String>(filth::wash_priority(
534:                 subject.id,
535:                 &subject.dirty,
536:                 subject.cut,
537:                 exposure,
538:             ))
539:         })
540:         .collect::<Result<Vec<_>, _>>()?;
541:     filth::sort_wash_priorities(&mut priorities);
542:     for priority in priorities {
543:         let subject = subjects
544:             .iter_mut()
545:             .find(|subject| subject.id == priority.character_id)
546:             .unwrap();
547:         let assigned = take_units(&mut shared, subject.remaining);
548:         let used = assigned.iter().map(|stack| stack.quantity).sum::<u32>();
549:         subject.remaining -= used;
550:         subject.assigned.extend(assigned);
551:     }
552:     let mut summary = WashSummary::default();
553:     let planned = subjects
554:         .into_iter()
555:         .map(|subject| {
556:             let plan = filth::plan_wash(&subject.dirty, &subject.assigned, subject.cut);
557:             for (key, quantity) in &plan.soap_stacks {
558:                 summary.total_units += quantity;
559:                 match key.source {
560:                     SoapSource::Personal => summary.personal_units += quantity,
561:                     SoapSource::Party => summary.shared_units += quantity,
562:                 }
563:                 summary.stacks.push((*key, *quantity));
564:             }
565:             PlannedCharacterWash {
566:                 character_id: subject.id,
567:                 plan,
568:             }
569:         })
570:         .collect();
571:     summary.stacks.sort_by_key(|(key, _)| *key);
572:     Ok((planned, summary))
573: }
