582: pub fn wash_party_before_explicit_rest(
583:     ctx: &ReducerContext,
584:     character_ids: &[u64],
585: ) -> Result<WashSummary, String> {
586:     let (planned, summary) = plan_party_wash(ctx, character_ids)?;
587:     // Preflight exact tagged identities before the first mutation.
588:     for (key, quantity) in &summary.stacks {
589:         match key.source {
590:             SoapSource::Personal => {
591:                 let stack = ctx
592:                     .db
593:                     .inventory_item()
594:                     .id()
595:                     .find(key.id)
596:                     .ok_or("Planned personal soap stack is missing")?;
597:                 if stack.item_id != SOFT_SOAP_ID
598:                     || crate::inventory_amount::personal_fraction(ctx, stack.id).unwrap_or_default()
599:                         < SOAP_FRACTION_PER_CLEANSING_POINT
600:                             .checked_mul(*quantity)
601:                             .ok_or("Planned personal soap amount overflow")?
602:                 {
603:                     return Err("Planned personal soap is no longer available".into());
604:                 }
605:             }
606:             SoapSource::Party => {
607:                 let stack = ctx
608:                     .db
609:                     .party_inventory_item()
610:                     .id()
611:                     .find(key.id)
612:                     .ok_or("Planned shared soap stack is missing")?;
613:                 if stack.item_id != SOFT_SOAP_ID
614:                     || crate::inventory_amount::party_fraction(ctx, stack.id).unwrap_or_default()
615:                         < SOAP_FRACTION_PER_CLEANSING_POINT
616:                             .checked_mul(*quantity)
617:                             .ok_or("Planned shared soap amount overflow")?
618:                 {
619:                     return Err("Planned shared soap is no longer available".into());
620:                 }
621:             }
622:         }
623:     }
624:     for (key, quantity) in &summary.stacks {
625:         match key.source {
626:             SoapSource::Personal => consume_personal(ctx, key.id, *quantity)?,
627:             SoapSource::Party => consume_party(ctx, key.id, *quantity)?,
628:         }
629:     }
630:     for character in planned {
631:         for (id, removed) in character.plan.cleaned_deposits {
632:             if let Some(mut row) = ctx.db.character_filth().id().find(id) {
633:                 if row.character_id != character.character_id || row.amount < removed {
634:                     return Err("Planned filth deposit changed before washing".into());
635:                 }
636:                 row.amount = row
637:                     .amount
638:                     .checked_sub(removed)
639:                     .ok_or("Filth removal underflow")?;
640:                 if row.amount == 0 {
641:                     for snapshot in ctx
642:                         .db
643:                         .filth_disease_snapshot()
644:                         .filth_id()
645:                         .filter(id)
646:                         .collect::<Vec<_>>()
647:                     {
648:                         ctx.db.filth_disease_snapshot().id().delete(snapshot.id);
649:                     }
650:                     ctx.db.filth_provenance().filth_id().delete(id);
651:                     ctx.db.character_filth().id().delete(id);
652:                 } else {
653:                     ctx.db.character_filth().id().update(row);
654:                 }
655:             } else {
656:                 return Err("Planned filth deposit is missing".into());
657:             }
658:         }
659:     }
660:     Ok(summary)
661: }
