668: pub fn preview_soap_units(ctx: &ReducerContext, character_id: u64) -> u32 {
669:     let amount: u32 = ctx
670:         .db
671:         .character_filth()
672:         .character_id()
673:         .filter(character_id)
674:         .map(|d| u32::from(d.amount))
675:         .sum();
676:     if amount == 0 {
677:         return 0;
678:     }
679:     let available: u32 = ctx
680:         .db
681:         .inventory_item()
682:         .character_and_item_id()
683:         .filter((character_id, SOFT_SOAP_ID))
684:         .map(|s| {
685:             crate::inventory_amount::personal_fraction(ctx, s.id)
686:                 .unwrap_or_default()
687:                 .get()
688:                 / SOAP_FRACTION_PER_CLEANSING_POINT.get()
689:         })
690:         .sum::<u32>()
691:         + ctx
692:             .db
693:             .character()
694:             .id()
695:             .find(character_id)
