499: pub(super) fn party_role_match(
500:     capabilities: &[CharacterCapability],
501:     role: &RecruitmentRoleView,
502: ) -> (&'static str, String) {
503:     let total = role_requirement_labels(role).len();
504:     if total == 0 {
505:         return (
506:             "none",
507:             "This role has no minimum recommendations.".to_string(),
508:         );
509:     }
510:     let best = capabilities
511:         .iter()
512:         .map(|capability| matched_role_requirements(capability, role))
513:         .max()
514:         .unwrap_or(0);
515:     if best == total {
516:         (
517:             "all",
518:             "Someone in your party meets every recommendation.".to_string(),
519:         )
520:     } else if best > 0 {
521:         (
522:             "some",
523:             format!("Your best candidate meets {best} of {total} recommendations."),
524:         )
525:     } else {
526:         (
527:             "none-met",
528:             "No one in your party meets any recommendation.".to_string(),
529:         )
530:     }
531: }
