533: pub(super) fn matched_role_requirements(
534:     capability: &CharacterCapability,
535:     role: &RecruitmentRoleView,
536: ) -> usize {
537:     let requirements: RoleRequirements = role.requirements;
538:     let mut matched = 0;
539:     for (required, present) in [
540:         (requirements.melee, capability.melee),
541:         (requirements.ranged, capability.ranged),
542:         (requirements.heavy, capability.heavy),
543:         (requirements.quarter_armor, capability.quarter_armor),
544:         (requirements.half_armor, capability.half_armor),
545:         (
546:             requirements.three_quarter_armor,
547:             capability.three_quarter_armor,
548:         ),
549:         (requirements.full_armor, capability.full_armor),
550:     ] {
551:         if required && present {
552:             matched += 1;
553:         }
554:     }
555:     if requirements.weapon_precision > 0.0
556:         && capability.weapon_precision >= requirements.weapon_precision
557:     {
558:         matched += 1;
559:     }
560:     for (minimum, value) in [
561:         (requirements.athletics, capability.athletics),
562:         (requirements.endurance, capability.endurance),
563:     ] {
564:         if minimum > 0 && adventuresim_core::capability::rating(value) >= minimum {
565:             matched += 1;
566:         }
567:     }
568:     matched
569: }
