58: impl fmt::Display for CatalogValidationError {
59:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
60:         writeln!(
61:             formatter,
62:             "item catalog validation failed ({} errors):",
63:             self.diagnostics.len()
64:         )?;
65:         for (index, diagnostic) in self.diagnostics.iter().enumerate() {
66:             if index > 0 {
67:                 writeln!(formatter)?;
68:             }
69:             let file = self
70:                 .files
71:                 .get(diagnostic.source_index)
72:                 .map(String::as_str)
73:                 .unwrap_or("item catalog");
74:             if let Some(source) = self.sources.get(diagnostic.source_index) {
75:                 let (line, column) = source_coordinates(source, &diagnostic.path);
76:                 write!(
77:                     formatter,
78:                     "{file}:{line}:{column}: {}: {}",
79:                     diagnostic.path, diagnostic.message
80:                 )?;
81:             } else {
82:                 write!(
83:                     formatter,
84:                     "{file}: {}: {}",
85:                     diagnostic.path, diagnostic.message
86:                 )?;
87:             }
88:         }
89:         Ok(())
90:     }
91: }
