133: pub fn parse_document(text: &str) -> Result<Value, serde_json::Error> {
134:     serde_json::from_str::<StrictValue>(text).map(|value| value.0)
135: }
136: 
137: struct StrictValue(Value);
138: 
139: impl<'de> Deserialize<'de> for StrictValue {
140:     fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
141:     where
142:         D: Deserializer<'de>,
143:     {
144:         deserializer.deserialize_any(StrictValueVisitor)
145:     }
146: }
147: 
148: struct StrictValueVisitor;
149: 
150: impl<'de> Visitor<'de> for StrictValueVisitor {
151:     type Value = StrictValue;
152: 
153:     fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
154:         formatter.write_str("a strict JSON-compatible YAML value")
155:     }
156: 
157:     fn visit_bool<E: de::Error>(self, value: bool) -> Result<Self::Value, E> {
158:         Ok(StrictValue(value.into()))
159:     }
160:     fn visit_i64<E: de::Error>(self, value: i64) -> Result<Self::Value, E> {
161:         Ok(StrictValue(value.into()))
162:     }
163:     fn visit_u64<E: de::Error>(self, value: u64) -> Result<Self::Value, E> {
164:         Ok(StrictValue(value.into()))
165:     }
166:     fn visit_f64<E: de::Error>(self, value: f64) -> Result<Self::Value, E> {
167:         serde_json::Number::from_f64(value)
168:             .map(Value::Number)
169:             .map(StrictValue)
170:             .ok_or_else(|| E::custom("non-finite number"))
171:     }
172:     fn visit_str<E: de::Error>(self, value: &str) -> Result<Self::Value, E> {
173:         Ok(StrictValue(value.into()))
174:     }
175:     fn visit_string<E: de::Error>(self, value: String) -> Result<Self::Value, E> {
176:         Ok(StrictValue(value.into()))
177:     }
178:     fn visit_none<E: de::Error>(self) -> Result<Self::Value, E> {
179:         Ok(StrictValue(Value::Null))
180:     }
181:     fn visit_unit<E: de::Error>(self) -> Result<Self::Value, E> {
182:         self.visit_none()
183:     }
184:     fn visit_seq<A: SeqAccess<'de>>(self, mut sequence: A) -> Result<Self::Value, A::Error> {
185:         let mut values = Vec::new();
186:         while let Some(value) = sequence.next_element::<StrictValue>()? {
187:             values.push(value.0);
188:         }
189:         Ok(StrictValue(values.into()))
190:     }
191:     fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Self::Value, A::Error> {
192:         let mut values = BTreeMap::new();
193:         while let Some(key) = map.next_key::<String>()? {
194:             if values.contains_key(&key) {
195:                 return Err(de::Error::custom(format!("duplicate mapping key {key:?}")));
196:             }
197:             values.insert(key, map.next_value::<StrictValue>()?.0);
198:         }
199:         Ok(StrictValue(
200:             values.into_iter().collect::<Map<_, _>>().into(),
201:         ))
202:     }
203: }
