203: fn melee_contact_coordinates(contact_sample: f32, gap_targeting: f32) -> (BodyPart, f32) {
204:     let (body_part, local_coordinate) =
205:         weighted_body_part_and_local(contact_sample.clamp(0.0, 1.0_f32.next_down()), |_| 1.0);
206:     let gap_targeting = gap_targeting.clamp(0.0, 1.0);
207:     let targeted_coordinate = (local_coordinate
208:         + (1.0_f32.next_down() - local_coordinate) * gap_targeting)
209:         .clamp(0.0, 1.0_f32.next_down());
210:     (body_part, targeted_coordinate)
211: }
