213: #[must_use]
214: pub fn anatomical_subregion(body_part: BodyPart, area_sample: f32) -> AnatomicalSubregion {
215:     let area_sample = area_sample.clamp(0.0, 1.0_f32.next_down());
216:     match body_part {
217:         BodyPart::LeftArm => AnatomicalSubregion::LeftArm,
218:         BodyPart::RightArm => AnatomicalSubregion::RightArm,
219:         BodyPart::LeftLeg => AnatomicalSubregion::LeftLeg,
220:         BodyPart::RightLeg => AnatomicalSubregion::RightLeg,
221:         BodyPart::Stomach if area_sample < ABDOMEN_END => AnatomicalSubregion::Abdomen,
222:         BodyPart::Stomach => AnatomicalSubregion::Groin,
223:         BodyPart::Head => AnatomicalSubregion::Head,
224:         BodyPart::Chest if area_sample < CHEST_STERNUM_END => AnatomicalSubregion::ChestSternum,
225:         BodyPart::Chest if area_sample < CHEST_LATERAL_RIBS_END => {
226:             AnatomicalSubregion::ChestLateralRibs
227:         }
228:         BodyPart::Chest if area_sample < CHEST_LOWER_EDGE_END => {
229:             AnatomicalSubregion::ChestLowerEdge
230:         }
231:         BodyPart::Chest if area_sample < CHEST_AXILLA_END => AnatomicalSubregion::ChestAxilla,
232:         BodyPart::Chest => AnatomicalSubregion::ChestNeckline,
233:     }
234: }
