236: fn weighted_body_part_and_local(sample: f32, factor: impl Fn(BodyPart) -> f32) -> (BodyPart, f32) {
237:     let total = BODY_PART_CONTACT_WEIGHTS
238:         .iter()
239:         .map(|(part, weight)| weight * factor(*part).max(0.0))
240:         .sum::<f32>();
241:     let mut cursor = sample * total;
242:     for (part, weight) in BODY_PART_CONTACT_WEIGHTS {
243:         let candidate_weight = weight * factor(part).max(0.0);
244:         if candidate_weight <= 0.0 {
245:             continue;
246:         }
247:         if cursor < candidate_weight {
248:             return (
249:                 part,
250:                 (cursor / candidate_weight).clamp(0.0, 1.0_f32.next_down()),
251:             );
252:         }
253:         cursor -= candidate_weight;
254:     }
255:     (BodyPart::Head, 1.0_f32.next_down())
256: }
