105:         .find(|placement| Some(placement.id.as_str()) == item.selected_placement_id.as_deref())
106:         .expect("validated armor retains its authored placement");
107:     let slot = match part {
108:         EquipmentBodyPart::LeftArm => ArmorSlot::Arms(Some(ArmorSide::Left)),
109:         EquipmentBodyPart::RightArm => ArmorSlot::Arms(Some(ArmorSide::Right)),
110:         EquipmentBodyPart::LeftLeg => ArmorSlot::Legs(Some(ArmorSide::Left)),
111:         EquipmentBodyPart::RightLeg => ArmorSlot::Legs(Some(ArmorSide::Right)),
112:         EquipmentBodyPart::Head => ArmorSlot::Head,
113:         EquipmentBodyPart::Chest => ArmorSlot::Chest,
114:         EquipmentBodyPart::Stomach => ArmorSlot::Stomach,
115:     };
116:     let mut coverage_geometry = [None; 7];
117:     for protected in &placement.protection {
118:         let body_part = adventuresim_core::equipment::equipment_body_part(*protected);
119:         let geometry =
120:             adventuresim_core::combat::AuthoredArmorCoverage::from_placement(placement, body_part);
