17:     };
18:     for point in points {
19:         for (axis, coordinate) in point.iter().enumerate() {
20:             bounds.min[axis] = bounds.min[axis].min(*coordinate);
21:             bounds.max[axis] = bounds.max[axis].max(*coordinate);
22:         }
23:     }
24:     bounds
25: }
