62: pub(crate) fn derived<'a>(
63:     design: &WeaponDesign,
64:     p: &PhysicalProperties,
65:     frames: &std::collections::BTreeMap<String, [f64; 3]>,
66:     parts: impl Iterator<Item = (&'a str, impl Iterator<Item = [f64; 3]>)>,
67: ) -> DerivedProperties {
68:     let head_ids: Vec<_> = design
69:         .recipe
70:         .components
71:         .iter()
72:         .filter(|c| c.role == Some(ComponentRole::Head))
73:         .filter_map(|c| c.id.as_deref())
74:         .collect();
75:     let (mut head_min, mut head_max) = (f64::INFINITY, f64::NEG_INFINITY);
76:     let (mut min, mut max) = (f64::INFINITY, f64::NEG_INFINITY);
77:     for (id, points) in parts {
78:         let working_section = design
79:             .recipe
80:             .components
81:             .iter()
82:             .find(|c| c.id.as_deref() == Some(id))
83:             .and_then(|c| match &c.shape {
84:                 recipe::Shape::Spear(parameters) if parameters.socket.is_some() => {
85:                     let base = frames.get(&format!("{id}.bladeBase"))?;
86:                     let tip = frames.get(&format!("{id}.tip"))?;
87:                     Some((base, tip))
88:                 }
89:                 _ => None,
90:             });
91:         for point in points {
92:             min = min.min(point[1]);
93:             max = max.max(point[1]);
94:             let within_working_section = working_section.is_none_or(|(base, tip)| {
95:                 construction::dot(
96:                     construction::sub(point, *base),
97:                     construction::sub(*tip, *base),
98:                 ) >= -1e-12
99:             });
100:             if head_ids.contains(&id) && within_working_section {
101:                 head_min = head_min.min(point[1]);
102:                 head_max = head_max.max(point[1]);
103:             }
104:         }
105:     }
106:     DerivedProperties {
107:         mass_kg: p.mass_kg as f32,
108:         length_m: (max - min) as f32,
109:         grip_to_tip_m: p.grip_to_tip_m as f32,
110:         striking_head_length_m: if head_min.is_finite() {
111:             (head_max - head_min) as f32
112:         } else {
113:             0.0
114:         },
115:         center_of_mass_from_grip_m: p.center_of_mass_from_grip_m as f32,
116:         moment_of_inertia_kg_m2: p.moment_of_inertia_kg_m2 as f32,
117:         balance: p.balance as f32,
118:     }
119: }
