130: fn cross(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
131:     [
132:         a[1] * b[2] - a[2] * b[1],
133:         a[2] * b[0] - a[0] * b[2],
134:         a[0] * b[1] - a[1] * b[0],
