218:     let first =
219:         ((b[1] - c[1]) * (point[0] - c[0]) + (c[0] - b[0]) * (point[1] - c[1])) / determinant;
220:     let second =
221:         ((c[1] - a[1]) * (point[0] - c[0]) + (a[0] - c[0]) * (point[1] - c[1])) / determinant;
222:     let third = 1.0 - first - second;
223:     const UV_EDGE_EPSILON: f64 = 1e-6;
224:     [first, second, third]
225:         .iter()
226:         .all(|weight| *weight >= -UV_EDGE_EPSILON && *weight <= 1.0 + UV_EDGE_EPSILON)
227:         .then_some([first, second, third])
