1463: pub struct QueryManyIter<'w, 's, D: QueryData, F: QueryFilter, I: Iterator<Item: EntityEquivalent>>
1464: {
1465:     world: UnsafeWorldCell<'w>,
1466:     entity_iter: I,
1467:     entities: &'w Entities,
1468:     tables: &'w Tables,
1469:     archetypes: &'w Archetypes,
