515: /// Apply authored curriculum entries without requiring database or clock state.
516: pub fn apply_curriculum_training(
517:     hours: &mut SkillHours,
518:     work_hours: f32,
519:     entries: &[crate::organization::TrainingEntry],
520:     activities: ActivityTrainingProfile,
521:     attributes: &impl PlayerAttributes,
522: ) -> (f32, Vec<(adventuresim_world_schema::WrittenLanguage, f32)>) {
523:     let mut excess = 0.0;
524:     let mut written = Vec::new();
525:     let mut award_direct = |skill: Skill, stored: &mut f32, real_hours: f32| {
526:         excess +=
527:             apply_direct_training(skill, stored, real_hours, attributes).excess_effective_hours;
528:     };
529:     for entry in entries {
530:         let award = work_hours * entry.weight;
531:         match &entry.target {
532:             TrainingTarget::FixedSkill { skill } => {
533:                 if let Some((kind, stored)) = fixed_skill_target(hours, skill) {
534:                     award_direct(kind, stored, award);
535:                 }
536:             }
537:             TrainingTarget::Religion { religion } => {
538:                 if let Some(religion) = OfficialReligion::from_id(religion) {
539:                     award_direct(Skill::Religion, hours.religion.direct_mut(religion), award);
540:                 }
541:             }
542:             TrainingTarget::Bestiary { category } => {
543:                 if let Some(category) =
544:                     adventuresim_world_schema::BestiaryCategory::from_id(category)
545:                 {
546:                     award_direct(Skill::Bestiary, hours.bestiary.direct_mut(category), award);
547:                 }
548:             }
549:             TrainingTarget::Terrain { terrain } => {
550:                 if let Some((kind, stored)) = terrain_target(hours, terrain) {
551:                     award_direct(kind, stored, award);
552:                 }
553:             }
554:             TrainingTarget::EquippedWeaponSkills => {
555:                 let weights = activities.combat.weapons.weights();
556:                 let total = weights.into_iter().sum::<f32>();
557:                 if total > 0.0 {
558:                     for ((skill, target), weight) in [
559:                         (Skill::Polearm, &mut hours.polearm),
560:                         (Skill::Axe, &mut hours.axe),
561:                         (Skill::Bludgeon, &mut hours.bludgeon),
562:                         (Skill::Sword, &mut hours.sword),
563:                         (Skill::Knife, &mut hours.knife),
564:                         (Skill::Bow, &mut hours.bow),
565:                         (Skill::Crossbow, &mut hours.crossbow),
566:                         (Skill::Firearm, &mut hours.firearm),
567:                         (Skill::Throw, &mut hours.throw),
568:                     ]
569:                     .into_iter()
570:                     .zip(weights)
571:                     {
572:                         award_direct(skill, target, award * weight / total);
573:                     }
574:                 }
575:             }
576:             TrainingTarget::Written { language } => written.push((*language, award)),
577:         }
578:     }
579:     (excess, written)
580: }
