582: fn fixed_skill_target<'a>(hours: &'a mut SkillHours, skill: &str) -> Option<(Skill, &'a mut f32)> {
583:     Some(match skill {
584:         "will" => (Skill::Will, &mut hours.will),
585:         "insight" => (Skill::Insight, &mut hours.insight),
586:         "charm" => (Skill::Charm, &mut hours.charm),
