590:         "cooking" => (Skill::Cooking, &mut hours.cooking),
591:         "herbalism" => (Skill::Herbalism, &mut hours.herbalism),
592:         "surgery" => (Skill::Surgery, &mut hours.surgery),
593:         "polearm" => (Skill::Polearm, &mut hours.polearm),
594:         "axe" => (Skill::Axe, &mut hours.axe),
595:         "bludgeon" => (Skill::Bludgeon, &mut hours.bludgeon),
596:         "sword" => (Skill::Sword, &mut hours.sword),
597:         "knife" => (Skill::Knife, &mut hours.knife),
598:         "bow" => (Skill::Bow, &mut hours.bow),
599:         "crossbow" => (Skill::Crossbow, &mut hours.crossbow),
600:         "firearm" => (Skill::Firearm, &mut hours.firearm),
601:         "throw" => (Skill::Throw, &mut hours.throw),
602:         "block" => (Skill::Block, &mut hours.block),
603:         "dodge" => (Skill::Dodge, &mut hours.dodge),
604:         "stealth" => (Skill::Stealth, &mut hours.stealth),
605:         "balance" => (Skill::Balance, &mut hours.balance),
606:         "terrain_plains" => (Skill::TerrainPlains, &mut hours.terrain_plains),
607:         "terrain_forest" => (Skill::TerrainForest, &mut hours.terrain_forest),
608:         "terrain_hills" => (Skill::TerrainHills, &mut hours.terrain_hills),
609:         "terrain_wetlands" => (Skill::TerrainWetlands, &mut hours.terrain_wetlands),
610:         "terrain_urban" => (Skill::TerrainUrban, &mut hours.terrain_urban),
611:         "terrain_snow" => (Skill::TerrainSnow, &mut hours.terrain_snow),
612:         "tailoring" => (Skill::Tailoring, &mut hours.tailoring),
