328: impl CombatTrainingProfile {
329:     pub fn from_equipped_hands(hands: impl IntoIterator<Item = EquippedCombatItem>) -> Self {
330:         let mut result = Self::default();
331:         let mut best_melee_balance: Option<f32> = None;
332:         for item in hands {
333:             for (target, weight) in [
334:                 &mut result.weapons.polearm,
335:                 &mut result.weapons.axe,
336:                 &mut result.weapons.bludgeon,
337:                 &mut result.weapons.sword,
338:                 &mut result.weapons.knife,
