341:                 &mut result.weapons.firearm,
342:                 &mut result.weapons.throw,
343:             ]
344:             .into_iter()
345:             .zip(item.weapons.weights())
346:             {
347:                 *target = target.max(weight);
348:             }
349:             if item.shield {
350:                 result.block = 1.0;
351:             }
352:             if item.weapons.melee_total() > 0.0 && item.weapons.ranged_total() == 0.0 {
353:                 let balance = if item.balance.is_finite() {
354:                     item.balance.clamp(0.0, 1.0)
355:                 } else {
356:                     1.0
357:                 };
358:                 best_melee_balance =
359:                     Some(best_melee_balance.map_or(balance, |old| old.min(balance)));
360:             }
361:         }
362:         if result.block < 1.0 {
363:             result.block = best_melee_balance.map_or(0.0, |balance| 1.0 - balance);
364:         }
365:         result
366:     }
