240: fn run_curriculum_activity<A: PlayerAttributes>(
241:     output: &mut LifeSimulationOutput,
242:     phase: LifePhaseKind,
243:     activity: HistoricalActivity,
244:     entries: &[TrainingEntry],
245:     work_hours: f32,
246:     input: &LifeSimulationInput<'_, A>,
247: ) -> bool {
248:     if !activity.eligible(phase) || work_hours <= 0.0 {
249:         return false;
250:     }
251:     let normalized = normalized_curriculum(entries);
252:     let (_, written) = apply_curriculum_training(
253:         &mut output.skills,
254:         work_hours,
255:         &normalized,
256:         input.activity_profile,
257:         input.attributes,
258:     );
259:     apply_written(output, written, input.attributes);
260:     true
261: }
262: 
263: fn apply_written(
264:     output: &mut LifeSimulationOutput,
265:     awards: Vec<(adventuresim_world_schema::WrittenLanguage, f32)>,
266:     attributes: &impl PlayerAttributes,
267: ) {
268:     let aptitude = Skill::Religion.governing_aptitude(attributes);
269:     for (language, hours) in awards {
270:         apply_language_training(output.written.direct_mut(language), hours, aptitude);
271:     }
272: }
