302: fn professional_curriculum(
303:     organization: &OrganizationDefinition,
304:     requirements: &[Requirement],
305: ) -> Vec<TrainingEntry> {
306:     let mut entries = organization.activity.training.clone();
307:     for credential in credential_curriculum(requirements) {
308:         if let Some(existing) = entries
309:             .iter_mut()
310:             .find(|entry| entry.target == credential.target)
311:         {
312:             existing.weight = existing.weight.max(credential.weight);
313:         } else {
314:             entries.push(credential);
315:         }
316:     }
317:     entries
318: }
319: 
320: fn normalized_curriculum(entries: &[TrainingEntry]) -> Vec<TrainingEntry> {
321:     let total = entries
322:         .iter()
323:         .map(|entry| entry.weight.max(0.0))
324:         .sum::<f32>();
325:     if total <= 0.0 {
326:         return Vec::new();
327:     }
328:     entries
329:         .iter()
330:         .map(|entry| TrainingEntry {
331:             weight: entry.weight.max(0.0) / total,
332:             target: entry.target.clone(),
333:         })
334:         .collect()
335: }
