258: pub fn record_event(
259:     ctx: &ReducerContext,
260:     event_id: String,
261:     character_id: u64,
262:     origin_settlement_id: &str,
263:     source_kind: &str,
264:     source_id: &str,
265:     raw_fame: i32,
266:     raw_infamy: i32,
267:     occurred_at_minute: StrategicMinute,
268: ) -> Result<bool, String> {
269:     if raw_fame < 0 || raw_infamy < 0 {
270:         return Err("Reputation event deltas must be nonnegative".into());
271:     }
272:     if ctx.db.reputation_event().id().find(&event_id).is_some() {
273:         return Ok(false);
274:     }
275:     if ctx
276:         .db
277:         .settlement()
278:         .id()
279:         .find(origin_settlement_id.to_owned())
280:         .is_none()
281:     {
282:         return Err("Reputation origin settlement not found".into());
283:     }
284:     let settlements = ctx
285:         .db
286:         .settlement()
287:         .iter()
288:         .map(|value| ReputationSettlement {
289:             id: value.id,
290:             node_id: value.source_node_id,
291:             population_level: value.population_level,
292:             population_estimate: value.population_estimate,
293:         })
294:         .collect::<Vec<_>>();
295:     let edges = ctx
296:         .db
297:         .travel_edge()
298:         .iter()
299:         .map(|value| ReputationEdge {
300:             from: value.from_node_id,
301:             to: value.to_node_id,
302:             length_m: value.length_m,
303:         })
304:         .collect::<Vec<_>>();
305:     let projected = contributions(
306:         origin_settlement_id,
307:         raw_fame,
308:         raw_infamy,
309:         &settlements,
310:         &edges,
311:     );
312:     ctx.db.reputation_event().insert(ReputationEvent {
313:         id: event_id.clone(),
314:         character_id,
315:         origin_settlement_id: origin_settlement_id.to_owned(),
316:         source_kind: source_kind.to_owned(),
317:         source_id: source_id.to_owned(),
318:         raw_fame,
319:         raw_infamy,
320:         occurred_at_minute,
321:     });
322:     for contribution in projected {
323:         let aggregate_id = aggregate_id(character_id, &contribution.settlement_id);
324:         let existing = ctx
325:             .db
326:             .character_settlement_reputation()
327:             .id()
328:             .find(&aggregate_id);
329:         let mut aggregate = existing.clone().unwrap_or(CharacterSettlementReputation {
330:             id: aggregate_id,
331:             character_id,
332:             settlement_id: contribution.settlement_id.clone(),
333:             fame: 0,
334:             infamy: 0,
335:         });
336:         aggregate.fame = apply_delta(aggregate.fame, contribution.fame);
337:         aggregate.infamy = apply_delta(aggregate.infamy, contribution.infamy);
338:         if existing.is_some() {
339:             ctx.db
340:                 .character_settlement_reputation()
341:                 .id()
342:                 .update(aggregate);
343:         } else {
344:             ctx.db.character_settlement_reputation().insert(aggregate);
345:         }
346:     }
347:     Ok(true)
348: }

