387: pub fn validate_definitions(definitions: &[EncounterDefinition]) -> Result<(), String> {
388:     let mut ids = BTreeSet::new();
389:     for definition in definitions {
390:         validate_id(&definition.id, "encounter.id")?;
391:         if !ids.insert(definition.id.as_str()) {
392:             return Err(format!("duplicate encounter ID {}", definition.id));
393:         }
394:         if definition.version == 0 {
395:             return Err(format!("{}: version must be positive", definition.id));
396:         }
397:         if definition.weight == 0 || definition.weight > MAX_WEIGHT {
398:             return Err(format!(
399:                 "{}: weight outside 1..={MAX_WEIGHT}",
400:                 definition.id
401:             ));
402:         }
403:         if !definition.triggers.travel && !definition.triggers.rest {
404:             return Err(format!("{}: no eligible trigger", definition.id));
405:         }
406:         if definition.cast.is_empty()
407:             && (!definition.opening.is_empty()
408:                 || definition
409:                     .choices
410:                     .iter()
411:                     .any(|choice| !choice.response.is_empty()))
412:         {
413:             return Err(format!("{}: cast is empty", definition.id));
414:         }
415:         let mut speakers = BTreeSet::new();
416:         for speaker in &definition.cast {
417:             validate_id(&speaker.id, "speaker.id")?;
418:             if speaker.name.trim().is_empty() || !speakers.insert(speaker.id.as_str()) {
419:                 return Err(format!("{}: empty or duplicate speaker", definition.id));
420:             }
421:             match &speaker.backing {
422:                 SpeakerBacking::Character { .. } if speaker.nature != SpeakerNature::Mortal => {
423:                     return Err(format!(
424:                         "{}:{}: supernatural cast cannot silently materialize as a Character",
425:                         definition.id, speaker.id
