139: fn compile_road_encounters(root: &Path) {
140:     let content = root.join("content/encounters");
141:     println!("cargo:rerun-if-changed={}", content.display());
142:     let mut files: Vec<_> = fs::read_dir(&content)
143:         .expect("content/encounters must exist")
144:         .map(|entry| entry.unwrap().path())
145:         .filter(|path| {
146:             path.extension()
147:                 .is_some_and(|extension| extension == "yaml")
148:         })
149:         .collect();
150:     files.sort();
151:     let mut definitions = Vec::new();
152:     let mut sources = Vec::new();
153:     let mut digest = Sha256::new();
154:     for file in files {
155:         let relative = file
156:             .strip_prefix(root)
157:             .unwrap()
158:             .to_string_lossy()
159:             .replace('\\', "/");
160:         let text = fs::read_to_string(&file).unwrap();
161:         digest.update(relative.as_bytes());
162:         digest.update([0]);
163:         digest.update(text.as_bytes());
164:         let document: road_encounter_catalog::CatalogDocument =
165:             serde_json::from_str(&text).unwrap_or_else(|error| panic!("{relative}: {error}"));
166:         for definition in document.encounters {
167:             let encoded_id = serde_json::to_string(&definition.id).unwrap();
168:             let offset = text
169:                 .find(&encoded_id)
170:                 .unwrap_or_else(|| panic!("{relative}: cannot locate encounter ID"));
171:             sources.push(road_encounter_catalog::EncounterSource {
172:                 id: definition.id.clone(),
173:                 file: relative.clone(),
174:                 line: (text[..offset].bytes().filter(|byte| *byte == b'\n').count() + 1) as u32,
175:             });
176:             definitions.push(definition);
177:         }
178:     }
179:     assert!(
180:         !definitions.is_empty(),
181:         "content/encounters contains no encounters"
182:     );
183:     road_encounter_catalog::validate_definitions(&definitions)
184:         .unwrap_or_else(|error| panic!("road encounter catalog: {error}"));
185:     let item_content = root.join("content/items");
186:     let mut item_ids = std::collections::BTreeSet::new();
187:     for file in fs::read_dir(item_content)
188:         .unwrap()
189:         .map(|entry| entry.unwrap().path())
190:         .filter(|path| {
191:             path.extension()
192:                 .is_some_and(|extension| extension == "yaml")
193:         })
194:     {
195:         let value: serde_json::Value =
196:             serde_json::from_str(&fs::read_to_string(file).unwrap()).unwrap();
197:         if let Some(items) = value.get("items").and_then(serde_json::Value::as_array) {
198:             item_ids.extend(
199:                 items
200:                     .iter()
201:                     .filter_map(|item| item.get("id").and_then(serde_json::Value::as_str))
202:                     .map(str::to_owned),
203:             );
204:         }
205:     }
206:     road_encounter_catalog::validate_item_references(&definitions, |id| item_ids.contains(id))
207:         .unwrap_or_else(|error| panic!("road encounter catalog: {error}"));
208:     let json = serde_json::to_string(&definitions).unwrap();
209:     let sources = serde_json::to_string(&sources).unwrap();
210:     let digest = format!("{:x}", digest.finalize());
211:     fs::write(
212:         Path::new(&env::var("OUT_DIR").unwrap()).join("road_encounter_catalog.rs"),
213:         format!(
214:             "pub const ROAD_ENCOUNTER_CATALOG_JSON: &str = {json:?};\n\
215:              pub const ROAD_ENCOUNTER_SOURCE_MAP_JSON: &str = {sources:?};\n\
216:              pub const ROAD_ENCOUNTER_CATALOG_DIGEST: &str = {digest:?};\n"
217:         ),
218:     )
219:     .unwrap();
220: }
