443:     ctx: &ReducerContext,
444:     character_id: u64,
445:     elapsed: u64,
446:     recovery: InjuryRecoveryMinutes,
447: ) -> Result<InjurySettlement, String> {
448:     if elapsed == 0 {
449:         return Ok(InjurySettlement {
450:             elapsed: 0,
451:             alive: true,
452:         });
453:     }
