461:             if row.maximum_blood_ml > 0.0 {
462:                 row.current_blood_ml / row.maximum_blood_ml
463:             } else {
464:                 1.0
465:             }
466:         });
467:     let mut injuries = BodyRegion::ALL.map(|limb| injury_for(ctx, character_id, limb));
468:     let open_cuts = injuries
469:         .iter()
470:         .map(|injury| {
471:             if injury.bandaged {
