59: impl<M: ChunkInstancedMaterial> Hash for ChunkPipelineKey<M> {
60:     fn hash<H: Hasher>(&self, state: &mut H) {
61:         self.mesh_key.hash(state);
62:         self.material_key.hash(state);
63:     }
64: }
65: 
66: impl<M: ChunkInstancedMaterial> SpecializedMeshPipeline for ChunkMaterialPipeline<M> {
67:     type Key = ChunkPipelineKey<M>;
68: 
69:     fn specialize(
70:         &self,
71:         key: Self::Key,
72:         layout: &MeshVertexBufferLayoutRef,
73:     ) -> Result<RenderPipelineDescriptor, SpecializedMeshPipelineError> {
74:         let mut descriptor = self.mesh_pipeline.specialize(key.mesh_key, layout)?;
75:         // Groups 0 and 1 stay Bevy's view layouts; the per-entity mesh
76:         // uniforms at group 2 give way to the chunk band.
77:         descriptor.layout.truncate(2);
78:         descriptor
79:             .layout
80:             .extend([self.band_layout.clone(), self.material_layout.clone()]);
81:         descriptor
82:             .vertex
83:             .shader_defs
84:             .push("VISIBILITY_RANGE_DITHER".into());
85:         descriptor.vertex.shader = self.shader.clone();
86:         if let Some(fragment) = descriptor.fragment.as_mut() {
87:             if let Some(Some(target)) = fragment.targets.first_mut() {
88:                 target.blend = None;
89:             }
90:             fragment.shader_defs.push("VISIBILITY_RANGE_DITHER".into());
91:             fragment.shader = self.shader.clone();
92:         }
93:         M::specialize(&mut descriptor, layout, key.material_key)?;
94:         descriptor.vertex.buffers.push(instance_buffer_layout());
95:         Ok(descriptor)
96:     }
97: }
