99: impl<M: ChunkInstancedMaterial> FromWorld for ChunkMaterialPipeline<M> {
100:     fn from_world(world: &mut World) -> Self {
101:         let render_device = world.resource::<RenderDevice>();
102:         let material_layout = BindGroupLayoutDescriptor::new(
103:             format!(
104:                 "chunk_instanced_material_layout_{}",
105:                 std::any::type_name::<M>()
106:             ),
107:             &M::bind_group_layout_entries(render_device, false),
108:         );
109:         Self {
110:             mesh_pipeline: world.resource::<MeshPipeline>().clone(),
111:             band_layout: world.resource::<ChunkBandLayout>().0.clone(),
112:             material_layout,
113:             shader: material_shader::<M>(world),
114:             material: PhantomData,
115:         }
116:     }
117: }
118: 
119: fn material_shader<M: ChunkInstancedMaterial>(world: &World) -> Handle<Shader> {
120:     match M::shader() {
121:         bevy::shader::ShaderRef::Handle(handle) => handle,
122:         bevy::shader::ShaderRef::Path(path) => world.resource::<AssetServer>().load(path),
123:         bevy::shader::ShaderRef::Default => Handle::default(),
124:     }
125: }
126: 
127: /// The `@location(8..10)` instance stream of `chunk_instancing.wgsl`.
128: fn instance_buffer_layout() -> VertexBufferLayout {
129:     let rotation_offset = VertexFormat::Float32x4.size();
130:     let seed_offset = rotation_offset + VertexFormat::Float32.size();
131:     VertexBufferLayout {
132:         array_stride: size_of::<ChunkInstance>() as u64,
133:         step_mode: VertexStepMode::Instance,
134:         attributes: vec![
135:             VertexAttribute {
136:                 format: VertexFormat::Float32x4,
137:                 offset: 0,
138:                 shader_location: 8,
139:             },
140:             VertexAttribute {
141:                 format: VertexFormat::Float32,
142:                 offset: rotation_offset,
143:                 shader_location: 9,
144:             },
145:             VertexAttribute {
146:                 format: VertexFormat::Uint32,
147:                 offset: seed_offset,
148:                 shader_location: 10,
149:             },
150:         ],
151:     }
152: }

