196: /// Bins chunks that share a material together.
197: fn material_bind_group_index<M: ChunkInstancedMaterial>(material: &Handle<M>) -> u32 {
198:     let mut hasher = DefaultHasher::new();
199:     material.id().hash(&mut hasher);
200:     hasher.finish() as u32
201: }
