1: //! Splits a batch's instances into ground chunks and spawns one culled entity
2: //! per chunk.
3: use std::{collections::BTreeMap, sync::Arc};
4: 
5: use bevy::{
6:     camera::{
7:         primitives::Aabb,
8:         visibility::{NoAutoAabb, VisibilityRange},
9:     },
10:     light::NotShadowCaster,
11:     prelude::*,
12: };
13: 
14: use super::{ChunkInstance, ChunkInstancedMaterial, ChunkMaterial, FadeBand, InstanceChunk};
15: 
16: /// Every instance of one mesh and material within one distance band.
17: pub(in crate::presentation) struct InstanceBatch<M: ChunkInstancedMaterial> {
18:     pub mesh: Handle<Mesh>,
19:     pub material: Handle<M>,
20:     pub instances: Vec<ChunkInstance>,
21:     pub band: FadeBand,
22:     pub reach: InstanceReach,
23:     pub chunk_size: ChunkSize,
24: }
25: 
26: /// How far a unit-scale instance's geometry extends from its root, in
27: /// metres. Bounds scale with the largest instance in each chunk.
28: #[derive(Clone, Copy, Debug)]
29: pub(in crate::presentation) struct InstanceReach {
30:     pub horizontal: f32,
31:     pub above: f32,
32:     pub below: f32,
33: }
34: 
35: /// The edge of the square ground cell one chunk entity covers, in metres.
36: /// Larger cells mean fewer entities to cull; smaller cells cull tighter.
37: #[derive(Clone, Copy, Debug)]
38: pub(in crate::presentation) struct ChunkSize(pub f32);
39: 
40: /// The instances of one ground cell.
41: struct Cell {
42:     instances: Vec<ChunkInstance>,
43: }
44: 
45: impl<M: ChunkInstancedMaterial> InstanceBatch<M> {
46:     /// Spawns one entity per occupied ground cell. `components` adds the
47:     /// caller's markers to each chunk, given that chunk's instances.
48:     pub(in crate::presentation) fn spawn<B: Bundle>(
49:         self,
50:         commands: &mut Commands,
51:         mut components: impl FnMut(&[ChunkInstance]) -> B,
52:     ) {
53:         let Self {
54:             mesh,
55:             material,
56:             instances,
57:             band,
58:             reach,
59:             chunk_size,
60:         } = self;
61:         let mut cells = BTreeMap::<(i32, i32), Cell>::new();
62:         for instance in instances {
63:             let key = (
64:                 (instance.position.x / chunk_size.0).floor() as i32,
65:                 (instance.position.z / chunk_size.0).floor() as i32,
66:             );
67:             cells
68:                 .entry(key)
69:                 .or_insert_with(|| Cell {
70:                     instances: Vec::new(),
71:                 })
72:                 .instances
73:                 .push(instance);
74:         }
75:         for cell in cells.into_values() {
76:             let bounds = cell.bounds(reach);
77:             let centre = Vec3::from(bounds.center);
78:             // Bevy measures the range from the entity's translation, so pad
79:             // the band by the chunk's half-diagonal: no instance inside the
80:             // band is culled with its chunk. Each instance dithers its own fade.
81:             let pad = Vec3::from(bounds.half_extents).length();
82:             let start = (band.fade_in().start - pad).max(0.0);
83:             let end = band.fade_out().end + pad;
84:             let extra = components(&cell.instances);
85:             commands.spawn((
86:                 Mesh3d(mesh.clone()),
87:                 ChunkMaterial(material.clone()),
88:                 InstanceChunk {
89:                     instances: Arc::from(cell.instances),
90:                     band: band.clone(),
91:                 },
92:                 Transform::from_translation(centre),
93:                 Visibility::Inherited,
94:                 Aabb {
95:                     center: Vec3::ZERO.into(),
96:                     half_extents: bounds.half_extents,
97:                 },
98:                 // Bevy otherwise replaces the chunk bounds with the mesh's.
99:                 NoAutoAabb,
100:                 VisibilityRange {
101:                     start_margin: start..start,
102:                     end_margin: end..end,
103:                     use_aabb: false,
104:                 },
105:                 NotShadowCaster,
106:                 extra,
107:             ));
108:         }
109:     }
110: }
111: 
112: impl Cell {
113:     fn bounds(&self, reach: InstanceReach) -> Aabb {
114:         let mut minimum = Vec3::splat(f32::INFINITY);
115:         let mut maximum = Vec3::splat(f32::NEG_INFINITY);
116:         let mut largest_scale = 1.0_f32;
117:         for instance in &self.instances {
118:             minimum = minimum.min(instance.position);
119:             maximum = maximum.max(instance.position);
120:             largest_scale = largest_scale.max(instance.scale);
121:         }
122:         let horizontal = reach.horizontal * largest_scale;
123:         let minimum = minimum - Vec3::new(horizontal, reach.below * largest_scale, horizontal);
124:         let maximum = maximum + Vec3::new(horizontal, reach.above * largest_scale, horizontal);
125:         Aabb::from_min_max(minimum, maximum)
126:     }
127: }

crates/adventuresim-tactical-client/src/presentation/ground_scatter/instanced_grass/batches.rs
1: //! Construct chunk-instanced batches from the procedural tuft lattice.
2: use super::*;
3: use fabelgeist_determinism::Seed;
4: 
5: use crate::presentation::chunk_instancing::{ChunkSize, InstanceBatch};
6: 
7: /// Ground cells of the dense near tiers, which fade out within ~20 m.
8: const NEAR_CHUNK_SIZE: ChunkSize = ChunkSize(16.0);
9: /// Ground cells of the sparse far tiers, which reach ~70 m.
10: const FAR_CHUNK_SIZE: ChunkSize = ChunkSize(32.0);
11: 
12: /// Turns filled instance batches into chunk entities per (tier, species),
13: /// each carrying `marker` on top of the chunk-instanced draw components.
14: pub(in crate::presentation) fn spawn_tuft_batches(
15:     world: GrassWorld<'_, '_, '_>,
16:     batches: &mut TierSpeciesBatches,
17:     label: &str,
18:     marker: impl Bundle + Clone,
19:     base_seed: Seed,
20:     pigment: TuftPigment,
21:     grass: &crate::presentation::config::GrassConfig,
22: ) {
23:     let GrassWorld {
24:         commands,
25:         meshes,
26:         materials,
27:     } = world;
28:     for lod in TIERS {
29:         let material = materials.add(diagnostics::material(
30:             lod,
31:             grass,
32:             pigment.density,
33:             pigment.dryness,
34:             pigment.wind_scale,
35:         ));
36:         for species in GrassSpecies::ALL {
37:             let instances = std::mem::take(&mut batches[lod.tier_index()][species.index()]);
38:             if instances.is_empty() {
39:                 continue;
40:             }
41:             let (mesh, triangle_count) = diagnostics::add_mesh(
42:                 meshes,
43:                 grass_tuft_mesh(
44:                     pigment.color,
45:                     lod,
46:                     pigment.density,
47:                     species,
48:                     streams::TUFT_MESH.seed(
49:                         base_seed,
50:                         &[species.index() as u64, lod.tier_index() as u64],
51:                     ),
52:                     grass,
53:                 ),
54:             );
55:             InstanceBatch {
56:                 mesh,
57:                 material: material.clone(),
58:                 instances,
59:                 band: configured_tier_band(lod, grass),
60:                 reach: ground_scatter_reach(configured_tuft_footprint_metres(lod, grass)),
61:                 chunk_size: match lod {
62:                     GrassMeshLod::Near | GrassMeshLod::NearEdge => NEAR_CHUNK_SIZE,
63:                     GrassMeshLod::Far | GrassMeshLod::Vista => FAR_CHUNK_SIZE,
64:                 },
65:             }
66:             .spawn(commands, |chunk| {
67:                 (
68:                     Name::new(format!(
69:                         "{label} {species:?} {lod:?} tufts ({})",
70:                         chunk.len()
71:                     )),
72:                     GroundScatterLayer::Grass,
73:                     triangle_count,
74:                     marker.clone(),
75:                 )
76:             });
77:         }
78:     }
79: }
crates/adventuresim-tactical-client/src/presentation/ground_scatter/loose_stone/batches.rs
1: //! Chunk-instanced batches for loose-stone pebble patches.
2: //!
3: //! The per-entity renderer spawned two or three entities for every qualifying
4: //! ground sample - one per square metre over the whole playable scene. These
5: //! batches carry the same placements as `ChunkInstance`s instead, so the ECS
6: //! holds one entity per (patch mesh, LOD, ground cell) rather than tens of
7: //! thousands.
8: 
9: use bevy::prelude::{Commands, Handle, Mesh, Name};
10: 
11: use super::{
12:     LooseStonePebblePatch, MESH_VARIANTS, PEBBLE_BATCH_FOOTPRINT_METRES, PebbleMeshLod,
13:     TacticalPebbleBillboardMaterial, TacticalPebbleMaterial, pebble_lod_visibility,
14: };
15: use crate::presentation::{
16:     chunk_instancing::{ChunkInstance, ChunkInstancedMaterial, ChunkSize, FadeBand, InstanceBatch},
17:     ground_scatter::{GroundScatterLayer, instanced_grass::ground_scatter_reach},
18: };
19: 
20: /// Pebbles reach at most ~180 m as billboards; the dense hero and near bands
21: /// end within 24 m, so mid-sized cells keep their culling tight.
22: const PEBBLE_CHUNK_SIZE: ChunkSize = ChunkSize(24.0);
23: 
24: /// The shared meshes and materials every pebble batch draws from.
25: pub(super) struct PebbleBatchAssets<'a> {
26:     pub(super) hero: &'a [Handle<Mesh>],
27:     pub(super) near: &'a [Handle<Mesh>],
28:     pub(super) billboard: &'a [Handle<Mesh>],
29:     pub(super) pebble_counts: &'a [usize],
30:     pub(super) stone: Handle<TacticalPebbleMaterial>,
31:     pub(super) woodland_stone: Handle<TacticalPebbleMaterial>,
32:     pub(super) billboard_material: Handle<TacticalPebbleBillboardMaterial>,
33: }
34: 
35: /// One LOD of one patch variant.
36: struct PebbleBatch<M: ChunkInstancedMaterial> {
37:     name: &'static str,
38:     mesh: Handle<Mesh>,
39:     material: Handle<M>,
40:     lod: PebbleMeshLod,
41:     /// Pebbles per placed patch, or zero for LODs that must not be counted.
42:     pebbles_per_patch: usize,
43: }
44: 
45: pub(super) fn spawn(
46:     commands: &mut Commands<'_, '_>,
47:     assets: PebbleBatchAssets<'_>,
48:     per_variant: Vec<Vec<ChunkInstance>>,
49: ) {
50:     for (variant, instances) in per_variant.into_iter().enumerate() {
51:         if instances.is_empty() {
52:             continue;
53:         }
54:         let woodland = variant < MESH_VARIANTS as usize;
55:         let stone = if woodland {
56:             assets.woodland_stone.clone()
57:         } else {
58:             assets.stone.clone()
59:         };
60:         // Only the hero batch reports a pebble count: the three LODs draw the
61:         // same placements, so summing all of them would treble the scene total
62:         // the review viewer reads back.
63:         PebbleBatch {
64:             name: if woodland {
65:                 "Instanced woodland hero pebble patches"
66:             } else {
67:                 "Instanced loose-stone hero pebble patches"
68:             },
69:             mesh: assets.hero[variant].clone(),
70:             material: stone.clone(),
71:             lod: PebbleMeshLod::Hero,
72:             pebbles_per_patch: assets.pebble_counts[variant],
73:         }
74:         .spawn(commands, &instances);
75:         PebbleBatch {
76:             name: if woodland {
77:                 "Instanced woodland near pebble patches"
78:             } else {
79:                 "Instanced loose-stone near pebble patches"
80:             },
81:             mesh: assets.near[variant].clone(),
82:             material: stone,
83:             lod: PebbleMeshLod::Near,
84:             pebbles_per_patch: 0,
85:         }
86:         .spawn(commands, &instances);
87:         if !woodland {
88:             PebbleBatch {
89:                 name: "Instanced loose-stone billboard pebble patches",
90:                 mesh: assets.billboard[variant].clone(),
91:                 material: assets.billboard_material.clone(),
92:                 lod: PebbleMeshLod::Billboard,
93:                 pebbles_per_patch: 0,
94:             }
95:             .spawn(commands, &instances);
96:         }
97:     }
98: }
99: 
100: impl<M: ChunkInstancedMaterial> PebbleBatch<M> {
101:     fn spawn(self, commands: &mut Commands<'_, '_>, instances: &[ChunkInstance]) {
102:         let range = pebble_lod_visibility(self.lod);
103:         let Self {
104:             name,
105:             pebbles_per_patch,
106:             ..
107:         } = self;
108:         InstanceBatch {
109:             mesh: self.mesh,
110:             material: self.material,
111:             instances: instances.to_vec(),
112:             band: FadeBand::new(range.start_margin, range.end_margin),
113:             reach: ground_scatter_reach(PEBBLE_BATCH_FOOTPRINT_METRES),
114:             chunk_size: PEBBLE_CHUNK_SIZE,
115:         }
116:         .spawn(commands, |chunk| {
117:             (
118:                 Name::new(format!("{name} ({})", chunk.len())),
119:                 GroundScatterLayer::LooseStone,
120:                 LooseStonePebblePatch {
121:                     physical_pebbles: pebbles_per_patch * chunk.len(),
122:                 },
123:             )
124:         });
125:     }
126: }
crates/adventuresim-tactical-client/src/presentation/vista/tree_cards.rs
1: //! Chunk-instanced vista tree cards.
2: //!
3: //! A dense woodland vista resolves to tens of thousands of whole-tree
4: //! billboards - measured at 29,247 for `dense-woodland`, nearly all of them in
5: //! the 250 m LOD ring. As one entity each they dominated
6: //! `check_visibility_cpu_culling`, which sweeps every renderable entity once
7: //! per frame and runs serially on wasm. Chunked, the same stands cost one
8: //! entity per distinct card variant per wide ground cell.
9: //!
10: //! Every per-card difference fits `ChunkInstance`: position and uniform scale,
11: //! with no rotation at all (the shader yaws each card to the camera). The one
12: //! value that did not fit is the near cutoff, which scales with the card's own
13: //! height; `tactical_vista_tree_instanced.wgsl` evaluates it per instance.
14: 
15: use bevy::{
16:     ecs::system::SystemParam,
17:     prelude::{Asset, Assets, Commands, Handle, Image, Mesh, Name, ResMut, TypePath, Vec4},
18:     render::render_resource::{
19:         AsBindGroup, RenderPipelineDescriptor, SpecializedMeshPipelineError,
20:     },
21:     shader::ShaderRef,
22: };
23: 
24: use crate::presentation::chunk_instancing::{
25:     ChunkInstance, ChunkInstancedMaterial, ChunkSize, FadeBand, InstanceBatch, InstanceReach,
26:     enable_alpha_to_coverage,
27: };
28: 
29: use super::{VistaLod, VistaTerrain};
30: use crate::presentation::obstacles::tree::TacticalTreeImpostorMaterial;
31: 
32: const VISTA_TREE_SHADER: &str = "shaders/tactical_vista_tree_instanced.wgsl";
33: /// Vista rings span kilometres of sparse stands; wide cells keep the entity
34: /// count low enough for serial CPU culling on wasm.
35: const VISTA_CARD_CHUNK_SIZE: ChunkSize = ChunkSize(256.0);
36: 
37: /// Instanced twin of `TacticalTreeImpostorMaterial`, restricted to the
38: /// whole-tree camera-facing representation every vista stand uses.
39: #[derive(Asset, TypePath, AsBindGroup, Debug, Clone)]
40: pub(in crate::presentation) struct TacticalVistaTreeInstancedMaterial {
41:     #[texture(0)]
42:     #[sampler(1)]
43:     pub(in crate::presentation) baked_color: Handle<Image>,
44:     /// Unscaled card height, deterministic seed, wind strength, wind speed.
45:     /// The per-entity material carried the representation level in x; every
46:     /// vista card is level 4, so x now carries the height the near cutoff
47:     /// needs.
48:     #[uniform(2)]
49:     pub(in crate::presentation) parameters: Vec4,
50:     #[uniform(2)]
51:     pub(in crate::presentation) lighting: Vec4,
52:     #[uniform(2)]
53:     pub(in crate::presentation) ambient: Vec4,
54: }
55: 
56: impl ChunkInstancedMaterial for TacticalVistaTreeInstancedMaterial {
57:     fn shader() -> ShaderRef {
58:         VISTA_TREE_SHADER.into()
59:     }
60: 
61:     fn specialize(
62:         descriptor: &mut RenderPipelineDescriptor,
63:         _layout: &bevy::mesh::MeshVertexBufferLayoutRef,
64:         _key: Self::Data,
65:     ) -> Result<(), SpecializedMeshPipelineError> {
66:         // Cards are two-sided and cut out of the atlas through coverage.
67:         descriptor.primitive.cull_mode = None;
68:         enable_alpha_to_coverage(descriptor);
69:         Ok(())
70:     }
71: }
72: 
73: /// The two material stores a vista card batch draws from, as one parameter so
74: /// the caller's signature does not grow with the instanced twin.
75: #[derive(SystemParam)]
76: pub(in crate::presentation) struct VistaTreeMaterials<'w> {
77:     pub(in crate::presentation) impostor: ResMut<'w, Assets<TacticalTreeImpostorMaterial>>,
78:     pub(in crate::presentation) cards: ResMut<'w, Assets<TacticalVistaTreeInstancedMaterial>>,
79: }
80: 
81: /// Collects instances per distinct card variant while the lattice is walked.
82: #[derive(Default)]
83: pub(super) struct VistaCardBatches {
84:     groups: Vec<VistaCardGroup>,
85: }
86: 
87: struct VistaCardGroup {
88:     mesh: Handle<Mesh>,
89:     source: Handle<TacticalTreeImpostorMaterial>,
90:     card_height: f32,
91:     instances: Vec<ChunkInstance>,
92: }
93: 
94: impl VistaCardBatches {
95:     pub(super) fn push(
96:         &mut self,
97:         mesh: &Handle<Mesh>,
98:         source: &Handle<TacticalTreeImpostorMaterial>,
99:         card_height: f32,
100:         instance: ChunkInstance,
101:     ) {
102:         if let Some(group) = self
103:             .groups
104:             .iter_mut()
105:             .find(|group| &group.source == source && &group.mesh == mesh)
106:         {
107:             group.instances.push(instance);
108:             return;
109:         }
110:         self.groups.push(VistaCardGroup {
111:             mesh: mesh.clone(),
112:             source: source.clone(),
113:             card_height,
114:             instances: vec![instance],
115:         });
116:     }
117: 
118:     /// Spawns chunks per variant. `far_band` is the LOD ring's fade-out;
119:     /// the near end stays zero because the shader applies each card's own
120:     /// cutoff, which varies with its instance scale.
121:     pub(super) fn spawn(
122:         self,
123:         commands: &mut Commands<'_, '_>,
124:         lod: &VistaLod,
125:         materials: &mut VistaTreeMaterials<'_>,
126:     ) {
127:         // Cards in a ring share the ring's fade-out; only the near cutoff
128:         // varies per card, and the shader derives that from the instance scale.
129:         let far = super::vista_tree_visibility(lod.spacing_metres, 1.0, 1.0).end_margin;
130:         let level = lod.level;
131:         for group in self.groups {
132:             let Some(source) = materials.impostor.get(&group.source) else {
133:                 continue;
134:             };
135:             let material = materials.cards.add(TacticalVistaTreeInstancedMaterial {
136:                 baked_color: source.baked_color.clone(),
137:                 parameters: Vec4::new(
138:                     group.card_height,
139:                     source.parameters.y,
140:                     source.parameters.z,
141:                     source.parameters.w,
142:                 ),
143:                 lighting: source.lighting,
144:                 ambient: source.ambient,
145:             });
146:             InstanceBatch {
147:                 mesh: group.mesh,
148:                 material,
149:                 instances: group.instances,
150:                 band: FadeBand::until(far.clone()),
151:                 // Cards turn to face the camera, so their width reaches as
152:                 // far as their height in every direction.
153:                 reach: InstanceReach {
154:                     horizontal: group.card_height,
155:                     above: group.card_height,
156:                     below: 0.0,
157:                 },
158:                 chunk_size: VISTA_CARD_CHUNK_SIZE,
159:             }
160:             .spawn(commands, |chunk| {
161:                 (
162:                     Name::new(format!("Instanced vista tree cards ({})", chunk.len())),
163:                     VistaTerrain(level),
164:                     super::VistaTreePresentation,
165:                 )
166:             });
167:         }
168:     }
169: }

