1: //! Chunk-instanced grass for every sward in the scene.
2: //!
3: //! One instance is a multi-blade tuft whose mesh reuses the shared blade,
4: //! species, and pigment construction (`grass_tuft_mesh`). Placement keeps the
5: //! jittered cell grid, the cover gate, and the slope rejection, then
6: //! subdivides each eligible cell into tufts. Ground-cover coverage is sampled
7: //! on the CPU at placement time and packed into each instance's seed byte, so
8: //! the shader needs no mask texture.
9: //!
10: //! The playable scene and the vista rings differ only in where height,
11: //! coverage, and community come from, so both go through [`TuftPlacement`] and
12: //! share one lattice walk and one batching path.
13: 
14: use fabelgeist_determinism::Seed;
15: 
16: use adventuresim_building_generator::spatial_geometry::GeometryResult;
17: use adventuresim_tactical_core::{
18:     city_layout::grounding::{SupportElevation, SupportQuery},
19:     prelude::{SceneEnvironment, SceneGround, SceneTerrain},
20:     scene_coordinates::ScenePlanPoint,
21: };
22: use bevy::{color::Color, prelude::*};
23: 
24: use crate::presentation::{
25:     bps,
26:     chunk_instancing::{ChunkInstance, ChunkMaterialPlugin, FadeBand, InstanceReach},
27:     stable_text_seed,
28: };
29: 
30: use super::{
31:     GrassInteractor, GroundScatterLayer,
32:     grass::{
33:         GrassCommunity, GrassCommunityField, GrassCommunityProfile, GrassMeshLod, GrassSpecies,
34:         cell_allows_grass, configured_tuft_footprint_metres, grass_species, grass_tuft_mesh,
35:     },
36:     grass_pigment, grass_scatter_density,
37: };
38: 
39: use super::cover_mask::CoverageMask;
40: pub(in crate::presentation) use batches::spawn_tuft_batches;
41: pub(crate) use diagnostics::GrassTriangleCount;
42: pub(in crate::presentation) use material::TacticalGrassInstancedMaterial;
43: 
44: mod batches;
45: mod diagnostics;
46: mod material;
47: mod streams;
48: mod variation;
49: 
50: const TIERS: [GrassMeshLod; 4] = [
51:     GrassMeshLod::Near,
52:     GrassMeshLod::NearEdge,
53:     GrassMeshLod::Far,
54:     GrassMeshLod::Vista,
55: ];
56: 
57: /// Maximum blade reach above a tuft root: authored ribbon height times the
58: /// largest height/species scaling the mesh generator produces.
59: const TUFT_HEIGHT_MARGIN_METRES: f32 = 1.5;
60: /// Roots sit on sampled terrain; this covers sinking into a steeper slope.
61: const TUFT_DEPTH_MARGIN_METRES: f32 = 0.3;
62: 
63: /// Grass rejects any site steeper than this surface normal tilt.
64: pub(in crate::presentation) const MINIMUM_GRASS_SLOPE_NORMAL_Y: f32 = 0.72;
65: 
66: /// Instance batches keyed by LOD tier, then by species within the tier.
67: pub(in crate::presentation) type TierSpeciesBatches =
68:     [[Vec<ChunkInstance>; GrassSpecies::ALL.len()]; TIERS.len()];
69: 
70: pub(crate) struct InstancedGrassPlugin;
71: 
72: /// Marks scenes whose instanced sward has been generated.
73: #[derive(Component)]
74: pub(super) struct InstancedGrassPresented;
75: 
76: /// Smoothing state for the grass interaction uniforms.
77: #[derive(Resource, Default)]
78: pub(in crate::presentation) struct InstancedGrassInteractionState {
79:     previous_position: Option<Vec3>,
80:     smoothed_velocity: Vec3,
81:     /// Last values written to the materials, to skip redundant asset writes
82:     /// (each write re-uploads the uniform and re-queues the batch).
83:     written: Option<(Vec3, Vec3)>,
84: }
85: 
86: /// The command buffer and asset stores a sward spawn writes through.
87: pub(in crate::presentation) struct GrassWorld<'a, 'w, 's> {
88:     pub(in crate::presentation) commands: &'a mut Commands<'w, 's>,
89:     pub(in crate::presentation) meshes: &'a mut Assets<Mesh>,
90:     pub(in crate::presentation) materials: &'a mut Assets<TacticalGrassInstancedMaterial>,
91: }
92: 
93: /// The playable scene's authoritative terrain, cover mask, and community profile.
94: struct ScenePlacement<'a> {
95:     terrain: &'a SceneTerrain,
96:     ground: &'a SceneGround,
97:     mask: CoverageMask,
98:     profile: GrassCommunityProfile,
99:     communities: GrassCommunityField,
100: }
101: 
102: /// The scene-wide pigment and wind inputs every tuft mesh and material shares.
103: #[derive(Clone, Copy)]
104: pub(in crate::presentation) struct TuftPigment {
105:     pub(in crate::presentation) color: Color,
106:     pub(in crate::presentation) density: f32,
107:     pub(in crate::presentation) dryness: f32,
108:     pub(in crate::presentation) wind_scale: f32,
109: }
110: 
111: /// Site sampling shared by playable terrain and vista heightfields. Both use
112: /// the same lattice walk, species selection, and batching below.
113: pub(in crate::presentation) trait TuftPlacement {
114:     /// Inclusive cell range to walk, in whole `cell_spacing` steps.
115:     fn lattice_bounds(&self, cell_spacing: f32) -> (IVec2, IVec2);
116: 
117:     /// Whether this jittered lattice cell may carry tufts at all.
118:     fn cell_allows(&self, cell_hash: Seed, cell: IVec2, cell_spacing: f32, jitter: f32) -> bool;
119: 
120:     /// Ground-cover coverage at a tuft centre; 0 leaves the site bare.
121:     fn coverage(&self, centre: ScenePlanPoint) -> u8;
122: 
123:     /// Ground height at a tuft centre, or `None` where the slope rejects grass.
124:     fn height(&self, centre: ScenePlanPoint) -> Option<SupportElevation>;
125: 
126:     /// Which community - and so which species pool - claims this site.
127:     fn community(&mut self, centre: ScenePlanPoint) -> GrassCommunity;
128: }
129: 
130: impl Plugin for InstancedGrassPlugin {
131:     fn build(&self, app: &mut App) {
132:         app.add_plugins((
133:             ChunkMaterialPlugin::<TacticalGrassInstancedMaterial>::default(),
134:             ChunkMaterialPlugin::<super::TacticalShrubBarkInstancedMaterial>::default(),
135:             ChunkMaterialPlugin::<super::TacticalShrubLeafInstancedMaterial>::default(),
136:         ))
137:         .init_resource::<InstancedGrassInteractionState>()
138:         .add_systems(
139:             Update,
140:             (present_instanced_grass, update_instanced_grass_interaction),
141:         );
142:     }
143: }
144: 
145: impl TuftPlacement for ScenePlacement<'_> {
146:     fn lattice_bounds(&self, cell_spacing: f32) -> (IVec2, IVec2) {
147:         let half = Vec2::new(self.terrain.width(), self.terrain.depth()) * 0.5;
148:         (
149:             (-half / cell_spacing).floor().as_ivec2(),
150:             (half / cell_spacing).ceil().as_ivec2(),
