182: pub(in crate::presentation) fn prepare_scene_tufts(
183:     terrain: &SceneTerrain,
184:     ground: &SceneGround,
185:     environment: &SceneEnvironment,
186:     grass: &crate::presentation::config::GrassConfig,
187:     fault_scarp: Option<&adventuresim_tactical_core::prelude::TerrainLandformRecipe>,
188: ) -> GeometryResult<TierSpeciesBatches> {
189:     if !grass.enabled {
190:         return Ok(Default::default());
191:     }
192:     let masked_ground = fault_scarp.map(|recipe| {
193:         super::scene_mask::scatter_ground_without_patch(ground, recipe.transition_collar())
194:     });
195:     let ground = masked_ground.as_ref().unwrap_or(ground);
196:     let base_seed = stable_text_seed(&environment.scene_digest).xor_word(0x6772_6173_735f_6c6f);
197:     let mut placement = ScenePlacement {
198:         terrain,
199:         ground,
200:         mask: CoverageMask::new(ground, stable_text_seed(&environment.scene_digest))?,
201:         profile: GrassCommunityProfile::from_environment(environment),
202:         communities: GrassCommunityField::new(base_seed),
203:     };
204:     let mut batches = TierSpeciesBatches::default();
205:     for lod in [GrassMeshLod::Near, GrassMeshLod::Far] {
206:         scatter_cell_tufts(
207:             &mut batches[lod.tier_index()],
208:             &mut placement,
209:             base_seed,
210:             lod,
211:             grass.placement.playable_patch_spacing_m,
212:             grass,
213:         );
214:     }
215:     // Reuse near placements so the near-edge crossfade does not move tufts.
216:     for species in GrassSpecies::ALL {
217:         batches[GrassMeshLod::NearEdge.tier_index()][species.index()] =
218:             batches[GrassMeshLod::Near.tier_index()][species.index()].clone();
219:     }
220:     scatter_cell_tufts(
221:         &mut batches[GrassMeshLod::Vista.tier_index()],
222:         &mut placement,
223:         base_seed.xor_word(0x7669_7374_615f_6c6f),
224:         GrassMeshLod::Vista,
225:         grass.placement.vista_patch_spacing_m,
226:         grass,
227:     );
228:     Ok(batches)
229: }
