421: /// Number of tuft columns/rows that subdivide one placement cell, per tier.
422: fn tufts_per_cell_side(lod: GrassMeshLod) -> i32 {
423:     match lod {
424:         GrassMeshLod::Near | GrassMeshLod::NearEdge => 12,
425:         GrassMeshLod::Far => 4,
426:         GrassMeshLod::Vista => 2,
427:     }
428: }
429: 
430: /// Legacy fade bands per tier: `xy` fade-in, `zw` fade-out, mirroring the
431: /// legacy `grass_lod_visibility` crossfade margins. The near tier's epsilon
432: /// fade-in keeps the dither-level math well-defined at zero distance.
433: ///
434: /// `range_scale` contracts every band edge uniformly, so tier hand-offs stay
435: /// contiguous while the geometric sward trades reach for vertex throughput.
436: /// Near-tier cost scales with the square of its radius, making this the
437: /// single most effective grass performance lever.
438: fn tier_visibility_range(lod: GrassMeshLod, range_scale: f32) -> Vec4 {
439:     let scale = range_scale.clamp(0.35, 1.0);
440:     (match lod {
441:         // #560's legacy near band (0..14 m) splits into a full-detail field and
442:         // a slimmer edge ring; the ring covers most of the band's area, so most
443:         // near verts move to the nine-vertex 6x6 mesh. The instanced tiers
444:         // reproduce the legacy `grass_lod_visibility` bands so the native and
445:         // wasm swards fade out at the same distances (~50 m terminal).
446:         GrassMeshLod::Near => Vec4::new(0.0, 0.001, 4.0, 6.0),
447:         GrassMeshLod::NearEdge => Vec4::new(4.0, 6.0, 7.0, 14.0),
448:         GrassMeshLod::Far => Vec4::new(7.0, 14.0, 36.0, 44.0),
449:         // The vista fade-in shares the far tier's fade-out endpoints so the
450:         // complementary crossfade partition hands off exactly.
451:         GrassMeshLod::Vista => Vec4::new(34.0, 42.0, 42.0, 50.0),
452:     }) * scale
453: }
454: 
455: fn configured_tier_band(
456:     lod: GrassMeshLod,
457:     grass: &crate::presentation::config::GrassConfig,
458: ) -> FadeBand {
459:     let tier = match lod {
460:         GrassMeshLod::Near => &grass.lod.near,
461:         GrassMeshLod::NearEdge => &grass.lod.near_edge,
462:         GrassMeshLod::Far => &grass.lod.far,
463:         GrassMeshLod::Vista => &grass.lod.vista,
464:     };
465:     FadeBand::new(
466:         tier.fade_in_m[0]..tier.fade_in_m[1],
467:         tier.fade_out_m[0]..tier.fade_out_m[1],
468:     )
469: }
