139:         _layout: &bevy::mesh::MeshVertexBufferLayoutRef,
140:         _key: Self::Data,
141:     ) -> Result<(), SpecializedMeshPipelineError> {
142:         // Leaf cards are shaded double-sided and cut out via A2C.
143:         descriptor.primitive.cull_mode = None;
144:         enable_alpha_to_coverage(descriptor);
145:         Ok(())
146:     }
147: }
148: 
149: /// Fade bands per representation; adjacent cambered/card bands share their
150: /// endpoints so the complementary crossfade partition hands off exactly.
151: fn representation_band(representation: ShrubRepresentation) -> FadeBand {
152:     match representation {
153:         ShrubRepresentation::Branches => FadeBand::until(44.0..52.0),
154:         ShrubRepresentation::CamberedLeaves => FadeBand::until(26.0..34.0),
155:         ShrubRepresentation::LeafCards => FadeBand::new(26.0..34.0, 84.0..96.0),
156:     }
157: }
158: 
159: #[derive(Clone, Copy, PartialEq, Eq)]
160: enum ShrubRepresentation {
161:     Branches,
162:     CamberedLeaves,
163:     LeafCards,
164: }
165: 
166: const REPRESENTATIONS: [ShrubRepresentation; 3] = [
167:     ShrubRepresentation::Branches,
168:     ShrubRepresentation::CamberedLeaves,
169:     ShrubRepresentation::LeafCards,
170: ];
171: 
172: #[expect(
173:     clippy::too_many_arguments,
174:     reason = "the instanced-understory construction boundary keeps asset stores, habitat, and placement inputs explicit"
175: )]
176: pub(super) fn spawn(
177:     commands: &mut Commands,
178:     bark_materials: &mut Assets<TacticalShrubBarkInstancedMaterial>,
179:     leaf_materials: &mut Assets<TacticalShrubLeafInstancedMaterial>,
180:     standard_materials: &Assets<StandardMaterial>,
181:     leaf_sources: &Assets<super::TacticalTreeLeafCardMaterial>,
182:     cache: &WoodyUnderstoryPresentationCache,
183:     terrain: &SceneTerrain,
184:     ground: &SceneGround,
185:     base_seed: Seed,
186:     chance: f32,
187:     habitat: UnderstoryHabitat,
188: ) {
189:     let mut per_species: [Vec<ChunkInstance>; 3] = Default::default();
190:     for ShrubPlacement {
191:         species,
192:         point,
193:         hash,
194:     } in understory::placements(terrain, ground, base_seed, chance, habitat)
195:     {
196:         // Preserve the shared understory/litter placement purposes, terrain
197:         // height and slope admission before projecting to the GPU instance.
198:         let (Some(height), Some(normal)) = (terrain.height_at(point), terrain.normal_at(point))
199:         else {
200:             continue;
201:         };
202:         if normal.y < 0.72 {
203:             continue;
204:         }
205:         let Ok(root) = Position::from_metres(Vec3::new(
206:             point.metres().x,
207:             height.metres(),
208:             point.metres().y,
209:         )) else {
210:             continue;
211:         };
212:         per_species[species_index(species)].push(shrub_instance(hash, root));
213:     }
214: 
215:     for species in [
216:         UnderstorySpecies::CommonHazel,
217:         UnderstorySpecies::Blackthorn,
218:         UnderstorySpecies::CommonHawthorn,
219:     ] {
220:         let instances = std::mem::take(&mut per_species[species_index(species)]);
221:         if instances.is_empty() {
222:             continue;
223:         }
224:         let presentation = cache.presentation(species);
225:         let (Some(branches), Some(cambered), Some(cards), Some(bark_handle), Some(leaf_handle)) = (
226:             presentation.branches.clone(),
227:             presentation.cambered_leaves.clone(),
228:             presentation.leaf_cards.clone(),
229:             presentation.bark.as_ref(),
230:             presentation.leaves.as_ref(),
231:         ) else {
232:             continue;
233:         };
234:         let bark_color = standard_materials
235:             .get(bark_handle)
236:             .map(|material| {
237:                 let linear = material.base_color.to_linear();
238:                 Vec4::new(
239:                     linear.red,
240:                     linear.green,
241:                     linear.blue,
242:                     material.perceptual_roughness,
243:                 )
244:             })
245:             .unwrap_or(Vec4::new(0.16, 0.13, 0.10, 0.96));
246:         let Some(leaf) = leaf_sources.get(leaf_handle) else {
247:             continue;
248:         };
249:         let bark = bark_materials.add(TacticalShrubBarkInstancedMaterial { color: bark_color });
250:         for representation in REPRESENTATIONS {
251:             let (mesh, label) = match representation {
252:                 ShrubRepresentation::Branches => (branches.clone(), "wood"),
253:                 ShrubRepresentation::CamberedLeaves => (cambered.clone(), "cambered leaves"),
254:                 ShrubRepresentation::LeafCards => (cards.clone(), "leaf cards"),
255:             };
256:             let components = |chunk: &[ChunkInstance]| {
257:                 (
258:                     Name::new(format!(
259:                         "Instanced {species:?} shrub {label} ({})",
260:                         chunk.len()
261:                     )),
262:                     super::GroundScatterLayer::Understory,
263:                 )
264:             };
265:             let band = representation_band(representation);
266:             let reach = ground_scatter_reach(SHRUB_FOOTPRINT_METRES);
267:             match representation {
268:                 ShrubRepresentation::Branches => InstanceBatch {
269:                     mesh,
270:                     material: bark.clone(),
271:                     instances: instances.clone(),
272:                     band,
273:                     reach,
274:                     chunk_size: SHRUB_CHUNK_SIZE,
275:                 }
276:                 .spawn(commands, components),
277:                 ShrubRepresentation::CamberedLeaves | ShrubRepresentation::LeafCards => {
278:                     InstanceBatch {
279:                         mesh,
280:                         material: leaf_materials
281:                             .add(TacticalShrubLeafInstancedMaterial::from(leaf)),
282:                         instances: instances.clone(),
283:                         band,
284:                         reach,
285:                         chunk_size: SHRUB_CHUNK_SIZE,
286:                     }
287:                     .spawn(commands, components)
288:                 }
289:             }
290:         }
291:     }
292: }
293: 
294: fn species_index(species: UnderstorySpecies) -> usize {
295:     match species {
296:         UnderstorySpecies::CommonHazel => 0,
297:         UnderstorySpecies::Blackthorn => 1,
298:         UnderstorySpecies::CommonHawthorn => 2,
299:     }
300: }
301: 
302: fn shrub_instance(hash: Seed, root: Position<Scene>) -> ChunkInstance {
303:     let yaw = PLACEMENT_YAW.rng(hash, &[]).inclusive_unit_f32() * core::f32::consts::TAU;
304:     let scale = 0.72 + PLACEMENT_SCALE.rng(hash, &[]).inclusive_unit_f32() * 0.58;
305:     ChunkInstance {
306:         position: root.metres(),
307:         scale,
308:         rotation: yaw,
309:         seed: (StreamId::new("visual.ground-scatter.instanced-understory.shader-seed")
310:             .seed(hash, &[])
311:             .to_u64()
312:             & 0xffff_ffff) as u32,
313:     }
314: }

