1: //! Chunk-instanced rendering for dense scatter: grass, shrubs, loose stones
2: //! and distant tree cards.
3: //!
4: //! A batch is one mesh drawn many times. It is split into ground chunks, and
5: //! each chunk is an ordinary entity: Bevy's CPU frustum and range culling
6: //! decide which chunks a camera sees, and each visible chunk is one instanced
7: //! `draw_indexed` over its own instance buffer, uploaded once. Instances fade
8: //! in and out per instance in the shader, so crossfading distance bands hand
9: //! over pixel-exactly however the chunks fall. Chunks draw in the main pass
10: //! only, never in prepass or shadow passes.
11: mod draw;
12: mod instance;
13: mod material;
14: mod pipeline;
15: mod queue;
16: mod spawn;
17: 
18: use std::marker::PhantomData;
19: 
20: use bevy::{
21:     core_pipeline::core_3d::Opaque3d,
22:     pbr::MeshPipelineSystems,
23:     prelude::*,
24:     render::{
25:         Render, RenderApp, RenderStartup, RenderSystems,
26:         extract_component::ExtractComponentPlugin,
27:         render_asset::RenderAssetPlugin,
28:         render_phase::AddRenderCommand,
29:         render_resource::{BindGroupLayoutDescriptor, SpecializedMeshPipelines},
30:     },
31:     shader::load_shader_library,
32: };
33: 
34: pub(in crate::presentation) use instance::ChunkMaterial;
35: pub(crate) use instance::{ChunkInstance, FadeBand, InstanceChunk};
36: pub(in crate::presentation) use material::{ChunkInstancedMaterial, enable_alpha_to_coverage};
37: pub(in crate::presentation) use spawn::{ChunkSize, InstanceBatch, InstanceReach};
38: 
39: /// The renderer shared by every chunk-instanced material; each
40: /// [`ChunkMaterialPlugin`] adds it once.
41: pub(in crate::presentation) struct ChunkInstancingPlugin;
42: 
43: /// Draws chunks whose [`ChunkMaterial`] is an `M`.
44: pub(in crate::presentation) struct ChunkMaterialPlugin<M>(PhantomData<M>);
45: 
46: /// The group-2 band layout shared by every chunk-instanced pipeline.
47: #[derive(Resource)]
48: struct ChunkBandLayout(BindGroupLayoutDescriptor);
49: 
50: impl Plugin for ChunkInstancingPlugin {
51:     fn build(&self, app: &mut App) {
52:         load_shader_library!(app, "chunk_instancing/chunk_instancing.wgsl");
53:         app.add_plugins(ExtractComponentPlugin::<InstanceChunk>::default());
54:         app.sub_app_mut(RenderApp)
55:             .insert_resource(ChunkBandLayout(draw::band_layout()))
56:             .add_systems(
57:                 Render,
58:                 draw::prepare_chunk_buffers.in_set(RenderSystems::PrepareResources),
59:             );
60:     }
61: }
62: 
63: impl<M> Default for ChunkMaterialPlugin<M> {
64:     fn default() -> Self {
65:         Self(PhantomData)
66:     }
67: }
68: 
69: impl<M: ChunkInstancedMaterial> Plugin for ChunkMaterialPlugin<M> {
70:     fn build(&self, app: &mut App) {
71:         if !app.is_plugin_added::<ChunkInstancingPlugin>() {
72:             app.add_plugins(ChunkInstancingPlugin);
73:         }
74:         app.init_asset::<M>().add_plugins((
75:             ExtractComponentPlugin::<ChunkMaterial<M>>::default(),
76:             RenderAssetPlugin::<material::PreparedChunkMaterial<M>>::default(),
77:         ));
78:         app.sub_app_mut(RenderApp)
79:             .add_render_command::<Opaque3d, draw::DrawChunkInstances<M>>()
80:             .init_resource::<SpecializedMeshPipelines<pipeline::ChunkMaterialPipeline<M>>>()
81:             .init_resource::<queue::QueuedChunks<M>>()
82:             .add_systems(
83:                 RenderStartup,
84:                 init_pipeline::<pipeline::ChunkMaterialPipeline<M>>.after(MeshPipelineSystems),
85:             )
86:             .add_systems(
87:                 Render,
88:                 queue::queue_chunks::<M>
89:                     .in_set(RenderSystems::QueueMeshes)
90:                     .after(bevy::pbr::queue_material_meshes),
91:             );
92:     }
93: }
94: 
95: fn init_pipeline<P: Resource + FromWorld>(world: &mut World) {
96:     let pipeline = P::from_world(world);
97:     world.insert_resource(pipeline);
98: }

