337: /// Like [`parse_yaml12_float`], but a decimal/exponential literal that overflows `f64` to
338: /// infinity (e.g. `1e999`, `9e400`) is treated as a successful non-finite parse instead of
339: /// an error.
340: ///
341: /// This is used only by `deserialize_any`'s typeless path (e.g. `serde_json::Value`), where
342: /// non-finite floats are rejected by default, or represented as canonical strings when
343: /// `reject_non_finite_typeless_float` is disabled, rather than causing an "invalid floating
344: /// point" parse error. Elsewhere, overflowing literals continue to be rejected as invalid
345: /// floats via [`parse_yaml12_float`], so this function must not replace it as the general
346: /// entry point.
347: ///
348: /// Deliberately narrower than a bare `str::parse::<f64>()`: Rust's parser also accepts
349: /// alphabetic spellings (`inf`, `infinity`, `nan`) that YAML/serde-saphyr correctly keep as
350: /// plain strings, so only numeral-shaped literals (optional sign, then a leading digit) are
351: /// considered here.
352: pub(crate) fn try_parse_float_incl_overflow(
353:     s: &str,
354:     location: Location,
355:     tag: SfTag,
356:     angle_conversions: bool,
357: ) -> Option<f64> {
358:     if let Ok(v) = parse_yaml12_float::<f64>(s, location, tag, angle_conversions) {
359:         return Some(v);
360:     }
361: 
362:     let t = s.trim();
363:     let unsigned = t.strip_prefix(['+', '-']).unwrap_or(t);
364:     if !unsigned.as_bytes().first().is_some_and(u8::is_ascii_digit) {
365:         return None;
366:     }
367: 
368:     match t.parse::<f64>() {
369:         Ok(v) if v.is_infinite() => Some(v),
370:         _ => None,
371:     }
372: }
