775:             }
776: 
777:             // Consume the scalar and attempt typed parses in order: bool -> int -> float.
778:             // Parse the effective value, but keep the raw source text for diagnostics.
779:             let view = self.take_scalar_view()?;
780:             let raw = view.raw.into_owned();
