1: // Chunk-instanced grass tufts.
2: //
3: // This is the instanced port of the grass path in `tactical_foliage.wgsl`.
4: // One instance is a multi-blade tuft; per-blade shape, pigment, and age are
5: // baked into the shared tuft mesh exactly like the legacy macro patches, so
6: // the two renderers stay visually comparable. Per-instance data carries the
7: // tuft root, yaw, scale, and a packed seed whose low byte is the ground-cover
8: // coverage sampled at placement time - the legacy per-vertex mask fetch is
9: // therefore replaced by CPU sampling, and this shader needs no texture.
10: //
11: // Mesh vertex contract (identical to the legacy grass patch meshes):
12: //   uv    = (side 0|1, height fraction; tip uses 0.5)
13: //   uv_b  = blade root offset in tuft-local xz
14: //   color = species pigment, alpha = per-blade threshold/variation hash
15: 
16: #import bevy_pbr::{
17:     mesh_view_bindings::{globals, lights, view},
18:     shadows,
19: }
20: 
21: #import fablegeist::chunk_instancing::{
22:     Vertex, chunk_band, instance_world_matrix, visibility_range_dither_level,
23: }
24: 
25: struct TacticalGrassInstancedUniform {
26:     // Wind direction xy, strength, and time scale.
27:     wind: vec4<f32>,
28:     // Interactor world position (xyz) and interaction radius.
29:     interaction: vec4<f32>,
30:     // Interactor smoothed velocity (xyz) and push strength.
31:     interaction_motion: vec4<f32>,
32:     // Root occlusion, dryness lane, authored lean, width compensation.
33:     params: vec4<f32>,
34:     // y scales the flat ambient term to stand in for the skipped image-based
35:     // lighting; every tier now shades fast, so x/z/w are reserved.
36:     shading: vec4<f32>,
37: }
38: 
39: @group(3) @binding(0) var<uniform> grass: TacticalGrassInstancedUniform;
40: 
41: struct GrassVertexOutput {
42:     @builtin(position) clip_position: vec4<f32>,
43: #ifdef VISIBILITY_RANGE_DITHER
44:     @location(0) @interpolate(flat) visibility_range_dither: i32,
45: #endif
46:     @location(1) world_position: vec4<f32>,
47:     @location(2) world_normal: vec3<f32>,
48:     @location(3) uv: vec2<f32>,
49:     @location(4) color: vec4<f32>,
50: }
51: 
52: @vertex
53: fn vertex(vertex: Vertex) -> GrassVertexOutput {
54:     var out: GrassVertexOutput;
55:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
56: 
57:     var blade_root_local = vec3<f32>(0.0, 0.0, 0.0);
58:     var blade_threshold = 0.0;
59: #ifdef VERTEX_UVS_B
60:     blade_root_local = vec3<f32>(vertex.uv_b.x, 0.0, vertex.uv_b.y);
61: #endif
62: #ifdef VERTEX_COLORS
63:     blade_threshold = vertex.color.a;
64: #endif
65: 
66:     let root_world = (instance_matrix * vec4<f32>(blade_root_local, 1.0)).xyz;
67:     let spatial_noise = sin(root_world.x * 0.071 + root_world.z * 0.113)
68:         * sin(root_world.x * 0.037 - root_world.z * 0.053);
69: 
70:     // Placement-time ground coverage, packed into the instance seed's low
71:     // byte. Distance opening reproduces the legacy meadow clump break-up.
72:     let ground_coverage = f32(vertex.i_seed & 0xffu) / 255.0;
73:     let meadow_zone = smoothstep(-0.36, 0.52, spatial_noise);
74:     let camera_distance = distance(root_world, view.world_position.xyz);
75:     let distance_opening = smoothstep(7.0, 24.0, camera_distance);
76:     let clump_coverage = mix(1.0, mix(0.54, 1.0, meadow_zone), distance_opening);
77:     let effective_coverage = ground_coverage * clump_coverage;
78:     let blade_visibility = select(1.0, 0.0, blade_threshold > effective_coverage);
79: 
80:     let bend = clamp(vertex.uv.y, 0.0, 1.0);
81:     let wind_direction = normalize(grass.wind.xy);
82:     let wind_cross = vec2<f32>(-wind_direction.y, wind_direction.x);
83: 
84:     let blade_variation = fract(
85:         blade_threshold * 1.73 + spatial_noise * 0.31
86:             + root_world.x * 0.013 - root_world.z * 0.017
87:     );
88:     let age_signal = fract(blade_threshold * 2.37 + 0.13);
89:     let mature_age = smoothstep(0.68, 0.94, age_signal);
90:     let juvenile_vigor = 0.28 + 0.78 * blade_variation * blade_variation;
91:     let mature_vigor = 0.48 + 0.58 * blade_variation;
92:     let edge_growth = mix(0.26, 1.0, smoothstep(0.04, 0.92, ground_coverage));
93:     let blade_vigor = mix(juvenile_vigor, mature_vigor, meadow_zone)
94:         * edge_growth
95:         * mix(1.0, 0.94, mature_age);
96: 
97:     let wave_position = dot(root_world.xz, wind_direction) * 0.22;
98:     let wind_time = globals.time * grass.wind.w;
99:     let gust = 0.68 + 0.32 * sin(wind_time * 0.29 + spatial_noise * 3.7);
100:     let primary_wave = sin(wind_time + wave_position + spatial_noise * 1.9);
101:     let flutter = sin(wind_time * 2.73 - wave_position * 1.61 + spatial_noise * 5.3);
102:     let lean_variation = fract(blade_variation * 1.618 + blade_threshold * 0.73);
103:     let lean_direction = normalize(vec2<f32>(
104:         fract(blade_threshold * 1.37 + 0.17) - 0.5,
105:         fract(blade_threshold * 2.11 + 0.63) - 0.5,
106:     ) + vec2<f32>(0.0001, 0.0));
107:     let lean_amount = 0.025 + 0.030 * lean_variation;
108:     let natural_lean = lean_direction * (lean_amount + 0.012 * mature_age);
109:     let wind_offset = (
110:         wind_direction * primary_wave * gust
111:         + wind_cross * flutter * 0.18
112:     ) * grass.wind.z;
113: 
114:     var interaction_offset = vec2<f32>(0.0, 0.0);
115:     var interaction_droop = 0.0;
116:     if grass.interaction.w > 0.0 {
117:         let from_player = root_world.xz - grass.interaction.xz;
118:         let player_distance = length(from_player);
119:         let velocity_xz = grass.interaction_motion.xz;
120:         let fallback_direction = normalize(velocity_xz + vec2<f32>(0.0001, 0.0));
121:         let push_direction = select(
122:             fallback_direction,
123:             normalize(from_player),
124:             player_distance > 0.001,
125:         );
126:         let player_push = (1.0 - smoothstep(0.18, grass.interaction.w, player_distance))
127:             * grass.interaction_motion.w;
128:         let motion_direction = normalize(velocity_xz + push_direction * 0.15);
129:         interaction_offset = (
130:             push_direction * 0.62 + motion_direction * min(length(velocity_xz) * 0.035, 0.28)
131:         ) * player_push;
132:         interaction_droop = player_push * 0.34;
133:     }
134: 
135:     let original_world_normal =
136:         normalize((instance_matrix * vec4<f32>(vertex.normal, 0.0)).xyz);
137: 
138:     // Single-ribbon reconstruction: rows follow one cubic curve; the ribbon
139:     // rotates toward the camera only as it becomes edge-on.
140:     let t = bend;
141:     let one_minus_t = 1.0 - t;
142:     let curve_profile = 3.0 * one_minus_t * one_minus_t * t * 0.06
143:         + 3.0 * one_minus_t * t * t * 0.5
144:         + t * t * t;
145:     let curve_derivative = 3.0 * one_minus_t * one_minus_t * 0.06
146:         + 6.0 * one_minus_t * t * (0.5 - 0.06)
147:         + 3.0 * t * t * (1.0 - 0.5);
148:     let authored_facing = normalize(original_world_normal.xz + vec2<f32>(0.0001, 0.0));
149:     let authored_amount = 0.65 + 0.30 * fract(blade_threshold * 1.91 + blade_variation * 0.47);
150:     let total_curve = authored_facing * grass.params.z * authored_amount
151:         + natural_lean
152:         + wind_offset
153:         + interaction_offset;
154: 
155:     let curve_offset = total_curve * curve_profile * blade_visibility;
156:     let world_up = normalize((instance_matrix * vec4<f32>(0.0, 1.0, 0.0, 0.0)).xyz);
157:     let tangent = normalize(vec3<f32>(
158:         world_up.x * blade_vigor + total_curve.x * curve_derivative,
159:         world_up.y * blade_vigor - interaction_droop * 2.0 * t,
160:         world_up.z * blade_vigor + total_curve.y * curve_derivative,
161:     ));
162: 
163:     let collapsed_position = blade_root_local
164:         + (vertex.position - blade_root_local) * blade_visibility;
165:     let centre_local = vec3<f32>(
166:         blade_root_local.x,
167:         collapsed_position.y * blade_vigor,
168:         blade_root_local.z,
169:     );
170:     let centre_world = instance_matrix * vec4<f32>(centre_local, 1.0);
171: 
172:     let local_side = normalize(vec2<f32>(-vertex.normal.z, vertex.normal.x));
173:     let transformed_side =
174:         (instance_matrix * vec4<f32>(local_side.x, 0.0, local_side.y, 0.0)).xz;
175:     let side_scale = length(transformed_side);
176:     let original_side = normalize(transformed_side + vec2<f32>(0.0001, 0.0));
177:     let to_camera = normalize(view.world_position.xz - root_world.xz
178:         + vec2<f32>(0.0001, 0.0));
179:     var camera_side = vec2<f32>(-to_camera.y, to_camera.x);
180:     camera_side = select(camera_side, -camera_side, dot(camera_side, original_side) < 0.0);
181:     let edge_on = 1.0 - smoothstep(
182:         0.08,
183:         0.38,
184:         abs(dot(original_world_normal.xz, to_camera)),
185:     );
186:     let visible_side = normalize(mix(original_side, camera_side, edge_on * 0.88));
187:     let half_width = length(collapsed_position.xz - blade_root_local.xz)
188:         * side_scale
189:         * max(grass.params.w, 1.0);
190:     let signed_side = select(-1.0, 1.0, vertex.uv.x >= 0.5);
191:     let side_offset = visible_side * half_width * signed_side;
192:     let world_position = vec4<f32>(
193:         centre_world.x + curve_offset.x + side_offset.x,
194:         centre_world.y - interaction_droop * t * t * blade_visibility,
195:         centre_world.z + curve_offset.y + side_offset.y,
196:         centre_world.w,
197:     );
198: 
199:     let shaped_world_normal = normalize(cross(
200:         tangent,
201:         vec3<f32>(visible_side.x, 0.0, visible_side.y),
202:     ));
203: 
204:     out.world_position = world_position;
205:     out.clip_position = view.clip_from_world * world_position;
206:     // The legacy path biases blade normals toward the sky (shading.z = 0.76).
207:     out.world_normal = normalize(mix(
208:         shaped_world_normal,
209:         vec3<f32>(0.0, 1.0, 0.0),
210:         0.76,
211:     ));
212:     out.uv = vertex.uv;
213: #ifdef VERTEX_COLORS
214:     out.color = vec4<f32>(vertex.color.rgb, 1.0);
215: #else
216:     out.color = vec4<f32>(1.0);
217: #endif
218: #ifdef VISIBILITY_RANGE_DITHER
219:     out.visibility_range_dither = visibility_range_dither_level(chunk_band.visibility_range, root_world);
220: #endif
221:     return out;
222: }
223: 
224: @fragment
225: fn fragment(
226:     in: GrassVertexOutput,
227:     @builtin(front_facing) is_front: bool,
228: ) -> @location(0) vec4<f32> {
229: #ifdef VISIBILITY_RANGE_DITHER
230:     // Complementary per-pixel partition between crossfading tiers. The old
231:     // AlphaToCoverage fade thinned the sward in a bald ring at every tier
232:     // boundary: equal alphas map to the same hardware coverage mask, so
233:     // the outgoing and incoming tiers overlapped on the same samples
234:     // instead of summing to solid. Adjacent tiers share their fade band
235:     // endpoints, so their dither levels quantize complementarily; keeping
236:     // the outgoing tier on `hash >= t` and the incoming tier on the
237:     // complement hands every pixel to exactly one tier - no gap, no
238:     // double-shaded overlap.
239:     if in.visibility_range_dither != 0 {
240:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
241:         let pixel_hash = fract(
242:             52.9829189
243:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
244:         );
245:         if in.visibility_range_dither > 0 {
246:             // Fading out with distance: keep the far side of the hash.
247:             if pixel_hash < magnitude {
248:                 discard;
249:             }
250:         } else if pixel_hash >= 1.0 - magnitude {
251:             // Fading in: keep exactly the pixels the outgoing tier dropped.
252:             discard;
253:         }
254:     }
255: #endif
256:     let lod_coverage = 1.0;
257:     let height_fraction = clamp(in.uv.y, 0.0, 1.0);
258:     let root_self_shadow = mix(grass.params.x, 1.0, pow(height_fraction, 0.72));
259:     let centre_distance = abs(in.uv.x - 0.5) * 2.0;
260:     let centre_rib = mix(0.84, 1.0, smoothstep(0.12, 0.72, centre_distance));
261:     var base_normal = select(-in.world_normal, in.world_normal, is_front);
262:     // Keep both thin faces in the upper hemisphere; see the legacy shader.
263:     base_normal.y = abs(base_normal.y);
264:     base_normal = normalize(base_normal);
265: 
266:     // Every tier - including the near field - shades with the fast foliage
267:     // model (bevy_feronia's default instanced-grass model): flat ambient +
268:     // wrapped Lambert translucency + one clamped cascade fetch. No tier
269:     // evaluates image-based lighting, diffuse transmission, or specular. The
270:     // near field already crossfaded seamlessly into this model at 8-10 m, so
271:     // its former full-PBR path was pure per-fragment cost for no visible gain.
272:     let occlusion = root_self_shadow * centre_rib;
273:     let albedo = in.color.rgb;
274:     var lit = albedo * lights.ambient_color.rgb * grass.shading.y * occlusion;
275:     let view_z = dot(vec4<f32>(
276:         view.view_from_world[0].z,
277:         view.view_from_world[1].z,
278:         view.view_from_world[2].z,
279:         view.view_from_world[3].z,
280:     ), in.world_position);
281:     for (var light_index = 0u; light_index < lights.n_directional_lights;
282:         light_index += 1u)
283:     {
284:         let light = lights.directional_lights[light_index];
285:         let alignment = dot(base_normal, light.direction_to_light);
286:         // Wrapped diffuse matching the old near-field energy split: with
287:         // diffuse_transmission 0.36 only 64% of light reflects off the lit
288:         // face while 36% passes through from behind.
289:         let wrapped = saturate(alignment) * 0.64 + saturate(-alignment) * 0.36;
290:         let shadow = clamp(
291:             shadows::fetch_directional_shadow(
292:                 light_index,
293:                 in.world_position,
294:                 base_normal,
295:                 view_z,
296:                 in.clip_position.xy,
297:             ),
298:             0.12,
299:             1.0,
300:         );
301:         // 1/pi matches the Lambert BRDF normalisation the near field used.
302:         lit += albedo * light.color.rgb * (wrapped * shadow * occlusion * 0.3183099);
303:     }
304:     return vec4<f32>(lit * view.exposure, lod_coverage);
305: }

1: // GPU-instanced grass tufts on bevy_eidolon's instanced-material pipeline.
2: //
3: // This is the instanced port of the grass path in `tactical_foliage.wgsl`.
4: // One instance is a multi-blade tuft; per-blade shape, pigment, and age are
5: // baked into the shared tuft mesh exactly like the legacy macro patches, so
6: // the two renderers stay visually comparable. Per-instance data carries the
7: // tuft root, yaw, scale, and a packed seed whose low byte is the ground-cover
8: // coverage sampled at placement time - the legacy per-vertex mask fetch is
9: // therefore replaced by CPU sampling, and this shader needs no texture.
10: //
11: // Mesh vertex contract (identical to the legacy grass patch meshes):
12: //   uv    = (side 0|1, height fraction; tip uses 0.5)
13: //   uv_b  = blade root offset in tuft-local xz
14: //   color = species pigment, alpha = per-blade threshold/variation hash
15: 
16: #import bevy_pbr::{
17:     mesh_view_bindings::{globals, lights, view},
18:     shadows,
19: }
20: 
21: #import bevy_eidolon::render::utils
22: #import bevy_eidolon::render::bindings::instance_uniforms
23: #import bevy_eidolon::render::io_types::Vertex
24: 
25: struct TacticalGrassInstancedUniform {
26:     // Wind direction xy, strength, and time scale.
27:     wind: vec4<f32>,
28:     // Interactor world position (xyz) and interaction radius.
29:     interaction: vec4<f32>,
30:     // Interactor smoothed velocity (xyz) and push strength.
31:     interaction_motion: vec4<f32>,
32:     // Root occlusion, dryness lane, authored lean, width compensation.
33:     params: vec4<f32>,
34:     // y scales the flat ambient term to stand in for the skipped image-based
35:     // lighting; every tier now shades fast, so x/z/w are reserved.
36:     shading: vec4<f32>,
37: }
38: 
39: @group(3) @binding(0) var<uniform> grass: TacticalGrassInstancedUniform;
40: 
41: struct GrassVertexOutput {
42:     @builtin(position) clip_position: vec4<f32>,
43: #ifdef VISIBILITY_RANGE_DITHER
44:     @location(0) @interpolate(flat) visibility_range_dither: i32,
45: #endif
46:     @location(1) world_position: vec4<f32>,
47:     @location(2) world_normal: vec3<f32>,
48:     @location(3) uv: vec2<f32>,
49:     @location(4) color: vec4<f32>,
50:     @location(5) @interpolate(flat) i_batch_id: u32,
51: }
52: 
53: @vertex
54: fn vertex(vertex: Vertex) -> GrassVertexOutput {
55:     var out: GrassVertexOutput;
56:     let batch = instance_uniforms[vertex.i_batch_id];
57:     let instance_matrix = utils::calc_instance_world_matrix(
58:         vertex.i_pos_scale,
59:         vertex.i_rotation,
60:         batch.world_from_local,
61:     );
62: 
63:     var blade_root_local = vec3<f32>(0.0, 0.0, 0.0);
64:     var blade_threshold = 0.0;
65: #ifdef VERTEX_UVS_B
66:     blade_root_local = vec3<f32>(vertex.uv_b.x, 0.0, vertex.uv_b.y);
67: #endif
68: #ifdef VERTEX_COLORS
69:     blade_threshold = vertex.color.a;
70: #endif
71: 
72:     let root_world = (instance_matrix * vec4<f32>(blade_root_local, 1.0)).xyz;
73:     let spatial_noise = sin(root_world.x * 0.071 + root_world.z * 0.113)
74:         * sin(root_world.x * 0.037 - root_world.z * 0.053);
75: 
76:     // Placement-time ground coverage, packed into the instance seed's low
77:     // byte. Distance opening reproduces the legacy meadow clump break-up.
78:     let ground_coverage = f32(vertex.i_seed & 0xffu) / 255.0;
79:     let meadow_zone = smoothstep(-0.36, 0.52, spatial_noise);
80:     let camera_distance = distance(root_world, view.world_position.xyz);
81:     let distance_opening = smoothstep(7.0, 24.0, camera_distance);
82:     let clump_coverage = mix(1.0, mix(0.54, 1.0, meadow_zone), distance_opening);
83:     let effective_coverage = ground_coverage * clump_coverage;
84:     let blade_visibility = select(1.0, 0.0, blade_threshold > effective_coverage);
85: 
86:     let bend = clamp(vertex.uv.y, 0.0, 1.0);
87:     let wind_direction = normalize(grass.wind.xy);
88:     let wind_cross = vec2<f32>(-wind_direction.y, wind_direction.x);
89: 
90:     let blade_variation = fract(
91:         blade_threshold * 1.73 + spatial_noise * 0.31
92:             + root_world.x * 0.013 - root_world.z * 0.017
93:     );
94:     let age_signal = fract(blade_threshold * 2.37 + 0.13);
95:     let mature_age = smoothstep(0.68, 0.94, age_signal);
96:     let juvenile_vigor = 0.28 + 0.78 * blade_variation * blade_variation;
97:     let mature_vigor = 0.48 + 0.58 * blade_variation;
98:     let edge_growth = mix(0.26, 1.0, smoothstep(0.04, 0.92, ground_coverage));
99:     let blade_vigor = mix(juvenile_vigor, mature_vigor, meadow_zone)
100:         * edge_growth
101:         * mix(1.0, 0.94, mature_age);
102: 
103:     let wave_position = dot(root_world.xz, wind_direction) * 0.22;
104:     let wind_time = globals.time * grass.wind.w;
105:     let gust = 0.68 + 0.32 * sin(wind_time * 0.29 + spatial_noise * 3.7);
106:     let primary_wave = sin(wind_time + wave_position + spatial_noise * 1.9);
107:     let flutter = sin(wind_time * 2.73 - wave_position * 1.61 + spatial_noise * 5.3);
108:     let lean_variation = fract(blade_variation * 1.618 + blade_threshold * 0.73);
109:     let lean_direction = normalize(vec2<f32>(
110:         fract(blade_threshold * 1.37 + 0.17) - 0.5,
111:         fract(blade_threshold * 2.11 + 0.63) - 0.5,
112:     ) + vec2<f32>(0.0001, 0.0));
113:     let lean_amount = 0.025 + 0.030 * lean_variation;
114:     let natural_lean = lean_direction * (lean_amount + 0.012 * mature_age);
115:     let wind_offset = (
116:         wind_direction * primary_wave * gust
117:         + wind_cross * flutter * 0.18
118:     ) * grass.wind.z;
119: 
120:     var interaction_offset = vec2<f32>(0.0, 0.0);
121:     var interaction_droop = 0.0;
122:     if grass.interaction.w > 0.0 {
123:         let from_player = root_world.xz - grass.interaction.xz;
124:         let player_distance = length(from_player);
125:         let velocity_xz = grass.interaction_motion.xz;
126:         let fallback_direction = normalize(velocity_xz + vec2<f32>(0.0001, 0.0));
127:         let push_direction = select(
128:             fallback_direction,
129:             normalize(from_player),
130:             player_distance > 0.001,
131:         );
132:         let player_push = (1.0 - smoothstep(0.18, grass.interaction.w, player_distance))
133:             * grass.interaction_motion.w;
134:         let motion_direction = normalize(velocity_xz + push_direction * 0.15);
135:         interaction_offset = (
136:             push_direction * 0.62 + motion_direction * min(length(velocity_xz) * 0.035, 0.28)
137:         ) * player_push;
138:         interaction_droop = player_push * 0.34;
139:     }
140: 
141:     let original_world_normal =
142:         normalize((instance_matrix * vec4<f32>(vertex.normal, 0.0)).xyz);
143: 
144:     // Single-ribbon reconstruction: rows follow one cubic curve; the ribbon
145:     // rotates toward the camera only as it becomes edge-on.
146:     let t = bend;
147:     let one_minus_t = 1.0 - t;
148:     let curve_profile = 3.0 * one_minus_t * one_minus_t * t * 0.06
149:         + 3.0 * one_minus_t * t * t * 0.5
150:         + t * t * t;
151:     let curve_derivative = 3.0 * one_minus_t * one_minus_t * 0.06
152:         + 6.0 * one_minus_t * t * (0.5 - 0.06)
153:         + 3.0 * t * t * (1.0 - 0.5);
154:     let authored_facing = normalize(original_world_normal.xz + vec2<f32>(0.0001, 0.0));
155:     let authored_amount = 0.65 + 0.30 * fract(blade_threshold * 1.91 + blade_variation * 0.47);
156:     let total_curve = authored_facing * grass.params.z * authored_amount
157:         + natural_lean
158:         + wind_offset
159:         + interaction_offset;
160: 
161:     let curve_offset = total_curve * curve_profile * blade_visibility;
162:     let world_up = normalize((instance_matrix * vec4<f32>(0.0, 1.0, 0.0, 0.0)).xyz);
163:     let tangent = normalize(vec3<f32>(
164:         world_up.x * blade_vigor + total_curve.x * curve_derivative,
165:         world_up.y * blade_vigor - interaction_droop * 2.0 * t,
166:         world_up.z * blade_vigor + total_curve.y * curve_derivative,
167:     ));
168: 
169:     let collapsed_position = blade_root_local
170:         + (vertex.position - blade_root_local) * blade_visibility;
171:     let centre_local = vec3<f32>(
172:         blade_root_local.x,
173:         collapsed_position.y * blade_vigor,
174:         blade_root_local.z,
175:     );
176:     let centre_world = instance_matrix * vec4<f32>(centre_local, 1.0);
177: 
178:     let local_side = normalize(vec2<f32>(-vertex.normal.z, vertex.normal.x));
179:     let transformed_side =
180:         (instance_matrix * vec4<f32>(local_side.x, 0.0, local_side.y, 0.0)).xz;
181:     let side_scale = length(transformed_side);
182:     let original_side = normalize(transformed_side + vec2<f32>(0.0001, 0.0));
183:     let to_camera = normalize(view.world_position.xz - root_world.xz
184:         + vec2<f32>(0.0001, 0.0));
185:     var camera_side = vec2<f32>(-to_camera.y, to_camera.x);
186:     camera_side = select(camera_side, -camera_side, dot(camera_side, original_side) < 0.0);
187:     let edge_on = 1.0 - smoothstep(
188:         0.08,
189:         0.38,
190:         abs(dot(original_world_normal.xz, to_camera)),
191:     );
192:     let visible_side = normalize(mix(original_side, camera_side, edge_on * 0.88));
193:     let half_width = length(collapsed_position.xz - blade_root_local.xz)
194:         * side_scale
195:         * max(grass.params.w, 1.0);
196:     let signed_side = select(-1.0, 1.0, vertex.uv.x >= 0.5);
197:     let side_offset = visible_side * half_width * signed_side;
198:     let world_position = vec4<f32>(
199:         centre_world.x + curve_offset.x + side_offset.x,
200:         centre_world.y - interaction_droop * t * t * blade_visibility,
201:         centre_world.z + curve_offset.y + side_offset.y,
202:         centre_world.w,
203:     );
204: 
205:     let shaped_world_normal = normalize(cross(
206:         tangent,
207:         vec3<f32>(visible_side.x, 0.0, visible_side.y),
208:     ));
209: 
210:     out.world_position = world_position;
211:     out.clip_position = view.clip_from_world * world_position;
212:     // The legacy path biases blade normals toward the sky (shading.z = 0.76).
213:     out.world_normal = normalize(mix(
214:         shaped_world_normal,
215:         vec3<f32>(0.0, 1.0, 0.0),
216:         0.76,
217:     ));
218:     out.uv = vertex.uv;
219: #ifdef VERTEX_COLORS
220:     out.color = vec4<f32>(vertex.color.rgb, 1.0) * batch.color;
221: #else
222:     out.color = batch.color;
223: #endif
224:     out.i_batch_id = vertex.i_batch_id;
225: #ifdef VISIBILITY_RANGE_DITHER
226:     out.visibility_range_dither = utils::get_visibility_range_dither_level(
227:         batch.visibility_range,
228:         vec4<f32>(root_world, 1.0),
229:     );
230: #endif
231:     return out;
232: }
