199: pub(in crate::presentation) fn grass_lod_visibility(lod: GrassMeshLod) -> VisibilityRange {
200:     match lod {
201:         GrassMeshLod::Near => VisibilityRange {
202:             start_margin: 0.0..0.0,
203:             end_margin: NEAR_TO_FAR_SWARD_FADE_START_METRES..NEAR_TO_FAR_SWARD_FADE_END_METRES,
204:             use_aabb: false,
205:         },
206:         // Instanced-only sub-tier; the legacy patch renderer never spawns it,
207:         // so this band only informs the instanced fade-continuity invariant.
208:         // The near field hands off to the edge ring at 4..6 m and the ring
209:         // fades out into the far tier across the legacy near band's end.
210:         GrassMeshLod::NearEdge => VisibilityRange {
211:             start_margin: 4.0..6.0,
212:             end_margin: NEAR_TO_FAR_SWARD_FADE_START_METRES..NEAR_TO_FAR_SWARD_FADE_END_METRES,
213:             use_aabb: false,
214:         },
215:         GrassMeshLod::Far => VisibilityRange {
216:             start_margin: NEAR_TO_FAR_SWARD_FADE_START_METRES..NEAR_TO_FAR_SWARD_FADE_END_METRES,
217:             end_margin: 36.0..44.0,
218:             use_aabb: false,
219:         },
220:         GrassMeshLod::Vista => VisibilityRange {
221:             start_margin: 34.0..42.0,
222:             end_margin: TERMINAL_SWARD_FADE_START_METRES..TERMINAL_SWARD_FADE_END_METRES,
223:             use_aabb: false,
224:         },
225:     }
226: }
