228: /// Blade grid side of one instanced tuft, per LOD tier.
229: ///
230: /// Near tufts subdivide the legacy macro patch so the instanced sward
231: /// reproduces the legacy per-cell shoot density; the near-edge ring deliberately
232: /// thins that count past the countable-blade distance. Far and vista tufts cover
233: /// larger footprints with the legacy per-cell shoot totals.
234: pub(in crate::presentation) fn tuft_blade_side(lod: GrassMeshLod) -> usize {
235:     match lod {
236:         GrassMeshLod::Near => 8,
237:         GrassMeshLod::NearEdge => 6,
238:         GrassMeshLod::Far => 10,
239:         GrassMeshLod::Vista => 12,
240:     }
241: }
242: 
243: /// One instanced grass tuft: a small blade grid sharing the legacy blade,
244: /// pigment, and inflorescence construction so the instanced and patch renderers
245: /// stay visually comparable. Placement resolves one species per tuft with the
246: /// legacy community weights; `seed` decorrelates blade hashes between the shared
247: /// tuft meshes of different species. The tuft is built from the current
248: /// (#560) blade/ribbon geometry via `grass_ribbon_patch_mesh`.
249: pub(in crate::presentation) fn grass_tuft_mesh(
250:     color: Color,
251:     lod: GrassMeshLod,
252:     grass_density: f32,
253:     species: GrassSpecies,
254:     seed: Seed,
255:     grass: &GrassConfig,
256: ) -> Mesh {
257:     let grid_side = lod.configured_tier(grass).native_blades_per_tuft_side;
258:     let centre = (grid_side - 1) as f32 * 0.5;
259:     let blade_spacing = configured_tuft_footprint_metres(lod, grass) / grid_side as f32;
260:     let blades = (0..grid_side * grid_side)
261:         .filter(|index| {
262:             grass_density >= 1.0
263:                 || streams::DENSITY
264:                     .rng(seed, &[*index as u64])
265:                     .inclusive_unit_f32()
266:                     < grass_density
267:         })
268:         .map(|index| {
269:             let row = index / grid_side;
270:             let column = index % grid_side;
271:             let hash = streams::BLADE_PLACEMENT.seed(seed, &[index as u64]);
272:             let jitter_x = (streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5)
273:                 * blade_spacing
274:                 * 0.46;
275:             let jitter_z = (streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5)
276:                 * blade_spacing
277:                 * 0.46;
278:             let clump_vigor = 0.5 + 0.5 * (row as f32 * 0.31 + column as f32 * 0.17 + 0.8).sin();
279:             let height_scale = (0.50
280:                 + streams::HEIGHT.rng(hash, &[]).inclusive_unit_f32() * 0.62
281:                 + clump_vigor * 0.20)
282:                 .clamp(0.50, 1.30);
283:             let width_scale = 0.62 + streams::WIDTH.rng(hash, &[]).inclusive_unit_f32() * 0.76;
284:             GrassBlade {
285:                 offset_x: (column as f32 - centre) * blade_spacing + jitter_x,
286:                 offset_z: (row as f32 - centre) * blade_spacing + jitter_z,
287:                 height_scale,
288:                 width_scale,
289:                 seed: streams::BLADE.seed(seed, &[index as u64]),
290:                 species,
291:             }
292:         })
293:         .collect::<Vec<_>>();
294:     grass_ribbon_patch_mesh_with_rows(
295:         grass.blade.width_m * (0.026 / GRASS_BLADE_WIDTH_METRES),
296:         0.82,
297:         color,
298:         lod,
299:         &blades,
300:         &lod.configured_tier(grass).ribbon_rows,
301:     )
302: }
303: 
304: pub(in crate::presentation) fn configured_tuft_footprint_metres(
305:     lod: GrassMeshLod,
306:     grass: &GrassConfig,
307: ) -> f32 {
308:     let tier = lod.configured_tier(grass);
309:     let patch_spacing = if lod == GrassMeshLod::Vista {
310:         grass.placement.vista_patch_spacing_m
311:     } else {
312:         grass.placement.playable_patch_spacing_m
313:     };
314:     patch_spacing / tier.native_tufts_per_cell_side as f32
315: }
