118:         (meshes, mesh_instances, mesh_allocator): SystemParamItem<'w, '_, Self::Param>,
119:         pass: &mut TrackedRenderPass<'w>,
120:     ) -> RenderCommandResult {
121:         let mesh_allocator = mesh_allocator.into_inner();
122:         let Some(chunk) = chunk else {
