163: pub(super) fn prepare_chunk_buffers(
164:     mut commands: Commands,
165:     chunks: Query<(Entity, &InstanceChunk), Or<(Changed<InstanceChunk>, Without<ChunkGpu>)>>,
166:     band_layout: Res<ChunkBandLayout>,
167:     pipeline_cache: Res<PipelineCache>,
168:     render_device: Res<RenderDevice>,
169:     render_queue: Res<RenderQueue>,
170: ) {
171:     let layout = pipeline_cache.get_bind_group_layout(&band_layout.0);
172:     for (entity, chunk) in &chunks {
173:         let instance_count = u32::try_from(chunk.instances.len()).unwrap_or(u32::MAX);
174:         if instance_count == 0 {
175:             continue;
176:         }
177:         let instances = render_device.create_buffer_with_data(&BufferInitDescriptor {
178:             label: Some("chunk_instances"),
179:             contents: bytemuck::cast_slice(&chunk.instances),
180:             usage: BufferUsages::VERTEX,
181:         });
182:         let mut band = UniformBuffer::from(ChunkBandUniform {
183:             visibility_range: chunk.band.shader_range(),
184:         });
185:         band.write_buffer(&render_device, &render_queue);
186:         let Some(band_binding) = band.binding() else {
187:             continue;
188:         };
189:         let band = render_device.create_bind_group(
190:             "chunk_band_bind_group",
191:             &layout,
192:             &BindGroupEntries::single(band_binding),
193:         );
194:         commands.entity(entity).insert(ChunkGpu {
195:             instances,
196:             instance_count,
197:             band,
198:         });
199:     }
200: }
