53:     pub(in crate::presentation) fn new(fade_in: Range<f32>, fade_out: Range<f32>) -> Self {
54:         let fade_in = fade_in.start..fade_in.end.max(fade_in.start + Self::OPEN_START_METRES);
55:         Self { fade_in, fade_out }
