1: //! The material contract of chunk-instanced batches and its render-world
2: //! preparation into a bind group.
3: use bevy::{
4:     asset::AssetId,
5:     core_pipeline::core_3d::Opaque3d,
6:     ecs::system::{SystemParamItem, lifetimeless::SRes},
7:     mesh::MeshVertexBufferLayoutRef,
8:     prelude::*,
9:     render::{
10:         render_asset::{PrepareAssetError, RenderAsset},
11:         render_phase::{DrawFunctionId, DrawFunctions},
12:         render_resource::{
13:             AsBindGroup, AsBindGroupError, BindGroup, BindGroupEntry, PipelineCache,
14:             RenderPipelineDescriptor, SpecializedMeshPipelineError,
15:         },
16:         renderer::RenderDevice,
17:     },
18:     shader::ShaderRef,
19: };
