23: /// A material drawn by the chunk-instanced renderer. Its shader imports
24: /// `fablegeist::chunk_instancing`, binds the material at group 3, and
25: /// provides `vertex` and `fragment` entry points.
26: pub(in crate::presentation) trait ChunkInstancedMaterial:
27:     Asset + AsBindGroup<Data: Clone + Eq + std::hash::Hash> + Clone + Sized
28: {
29:     fn shader() -> ShaderRef;
30: 
31:     /// Adjusts the material's main-pass pipeline.
32:     fn specialize(
33:         _descriptor: &mut RenderPipelineDescriptor,
34:         _layout: &MeshVertexBufferLayoutRef,
35:         _key: Self::Data,
36:     ) -> Result<(), SpecializedMeshPipelineError> {
37:         Ok(())
38:     }
39: }
40: 
41: /// A material's bind group and the draw function that uses it.
42: pub(super) struct PreparedChunkMaterial<M: ChunkInstancedMaterial> {
43:     pub bind_group: BindGroup,
44:     pub key: M::Data,
45:     pub draw_main: DrawFunctionId,
46: }
47: 
48: impl<M: ChunkInstancedMaterial> RenderAsset for PreparedChunkMaterial<M> {
49:     type SourceAsset = M;
50:     type Param = (
51:         SRes<RenderDevice>,
52:         SRes<ChunkMaterialPipeline<M>>,
53:         SRes<PipelineCache>,
54:         <M as AsBindGroup>::Param,
55:         SRes<DrawFunctions<Opaque3d>>,
56:     );
57: 
58:     fn prepare_asset(
59:         material: Self::SourceAsset,
60:         _asset_id: AssetId<Self::SourceAsset>,
61:         (render_device, pipeline, pipeline_cache, material_param, draw_main): &mut SystemParamItem<
62:             Self::Param,
63:         >,
64:         _previous_asset: Option<&Self>,
65:     ) -> Result<Self, PrepareAssetError<Self::SourceAsset>> {
66:         let layout = pipeline_cache.get_bind_group_layout(&pipeline.material_layout);
67:         let unprepared =
68:             match material.unprepared_bind_group(&layout, render_device, material_param, false) {
69:                 Ok(unprepared) => unprepared,
70:                 Err(AsBindGroupError::RetryNextUpdate) => {
71:                     return Err(PrepareAssetError::RetryNextUpdate(material));
72:                 }
73:                 Err(error) => return Err(PrepareAssetError::AsBindGroupError(error)),
74:             };
75:         let entries = unprepared
76:             .bindings
77:             .iter()
78:             .map(|(binding, resource)| BindGroupEntry {
79:                 binding: *binding,
80:                 resource: resource.get_binding(),
81:             })
82:             .collect::<Vec<_>>();
83:         let Some(draw_main) = draw_main.read().get_id::<DrawChunkInstances<M>>() else {
84:             return Err(PrepareAssetError::RetryNextUpdate(material));
85:         };
86:         Ok(Self {
87:             bind_group: render_device.create_bind_group(
88:                 Some("chunk_instanced_material_bind_group"),
89:                 &layout,
90:                 &entries,
91:             ),
92:             key: material.bind_group_data(),
93:             draw_main,
94:         })
95:     }
96: }
