1: //! Main-pass pipelines of chunk-instanced materials.
2: //!
3: //! Each starts from Bevy's mesh pipeline, replaces bind group 2 with the
4: //! chunk band and bind group 3 with the material, and appends the
5: //! per-instance vertex stream. Chunks never cast shadows.
6: use std::{
7:     hash::{Hash, Hasher},
8:     marker::PhantomData,
9: };
10: 
11: use bevy::{
12:     mesh::{MeshVertexBufferLayoutRef, VertexBufferLayout},
13:     pbr::{MeshPipeline, MeshPipelineKey},
14:     prelude::*,
15:     render::{
16:         render_resource::{
17:             BindGroupLayoutDescriptor, RenderPipelineDescriptor, SpecializedMeshPipeline,
18:             SpecializedMeshPipelineError, VertexAttribute, VertexFormat, VertexStepMode,
19:         },
20:         renderer::RenderDevice,
21:     },
22: };
23: 
24: use super::{ChunkBandLayout, ChunkInstance, ChunkInstancedMaterial};
25: 
26: /// The pipeline key: the view and mesh key plus the material's own data.
27: pub(super) struct ChunkPipelineKey<M: ChunkInstancedMaterial> {
28:     pub mesh_key: MeshPipelineKey,
29:     pub material_key: M::Data,
30: }
31: 
32: /// Main-pass pipeline inputs of one material.
33: #[derive(Resource)]
34: pub(super) struct ChunkMaterialPipeline<M: ChunkInstancedMaterial> {
35:     mesh_pipeline: MeshPipeline,
36:     band_layout: BindGroupLayoutDescriptor,
37:     pub material_layout: BindGroupLayoutDescriptor,
38:     shader: Handle<Shader>,
39:     material: PhantomData<M>,
40: }
41: 
42: impl<M: ChunkInstancedMaterial> Clone for ChunkPipelineKey<M> {
43:     fn clone(&self) -> Self {
44:         Self {
45:             mesh_key: self.mesh_key,
46:             material_key: self.material_key.clone(),
47:         }
48:     }
49: }
50: 
51: impl<M: ChunkInstancedMaterial> PartialEq for ChunkPipelineKey<M> {
52:     fn eq(&self, other: &Self) -> bool {
53:         self.mesh_key == other.mesh_key && self.material_key == other.material_key
54:     }
55: }
56: 
57: impl<M: ChunkInstancedMaterial> Eq for ChunkPipelineKey<M> {}
58: 
59: impl<M: ChunkInstancedMaterial> Hash for ChunkPipelineKey<M> {
60:     fn hash<H: Hasher>(&self, state: &mut H) {
61:         self.mesh_key.hash(state);
62:         self.material_key.hash(state);
63:     }
64: }
65: 
66: impl<M: ChunkInstancedMaterial> SpecializedMeshPipeline for ChunkMaterialPipeline<M> {
67:     type Key = ChunkPipelineKey<M>;
68: 
69:     fn specialize(
70:         &self,
71:         key: Self::Key,
72:         layout: &MeshVertexBufferLayoutRef,
73:     ) -> Result<RenderPipelineDescriptor, SpecializedMeshPipelineError> {
74:         let mut descriptor = self.mesh_pipeline.specialize(key.mesh_key, layout)?;
75:         // Groups 0 and 1 stay Bevy's view layouts; the per-entity mesh
76:         // uniforms at group 2 give way to the chunk band.
77:         descriptor.layout.truncate(2);
78:         descriptor
79:             .layout
80:             .extend([self.band_layout.clone(), self.material_layout.clone()]);
81:         descriptor
82:             .vertex
83:             .shader_defs
84:             .push("VISIBILITY_RANGE_DITHER".into());
85:         descriptor.vertex.shader = self.shader.clone();
86:         if let Some(fragment) = descriptor.fragment.as_mut() {
87:             if let Some(Some(target)) = fragment.targets.first_mut() {
88:                 target.blend = None;
89:             }
90:             fragment.shader_defs.push("VISIBILITY_RANGE_DITHER".into());
91:             fragment.shader = self.shader.clone();
92:         }
93:         M::specialize(&mut descriptor, layout, key.material_key)?;
94:         descriptor.vertex.buffers.push(instance_buffer_layout());
95:         Ok(descriptor)
96:     }
97: }
98: 
99: impl<M: ChunkInstancedMaterial> FromWorld for ChunkMaterialPipeline<M> {
100:     fn from_world(world: &mut World) -> Self {
101:         let render_device = world.resource::<RenderDevice>();
102:         let material_layout = BindGroupLayoutDescriptor::new(
103:             format!(
104:                 "chunk_instanced_material_layout_{}",
105:                 std::any::type_name::<M>()
106:             ),
107:             &M::bind_group_layout_entries(render_device, false),
108:         );
109:         Self {
110:             mesh_pipeline: world.resource::<MeshPipeline>().clone(),
111:             band_layout: world.resource::<ChunkBandLayout>().0.clone(),
112:             material_layout,
113:             shader: material_shader::<M>(world),
114:             material: PhantomData,
115:         }
116:     }
117: }
118: 
119: fn material_shader<M: ChunkInstancedMaterial>(world: &World) -> Handle<Shader> {
120:     match M::shader() {
121:         bevy::shader::ShaderRef::Handle(handle) => handle,
122:         bevy::shader::ShaderRef::Path(path) => world.resource::<AssetServer>().load(path),
123:         bevy::shader::ShaderRef::Default => Handle::default(),
124:     }
125: }
126: 
127: /// The `@location(8..10)` instance stream of `chunk_instancing.wgsl`.
128: fn instance_buffer_layout() -> VertexBufferLayout {
129:     let rotation_offset = VertexFormat::Float32x4.size();
130:     let seed_offset = rotation_offset + VertexFormat::Float32.size();
131:     VertexBufferLayout {
132:         array_stride: size_of::<ChunkInstance>() as u64,
133:         step_mode: VertexStepMode::Instance,
134:         attributes: vec![
135:             VertexAttribute {
136:                 format: VertexFormat::Float32x4,
137:                 offset: 0,
138:                 shader_location: 8,
139:             },
140:             VertexAttribute {
141:                 format: VertexFormat::Float32,
142:                 offset: rotation_offset,
143:                 shader_location: 9,
144:             },
145:             VertexAttribute {
146:                 format: VertexFormat::Uint32,
147:                 offset: seed_offset,
148:                 shader_location: 10,
149:             },
150:         ],
151:     }
152: }
