1: //! Queues every chunk Bevy's CPU culling left visible into each camera's main
2: //! pass.
3: use std::{
4:     collections::{HashMap, HashSet},
5:     hash::{DefaultHasher, Hash, Hasher},
6:     marker::PhantomData,
7: };
8: 
9: use bevy::{
10:     core_pipeline::core_3d::{Opaque3d, Opaque3dBatchSetKey, Opaque3dBinKey},
11:     ecs::system::SystemParam,
12:     mesh::Mesh3d,
13:     pbr::{MeshPipelineKey, RenderMeshInstances, ViewKeyCache},
14:     prelude::*,
15:     render::{
16:         mesh::{
17:             RenderMesh,
18:             allocator::{MeshAllocator, MeshSlabs},
19:         },
20:         render_asset::RenderAssets,
21:         render_phase::{
22:             BinnedRenderPhase, BinnedRenderPhaseType, InputUniformIndex, ViewBinnedRenderPhases,
23:         },
24:         render_resource::{CachedRenderPipelineId, PipelineCache, SpecializedMeshPipelines},
25:         sync_world::MainEntity,
26:         view::{ExtractedView, RenderVisibleEntities, RetainedViewEntity},
27:     },
28: };
