1: //! Splits a batch's instances into ground chunks and spawns one culled entity
2: //! per chunk.
3: use std::{collections::BTreeMap, sync::Arc};
4: 
5: use bevy::{
6:     camera::{
7:         primitives::Aabb,
8:         visibility::{NoAutoAabb, VisibilityRange},
9:     },
10:     light::NotShadowCaster,
11:     prelude::*,
12: };
13: 
14: use super::{ChunkInstance, ChunkInstancedMaterial, ChunkMaterial, FadeBand, InstanceChunk};
15: 
16: /// Every instance of one mesh and material within one distance band.
17: pub(in crate::presentation) struct InstanceBatch<M: ChunkInstancedMaterial> {
18:     pub mesh: Handle<Mesh>,
19:     pub material: Handle<M>,
20:     pub instances: Vec<ChunkInstance>,
21:     pub band: FadeBand,
22:     pub reach: InstanceReach,
23:     pub chunk_size: ChunkSize,
24: }
25: 
26: /// How far a unit-scale instance's geometry extends from its root, in
27: /// metres. Bounds scale with the largest instance in each chunk.
28: #[derive(Clone, Copy, Debug)]
29: pub(in crate::presentation) struct InstanceReach {
30:     pub horizontal: f32,
31:     pub above: f32,
32:     pub below: f32,
33: }
34: 
35: /// The edge of the square ground cell one chunk entity covers, in metres.
36: /// Larger cells mean fewer entities to cull; smaller cells cull tighter.
37: #[derive(Clone, Copy, Debug)]
38: pub(in crate::presentation) struct ChunkSize(pub f32);
39: 
40: /// The instances of one ground cell.
41: struct Cell {
42:     instances: Vec<ChunkInstance>,
43: }
44: 
45: impl<M: ChunkInstancedMaterial> InstanceBatch<M> {
46:     /// Spawns one entity per occupied ground cell. `components` adds the
47:     /// caller's markers to each chunk, given that chunk's instances.
48:     pub(in crate::presentation) fn spawn<B: Bundle>(
49:         self,
50:         commands: &mut Commands,
51:         mut components: impl FnMut(&[ChunkInstance]) -> B,
52:     ) {
53:         let Self {
54:             mesh,
55:             material,
56:             instances,
57:             band,
58:             reach,
59:             chunk_size,
60:         } = self;
61:         let mut cells = BTreeMap::<(i32, i32), Cell>::new();
62:         for instance in instances {
63:             let key = (
64:                 (instance.position.x / chunk_size.0).floor() as i32,
65:                 (instance.position.z / chunk_size.0).floor() as i32,
66:             );
67:             cells
68:                 .entry(key)
69:                 .or_insert_with(|| Cell {
70:                     instances: Vec::new(),
71:                 })
72:                 .instances
73:                 .push(instance);
74:         }
75:         for cell in cells.into_values() {
76:             let bounds = cell.bounds(reach);
77:             let centre = Vec3::from(bounds.center);
78:             // Bevy measures the range from the entity's translation, so pad
79:             // the band by the chunk's half-diagonal: no instance inside the
80:             // band is culled with its chunk. Each instance dithers its own fade.
81:             let pad = Vec3::from(bounds.half_extents).length();
82:             let start = (band.fade_in().start - pad).max(0.0);
83:             let end = band.fade_out().end + pad;
84:             let extra = components(&cell.instances);
85:             commands.spawn((
86:                 Mesh3d(mesh.clone()),
87:                 ChunkMaterial(material.clone()),
88:                 InstanceChunk {
89:                     instances: Arc::from(cell.instances),
90:                     band: band.clone(),
91:                 },
92:                 Transform::from_translation(centre),
93:                 Visibility::Inherited,
94:                 Aabb {
95:                     center: Vec3::ZERO.into(),
96:                     half_extents: bounds.half_extents,
97:                 },
98:                 // Bevy otherwise replaces the chunk bounds with the mesh's.
99:                 NoAutoAabb,
100:                 VisibilityRange {
101:                     start_margin: start..start,
102:                     end_margin: end..end,
103:                     use_aabb: false,
104:                 },
105:                 NotShadowCaster,
106:                 extra,
107:             ));
108:         }
109:     }
110: }
111: 
112: impl Cell {
113:     fn bounds(&self, reach: InstanceReach) -> Aabb {
114:         let mut minimum = Vec3::splat(f32::INFINITY);
115:         let mut maximum = Vec3::splat(f32::NEG_INFINITY);
116:         let mut largest_scale = 1.0_f32;
117:         for instance in &self.instances {
118:             minimum = minimum.min(instance.position);
119:             maximum = maximum.max(instance.position);
120:             largest_scale = largest_scale.max(instance.scale);
121:         }
122:         let horizontal = reach.horizontal * largest_scale;
123:         let minimum = minimum - Vec3::new(horizontal, reach.below * largest_scale, horizontal);
124:         let maximum = maximum + Vec3::new(horizontal, reach.above * largest_scale, horizontal);
125:         Aabb::from_min_max(minimum, maximum)
126:     }
127: }

