1: // Preserve retained instance buffers; reject individual animated tufts on GPU.
2: #import bevy_eidolon::cull::bindings::{source_buffer, instance_buffer, indirect_args, batch_offsets, instance_uniforms, camera}
3: 
4: // Reset in command order before each camera, preserving geometry draw fields.
5: @compute @workgroup_size(64)
6: fn reset(@builtin(global_invocation_id) id: vec3<u32>) {
7:     if id.x < arrayLength(&indirect_args) {
8:         atomicStore(&indirect_args[id.x].instance_count, 0u);
9:     }
10: }
11: 
12: @compute @workgroup_size(64)
13: fn main(@builtin(global_invocation_id) id: vec3<u32>) {
14:     let index = id.x + id.y * 65535u * 64u;
15:     if index >= arrayLength(&source_buffer) { return; }
16:     let instance = source_buffer[index];
17:     let batch_id = instance.batch_id;
18:     if batch_id == 0xffffffffu || batch_id >= arrayLength(&indirect_args) { return; }
19:     let batch = instance_uniforms[batch_id];
20:     let position = batch.world_from_local * vec4(instance.pos_and_scale.xyz, 1.0);
21:     let distance_to_view = distance(position.xyz, camera.view_pos.xyz);
22:     if distance_to_view < batch.visibility_range.x || distance_to_view > batch.visibility_range.w { return; }
23: 
24:     // Frobenius norm conservatively bounds arbitrary linear transforms. The
25:     // minimum of one also covers world-space wind/player displacement when
26:     // instances shrink. RGB is tint; the custom grass batch alpha is radius.
27:     let transform_scale = sqrt(dot(batch.world_from_local[0].xyz, batch.world_from_local[0].xyz)
28:         + dot(batch.world_from_local[1].xyz, batch.world_from_local[1].xyz)
29:         + dot(batch.world_from_local[2].xyz, batch.world_from_local[2].xyz));
30:     let radius = batch.color.a * max(1.0, abs(instance.pos_and_scale.w) * transform_scale);
31:     for (var plane_index = 0u; plane_index < 6u; plane_index++) {
32:         let plane = camera.frustum[plane_index];
33:         if dot(plane, position) < -radius * length(plane.xyz) { return; }
34:     }
35:     let offset = atomicAdd(&indirect_args[batch_id].instance_count, 1u);
36:     instance_buffer[batch_offsets[batch_id].start_index + offset] = instance;
37: }
