1: diagnostic(off, derivative_uniformity);
2: 
3: #import bevy_pbr::{
4:     forward_io::{Vertex, VertexOutput},
5:     mesh_functions,
6:     mesh_view_bindings::view,
7:     pbr_functions,
8:     view_transformations::position_world_to_clip,
9: }
10: 
11: struct TacticalPebbleBillboardMaterial {
12:     color: vec4<f32>,
13:     lighting: vec4<f32>,
14:     ambient: vec4<f32>,
15: }
16: 
17: @group(#{MATERIAL_BIND_GROUP}) @binding(0)
18: var<uniform> pebble: TacticalPebbleBillboardMaterial;
19: 
20: @vertex
21: fn vertex(vertex: Vertex) -> VertexOutput {
22:     var out: VertexOutput;
23:     let world_from_local = mesh_functions::get_world_from_local(vertex.instance_index);
24:     // Distant patch meshes store each pebble centre in the unused normal
25:     // channel. Positions are quad offsets, allowing a whole patch to remain
26:     // one draw while every member independently faces the camera.
27:     let centre_world = mesh_functions::mesh_position_local_to_world(
28:         world_from_local,
29:         vec4<f32>(vertex.normal, 1.0),
30:     ).xyz;
31:     let to_camera = normalize(view.world_position.xz - centre_world.xz + vec2<f32>(0.0001, 0.0));
32:     let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
33:     let world_position = vec4<f32>(
34:         centre_world + right * vertex.position.x + vec3<f32>(0.0, vertex.position.y, 0.0),
35:         1.0,
36:     );
37: 
38:     out.world_position = world_position;
39:     out.position = position_world_to_clip(world_position.xyz);
40:     out.world_normal = normalize(vec3<f32>(to_camera.x, 0.35, to_camera.y));
41:     out.uv = vertex.uv;
42: #ifdef VERTEX_OUTPUT_INSTANCE_INDEX
43:     out.instance_index = vertex.instance_index;
44: #endif
45: #ifdef VISIBILITY_RANGE_DITHER
46:     out.visibility_range_dither = mesh_functions::get_visibility_range_dither_level(
47:         vertex.instance_index,
48:         world_from_local[3],
49:     );
50: #endif
51:     return out;
52: }
53: 
54: fn interleaved_gradient_noise(pixel: vec2<f32>) -> f32 {
55:     return fract(52.9829189 * fract(dot(pixel, vec2<f32>(0.06711056, 0.00583715))));
56: }
57: 
58: @fragment
59: fn fragment(in: VertexOutput) -> @location(0) vec4<f32> {
60: #ifdef VISIBILITY_RANGE_DITHER
61:     pbr_functions::visibility_range_dither(in.position, in.visibility_range_dither);
62: #endif
63:     let shape = in.uv * 2.0 - vec2<f32>(1.0);
64:     let radius_squared = dot(shape, shape);
65:     let edge_width = max(fwidth(radius_squared), 0.001);
66:     let silhouette = 1.0 - smoothstep(1.0 - edge_width, 1.0 + edge_width, radius_squared);
67: 
68:     // UV derivatives provide the quad's actual rasterized diameter, so each
69:     // physical size fades independently instead of sharing a world-distance
70:     // cutoff. The last stochastic samples disappear at roughly one pixel.
71:     let uv_per_pixel = max(length(dpdx(in.uv)), length(dpdy(in.uv)));
72:     let diameter_pixels = 1.0 / max(uv_per_pixel, 0.00001);
73:     let screen_coverage = smoothstep(0.75, 1.5, diameter_pixels);
74:     let coverage = silhouette * screen_coverage;
75:     if interleaved_gradient_noise(floor(in.position.xy)) > coverage {
76:         discard;
77:     }
78: 
79:     // Reconstruct a broad world-space pebble normal from the camera-facing
80:     // basis. Albedo remains the one uniform molded-stone colour shared with
81:     // the mesh LODs; only lighting creates variation across the sprite.
82:     let to_camera = normalize(view.world_position.xz - in.world_position.xz + vec2<f32>(0.0001, 0.0));
83:     let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
84:     let facing = vec3<f32>(to_camera.x, 0.0, to_camera.y);
85:     let surface_normal = normalize(
86:         right * shape.x
87:         + vec3<f32>(0.0, shape.y, 0.0)
88:         + facing * sqrt(max(1.0 - radius_squared, 0.0)),
89:     );
90:     let direct = max(dot(surface_normal, normalize(pebble.lighting.xyz)), 0.0)
91:         * pebble.lighting.w
92:         * (1.0 - pebble.ambient.w);
93:     let irradiance = pebble.ambient.rgb * pebble.ambient.w + vec3<f32>(direct);
94:     return vec4<f32>(pebble.color.rgb * irradiance, 1.0);
95: }
