1: // Chunk-instanced distant loose-stone billboards.
2: //
3: // A port of `tactical_pebble_billboard.wgsl` onto the chunk instance buffer.
4: // The patch mesh still stores each pebble's centre in the unused normal channel
5: // and its positions as quad offsets, so every member of a patch faces the camera
6: // independently; the only change is that the patch's world matrix now comes
7: // from the instance buffer rather than a per-entity mesh uniform.
8: 
9: // `fwidth`/`dpdx` appear inside branches below, which browser WebGPU rejects
10: // under uniformity analysis unless the diagnostic is disabled here.
11: diagnostic(off, derivative_uniformity);
12: 
13: #import bevy_pbr::{
14:     mesh_view_bindings::view,
15:     view_transformations::position_world_to_clip,
16: }
17: 
18: #import fablegeist::chunk_instancing::{
19:     Vertex, chunk_band, instance_world_matrix, visibility_range_dither_level,
20: }
21: 
22: struct TacticalPebbleBillboardInstancedMaterial {
23:     color: vec4<f32>,
24:     lighting: vec4<f32>,
25:     ambient: vec4<f32>,
26: }
27: 
28: @group(3) @binding(0) var<uniform> pebble: TacticalPebbleBillboardInstancedMaterial;
29: 
30: struct BillboardVertexOutput {
31:     @builtin(position) clip_position: vec4<f32>,
32: #ifdef VISIBILITY_RANGE_DITHER
33:     @location(0) @interpolate(flat) visibility_range_dither: i32,
34: #endif
35:     @location(1) world_position: vec4<f32>,
36:     @location(2) uv: vec2<f32>,
37: }
38: 
39: @vertex
40: fn vertex(vertex: Vertex) -> BillboardVertexOutput {
41:     var out: BillboardVertexOutput;
42:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
43: 
44:     var centre_local = vec3<f32>(0.0, 0.0, 0.0);
45: #ifdef VERTEX_NORMALS
46:     centre_local = vertex.normal;
47: #endif
48:     let centre_world = (instance_matrix * vec4<f32>(centre_local, 1.0)).xyz;
49:     let to_camera = normalize(view.world_position.xz - centre_world.xz + vec2<f32>(0.0001, 0.0));
50:     let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
51:     // Quad offsets are authored in patch-local metres, so the instance's
52:     // uniform scale has to reach them even though they bypass the matrix.
53:     let quad_scale = vertex.i_pos_scale.w;
54:     let world_position = vec4<f32>(
55:         centre_world
56:             + right * (vertex.position.x * quad_scale)
57:             + vec3<f32>(0.0, vertex.position.y * quad_scale, 0.0),
58:         1.0,
59:     );
60: 
61:     out.world_position = world_position;
62:     out.clip_position = position_world_to_clip(world_position.xyz);
63: #ifdef VERTEX_UVS_A
64:     out.uv = vertex.uv;
65: #else
66:     out.uv = vec2<f32>(0.5, 0.5);
67: #endif
68: 
69: #ifdef VISIBILITY_RANGE_DITHER
70:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
71:     out.visibility_range_dither =
72:         visibility_range_dither_level(chunk_band.visibility_range, instance_origin.xyz);
73: #endif
74:     return out;
75: }
76: 
77: fn interleaved_gradient_noise(pixel: vec2<f32>) -> f32 {
78:     return fract(52.9829189 * fract(dot(pixel, vec2<f32>(0.06711056, 0.00583715))));
79: }
80: 
81: @fragment
82: fn fragment(in: BillboardVertexOutput) -> @location(0) vec4<f32> {
83: #ifdef VISIBILITY_RANGE_DITHER
84:     if in.visibility_range_dither != 0 {
85:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
86:         let pixel_hash = interleaved_gradient_noise(floor(in.clip_position.xy));
87:         if in.visibility_range_dither > 0 {
88:             if pixel_hash < magnitude {
89:                 discard;
90:             }
91:         } else if pixel_hash >= 1.0 - magnitude {
92:             discard;
93:         }
94:     }
95: #endif
96:     let shape = in.uv * 2.0 - vec2<f32>(1.0);
97:     let radius_squared = dot(shape, shape);
98:     let edge_width = max(fwidth(radius_squared), 0.001);
99:     let silhouette = 1.0 - smoothstep(1.0 - edge_width, 1.0 + edge_width, radius_squared);
100: 
101:     // UV derivatives give the quad's rasterized diameter, so each physical size
102:     // fades independently instead of sharing a world-distance cutoff.
103:     let uv_per_pixel = max(length(dpdx(in.uv)), length(dpdy(in.uv)));
104:     let diameter_pixels = 1.0 / max(uv_per_pixel, 0.00001);
105:     let screen_coverage = smoothstep(0.75, 1.5, diameter_pixels);
106:     let coverage = silhouette * screen_coverage;
107:     if interleaved_gradient_noise(floor(in.clip_position.xy)) > coverage {
108:         discard;
109:     }
110: 
111:     let to_camera = normalize(view.world_position.xz - in.world_position.xz + vec2<f32>(0.0001, 0.0));
112:     let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
113:     let facing = vec3<f32>(to_camera.x, 0.0, to_camera.y);
114:     let surface_normal = normalize(
115:         right * shape.x
116:         + vec3<f32>(0.0, shape.y, 0.0)
117:         + facing * sqrt(max(1.0 - radius_squared, 0.0)),
118:     );
119:     let direct = max(dot(surface_normal, normalize(pebble.lighting.xyz)), 0.0)
120:         * pebble.lighting.w
121:         * (1.0 - pebble.ambient.w);
122:     let irradiance = pebble.ambient.rgb * pebble.ambient.w + vec3<f32>(direct);
123:     return vec4<f32>(pebble.color.rgb * irradiance, 1.0);
124: }
33714256b6313ce86fdfbb534c54d92d024d7726 assets/shaders/tactical_pebble_instanced.wgsl
1: // Chunk-instanced loose-stone pebble patches (hero and near LODs).
2: //
3: // Shading is a straight port of `tactical_pebble.wgsl`: flat ambient plus a
4: // Lambert term with one clamped cascade fetch, normalised the same way, so the
5: // instanced path is pixel-equivalent on the lit face. Only the vertex stage
6: // differs - the world matrix comes from the chunk's instance buffer rather than
7: // from a per-entity mesh uniform, and the LOD hand-off dithers each instance
8: // against the chunk's band instead of Bevy's per-entity range table.
9: 
10: #import bevy_pbr::{
11:     mesh_view_bindings::{lights, view},
12:     shadows,
13:     view_transformations::position_world_to_clip,
14: }
15: 
16: #import fablegeist::chunk_instancing::{
17:     Vertex, chunk_band, instance_world_matrix, visibility_range_dither_level,
18: }
19: 
20: // Linear albedo in rgb, flat-ambient scale in w.
21: @group(3) @binding(0) var<uniform> surface: vec4<f32>;
22: 
23: struct PebbleVertexOutput {
24:     @builtin(position) clip_position: vec4<f32>,
25: #ifdef VISIBILITY_RANGE_DITHER
26:     @location(0) @interpolate(flat) visibility_range_dither: i32,
27: #endif
28:     @location(1) world_position: vec4<f32>,
29:     @location(2) world_normal: vec3<f32>,
30: }
31: 
32: @vertex
33: fn vertex(vertex: Vertex) -> PebbleVertexOutput {
34:     var out: PebbleVertexOutput;
35:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
36:     let world_position = instance_matrix * vec4<f32>(vertex.position, 1.0);
37:     out.world_position = world_position;
38:     out.clip_position = position_world_to_clip(world_position.xyz);
39: 
40:     var normal = vec3<f32>(0.0, 1.0, 0.0);
41: #ifdef VERTEX_NORMALS
42:     normal = vertex.normal;
43: #endif
44:     // Yaw-only instance rotation; uniform scale leaves the direction intact.
45:     let rotation_cos = cos(vertex.i_rotation);
46:     let rotation_sin = sin(vertex.i_rotation);
47:     out.world_normal = normalize(vec3<f32>(
48:         rotation_cos * normal.x + rotation_sin * normal.z,
49:         normal.y,
50:         -rotation_sin * normal.x + rotation_cos * normal.z,
51:     ));
52: 
53: #ifdef VISIBILITY_RANGE_DITHER
54:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
55:     out.visibility_range_dither =
56:         visibility_range_dither_level(chunk_band.visibility_range, instance_origin.xyz);
57: #endif
58:     return out;
59: }
60: 
61: @fragment
62: fn fragment(
63:     in: PebbleVertexOutput,
64:     @builtin(front_facing) is_front: bool,
65: ) -> @location(0) vec4<f32> {
66: #ifdef VISIBILITY_RANGE_DITHER
67:     // Complementary per-pixel partition; see tactical_grass_instanced.wgsl.
68:     if in.visibility_range_dither != 0 {
69:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
70:         let pixel_hash = fract(
71:             52.9829189
72:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
73:         );
74:         if in.visibility_range_dither > 0 {
75:             if pixel_hash < magnitude {
76:                 discard;
77:             }
78:         } else if pixel_hash >= 1.0 - magnitude {
79:             discard;
80:         }
81:     }
82: #endif
83:     let normal = normalize(select(-in.world_normal, in.world_normal, is_front));
84:     let albedo = surface.rgb;
85: 
86:     var lit = albedo * lights.ambient_color.rgb * surface.w;
87:     let view_z = dot(vec4<f32>(
88:         view.view_from_world[0].z,
89:         view.view_from_world[1].z,
90:         view.view_from_world[2].z,
91:         view.view_from_world[3].z,
92:     ), in.world_position);
93:     for (var light_index = 0u; light_index < lights.n_directional_lights; light_index += 1u) {
94:         let light = lights.directional_lights[light_index];
95:         let n_dot_l = saturate(dot(normal, light.direction_to_light));
96:         let shadow = clamp(
97:             shadows::fetch_directional_shadow(
98:                 light_index,
99:                 in.world_position,
100:                 normal,
101:                 view_z,
102:                 in.clip_position.xy,
103:             ),
104:             0.12,
105:             1.0,
106:         );
107:         lit += albedo * light.color.rgb * (n_dot_l * shadow * 0.3183099);
108:     }
109: 
110:     return vec4<f32>(lit * view.exposure, 1.0);
111: }

