32:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
33:     let world_position = instance_matrix * vec4<f32>(vertex.position, 1.0);
34:     out.world_position = world_position;
35:     out.clip_position = position_world_to_clip(world_position.xyz);
36: 
37:     var normal = vec3<f32>(0.0, 1.0, 0.0);
38: #ifdef VERTEX_NORMALS
39:     normal = vertex.normal;
40: #endif
41:     // Yaw-only instance rotation; uniform scale leaves direction unchanged.
42:     let rotation_cos = cos(vertex.i_rotation);
43:     let rotation_sin = sin(vertex.i_rotation);
44:     out.world_normal = normalize(vec3<f32>(
45:         rotation_cos * normal.x + rotation_sin * normal.z,
46:         normal.y,
47:         -rotation_sin * normal.x + rotation_cos * normal.z,
48:     ));
49: 
50: #ifdef VISIBILITY_RANGE_DITHER
51:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
52:     out.visibility_range_dither =
53:         visibility_range_dither_level(chunk_band.visibility_range, instance_origin.xyz);
54: #endif
