58: @fragment
59: fn fragment(
60:     in: ShrubVertexOutput,
61:     @builtin(front_facing) is_front: bool,
62: ) -> @location(0) vec4<f32> {
63: #ifdef VISIBILITY_RANGE_DITHER
64:     // Complementary per-pixel partition; see tactical_grass_instanced.wgsl.
65:     if in.visibility_range_dither != 0 {
66:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
67:         let pixel_hash = fract(
68:             52.9829189
69:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
70:         );
71:         if in.visibility_range_dither > 0 {
72:             if pixel_hash < magnitude {
73:                 discard;
74:             }
75:         } else if pixel_hash >= 1.0 - magnitude {
76:             discard;
77:         }
78:     }
79: #endif
80:     let normal = normalize(select(-in.world_normal, in.world_normal, is_front));
81:     // The wood mesh packs metric root height into the vertex-colour lane (see
82:     // wood_mesh.rs) - the tree bark shader decodes it as a soil-deposition
83:     // mask, it is NOT pigment. Its red channel carries height above the
84:     // tree-scale root plane (~8-10 m), so multiplying it into the bark colour
85:     // scaled the red channel past one and blew the wood out to coral. The
86:     // shrub fast path uses the flat bark pigment directly.
