101:             shadows::fetch_directional_shadow(
102:                 light_index,
103:                 in.world_position,
104:                 normal,
105:                 view_z,
106:                 in.clip_position.xy,
107:             ),
108:             0.12,
109:             1.0,
110:         );
111:         lit += albedo * light.color.rgb * (alignment * shadow * 0.3183099);
112:     }
