51:         normal.y,
52:         -rotation_sin * normal.x + rotation_cos * normal.z,
53:     ));
54: 
55: #ifdef VISIBILITY_RANGE_DITHER
56:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
57:     out.visibility_range_dither =
58:         utils::get_visibility_range_dither_level(batch.visibility_range, instance_origin);
59: #endif
60:     return out;
61: }
62: 
63: @fragment
64: fn fragment(
65:     in: ShrubVertexOutput,
66:     @builtin(front_facing) is_front: bool,
67: ) -> @location(0) vec4<f32> {
68: #ifdef VISIBILITY_RANGE_DITHER
69:     // Complementary per-pixel partition; see tactical_grass_instanced.wgsl.
70:     if in.visibility_range_dither != 0 {
71:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
72:         let pixel_hash = fract(
73:             52.9829189
74:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
75:         );
76:         if in.visibility_range_dither > 0 {
77:             if pixel_hash < magnitude {
78:                 discard;
79:             }
80:         } else if pixel_hash >= 1.0 - magnitude {
81:             discard;
82:         }
83:     }
84: #endif
85:     let normal = normalize(select(-in.world_normal, in.world_normal, is_front));
86:     // The wood mesh packs metric root height into the vertex-colour lane (see
87:     // wood_mesh.rs) - the tree bark shader decodes it as a soil-deposition
88:     // mask, it is NOT pigment. Its red channel carries height above the
89:     // tree-scale root plane (~8-10 m), so multiplying it into the bark colour
90:     // scaled the red channel past one and blew the wood out to coral. The
91:     // shrub fast path uses the flat bark pigment directly.
92:     let albedo = bark_color.rgb;
93:     var lit = albedo * lights.ambient_color.rgb;
94:     let view_z = dot(vec4<f32>(
95:         view.view_from_world[0].z,
96:         view.view_from_world[1].z,
97:         view.view_from_world[2].z,
98:         view.view_from_world[3].z,
99:     ), in.world_position);
100:     for (var light_index = 0u; light_index < lights.n_directional_lights;
101:         light_index += 1u)
102:     {
103:         let light = lights.directional_lights[light_index];
104:         let alignment = saturate(dot(normal, light.direction_to_light));
105:         let shadow = clamp(
106:             shadows::fetch_directional_shadow(
107:                 light_index,
108:                 in.world_position,
109:                 normal,
110:                 view_z,
111:                 in.clip_position.xy,
112:             ),
113:             0.12,
114:             1.0,
115:         );
116:         lit += albedo * light.color.rgb * (alignment * shadow * 0.3183099);
117:     }
118:     return vec4<f32>(lit * view.exposure, 1.0);
119: }
e2755a732c84e67296b5e3441a4259a84f461b2f assets/shaders/tactical_shrub_leaf_instanced.wgsl
1: // Instanced shrub foliage: the texture set and calibration of
2: // `tactical_tree_leaf_card.wgsl` on eidolon's instanced vertex path. Every
3: // representation - cambered near leaves and distant alpha cards alike - shades
4: // with the fast foliage model; the former full-PBR cambered path was pure
5: // per-fragment cost. The front/back normal maps are now unused (kept bound for
6: // now; a follow-up can drop bindings 6-9 from the material).
7: 
8: diagnostic(off, derivative_uniformity);
9: 
10: #import bevy_pbr::{
11:     mesh_view_bindings::{globals, lights, view},
12:     shadows,
13:     view_transformations::position_world_to_clip,
14: }
15: 
16: #import bevy_eidolon::render::utils
17: #import bevy_eidolon::render::bindings::instance_uniforms
18: #import bevy_eidolon::render::io_types::Vertex
19: 
20: @group(3) @binding(0) var leaf_opacity: texture_2d<f32>;
21: @group(3) @binding(1) var leaf_opacity_sampler: sampler;
22: @group(3) @binding(2) var front_albedo: texture_2d<f32>;
23: @group(3) @binding(3) var front_albedo_sampler: sampler;
24: @group(3) @binding(4) var back_albedo: texture_2d<f32>;
25: @group(3) @binding(5) var back_albedo_sampler: sampler;
26: @group(3) @binding(6) var front_normal: texture_2d<f32>;
27: @group(3) @binding(7) var front_normal_sampler: sampler;
28: @group(3) @binding(8) var back_normal: texture_2d<f32>;
29: @group(3) @binding(9) var back_normal_sampler: sampler;
30: @group(3) @binding(10) var leaf_arm: texture_2d<f32>;
31: @group(3) @binding(11) var leaf_arm_sampler: sampler;
32: 
33: struct TacticalShrubLeafInstancedUniform {
34:     // Wind direction XZ, strength; w reserved (phase comes from globals).
35:     parameters: vec4<f32>,
36:     // Opacity cutoff, normal strength, canopy AO strength, transmission.
37:     surface_parameters: vec4<f32>,
38:     // Roughness fallback, thickness, litter pigment lane, reserved.
39:     physical_parameters: vec4<f32>,
40:     // y scales the flat ambient term; every representation now shades fast.
41:     shading: vec4<f32>,
42: }
43: 
44: @group(3) @binding(12) var<uniform> leaf: TacticalShrubLeafInstancedUniform;
45: 
46: struct ShrubLeafVertexOutput {
47:     @builtin(position) clip_position: vec4<f32>,
48: #ifdef VISIBILITY_RANGE_DITHER
49:     @location(0) @interpolate(flat) visibility_range_dither: i32,
50: #endif
51:     @location(1) world_position: vec4<f32>,
52:     @location(2) world_normal: vec3<f32>,
53:     @location(3) uv: vec2<f32>,
54:     @location(4) color: vec4<f32>,
55: }
56: 
57: @vertex
58: fn vertex(vertex: Vertex) -> ShrubLeafVertexOutput {
59:     var out: ShrubLeafVertexOutput;
60:     let batch = instance_uniforms[vertex.i_batch_id];
61:     let instance_matrix = utils::calc_instance_world_matrix(
62:         vertex.i_pos_scale,
63:         vertex.i_rotation,
64:         batch.world_from_local,
65:     );
66:     var world_position = instance_matrix * vec4<f32>(vertex.position, 1.0);
67: 
68:     var uv = vec2<f32>(0.0);
69: #ifdef VERTEX_UVS_A
70:     uv = vertex.uv;
71: #endif
72:     // Same sway as the tree leaf-card shader, driven by the shader clock.
73:     let bend = smoothstep(0.03, 1.0, 1.0 - uv.y);
74:     let wind_direction = normalize(leaf.parameters.xy);
75:     let wind_cross = vec2<f32>(-wind_direction.y, wind_direction.x);
76:     let position_phase = dot(world_position.xz, wind_direction) * 0.31
77:         + world_position.y * 0.17;
78:     let time = globals.time * 1.15;
79:     let gust = 0.7 + 0.3 * sin(time * 0.37 + position_phase * 0.63);
80:     let primary = sin(time + position_phase);
81:     let flutter = sin(time * 3.11 - position_phase * 1.73);
82:     let displacement = (
83:         wind_direction * primary * gust + wind_cross * flutter * 0.22
84:     ) * leaf.parameters.z * bend * bend;
85:     world_position.x += displacement.x;
86:     world_position.z += displacement.y;
87:     world_position.y -= length(displacement) * 0.16 * bend;
88: 
89:     out.world_position = world_position;
90:     out.clip_position = position_world_to_clip(world_position.xyz);
91:     out.uv = uv;
92: 
93:     var normal = vec3<f32>(0.0, 1.0, 0.0);
94: #ifdef VERTEX_NORMALS
95:     normal = vertex.normal;
96: #endif
97:     let rotation_cos = cos(vertex.i_rotation);
98:     let rotation_sin = sin(vertex.i_rotation);
99:     var world_normal = normalize(vec3<f32>(
100:         rotation_cos * normal.x + rotation_sin * normal.z,
101:         normal.y,
102:         -rotation_sin * normal.x + rotation_cos * normal.z,
103:     ));
104:     let normal_bend = smoothstep(0.03, 1.0, 1.0 - uv.y);
105:     out.world_normal = normalize(world_normal + vec3<f32>(0.0, 0.16 * normal_bend, 0.0));
106: 
107:     out.color = vec4<f32>(1.0);
108: #ifdef VERTEX_COLORS
109:     out.color = vertex.color;
110: #endif
111: 
112: #ifdef VISIBILITY_RANGE_DITHER
113:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
114:     out.visibility_range_dither =
115:         utils::get_visibility_range_dither_level(batch.visibility_range, instance_origin);
116: #endif
117:     return out;
118: }
119: 
120: @fragment
121: fn fragment(
122:     in: ShrubLeafVertexOutput,
123:     @builtin(front_facing) is_front: bool,
124: ) -> @location(0) vec4<f32> {
125: #ifdef VISIBILITY_RANGE_DITHER
126:     // Complementary per-pixel partition between the cambered and card
127:     // representations; see tactical_grass_instanced.wgsl for the rationale.
128:     if in.visibility_range_dither != 0 {
129:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
130:         let pixel_hash = fract(
131:             52.9829189
132:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
133:         );
134:         if in.visibility_range_dither > 0 {
135:             if pixel_hash < magnitude {
136:                 discard;
137:             }
138:         } else if pixel_hash >= 1.0 - magnitude {
139:             discard;
140:         }
141:     }
142: #endif
143:     let opacity = textureSample(leaf_opacity, leaf_opacity_sampler, in.uv).r;
144:     if opacity < leaf.surface_parameters.x {
145:         discard;
146:     }
147: 
148:     let uv_dx = dpdx(in.uv);
149:     let uv_dy = dpdy(in.uv);
150:     var albedo = textureSample(front_albedo, front_albedo_sampler, in.uv).rgb;
151:     if !is_front {
152:         // Face selection can diverge within a fragment quad on WebGPU.
153:         albedo = textureSampleGrad(back_albedo, back_albedo_sampler, in.uv, uv_dx, uv_dy).rgb;
154:     }
155:     // Deterministic per-leaf pigments (berries, senescent tints) ride the
156:     // vertex colour lane, exactly like the tree leaf-card shader.
157:     albedo = mix(albedo, in.color.rgb, leaf.physical_parameters.z);
158:     let arm = textureSample(leaf_arm, leaf_arm_sampler, in.uv).rgb;
159:     let base_normal = normalize(select(-in.world_normal, in.world_normal, is_front));
160:     let canopy_visibility = mix(1.0, in.color.a, leaf.surface_parameters.z);
161:     let occlusion = canopy_visibility * arm.r;
162: 
163:     // Every representation - including the cambered near leaves - shades with
164:     // the fast foliage model: flat ambient + wrapped Lambert translucency +
165:     // one clamped cascade fetch. No screen-space tangent frame, normal map,
166:     // image-based lighting, or specular. The cards already used this model and
167:     // the cambered leaves crossfade into it, so full PBR was pure cost.
168:     var lit = albedo * lights.ambient_color.rgb * leaf.shading.y * occlusion;
169:     let view_z = dot(vec4<f32>(
170:         view.view_from_world[0].z,
171:         view.view_from_world[1].z,
172:         view.view_from_world[2].z,
173:         view.view_from_world[3].z,
174:     ), in.world_position);
175:     let transmission = leaf.surface_parameters.w;
176:     for (var light_index = 0u; light_index < lights.n_directional_lights;
177:         light_index += 1u)
178:     {
179:         let light = lights.directional_lights[light_index];
180:         let alignment = dot(base_normal, light.direction_to_light);
181:         let wrapped = saturate(alignment) * (1.0 - transmission)
182:             + saturate(-alignment) * transmission;
183:         let shadow = clamp(
184:             shadows::fetch_directional_shadow(
185:                 light_index,
186:                 in.world_position,
187:                 base_normal,
188:                 view_z,
189:                 in.clip_position.xy,
190:             ),
191:             0.12,
192:             1.0,
193:         );
194:         lit += albedo * light.color.rgb * (wrapped * shadow * occlusion * 0.3183099);
195:     }
196:     return vec4<f32>(lit * view.exposure, opacity);
197: }

33714256b6313ce86fdfbb534c54d92d024d7726 assets/shaders/tactical_vista_tree_instanced.wgsl
1: // Chunk-instanced distant vista tree cards.
2: //
3: // A port of the level-4 branch of `tactical_tree_impostor.wgsl` onto the
4: // chunk instance buffer. Vista stands are always whole-tree camera-facing
5: // cards, so the representation branch is gone; what remains is the billboard
6: // basis, the wind sway, the eight-view atlas selection and the cutout.
7: //
8: // The near cutoff is the one thing that could not move to the chunk. The
9: // per-entity renderer gave every card its own `VisibilityRange` whose start
10: // distance scales with that card's height, keeping a stand out of the near
11: // field until it subtends at most 16 degrees. Chunk bands are shared, so
12: // that test is evaluated here per instance instead, from the instance's own
13: // uniform scale.
14: 
15: diagnostic(off, derivative_uniformity);
16: 
17: #import bevy_pbr::{
18:     mesh_view_bindings::{globals, view},
19:     view_transformations::position_world_to_clip,
20: }
21: 
22: #import fablegeist::chunk_instancing::{
23:     Vertex, chunk_band, instance_world_matrix, visibility_range_dither_level,
24: }
25: 
26: @group(3) @binding(0) var baked_color: texture_2d<f32>;
27: @group(3) @binding(1) var baked_color_sampler: sampler;
28: 
29: struct TacticalVistaTreeInstancedMaterial {
30:     /// Unscaled card height in x, deterministic seed in y, wind strength in z,
31:     /// wind speed in w. The per-entity material carried the representation
32:     /// level in x; every vista card is level 4, so that slot now carries the
33:     /// height the near cutoff needs.
34:     parameters: vec4<f32>,
35:     lighting: vec4<f32>,
36:     ambient: vec4<f32>,
37: }
38: 
39: @group(3) @binding(2) var<uniform> tree: TacticalVistaTreeInstancedMaterial;
40: 
41: /// Half of the 16-degree maximum angular height, pre-tangented.
42: const VISTA_TREE_HALF_ANGLE_TANGENT: f32 = 0.14054084;
43: 
44: struct VistaCardVertexOutput {
45:     @builtin(position) clip_position: vec4<f32>,
46: #ifdef VISIBILITY_RANGE_DITHER
47:     @location(0) @interpolate(flat) visibility_range_dither: i32,
48: #endif
49:     @location(1) world_position: vec4<f32>,
50:     @location(2) world_normal: vec3<f32>,
51:     @location(3) uv: vec2<f32>,
52:     /// Distance at which this card is allowed to appear, from its own scale.
53:     @location(4) @interpolate(flat) near_cutoff: f32,
54: }
55: 
56: @vertex
57: fn vertex(vertex: Vertex) -> VistaCardVertexOutput {
58:     var out: VistaCardVertexOutput;
59:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
60:     let root_world = (instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0)).xyz;
61:     let scale = vertex.i_pos_scale.w;
62: 
63:     // Whole-tree cards face the camera, so they cannot use the model basis.
64:     let to_camera = normalize(view.world_position.xz - root_world.xz + vec2<f32>(0.0001, 0.0));
65:     let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
66:     var world_position = vec4<f32>(
67:         root_world
68:             + right * (vertex.position.x * scale)
69:             + vec3<f32>(0.0, vertex.position.y * scale, 0.0),
70:         1.0,
71:     );
72: 
73:     var uv = vec2<f32>(0.0, 0.0);
74: #ifdef VERTEX_UVS_A
75:     uv = vertex.uv;
76: #endif
77:     let height_weight = smoothstep(0.05, 1.0, uv.y);
78:     let phase = globals.time * tree.parameters.w
79:         + world_position.x * 0.11
80:         + world_position.z * 0.073
81:         + tree.parameters.y * 6.2831853;
82:     let wind = (sin(phase) * 0.72 + sin(phase * 2.17 + 1.3) * 0.28)
83:         * tree.parameters.z
84:         * height_weight
85:         * height_weight;
86:     world_position.x += wind;
87:     world_position.z += wind * 0.38;
88: 
89:     out.world_position = world_position;
90:     out.clip_position = position_world_to_clip(world_position.xyz);
91:     out.world_normal = normalize(mix(
92:         vec3<f32>(to_camera.x, 0.18, to_camera.y),
93:         vec3<f32>(0.0, 1.0, 0.0),
94:         0.22,
95:     ));
96:     out.uv = uv;
97:     // The scaled card must subtend no more than the maximum angular height.
98:     out.near_cutoff = (tree.parameters.x * scale) / (2.0 * VISTA_TREE_HALF_ANGLE_TANGENT);
99: 
100: #ifdef VISIBILITY_RANGE_DITHER
101:     let instance_origin = vec4<f32>(root_world, 1.0);
102:     out.visibility_range_dither =
103:         visibility_range_dither_level(chunk_band.visibility_range, instance_origin.xyz);
104: #endif
105:     return out;
106: }
107: 
108: @fragment
109: fn fragment(in: VistaCardVertexOutput) -> @location(0) vec4<f32> {
110: #ifdef VISIBILITY_RANGE_DITHER
111:     // Crisp handoff at the midpoint, as the per-entity path did: a translucent
112:     // crossfade reads as a pale duplicate crown.
113:     if in.visibility_range_dither <= -8 || in.visibility_range_dither > 8 {
114:         discard;
115:     }
116: #endif
117:     // Per-instance near cutoff. The per-entity renderer faded this over a 12%
118:     // band; keep that so a stand does not pop in as one hard edge.
119:     let camera_distance = distance(view.world_position.xz, in.world_position.xz);
120:     if camera_distance < in.near_cutoff {
121:         discard;
122:     }
123:     let near_fade = smoothstep(in.near_cutoff, in.near_cutoff * 1.12, camera_distance);
124:     let pixel_hash = fract(
125:         52.9829189 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
126:     );
127:     if pixel_hash > near_fade {
128:         discard;
129:     }
130: 
131:     let direction = normalize(view.world_position.xz - in.world_position.xz + vec2<f32>(0.0001, 0.0));
132:     let angle = atan2(direction.y, direction.x);
133:     // Bake-card right axes produce view normals one quarter turn behind their
134:     // authored angle; select by that convention.
135:     let wrapped = fract(angle / 6.2831853 + 1.0 - 0.25);
136:     let view_index = u32(round(wrapped * 8.0)) % 8u;
137:     let column = view_index % 3u;
138:     let row = view_index / 3u;
139:     let uv = vec2<f32>(
140:         (f32(column) + in.uv.x) / 3.0,
141:         (f32(row) + in.uv.y) / 3.0,
142:     );
143: 
144:     let baked = textureSample(baked_color, baked_color_sampler, uv);
145:     if baked.a < 0.2 {
146:         discard;
147:     }
148:     let light_direction = normalize(tree.lighting.xyz);
149:     // The atlas already carries small-scale normal and occlusion variation;
150:     // apply only a broad symmetric wrap so an oblique card is not a black
151:     // cutout.
152:     let card_light = abs(dot(normalize(in.world_normal), light_direction));
153:     let normal_light = 0.25 + card_light * 0.75;
154:     let ambient_irradiance = tree.ambient.rgb * tree.ambient.w;
155:     let direct_irradiance = normal_light * tree.lighting.w * (1.0 - tree.ambient.w);
156:     return vec4<f32>(baked.rgb * (ambient_irradiance + vec3<f32>(direct_irradiance)), baked.a);
157: }
