1: //! Cache pebble assets and place only patches clear of managed ground.
2: use super::*;
3: use adventuresim_tactical_core::prelude::GroundSurface;
4: use adventuresim_tactical_core::scene_coordinates::ScenePlanPoint;
5: use bevy::prelude::Handle;
6: use fabelgeist_determinism::Seed;
7: use fabelgeist_determinism::StreamId;
8: 
9: pub(in crate::presentation::ground_scatter) fn spawn(
10:     commands: &mut Commands,
11:     meshes: &mut Assets<Mesh>,
12:     pebble_materials: &mut Assets<TacticalPebbleMaterial>,
13:     billboard_materials: &mut Assets<TacticalPebbleBillboardMaterial>,
14:     terrain: &SceneTerrain,
15:     ground: &SceneGround,
16:     base_seed: Seed,
17: ) {
18:     let half_extent = ground.grid_scale() * 0.5;
19:     let PatchAssets {
20:         hero_meshes,
21:         near_meshes,
22:         billboard_meshes,
23:         pebble_counts,
24:         stone_material,
25:         woodland_stone_material,
26:         billboard_material,
27:     } = PatchAssets::new(meshes, pebble_materials, billboard_materials, half_extent);
28: 
29:     for (index, sample) in ground.samples().iter().enumerate() {
30:         let Some(PatchPlacement {
31:             variant,
32:             woodland,
33:             transform,
34:         }) = PatchPlacement::new(ground, terrain, index, *sample, base_seed, half_extent)
35:         else {
36:             continue;
37:         };
38:         commands.spawn((
39:             Name::new(if woodland {
40:                 "Tactical woodland hero pebble patch"
41:             } else {
42:                 "Tactical loose-stone hero pebble patch"
43:             }),
44:             GroundScatterLayer::LooseStone,
45:             LooseStonePebblePatch::hero(pebble_counts[variant]),
46:             NotShadowCaster,
47:             Mesh3d(hero_meshes[variant].clone()),
48:             MeshMaterial3d(if woodland {
49:                 woodland_stone_material.clone()
50:             } else {
51:                 stone_material.clone()
52:             }),
53:             pebble_lod_visibility(PebbleMeshLod::Hero),
54:             transform,
55:         ));
56:         commands.spawn((
57:             Name::new(if woodland {
58:                 "Tactical woodland near pebble patch"
59:             } else {
60:                 "Tactical loose-stone near pebble patch"
61:             }),
62:             GroundScatterLayer::LooseStone,
63:             LooseStonePebblePatch {
64:                 physical_pebbles: 0,
65:             },
66:             NotShadowCaster,
67:             Mesh3d(near_meshes[variant].clone()),
68:             MeshMaterial3d(if woodland {
69:                 woodland_stone_material.clone()
70:             } else {
71:                 stone_material.clone()
72:             }),
73:             pebble_lod_visibility(PebbleMeshLod::Near),
74:             transform,
75:         ));
76:         if !woodland {
77:             commands.spawn((
78:                 Name::new("Tactical loose-stone billboard pebble patch"),
79:                 GroundScatterLayer::LooseStone,
80:                 LooseStonePebblePatch {
81:                     physical_pebbles: 0,
82:                 },
83:                 // The shader yaws each pebble quad toward the camera, so the
84:                 // mesh's static bounds would mis-cull; this rotation-safe box
85:                 // restores frustum culling for off-screen patches.
86:                 bevy::camera::primitives::Aabb {
87:                     center: bevy::math::Vec3A::new(0.0, 0.1, 0.0),
88:                     half_extents: bevy::math::Vec3A::new(half_extent + 0.3, 0.4, half_extent + 0.3),
89:                 },
90:                 NotShadowCaster,
91:                 Mesh3d(billboard_meshes[variant].clone()),
92:                 MeshMaterial3d(billboard_material.clone()),
93:                 pebble_lod_visibility(PebbleMeshLod::Billboard),
94:                 transform,
95:             ));
96:         }
97:     }
98: }
99: 
100: struct PatchAssets {
101:     hero_meshes: Vec<Handle<Mesh>>,
102:     near_meshes: Vec<Handle<Mesh>>,
103:     billboard_meshes: Vec<Handle<Mesh>>,
104:     pebble_counts: Vec<usize>,
105:     stone_material: Handle<TacticalPebbleMaterial>,
106:     woodland_stone_material: Handle<TacticalPebbleMaterial>,
107:     billboard_material: Handle<TacticalPebbleBillboardMaterial>,
108: }
109: impl PatchAssets {
110:     fn new(
111:         meshes: &mut Assets<Mesh>,
112:         pebble_materials: &mut Assets<TacticalPebbleMaterial>,
113:         billboard_materials: &mut Assets<TacticalPebbleBillboardMaterial>,
114:         half_extent: f32,
115:     ) -> Self {
116:         let mut hero_meshes = Vec::new();
117:         let mut near_meshes = Vec::new();
118:         let mut billboard_meshes = Vec::new();
119:         let mut pebble_counts = Vec::new();
120:         for density in PebbleDensity::ALL {
121:             for variant in 0..MESH_VARIANTS {
122:                 let seed = StreamId::new("visual.ground-scatter.loose-stone.variant")
123:                     .seed(0.into(), &[variant]);
124:                 let hero = pebble_patch_mesh(seed, PebbleMeshLod::Hero, half_extent, density);
125:                 pebble_counts.push(hero.count_vertices() / HERO_PEBBLE_VERTICES);
126:                 hero_meshes.push(meshes.add(hero));
127:                 near_meshes.push(meshes.add(pebble_patch_mesh(
128:                     seed,
129:                     PebbleMeshLod::Near,
130:                     half_extent,
131:                     density,
132:                 )));
133:                 billboard_meshes.push(meshes.add(pebble_billboard_patch_mesh(
134:                     seed,
135:                     half_extent,
136:                     density,
137:                 )));
138:             }
139:         }
140:         let stone_material = pebble_materials.add(TacticalPebbleMaterial::new(rock_color(
141:             RockLithology::Granite,
142:         )));
143:         let woodland_stone_material =
144:             pebble_materials.add(TacticalPebbleMaterial::new(Color::srgb_u8(104, 91, 70)));
145:         let billboard_material = billboard_materials.add(TacticalPebbleBillboardMaterial {
146:             color: Vec4::from_array(
147:                 rock_color(RockLithology::Granite)
148:                     .to_linear()
149:                     .to_f32_array(),
150:             ),
151:             lighting: Vec3::new(0.35, 0.86, 0.25).normalize().extend(1.0),
152:             ambient: Vec4::new(1.0, 1.0, 1.0, 0.28),
153:         });
154: 
155:         Self {
156:             hero_meshes,
157:             near_meshes,
158:             billboard_meshes,
159:             pebble_counts,
160:             stone_material,
161:             woodland_stone_material,
162:             billboard_material,
163:         }
164:     }
165: }
166: struct PatchPlacement {
167:     variant: usize,
168:     woodland: bool,
169:     transform: Transform,
170: }
171: impl PatchPlacement {
172:     fn new(
173:         ground: &SceneGround,
174:         terrain: &SceneTerrain,
175:         index: usize,
176:         sample: GroundSurface,
177:         base_seed: Seed,
178:         half_extent: f32,
179:     ) -> Option<Self> {
180:         if !matches!(
181:             sample.cover,
182:             GroundCover::LooseStone | GroundCover::LeafLitter
183:         ) {
184:             return None;
185:         }
186:         let grid_x = index % ground.grid_width();
187:         let grid_z = index / ground.grid_width();
188:         let position = Vec2::new(
189:             grid_x as f32 * ground.grid_scale() - ground.width() * 0.5,
190:             grid_z as f32 * ground.grid_scale() - ground.depth() * 0.5,
191:         );
192:         let position = ScenePlanPoint::from_metres(position)?;
193:         // The patch can rotate and tilt. Exclude its full existing bounds,
194:         // including pebble overhang, from exact managed-ground ownership.
195:         let envelope_radius = Vec3::new(half_extent + 0.3, 0.4, half_extent + 0.3).length();
196:         if ground.urban.overlaps_disk(position, envelope_radius) {
197:             return None;
198:         }
199:         let (Some(height), Some(normal)) =
200:             (terrain.height_at(position), terrain.normal_at(position))
201:         else {
202:             return None;
203:         };
204:         if normal.y < 0.72 {
205:             return None;
206:         }
207:         let hash = StreamId::new("visual.ground-scatter.loose-stone.scatter")
208:             .seed(base_seed, &[index as u64]);
209:         let woodland = sample.cover == GroundCover::LeafLitter;
210:         let density = if woodland {
211:             // Every woodland cell gets a sparse candidate patch. Individual
212:             // survival still leaves irregular gaps, but keeping the patches
213:             // continuous yields roughly one visible 3--8 cm stone per square
214:             // metre instead of making rocks disappear from review frames.
215:             PebbleDensity::Woodland
216:         } else {
217:             let coverage = scree_patch_coverage(base_seed, position, normal);
218:             if coverage >= 0.61 {
219:                 PebbleDensity::Dense
220:             } else if coverage >= 0.34 {
221:                 PebbleDensity::Sparse
222:             } else {
223:                 return None;
224:             }
225:         };
226:         let variant = density.asset_offset()
227:             + StreamId::new("visual.ground-scatter.loose-stone.spawn.mesh-variant")
228:                 .rng(hash, &[])
229:                 .index(MESH_VARIANTS as usize);
230:         let yaw = Quat::from_rotation_y(
231:             StreamId::new("visual.ground-scatter.loose-stone.spawn.yaw")
232:                 .rng(hash, &[])
233:                 .inclusive_unit_f32()
234:                 * core::f32::consts::TAU,
235:         );
236:         let transform = Transform::from_xyz(
237:             position.metres().x,
238:             height.metres() + if woodland { -0.006 } else { 0.006 },
239:             position.metres().y,
240:         )
241:         .with_rotation(Quat::from_rotation_arc(Vec3::Y, *normal) * yaw)
242:         .with_scale(Vec3::splat(if woodland { 0.58 } else { 1.0 }));
243: 
244:         Some(Self {
245:             variant,
246:             woodland,
247:             transform,
248:         })
249:     }
250: }
