109: 
110: #[derive(Component)]
111: pub(crate) struct LooseStonePebblePatch {
112:     pub(crate) physical_pebbles: usize,
113: }
114: 
115: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
116: enum PebbleMeshLod {
117:     Hero,
118:     Near,
119:     Billboard,
120: }
121: 
122: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
123: enum PebbleDensity {
124:     Woodland,
125:     Sparse,
126:     Dense,
127: }
128: 
129: impl PebbleDensity {
130:     const ALL: [Self; 3] = [Self::Woodland, Self::Sparse, Self::Dense];
131: 
132:     const fn asset_offset(self) -> usize {
133:         match self {
134:             Self::Woodland => 0,
135:             Self::Sparse => MESH_VARIANTS as usize,
136:             Self::Dense => MESH_VARIANTS as usize * 2,
137:         }
138:     }
139: }
140: 
141: mod spawn;
142: pub(super) use spawn::spawn;
143: 
144: fn pebble_lod_visibility(lod: PebbleMeshLod) -> VisibilityRange {
145:     match lod {
146:         PebbleMeshLod::Hero => VisibilityRange {
147:             start_margin: 0.0..0.0,
148:             end_margin: 5.0..6.0,
149:             use_aabb: false,
150:         },
151:         // Even the six-centimetre minimum spans at least five QHD pixels at
152:         // close range; hand off only once its full diameter approaches two.
153:         PebbleMeshLod::Near => VisibilityRange {
154:             start_margin: 5.0..6.0,
155:             end_margin: 20.0..24.0,
156:             use_aabb: false,
157:         },
158:         PebbleMeshLod::Billboard => VisibilityRange {
159:             start_margin: 20.0..24.0,
160:             // The shader independently screen-fades each pebble around one
161:             // pixel; this range is only a conservative entity-level cutoff.
162:             end_margin: 160.0..180.0,
163:             use_aabb: false,
164:         },
165:     }
166: }
167: 
168: /// Scene-metre dot products and dimensionless noise coordinates for the scree field.
169: fn scree_patch_coverage(seed: Seed, point: ScenePlanPoint, normal: Dir3) -> f32 {
170:     let point = point.metres();
171:     let downhill = Vec2::new(normal.x, normal.z).normalize_or_zero();
172:     let downhill = if downhill.length_squared() > 0.001 {
173:         downhill
174:     } else {
175:         Vec2::X
176:     };
177:     let across = Vec2::new(-downhill.y, downhill.x);
178:     let broad = scree_noise(seed.xor_word(0x7363_7265_655f_6272), point / 4.8);
179:     // Stretch the second field along the fall line so loose material gathers
180:     // into downhill trains rather than evenly stippling the whole substrate.
181:     let streak_point = Vec2::new(point.dot(across) / 2.2, point.dot(downhill) / 8.5);
182:     let streak = scree_noise(seed.xor_word(0x7363_7265_655f_7374), streak_point);
183:     broad * 0.58 + streak * 0.42
184: }
185: 
186: fn scree_noise(seed: Seed, point: Vec2) -> f32 {
187:     let cell = point.floor();
188:     let local = point - cell;
189:     let curve = local * local * (Vec2::splat(3.0) - local * 2.0);
190:     let hash = |offset: Vec2| {
191:         let coordinate = cell + offset;
192:         let x = i64::from(coordinate.x as i32) as u64;
193:         let y = i64::from(coordinate.y as i32) as u64;
194:         streams::LATTICE.rng(seed, &[x, y]).inclusive_unit_f32()
195:     };
196:     let bottom_left = hash(Vec2::ZERO);
197:     let bottom = bottom_left + (hash(Vec2::X) - bottom_left) * curve.x;
198:     let top_left = hash(Vec2::Y);
199:     let top = top_left + (hash(Vec2::ONE) - top_left) * curve.x;
200:     bottom + (top - bottom) * curve.y
201: }
202: 
203: fn pebble_survives(
204:     seed: Seed,
205:     hash: Seed,
206:     centre: Vec2,
207:     half_extent: f32,
208:     density: PebbleDensity,
209: ) -> bool {
210:     let cluster = |salt: u64| {
211:         Vec2::new(
212:             streams::CLUSTER_X.rng(seed, &[salt]).inclusive_unit_f32() * 2.0 - 1.0,
213:             streams::CLUSTER_Z.rng(seed, &[salt]).inclusive_unit_f32() * 2.0 - 1.0,
214:         ) * half_extent
215:             * 0.7
216:     };
217:     let radius = (half_extent * 0.72).max(0.18);
218:     let influence = [cluster(0), cluster(1)]
219:         .into_iter()
220:         .map(|cluster| (-(centre.distance_squared(cluster) / radius.powi(2)) * 1.4).exp())
221:         .fold(0.0_f32, f32::max);
222:     let chance = match density {
223:         PebbleDensity::Woodland => 0.045 + influence * 0.16,
224:         PebbleDensity::Sparse => 0.035 + influence * 0.42,
225:         PebbleDensity::Dense => 0.09 + influence * 0.76,
226:     };
227:     streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() < chance
228: }
229: 
230: fn pebble_facet_scale(hash: Seed, segment: usize, density: PebbleDensity) -> f32 {
231:     if density == PebbleDensity::Woodland {
232:         0.82 + streams::FACET
233:             .rng(hash, &[segment as u64])
234:             .inclusive_unit_f32()
235:             * 0.28
236:     } else {
237:         1.0
238:     }
239: }
240: 
241: fn pebble_patch_mesh(
242:     seed: Seed,
243:     lod: PebbleMeshLod,
244:     half_extent: f32,
245:     density: PebbleDensity,
246: ) -> Mesh {
247:     let (radial_segments, ring_profiles): (usize, &[(f32, f32, f32)]) = match lod {
248:         PebbleMeshLod::Hero => (
249:             HERO_PEBBLE_RADIAL_SEGMENTS,
250:             &[(-0.05, 0.72, -0.38), (0.42, 1.00, 0.06), (0.76, 0.76, 0.46)],
251:         ),
252:         PebbleMeshLod::Near => (
253:             STANDARD_PEBBLE_RADIAL_SEGMENTS,
254:             &[(-0.03, 0.84, -0.28), (0.58, 1.0, 0.28)],
255:         ),
256:         PebbleMeshLod::Billboard => unreachable!("billboards use their dedicated quad mesh"),
257:     };
258:     let vertices_per_pebble = radial_segments * ring_profiles.len() + 2;
259:     let triangles_per_pebble = radial_segments * ring_profiles.len() * 2;
260:     let mut positions = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
261:     let mut normals = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
262:     let mut uvs = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
263:     let mut indices = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * triangles_per_pebble * 3);
264: 
265:     for pebble in 0..PEBBLE_CANDIDATES_PER_PATCH {
266:         let hash = streams::PEBBLE.seed(seed, &[pebble as u64]);
267:         let unit_draw =
268:             |purpose: fabelgeist_determinism::StreamId| purpose.rng(hash, &[]).inclusive_unit_f32();
269:         let radius = MIN_PEBBLE_RADIUS_METRES
270:             + unit_draw(streams::RADIUS) * (MAX_PEBBLE_RADIUS_METRES - MIN_PEBBLE_RADIUS_METRES);
271:         // Jittered low-discrepancy points avoid overlap and the large random
272:         // holes which previously exposed the repeated shared mesh tiles.
273:         let column = pebble % PEBBLE_PATCH_COLUMNS;
274:         let row = pebble / PEBBLE_PATCH_COLUMNS;
275:         let jitter_x = unit_draw(streams::JITTER_X) - 0.5;
276:         let jitter_z = unit_draw(streams::JITTER_Z) - 0.5;
277:         let centre = Vec3::new(
278:             ((column as f32 + 0.5 + jitter_x * 0.88) / PEBBLE_PATCH_COLUMNS as f32 * 2.0 - 1.0)
279:                 * half_extent,
280:             0.0,
281:             ((row as f32 + 0.5 + jitter_z * 0.88) / PEBBLE_PATCH_ROWS as f32 * 2.0 - 1.0)
282:                 * half_extent,
283:         );
284:         if !pebble_survives(
285:             seed,
286:             hash,
287:             Vec2::new(centre.x, centre.z),
288:             half_extent,
289:             density,
290:         ) {
291:             continue;
292:         }
293:         let height_scale = if density == PebbleDensity::Woodland {
294:             0.52 + unit_draw(streams::HEIGHT) * 0.30
295:         } else {
296:             0.85 + unit_draw(streams::HEIGHT) * 0.45
297:         };
298:         let height = radius * height_scale;
299:         let yaw = unit_draw(streams::YAW) * core::f32::consts::TAU;
300:         let direction = Vec3::new(yaw.cos(), 0.0, yaw.sin());
301:         let tangent = Vec3::new(-direction.z, 0.0, direction.x);
302:         let lateral_scale = if density == PebbleDensity::Woodland {
303:             0.52 + unit_draw(streams::LATERAL_SCALE) * 0.34
304:         } else {
305:             0.72 + unit_draw(streams::LATERAL_SCALE) * 0.26
306:         };
307:         let base = positions.len() as u32;
308:         positions.push((centre - Vec3::Y * radius * 0.18).to_array());
309:         normals.push(Vec3::NEG_Y.to_array());
310:         uvs.push([0.5, 0.5]);
311: 
312:         for &(height_fraction, radius_scale, normal_y) in ring_profiles {
313:             for segment in 0..radial_segments {
314:                 let angle = segment as f32 / radial_segments as f32 * core::f32::consts::TAU;
315:                 let facet_scale = pebble_facet_scale(hash, segment, density);
316:                 let horizontal = direction * angle.cos() + tangent * angle.sin() * lateral_scale;
317:                 let vertex = centre
318:                     + direction * angle.cos() * radius * radius_scale * facet_scale
319:                     + tangent * angle.sin() * radius * radius_scale * lateral_scale * facet_scale
320:                     + Vec3::Y * height * height_fraction;
321:                 positions.push(vertex.to_array());
322:                 normals.push(
323:                     (horizontal + Vec3::Y * normal_y)
324:                         .normalize_or_zero()
325:                         .to_array(),
326:                 );
327:                 uvs.push([segment as f32 / radial_segments as f32, height_fraction]);
328:             }
329:         }
330: 
331:         positions.push((centre + Vec3::Y * height).to_array());
332:         normals.push(Vec3::Y.to_array());
333:         uvs.push([0.5, 1.0]);
334: 
335:         let first_ring = base + 1;
336:         let top = first_ring + (radial_segments * ring_profiles.len()) as u32;
337:         for segment in 0..radial_segments as u32 {
338:             let next = (segment + 1) % radial_segments as u32;
339:             indices.extend_from_slice(&[base, first_ring + segment, first_ring + next]);
340:         }
341:         for ring in 0..ring_profiles.len() - 1 {
342:             let lower = first_ring + (ring * radial_segments) as u32;
343:             let upper = lower + radial_segments as u32;
344:             for segment in 0..radial_segments as u32 {
345:                 let next = (segment + 1) % radial_segments as u32;
346:                 indices.extend_from_slice(&[
347:                     lower + segment,
348:                     upper + next,
349:                     lower + next,
350:                     lower + segment,
351:                     upper + segment,
352:                     upper + next,
353:                 ]);
354:             }
355:         }
356:         let last_ring = top - radial_segments as u32;
357:         for segment in 0..radial_segments as u32 {
358:             let next = (segment + 1) % radial_segments as u32;
359:             indices.extend_from_slice(&[last_ring + segment, top, last_ring + next]);
360:         }
361:     }
362: 
363:     let mut mesh = Mesh::new(
364:         PrimitiveTopology::TriangleList,
365:         RenderAssetUsages::RENDER_WORLD,
366:     );
367:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
368:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
369:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
370:     mesh.insert_indices(Indices::U32(indices));
371:     mesh
372: }
373: 
374: fn pebble_billboard_patch_mesh(seed: Seed, half_extent: f32, density: PebbleDensity) -> Mesh {
375:     let mut positions = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
376:     let mut centres = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
377:     let mut uvs = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
378:     let mut indices = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_TRIANGLES * 3);
379: 
380:     for pebble in 0..PEBBLE_CANDIDATES_PER_PATCH {
381:         let hash = streams::PEBBLE.seed(seed, &[pebble as u64]);
382:         let radius = MIN_PEBBLE_RADIUS_METRES
383:             + streams::RADIUS.rng(hash, &[]).inclusive_unit_f32()
384:                 * (MAX_PEBBLE_RADIUS_METRES - MIN_PEBBLE_RADIUS_METRES);
385:         let column = pebble % PEBBLE_PATCH_COLUMNS;
386:         let row = pebble / PEBBLE_PATCH_COLUMNS;
387:         let jitter_x = streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5;
388:         let jitter_z = streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5;
389:         let centre = Vec3::new(
390:             ((column as f32 + 0.5 + jitter_x * 0.88) / PEBBLE_PATCH_COLUMNS as f32 * 2.0 - 1.0)
391:                 * half_extent,
392:             0.0,
393:             ((row as f32 + 0.5 + jitter_z * 0.88) / PEBBLE_PATCH_ROWS as f32 * 2.0 - 1.0)
394:                 * half_extent,
395:         );
396:         if !pebble_survives(
397:             seed,
398:             hash,
399:             Vec2::new(centre.x, centre.z),
400:             half_extent,

401:             density,
402:         ) {
403:             continue;
404:         }
405:         let height = radius * (0.85 + streams::HEIGHT.rng(hash, &[]).inclusive_unit_f32() * 0.45);
406:         let sprite_centre = centre + Vec3::Y * height * 0.5;
407:         let base = positions.len() as u32;
408: 
409:         for (offset, uv) in [
410:             ([-radius, -height * 0.5, 0.0], [0.0, 0.0]),
411:             ([radius, -height * 0.5, 0.0], [1.0, 0.0]),
412:             ([radius, height * 0.5, 0.0], [1.0, 1.0]),
413:             ([-radius, height * 0.5, 0.0], [0.0, 1.0]),
414:         ] {
415:             positions.push(offset);
416:             // The billboard shader repurposes this otherwise unused vertex
417:             // channel as the per-quad local centre within the shared patch.
418:             centres.push(sprite_centre.to_array());
419:             uvs.push(uv);
420:         }
421:         indices.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
422:     }
423: 
424:     let mut mesh = Mesh::new(
425:         PrimitiveTopology::TriangleList,
426:         RenderAssetUsages::RENDER_WORLD,
427:     );
428:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
429:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, centres);
430:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
431:     mesh.insert_indices(Indices::U32(indices));
432:     mesh
433: }
