171: fn pebble_lod_visibility(lod: PebbleMeshLod) -> VisibilityRange {
172:     match lod {
173:         PebbleMeshLod::Hero => VisibilityRange {
174:             start_margin: 0.0..0.0,
175:             end_margin: 5.0..6.0,
176:             use_aabb: false,
177:         },
178:         // Even the six-centimetre minimum spans at least five QHD pixels at
179:         // close range; hand off only once its full diameter approaches two.
180:         PebbleMeshLod::Near => VisibilityRange {
181:             start_margin: 5.0..6.0,
182:             end_margin: 20.0..24.0,
183:             use_aabb: false,
184:         },
185:         PebbleMeshLod::Billboard => VisibilityRange {
186:             start_margin: 20.0..24.0,
187:             // The shader independently screen-fades each pebble around one
188:             // pixel; this range is only a conservative entity-level cutoff.
189:             end_margin: 160.0..180.0,
190:             use_aabb: false,
191:         },
192:     }
193: }
194: 
195: /// Scene-metre dot products and dimensionless noise coordinates for the scree field.
196: fn scree_patch_coverage(seed: Seed, point: ScenePlanPoint, normal: Dir3) -> f32 {
197:     let point = point.metres();
198:     let downhill = Vec2::new(normal.x, normal.z).normalize_or_zero();
199:     let downhill = if downhill.length_squared() > 0.001 {
200:         downhill
201:     } else {
202:         Vec2::X
203:     };
204:     let across = Vec2::new(-downhill.y, downhill.x);
205:     let broad = scree_noise(seed.xor_word(0x7363_7265_655f_6272), point / 4.8);
206:     // Stretch the second field along the fall line so loose material gathers
207:     // into downhill trains rather than evenly stippling the whole substrate.
208:     let streak_point = Vec2::new(point.dot(across) / 2.2, point.dot(downhill) / 8.5);
209:     let streak = scree_noise(seed.xor_word(0x7363_7265_655f_7374), streak_point);
210:     broad * 0.58 + streak * 0.42
211: }
212: 
213: fn scree_noise(seed: Seed, point: Vec2) -> f32 {
214:     let cell = point.floor();
215:     let local = point - cell;
216:     let curve = local * local * (Vec2::splat(3.0) - local * 2.0);
217:     let hash = |offset: Vec2| {
218:         let coordinate = cell + offset;
219:         let x = i64::from(coordinate.x as i32) as u64;
220:         let y = i64::from(coordinate.y as i32) as u64;
221:         streams::LATTICE.rng(seed, &[x, y]).inclusive_unit_f32()
222:     };
223:     let bottom_left = hash(Vec2::ZERO);
224:     let bottom = bottom_left + (hash(Vec2::X) - bottom_left) * curve.x;
225:     let top_left = hash(Vec2::Y);
226:     let top = top_left + (hash(Vec2::ONE) - top_left) * curve.x;
227:     bottom + (top - bottom) * curve.y
228: }
229: 
230: fn pebble_survives(
231:     seed: Seed,
232:     hash: Seed,
233:     centre: Vec2,
234:     half_extent: f32,
235:     density: PebbleDensity,
236: ) -> bool {
237:     let cluster = |salt: u64| {
238:         Vec2::new(
239:             streams::CLUSTER_X.rng(seed, &[salt]).inclusive_unit_f32() * 2.0 - 1.0,
240:             streams::CLUSTER_Z.rng(seed, &[salt]).inclusive_unit_f32() * 2.0 - 1.0,
241:         ) * half_extent
242:             * 0.7
243:     };
244:     let radius = (half_extent * 0.72).max(0.18);
245:     let influence = [cluster(0), cluster(1)]
246:         .into_iter()
247:         .map(|cluster| (-(centre.distance_squared(cluster) / radius.powi(2)) * 1.4).exp())
248:         .fold(0.0_f32, f32::max);
249:     let chance = match density {
250:         PebbleDensity::Woodland => 0.045 + influence * 0.16,
251:         PebbleDensity::Sparse => 0.035 + influence * 0.42,
252:         PebbleDensity::Dense => 0.09 + influence * 0.76,
253:     };
254:     streams::PRESENCE.rng(hash, &[]).inclusive_unit_f32() < chance
255: }
256: 
257: fn pebble_facet_scale(hash: Seed, segment: usize, density: PebbleDensity) -> f32 {
258:     if density == PebbleDensity::Woodland {
259:         0.82 + streams::FACET
260:             .rng(hash, &[segment as u64])
261:             .inclusive_unit_f32()
262:             * 0.28
263:     } else {
264:         1.0
265:     }
266: }
267: 
268: fn pebble_patch_mesh(
269:     seed: Seed,
270:     lod: PebbleMeshLod,
271:     half_extent: f32,
272:     density: PebbleDensity,
273: ) -> Mesh {
274:     let (radial_segments, ring_profiles): (usize, &[(f32, f32, f32)]) = match lod {
275:         PebbleMeshLod::Hero => (
276:             HERO_PEBBLE_RADIAL_SEGMENTS,
277:             &[(-0.05, 0.72, -0.38), (0.42, 1.00, 0.06), (0.76, 0.76, 0.46)],
278:         ),
279:         PebbleMeshLod::Near => (
280:             STANDARD_PEBBLE_RADIAL_SEGMENTS,
281:             &[(-0.03, 0.84, -0.28), (0.58, 1.0, 0.28)],
282:         ),
283:         PebbleMeshLod::Billboard => unreachable!("billboards use their dedicated quad mesh"),
284:     };
285:     let vertices_per_pebble = radial_segments * ring_profiles.len() + 2;
286:     let triangles_per_pebble = radial_segments * ring_profiles.len() * 2;
287:     let mut positions = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
288:     let mut normals = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
289:     let mut uvs = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * vertices_per_pebble);
290:     let mut indices = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * triangles_per_pebble * 3);
291: 
292:     for pebble in 0..PEBBLE_CANDIDATES_PER_PATCH {
293:         let hash = streams::PEBBLE.seed(seed, &[pebble as u64]);
294:         let unit_draw =
295:             |purpose: fabelgeist_determinism::StreamId| purpose.rng(hash, &[]).inclusive_unit_f32();
296:         let radius = MIN_PEBBLE_RADIUS_METRES
297:             + unit_draw(streams::RADIUS) * (MAX_PEBBLE_RADIUS_METRES - MIN_PEBBLE_RADIUS_METRES);
298:         // Jittered low-discrepancy points avoid overlap and the large random
299:         // holes which previously exposed the repeated shared mesh tiles.
300:         let column = pebble % PEBBLE_PATCH_COLUMNS;
301:         let row = pebble / PEBBLE_PATCH_COLUMNS;
302:         let jitter_x = unit_draw(streams::JITTER_X) - 0.5;
303:         let jitter_z = unit_draw(streams::JITTER_Z) - 0.5;
304:         let centre = Vec3::new(
305:             ((column as f32 + 0.5 + jitter_x * 0.88) / PEBBLE_PATCH_COLUMNS as f32 * 2.0 - 1.0)
306:                 * half_extent,
307:             0.0,
308:             ((row as f32 + 0.5 + jitter_z * 0.88) / PEBBLE_PATCH_ROWS as f32 * 2.0 - 1.0)
309:                 * half_extent,
310:         );
311:         if !pebble_survives(
312:             seed,
313:             hash,
314:             Vec2::new(centre.x, centre.z),
315:             half_extent,
316:             density,
317:         ) {
318:             continue;
319:         }
320:         let height_scale = if density == PebbleDensity::Woodland {
321:             0.52 + unit_draw(streams::HEIGHT) * 0.30
322:         } else {
323:             0.85 + unit_draw(streams::HEIGHT) * 0.45
324:         };
325:         let height = radius * height_scale;
326:         let yaw = unit_draw(streams::YAW) * core::f32::consts::TAU;
327:         let direction = Vec3::new(yaw.cos(), 0.0, yaw.sin());
328:         let tangent = Vec3::new(-direction.z, 0.0, direction.x);
329:         let lateral_scale = if density == PebbleDensity::Woodland {
330:             0.52 + unit_draw(streams::LATERAL_SCALE) * 0.34
331:         } else {
332:             0.72 + unit_draw(streams::LATERAL_SCALE) * 0.26
333:         };
334:         let base = positions.len() as u32;
335:         positions.push((centre - Vec3::Y * radius * 0.18).to_array());
336:         normals.push(Vec3::NEG_Y.to_array());
337:         uvs.push([0.5, 0.5]);
338: 
339:         for &(height_fraction, radius_scale, normal_y) in ring_profiles {
340:             for segment in 0..radial_segments {
341:                 let angle = segment as f32 / radial_segments as f32 * core::f32::consts::TAU;
342:                 let facet_scale = pebble_facet_scale(hash, segment, density);
343:                 let horizontal = direction * angle.cos() + tangent * angle.sin() * lateral_scale;
344:                 let vertex = centre
345:                     + direction * angle.cos() * radius * radius_scale * facet_scale
346:                     + tangent * angle.sin() * radius * radius_scale * lateral_scale * facet_scale
347:                     + Vec3::Y * height * height_fraction;
348:                 positions.push(vertex.to_array());
349:                 normals.push(
350:                     (horizontal + Vec3::Y * normal_y)
351:                         .normalize_or_zero()
352:                         .to_array(),
353:                 );
354:                 uvs.push([segment as f32 / radial_segments as f32, height_fraction]);
355:             }
356:         }
357: 
358:         positions.push((centre + Vec3::Y * height).to_array());
359:         normals.push(Vec3::Y.to_array());
360:         uvs.push([0.5, 1.0]);
361: 
362:         let first_ring = base + 1;
363:         let top = first_ring + (radial_segments * ring_profiles.len()) as u32;
364:         for segment in 0..radial_segments as u32 {
365:             let next = (segment + 1) % radial_segments as u32;
366:             indices.extend_from_slice(&[base, first_ring + segment, first_ring + next]);
367:         }
368:         for ring in 0..ring_profiles.len() - 1 {
369:             let lower = first_ring + (ring * radial_segments) as u32;
370:             let upper = lower + radial_segments as u32;
371:             for segment in 0..radial_segments as u32 {
372:                 let next = (segment + 1) % radial_segments as u32;
373:                 indices.extend_from_slice(&[
374:                     lower + segment,
375:                     upper + next,
376:                     lower + next,
377:                     lower + segment,
378:                     upper + segment,
379:                     upper + next,
380:                 ]);
381:             }
382:         }
383:         let last_ring = top - radial_segments as u32;
384:         for segment in 0..radial_segments as u32 {
385:             let next = (segment + 1) % radial_segments as u32;
386:             indices.extend_from_slice(&[last_ring + segment, top, last_ring + next]);
387:         }
388:     }
389: 
390:     let mut mesh = Mesh::new(
391:         PrimitiveTopology::TriangleList,
392:         RenderAssetUsages::RENDER_WORLD,
393:     );
394:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
395:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
396:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
397:     mesh.insert_indices(Indices::U32(indices));
398:     mesh
399: }
400: 
401: fn pebble_billboard_patch_mesh(seed: Seed, half_extent: f32, density: PebbleDensity) -> Mesh {
402:     let mut positions = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
403:     let mut centres = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
404:     let mut uvs = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_VERTICES);
405:     let mut indices = Vec::with_capacity(PEBBLE_CANDIDATES_PER_PATCH * BILLBOARD_TRIANGLES * 3);
406: 
407:     for pebble in 0..PEBBLE_CANDIDATES_PER_PATCH {
408:         let hash = streams::PEBBLE.seed(seed, &[pebble as u64]);
409:         let radius = MIN_PEBBLE_RADIUS_METRES
410:             + streams::RADIUS.rng(hash, &[]).inclusive_unit_f32()
411:                 * (MAX_PEBBLE_RADIUS_METRES - MIN_PEBBLE_RADIUS_METRES);
412:         let column = pebble % PEBBLE_PATCH_COLUMNS;
413:         let row = pebble / PEBBLE_PATCH_COLUMNS;
414:         let jitter_x = streams::JITTER_X.rng(hash, &[]).inclusive_unit_f32() - 0.5;
415:         let jitter_z = streams::JITTER_Z.rng(hash, &[]).inclusive_unit_f32() - 0.5;
416:         let centre = Vec3::new(
417:             ((column as f32 + 0.5 + jitter_x * 0.88) / PEBBLE_PATCH_COLUMNS as f32 * 2.0 - 1.0)
418:                 * half_extent,
419:             0.0,
420:             ((row as f32 + 0.5 + jitter_z * 0.88) / PEBBLE_PATCH_ROWS as f32 * 2.0 - 1.0)
421:                 * half_extent,
422:         );
423:         if !pebble_survives(
424:             seed,
425:             hash,

426:             Vec2::new(centre.x, centre.z),
427:             half_extent,
428:             density,
429:         ) {
430:             continue;
431:         }
432:         let height = radius * (0.85 + streams::HEIGHT.rng(hash, &[]).inclusive_unit_f32() * 0.45);
433:         let sprite_centre = centre + Vec3::Y * height * 0.5;
434:         let base = positions.len() as u32;
435: 
436:         for (offset, uv) in [
437:             ([-radius, -height * 0.5, 0.0], [0.0, 0.0]),
438:             ([radius, -height * 0.5, 0.0], [1.0, 0.0]),
439:             ([radius, height * 0.5, 0.0], [1.0, 1.0]),
440:             ([-radius, height * 0.5, 0.0], [0.0, 1.0]),
441:         ] {
442:             positions.push(offset);
443:             // The billboard shader repurposes this otherwise unused vertex
444:             // channel as the per-quad local centre within the shared patch.
445:             centres.push(sprite_centre.to_array());
446:             uvs.push(uv);
447:         }
448:         indices.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
449:     }
450: 
451:     let mut mesh = Mesh::new(
452:         PrimitiveTopology::TriangleList,
453:         RenderAssetUsages::RENDER_WORLD,
454:     );
455:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
456:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, centres);
457:     mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
458:     mesh.insert_indices(Indices::U32(indices));
459:     mesh
460: }
