1: //! Stable deterministic primitives shared across dependency layers.
2: //!
3: //! Identical canonical inputs and draw sequences are reproducible across
4: //! supported targets. Intentional output changes require updating affected
5: //! replay markers and generated fixtures.
6: 
7: mod seed;
8: mod stream;
9: pub use seed::{Seed, StreamId};
10: pub use stream::{DeterministicRng, SamplingError};
11: 
12: const UNIT_F32_SCALE: f32 = (1_u32 << 24) as f32;
13: const INCLUSIVE_UNIT_F32_SCALE: f32 = ((1_u32 << 24) - 1) as f32;
14: const UNIT_F64_SCALE: f64 = (1_u64 << 53) as f64;
15: const INCLUSIVE_UNIT_F64_SCALE: f64 = ((1_u64 << 53) - 1) as f64;
16: 
17: /// Convert the high 24 bits to the half-open unit interval `[0, 1)`.
18: pub fn unit_f32(value: u64) -> f32 {
19:     (value >> 40) as f32 / UNIT_F32_SCALE
20: }
21: 
22: /// Convert the high 24 bits to the inclusive unit interval `[0, 1]`.
23: pub fn inclusive_unit_f32(value: u64) -> f32 {
24:     (value >> 40) as f32 / INCLUSIVE_UNIT_F32_SCALE
25: }
26: 
27: /// Convert the high 53 bits to the half-open unit interval `[0, 1)`.
28: pub fn unit_f64(value: u64) -> f64 {
29:     (value >> 11) as f64 / UNIT_F64_SCALE
30: }
31: 
32: /// Convert the high 53 bits to the inclusive unit interval `[0, 1]`.
33: pub fn inclusive_unit_f64(value: u64) -> f64 {
34:     (value >> 11) as f64 / INCLUSIVE_UNIT_F64_SCALE
35: }
36: 
