42:     fn splitmix64_seed_zero_sequence_is_stable() {
43:         let mut random = DeterministicRng::new(Seed::from_u64(0));
44:         assert_eq!(random.next_u64(), 0xe220_a839_7b1d_cdaf);
45:         assert_eq!(random.next_u64(), 0x6e78_9e6a_a1b9_65f4);
46:         assert_eq!(random.next_u64(), 0x06c4_5d18_8009_454f);
47:     }
