49:     #[test]
50:     fn unit_conversions_keep_their_interval_contracts() {
51:         assert_eq!(unit_f32(0), 0.0);
52:         assert!(unit_f32(u64::MAX) < 1.0);
53:         assert_eq!(inclusive_unit_f32(u64::MAX), 1.0);
54:         assert_eq!(unit_f64(0), 0.0);
55:         assert!(unit_f64(u64::MAX) < 1.0);
56:         assert_eq!(inclusive_unit_f64(u64::MAX), 1.0);
57:     }
