1: //! Sampling policy: all randomness flows through fixed-width `next_u64`.
2: 
3: use std::num::NonZeroU64;
4: 
5: use rand::{
6:     RngCore, SeedableRng,
7:     distr::{Distribution, Uniform, weighted::WeightedIndex},
8: };
9: 
10: use crate::Seed;
11: 
12: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
13: pub enum SamplingError {
14:     EmptyCandidates,
15:     ZeroTotalWeight,
16:     WeightOverflow,
17: }
18: 
19: impl std::fmt::Display for SamplingError {
20:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
21:         f.write_str(match self {
22:             Self::EmptyCandidates => "sampling requires candidates",
23:             Self::ZeroTotalWeight => "sampling requires positive total weight",
24:             Self::WeightOverflow => "sampling weights exceed u64",
25:         })
26:     }
27: }
28: impl std::error::Error for SamplingError {}
29: 
30: /// Portable SplitMix64 draws and integer sampling, with no ambient entropy.
31: #[derive(Clone, Debug, Eq, PartialEq)]
32: pub struct DeterministicRng(rand_xoshiro::SplitMix64);
33: 
34: impl DeterministicRng {
35:     pub fn new(seed: Seed) -> Self {
36:         Self(rand_xoshiro::SplitMix64::from_seed(seed.to_le_bytes()))
37:     }
38: 
39:     pub fn next_u64(&mut self) -> u64 {
40:         self.0.next_u64()
41:     }
42: 
43:     /// One unchanged word draw whose consumer owns a generation seed.
44:     pub fn next_seed(&mut self) -> Seed {
45:         Seed::from_u64(self.next_u64())
46:     }
47: 
48:     /// Uniform `[0, upper)` using Rand's constructed, unbiased u64 sampler.
49:     pub fn below(&mut self, upper: NonZeroU64) -> u64 {
50:         sample_below(&mut self.0, upper)
51:     }
52: 
53:     /// Select an index only after sampling at a fixed width.
54:     ///
55:     /// Panics for an empty collection in every build profile. Callers with
56:     /// optional candidates must handle absence before requesting a draw.
57:     pub fn index(&mut self, length: usize) -> usize {
58:         let bound =
59:             NonZeroU64::new(length as u64).expect("sampling requires a nonempty collection");
60:         usize::try_from(self.below(bound)).expect("sample fits collection length")
61:     }
62: 
63:     /// Choose uniformly from candidates in their stable authored order.
64:     ///
65:     /// Like [`Self::index`], this requires a nonempty collection.
66:     pub fn choose<'a, T>(&mut self, candidates: &'a [T]) -> &'a T {
67:         &candidates[self.index(candidates.len())]
68:     }
69: 
70:     pub fn boolean(&mut self) -> bool {
71:         self.below(NonZeroU64::new(2).expect("two outcomes")) == 0
72:     }
73: 
74:     pub fn unit_f32(&mut self) -> f32 {
75:         crate::unit_f32(self.next_u64())
76:     }
77: 
78:     pub fn unit_f64(&mut self) -> f64 {
79:         crate::unit_f64(self.next_u64())
80:     }
81: 
82:     pub fn inclusive_unit_f32(&mut self) -> f32 {
83:         crate::inclusive_unit_f32(self.next_u64())
84:     }
85: 
86:     pub fn inclusive_unit_f64(&mut self) -> f64 {
87:         crate::inclusive_unit_f64(self.next_u64())
88:     }
89: 
90:     /// Scaling has interval semantics but no downstream bitwise guarantee.
91:     pub fn range_f32(&mut self, minimum: f32, maximum: f32) -> f32 {
92:         assert!(minimum.is_finite() && maximum.is_finite() && minimum <= maximum);
93:         minimum + self.unit_f32() * (maximum - minimum)
94:     }
95: 
96:     /// Descending Fisher–Yates. Every swap uses the same u64 sampler.
97:     pub fn shuffle<T>(&mut self, values: &mut [T]) {
98:         for index in (1..values.len()).rev() {
99:             let selected = self.index(index + 1);
100:             values.swap(index, selected);
101:         }
102:     }
103: 
104:     /// The input order must be authored or canonicalized by stable identity.
105:     pub fn weighted_index(&mut self, weights: &[u64]) -> Result<usize, SamplingError> {
106:         use rand::distr::weighted::Error;
107:         let distribution = WeightedIndex::<u64>::new(weights).map_err(|error| match error {
108:             Error::InvalidInput => SamplingError::EmptyCandidates,
109:             Error::InsufficientNonZero => SamplingError::ZeroTotalWeight,
110:             Error::Overflow => SamplingError::WeightOverflow,
111:             Error::InvalidWeight => unreachable!("u64 weights are nonnegative"),
112:             _ => unreachable!("pinned weighted sampler error"),
113:         })?;
114:         Ok(distribution.sample(&mut self.0))
115:     }
116: 
117:     /// Proportional draws without replacement; zero-weight entries are omitted.
118:     pub fn weighted_order(&mut self, weights: &[u64]) -> Result<Vec<usize>, SamplingError> {
119:         let mut remaining = weights.to_vec();
120:         let mut result = Vec::new();
121:         let count = remaining.iter().filter(|weight| **weight != 0).count();
122:         if count == 0 {
123:             return self.weighted_index(weights).map(|_| result);
124:         }
125:         for _ in 0..count {
126:             let index = self.weighted_index(&remaining)?;
127:             result.push(index);
128:             remaining[index] = 0;
129:         }
130:         Ok(result)
131:     }
132: }
133: 
134: fn sample_below(random: &mut impl RngCore, upper: NonZeroU64) -> u64 {
135:     Uniform::new(0_u64, upper.get())
136:         .expect("nonzero bound")
137:         .sample(random)
138: }
