1: //! Length-framed, domain-separated deterministic seeds.
2: 
3: const DERIVATION_CONTEXT: &str = "fabelgeist.determinism.seed.v1";
4: 
5: fn derivation_hasher(root: &[u8], stream: StreamId) -> blake3::Hasher {
6:     static BASE: std::sync::OnceLock<blake3::Hasher> = std::sync::OnceLock::new();
7:     let mut hasher = BASE
8:         .get_or_init(|| blake3::Hasher::new_derive_key(DERIVATION_CONTEXT))
9:         .clone();
10:     for field in [root, stream.0.as_bytes()] {
11:         hasher.update(&(field.len() as u64).to_le_bytes());
12:         hasher.update(field);
13:     }
14:     hasher
15: }
16: 
17: fn finish(hasher: blake3::Hasher) -> Seed {
18:     let mut seed = [0; 8];
19:     seed.copy_from_slice(&hasher.finalize().as_bytes()[..8]);
20:     Seed::from_u64(u64::from_le_bytes(seed))
21: }
22: 
23: /// A purpose owned by the caller, independent of other purposes' draw counts.
24: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
25: pub struct StreamId(&'static str);
26: 
27: impl StreamId {
28:     pub const fn new(name: &'static str) -> Self {
29:         assert!(!name.is_empty(), "random streams require a purpose name");
30:         Self(name)
31:     }
32: 
33:     /// Derive numeric context using fixed-width little-endian words.
34:     pub fn seed(self, root: Seed, context: &[u64]) -> Seed {
35:         let mut hasher = derivation_hasher(&root.to_le_bytes(), self);
36:         for value in context {
37:             let field = value.to_le_bytes();
38:             hasher.update(&(field.len() as u64).to_le_bytes());
39:             hasher.update(&field);
40:         }
41:         finish(hasher)
42:     }
43: 
44:     pub fn rng(self, root: Seed, context: &[u64]) -> crate::DeterministicRng {
45:         self.seed(root, context).rng()
46:     }
47: }
48: 
49: /// A deterministic root word, framed as eight little-endian bytes for sampling.
50: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq, serde::Serialize, serde::Deserialize)]
51: #[serde(deny_unknown_fields)]
52: #[cfg_attr(feature = "spacetimedb", derive(spacetimedb_sats::SpacetimeType))]
53: #[cfg_attr(feature = "spacetimedb", sats(crate = spacetimedb_sats))]
54: pub struct Seed {
55:     word: u64,
56: }
57: 
58: impl Seed {
59:     /// Derive from a root, named purpose, and ordered context fields.
60:     ///
61:     /// Numeric fields must use fixed-width little-endian encoding. Context
62:     /// ordinals must denote stable domain slots, never incidental iteration.
63:     pub fn derive(root: &[u8], stream: StreamId, context: &[&[u8]]) -> Self {
64:         let mut hasher = derivation_hasher(root, stream);
65:         for field in context {
66:             hasher.update(&(field.len() as u64).to_le_bytes());
67:             hasher.update(field);
68:         }
69:         finish(hasher)
70:     }
71: 
72:     /// A root word or an already derived seed at a serialization boundary.
73:     pub const fn from_u64(value: u64) -> Self {
74:         Self { word: value }
75:     }
76: 
77:     pub const fn to_u64(self) -> u64 {
78:         self.word
79:     }
80: 
81:     pub const fn to_le_bytes(self) -> [u8; 8] {
82:         self.word.to_le_bytes()
83:     }
84: 
85:     /// Visit an adjacent root word with the existing wrapping seed arithmetic.
86:     pub const fn wrapping_offset(self, offset: u64) -> Self {
87:         Self::from_u64(self.to_u64().wrapping_add(offset))
88:     }
89: 
90:     /// Apply a numeric bitmask at an owned seed arithmetic boundary.
91:     pub const fn xor_word(self, mask: u64) -> Self {
92:         Self::from_u64(self.to_u64() ^ mask)
93:     }
94: 
95:     /// Interpret the existing seed bits as `[0, 1)` without consuming a draw.
96:     pub fn unit_f32(self) -> f32 {
97:         crate::unit_f32(self.to_u64())
98:     }
99: 
100:     /// Interpret the existing seed bits as `[0, 1]` without consuming a draw.
101:     pub fn inclusive_unit_f32(self) -> f32 {
102:         crate::inclusive_unit_f32(self.to_u64())
103:     }
104: 
105:     /// Interpret the existing seed bits as `[0, 1)` without consuming a draw.
106:     pub fn unit_f64(self) -> f64 {
107:         crate::unit_f64(self.to_u64())
108:     }
109: 
110:     pub fn child(self, stream: StreamId, context: &[&[u8]]) -> Self {
111:         Self::derive(&self.to_le_bytes(), stream, context)
112:     }
113: 
114:     pub fn rng(self) -> crate::DeterministicRng {
115:         crate::DeterministicRng::new(self)
116:     }
117: }
118: 
119: // Preserve the canonical eight-byte hash input independently of record encoding.
120: impl std::hash::Hash for Seed {
121:     fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
122:         std::hash::Hash::hash(&self.to_le_bytes(), state);
123:     }
124: }
125: 
126: // Numeric ordering preserves the original word order of seed-keyed lattices.
127: impl Ord for Seed {
128:     fn cmp(&self, other: &Self) -> std::cmp::Ordering {
129:         self.to_u64().cmp(&other.to_u64())
130:     }
131: }
132: impl PartialOrd for Seed {
133:     fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
134:         Some(self.cmp(other))
135:     }
136: }
137: impl std::fmt::Display for Seed {
138:     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
139:         self.to_u64().fmt(formatter)
140:     }
141: }
142: impl std::fmt::LowerHex for Seed {
143:     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
144:         std::fmt::LowerHex::fmt(&self.to_u64(), formatter)
145:     }
146: }
147: impl std::str::FromStr for Seed {
148:     type Err = std::num::ParseIntError;
149: 
150:     fn from_str(word: &str) -> Result<Self, Self::Err> {
151:         word.parse().map(Self::from_u64)
152:     }
153: }
154: 
155: impl rand::distr::Distribution<Seed> for rand::distr::StandardUniform {
156:     fn sample<R: rand::Rng + ?Sized>(&self, random: &mut R) -> Seed {
157:         Seed::from_u64(random.random())
158:     }
159: }
160: 
161: // SpacetimeDB currently supplies its transaction RNG through Rand 0.8.
162: // Sampling a Seed consumes the same one-word draw as its native u64 output.
163: #[cfg(feature = "spacetimedb")]
164: impl rand08::distributions::Distribution<Seed> for rand08::distributions::Standard {
165:     fn sample<R: rand08::Rng + ?Sized>(&self, random: &mut R) -> Seed {
166:         Seed::from_u64(random.r#gen())
167:     }
168: }
169: 
170: impl From<u64> for Seed {
171:     fn from(word: u64) -> Self {
172:         Self::from_u64(word)
173:     }
174: }
