1: //! Animation visibility follows every active 3D view, including portrait cameras.
2: use super::*;
3: use bevy::camera::{
4:     primitives::{Frustum, Sphere},
5:     visibility::RenderLayers,
6: };
7: 
8: pub(super) type AnimationViews<'w, 's> = Query<
9:     'w,
10:     's,
11:     (
12:         &'static Camera,
13:         &'static GlobalTransform,
14:         &'static Frustum,
15:         Option<&'static RenderLayers>,
16:     ),
17:     With<Camera3d>,
18: >;
19: 
20: impl PoseBufferRig {
21:     /// Resume sampling after culling without changing authored display history.
22:     pub(super) fn resume_visible_sampling(&mut self) {
23:         if self.visibility == PoseVisibility::Frozen {
24:             self.sample_accumulator = AnimationElapsed::ZERO;
25:             self.interpolation_alpha = PoseInterpolation::ZERO;
26:             self.target_linear_velocities.fill(Vec3::ZERO);
27:             self.target_angular_velocities.fill(Vec3::ZERO);
28:         }
29:         self.visibility = PoseVisibility::Visible;
30:     }
31: }
32: 
33: pub(super) fn outside_views(
34:     position: Vec3,
35:     layers: Option<&RenderLayers>,
36:     views: &AnimationViews,
37: ) -> bool {
38:     let layers = layers.cloned().unwrap_or_default();
39:     let sphere = Sphere {
40:         center: position.into(),
41:         radius: pose_tuning().cull_radius_metres.metres(),
42:     };
43:     let mut has_view = false;
44:     for (camera, transform, frustum, camera_layers) in views {
45:         if !camera.is_active {
46:             continue;
47:         }
48:         has_view = true;
49:         if layers.intersects(&camera_layers.cloned().unwrap_or_default())
50:             && position.distance_squared(transform.translation())
51:                 <= pose_tuning().cull_distance_metres.metres().powi(2)
52:             && frustum.intersects_sphere(&sphere, false)
53:         {
54:             return false;
55:         }
56:     }
57:     has_view
58: }
