1: //! The pose buffer's boundary toward physics-driven poses.
2: //!
3: //! A ragdoll reads bodies back into `previous`/`next` so the same buffer
4: //! feeds rendering, the procedural passes, and, on exit, the ordinary
5: //! inertialized transition out of whatever tangle physics ended in.
6: 
7: use super::*;
8: use bevy::math::Affine3A;
9: 
10: impl PoseBufferRig {
11:     pub(in crate::animation) fn joint_count(&self) -> usize {
12:         self.definition.joints.len()
13:     }
14: 
15:     pub(in crate::animation) fn joint_role(&self, joint: RigJointOrdinal) -> Option<BoneRole> {
16:         self.definition.joints[joint].role
17:     }
18: 
19:     pub(in crate::animation) fn joint_parent(
20:         &self,
21:         joint: RigJointOrdinal,
22:     ) -> Option<RigJointOrdinal> {
23:         self.definition.joints[joint].parent
24:     }
25: 
26:     pub(in crate::animation) fn joint_entity(&self, joint: RigJointOrdinal) -> Option<Entity> {
27:         self.entities[joint]
28:     }
29: 
30:     pub(in crate::animation) fn previous_pose(&self, joint: RigJointOrdinal) -> LocalPose {
31:         self.previous[joint]
32:     }
33: 
34:     pub(in crate::animation) fn upcoming_pose(&self, joint: RigJointOrdinal) -> LocalPose {
35:         self.next[joint]
36:     }
37: 
38:     /// The pose the renderer shows this frame, inertial offset included.
39:     pub(in crate::animation) fn displayed_pose(&self, joint: RigJointOrdinal) -> LocalPose {
40:         let pose =
41:             self.previous[joint].interpolate(self.next[joint], self.interpolation_alpha.amount());
42:         if self.inertial_state == InertialState::Settled {
43:             pose
44:         } else {
45:             self.offsets[joint].peek(pose)
46:         }
47:     }
48: 
49:     pub(in crate::animation) fn is_frozen(&self) -> bool {
50:         self.visibility == PoseVisibility::Frozen
51:     }
52: 
53:     pub(in crate::animation) fn is_physics_owned(&self) -> bool {
54:         self.ownership == PoseOwnership::Physics
55:     }
56: 
57:     /// Hand the buffer to physics or back to authored sampling. Returning it forces the next update to capture a
58:     /// transition out of the physics pose, even if the plan is unchanged.
59:     pub(in crate::animation) fn set_ownership(&mut self, ownership: PoseOwnership) {
60:         if self.ownership == PoseOwnership::Physics && ownership == PoseOwnership::Authored {
61:             self.plan = None;
62:         }
63:         self.ownership = ownership;
64:     }
65: 
66:     /// Physics owns this joint: both buffered samples become `pose`, and any
67:     /// in-flight transition on it is dropped so the bone lands exactly on
68:     /// its body.
69:     pub(in crate::animation) fn pin_joint(&mut self, joint: RigJointOrdinal, pose: LocalPose) {
70:         self.previous[joint] = pose;
71:         self.next[joint] = pose;
72:         self.offsets[joint] = JointInertialOffset::default();
73:         self.target_linear_velocities[joint] = Vec3::ZERO;
74:         self.target_angular_velocities[joint] = Vec3::ZERO;
75:     }
76: 
77:     /// An undriven ancestor of a driven joint: hold exactly `next`, with no
78:     /// interpolation or offset displacing it, so the driven descendants'
79:     /// derived locals compose back onto their bodies.
80:     pub(in crate::animation) fn hold_joint(&mut self, joint: RigJointOrdinal) {
81:         let held = self.next[joint];
82:         self.pin_joint(joint, held);
83:     }
84: 
85:     /// Seconds between the two buffered samples, for finite-difference
86:     /// velocities.
87:     pub(in crate::animation) fn sample_interval(
88:         &self,
89:     ) -> adventuresim_tactical_core::animation::PositiveAnimationDuration {
90:         pose_sample_interval()
91:     }
92: }
93: 
94: impl LocalPose {
95:     pub(in crate::animation) fn affine(self) -> Affine3A {
96:         Affine3A::from_scale_rotation_translation(self.scale, self.rotation, self.translation)
97:     }
98: }

