491:             Ok(elapsed) => elapsed,
492:             Err(error) => {
493:                 warn!(%error, "Rejected pose-buffer accumulator");
494:                 continue;
495:             }
496:         };
497:         let Some(mut sampled) = sample_character_plan(
498:             playback,
499:             &rig,
500:             &clips,
501:             &mut bank,
502:             &mut metrics,
503:             &proportion_offsets,
504:         ) else {
505:             continue;
506:         };
