513:             // Buffered joint poses are relative to the authored scene, not to
514:             // the controller entity. The scene is translated from the
515:             // capsule's centre to the character's visual ground origin.
516:             // Omitting that transform makes every sampled ankle appear about
517:             // one capsule half-height too high and disables terrain contact.
518:             let presentation_transform = rig_scenes
