84: impl AnimationPlayback {
85:     pub(crate) fn authored_pose_is_ready(&self) -> bool {
86:         !self.plan.is_bind()
87:     }
88: 
89:     pub(crate) fn presentation_is_settled(&self) -> bool {
90:         self.authored_pose_is_ready()
91:     }
92: 
93:     pub(super) fn from_presented_pose(
94:         skeleton: &SkeletonState,
95:         target: PlaybackPose,
96:         movement_speed: NonnegativeSpeed,
97:     ) -> Self {
98:         let active = ordinary_locomotion_candidate(skeleton)
99:             && movement_speed > playback_tuning().initial_locomotion_speed_metres_per_second;
100:         Self {
101:             plan: target.plan,
102:             whole_body_mirror: target.whole_body_mirror,
103:             foot_ik_weights: target.foot_ik_weights,
104:             weapon_guard: skeleton.weapon_guard(),
105:             ordinary_locomotion: OrdinaryLocomotion::from_candidate(active),
106:             cadence: target.cadence,
107:         }
108:     }
109: 
110:     pub(super) fn apply_presented_pose(
111:         &mut self,
112:         skeleton: &SkeletonState,
113:         target: PlaybackPose,
114:         movement_speed: NonnegativeSpeed,
115:     ) {
116:         // Hysteresis prevents sub-threshold velocity noise from repeatedly
117:         // restarting the idle/locomotion presentation transition.
118:         let threshold = if self.ordinary_locomotion == OrdinaryLocomotion::Active {
119:             playback_tuning().locomotion_deactivation_speed_metres_per_second
120:         } else {
121:             playback_tuning().locomotion_activation_speed_metres_per_second
122:         };
123:         let active = ordinary_locomotion_candidate(skeleton) && movement_speed > threshold;
124:         self.weapon_guard = skeleton.weapon_guard();
125:         self.ordinary_locomotion = OrdinaryLocomotion::from_candidate(active);
126:         apply_playback_pose(self, target);
127:     }
128: 
129:     pub(super) fn sampling_cadence(&self) -> PoseSamplingCadence {
130:         if self.cadence == PoseSamplingCadence::Buffered
131:             && self.plan.extrapolated().is_empty()
132:             && self.plan.continuations().is_empty()
133:         {
134:             PoseSamplingCadence::Buffered
135:         } else {
136:             // Every action segment follows the authoritative action phase.
137:             // Switching only its simple spans back to the 30 Hz clip grid
138:             // aliases fast weapon motion and creates a cadence discontinuity.
139:             PoseSamplingCadence::Direct
140:         }
141:     }
142: }
143: 
144: impl Default for AnimationPlayback {
145:     fn default() -> Self {
146:         Self {
147:             plan: PlaybackContributions::default(),
148:             whole_body_mirror: UnitInterval::ZERO,
149:             foot_ik_weights: FootIkInfluence::NONE,
150:             weapon_guard: WeaponGuardState::Lowered,
151:             ordinary_locomotion: OrdinaryLocomotion::Inactive,
152:             cadence: PoseSamplingCadence::Buffered,
153:         }
154:     }
155: }
