126:     /// Preserve the first occurrence when a rig contains duplicate labels.
127:     pub fn index_in<'a>(
128:         &self,
129:         names: impl IntoIterator<Item = &'a Self>,
130:     ) -> Option<RigJointOrdinal> {
131:         names
132:             .into_iter()
