139:     ) -> Result<RigJointOrdinal, RigJointLookupError> {
140:         self.index_in(names).ok_or_else(|| -> RigJointLookupError {
141:             RigJointLookupError {
142:                 joint: self.clone(),
143:             }
144:         })
145:     }
146: }
