107: /// Tools can render gameplay, side, and front views from one logical sample.
108: /// Preserve the first complete post-procedural local pose for that fixed tick
109: /// and restore it before propagation on every repeated render. Live gameplay
110: /// leaves the fixed clock unset and never enters this path.
111: pub(super) fn stabilize_repeated_fixed_tick_pose(
112:     clock: Res<ProceduralAnimationClock>,
113:     mut cache: ResMut<FixedTickPoseCache>,
114:     mut bones: Query<(Entity, &mut Transform), With<MhrBone>>,
115: ) {
116:     let Some(FixedAnimationStep { tick, .. }) = clock.fixed_step() else {
117:         cache.tick = None;
118:         cache.bones.clear();
119:         return;
120:     };
121:     if cache.tick != Some(tick) {
122:         cache.tick = Some(tick);
123:         cache.bones.clear();
124:         cache.bones.extend(
125:             bones
126:                 .iter_mut()
127:                 .map(|(entity, transform)| (entity, *transform)),
128:         );
129:         return;
130:     }
131:     for (entity, mut transform) in &mut bones {
132:         if let Some(cached) = cache.bones.get(&entity) {
133:             *transform = *cached;
134:         }
135:     }
136: }
