157: pub(super) fn apply_head_and_torso_look(
158:     mut commands: Commands,
159:     owners: Query<(Entity, &CharacterLook, &PresentedSkeleton)>,
160:     mut transforms: ParamSet<(
161:         Query<&Transform>,
162:         Query<(
163:             Entity,
164:             &HumanoidBone,
165:             &mut Transform,
166:             Option<&mut ProceduralLookState>,
167:         )>,
168:     )>,
169: ) {
170:     let owner_look = owners
171:         .iter()
172:         .filter_map(|(owner, look, skeleton)| {
173:             // This pass runs before transform propagation. GlobalTransform is
174:             // therefore one frame behind the current replicated root and
175:             // would reapply that root yaw across the neck chain.
176:             let owner_rotation = transforms.p0().get(owner).ok()?.rotation;
177:             Some((
178:                 owner,
179:                 (
180:                     guarded_camera_look(
181:                         look,
182:                         owner_rotation,
183:                         skeleton.weapon_guard(),
184:                         skeleton.posture_transition(),
185:                     ),
186:                     skeleton.action_direction().x.clamp(-1.0, 1.0) * 0.35,
187:                 ),
188:             ))
189:         })
190:         .collect::<BTreeMap<_, _>>();
191:     for (entity, bone, mut transform, state) in &mut transforms.p1() {
192:         let Some(&(aim, directional_yaw)) = owner_look.get(&bone.owner) else {
193:             continue;
194:         };
195:         let weight = match bone.role {
196:             BoneRole::StomachOne => 0.08,
197:             BoneRole::StomachTwo => 0.12,
198:             BoneRole::StomachThree => 0.16,
199:             BoneRole::Chest => 0.18,
200:             BoneRole::NeckOne => 0.2,
201:             BoneRole::Head => 0.26,
202:             _ => continue,
203:         };
204:         let aim_offset = match (aim, bone.role) {
205:             (Some(offset), BoneRole::NeckOne | BoneRole::Head) => offset,
206:             _ => Vec2::ZERO,
207:         };
208:         // Owner yaw is already on the character transform. Only the bounded
209:         // residual camera direction and local action offset are distributed
210:         // here. Camera pitch belongs exclusively to held aim/block; ordinary
211:         // camera look must not nod the presented head and neck.
212:         let offset = Quat::from_euler(
213:             EulerRot::YXZ,
214:             directional_yaw * weight + aim_offset.x,
215:             aim_offset.y,
216:             0.0,
217:         );
218:         let (rotation, next) = additive_look_rotation(transform.rotation, offset);
219:         transform.rotation = rotation;
220:         if let Some(mut state) = state {
221:             *state = next;
222:         } else {
223:             commands.entity(entity).insert(next);
224:         }
225:     }
226: }
