228: /// Space begins an upright jump with a small procedural anticipation rather
229: /// than launching on the press edge. FK remains authored; this layer lowers
230: /// the pelvis and shares a modest forward fold across the spine.
231: pub(super) fn apply_jump_anticipation(
232:     mut commands: Commands,
233:     owners: Query<&PresentedSkeleton>,
234:     mut bones: Query<(
235:         Entity,
236:         &HumanoidBone,
237:         &mut Transform,
238:         Option<&mut ProceduralJumpAnticipationState>,
239:     )>,
240: ) {
241:     for (entity, bone, mut transform, state) in &mut bones {
242:         let Ok(skeleton) = owners.get(bone.owner) else {
243:             continue;
244:         };
245:         let charging =
246:             skeleton.jump_anticipation() == JumpAnticipation::Charging && !skeleton.is_quickstep();
247:         let previous = state.as_deref().copied();
248:         let base = previous.map_or(*transform, |previous| {
249:             if previous.evaluation_tick == skeleton.locomotion_sample_tick
250:                 || transform
251:                     .translation
252:                     .abs_diff_eq(previous.applied.translation, 0.000_01)
253:                     && transform.rotation.angle_between(previous.applied.rotation) <= 0.000_01
254:             {
255:                 previous.base
256:             } else {
257:                 *transform
258:             }
259:         });
260:         let previous_amount = previous.map_or(0.0, |previous| previous.amount);
261:         let previous_pelvis_amount = previous.map_or(0.0, |previous| previous.pelvis_amount);
262:         let amount = if skeleton.is_quickstep() {
263:             0.0
264:         } else if previous
265:             .is_some_and(|previous| previous.evaluation_tick == skeleton.locomotion_sample_tick)
266:         {
267:             previous_amount
268:         } else {
269:             let target = charging as u8 as f32;
270:             previous_amount + (target - previous_amount).clamp(-0.125, 0.125)
271:         };
272:         let pelvis_amount = if skeleton.is_quickstep() {
273:             0.0
274:         } else if previous
275:             .is_some_and(|previous| previous.evaluation_tick == skeleton.locomotion_sample_tick)
276:         {
277:             previous_pelvis_amount
278:         } else {
279:             let target =
280:                 jump_charge_pelvis_target(skeleton.jump_anticipation(), skeleton.weapon_guard());
281:             previous_pelvis_amount + (target - previous_pelvis_amount).clamp(-0.125, 0.125)
282:         };
283:         let mut applied = base;
284:         if amount > 0.0 {
285:             match bone.role {
286:                 BoneRole::Pelvis => applied.translation.y -= 0.12 * pelvis_amount,
287:                 BoneRole::StomachOne => {
288:                     applied.rotation =
289:                         (applied.rotation * Quat::from_rotation_x(0.075 * amount)).normalize()
290:                 }
291:                 BoneRole::StomachTwo => {
292:                     applied.rotation =
293:                         (applied.rotation * Quat::from_rotation_x(0.06 * amount)).normalize()
294:                 }
295:                 BoneRole::StomachThree => {
296:                     applied.rotation =
297:                         (applied.rotation * Quat::from_rotation_x(0.05 * amount)).normalize()
298:                 }
299:                 BoneRole::Chest => {
300:                     applied.rotation =
301:                         (applied.rotation * Quat::from_rotation_x(0.04 * amount)).normalize()
302:                 }
303:                 _ => continue,
304:             }
305:         } else if !matches!(
306:             bone.role,
307:             BoneRole::Pelvis
308:                 | BoneRole::StomachOne
309:                 | BoneRole::StomachTwo
310:                 | BoneRole::StomachThree
311:                 | BoneRole::Chest
312:         ) {
313:             continue;
314:         }
315:         *transform = applied;
316:         let next = ProceduralJumpAnticipationState {
317:             base,
318:             applied,
319:             amount,
320:             pelvis_amount,
321:             evaluation_tick: skeleton.locomotion_sample_tick,
322:         };
323:         if let Some(mut state) = state {
324:             *state = next;
325:         } else {
326:             commands.entity(entity).insert(next);
327:         }
328:     }
329: }
