331: /// Applies whole-body reflection for same-pack semantic pose fallbacks.
332: /// Ordinary gait parity is already baked into distinct endpoint clips before
333: /// FK blending and must never pass through this post-blend operation.

334: pub(super) fn apply_pose_mirroring(
335:     playbacks: Query<&AnimationPlayback>,
336:     rigs: Query<(Entity, &HumanoidRig)>,
337:     parents: Query<&ChildOf>,
338:     mut transforms: ParamSet<(Query<&Transform>, TransformHelper, Query<&mut Transform>)>,
339: ) {
340:     for (owner, topology) in &rigs {
341:         let Ok(playback) = playbacks.get(owner) else {
342:             continue;
343:         };
344:         let whole_body_weight = playback.whole_body_mirror;
345:         if whole_body_weight == UnitInterval::ZERO {
346:             continue;
347:         }
348:         let Some(rig_scene) = topology.rig_scene() else {
349:             continue;
350:         };
351:         let mirror_entities = topology
352:             .mirror_centers()
353:             .iter()
354:             .copied()
355:             .chain(
356:                 topology
357:                     .mirror_pairs()
358:                     .iter()
359:                     .flat_map(|pair| [pair.left, pair.right]),
360:             )
361:             .collect::<Vec<_>>();
362:         let local_snapshots = {
363:             let locals = transforms.p0();
364:             mirror_entities
365:                 .iter()
366:                 .filter_map(|&entity| Some((entity, *locals.get(entity).ok()?)))
367:                 .collect::<Vec<_>>()
368:         };
369:         let (rig, rig_global) = {
370:             let helper = transforms.p1();
371:             let Ok(rig_global) = helper.compute_global_transform(rig_scene) else {
372:                 continue;
373:             };
374:             let mut rig = BTreeMap::new();
375:             for (entity, local) in local_snapshots {
376:                 let Ok(global) = helper.compute_global_transform(entity) else {
377:                     continue;
378:                 };
379:                 let parent = parents.get(entity).ok().map(ChildOf::parent);
380:                 let parent_global = parent
381:                     .and_then(|parent| helper.compute_global_transform(parent).ok())
382:                     .unwrap_or(GlobalTransform::IDENTITY);
383:                 rig.insert(
384:                     entity,
385:                     MirrorBone {
386:                         entity,
387:                         local,
388:                         global,
389:                         parent,
390:                         parent_global,
391:                     },
392:                 );
393:             }
394:             (rig, rig_global)
395:         };
396:         let mut desired_globals = BTreeMap::<Entity, Affine3A>::new();
397:         let mut mirror_weights = BTreeMap::<Entity, UnitInterval>::new();
398:         for &entity in topology.mirror_centers() {
399:             let Some(bone) = rig.get(&entity) else {
400:                 continue;
401:             };
402:             desired_globals.insert(bone.entity, mirrored_global_affine(bone.global, rig_global));
403:             mirror_weights.insert(bone.entity, whole_body_weight);
404:         }
405:         for pair in topology.mirror_pairs() {
406:             let (Some(left), Some(right)) = (rig.get(&pair.left), rig.get(&pair.right)) else {
407:                 continue;
408:             };
409:             desired_globals.insert(
410:                 left.entity,
411:                 mirrored_global_affine(right.global, rig_global),
412:             );
413:             desired_globals.insert(
414:                 right.entity,
415:                 mirrored_global_affine(left.global, rig_global),
416:             );
417:             mirror_weights.insert(left.entity, whole_body_weight);
418:             mirror_weights.insert(right.entity, whole_body_weight);
419:         }
420:         let mut bones = transforms.p2();
421:         for bone in rig.values() {
422:             let Some(&desired_global) = desired_globals.get(&bone.entity) else {
423:                 continue;
424:             };
425:             let Some(&weight) = mirror_weights.get(&bone.entity) else {
426:                 continue;
427:             };
428:             if weight == UnitInterval::ZERO {
429:                 continue;
430:             }
431:             let desired_parent = bone
432:                 .parent
433:                 .and_then(|parent| desired_globals.get(&parent).copied())
434:                 .unwrap_or_else(|| bone.parent_global.affine());
435:             let (scale, rotation, translation) =
436:                 (desired_parent.inverse() * desired_global).to_scale_rotation_translation();
437:             if !translation.is_finite() || !rotation.is_finite() || !scale.is_finite() {
438:                 continue;
439:             }
440:             if let Ok(mut transform) = bones.get_mut(bone.entity) {
441:                 transform.translation = bone.local.translation.lerp(translation, weight.fraction());
442:                 transform.rotation = bone.local.rotation.slerp(rotation, weight.fraction());
443:                 transform.scale = bone.local.scale.lerp(scale, weight.fraction());
444:             }
445:         }
446:     }
447: }
