458: ) {
459:     let mut heights = BTreeMap::new();
460:     for (owner, skeleton, state) in &mut owners {
461:         let current = state.as_deref().copied().unwrap_or_default();
462:         let next = match current.advance_height(skeleton) {
463:             Ok(next) => next,
464:             Err(error) => {
465:                 warn!(%error, ?owner, "Rejected locomotion height sample");
466:                 continue;
467:             }
468:         };
469:         if !skeleton.is_quickstep() {
470:             heights.insert(owner, next);
471:         }
472:         if let Some(mut state) = state {
473:             *state = next;
474:         } else {
475:             commands.entity(owner).insert(next);
476:         }
477:     }
478:     for (bone, mut transform) in &mut bones {
479:         let Some(height) = heights.get(&bone.owner) else {
480:             continue;
481:         };
482:         if height.displayed_wave.metres() == 0.0 {
483:             continue;
484:         }
485:         if bone.role == BoneRole::Root {
486:             let translated_y = transform.translation.y + height.displayed_wave.metres();
487:             if !translated_y.is_finite() {
488:                 warn!(error = %AnimationValueError::Overflow { quantity: AnimationQuantity::HeightOffset }, owner = ?bone.owner, "Rejected root height displacement");
489:                 continue;
490:             }
491:             transform.translation.y = translated_y;
492:         }
493:     }
494: }
495: 
496: /// Turns authored walk/run legs into the movement direction while preserving
497: /// the weapon layer's world-facing torso. The pelvis owns the yaw and the
498: /// first spine bone cancels it, so descendants on either side of the layer
499: /// boundary remain independent.
500: pub(super) fn orient_guarded_run_lower_body(
501:     owners: Query<&PresentedSkeleton>,
502:     rigs: Query<(Entity, &HumanoidRig)>,
503:     mut transforms: Query<&mut Transform>,
504: ) {
505:     for (owner, rig) in &rigs {
506:         let Ok(skeleton) = owners.get(owner) else {
507:             continue;
508:         };
509:         if skeleton.is_quickstep()
510:             || !skeleton.is_guarded_sprinting()
511:             || !skeleton.raised_locomotion().is_moving()
512:         {
513:             continue;
514:         }
515:         let direction = skeleton.raised_locomotion().local_direction();
516:         let Some((pelvis_yaw, spine_counter_yaw)) = guarded_run_split_yaw(direction) else {
517:             continue;
518:         };
519:         let (Some(&pelvis), Some(&spine)) =
520:             (rig.get(&BoneRole::Pelvis), rig.get(&BoneRole::StomachOne))
521:         else {
522:             continue;
523:         };
524:         let Ok([mut pelvis, mut spine]) = transforms.get_many_mut([pelvis, spine]) else {
525:             continue;
526:         };
527:         pelvis.rotation = (pelvis.rotation * pelvis_yaw).normalize();
528:         spine.rotation = (spine_counter_yaw * spine.rotation).normalize();
529:     }
530: }
531: 
532: /// Preserves both world-space feet during the short landing-only pelvis
533: /// compression by flexing the actual hip/knee chains. This is independent of
534: /// the opt-in terrain solver and never translates or stretches thigh roots.
535: pub(super) fn apply_landing_leg_compression(
536:     mut owners: Query<
537:         (
538:             &PresentedSkeleton,
539:             &mut LocomotionHeightState,
540:             &GlobalTransform,
541:         ),
542:         Without<HumanoidBone>,
543:     >,
544:     rigs: Query<(Entity, &HumanoidRig)>,
545:     bones: Query<(Entity, &GlobalTransform), With<HumanoidBone>>,
546:     parents: Query<&ChildOf>,
547:     mut transforms: ParamSet<(TransformHelper, Query<&mut Transform>)>,
548: ) {
549:     let _spike = crate::animation::diagnostics::SpikeGuard::new("apply_landing_leg_compression");
550:     // Built on first use: the guards below reject every rig on frames where
551:     // nobody is landing, and `GlobalTransform` is stable until propagation.
552:     let mut previous_world_positions: Option<BTreeMap<Entity, Vec3>> = None;
553:     for (owner, rig) in &rigs {
554:         let Ok((skeleton, mut height, owner_transform)) = owners.get_mut(owner) else {
555:             continue;
556:         };
557:         if !height.supports_foot_plants(skeleton) {
558:             clear_landing_foot_plants(&mut height);
559:             continue;
560:         }
561:         let owner_position = owner_transform.translation();
562:         if height.landing_plant_resync_tick == Some(skeleton.locomotion_sample_tick) {
563:             continue;
564:         }
565:         height.landing_plant_resync_tick = None;
566:         let discontinuous = landing_plant_is_discontinuous(
567:             height.landing_plant_tick,
568:             skeleton.locomotion_sample_tick,
569:             height.landing_plant_owner_position,
570:             owner_position,
571:         );
572:         if discontinuous {
573:             clear_landing_foot_plants(&mut height);
574:             height.landing_plant_resync_tick = Some(skeleton.locomotion_sample_tick);
575:             continue;
576:         }
577:         height.landing_plant_tick = Some(skeleton.locomotion_sample_tick);
578:         height.landing_plant_owner_position = Some(owner_position);
579:         // Native root-local displacement enters the skeletal vector kernel here.
580:         let landing_compression = height.landing_compression;
581:         height.apply_landing_pelvis_compression(rig, &parents, &mut transforms);
582:         for (upper_role, lower_role, foot_role, foot_side) in [
583:             (
584:                 BoneRole::ThighLeft,
585:                 BoneRole::ShinLeft,
586:                 BoneRole::FootLeft,
587:                 LeadFoot::Left,
588:             ),
589:             (
590:                 BoneRole::ThighRight,
591:                 BoneRole::ShinRight,
592:                 BoneRole::FootRight,
593:                 LeadFoot::Right,
594:             ),
595:         ] {
596:             let (Some(&upper), Some(&lower), Some(&foot)) = (
597:                 rig.get(&upper_role),
598:                 rig.get(&lower_role),
599:                 rig.get(&foot_role),
600:             ) else {
601:                 continue;
602:             };
603:             let Some((upper_snapshot, lower_snapshot, foot_snapshot)) =
604:                 snapshot_chain(upper, lower, foot, &parents, &transforms.p0())
605:             else {
606:                 continue;
607:             };
608:             let LimbSegments {
609:                 upper: upper_length,
610:                 lower: lower_length,
611:             } = match LimbSegments::measure(
612:                 upper_snapshot.global.translation(),
613:                 lower_snapshot.global.translation(),
614:                 foot_snapshot.global.translation(),
615:             ) {
616:                 Ok(segments) => segments,
617:                 Err(error) => {
618:                     warn!(%error, "landing segment measurement rejected");
619:                     continue;
620:                 }
621:             };
622:             let retained_target = match foot_side {
623:                 LeadFoot::Left => &mut height.landing_left_foot_target,
624:                 LeadFoot::Right => &mut height.landing_right_foot_target,
625:             };
626:             let landing_snapshot = previous_world_positions
627:                 .get_or_insert_with(|| bones.iter().map(|(e, g)| (e, g.translation())).collect());
628:             let target = retain_landing_foot_target(retained_target, landing_snapshot[&foot]);
629:             let side = match foot_side {
630:                 LeadFoot::Left => FootTrackSide::NegativeX,
631:                 LeadFoot::Right => FootTrackSide::PositiveX,
632:             };
633:             let pole = owner_transform.rotation() * canonical_knee_pole(side);
634:             let pole = constrain_rendered_leg_pole(
635:                 rig,
636:                 foot_side,
637:                 upper_snapshot.global.translation(),
638:                 foot_snapshot.global.translation(),
639:                 target,
640:                 pole,
641:                 &parents,
642:                 &transforms.p0(),
643:             );
644:             let solution = match solve_landing_two_bone(
645:                 TwoBoneChain::new(
646:                     upper_snapshot.global.translation(),
647:                     lower_snapshot.global.translation(),
648:                     foot_snapshot.global.translation(),
649:                     upper_length,
650:                     lower_length,
651:                     pole,
652:                 ),
653:                 target,
654:                 landing_compression,
655:             ) {
656:                 Ok(solution) => solution,
657:                 Err(error) => {
658:                     warn!(%error, "landing geometry rejected");
659:                     continue;
660:                 }
661:             };
662:             if let Some(solution) = solution {
663:                 apply_two_bone_solution(upper, lower, foot, solution, &parents, &mut transforms);
664:             }
665:         }
666:     }
667: }
