669: fn procedural_tuning() -> ProceduralAnimationConfig {
670:     runtime_animation_config().procedural
671: }
672: 
673: fn additive_look_rotation(current: Quat, offset: Quat) -> (Quat, ProceduralLookState) {
674:     let applied_rotation = (current * offset).normalize();
675:     (
676:         applied_rotation,
677:         ProceduralLookState {
678:             base_rotation: current,
679:         },
680:     )
681: }
682: 
683: fn guarded_camera_look(
684:     look: &CharacterLook,
685:     owner_rotation: Quat,
686:     weapon_guard: WeaponGuardState,
687:     posture_transition: Option<PostureTransitionState>,
688: ) -> Option<Vec2> {
689:     (weapon_guard == WeaponGuardState::Raised && posture_transition.is_none())
690:         .then(|| constrained_camera_look(look, owner_rotation))
691: }
692: 
693: fn constrained_camera_look(look: &CharacterLook, owner_rotation: Quat) -> Vec2 {
694:     let tuning = procedural_tuning();
695:     let joint_limit = tuning.guarded_look_joint_limit_degrees.radians();
696:     let camera_forward = Quat::from_euler(EulerRot::YXZ, look.yaw, look.pitch, 0.0) * Vec3::NEG_Z;
697:     let local = owner_rotation.inverse() * camera_forward;
698:     // Directly behind the body there is no anatomically preferable left/right
699:     // twist. Using signed Z puts atan2's branch cut at exactly that ambiguous
700:     // direction and can flip the neck chain between both joint limits. Fold
701:     // the rear hemisphere onto neutral instead: side look remains signed and
702:     // continuous, while a camera directly behind leaves the neck untwisted.
703:     let yaw = local.x.atan2(local.z.abs());
704:     let pitch = local.y.atan2(local.xz().length());
705:     Vec2::new(
706:         tuning
707:             .guarded_look_joint_count
708:             .distribute_radians(yaw)
709:             .clamp(-joint_limit, joint_limit),
710:         tuning
711:             .guarded_look_joint_count
712:             .distribute_radians(pitch)
713:             .clamp(-joint_limit, joint_limit),
714:     )
715: }
716: 
717: fn jump_charge_pelvis_target(anticipation: JumpAnticipation, guard: WeaponGuardState) -> f32 {
718:     (anticipation == JumpAnticipation::Charging && guard == WeaponGuardState::Lowered) as u8 as f32
719: }
720: 
721: /// Split local travel yaw between the pelvis and its inverse leg compensation.
722: fn guarded_run_split_yaw(direction: Vec2) -> Option<(Quat, Quat)> {
723:     let direction = direction.try_normalize()?;
724:     // Local movement uses -Y for character-forward, corresponding to -Z in
725:     // the authored rig. Positive X is character-right.
726:     let angle = -direction.x.atan2(-direction.y);
727:     let pelvis = Quat::from_rotation_y(angle);
728:     Some((pelvis, pelvis.inverse()))
729: }
730: 
731: fn retain_landing_foot_target(
732:     retained: &mut Option<Vec3>,
733:     pre_landing_foot_position: Vec3,
734: ) -> Vec3 {
735:     *retained.get_or_insert(pre_landing_foot_position)
736: }
737: 
738: fn landing_plant_is_discontinuous(
739:     previous_tick: Option<AnimationSampleTick>,
740:     current_tick: AnimationSampleTick,
741:     previous_owner_position: Option<Vec3>,
742:     current_owner_position: Vec3,
743: ) -> bool {
744:     presentation_tick_delta(previous_tick, current_tick).is_none()
745:         || previous_owner_position
746:             .is_some_and(|previous| previous.distance_squared(current_owner_position) > 4.0)
747: }
748: 
749: fn mirrored_global_affine(source: GlobalTransform, owner: GlobalTransform) -> Affine3A {
750:     let owner_affine = owner.affine();
751:     let relative = owner_affine.inverse() * source.affine();
752:     let (scale, rotation, translation) = relative.to_scale_rotation_translation();
753:     let mirrored = mirrored_across_anatomical_center(Transform {
754:         translation,
755:         rotation,
756:         scale,
757:     });
758:     owner_affine * mirrored.compute_affine()
759: }
760: 
761: fn mirrored_across_anatomical_center(mut transform: Transform) -> Transform {
762:     transform.translation.x = -transform.translation.x;
763:     let rotation = transform.rotation;
764:     transform.rotation = Quat::from_xyzw(rotation.x, -rotation.y, -rotation.z, rotation.w);
765:     transform
766: }
