211: impl LocalPose {
212:     fn from_transform(transform: Transform) -> Self {
213:         Self {
214:             translation: transform.translation,
215:             rotation: transform.rotation,
216:             scale: transform.scale,
217:         }
218:     }
219: 
220:     fn interpolate(self, next: Self, alpha: UnitInterval) -> Self {
221:         let alpha = alpha.fraction().clamp(0.0, 1.0);
222:         Self {
223:             translation: self.translation.lerp(next.translation, alpha),
224:             rotation: hemisphere_slerp(self.rotation, next.rotation, alpha),
225:             scale: self.scale.lerp(next.scale, alpha),
226:         }
227:     }
228: 
229:     fn extrapolate(self, next: Self, coordinate: AttackPoseCoordinate) -> Self {
230:         let coordinate = coordinate.clamped_to_curve().coordinate();
231:         self.extrapolate_unbounded(next, coordinate)
232:     }
233: 
234:     fn extrapolate_unbounded(self, next: Self, coordinate: f32) -> Self {
235:         let relative = shortest_rotation(next.rotation * self.rotation.inverse());
236:         Self {
237:             translation: self.translation + (next.translation - self.translation) * coordinate,
238:             rotation: (quaternion_exp(quaternion_log(relative) * coordinate) * self.rotation)
239:                 .normalize(),
240:             scale: self.scale + (next.scale - self.scale) * coordinate,
241:         }
242:     }
243: 
244:     fn continuation_transition(
245:         self,
246:         transition: ContinuationTransition,
247:         progress: UnitInterval,
248:     ) -> Self {
249:         let start = self.extrapolate(transition.contact, transition.start_coordinate);
250:         // The complete native spline consumes phase knots, normalized progress
251:         // and an attack-coordinate derivative; checked roles end at this kernel.
252:         let progress = progress.fraction().clamp(0.0, 1.0);
253:         let ready_phase = transition.ready_phase.phase();
254:         let knots = [0.0, ready_phase, 0.5, 1.0];
255:         let incoming_scale = transition.incoming_tangent.coordinate_delta() / ready_phase;
256:         let rotation_values = [
257:             Vec3::ZERO,
258:             quaternion_log(shortest_rotation(
259:                 transition.ready.rotation * start.rotation.inverse(),
260:             )),
261:             quaternion_log(shortest_rotation(
262:                 transition.outgoing.rotation * start.rotation.inverse(),
263:             )),
264:             quaternion_log(shortest_rotation(
265:                 transition.finish.rotation * start.rotation.inverse(),
266:             )),
267:         ];
268:         Self {
269:             translation: clamped_cubic_spline_vec3(
270:                 knots,
271:                 [
272:                     start.translation,
273:                     transition.ready.translation,
274:                     transition.outgoing.translation,
275:                     transition.finish.translation,
276:                 ],
277:                 (transition.contact.translation - self.translation) * incoming_scale,
278:                 Vec3::ZERO,
279:                 progress,
280:             ),
281:             rotation: (quaternion_exp(clamped_cubic_spline_vec3(
282:                 knots,
283:                 rotation_values,
284:                 quaternion_log(shortest_rotation(
285:                     transition.contact.rotation * self.rotation.inverse(),
286:                 )) * incoming_scale,
287:                 Vec3::ZERO,
288:                 progress,
289:             )) * start.rotation)
290:                 .normalize(),
291:             scale: clamped_cubic_spline_vec3(
292:                 knots,
293:                 [
294:                     start.scale,
295:                     transition.ready.scale,
296:                     transition.outgoing.scale,
297:                     transition.finish.scale,
298:                 ],
299:                 (transition.contact.scale - self.scale) * incoming_scale,
300:                 Vec3::ZERO,
301:                 progress,
302:             ),
303:         }
304:     }
305: }
