307: impl PosePlanKey {
308:     fn from_playback(playback: &AnimationPlayback) -> Self {
309:         let mut clips = playback
310:             .plan
311:             .clips()
312:             .iter()
313:             .map(|weighted| (weighted.clip.handle.id(), weighted.clip.layer))
314:             .collect::<Vec<_>>();
315:         clips.extend(playback.plan.extrapolated().iter().flat_map(|span| {
316:             [
317:                 (span.start.handle.id(), span.start.layer),
318:                 (span.end.handle.id(), span.end.layer),
319:             ]
320:         }));
321:         clips.extend(playback.plan.continuations().iter().flat_map(|span| {
322:             [
323:                 (span.start.handle.id(), span.start.layer),
324:                 (span.contact.handle.id(), span.contact.layer),
325:                 (span.end.handle.id(), span.end.layer),
326:                 (span.outgoing.handle.id(), span.outgoing.layer),
327:                 (span.finish.handle.id(), span.finish.layer),
328:             ]
329:         }));
330:         clips.sort_by_key(|(id, layer)| (*id, *layer as u8));
331:         clips.dedup();
332:         Self { clips }
333:     }
334: }
