501:             &mut bank,
502:             &mut metrics,
503:             &proportion_offsets,
504:         ) else {
505:             continue;
506:         };
507:         let locomotion_ik_owns = procedural::authored_locomotion_ik_owns(skeleton);
508:         let terrain = (terrain_ik_enabled.is_enabled() && locomotion_ik_owns)
509:             .then(|| terrain.single().ok())
510:             .flatten();
511:         if terrain.is_some() || sampled.locomotion_pelvis_rotation.is_some() {
512:             let definition = Arc::clone(&rig.definition);
513:             // Buffered joint poses are relative to the authored scene, not to
514:             // the controller entity. The scene is translated from the
515:             // capsule's centre to the character's visual ground origin.
516:             // Omitting that transform makes every sampled ankle appear about
517:             // one capsule half-height too high and disables terrain contact.
518:             let presentation_transform = rig_scenes
519:                 .iter()
520:                 .find_map(|(scene, local)| {
521:                     (scene.0 == owner).then(|| presentation_world_transform(owner_transform, local))
522:                 })
523:                 .unwrap_or(*owner_transform);
524:             conform_upcoming_pose_to_terrain(
525:                 &definition,
526:                 &mut sampled.pose,
527:                 &mut rig.terrain_plants,
528:                 PoseConformity {
529:                     owner: &presentation_transform,
530:                     weights: playback.foot_ik_weights,
531:                     terrain,
532:                     contact_plants: ContactPlantPolicy::Reset,
533:                     locomotion_pelvis_rotation: sampled.locomotion_pelvis_rotation,
534:                 },
535:             );
536:             // Translating authored cycles own their complete XZ trajectories.
537:             // Stationary guard turning uses the separate procedural pole-limit
538:             // plant path; never carry a world-space plant through this terrain
539:             // conformity pass.
540:         } else {
541:             rig.terrain_plants = [None; 2];
542:         }
543:         let target = sampled.pose;
544:         if let Some(weapon_target) = AuthoredWeaponTarget::from_pose(&rig.definition, &target) {
545:             commands.entity(owner).insert(weapon_target);
546:         }
547:         let direct_sampling = playback.sampling_cadence() == PoseSamplingCadence::Direct;
548:         let target_velocities = target
549:             .iter()
550:             .zip(&rig.next)
551:             .map(|(target, previous)| {
552:                 if rig.has_presented_pose() && direct_sampling && !transition {
553:                     local_pose_velocity(*previous, *target, delta_seconds)
554:                 } else {
555:                     // Poses on opposite sides of a plan change do not form a
556:                     // trajectory. Differentiating them invents an angular
557:                     // velocity that inertialization would then preserve.
558:                     (Vec3::ZERO, Vec3::ZERO)
559:                 }
560:             })
561:             .collect::<RigJointTable<_>>();
562:         if transition {
563:             if let Err(error) = rig.capture_transition_offsets(&target, &target_velocities) {
564:                 warn!(%error, "Rejected pose inertialization duration");
565:                 continue;
566:             }
567:             rig.set_target_velocities(&target_velocities);
568:             rig.previous.clone_from(&target);
569:             rig.next = target;
570:             rig.sample_accumulator = AnimationElapsed::ZERO;
571:             rig.interpolation_alpha = PoseInterpolation::ONE;
572:             rig.plan = Some(key);
573:             rig.presentation = PosePresentationMode::Displaying;
574:         } else {
575:             if direct_sampling {
576:                 // The semantic curve supplies the continuous target. Preserve
577:                 // transition inertialization, but do not quantize its normal
578:                 // updates through the authored-clip sampling accumulator.
579:                 rig.previous.clone_from(&target);
580:                 rig.next = target;
581:                 rig.sample_accumulator = AnimationElapsed::ZERO;
582:                 rig.interpolation_alpha = PoseInterpolation::ONE;
583:                 rig.set_target_velocities(&target_velocities);
584:             } else {
585:                 // Terrain IK already owns `next`; interpolate the two solved
586:                 // samples without introducing another contact transition.
587:                 if let Err(error) = rig.advance_buffered_sample(target, pose_sample_interval()) {
588:                     warn!(%error, "Rejected pose-buffer sample clock");
589:                     continue;
590:                 }
591:             }
592:         }
593:     }
594: }
595: 
596: pub(super) fn apply_pose_buffers(
597:     mut rigs: Query<&mut PoseBufferRig>,
598:     mut transforms: Query<&mut Transform, Without<PoseBufferRig>>,
599: ) {
600:     let _spike = crate::animation::diagnostics::SpikeGuard::new("apply_pose_buffers");
601:     for mut rig in &mut rigs {
602:         if !rig.has_presented_pose() || rig.visibility == PoseVisibility::Frozen {
603:             continue;
604:         }
605:         let alpha = rig.interpolation_alpha.amount();
606:         let delta_seconds = rig.decay_delta_seconds;
607:         let rig = &mut *rig;
608:         for joint in rig.entities.ordinals() {
609:             let Some(entity) = rig.entities[joint] else {
610:                 continue;
611:             };
612:             let input = rig.previous[joint].interpolate(rig.next[joint], alpha);
613:             let pose = if rig.inertial_state == InertialState::Settled {
614:                 input
615:             } else if !delta_seconds.is_zero() {
616:                 match rig.offsets[joint].update(input, delta_seconds) {
617:                     Ok(pose) => pose,
618:                     Err(error) => {
619:                         warn!(%error, "Rejected pose inertialization clock");
620:                         continue;
621:                     }
622:                 }
623:             } else {
624:                 rig.offsets[joint].peek(input)
625:             };
626:             if let Ok(mut transform) = transforms.get_mut(entity) {
627:                 transform.translation = pose.translation;
628:                 transform.rotation = pose.rotation;
629:                 transform.scale = pose.scale;
630:             }
631:         }
632:         // Once every quintic has run its full length the offsets are exactly
633:         // zero; clear them so at-rest rigs skip the decay entirely.
634:         if rig.inertial_state != InertialState::Settled
635:             && rig.offsets.iter().all(JointInertialOffset::done)
636:         {
637:             rig.inertial_state = InertialState::Settled;
638:             rig.offsets.fill(JointInertialOffset::default());
639:         }
640:     }
641: }
