672: fn sample_plan(
673:     playback: &AnimationPlayback,
674:     definition: &RigDefinition,
675:     clips: &Assets<AnimationClip>,
676:     bank: &mut BakedClipBank,
677:     metrics: &mut PoseBufferMetrics,
678: ) -> Option<SampledPlan> {
679:     if playback.plan.is_bind() {
680:         return Some(SampledPlan {
681:             pose: definition.joints.iter().map(|joint| joint.bind).collect(),
682:             locomotion_pelvis_rotation: None,
683:         });
684:     }
685:     let mut baked = Vec::with_capacity(playback.plan.clips().len());
686:     for weighted in playback.plan.clips() {
687:         let clip = get_or_bake(
688:             weighted.clip.handle.id(),
689:             &weighted.clip.handle,
690:             definition,
691:             clips,
692:             bank,
693:             metrics,
694:         )?;
695:         baked.push((weighted, clip, clips.get(&weighted.clip.handle)?));
696:     }
697:     let mut baked_spans = Vec::with_capacity(playback.plan.extrapolated().len());
698:     for span in playback.plan.extrapolated() {
699:         let start = get_or_bake(
700:             span.start.handle.id(),

701:             &span.start.handle,
702:             definition,
703:             clips,
704:             bank,
705:             metrics,
706:         )?;
707:         let end = get_or_bake(
708:             span.end.handle.id(),
709:             &span.end.handle,
710:             definition,
711:             clips,
712:             bank,
713:             metrics,
714:         )?;
715:         baked_spans.push((span, start, end));
716:     }
717:     let mut baked_continuations = Vec::with_capacity(playback.plan.continuations().len());
718:     for span in playback.plan.continuations() {
719:         let start = get_or_bake(
720:             span.start.handle.id(),
721:             &span.start.handle,
722:             definition,
723:             clips,
724:             bank,
725:             metrics,
726:         )?;
727:         let contact = get_or_bake(
728:             span.contact.handle.id(),
729:             &span.contact.handle,
730:             definition,
731:             clips,
732:             bank,
733:             metrics,
734:         )?;
735:         let end = get_or_bake(
736:             span.end.handle.id(),
737:             &span.end.handle,
738:             definition,
739:             clips,
740:             bank,
741:             metrics,
742:         )?;
743:         let outgoing = get_or_bake(
744:             span.outgoing.handle.id(),
745:             &span.outgoing.handle,
746:             definition,
747:             clips,
748:             bank,
749:             metrics,
750:         )?;
751:         let finish = get_or_bake(
752:             span.finish.handle.id(),
753:             &span.finish.handle,
754:             definition,
755:             clips,
756:             bank,
757:             metrics,
758:         )?;
759:         baked_continuations.push((span, start, contact, end, outgoing, finish));
760:     }
761:     let mut pose = RigJointTable::default();
762:     let mut locomotion_pelvis_rotation = None;
763:     for (joint_index, joint) in definition.joints.indexed() {
764:         let mut blended = joint.bind;
765:         let mut accumulated = BlendWeight::ZERO;
766:         let is_pelvis = joint.role == Some(BoneRole::Pelvis);
767:         let mut combat_upper = joint.bind;
768:         let mut combat_upper_weight = BlendWeight::ZERO;
769:         let mut combat_lower = joint.bind;
770:         let mut combat_lower_weight = BlendWeight::ZERO;
771:         for (weighted, clip, source) in &baked {
772:             let included = joint.body_region.includes(weighted.clip.layer, joint.role);
773:             if !included || weighted.weight.is_absent() {
774:                 continue;
775:             }
776:             let sample = if weighted.locomotion_phase.is_some() {
777:                 sample_locomotion_at_time(
778:                     source,
779:                     joint,
780:                     weighted.clip.duration_seconds,
781:                     weighted.time_seconds,
782:                 )
783:                 .ok()?
784:             } else {
785:                 clip.sample(joint_index, weighted.time_seconds)
786:             };
787:             let sample = sanitize_pose(sample, joint.bind);
788:             if is_pelvis && weighted.clip.layer == ClipLayer::CombatUpper {
789:                 accumulate_local_pose(
790:                     &mut combat_upper,
791:                     &mut combat_upper_weight,
792:                     sample,
793:                     weighted.weight,
794:                 )
795:                 .ok()?;
796:                 continue;
797:             }
798:             if is_pelvis && weighted.clip.layer == ClipLayer::CombatLower {
799:                 accumulate_local_pose(
800:                     &mut combat_lower,
801:                     &mut combat_lower_weight,
802:                     sample,
803:                     weighted.weight,
804:                 )
805:                 .ok()?;
806:                 continue;
807:             }
808:             accumulate_local_pose(&mut blended, &mut accumulated, sample, weighted.weight).ok()?;
809:         }
810:         for (span, start_clip, end_clip) in &baked_spans {
811:             let included = joint.body_region.includes(span.start.layer, joint.role);
812:             if !included || span.weight.is_absent() {
813:                 continue;
814:             }
815:             let start = sanitize_pose(
816:                 start_clip.sample(joint_index, span.start_time_seconds),
817:                 joint.bind,
818:             );
819:             let end = sanitize_pose(
820:                 end_clip.sample(joint_index, span.end_time_seconds),
821:                 joint.bind,
822:             );
823:             // CurveSpan is defined by its two semantic anchors, not the keys
824:             // authored between or after them. Applying their transform delta
825:             // directly gives one constant spatial path through coordinate 1,
826:             // so contact cannot introduce a hidden ease-out/ease-in stop.
827:             let sample = start.extrapolate(end, span.coordinate);
828:             let sample = sanitize_pose(sample, joint.bind);
829:             if is_pelvis && span.start.layer == ClipLayer::CombatUpper {
830:                 accumulate_local_pose(
831:                     &mut combat_upper,
832:                     &mut combat_upper_weight,
833:                     sample,
834:                     span.weight,
835:                 )
836:                 .ok()?;
837:                 continue;
838:             }
839:             if is_pelvis && span.start.layer == ClipLayer::CombatLower {
840:                 accumulate_local_pose(
841:                     &mut combat_lower,
842:                     &mut combat_lower_weight,
843:                     sample,
844:                     span.weight,
845:                 )
846:                 .ok()?;
847:                 continue;
848:             }
849:             accumulate_local_pose(&mut blended, &mut accumulated, sample, span.weight).ok()?;
850:         }
851:         for (span, start_clip, contact_clip, end_clip, outgoing_clip, finish_clip) in
852:             &baked_continuations
853:         {
854:             let included = joint.body_region.includes(span.start.layer, joint.role);
855:             if !included || span.weight.is_absent() {
856:                 continue;
857:             }
858:             let start = sanitize_pose(
859:                 start_clip.sample(joint_index, span.start_time_seconds),
860:                 joint.bind,
861:             );
862:             let contact = sanitize_pose(
863:                 contact_clip.sample(joint_index, span.contact_time_seconds),
864:                 joint.bind,
865:             );
866:             let end = sanitize_pose(
867:                 end_clip.sample(joint_index, span.end_time_seconds),
868:                 joint.bind,
869:             );
870:             let outgoing = sanitize_pose(
871:                 outgoing_clip.sample(joint_index, span.outgoing_time_seconds),
872:                 joint.bind,
873:             );
874:             let finish = sanitize_pose(
875:                 finish_clip.sample(joint_index, span.finish_time_seconds),
876:                 joint.bind,
877:             );
878:             let sample = sanitize_pose(
879:                 start.continuation_transition(
880:                     ContinuationTransition::from_span(contact, end, outgoing, finish, span),
881:                     span.progress,
882:                 ),
883:                 joint.bind,
884:             );
885:             if is_pelvis && span.start.layer == ClipLayer::CombatUpper {
886:                 accumulate_local_pose(
887:                     &mut combat_upper,
888:                     &mut combat_upper_weight,
889:                     sample,
890:                     span.weight,
891:                 )
892:                 .ok()?;
893:                 continue;
894:             }
895:             if is_pelvis && span.start.layer == ClipLayer::CombatLower {
896:                 accumulate_local_pose(
897:                     &mut combat_lower,
898:                     &mut combat_lower_weight,
899:                     sample,
900:                     span.weight,
901:                 )
902:                 .ok()?;
903:                 continue;
904:             }
905:             accumulate_local_pose(&mut blended, &mut accumulated, sample, span.weight).ok()?;
906:         }
907:         let mut result =
908:             if is_pelvis && !combat_upper_weight.is_absent() && !combat_lower_weight.is_absent() {
909:                 locomotion_pelvis_rotation = Some(combat_lower.rotation);
910:                 combine_combat_pelvis(combat_upper, combat_lower)
911:             } else if !accumulated.is_absent() {
912:                 blended
913:             } else {
914:                 joint.bind
915:             };
916:         if let Some(hand) = hand_animation_joint(definition, joint_index) {
917:             let mut hand_pose = joint.bind;
918:             let mut hand_weight = BlendWeight::ZERO;
919:             for (weighted, clip, _) in &baked {
920:                 if weighted.clip.layer != hand
921:                     || clip.track_source(joint_index) != BoneTrackSource::Authored
922:                     || weighted.weight.is_absent()
923:                 {
924:                     continue;
925:                 }
926:                 let sample =
927:                     sanitize_pose(clip.sample(joint_index, weighted.time_seconds), joint.bind);
928:                 accumulate_local_pose(&mut hand_pose, &mut hand_weight, sample, weighted.weight)
929:                     .ok()?;
930:             }
931:             if !hand_weight.is_absent() {
932:                 result = hand_pose;
933:             }
934:         }
935:         pose.push(result);
936:     }
937:     metrics.sampled_pose_count = metrics.sampled_pose_count.saturating_add(1);
938:     Some(SampledPlan {
939:         pose,
940:         locomotion_pelvis_rotation,
941:     })
942: }
943: 
944: fn accumulate_local_pose(
945:     accumulated_pose: &mut LocalPose,
946:     accumulated_weight: &mut BlendWeight,
947:     sample: LocalPose,
948:     weight: BlendWeight,
949: ) -> AnimationValueResult<()> {
950:     let next_total = accumulated_weight.checked_add(weight)?;
951:     let next_pose = if accumulated_weight.is_absent() {
952:         sample
953:     } else {
954:         accumulated_pose.interpolate(
955:             sample,
956:             UnitInterval::from_fraction(weight.factor() / next_total.factor())?,
957:         )
958:     };
959:     *accumulated_pose = next_pose;
960:     *accumulated_weight = next_total;
961:     Ok(())
962: }
