964: fn combine_combat_pelvis(combat: LocalPose, locomotion: LocalPose) -> LocalPose {
965:     LocalPose {
966:         translation: locomotion.translation,
967:         rotation: combat.rotation,
968:         scale: locomotion.scale,
969:     }
970: }
971: 
972: fn sample_source_clip(clip: &AnimationClip, joint: &RigJoint, time_seconds: ClipTime) -> LocalPose {
973:     let translation_field = animated_field!(Transform::translation);
974:     let rotation_field = animated_field!(Transform::rotation);
975:     let scale_field = animated_field!(Transform::scale);
976:     LocalPose {
977:         translation: clip
978:             .sample_clamped(translation_field, joint.target, time_seconds.seconds())
979:             .unwrap_or(joint.bind.translation),
980:         rotation: clip
981:             .sample_clamped(rotation_field, joint.target, time_seconds.seconds())
982:             .unwrap_or(joint.bind.rotation),
983:         scale: clip
984:             .sample_clamped(scale_field, joint.target, time_seconds.seconds())
985:             .unwrap_or(joint.bind.scale),
986:     }
987: }
