989: fn conform_upcoming_pose_to_terrain(
990:     definition: &RigDefinition,
991:     pose: &mut RigJointTable<LocalPose>,
992:     plants: &mut [Option<AuthoredContactPlant>; 2],
993:     conformity: PoseConformity<'_>,
994: ) {
995:     let PoseConformity {
996:         owner,
997:         weights,
998:         terrain,
999:         contact_plants,
1000:         locomotion_pelvis_rotation,
1001:     } = conformity;
1002:     if contact_plants == ContactPlantPolicy::Reset {
1003:         *plants = [None; 2];
1004:     }
1005:     let locomotion_reference = locomotion_pelvis_rotation.and_then(|rotation| {
1006:         definition
1007:             .joints
1008:             .iter()
1009:             .position(|joint| joint.role == Some(BoneRole::Pelvis))
1010:             .map(RigJointOrdinal::from)
1011:             .map(|pelvis| {
1012:                 let mut reference = pose.clone();
1013:                 reference[pelvis].rotation = rotation;
1014:                 reference
1015:             })
1016:     });
1017:     let mut locomotion_reference_cache = locomotion_reference
1018:         .as_ref()
1019:         .map(|reference| RigJointTable::from(vec![None; reference.len()]));
1020:     for (index, (left, weight, names)) in [
1021:         (true, weights.left(), RigJointName::LEFT_LEG_CHAIN),
1022:         (false, weights.right(), RigJointName::RIGHT_LEG_CHAIN),
1023:     ]
1024:     .into_iter()
1025:     .enumerate()
1026:     {
1027:         let weight = weight.fraction().clamp(0.0, 1.0);
1028:         if weight <= 0.0 && locomotion_pelvis_rotation.is_none() {
1029:             plants[index] = None;
1030:             continue;
1031:         }
1032:         let [Some(upper), Some(lower), Some(foot)] = names.map(|name| {
1033:             definition
1034:                 .joints
1035:                 .iter()
1036:                 .position(|joint| {
1037:                     joint
1038:                         .name
1039:                         .as_ref()
1040:                         .is_some_and(|joint_name| joint_name.eq_ignore_ascii_case(&name))
1041:                 })
1042:                 .map(RigJointOrdinal::from)
1043:         }) else {
1044:             continue;
1045:         };
1046:         let mut cache = RigJointTable::from(vec![None; pose.len()]);
1047:         let upper_global = local_pose_global(definition, pose, upper, &mut cache);
1048:         let lower_global = local_pose_global(definition, pose, lower, &mut cache);
1049:         let foot_global = local_pose_global(definition, pose, foot, &mut cache);
1050:         let foot_world = owner.transform_point(foot_global.translation);

1051:         let reference_foot = match (&locomotion_reference, locomotion_reference_cache.as_mut()) {
1052:             (Some(reference), Some(cache)) => local_pose_global(definition, reference, foot, cache),
1053:             _ => foot_global,
1054:         };
1055:         let reference_foot_world = owner.transform_point(reference_foot.translation);
1056:         let reference_foot_rotation_world = owner.rotation() * reference_foot.rotation;
1057:         let terrain_target_world = ScenePlanPoint::from_metres(reference_foot_world.xz())
1058:             .and_then(|point| terrain.and_then(|terrain| terrain.height_at(point)))
1059:             .map(|height| {
1060:                 reference_foot_world.with_y(
1061:                     reference_foot_world
1062:                         .y
1063:                         .max(height.metres() + measured_ankle_sole_offset_metres().metres()),
1064:                 )
1065:             })
1066:             .unwrap_or(reference_foot_world);
1067:         let supported =
1068:             terrain.is_some() && contact_plants == ContactPlantPolicy::Retain && weight > 0.05;
1069:         if !supported {
1070:             plants[index] = None;
1071:         } else if plants[index].is_none() {
1072:             plants[index] = Some(AuthoredContactPlant {
1073:                 position_world: terrain_target_world,
1074:                 rotation_world: reference_foot_rotation_world,
1075:                 reference_owner_position: owner
1076:                     .affine()
1077:                     .inverse()
1078:                     .transform_point3(terrain_target_world),
1079:                 reference_owner_rotation: owner.rotation().inverse()
1080:                     * reference_foot_rotation_world,
1081:             });
1082:         }
1083:         if let Some(mut plant) = plants[index] {
1084:             let reference_world = owner.transform_point(plant.reference_owner_position);
1085:             let reference_rotation_world = owner.rotation() * plant.reference_owner_rotation;
1086:             let displacement = reference_world.xz() - plant.position_world.xz();
1087:             let distance = displacement.length();
1088:             if distance > pose_tuning().authored_contact_plant_limit_metres.metres() {
1089:                 let excess = distance - pose_tuning().authored_contact_plant_limit_metres.metres();
1090:                 plant.position_world +=
1091:                     Vec3::new(displacement.x, 0.0, displacement.y).normalize_or_zero() * excess;
1092:                 plant.rotation_world = hemisphere_slerp(
1093:                     plant.rotation_world,
1094:                     reference_rotation_world,
1095:                     (excess / distance).clamp(0.0, 1.0),
1096:                 );
1097:             }
1098:             if let Some(plant_height) = ScenePlanPoint::from_metres(plant.position_world.xz())
1099:                 .and_then(|point| terrain.and_then(|terrain| terrain.height_at(point)))
1100:             {
1101:                 plant.position_world.y = plant
1102:                     .position_world
1103:                     .y
1104:                     .max(plant_height.metres() + measured_ankle_sole_offset_metres().metres());
1105:             }
1106:             plants[index] = Some(plant);
1107:         }
1108:         let (terrain_world, preserved_foot_rotation) = if let Some(plant) = plants[index] {
1109:             (
1110:                 // Contact ownership is discrete. Smoothness comes from the
1111:                 // pose buffer interpolating the previous displayed pose into
1112:                 // this conformed upcoming target; blending the target itself
1113:                 // by the contact scalar lets the planted ankle follow the
1114:                 // authored clip and the rotating owner.
1115:                 plant.position_world,
1116:                 owner.rotation().inverse() * plant.rotation_world,
1117:             )
1118:         } else {
1119:             (terrain_target_world, reference_foot.rotation)
1120:         };
1121:         if terrain_world.distance(foot_world) <= 0.0001
1122:             && preserved_foot_rotation.angle_between(foot_global.rotation) <= 0.0001
1123:         {
1124:             // An identity target is not an identity two-bone solve: pole
1125:             // selection can still perturb an authored chain. Treat an already
1126:             // clear upcoming sample as a strict no-op.
1127:             continue;
1128:         }
1129:         // Authored locomotion is calibrated against flat ground. A fixed
1130:         // ankle-to-sole target is only a lower bound here: lowering a pitched
1131:         // or non-flat authored combat foot changes its intended sole clearance
1132:         // and can bury the visible mesh even on level terrain. Preserve the
1133:         // upcoming authored height unless terrain actually rises into it.
1134:         let target_world = if plants[index].is_some() {
1135:             terrain_world
1136:         } else {
1137:             reference_foot_world.lerp(terrain_world, weight)
1138:         };
1139:         let target = owner.affine().inverse().transform_point3(target_world);
1140:         let hip = upper_global.translation;
1141:         let knee = lower_global.translation;
1142:         let ankle = foot_global.translation;
1143:         let upper_length = hip.distance(knee);
1144:         let lower_length = knee.distance(ankle);
1145:         let Some(solution) = solve_pose_two_bone(
1146:             hip,
1147:             knee,
1148:             target,
1149:             upper_length,
1150:             lower_length,
1151:             if left { Vec3::NEG_Z } else { Vec3::Z },
1152:         ) else {
1153:             continue;
1154:         };
1155:         aim_pose_joint(definition, pose, upper, knee - hip, solution.0 - hip);
1156:         let mut cache = RigJointTable::from(vec![None; pose.len()]);
1157:         let lower_after = local_pose_global(definition, pose, lower, &mut cache);
1158:         let foot_after = local_pose_global(definition, pose, foot, &mut cache);
1159:         aim_pose_joint(
1160:             definition,
1161:             pose,
1162:             lower,
1163:             foot_after.translation - lower_after.translation,
1164:             solution.1 - solution.0,
1165:         );
1166:         let mut cache = RigJointTable::from(vec![None; pose.len()]);
1167:         let parent_rotation = definition.joints[foot]
1168:             .parent
1169:             .map(|parent| local_pose_global(definition, pose, parent, &mut cache).rotation)
1170:             .unwrap_or(Quat::IDENTITY);
1171:         let local = parent_rotation.inverse() * preserved_foot_rotation;
1172:         if local.is_finite() {
1173:             pose[foot].rotation = local.normalize();
1174:         }
1175:     }
1176: }
1177: 
1178: fn solve_pose_two_bone(
1179:     hip: Vec3,
1180:     current_knee: Vec3,
1181:     target: Vec3,
1182:     upper_length: f32,
1183:     lower_length: f32,
1184:     fallback_pole: Vec3,
1185: ) -> Option<(Vec3, Vec3)> {
1186:     let offset = target - hip;
1187:     let direction = offset.try_normalize()?;
1188:     let distance = offset.length().clamp(
1189:         (upper_length - lower_length).abs() + 0.0001,
1190:         upper_length + lower_length - 0.0001,
1191:     );
1192:     let end = hip + direction * distance;
1193:     let along = (upper_length * upper_length - lower_length * lower_length + distance * distance)
1194:         / (2.0 * distance);
1195:     let height = (upper_length * upper_length - along * along)
1196:         .max(0.0)
1197:         .sqrt();
1198:     let bend = (current_knee - hip)
1199:         .reject_from_normalized(direction)
1200:         .try_normalize()
1201:         .or_else(|| {
1202:             fallback_pole
1203:                 .reject_from_normalized(direction)
1204:                 .try_normalize()
1205:         })?;
1206:     let knee = hip + direction * along + bend * height;
1207:     (knee.is_finite() && end.is_finite()).then_some((knee, end))
1208: }
