1210: fn sanitize_pose(pose: LocalPose, fallback: LocalPose) -> LocalPose {
1211:     if pose.translation.is_finite()
1212:         && pose.rotation.is_finite()
1213:         && pose.rotation.length_squared() > 1e-8
1214:         && pose.scale.is_finite()
1215:     {
1216:         LocalPose {
1217:             rotation: pose.rotation.normalize(),
1218:             ..pose
1219:         }
1220:     } else {
1221:         fallback
1222:     }
1223: }
