1: //! Fixed sample-clock advancement between the pose buffer's solved targets.
2: 
3: use super::*;
4: use adventuresim_tactical_core::animation::PositiveAnimationDuration;
5: 
6: impl PoseBufferRig {
7:     pub(super) fn advance_buffered_sample(
8:         &mut self,
9:         target: RigJointTable<LocalPose>,
10:         interval: PositiveAnimationDuration,
11:     ) -> AnimationValueResult<()> {
12:         let due = samples_due(self.sample_accumulator, interval);
13:         let elapsed = interval.sample_span(due)?;
14:         let remainder = self.sample_accumulator.saturating_sub(elapsed);
15:         let fraction = PoseInterpolation::from_sample_clock(remainder, interval)?;
16:         if due > 0 {
17:             self.previous = self.next.clone();
18:             self.next = target;
19:             for joint in self.next.ordinals() {
20:                 let (linear, angular) =
21:                     local_pose_velocity(self.previous[joint], self.next[joint], elapsed);
22:                 self.target_linear_velocities[joint] = linear;
23:                 self.target_angular_velocities[joint] = angular;
24:             }
25:             self.sample_accumulator = remainder;
26:         }
27:         self.interpolation_alpha = fraction;
28:         Ok(())
29:     }
30: }
31: 
32: pub(super) fn samples_due(
33:     accumulator: AnimationElapsed,
34:     interval: PositiveAnimationDuration,
35: ) -> u32 {
36:     (accumulator.seconds().max(0.0) / interval.seconds()).floor() as u32
37: }
38: 
