1: //! Checked finite fractions, independent of each producer's clamp policy.
2: 
3: use fabelgeist_math::units::Ratio;
4: use serde::{Deserialize, Serialize};
5: use std::ops::Mul;
6: 
7: pub type FractionResult<T> = Result<T, FractionError>;
8: 
9: #[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd, Serialize, Deserialize)]
10: #[serde(try_from = "f32", into = "f32")]
11: pub struct UnitInterval(f32);
12: 
13: #[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
14: pub enum FractionError {
15:     #[error("unit fraction must be finite")]
16:     NonFinite,
17:     #[error("unit fraction must lie in [0, 1]")]
18:     OutsideUnitInterval,
19:     #[error("unit fraction interpolation bounds must be strictly increasing")]
20:     NonIncreasingBounds,
21: }
22: 
23: impl UnitInterval {
24:     pub const ZERO: Self = Self(0.0);
25:     pub const ONE: Self = Self(1.0);
26:     pub const HALF: Self = Self(0.5);
27:     pub fn from_fraction(value: f32) -> FractionResult<Self> {
28:         if !value.is_finite() {
29:             return Err(FractionError::NonFinite);
30:         }
31:         if !(0.0..=1.0).contains(&value) {
32:             return Err(FractionError::OutsideUnitInterval);
33:         }
34:         Ok(Self(value))
35:     }
36:     /// Selecting a confidence preserves admission, including native signed-zero semantics.
37:     pub fn max(self, other: Self) -> Self {
38:         Self(self.0.max(other.0))
39:     }
40:     pub fn complement(self) -> Self {
41:         Self(1.0 - self.0)
42:     }
43:     /// Subtract another fraction, saturating at zero when it is larger.
44:     pub fn saturating_sub(self, other: Self) -> Self {
45:         Self((self.0 - other.0).max(0.0))
46:     }
47:     /// Interpolate admitted endpoints and check the computed fraction.
48:     pub fn checked_lerp(self, other: Self, fraction: Self) -> FractionResult<Self> {
49:         Self::from_fraction(self.0 + (other.0 - self.0) * fraction.0)
50:     }
51:     /// Normalize within an increasing interval, saturating at its endpoints.
52:     pub fn clamped_inverse_lerp(self, lower: Self, upper: Self) -> FractionResult<Self> {
53:         if lower >= upper {
54:             return Err(FractionError::NonIncreasingBounds);
55:         }
56:         if self <= lower {
57:             return Ok(Self::ZERO);
58:         }
59:         if self >= upper {
60:             return Ok(Self::ONE);
61:         }
62:         Self::from_fraction((self.0 - lower.0) / (upper.0 - lower.0))
63:     }
64:     /// Evaluate cubic smoothstep and admit the resulting fraction.
65:     pub fn smoothstep(self) -> FractionResult<Self> {
66:         let fraction = self.0;
67:         Self::from_fraction(fraction * fraction * (3.0 - 2.0 * fraction))
68:     }
69:     pub fn fraction(self) -> f32 {
70:         self.0
71:     }
72: }
73: impl Mul for UnitInterval {
74:     type Output = Self;
75: 
76:     fn mul(self, other: Self) -> Self {
77:         Self(self.0 * other.0)
78:     }
79: }
