298:     /// Advance the shared root correction before publishing the retained offset.
299:     pub(super) fn advance_terrain_pelvis(
300:         &mut self,
301:         desired: SignedLength,
302:         terminal: bool,
303:         first_sample: bool,
304:         gait: LocomotionGait,
305:         elapsed: AnimationElapsed,
306:     ) -> AnimationValueResult<SignedLength> {
307:         if terminal {
308:             if let Some(reach) = self.terminal_contacts.prepared_mut() {
309:                 let target = match reach.target_shift {
310:                     Some(target) => target,
311:                     None => SignedLength::from_metres(desired.metres().clamp(-0.25, 0.0)).map_err(
312:                         |_| AnimationValueError::Overflow {
313:                             quantity: AnimationQuantity::HeightOffset,
314:                         },
315:                     )?,
316:                 };
317:                 let shift = if elapsed.is_zero() {
318:                     reach.shift
319:                 } else {
320:                     advance_pelvis_shift(reach.shift, target, elapsed)?
321:                 };
322:                 reach.target_shift = Some(target);
323:                 reach.shift = shift;
324:             }
325:             Ok(self.terminal_contacts.shift())
326:         } else {
327:             let shift = if first_sample {
328:                 desired
329:             } else if elapsed.is_zero() {
330:                 self.pelvis_shift
331:             } else if gait == LocomotionGait::Run {
332:                 advance_scalar_at_speed(
