281: pub(super) fn guard_step_liveness_metrics(frames: &[&FrameSample]) -> GuardStepLivenessMetrics {
282:     let required = GuardStepLivenessMetrics::is_required(frames);
283:     if !required {
284:         return GuardStepLivenessMetrics::default();
285:     }
286: 
287:     let mut interval_start = 0;
288:     let mut completed_half_steps = 0;
289:     let mut visible_half_steps = 0;
290:     let mut minimum_swing_travel = f32::INFINITY;
291:     let mut minimum_swing_clearance_gain = f32::INFINITY;
292: 
293:     for interval_end in 1..frames.len() {
294:         if frames[interval_end].contact_sequence == frames[interval_end - 1].contact_sequence {
295:             continue;
296:         }
297: 
298:         let start = frames[interval_start];
299:         let end = frames[interval_end];
300:         let left_gain = end.left_support_weight.fraction() - start.left_support_weight.fraction();
301:         let right_gain =
302:             end.right_support_weight.fraction() - start.right_support_weight.fraction();
303:         let (
304:             swing_foot,
305:             start_swing_support,
306:             end_swing_support,
307:             start_other_support,
308:             end_other_support,
309:         ) = if left_gain >= right_gain {
310:             (
311:                 BoneRole::FootLeft,
312:                 start.left_support_weight.fraction(),
313:                 end.left_support_weight.fraction(),
314:                 start.right_support_weight.fraction(),
315:                 end.right_support_weight.fraction(),
316:             )
317:         } else {
318:             (
319:                 BoneRole::FootRight,
320:                 start.right_support_weight.fraction(),
321:                 end.right_support_weight.fraction(),
322:                 start.left_support_weight.fraction(),
323:                 end.left_support_weight.fraction(),
324:             )
325:         };
326: 
327:         completed_half_steps += 1;
328:         let support_swap_valid = start_swing_support <= 0.25
329:             && end_swing_support >= 0.75
330:             && start_other_support >= 0.75
331:             && end_other_support <= 0.25;
332:         let travel = start
333:             .bones
334:             .get(swing_foot)
335:             .zip(end.bones.get(swing_foot))
336:             .map_or(0.0, |(start, end)| {
337:                 (Vec3::from_array(end.position) - Vec3::from_array(start.position))
338:                     .xz()
339:                     .length()
340:             });
341:         let interval = &frames[interval_start..=interval_end];
342:         let start_clearance = start
343:             .bones
344:             .get(swing_foot)
345:             .and_then(|bone| bone.terrain_clearance_metres);
346:         let end_clearance = end
347:             .bones
348:             .get(swing_foot)
349:             .and_then(|bone| bone.terrain_clearance_metres);
350:         let maximum_clearance = interval
351:             .iter()
352:             .filter_map(|frame| {
353:                 frame
354:                     .bones
355:                     .get(swing_foot)
356:                     .and_then(|bone| bone.terrain_clearance_metres)
357:             })
358:             .fold(f32::NEG_INFINITY, f32::max);
359:         let clearance_gain = start_clearance
360:             .zip(end_clearance)
361:             .filter(|_| maximum_clearance.is_finite())
362:             .map_or(0.0, |(start, end)| maximum_clearance - start.max(end));
363: 
364:         minimum_swing_travel = minimum_swing_travel.min(travel);
365:         minimum_swing_clearance_gain = minimum_swing_clearance_gain.min(clearance_gain);
366:         if support_swap_valid
367:             && travel >= MINIMUM_GUARD_SWING_TRAVEL_METRES
368:             && clearance_gain >= MINIMUM_GUARD_SWING_CLEARANCE_GAIN_METRES
369:         {
370:             visible_half_steps += 1;
371:         }
372:         interval_start = interval_end;
373:     }
374: 
375:     GuardStepLivenessMetrics {
376:         required,
377:         completed_half_steps,
378:         visible_half_steps,
379:         minimum_swing_travel_metres: if minimum_swing_travel.is_finite() {
380:             minimum_swing_travel
381:         } else {
382:             0.0
383:         },
384:         minimum_swing_clearance_gain_metres: if minimum_swing_clearance_gain.is_finite() {
385:             minimum_swing_clearance_gain
386:         } else {
387:             0.0
388:         },
389:     }
390: }
