854: pub(super) fn ordinary_unplanned_release_transition_is_valid(
855:     before: &FrameSample,
856:     after: &FrameSample,
857:     before_solve: Option<[f32; 3]>,
858:     after_solve: Option<[f32; 3]>,
859:     before_release_target: Option<[f32; 3]>,
860:     after_release_target: Option<[f32; 3]>,
861: ) -> bool {
862:     before_solve
863:         .zip(after_solve)
864:         .is_some_and(|(before_solve, after_solve)| {
865:             let before_solve_world = Vec3::from_array(before_solve);
866:             let after_solve_world = Vec3::from_array(after_solve);
867:             let before_solve = target_body_local(before, before_solve_world);
868:             let after_solve = target_body_local(after, after_solve_world);
869:             let frozen_goal_converges = before_release_target.zip(after_release_target).is_none_or(
870:                 |(before_goal, after_goal)| {
871:                     let before_goal = Vec3::from_array(before_goal);
872:                     let after_goal = Vec3::from_array(after_goal);
873:                     target_body_local(before, before_goal)
874:                         .distance(target_body_local(after, after_goal))
875:                         > 0.002
876:                         || after_solve_world.distance(after_goal)
877:                             <= before_solve_world.distance(before_goal) + 0.001
878:                 },
879:             );
880:             let step_limit = if frame_uses_run_motion_budget(after) {
881:                 // Run's owner-space target advances up to 8.75 cm per sample;
882:                 // its terrain scenario independently rejects rendered foot
883:                 // motion above 9.5 cm. Walk/settle retains the 5.5 cm budget.
884:                 0.095
885:             } else {
886:                 0.055
887:             };
888:             after_solve.distance(before_solve) <= step_limit && frozen_goal_converges
889:         })
890: }
