912:     after_solve: Option<[f32; 3]>,
913:     after_support: UnitInterval,
914:     release_active: bool,
915: ) -> bool {
916:     before_plan
917:         .zip(after_plan)
918:         .zip(before_solve.zip(after_solve))
919:         .is_none_or(|((before_plan, after_plan), (before_solve, after_solve))| {
920:             let before_plan = Vec3::from_array(before_plan);
921:             let after_plan = Vec3::from_array(after_plan);
922:             let before_solve_world = Vec3::from_array(before_solve);
923:             let after_solve_world = Vec3::from_array(after_solve);
924:             if frame_uses_run_motion_budget(after) {
925:                 let plan_is_frozen = before_plan.distance(after_plan) <= 0.002;
926:                 let atomic_acquisition_retarget = after_support.fraction() > 0.05
927:                     && !release_active
928:                     && after_solve_world.distance(after_plan) <= 0.02;
929:                 let owned_airborne_replan = after_support.fraction() <= 0.5 && release_active;
930:                 let rendered_step = before.bones.get(foot).zip(after.bones.get(foot)).map(
931:                     |(before_foot, after_foot)| {
932:                         target_body_local(after, Vec3::from_array(after_foot.position)).distance(
933:                             target_body_local(before, Vec3::from_array(before_foot.position)),
934:                         )
935:                     },
936:                 );
937:                 (plan_is_frozen || atomic_acquisition_retarget || owned_airborne_replan)
938:                     && rendered_step.is_some_and(|step| step <= 0.095)
939:             } else {
940:                 before_plan.distance(after_plan) <= 0.002
941:                     && after_solve_world.distance(after_plan)
942:                         <= before_solve_world.distance(before_plan) + 0.005
943:             }
944:         })
945: }
