966: pub(super) fn contact_sole_clearance_range(
967:     frames: &[&FrameSample],
968: ) -> AnimationValueResult<(f32, f32)> {
969:     let mut minimum = f32::INFINITY;
970:     let mut maximum = f32::NEG_INFINITY;
971:     for frame in frames {
972:         let procedural_solve_active =
973:             frame.ik_left_solve_target.is_some() || frame.ik_right_solve_target.is_some();
974:         let support = if procedural_solve_active {
975:             Some(frame.required_ik_support()?)
976:         } else {
977:             None
978:         };
979:         for (foot, left) in [(BoneRole::FootLeft, true), (BoneRole::FootRight, false)] {
980:             let is_contact = if let Some((left_support, right_support)) = support {
981:                 (if left { left_support } else { right_support }).fraction() >= 0.95
982:             } else {
983:                 let phase = frame.gait_phase.cycles().rem_euclid(1.0);
984:                 let distance = if left {
985:                     phase.min(1.0 - phase)
986:                 } else {
987:                     (phase - 0.5).abs()
988:                 };
989:                 distance <= 0.035
990:             };
991:             if is_contact
992:                 && let Some(ankle) = frame
993:                     .bones
994:                     .get(foot)
995:                     .and_then(|bone| bone.terrain_clearance_metres)
996:             {
997:                 let clearance = ankle - measured_ankle_sole_offset_metres().metres();
998:                 minimum = minimum.min(clearance);
999:                 maximum = maximum.max(clearance);
1000:             }
1001:         }
1002:     }
1003:     Ok(if minimum.is_finite() && maximum.is_finite() {
1004:         (minimum, maximum)
1005:     } else {
1006:         (0.0, 0.0)
1007:     })
1008: }
