1155: /// Terrain height variation under the two sampled feet relative to the
1156: /// controller root's ground point. Subtracting this measured relief from the
1157: /// torso range preserves the flat-ground gait envelope while allowing the
1158: /// bounded pelvis correction required to keep both legs reachable on a slope.
1159: pub(super) fn foot_terrain_relief(frames: &[&FrameSample]) -> f32 {
1160:     let (minimum, maximum) = frames
1161:         .iter()
1162:         .flat_map(|frame| {
1163:             [BoneRole::FootLeft, BoneRole::FootRight]
1164:                 .into_iter()
1165:                 .filter_map(|foot| {
1166:                     let bone = frame.bones.get(foot)?;
1167:                     let clearance = bone.terrain_clearance_metres?;
1168:                     let terrain_height = bone.position[1] - clearance;
1169:                     let root_ground =
1170:                         frame.root_position_metres[1] - CAPTURE_ROOT_GROUND_OFFSET_METRES;
1171:                     Some(terrain_height - root_ground)
1172:                 })
1173:         })
1174:         .fold(
1175:             (f32::INFINITY, f32::NEG_INFINITY),
1176:             |(minimum, maximum), value| (minimum.min(value), maximum.max(value)),
1177:         );
1178:     if minimum.is_finite() && maximum.is_finite() {
1179:         maximum - minimum
1180:     } else {
1181:         0.0
1182:     }
1183: }
