1185: fn maximum_planted_foot_drift(metadata: &ScenarioMetadata<'_>, frames: &[&FrameSample]) -> f32 {
1186:     let mut maximum = 0.0_f32;
1187:     for (foot, left) in [(BoneRole::FootLeft, true), (BoneRole::FootRight, false)] {
1188:         let mut anchor = None;
1189:         for frame in frames {
1190:             if metadata.kind() != ScenarioKind::Terrain && !frame.guard_action {
1191:                 anchor = None;
1192:                 continue;
1193:             }
1194:             let support = if left {
1195:                 frame.left_support_weight.fraction()
1196:             } else {
1197:                 frame.right_support_weight.fraction()
1198:             };
1199:             // The IK target deliberately releases continuously below full
1200:             // support. Measure cumulative plant drift only while the solver is
1201:             // effectively pinned; the separate >=0.9 per-frame slip metric
1202:             // continues to gate the blended release interval.
1203:             if support >= FULL_PLANT_SUPPORT_WEIGHT {
1204:                 let Some(position) = frame
1205:                     .bones
1206:                     .get(foot)
1207:                     .map(|bone| Vec3::from_array(bone.position).xz())
1208:                 else {
1209:                     continue;
1210:                 };
1211:                 let origin = anchor.get_or_insert(position);
1212:                 maximum = maximum.max(position.distance(*origin));
1213:             } else {
1214:                 anchor = None;
1215:             }
1216:         }
1217:     }
1218:     maximum
1219: }
