76: pub(super) fn both_feet_behind_hips(frames: &[FrameSample]) -> bool {
77:     let mut duration = 0.0_f32;
78:     for pair in frames.windows(2) {
79:         let [before, after] = pair else {
80:             continue;
81:         };
82:         if before.scenario != after.scenario
83:             || after.speed_metres_per_second <= SignedSpeed::from(STATIONARY_ANIMATION_SPEED_LIMIT)
84:         {
85:             duration = 0.0;
86:             continue;
87:         }
88:         let Some(direction) = Vec3::from_array(after.world_travel_direction).try_normalize() else {
89:             duration = 0.0;
90:             continue;
91:         };
92:         let behind = [
93:             (BoneRole::ThighLeft, BoneRole::FootLeft),
94:             (BoneRole::ThighRight, BoneRole::FootRight),
95:         ]
96:         .into_iter()
97:         .all(|(hip, foot)| {
98:             let Some(hip) = after.bones.get(hip) else {
99:                 return false;
100:             };
101:             let Some(foot) = after.bones.get(foot) else {
102:                 return false;
103:             };
104:             (Vec3::from_array(foot.position) - Vec3::from_array(hip.position)).dot(direction)
105:                 < -0.02
106:         });
107:         if behind {
108:             duration += (after.time_seconds.seconds() - before.time_seconds.seconds()).max(0.0);
109:             if duration >= 0.3 {
110:                 return true;
111:             }
112:         } else {
113:             duration = 0.0;
114:         }
115:     }
116:     false
117: }
