119: pub(super) fn scenario_metrics(
120:     frames: &[FrameSample],
121: ) -> AnimationValueResult<Vec<ScenarioMetrics>> {
122:     let mut grouped = BTreeMap::<&ScenarioMetadata<'static>, Vec<&FrameSample>>::new();
123:     for frame in frames {
124:         grouped.entry(&frame.scenario).or_default().push(frame);
125:     }
126:     grouped
127:         .into_iter()
128:         .map(|(scenario, frames)| {
129:             let metadata = scenario;
130:             let metric_frames = metric_frames_after_warmup(metadata, &frames);
131:             let procedural_frames = metric_frames
132:                 .iter()
133:                 .copied()
134:                 .filter(|frame| metadata.kind() == ScenarioKind::Terrain || frame.guard_action)
135:                 .collect::<Vec<_>>();
136:             let mut maximum_step = 0.0_f32;
137:             let mut maximum_leg_step = 0.0_f32;
138:             let mut maximum_foot_step = 0.0_f32;
139:             let mut maximum_knee_step = 0.0_f32;
140:             let mut maximum_rotation = 0.0_f32;
141:             let mut maximum_foot_rotation = 0.0_f32;
142:             let mut maximum_slip = 0.0_f32;
143:             let mut worst_displacement = None;
144:             let mut worst_rotation = None;
145:             // Frame zero establishes retained procedural state from a fresh
146:             // component. The scenario pre-roll begins at frame one; continuity
147:             // gates therefore start with the first real pre-roll transition
148:             // (1→2) without exempting any movement frame.
149:             for pair in metric_frames.windows(2).skip(1) {
150:                 let (before, after) = (pair[0], pair[1]);
151:                 for (name, before_bone) in &before.bones {
152:                     let Some(after_bone) = after.bones.get(*name) else {
153:                         continue;
154:                     };
155:                     let displacement = body_local(after, *name)
156:                         .zip(body_local(before, *name))
157:                         .map_or(f32::INFINITY, |(after, before)| after.distance(before));
158:                     if displacement > maximum_step {
159:                         maximum_step = displacement;
160:                         worst_displacement = Some(ContinuityLocation {
161:                             bone: *name,
162:                             from_frame: before.scenario_frame,
163:                             to_frame: after.scenario_frame,
164:                             value: displacement,
165:                         });
166:                     }
167:                     if is_leg_bone(name) {
168:                         maximum_leg_step = maximum_leg_step.max(displacement);
169:                     }
170:                     if is_foot_bone(name) {
171:                         maximum_foot_step = maximum_foot_step.max(displacement);
172:                     }
173:                     if is_knee_bone(name) {
174:                         maximum_knee_step = maximum_knee_step.max(displacement);
175:                     }
176:                     let rotation = body_local_rotation(after, after_bone)
177:                         .angle_between(body_local_rotation(before, before_bone))
178:                         .to_degrees();
179:                     if is_foot_bone(name) {
180:                         maximum_foot_rotation = maximum_foot_rotation.max(rotation);
181:                     }
182:                     if rotation > maximum_rotation {
183:                         maximum_rotation = rotation;
184:                         worst_rotation = Some(ContinuityLocation {
185:                             bone: *name,
186:                             from_frame: before.scenario_frame,
187:                             to_frame: after.scenario_frame,
188:                             value: rotation,
189:                         });
190:                     }
191:                 }
192:                 maximum_slip =
193:                     maximum_slip.max(supported_foot_slip(metadata, before, after)?.metres());
194:             }
195:             let maximum_plant_drift = maximum_planted_foot_drift(metadata, &metric_frames);
196:             let seam = LoopSeamMetrics::measure(metadata, &frames);
197:             let (visual_height_peak_count, visual_height_peaks_in_passing_windows) =
198:                 visual_height_peaks(&metric_frames);
199:             let guard_liveness = guard_step_liveness_metrics(&metric_frames);
200:             let contact_sole_range = contact_sole_clearance_range(&metric_frames)?;
201:             Ok(ScenarioMetrics {
202:                 scenario: (*scenario).clone(),
203:                 frame_count: frames.len(),
204:                 maximum_root_relative_step_metres: maximum_step,
205:                 maximum_leg_root_relative_step_metres: maximum_leg_step,
206:                 maximum_foot_root_relative_step_metres: maximum_foot_step,
207:                 maximum_knee_root_relative_step_metres: maximum_knee_step,
208:                 worst_displacement,
209:                 maximum_bone_rotation_step_degrees: maximum_rotation,
210:                 maximum_foot_rotation_step_degrees: maximum_foot_rotation,
211:                 worst_rotation,
212:                 loop_seam_position_metres: seam.as_ref().map(|seam| seam.position_metres),
213:                 loop_seam_rotation_degrees: seam.as_ref().map(|seam| seam.rotation_degrees),
214:                 pelvis_vertical_range_metres: root_relative_vertical_range(
215:                     &metric_frames,
