1: //! Celestial lighting written into the materials that shade from it directly.
2: //!
3: //! Bark, tree impostors, vista cards, pebble billboards and foliage all carry
4: //! their own sun direction and ambient response rather than reading Bevy's
5: //! lights, so one system keeps them in step with the presented celestial
6: //! snapshot. It lives apart from any one of them because it owns none of them.
7: 
8: use super::PresentedCelestialLighting;
9: use super::ground_scatter::{TacticalFoliageMaterial, TacticalPebbleBillboardMaterial};
10: use super::obstacles::tree::{TacticalTreeBarkMaterial, TacticalTreeImpostorMaterial};
11: use super::vista::tree_cards::TacticalVistaTreeInstancedMaterial;
12: use bevy::prelude::*;
13: 
14: pub(in crate::presentation) fn update_celestial_material_lighting(
15:     celestial: Res<PresentedCelestialLighting>,
16:     mut bark_materials: ResMut<Assets<TacticalTreeBarkMaterial>>,
17:     mut impostor_materials: ResMut<Assets<TacticalTreeImpostorMaterial>>,
18:     mut vista_card_materials: ResMut<
19:         Assets<crate::presentation::vista::tree_cards::TacticalVistaTreeInstancedMaterial>,
20:     >,
21:     mut pebble_materials: ResMut<Assets<TacticalPebbleBillboardMaterial>>,
22:     mut written: Local<Option<(Vec4, Vec4)>>,
23:     mut foliage_materials: ResMut<Assets<TacticalFoliageMaterial>>,
24: ) {
25:     if !celestial.is_changed() {
26:         return;
27:     }
28:     let Some(celestial) = celestial.snapshot.as_ref() else {
29:         return;
30:     };
31:     let direction = if celestial.sun_altitude_degrees > -6.0 {
32:         celestial.sun_direction
33:     } else if celestial.moon_altitude_degrees > -2.0 {
34:         celestial.moon_direction
35:     } else {
36:         Vec3::new(0.25, 0.92, 0.3).normalize()
37:     };
38:     // The presented snapshot refreshes on every replicated environment tick,
39:     // but celestial motion is glacial on gameplay timescales. Rewriting the
40:     // material assets dirties them and re-queues every tree and pebble, so
41:     // skip the write until the change would be visible.
42:     let lighting = direction.extend(celestial.material_light_factor);
43:     let ambient = celestial
44:         .ambient_color
45:         .extend(celestial.material_ambient_response);
46:     if written.is_some_and(|(written_lighting, written_ambient)| {
47:         written_lighting.distance_squared(lighting) < 1e-6
48:             && written_ambient.distance_squared(ambient) < 1e-6
49:     }) {
50:         return;
51:     }
52:     *written = Some((lighting, ambient));
53:     for (_, material) in bark_materials.iter_mut() {
54:         material.extension.lighting = lighting;
55:     }
56:     for (_, material) in impostor_materials.iter_mut() {
57:         material.lighting = lighting;
58:         material.ambient = ambient;
59:     }
60:     for (_, material) in vista_card_materials.iter_mut() {
61:         material.lighting = lighting;
62:         material.ambient = ambient;
63:     }
64:     for (_, material) in pebble_materials.iter_mut() {
65:         material.lighting = lighting;
66:         material.ambient = ambient;
67:     }
68:     for (_, material) in foliage_materials.iter_mut() {
69:         if material.quality.x > 0.5 {
70:             material.lighting = direction.extend(celestial.material_light_factor);
71:             material.ambient = celestial
72:                 .ambient_color
73:                 .extend(celestial.material_ambient_response);
74:         }
75:     }
76: }
