410: #[allow(clippy::type_complexity)]
411: fn census_terrain(
412:     meshes: &Query<
413:         (
414:             &ViewVisibility,
415:             &TerrainTriangleCount,
416:             Has<TerrainDetailPatch>,
417:             Has<TerrainMaterialPresentation>,
418:             Option<&VistaTerrainMesh>,
419:         ),
420:         With<Mesh3d>,
421:     >,
422: ) -> BTreeMap<String, MeshTierCensus> {
423:     let mut result = BTreeMap::<String, MeshTierCensus>::new();
424:     for (visibility, triangles, detail, playable, vista) in meshes {
425:         let tier = if detail {
426:             "detail patch".to_owned()
427:         } else if playable {
428:             "playable terrain".to_owned()
429:         } else if let Some(vista) = vista {
430:             format!("vista LOD{}", vista.0)
431:         } else {
432:             continue;
433:         };
434:         record_mesh(result.entry(tier).or_default(), visibility, triangles.0);
435:     }
436:     result
437: }
438: 
439: fn census_buildings(
440:     meshes: &Query<(&ViewVisibility, &PresentedBuildingMesh), With<Mesh3d>>,
441: ) -> BTreeMap<String, MeshTierCensus> {
442:     let mut result = BTreeMap::<String, MeshTierCensus>::new();
443:     for (visibility, building) in meshes {
444:         let tier = format!("{:?}/{:?}", building.level, building.material);
445:         record_mesh(
446:             result.entry(tier).or_default(),
447:             visibility,
448:             building.triangles,
449:         );
450:     }
451:     result
452: }
453: 
454: fn census_grass(
455:     chunks: &Query<
456:         (
457:             &GroundScatterLayer,
458:             &InstanceChunk,
459:             &ViewVisibility,
460:             &GrassTriangleCount,
461:         ),
462:         Without<TacticalGameplayCamera>,
463:     >,
464:     camera_position: Vec3,
465: ) -> BTreeMap<String, GrassTierCensus> {
466:     let mut result = BTreeMap::<String, GrassTierCensus>::new();
467:     for (layer, chunk, visibility, triangle_count) in chunks {
468:         if *layer != GroundScatterLayer::Grass {
469:             continue;
470:         }
471:         let triangles_per_tuft = triangle_count.0;
472:         let band = chunk.band.shader_range();
473:         let tier = result
474:             .entry(format!("{:.3}-{:.3} metres", band.x, band.w))
475:             .or_default();
476:         let resident_tufts = chunk.instances.len();
477:         let drawn_tufts = if visibility.get() {
478:             chunk
479:                 .instances
480:                 .iter()
481:                 .filter(|instance| {
482:                     let distance = instance.position.distance(camera_position);
483:                     distance >= band.x && distance <= band.w
484:                 })
485:                 .count()
486:         } else {
487:             0
488:         };
489:         tier.resident_chunks += 1;
490:         tier.resident_tufts += resident_tufts;
491:         tier.drawn_tufts += drawn_tufts;
492:         tier.resident_triangles += resident_tufts * triangles_per_tuft;
493:         tier.drawn_triangles += drawn_tufts * triangles_per_tuft;
494:     }
495:     result
496: }
497: 
498: fn record_mesh(tier: &mut MeshTierCensus, visibility: &ViewVisibility, triangles: usize) {
499:     tier.resident_meshes += 1;
500:     tier.resident_triangles += triangles;
501:     if visibility.get() {
502:         tier.view_visible_meshes += 1;
503:         tier.view_visible_triangles += triangles;
504:     }
505: }

