113: pub(super) fn vista_rock_mesh() -> Mesh {
114:     let vertices = [
115:         Vec3::new(-0.58, -0.36, -0.48),
116:         Vec3::new(0.52, -0.36, -0.44),
117:         Vec3::new(0.61, -0.28, 0.42),
118:         Vec3::new(-0.49, -0.31, 0.55),
119:         Vec3::new(-0.37, 0.31, -0.33),
120:         Vec3::new(0.32, 0.42, -0.29),
121:         Vec3::new(0.39, 0.27, 0.31),
122:         Vec3::new(-0.31, 0.36, 0.38),
123:     ];
124:     let faces = [
125:         [0, 2, 1],
126:         [0, 3, 2],
127:         [4, 5, 6],
128:         [4, 6, 7],
129:         [0, 1, 5],
130:         [0, 5, 4],
131:         [1, 2, 6],
132:         [1, 6, 5],
133:         [2, 3, 7],
134:         [2, 7, 6],
135:         [3, 0, 4],
136:         [3, 4, 7],
137:     ];
138:     let mut positions = Vec::with_capacity(faces.len() * 3);
139:     let mut normals = Vec::with_capacity(faces.len() * 3);
140:     for [a, b, c] in faces {
141:         let normal = (vertices[b] - vertices[a])
142:             .cross(vertices[c] - vertices[a])
143:             .normalize_or_zero();
144:         positions.extend([
145:             vertices[a].to_array(),
146:             vertices[b].to_array(),
147:             vertices[c].to_array(),
148:         ]);
149:         normals.extend([normal.to_array(); 3]);
150:     }
151:     let mut mesh = Mesh::new(
152:         PrimitiveTopology::TriangleList,
153:         RenderAssetUsages::RENDER_WORLD,
154:     );
155:     mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, positions);
156:     mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, normals);
157:     mesh
158: }
