164: pub(super) fn spawn_vista_trees(
165:     commands: &mut Commands,
166:     lod: &VistaLod,
167:     coarser_lod: Option<&VistaLod>,
168:     playable_half_extent: Vec2,
169:     scene_digest: &str,
170:     environment: Option<&SceneEnvironment>,
171:     terrain: &SceneTerrain,
172:     meshes: &mut Assets<Mesh>,
173:     materials: &mut tree_cards::VistaTreeMaterials<'_>,
174:     images: &mut Assets<Image>,
175:     cache: &mut VistaTreePresentationCache,
176:     prepared: Option<&PreparedTreeImpostorAsset>,
177: ) {
178:     let width = usize::from(lod.width);
179:     let depth = usize::from(lod.depth);
180:     let center = Vec2::new((width - 1) as f32, (depth - 1) as f32) * 0.5;
181:     let scene_seed = stable_text_seed(scene_digest);
182:     let mut batches = tree_cards::VistaCardBatches::default();
183:     for z in 0..depth - 1 {
184:         for x in 0..width - 1 {
185:             let sample = lod.environment[z * width + x];
186:             let canopy = bps(sample.canopy_bps)
187:                 * (1.0 - bps(sample.water_bps))
188:                 * (1.0 - bps(sample.cultivation_bps) * 0.85);
189:             // A regional source cell represents a stand, not individual
190:             // stems. Keep a physical-area-scaled silhouette sample; the
191:             // terrain material carries the remaining aggregate canopy.
192:             let candidate_count = vista_tree_candidate_count(
193:                 canopy,
194:                 lod.spacing_metres,
195:                 streams::tree_count_seed(scene_seed, x, z),
196:             )
197:             .min(if lod.spacing_metres <= 250.0 { 24 } else { 3 });
198:             if candidate_count == 0 {
199:                 continue;
200:             }
201:             let cell_min = (Vec2::new(x as f32, z as f32) - center) * lod.spacing_metres;
202:             for candidate in 0..candidate_count {
203:                 let hash = streams::tree_seed(scene_seed, x, z, candidate);
204:                 let local = cell_min + streams::tree_jitter(hash) * lod.spacing_metres;
205:                 if local.x.abs() <= playable_half_extent.x + 7.0
206:                     && local.y.abs() <= playable_half_extent.y + 7.0
207:                 {
208:                     continue;
209:                 }
210:                 let world = local
211:                     + Vec2::new(
212:                         lod.origin_east_metres as f32,
213:                         lod.origin_north_metres as f32,
214:                     );
215:                 let Some(world) = ScenePlanPoint::from_metres(world) else {
216:                     continue;
217:                 };
218:                 let Some(height) = tree_root_height(terrain, lod, coarser_lod, world) else {
219:                     continue;
220:                 };
221:                 // One calibrated whole-tree atlas avoids baking for every source cell.
222:                 let variant_seed =
223:                     crate::presentation::obstacles::tree::specimen::oak_variant_seed(0);
224:                 let species = vista_tree_species(environment, local);
225:                 let cached = ensure_vista_tree_variant(
226:                     variant_seed,
227:                     0.5,
228:                     species,
229:                     meshes,
230:                     &mut materials.impostor,
231:                     images,
232:                     cache,
233:                     prepared,
234:                 );
235:                 // Each atlas represents the visible crown mass of a small
236:                 // stand at regional distance, not a survey-accurate stem.
237:                 let scale = vista_tree_scale(
238:                     lod.spacing_metres,
239:                     streams::TREE_SCALE.rng(hash, &[]).inclusive_unit_f32(),
240:                 );
241:                 let card_height = cached
242:                     .provenance
243:                     .records
244:                     .first()
245:                     .map_or(12.0, |record| record.projected_bounds.w);
246:                 batches.push(
247:                     &cached.mesh,
248:                     &cached.material,
249:                     card_height,
250:                     crate::presentation::chunk_instancing::ChunkInstance {
251:                         position: Vec3::new(local.x, height.metres(), local.y),
252:                         scale,
253:                         ..Default::default()
254:                     },
255:                 );
256:             }
257:         }
258:     }
259:     batches.spawn(commands, lod, materials);
260: }
