262: pub(super) const VISTA_TREE_MAX_ANGULAR_HEIGHT_RADIANS: f32 = 16.0_f32.to_radians();
263: 
264: pub(super) fn vista_tree_scale(spacing_metres: f32, variation: f32) -> f32 {
265:     // Candidate count already represents regional stand density. Each card
266:     // must remain one plausible tree; scaling a single trunk into a 32-metre
267:     // stand creates the near-ring columns seen from the playable scene.
268:     let coarse_scale = if spacing_metres <= 250.0 { 1.0 } else { 1.25 };
269:     (0.85 + variation.clamp(0.0, 1.0) * 0.4) * coarse_scale
270: }
271: 
272: pub(super) fn vista_tree_visibility(
273:     spacing_metres: f32,
274:     unscaled_card_height: f32,
275:     scale: f32,
276: ) -> VisibilityRange {
277:     let scaled_height = unscaled_card_height.max(0.0) * scale.max(0.0);
278:     // Keep regional stand cards out of the near field. The first visible
279:     // sample is at most 16 degrees; the fade completes farther away. Using
280:     // this distance as the end of the fade admitted partially visible 17-19
281:     // degree cards, contradicting the background-size contract.
282:     let first_visible_distance =
283:         scaled_height / (2.0 * (VISTA_TREE_MAX_ANGULAR_HEIGHT_RADIANS * 0.5).tan());
284:     VisibilityRange {
285:         start_margin: first_visible_distance..(first_visible_distance * 1.12),
286:         end_margin: if spacing_metres <= 250.0 {
287:             1_600.0..1_900.0
288:         } else {
289:             4_600.0..5_200.0
290:         },
291:         use_aabb: false,
292:     }
293: }
294: 
295: pub(super) fn vista_tree_candidate_count(canopy: f32, spacing_metres: f32, seed: Seed) -> usize {
296:     let expected = canopy.clamp(0.0, 1.0) * spacing_metres * spacing_metres / 3_200.0;
297:     expected.floor() as usize
298:         + usize::from(
299:             streams::TREE_COUNT_FRACTION
300:                 .rng(seed, &[])
301:                 .inclusive_unit_f32()
302:                 < expected.fract(),
303:         )
304: }
