crates/adventuresim-tactical-client/src/loading_screen.rs
1: //! Full-screen gate between joining a tactical scene and playing it.
2: //!
3: //! A load begins whenever a tactical client is spawned, on native startup and
4: //! on browser `enter-tactical` alike. The scene builds behind the opaque
5: //! screen so that its render pipelines compile before the player can see or
6: //! control it. Losing the connection, a failed required asset and a stage that
7: //! stops advancing all end in a failure panel with retry and exit actions.
8: use crate::{
9:     equipment::{EquipmentHudSet, settlement::EquipmentSettlement},
10:     player::ClientPlayer,
11:     presentation::{
12:         ClientStartupTiming, is_required_scene_asset,
13:         pipeline_readiness::{self, waiting_pipelines},
14:     },
15: };
16: use adventuresim_tactical_core::prelude::{ContextActivity, Player};
17: use adventuresim_tactical_netcode::prelude::{
18:     AdventureSimulatorClient, DisconnectReason, Disconnected,
19: };
20: use bevy::{asset::UntypedAssetLoadFailedEvent, prelude::*};
21: use bevy_egui::EguiPrimaryContextPass;
22: use progress::{LoadingFailure, LoadingRun, RunVerdict};
23: use sources::LoadingSources;
24: 
25: mod progress;
26: mod sources;
27: mod view;
28: 
29: const REVEAL_SECONDS: f32 = 0.6;
30: 
31: struct LoadingScreenPlugin;
32: 
33: /// Progress of the current tactical load, if any.
34: #[derive(Resource, Default)]
35: pub(crate) struct LoadingScreen {
36:     phase: LoadingPhase,
37:     /// A failed session despawns its client, so retry keeps its own copy.
38:     connection: Option<AdventureSimulatorClient>,
39: }
40: 
41: #[derive(Default)]
42: enum LoadingPhase {
43:     #[default]
44:     Idle,
45:     Loading(LoadingRun),
46:     Failed(LoadingFailure),
47:     Revealing(Timer),
48: }
49: 
50: impl LoadingScreen {
51:     /// Whether the player may see and control the scene.
52:     pub(crate) fn gameplay_unlocked(&self) -> bool {
53:         matches!(self.phase, LoadingPhase::Idle | LoadingPhase::Revealing(_))
54:     }
55: 
56:     /// Abandons the load when the browser leaves tactical play.
57:     #[cfg(target_family = "wasm")]
58:     pub(crate) fn dismiss(&mut self) {
59:         self.phase = LoadingPhase::Idle;
60:         self.connection = None;
61:     }
62: 
63:     fn fail(&mut self, failure: LoadingFailure) {
64:         if matches!(self.phase, LoadingPhase::Loading(_)) {
65:             warn!(%failure, "Tactical loading failed");
66:             self.phase = LoadingPhase::Failed(failure);
67:         }
68:     }
69: }
70: 
71: impl Plugin for LoadingScreenPlugin {
72:     fn build(&self, app: &mut App) {
73:         app.init_resource::<LoadingScreen>()
74:             .add_observer(begin_load)
75:             .add_observer(fail_on_disconnect)
76:             .add_systems(Startup, view::spawn)
77:             .add_systems(
78:                 Update,
79:                 (
80:                     fail_on_required_asset,
81:                     advance_load,
82:                     hold_new_players,
83:                     view::handle_actions,
84:                     view::sync_stage_bars,
85:                     view::sync_overlay,
86:                 )
87:                     .chain(),
88:             );
89:     }
90: }
91: 
92: /// Adds the loading gate to a client. Headless automation has no one to show
93: /// it to and drives input itself, so it runs without one.
94: pub(crate) fn install(app: &mut App, headless: bool) {
95:     pipeline_readiness::install(app);
96:     if !headless {
97:         app.add_plugins(LoadingScreenPlugin);
98:     }
99:     app.configure_sets(
100:         EguiPrimaryContextPass,
101:         EquipmentHudSet.run_if(gameplay_unlocked),
102:     );
103: }
104: 
105: /// Run condition for systems that must wait for the scene to be revealed.
106: /// Clients without the plugin, such as headless automation, are never held.
107: pub(crate) fn gameplay_unlocked(screen: Option<Res<LoadingScreen>>) -> bool {
108:     screen.is_none_or(|screen| screen.gameplay_unlocked())
109: }
110: 
111: /// Run condition for overlays of the local player's own state.
112: pub(crate) fn local_player_revealed(
113:     screen: Option<Res<LoadingScreen>>,
114:     players: Query<(), With<ClientPlayer>>,
115: ) -> bool {
116:     !players.is_empty() && gameplay_unlocked(screen)
117: }
118: 
119: fn begin_load(
120:     client: On<Add, AdventureSimulatorClient>,
121:     clients: Query<&AdventureSimulatorClient>,
122:     mut screen: ResMut<LoadingScreen>,
123:     time: Res<Time>,
124: ) -> Result {
125:     screen.connection = Some(clients.get(client.entity)?.clone());
126:     screen.phase = LoadingPhase::Loading(LoadingRun::new(time.elapsed()));
127:     Ok(())
128: }
129: 
130: fn fail_on_disconnect(
131:     disconnected: On<Disconnected>,
132:     clients: Query<(), With<AdventureSimulatorClient>>,
133:     mut screen: ResMut<LoadingScreen>,
134: ) {
135:     if !clients.contains(disconnected.entity) {
136:         return;
137:     }
138:     let reason = match &disconnected.reason {
139:         DisconnectReason::ByUser(reason) | DisconnectReason::ByPeer(reason) => reason.clone(),
140:         DisconnectReason::ByError(error) => format!("{error:#}"),
141:     };
142:     screen.fail(LoadingFailure::ConnectionLost(reason));
143: }
144: 
145: fn fail_on_required_asset(
146:     mut events: MessageReader<UntypedAssetLoadFailedEvent>,
147:     mut screen: ResMut<LoadingScreen>,
148: ) {
149:     for event in events.read() {
150:         let path = event.path.path();
151:         if is_required_scene_asset(path) {
152:             screen.fail(LoadingFailure::Asset(path.display().to_string()));
153:         }
154:     }
155: }
156: 
157: fn advance_load(
158:     mut commands: Commands,
159:     mut screen: ResMut<LoadingScreen>,
160:     sources: LoadingSources,
161:     equipment: EquipmentSettlement,
162:     players: Query<Entity, With<ClientPlayer>>,
163:     startup: Res<ClientStartupTiming>,
164:     time: Res<Time>,
165: ) {
166:     let run = match &mut screen.phase {
167:         LoadingPhase::Loading(run) => run,
168:         LoadingPhase::Revealing(timer) => {
169:             if timer.tick(time.delta()).is_finished() {
170:                 screen.phase = LoadingPhase::Idle;
171:             }
172:             return;
173:         }
174:         LoadingPhase::Idle | LoadingPhase::Failed(_) => return,
175:     };
176:     let progress = sources.progress(run, equipment.is_settled(), waiting_pipelines());
177:     match run.observe(progress, time.elapsed()) {
178:         RunVerdict::Stalled(stage) => screen.fail(LoadingFailure::Stalled(stage)),
179:         RunVerdict::Ready => {
180:             startup.mark("tactical scene ready; revealing");
181:             for player in &players {
182:                 commands
183:                     .entity(player)
184:                     .insert(ContextActivity::<Player>::ACTIVE);
185:             }
186:             screen.phase =
187:                 LoadingPhase::Revealing(Timer::from_seconds(REVEAL_SECONDS, TimerMode::Once));
188:         }
189:         RunVerdict::Waiting => {}
190:     }
191: }
192: 
193: /// Keeps a player that arrives mid-load from moving behind the screen.
194: fn hold_new_players(
195:     mut commands: Commands,
196:     screen: Res<LoadingScreen>,
197:     players: Query<Entity, Added<ClientPlayer>>,
198: ) {
199:     if screen.gameplay_unlocked() {
200:         return;
201:     }
202:     for player in &players {
203:         commands
204:             .entity(player)
205:             .insert(ContextActivity::<Player>::INACTIVE);
206:     }
207: }
crates/adventuresim-tactical-client/src/loading_screen/progress.rs
1: //! Loading stages and the rules that decide when a load is ready or stuck.
2: use crate::presentation::pipeline_readiness::SETTLED_RENDER_FRAMES;
3: use std::{fmt, time::Duration};
4: 
5: /// How long every stage may stand still before the load counts as stuck. Long
6: /// enough for one slow browser pipeline compile; the connection has no timeout
7: /// of its own, so this also bounds an unanswered connect. Measured in game
8: /// time, because a browser stops running frames in a background tab and the
9: /// wall clock would fail the load the moment the tab returned.
10: const STALL_LIMIT: Duration = Duration::from_secs(90);
11: 
12: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
13: pub(super) enum LoadingStage {
14:     Connection,
15:     Character,
16:     Textures,
17:     Terrain,
18:     Vista,
19:     Trees,
20:     GroundCover,
21:     Sky,
22:     Equipment,
23:     Pose,
24:     Shaders,
25: }
26: 
27: impl LoadingStage {
28:     pub(super) const ALL: [Self; 11] = [
29:         Self::Connection,
30:         Self::Character,
31:         Self::Textures,
32:         Self::Terrain,
33:         Self::Vista,
34:         Self::Trees,
35:         Self::GroundCover,
36:         Self::Sky,
37:         Self::Equipment,
38:         Self::Pose,
39:         Self::Shaders,
40:     ];
41: 
42:     pub(super) fn label(self) -> &'static str {
43:         match self {
44:             Self::Connection => "Connecting to the server",
45:             Self::Character => "Joining the scene",
46:             Self::Textures => "Loading textures",
47:             Self::Terrain => "Shaping the terrain",
48:             Self::Vista => "Raising the distant landscape",
49:             Self::Trees => "Growing trees",
50:             Self::GroundCover => "Laying ground cover",
51:             Self::Sky => "Lighting the sky",
52:             Self::Equipment => "Fitting equipment",
53:             Self::Pose => "Posing your character",
54:             Self::Shaders => "Compiling shaders",
55:         }
56:     }
57: }
58: 
59: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
60: pub(super) struct StageProgress {
61:     pub(super) completed: usize,
62:     pub(super) total: usize,
63: }
64: 
65: impl StageProgress {
66:     pub(super) const PENDING: Self = Self {
67:         completed: 0,
68:         total: 1,
69:     };
70:     pub(super) const FINISHED: Self = Self {
71:         completed: 1,
72:         total: 1,
73:     };
74: 
75:     pub(super) fn from_flag(finished: bool) -> Self {
76:         if finished {
77:             Self::FINISHED
78:         } else {
79:             Self::PENDING
80:         }
81:     }
82: 
83:     pub(super) fn is_finished(self) -> bool {
84:         self.total > 0 && self.completed >= self.total
85:     }
86: 
87:     pub(super) fn fraction(self) -> f32 {
88:         if self.total == 0 {
89:             return 0.0;
90:         }
91:         self.completed.min(self.total) as f32 / self.total as f32
92:     }
93: }
94: 
95: /// One entry per [`LoadingStage`], in [`LoadingStage::ALL`] order.
96: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
97: pub(super) struct LoadingProgress {
98:     stages: [StageProgress; LoadingStage::ALL.len()],
99: }
100: 
101: impl LoadingProgress {
102:     pub(super) fn get(&self, stage: LoadingStage) -> StageProgress {
103:         self.stages[stage as usize]
104:     }
105: 
106:     pub(super) fn set(&mut self, stage: LoadingStage, progress: StageProgress) {
107:         self.stages[stage as usize] = progress;
108:     }
109: 
110:     fn first_unfinished(&self) -> Option<LoadingStage> {
111:         LoadingStage::ALL
112:             .into_iter()
113:             .find(|stage| !self.get(*stage).is_finished())
114:     }
115: }
116: 
117: /// Turns a shrinking backlog into progress. The size of a backlog is unknown
118: /// up front, so its largest observed size stands in for the total.
119: #[derive(Clone, Copy, Debug, Default)]
120: pub(super) struct BacklogPeak(usize);
121: 
122: impl BacklogPeak {
123:     pub(super) fn observe(&mut self, pending: usize) -> StageProgress {
124:         self.0 = self.0.max(pending);
125:         if self.0 == 0 {
126:             return StageProgress::FINISHED;
127:         }
128:         StageProgress {
129:             completed: self.0 - pending,
130:             total: self.0,
131:         }
132:     }
133: }
134: 
135: pub(super) enum RunVerdict {
136:     Waiting,
137:     Ready,
138:     Stalled(LoadingStage),
139: }
140: 
141: /// One attempt at loading a scene.
142: pub(super) struct LoadingRun {
143:     pub(super) progress: LoadingProgress,
144:     pub(super) trees: BacklogPeak,
145:     pub(super) pipelines: BacklogPeak,
146:     settled_frames: usize,
147:     last_advance: Duration,
148: }
149: 
150: impl LoadingRun {
151:     pub(super) fn new(now: Duration) -> Self {
152:         Self {
153:             progress: LoadingProgress::default(),
154:             trees: BacklogPeak::default(),
155:             pipelines: BacklogPeak::default(),
156:             settled_frames: 0,
157:             last_advance: now,
158:         }
159:     }
160: 
161:     pub(super) fn observe(&mut self, progress: LoadingProgress, now: Duration) -> RunVerdict {
162:         if progress != self.progress {
163:             self.last_advance = now;
164:         }
165:         self.progress = progress;
166:         let Some(stage) = progress.first_unfinished() else {
167:             self.settled_frames += 1;
168:             return if self.settled_frames >= SETTLED_RENDER_FRAMES {
169:                 RunVerdict::Ready
170:             } else {
171:                 RunVerdict::Waiting
172:             };
173:         };
174:         self.settled_frames = 0;
175:         if now.saturating_sub(self.last_advance) >= STALL_LIMIT {
176:             RunVerdict::Stalled(stage)
177:         } else {
178:             RunVerdict::Waiting
179:         }
180:     }
181: }
182: 
183: /// Why a load stopped. Presentation text comes from [`fmt::Display`].
184: #[derive(Clone, Debug, Eq, PartialEq)]
185: pub(super) enum LoadingFailure {
186:     ConnectionLost(String),
187:     Asset(String),
188:     Stalled(LoadingStage),
189: }
190: 
191: impl fmt::Display for LoadingFailure {
192:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
193:         match self {
194:             Self::ConnectionLost(reason) => write!(formatter, "Connection lost: {reason}"),
195:             Self::Asset(path) => write!(formatter, "Could not load {path}"),
196:             Self::Stalled(stage) => {
197:                 write!(formatter, "Loading stopped at: {}", stage.label())
198:             }
199:         }
200:     }
201: }

