1: //! Render-world pipeline telemetry shared by every loading gate.
2: use bevy::{
3:     prelude::*,
4:     render::{Render, RenderApp, RenderSystems, render_resource::PipelineCache},
5: };
6: use std::sync::atomic::{AtomicUsize, Ordering};
7: 
8: static WAITING_PIPELINES: AtomicUsize = AtomicUsize::new(0);
9: 
10: /// Consecutive ready frames required before a loading gate trusts readiness.
11: pub(crate) const SETTLED_RENDER_FRAMES: usize = 4;
12: 
13: pub(crate) fn install(app: &mut App) {
14:     if let Some(render) = app.get_sub_app_mut(RenderApp) {
15:         render.add_systems(Render, pipeline_status.after(RenderSystems::Prepare));
16:     }
17: }
18: 
19: /// Number of pipelines the render world has queued but not finished compiling.
20: pub(crate) fn waiting_pipelines() -> usize {
21:     WAITING_PIPELINES.load(Ordering::Relaxed)
22: }
23: 
24: fn pipeline_status(cache: Res<PipelineCache>) {
25:     WAITING_PIPELINES.store(cache.waiting_pipelines().count(), Ordering::Relaxed);
26: }
