1: //! Read-only view of tactical scene presentation for loading gates.
2: use super::{
3:     PendingTerrainPresentation, VistaTerrain,
4:     ground_scatter::{GroundScatterPresented, InstancedGrassPresented},
5:     obstacles::tree::PendingTreePresentation,
6: };
7: use adventuresim_tactical_core::prelude::SceneTerrain;
8: use bevy::{ecs::system::SystemParam, prelude::*};
9: 
10: type ScenePresentationState = (
11:     Has<PendingTerrainPresentation>,
12:     Has<GroundScatterPresented>,
13:     Has<InstancedGrassPresented>,
