19: pub(crate) struct SceneReadiness<'w, 's> {
20:     scenes: Query<'w, 's, ScenePresentationState, With<SceneTerrain>>,
21:     trees: Query<'w, 's, (), With<PendingTreePresentation>>,
22:     vista: Query<'w, 's, (), With<VistaTerrain>>,
23: }
24: 
25: /// Completed work against the scenes replicated so far.
26: #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
