35: impl SceneReadiness<'_, '_> {
36:     pub(crate) fn counts(&self) -> SceneReadinessCounts {
37:         let mut counts = SceneReadinessCounts {
38:             pending_trees: self.trees.iter().count(),
39:             vista_presented: !self.vista.is_empty(),
40:             ..default()
41:         };
42:         for (terrain_pending, scatter, grass) in &self.scenes {
43:             counts.scenes += 1;
44:             counts.terrain_presented += usize::from(!terrain_pending);
45:             counts.ground_layers_presented += usize::from(scatter) + usize::from(grass);
46:         }
47:         counts
48:     }
