1: //! The loading overlay. Built directly in bevy_ui rather than `ui.css` because
2: //! the fade drives every colour's alpha, which flair has no property for, and
3: //! the screen must not depend on a stylesheet that is itself still loading.
4: use super::{LoadingPhase, LoadingScreen, progress::LoadingStage};
5: use adventuresim_tactical_netcode::prelude::AdventureSimulatorClient;
6: use bevy::prelude::*;
7: 
8: const FONT_ASSET: &str = "SNPro-VariableFont_wght.ttf";
9: /// Above the HUD and every other UI root.
10: const OVERLAY_Z_INDEX: i32 = 1_000;
11: const TITLE_SIZE: f32 = 40.0;
12: const STAGE_TEXT_SIZE: f32 = 16.0;
13: const BACKDROP: Color = Color::srgb(0.02, 0.024, 0.031);
14: const TEXT: Color = Color::srgba(1.0, 1.0, 1.0, 0.8);
15: const TRACK: Color = Color::srgba(1.0, 1.0, 1.0, 0.1);
16: const ACTIVE_FILL: Color = Color::srgb(0.565, 0.792, 0.976);
17: const FINISHED_FILL: Color = Color::srgb(0.506, 0.78, 0.518);
18: const FAILURE_TEXT: Color = Color::srgb(0.898, 0.451, 0.451);
19: const BUTTON: Color = Color::srgba(1.0, 1.0, 1.0, 0.12);
20: 
21: type OverlayRootOnly = (With<LoadingRoot>, Without<FailurePanel>);
22: 
23: #[derive(Component)]
24: pub(super) struct LoadingRoot;
25: 
26: /// Base colour of a node or text; the fade scales its alpha.
27: #[derive(Component, Clone, Copy)]
28: pub(super) struct FadeColor(Color);
29: 
30: #[derive(Component)]
31: pub(super) struct StageFill(LoadingStage);
32: 
33: #[derive(Component)]
34: pub(super) struct FailurePanel;
35: 
36: #[derive(Component)]
37: pub(super) struct FailureMessage;
38: 
39: #[derive(Component, Clone, Copy)]
