41:     Retry,
42:     Exit,
43: }
44: 
45: struct OverlayFont(FontSource);
46: 
47: impl OverlayFont {
48:     fn sized(&self, size: f32) -> TextFont {
49:         TextFont {
50:             font: self.0.clone(),
51:             font_size: FontSize::Px(size),
52:             ..default()
53:         }
54:     }
