57: pub(super) fn spawn(mut commands: Commands, asset_server: Res<AssetServer>) {
58:     let font = OverlayFont(asset_server.load(FONT_ASSET).into());
59:     commands
60:         .spawn((
61:             LoadingRoot,
62:             Name::new("loading-screen"),
63:             GlobalZIndex(OVERLAY_Z_INDEX),
64:             FadeColor(BACKDROP),
65:             BackgroundColor(BACKDROP),
66:             Node {
67:                 position_type: PositionType::Absolute,
68:                 width: percent(100),
69:                 height: percent(100),
70:                 display: Display::None,
71:                 flex_direction: FlexDirection::Column,
72:                 justify_content: JustifyContent::Center,
73:                 align_items: AlignItems::Center,
74:                 row_gap: px(8),
75:                 ..default()
76:             },
77:         ))
78:         .with_children(|root| {
79:             root.spawn((
80:                 Text::new("Fabelgeist"),
81:                 font.sized(TITLE_SIZE),
82:                 TextColor(TEXT),
83:                 FadeColor(TEXT),
84:                 Node {
85:                     margin: UiRect::bottom(px(24)),
86:                     ..default()
87:                 },
88:             ));
89:             for stage in LoadingStage::ALL {
90:                 spawn_stage_row(root, &font, stage);
91:             }
92:             spawn_failure_panel(root, &font);
93:         });
