96: fn spawn_stage_row(root: &mut ChildSpawnerCommands, font: &OverlayFont, stage: LoadingStage) {
97:     root.spawn(Node {
98:         width: px(440),
99:         max_width: percent(90),
100:         flex_direction: FlexDirection::Column,
101:         row_gap: px(3),
102:         ..default()
103:     })
104:     .with_children(|row| {
105:         row.spawn((
106:             Text::new(stage.label()),
107:             font.sized(STAGE_TEXT_SIZE),
108:             TextColor(TEXT),
