111:         row.spawn((
112:             BackgroundColor(TRACK),
113:             FadeColor(TRACK),
114:             Node {
115:                 width: percent(100),
116:                 height: px(4),
117:                 ..default()
118:             },
119:         ))
120:         .with_child((
121:             StageFill(stage),
122:             BackgroundColor(ACTIVE_FILL),
123:             FadeColor(ACTIVE_FILL),
124:             Node {
125:                 width: percent(0),
126:                 height: percent(100),
127:                 ..default()
128:             },
