133: fn spawn_failure_panel(root: &mut ChildSpawnerCommands, font: &OverlayFont) {
134:     root.spawn((
135:         FailurePanel,
136:         Node {
137:             display: Display::None,
138:             max_width: percent(90),
139:             flex_direction: FlexDirection::Column,
140:             align_items: AlignItems::Center,
141:             row_gap: px(12),
142:             margin: UiRect::top(px(20)),
143:             ..default()
144:         },
145:     ))
146:     .with_children(|panel| {
147:         panel.spawn((
148:             FailureMessage,
149:             Text::default(),
150:             font.sized(STAGE_TEXT_SIZE),
151:             TextColor(FAILURE_TEXT),
152:             FadeColor(FAILURE_TEXT),
153:         ));
154:         panel
155:             .spawn(Node {
156:                 column_gap: px(12),
157:                 ..default()
158:             })
159:             .with_children(|buttons| {
160:                 for (action, label) in [
161:                     (LoadingAction::Retry, "Retry"),
162:                     (LoadingAction::Exit, "Exit"),
163:                 ] {
164:                     buttons
165:                         .spawn((
166:                             action,
167:                             Button,
168:                             BackgroundColor(BUTTON),
169:                             FadeColor(BUTTON),
170:                             Node {
171:                                 padding: UiRect::axes(px(20), px(8)),
172:                                 ..default()
173:                             },
174:                         ))
175:                         .with_child((
176:                             Text::new(label),
177:                             font.sized(STAGE_TEXT_SIZE),
178:                             TextColor(TEXT),
179:                             FadeColor(TEXT),
180:                         ));
181:                 }
182:             });
183:     });
184: }
185: 
186: pub(super) fn handle_actions(
187:     mut commands: Commands,
188:     screen: Res<LoadingScreen>,
189:     actions: Query<(&Interaction, &LoadingAction), Changed<Interaction>>,
190:     clients: Query<Entity, With<AdventureSimulatorClient>>,
191:     mut exit: MessageWriter<AppExit>,
192: ) {
193:     if !matches!(screen.phase, LoadingPhase::Failed(_)) {
194:         return;
195:     }
196:     for (interaction, action) in &actions {
197:         if *interaction != Interaction::Pressed {
198:             continue;
199:         }
200:         match action {
201:             LoadingAction::Retry => {
202:                 if let Some(connection) = &screen.connection {
203:                     // A load can fail with its session still open.
204:                     for client in &clients {
205:                         commands.entity(client).despawn();
206:                     }
207:                     commands.spawn(connection.clone());
208:                 }
209:             }
210:             LoadingAction::Exit => leave_tactical(&mut exit),
211:         }
212:     }
213: }
214: 
215: #[cfg(not(target_family = "wasm"))]
216: fn leave_tactical(exit: &mut MessageWriter<AppExit>) {
217:     exit.write(AppExit::Success);
218: }
219: 
220: /// The host page owns navigation, so the browser client only asks it to leave.
221: #[cfg(target_family = "wasm")]
222: fn leave_tactical(_exit: &mut MessageWriter<AppExit>) {
223:     crate::browser_runtime::request_tactical_exit();
224: }
225: 
226: pub(super) fn sync_stage_bars(
227:     screen: Res<LoadingScreen>,
228:     mut fills: Query<(&StageFill, &mut Node, &mut FadeColor)>,
229: ) {
230:     let LoadingPhase::Loading(run) = &screen.phase else {
231:         return;
232:     };
233:     for (fill, mut node, mut color) in &mut fills {
234:         let stage = run.progress.get(fill.0);
235:         node.width = percent(stage.fraction() * 100.0);
236:         color.0 = if stage.is_finished() {
237:             FINISHED_FILL
238:         } else {
239:             ACTIVE_FILL
240:         };
241:     }
242: }
243: 
244: pub(super) fn sync_overlay(
245:     screen: Res<LoadingScreen>,
246:     mut root: Single<&mut Node, OverlayRootOnly>,
247:     mut failure_panel: Single<&mut Node, With<FailurePanel>>,
248:     mut failure_message: Single<&mut Text, With<FailureMessage>>,
249:     mut colors: Query<(
250:         &FadeColor,
251:         Option<&mut BackgroundColor>,
252:         Option<&mut TextColor>,
253:     )>,
254: ) {
255:     let opacity = match &screen.phase {
256:         LoadingPhase::Idle => {
257:             root.display = Display::None;
258:             return;
259:         }
260:         LoadingPhase::Loading(_) | LoadingPhase::Failed(_) => 1.0,
261:         LoadingPhase::Revealing(timer) => timer.fraction_remaining(),
262:     };
263:     root.display = Display::Flex;
264:     if let LoadingPhase::Failed(failure) = &screen.phase {
265:         failure_panel.display = Display::Flex;
266:         failure_message.0 = failure.to_string();
267:     } else {
268:         failure_panel.display = Display::None;
269:     }
270:     for (base, background, text) in &mut colors {
271:         let color = base.0.with_alpha(base.0.alpha() * opacity);
272:         // Text nodes also carry the `BackgroundColor` that `Node` requires.
273:         if let Some(mut text) = text {
274:             text.0 = color;
275:         } else if let Some(mut background) = background {
276:             background.0 = color;
277:         }
278:     }
279: }

