1: //! Logic for connection and disconnection of a [`Session`].
2: 
3: use {
4:     crate::{Session, SessionEndpoint},
5:     alloc::string::String,
6:     bevy_app::prelude::*,
7:     bevy_ecs::prelude::*,
8:     core::{fmt::Debug, net::SocketAddr},
9:     derive_more::Deref,
10:     log::debug,
11: };
12: 
13: pub(crate) struct ConnectionPlugin;
14: 
15: impl Plugin for ConnectionPlugin {
16:     fn build(&self, app: &mut App) {
17:         app.add_observer(on_connecting)
18:             .add_observer(on_connected)
19:             .add_observer(on_disconnect)
20:             .add_observer(on_disconnected);
21:     }
22: }
23: 
24: /// Triggered when a user requests a [`Session`] to gracefully disconnect from
25: /// its peer with a given reason.
26: ///
27: /// Triggering this will guarantee that the session is disconnected and
28: /// despawned immediately, however the disconnection reason will be transmitted
29: /// to the peer as a best-effort attempt. If the IO layer implementation does
30: /// not support disconnection reasons, or it cannot send your given reason (if
31: /// e.g. it is too long), the peer may not receive this disconnect reason.
32: ///
33: /// # Examples
34: ///
35: /// ```
36: /// use {aeronet_io::connection::Disconnect, bevy_ecs::prelude::*};
37: ///
38: /// # fn run(mut commands: Commands, session: Entity, session1: Entity, session2: Entity) {
39: /// // disconnect a session
40: /// commands.trigger(Disconnect::new(session, "show's over, go home"));
41: /// # }
42: /// ```
43: #[derive(Debug, Clone, PartialEq, Eq, EntityEvent)]
44: pub struct Disconnect {
45:     /// [`Session`] entity to be disconnected.
46:     pub entity: Entity,
47:     /// User-provided disconnection reason.
48:     ///
49:     /// Will be used as the reason in [`DisconnectReason::ByUser`].
50:     pub reason: String,
51: }
52: 
53: impl Disconnect {
54:     /// Creates a [`Disconnect`] with the given reason.
55:     #[must_use]
56:     pub fn new(entity: Entity, reason: impl Into<String>) -> Self {
57:         Self {
58:             entity,
59:             reason: reason.into(),
60:         }
61:     }
62: }
63: 
64: /// Triggered when a [`Session`] loses connection for any reason.
65: ///
66: /// Immediately after this, the session will be despawned **without a graceful
67: /// disconnect**. If you want to *request* the session to disconnect gracefully
68: /// via the IO layer, see [`Disconnect`].
69: ///
70: /// This must be triggered by the IO layer when it detects that the peer has
71: /// disconnected from us, or when it detects a connection error.
72: ///
73: /// This may also be used by code above the IO layer for e.g. signaling
74: /// transport errors, however this is not guaranteed.
75: #[derive(Debug, EntityEvent)]
76: pub struct Disconnected {
77:     /// [`Session`] entity which was disconnected.
78:     pub entity: Entity,
79:     /// Why the session was disconnected.
80:     pub reason: DisconnectReason,
81: }
82: 
83: /// Why a [`Disconnected`] was triggered.
84: #[derive(Debug)]
85: pub enum DisconnectReason {
86:     /// Session was disconnected by the user on our side, with a provided
87:     /// reason.
88:     ///
89:     /// On the peer, this will be interpreted as a [`DisconnectReason::ByPeer`]
90:     /// with the same reason.
91:     ByUser(String),
92:     /// Session was disconnected by the peer on the other side, with a provided
93:     /// reason.
94:     ///
95:     /// On the peer, this will be interpreted as a [`DisconnectReason::ByUser`]
96:     /// with the same reason.
97:     ByPeer(String),
98:     /// Session encountered a fatal connection error, and communication between
99:     /// this session and the peer is no longer possible.
100:     ///
101:     /// This may be caused by:
102:     /// - a bad network condition for a prolonged period of time
103:     /// - a malicious or malfunctioning peer
104:     /// - failing to send a message reliably
105:     /// - the peer pretending like there are network errors to discreetly force
106:     ///   us to disconnect
107:     /// - ..and more
108:     ///
109:     /// If you want to get the concrete error type, use
110:     /// [`anyhow::Error::downcast_ref`].
111:     ByError(anyhow::Error),
112: }
113: 
114: impl DisconnectReason {
115:     /// Creates a [`DisconnectReason::ByUser`] from the given reason.
116:     #[must_use]
117:     pub fn by_user(reason: impl Into<String>) -> Self {
118:         Self::ByUser(reason.into())
119:     }
120: 
121:     /// Creates a [`DisconnectReason::ByPeer`] from the given reason.
122:     #[must_use]
123:     pub fn by_peer(reason: impl Into<String>) -> Self {
124:         Self::ByPeer(reason.into())
125:     }
126: 
127:     /// Creates a [`DisconnectReason::ByError`] from the given reason.
128:     #[must_use]
129:     pub fn by_error(reason: impl Into<anyhow::Error>) -> Self {
130:         Self::ByError(reason.into())
131:     }
132: 
133:     /// If this value is a [`DisconnectReason::ByError`], creates a new
134:     /// [`DisconnectReason::ByError`] using the mapping function.
135:     #[must_use]
136:     pub fn map_err(self, f: impl FnOnce(anyhow::Error) -> anyhow::Error) -> Self {
137:         match self {
138:             Self::ByUser(reason) => Self::ByUser(reason),
139:             Self::ByPeer(reason) => Self::ByPeer(reason),
140:             Self::ByError(err) => Self::ByError(f(err)),
141:         }
142:     }
143: }
144: 
145: impl<E: Into<anyhow::Error>> From<E> for DisconnectReason {
146:     fn from(value: E) -> Self {
147:         Self::by_error(value)
148:     }
149: }
150: 
151: /// Disconnect reason to use when an IO layer component is dropped.
152: ///
153: /// IO layer implementations may use this as a default disconnection reason when
154: /// their IO component is dropped, instead of being explicitly disconnected via
155: /// [`Disconnect`].
156: pub const DROP_DISCONNECT_REASON: &str = "(dropped)";
157: 
158: /// Disconnect reason to use when an IO layer component is disconnected for an
159: /// unknown reason.
160: pub const UNKNOWN_DISCONNECT_REASON: &str = "(unknown)";
161: 
162: /// Local socket address that this entity uses for connections.
163: ///
164: /// Sessions or servers which use a network will use an OS socket for
165: /// communication. This component stores the local [`SocketAddr`] of this
166: /// socket.
167: ///
168: /// This component may not be present in environments where there is no access
169: /// to OS sockets (i.e. WASM).
170: ///
171: /// To access the socket address of a session's peer, see [`PeerAddr`].
172: #[derive(Debug, Clone, Copy, PartialEq, Eq, Deref, Component)]
173: pub struct LocalAddr(pub SocketAddr);
174: 
175: /// Socket address of the peer that this [`Session`] is connected to.
176: ///
177: /// Sessions which use a network will use an OS socket for communication. This
178: /// component stores the [`SocketAddr`] of the peer, which this session is
179: /// connected to.
180: ///
181: /// This component may not be present in environments where there is no access
182: /// to OS sockets (i.e. WASM).
183: ///
184: /// To access the local socket address of a session, see [`LocalAddr`].
185: #[derive(Debug, Clone, Copy, PartialEq, Eq, Deref, Component)]
186: pub struct PeerAddr(pub SocketAddr);
187: 
188: fn on_connecting(trigger: On<Add, SessionEndpoint>) {
189:     let entity = trigger.event_target();
190:     debug!("{entity} connecting");
191: }
192: 
193: fn on_connected(trigger: On<Add, Session>) {
194:     let entity = trigger.event_target();
195:     debug!("{entity} connected");
196: }
197: 
198: fn on_disconnect(trigger: On<Disconnect>, mut commands: Commands) {
199:     let entity = trigger.event_target();
200:     commands.trigger(Disconnected {
201:         entity,
202:         reason: DisconnectReason::by_user(&trigger.reason),
203:     });
204: }
205: 
206: fn on_disconnected(trigger: On<Disconnected>, mut commands: Commands) {
207:     let entity = trigger.event_target();
208:     match &trigger.reason {
209:         DisconnectReason::ByUser(reason) => {
210:             debug!("{entity} disconnected by user: {reason}");
211:         }
212:         DisconnectReason::ByPeer(reason) => {
213:             debug!("{entity} disconnected by peer: {reason}");
214:         }
215:         DisconnectReason::ByError(err) => {
216:             debug!("{entity} disconnected due to error: {err:#}");
217:         }
218:     }
219: 
220:     commands.entity(entity).try_despawn();
221: }
