266: /// Keeps rendering after a pipeline fails validation instead of quitting.
267: ///
268: /// Browser WebGPU rejects some pipelines the native backend accepts (shader
269: /// modules and limits it does not expose). Bevy's default handler hard-quits
270: /// the app on the first such error, blanking the canvas. Ignoring it lets the
271: /// rest of the scene draw -- the instanced grass has its own pipeline -- and
272: /// surfaces every incompatible pipeline rather than only the first. Native
273: /// compiles every pipeline, so this never fires there.
274: fn resilient_render_errors() -> RenderErrorHandler {
275:     RenderErrorHandler(|_error, _main_world, _render_world| RenderErrorPolicy::Ignore)
276: }
