278: fn run(
279:     args: Args,
280:     initial_tactical: bool,
281:     mut graphics_config: presentation::TacticalGraphicsConfig,
282:     audio_config: audio_config::TacticalAudioConfig,
283: ) {
284:     let startup_started_at = Instant::now();
285:     #[cfg(not(target_family = "wasm"))]
286:     eprintln!("[startup] native client process entry");
287:     let mut app = App::new();
288:     #[cfg(not(target_family = "wasm"))]
289:     let asset_root = native_asset_root(args.asset_root.as_deref());
290:     #[cfg(not(target_family = "wasm"))]
291:     validate_native_presentation_assets(&asset_root)
292:         .unwrap_or_else(|error| panic!("invalid tactical client asset root: {error}"));
293:     #[cfg(not(target_family = "wasm"))]
294:     app.register_asset_source(
295:         crate::animation::WORKSPACE_ASSET_SOURCE,
296:         AssetSourceBuilder::platform_default(&asset_root.to_string_lossy(), None),
297:     );
298:     #[cfg(feature = "debug")]
299:     let headless = args.headless;
300:     #[cfg(not(feature = "debug"))]
301:     let headless = false;
302:     if headless {
303:         graphics_config.disable_headless_rendering();
304:     }
305:     #[cfg(not(target_family = "wasm"))]
306:     let default_plugins = {
307:         let with_asset_plugin = DefaultPlugins.set(AssetPlugin {
308:             file_path: asset_root.to_string_lossy().into_owned(),
309:             ..default()
310:         });

311:         if headless {
312:             with_asset_plugin
313:                 .set(WindowPlugin {
314:                     primary_window: None,
315:                     exit_condition: bevy::window::ExitCondition::DontExit,
316:                     ..default()
317:                 })
318:                 .disable::<bevy::winit::WinitPlugin>()
319:         } else {
320:             let desktop = &graphics_config.desktop;
321:             with_asset_plugin.set(WindowPlugin {
322:                 primary_window: Some(Window {
323:                     title: "Fabelgeist - Tactical".into(),
324:                     mode: window_mode(desktop.window.mode),
325:                     resolution: (desktop.window.width, desktop.window.height).into(),
326:                     resizable: desktop.window.resizable,
327:                     decorations: desktop.window.decorations,
328:                     present_mode: present_mode(desktop.present_mode),
329:                     ..default()
330:                 }),
331:                 ..default()
332:             })
333:         }
334:     };
335:     #[cfg(target_family = "wasm")]
336:     let default_plugins = DefaultPlugins
337:         .set(AssetPlugin {
338:             file_path: "/tactical/assets".into(),
339:             meta_check: AssetMetaCheck::Never,
340:             ..default()
341:         })
342:         .set(WindowPlugin {
343:             primary_window: Some(Window {
344:                 title: "Fabelgeist - Tactical".into(),
345:                 canvas: Some("#game-canvas".into()),
346:                 fit_canvas_to_parent: true,
347:                 prevent_default_event_handling: true,
348:                 present_mode: present_mode(graphics_config.desktop.present_mode),
349:                 decorations: false,
350:                 ..default()
351:             }),
352:             ..default()
353:         });
354:     app.add_plugins((
355:         default_plugins,
356:         FrameTimeDiagnosticsPlugin::default(),
357:         EnhancedInputPlugin,
358:     ))
359:     .add_plugins((
360:         AdventureSimulatorCorePlugins
361:             .build()
362:             .set(AdventureSimulatorPhysicsPlugin {
363:                 enable_simulation: false,
364:                 enable_presentation_simulation: true,
365:             }),
366:         AdventureSimulatorNetPlugins,
367:     ))
368:     .add_input_context::<Player>();
369:     add_gameplay_plugins(&mut app, graphics_config);
370:     app.insert_resource(ClearColor(Color::srgb(0.1, 0.1, 0.15)))
371:         .insert_resource(resilient_render_errors())
372:         .insert_resource(audio_config)
373:         .insert_resource(presentation::ClientStartupTiming::new(startup_started_at))
374:         .add_systems(Startup, setup_initial_client)
375:         .add_systems(
376:             Update,
377:             (
378:                 capture_cursor.run_if(cursor_capture_requested()),
379:                 release_cursor.run_if(
380:                     input_just_pressed(KeyCode::Escape)
381:                         .and_then(any_with_component::<CharacterController>),
382:                 ),
383:             ),
384:         )
385:         .insert_resource(player::LocalCharacterId(args.id))
386:         .insert_resource(InitialTacticalMode(initial_tactical))
387:         .insert_resource(args.clone());
388:     #[cfg(target_family = "wasm")]
389:     app.add_plugins(browser_runtime::BrowserRuntimePlugin::new(initial_tactical));
390:     loading_screen::install(&mut app, headless);
391:     #[cfg(feature = "debug")]
392:     app.add_plugins(debug::DebugPlugin);
393: 
394:     #[cfg(not(target_family = "wasm"))]
395:     app.add_plugins(
396:         diagnostics::DiagnosticPlugin::new(
397:             args.input_script.as_deref(),
398:             args.animation_log.as_deref(),
399:             args.frame_timing_log.as_deref(),
400:             args.frame_timing_seconds,
401:             args.frame_timing_warmup_seconds,
402:             args.exit_after_script,
403:         )
404:         .unwrap_or_else(|error| panic!("invalid tactical client diagnostics: {error}")),
405:     );
406: 
407:     #[cfg(not(target_family = "wasm"))]
408:     if headless {
409:         app.add_plugins(bevy::app::ScheduleRunnerPlugin {
410:             run_mode: bevy::app::RunMode::Loop {
411:                 wait: Some(std::time::Duration::from_secs_f64(1.0 / 60.0)),
412:             },
413:         });
414:     }
415: 
416:     #[cfg(all(not(target_family = "wasm"), feature = "debug"))]
417:     if let Some(port) = args.brp_port {
418:         app.add_plugins((
419:             bevy::remote::RemotePlugin::default(),
420:             bevy::remote::http::RemoteHttpPlugin::default().with_port(port),
421:         ));
422:     }
423: 
424:     // Headless has no window to screenshot (F12, see `debug.rs`), so point
425:     // the gameplay camera at an off-screen render target instead.
426:     #[cfg(all(not(target_family = "wasm"), feature = "debug"))]
427:     if headless {
428:         app.add_systems(Update, configure_headless_render_target);
429:     }
430: 
431:     #[cfg(not(target_family = "wasm"))]
432:     eprintln!(
433:         "[startup] native client app constructed elapsed_ms={}",
434:         startup_started_at.elapsed().as_millis()
435:     );
436:     app.run();
437: }
