455: #[cfg(all(not(target_family = "wasm"), feature = "debug"))]
456: fn configure_headless_render_target(
457:     mut commands: Commands,
458:     mut images: ResMut<Assets<Image>>,
459:     cameras: Query<Entity, Added<Camera3d>>,
460: ) {
461:     for entity in &cameras {
462:         let image = images.add(Image::new_target_texture(
463:             HEADLESS_SCREENSHOT_SIZE.0,
464:             HEADLESS_SCREENSHOT_SIZE.1,
465:             bevy::render::render_resource::TextureFormat::Rgba8UnormSrgb,
466:             None,
467:         ));
468:         commands
469:             .entity(entity)
470:             .insert(bevy::camera::RenderTarget::Image(image.clone().into()));
471:         commands.insert_resource(debug::HeadlessScreenshotTarget(image));
472:     }
473: }
