476: fn native_asset_root(configured: Option<&std::path::Path>) -> std::path::PathBuf {
477:     configured
478:         .map(std::path::Path::to_path_buf)
479:         .unwrap_or_else(|| std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets"))
480:         .canonicalize()
481:         .unwrap_or_else(|error| panic!("could not resolve native asset directory: {error}"))
482: }
