484: #[cfg(not(target_family = "wasm"))]
485: /// Only shaders the client loads from the asset root belong here. Tree bark and
486: /// leaf cards ship embedded in `adventuresim-procedural-materials`, so they are
487: /// not asset-root files at all.
488: fn validate_native_presentation_assets(asset_root: &std::path::Path) -> Result<(), String> {
489:     // Only filesystem assets belong here; ProceduralMaterialsPlugin embeds its shaders.
490:     const REQUIRED_ASSETS: &[&str] = &[
491:         "shaders/tactical_foliage.wgsl",
492:         "shaders/tactical_clouds.wgsl",
493:         "shaders/tactical_moon.wgsl",
494:         "shaders/tactical_stars.wgsl",
495:         "shaders/tactical_terrain.wgsl",
496:         "shaders/tactical_weather.wgsl",
497:         "shaders/tactical_tree_impostor.wgsl",
498:         "tactical-equipment-icons.png",
499:         "textures/moon/lroc_color_2k.jpg",
500:     ];
501:     let missing = REQUIRED_ASSETS
502:         .iter()
503:         .filter(|path| !asset_root.join(path).is_file())
504:         .copied()
505:         .collect::<Vec<_>>();
506:     if missing.is_empty() {
507:         Ok(())
508:     } else {
509:         Err(format!(
510:             "{} is missing required presentation assets: {}",
511:             asset_root.display(),
512:             missing.join(", ")
513:         ))
514:     }
515: }
