542: fn capture_cursor(
543:     mut commands: Commands,
544:     player: Single<Entity, With<CharacterController>>,
545:     mut cursor: Single<&mut CursorOptions>,
546: ) {
547:     if !cursor.visible {
548:         return;
549:     }
550: 
551:     commands
552:         .entity(player.into_inner())
553:         .insert(ContextActivity::<Player>::ACTIVE);
554:     cursor.grab_mode = CursorGrabMode::Locked;
555:     cursor.visible = false;
556: }
557: 
558: fn release_cursor(
559:     mut commands: Commands,
560:     player: Single<Entity, With<CharacterController>>,
561:     mut cursor: Single<&mut CursorOptions>,
562: ) {
563:     if cursor.visible {
564:         return;
565:     }
566: 
567:     commands
568:         .entity(player.into_inner())
569:         .insert(ContextActivity::<Player>::INACTIVE);
570:     cursor.visible = true;
571:     cursor.grab_mode = CursorGrabMode::None;
572: }
