113: impl ForgePreviewView {
114:     fn orbit(&mut self, delta_x: f32, delta_y: f32) {
115:         self.yaw += delta_x * 0.008;
116:         self.pitch = (self.pitch + delta_y * 0.008).clamp(-1.2, 1.2);
117:     }
118: 
119:     fn zoom(&mut self, delta: f32) {
120:         self.distance = (self.distance + delta * 0.002).clamp(0.9, 4.5);
121:     }
122: }
