167: fn sync_gameplay_view(
168:     mode: Res<BrowserMode>,
169:     sky: Res<crate::presentation::AtmosphereIblCache>,
170:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
171:     view: Option<Res<crate::strategic_scene::protocol::StrategicView>>,
172:     mut cameras: Query<&mut Camera, With<TacticalGameplayCamera>>,
173: ) {
174:     for mut camera in &mut cameras {
175:         if *mode == BrowserMode::Tactical {
176:             camera.is_active = true;
177:             camera.viewport = None;
178:             camera.sub_camera_view = None;
179:         } else {
180:             // The atmosphere bake validates submissions from this exact camera.
181:             // Render a masked one-pixel view until its shared environment map exists.
182:             camera.is_active = view.is_some() && !sky.is_ready(&settings);
183:             camera.viewport = Some(bevy::camera::Viewport {
184:                 physical_size: UVec2::ONE,
185:                 ..default()
186:             });
187:             camera.sub_camera_view = None;
188:         }
189:     }
190: }
