203: #[expect(
204:     clippy::too_many_arguments,
205:     reason = "the browser command bridge coordinates the complete renderer state in one exclusive drain"
206: )]
207: fn drain_browser_commands(
208:     mut commands: Commands,
209:     mut mode: ResMut<BrowserMode>,
210:     mut args: ResMut<Args>,
211:     mut local_character: ResMut<LocalCharacterId>,
212:     scene_entities: Query<Entity, With<StrategicSceneEntity>>,
213:     clients: Query<Entity, With<AdventureSimulatorClient>>,
214:     mut meshes: ResMut<Assets<Mesh>>,
215:     mut materials: ResMut<Assets<StandardMaterial>>,
216:     mut scene_roots: Query<&mut Transform, (With<StrategicSceneRoot>, Without<Camera3d>)>,
217:     mut preview_view: ResMut<ForgePreviewView>,
218: ) {
219:     let pending = pending_commands();
220: 
221:     for command in pending {
222:         match command {
223:             BrowserCommand::PrepareStrategicScene {
224:                 location,
225:                 input_json,
226:                 preparation,
227:             } => prepare_city(&mut commands, location, input_json, preparation),
228:             BrowserCommand::SyncStrategicView { view } => {
229:                 commands.insert_resource(view);
230:             }
231:             BrowserCommand::RegionalMap { command } => {
232:                 commands.queue(move |world: &mut World| command.apply(world))
233:             }
234:             BrowserCommand::ShowStrategicScene { scene } => {
235:                 *mode = BrowserMode::Strategic;
236:                 despawn_forge_preview(&mut commands, &scene_entities);
237:                 match scene {
238:                     StrategicScene::Forge {
239:                         catalog_id,
240:                         design_json,
241:                     } => spawn_forge_scene(
242:                         &mut commands,
243:                         &mut meshes,
244:                         &mut materials,
245:                         &catalog_id,
246:                         design_json.as_deref(),
247:                         &preview_view,
248:                     ),
249:                 }
250:             }
251:             BrowserCommand::OrbitForge { delta_x, delta_y } => {
252:                 preview_view.orbit(delta_x, delta_y);
253:                 for mut root in &mut scene_roots {
254:                     apply_preview_view(&preview_view, &mut root);
255:                 }
256:             }
257:             BrowserCommand::ZoomForge { delta } => {
258:                 preview_view.zoom(delta);
259:                 for mut root in &mut scene_roots {
260:                     apply_preview_view(&preview_view, &mut root);
261:                 }
262:             }
263:             BrowserCommand::HideForgePreview => {
264:                 despawn_forge_preview(&mut commands, &scene_entities);
265:                 *preview_view = ForgePreviewView::default();
266:             }
267:             BrowserCommand::EnterTactical {
268:                 server_addr,
269:                 character_id,
270:             } => {
271:                 commands.queue(|world: &mut World| {
272:                     crate::presentation::regional_map::protocol::MapCommand::Hide.apply(world)
273:                 });
274:                 commands.queue(crate::strategic_scene::release_scene);
275:                 commands.remove_resource::<crate::strategic_scene::protocol::StrategicView>();
276:                 despawn_forge_preview(&mut commands, &scene_entities);
277:                 if clients.is_empty() {
278:                     args.id = character_id;
279:                     args.server_addr.clone_from(&server_addr);
280:                     local_character.0 = character_id;

281:                     commands.spawn(AdventureSimulatorClient {
282:                         player_id: character_id,
283:                         server_url: server_addr,
284:                     });
285:                 }
286:                 *mode = BrowserMode::Tactical;
287:             }
288:             BrowserCommand::ExitTactical => {
289:                 for entity in &clients {
290:                     commands.entity(entity).despawn();
291:                 }
292:                 *mode = BrowserMode::Strategic;
293:             }
294:         }
295:     }
296: }
