305: fn pending_commands() -> Vec<BrowserCommand> {
306:     COMMANDS
307:         .get_or_init(|| Mutex::new(VecDeque::new()))
308:         .lock()
309:         .map(|mut queue| queue.drain(..).collect())
310:         .unwrap_or_default()
311: }
