313: fn despawn_forge_preview(
314:     commands: &mut Commands,
315:     scene_entities: &Query<Entity, With<StrategicSceneEntity>>,
316: ) {
317:     for entity in scene_entities {
318:         commands.entity(entity).despawn();
319:     }
