322: fn spawn_forge_scene(
323:     commands: &mut Commands,
324:     meshes: &mut Assets<Mesh>,
325:     materials: &mut Assets<StandardMaterial>,
326:     catalog_id: &str,
327:     design_json: Option<&str>,
328:     view: &ForgePreviewView,
329: ) {
330:     let design = match design_json {
331:         Some(json) => match serde_json::from_str::<WeaponDesign>(json) {
332:             Ok(design) => Some(design),
333:             Err(error) => {
334:                 warn!(catalog_id, %error, "browser forge preview rejected invalid recipe");
335:                 return;
336:             }
337:         },
338:         None => default_design(catalog_id),
339:     };
340:     let Some(design) = design else {
341:         warn!(
342:             catalog_id,
343:             "browser forge preview rejected unknown weapon chassis"
344:         );
345:         return;
346:     };
347:     let Ok(generated) = generate(&design) else {
348:         warn!(
349:             catalog_id,
350:             "browser forge preview failed to generate weapon mesh"
351:         );
352:         return;
353:     };
354: 
355:     let center =
356:         (Vec3::from_array(generated.bounds.min) + Vec3::from_array(generated.bounds.max)) * 0.5;
357:     let extent = Vec3::from_array(generated.bounds.max) - Vec3::from_array(generated.bounds.min);
358:     let scale = 1.45 / extent.max_element().max(0.001);
359:     let root = commands
360:         .spawn((
361:             Name::new("Strategic forge weapon preview"),
362:             Visibility::default(),
363:             StrategicSceneEntity,
364:             StrategicSceneRoot,
365:             preview_transform(view, scale),
366:         ))
367:         .id();
368: 
369:     for part in generated.parts {
370:         let mut mesh = Mesh::new(
371:             PrimitiveTopology::TriangleList,
372:             RenderAssetUsages::MAIN_WORLD | RenderAssetUsages::RENDER_WORLD,
373:         );
374:         mesh.insert_attribute(Mesh::ATTRIBUTE_POSITION, part.positions);
375:         mesh.insert_attribute(Mesh::ATTRIBUTE_NORMAL, part.normals);
376:         mesh.insert_indices(Indices::U32(part.indices));
377:         commands.spawn((
378:             Name::new(format!("Strategic forge part {}", part.component_id)),
379:             Mesh3d(meshes.add(mesh)),
380:             bevy::camera::visibility::RenderLayers::layer(
381:                 crate::strategic_scene::protocol::FORGE_LAYER,
382:             ),
383:             MeshMaterial3d(materials.add(preview_material(part.material))),
384:             Transform::from_translation(-center),
385:             ChildOf(root),
386:         ));
387:     }
388: 
389:     commands.spawn((
390:         Name::new("Strategic forge preview light"),
391:         bevy::camera::visibility::RenderLayers::layer(
392:             crate::strategic_scene::protocol::FORGE_LAYER,
393:         ),
394:         StrategicSceneEntity,
395:         DirectionalLight {
396:             illuminance: 60_000.0,
397:             shadow_maps_enabled: false,
398:             ..default()
399:         },
400:         Transform::from_xyz(-3.0, 4.0, 2.0).looking_at(Vec3::new(0.0, 0.0, -2.2), Vec3::Y),
401:     ));
402: 
403:     commands.spawn((
404:         Name::new("Strategic forge preview fill light"),
405:         bevy::camera::visibility::RenderLayers::layer(
406:             crate::strategic_scene::protocol::FORGE_LAYER,
407:         ),
408:         StrategicSceneEntity,
409:         PointLight {
410:             intensity: 12_000.0,
411:             range: 8.0,
412:             shadow_maps_enabled: false,
413:             ..default()
414:         },
415:         Transform::from_xyz(2.0, 1.5, 0.5),
416:     ));
417: }
418: 
419: fn preview_transform(view: &ForgePreviewView, scale: f32) -> Transform {
420:     Transform::from_xyz(0.0, 0.0, -view.distance)
421:         .with_rotation(Quat::from_euler(EulerRot::YXZ, view.yaw, view.pitch, -0.55))
422:         .with_scale(Vec3::splat(scale))
423: }
424: 
425: fn apply_preview_view(view: &ForgePreviewView, transform: &mut Transform) {
426:     let scale = transform.scale.x;
427:     *transform = preview_transform(view, scale);
428: }
