22: impl CanvasRect {
23:     pub(crate) fn uncropped(self) -> Self {
24:         Self {
25:             x: 0,
26:             y: 0,
27:             width: self.full_width,
28:             height: self.full_height,
29:             offset_x: 0.0,
30:             offset_y: 0.0,
31:             ..self
32:         }
33:     }
34: 
35:     pub fn apply(self, camera: &mut Camera, size: UVec2) {
36:         let origin = UVec2::new(self.x, self.y).min(size);
37:         let extent = UVec2::new(self.width, self.height).min(size - origin);
38:         camera.is_active = extent.min_element() > 0;
39:         if !camera.is_active {
40:             return;
41:         }
42:         camera.viewport = Some(bevy::camera::Viewport {
43:             physical_position: origin,
44:             physical_size: extent,
45:             ..default()
46:         });
47:         camera.sub_camera_view = Some(bevy::camera::SubCameraView {
48:             full_size: UVec2::new(self.full_width.max(1), self.full_height.max(1)),
49:             offset: Vec2::new(self.offset_x, self.offset_y),
50:             size: extent,
51:         });
52:     }
53: }
