8: 
9: type EquipmentRootState = (
10:     &'static ItemPlaceholder,
11:     &'static Visibility,
12:     Has<RuntimeEquipmentPresentation>,
13:     Has<ProceduralEquipmentResolved>,
14:     Has<ProceduralEquipmentFailed>,
15: );
