17: #[derive(SystemParam)]
18: pub(crate) struct EquipmentReadiness<'w, 's> {
19:     roots: Query<'w, 's, EquipmentRootState>,
20:     parts: Query<'w, 's, (&'static ProceduralEquipmentPart, &'static Visibility)>,
21: }
22: 
23: impl EquipmentReadiness<'_, '_> {
24:     pub(crate) fn pending_summary(&self, items: impl Iterator<Item = Entity>) -> String {
25:         let items: std::collections::HashSet<_> = items.collect();
26:         let roots = self
27:             .roots
28:             .iter()
29:             .filter(|(root, ..)| items.contains(&root.0))
30:             .collect::<Vec<_>>();
31:         let hidden = roots
32:             .iter()
33:             .filter(|(_, visibility, ..)| **visibility == Visibility::Hidden)
34:             .count();
35:         let unresolved = roots
36:             .iter()
37:             .filter(|(_, _, runtime, resolved, _)| *runtime && !*resolved)
38:             .count();
39:         let unbound = self
40:             .parts
41:             .iter()
42:             .filter(|(part, visibility)| {
43:                 items.contains(&part.item) && **visibility == Visibility::Hidden
44:             })
45:             .count();
46:         format!(
47:             "{} items, {} roots, {hidden} hidden, {unresolved} awaiting geometry, {unbound} awaiting presentation",
48:             items.len(),
49:             roots.len()
50:         )
51:     }
52: 
53:     pub(crate) fn check(&self, items: impl Iterator<Item = Entity>) -> Result<bool, &'static str> {
54:         let items: std::collections::HashSet<_> = items.collect();
55:         let mut ready = 0;
56:         for (placeholder, visibility, runtime, resolved, failed) in &self.roots {
57:             if !items.contains(&placeholder.0) {
58:                 continue;
59:             }
60:             if failed {
61:                 return Err("Could not generate character equipment");
62:             }
63:             if *visibility != Visibility::Hidden && (!runtime || resolved) {
64:                 ready += 1;
65:             }
66:         }
67:         Ok(ready == items.len()
68:             && self.parts.iter().all(|(part, visibility)| {
69:                 !items.contains(&part.item) || *visibility != Visibility::Hidden
70:             }))
71:     }
72: }

