262: impl CachedEquipment {

263:     fn attach(
264:         &self,
265:         commands: &mut Commands,
266:         entity: Entity,
267:         presentation: &RuntimeEquipmentPresentation,
268:         body: &FittedBody,
269:     ) {
270:         if !self.sockets.is_empty() {
271:             commands
272:                 .entity(presentation.item)
273:                 .insert(EquipmentAttachmentSockets(self.sockets.clone()));
274:         }
275:         for (index, mesh_part) in self.parts.iter().enumerate() {
276:             let part = ProceduralEquipmentPart::new(
277:                 presentation.item,
278:                 body.inverse_bindposes.clone(),
279:                 body.body.joint_names.clone(),
280:                 self.rigid_center,
281:             );
282:             commands.entity(entity).with_child(part.render_bundle(
283:                 format!("Runtime equipment {} part {index}", presentation.item_id),
284:                 mesh_part.mesh.clone(),
285:                 mesh_part.material.clone(),
286:             ));
287:         }
288:         commands
289:             .entity(entity)
290:             .insert((ProceduralEquipmentResolved, Visibility::Inherited));
291:     }
292: }
