295:     clippy::too_many_arguments,
296:     clippy::type_complexity,
297:     reason = "equipment job integration and wearer-owned fitting inputs"
298: )]
299: pub(in crate::equipment) fn generate_runtime_equipment_models(
300:     mut commands: Commands,
301:     mut meshes: ResMut<Assets<Mesh>>,
302:     mut materials: ResMut<Assets<StandardMaterial>>,
303:     mut images: ResMut<Assets<Image>>,
304:     mut bindposes: ResMut<Assets<SkinnedMeshInverseBindposes>>,
305:     mut cache: ResMut<RuntimeEquipmentBodyCache>,
306:     presentations: Query<(
307:         Entity,
308:         &RuntimeEquipmentPresentation,
309:         Option<&FitKey>,
310:         Has<ProceduralEquipmentResolved>,
311:         Option<&Children>,
312:     )>,
313:     parts: Query<(), With<ProceduralEquipmentPart>>,
314:     items: Query<(
315:         Option<&ItemOf>,
316:         Has<TacticalSceneItem>,
317:         Option<&LastFit>,
318:         Option<&EquipSlot>,
319:     )>,
320:     characters: Query<(&CharacterId, Option<&CharacterSkeletalProportions>)>,
321: ) {
322:     cache.finish(&mut meshes, &mut materials, &mut images);
323:     let outfits = layers::outfits(presentations.iter().filter_map(|(_, presentation, ..)| {
324:         let (owner, scene, _, slot) = items.get(presentation.item).ok()?;
325:         let owner = owner.filter(|_| !scene && holding_side(slot).is_none())?;
326:         Some((
327:             owner.0,
328:             layers::LayerSelection::admit(&presentation.item_id, &presentation.placement_id),
329:         ))
330:     }));
331:     for (entity, presentation, current, resolved, children) in &presentations {
332:         if cache.failed {
333:             commands
334:                 .entity(entity)
335:                 .insert((ProceduralEquipmentFailed, ProceduralEquipmentResolved));
336:             continue;
337:         }
338:         let Some(canonical) = cache.body.as_ref() else {
339:             return;
340:         };
341:         if cache.bracer_design.is_none() || cache.breastplate_design.is_none() {
342:             return;
343:         }
344:         let Ok((owner, scene, last_fit, slot)) = items.get(presentation.item) else {
345:             continue;
346:         };
347:         let fitted_to_owner = !scene && holding_side(slot).is_none() && owner.is_some();
348:         let previous = last_fit.map(|fit| &fit.0).or(current);
349:         let key = FitKey::for_presentation(
350:             canonical,
351:             presentation,
352:             previous,
353:             owner,
354:             fitted_to_owner,
355:             &characters,
356:         );
357:         let mut key = match key {
358:             Ok(Some(key)) => key,
359:             Ok(None) => continue,
360:             Err(error) => {
361:                 presentation.fail_fit(entity, resolved, &error, &mut commands);
362:                 continue;
363:             }
364:         };
365:         if fitted_to_owner {
366:             let Some(owner) = owner else {
367:                 continue;
368:             };
369:             match key.layers_for_outfit(&outfits[&owner.0]) {
370:                 Ok(layers) => key.layers = layers,
371:                 Err(error) => {
372:                     presentation.fail_fit(entity, resolved, &error, &mut commands);
373:                     continue;
374:                 }
375:             }
376:         }
377:         cache.use_clock = cache.use_clock.wrapping_add(1);
378:         let clock = cache.use_clock;
379:         cache.last_used.insert(key.clone(), clock);
380:         if current == Some(&key) && resolved {
381:             continue;
382:         }
383:         if current != Some(&key) {
384:             key.install(&mut commands, entity, presentation, children, &parts);
385:         }
386:         cache.resolve(key, entity, presentation, &mut commands, &mut bindposes);
387:     }
388:     cache.trim();
389: }
