391: impl RuntimeEquipmentPresentation {
392:     /// A rejected selection cannot retain a resolved mesh or a previous fit key.
393:     fn fail_fit(
394:         &self,
395:         entity: Entity,
396:         resolved: bool,
397:         error: &anyhow::Error,
398:         commands: &mut Commands,
399:     ) {
400:         if !resolved {
401:             error!(item = self.item_id, "invalid equipment fit: {error:#}");
402:         }
403:         commands.entity(entity).remove::<FitKey>().insert((
404:             ProceduralEquipmentFailed,
405:             ProceduralEquipmentResolved,
406:             Visibility::Hidden,
407:         ));
408:     }
409: }
410: 
411: impl RuntimeEquipmentBodyCache {
412:     fn resolve(
413:         &mut self,
414:         key: FitKey,
415:         entity: Entity,
416:         presentation: &RuntimeEquipmentPresentation,
417:         commands: &mut Commands,
418:         bindposes: &mut Assets<SkinnedMeshInverseBindposes>,
419:     ) {
420:         if let Some(result) = self.models.get(&key) {
421:             let Ok(model) = result else {
422:                 commands
423:                     .entity(entity)
424:                     .insert((ProceduralEquipmentResolved, ProceduralEquipmentFailed));
425:                 return;
426:             };
427:             let body = &self.bodies[&key.shape];
428:             model.attach(commands, entity, presentation, body);
429:         } else if !self.is_preparing() {
430:             let result = self.next_fit(&key).and_then(|next| {
431:                 self.prepare_shape(&next.shape, bindposes)?;
432:                 self.start(next)
433:             });
434:             match result {
435:                 Ok(()) => {}
436:                 Err(error) => {
437:                     self.models.insert(key, Err(format!("{error:#}")));
438:                 }
439:             }
440:         }
441:     }
442: }
443: 
444: impl FitKey {
445:     fn install(
446:         &self,
447:         commands: &mut Commands,
448:         entity: Entity,
449:         presentation: &RuntimeEquipmentPresentation,
450:         children: Option<&Children>,
451:         parts: &Query<(), With<ProceduralEquipmentPart>>,
452:     ) {
453:         if let Some(children) = children {
454:             for child in children.iter() {
455:                 if parts.contains(child) {
456:                     commands.entity(child).despawn();
457:                 }
458:             }
459:         }
460:         commands
461:             .entity(entity)
462:             .insert(self.clone())
463:             .remove::<(ProceduralEquipmentResolved, ProceduralEquipmentFailed)>();
464:         commands
465:             .entity(presentation.item)
466:             .insert(LastFit(self.clone()))
467:             .remove::<EquipmentAttachmentSockets>();
468:     }
469: }

