858:     existing: Query<(Entity, &ItemPlaceholder)>,
859:     mut meshes: ResMut<Assets<Mesh>>,
860:     mut materials: ResMut<Assets<StandardMaterial>>,
861:     mut cache: ResMut<WeaponMeshCache>,
862: ) {
863:     for (item, physical, topology, properties, appearance, holder_appearance) in &added {
864:         if !physical.is_valid() {
865:             continue;
866:         }
867:         for (root, placeholder) in &existing {
868:             if placeholder.0 == item {
869:                 commands.entity(root).despawn();
870:             }
871:         }
872:         commands.entity(item).remove::<EquipmentAttachmentSockets>();
873:         let mut root_commands = commands.spawn((
874:             Name::new("Tactical item placeholder"),
875:             ItemPlaceholder(item),
876:             Transform::default(),
877:             // Attachment is resolved on the following update. Keeping the
878:             // root hidden avoids a one-frame flash at the world origin.
879:             Visibility::Hidden,
880:         ));
881:         if let Some(presentation) = runtime_equipment::presentation(item, properties, topology) {
882:             root_commands.insert(presentation);
883:             continue;
884:         }
885:         let root = root_commands.id();
886:         let (generated, part_name) = if let Some(holder) =
887:             holder_appearance.and_then(|appearance| {
888:                 cached_holder(appearance, &mut cache, &mut meshes, &mut materials)
889:             }) {
890:             (Some(holder), "Procedural weapon holder part")
891:         } else if properties.is_some_and(|properties| {
892:             matches!(
893:                 properties.id.as_str(),
894:                 "scabbard" | "sword_sheath" | "boot_sheath" | "forearm_holster" | "weapon_loop"
895:             )
896:         }) {
897:             // Holder catalog rows are semantic chassis, not renderable generic
898:             // boxes. An absent, corrupt, or unsupported holder instance stays
899:             // visually absent until a valid first-class recipe arrives.
900:             continue;
901:         } else {
902:             (
903:                 appearance.and_then(|appearance| {
904:                     cached_weapon(appearance, &mut cache, &mut meshes, &mut materials)
905:                 }),
906:                 "Procedural weapon part",
907:             )
908:         };
909:         if let Some(generated) = generated {
910:             placeholder_visual::spawn_generated(&mut commands, root, item, generated, part_name);
911:         } else {
912:             placeholder_visual::spawn_fallback(
913:                 &mut commands,
914:                 root,
915:                 item,
916:                 physical,
917:                 &mut meshes,
918:                 &mut materials,
919:             );
920:         }
921:     }
922: }
