13: /// A cache selection retains the actual catalogue records. Its value identity
14: /// remains the exact item/placement pair, so fit keys keep their lexical order.
15: #[derive(Clone, Copy, Debug)]
16: pub(super) struct LayerSelection {
17:     pub selection: CatalogPlacement<'static>,
18: }
19: 
20: impl LayerSelection {
21:     /// Item/placement text from ECS presentation enters the catalogue here.
22:     pub(super) fn admit(item: &str, placement: &str) -> anyhow::Result<Self> {
23:         let selection = CatalogItem::find(item_catalog::catalog(), item)
24:             .and_then(|item| item.placement(placement))
25:             .with_context(|| format!("no equipment placement {item} {placement}"))?;
26:         Ok(Self { selection })
27:     }
28: 
29:     fn definition(&self) -> &'static EquipmentPlacement {
30:         self.selection.definition()
31:     }
32: 
33:     fn key(&self) -> (&'static str, &'static str) {
34:         (
35:             self.selection.item().definition().id.as_str(),
36:             self.selection.definition().id.as_str(),
37:         )
38:     }
39: }
40: 
41: impl From<CatalogPlacement<'static>> for LayerSelection {
42:     fn from(selection: CatalogPlacement<'static>) -> Self {
43:         Self { selection }
44:     }
45: }
46: 
47: impl PartialEq for LayerSelection {
48:     fn eq(&self, other: &Self) -> bool {
49:         self.key() == other.key()
50:     }
51: }
52: 
53: impl Eq for LayerSelection {}
54: 
55: impl Hash for LayerSelection {
56:     fn hash<H: Hasher>(&self, state: &mut H) {
57:         self.key().hash(state);
58:     }
59: }
60: 
61: impl PartialOrd for LayerSelection {
62:     fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
63:         Some(self.cmp(other))
64:     }
65: }
66: 
67: impl Ord for LayerSelection {
68:     fn cmp(&self, other: &Self) -> Ordering {
69:         self.key().cmp(&other.key())
70:     }
71: }
72: 
73: /// A deterministic list permits sharing fits between identically dressed
74: /// wearers regardless of ECS entity allocation or inventory iteration order.
75: pub(super) struct OutfitPlan {
76:     selections: Vec<LayerSelection>,
77:     plan: LayerPlan,
78: }
79: 
80: impl OutfitPlan {
81:     pub(super) fn new(mut selections: Vec<LayerSelection>) -> anyhow::Result<Self> {
82:         selections.sort();
83:         selections.dedup();
84:         let placements = selections
85:             .iter()
86:             .map(LayerSelection::definition)
87:             .collect::<Vec<_>>();
88:         let plan = LayerPlan::new(&placements)?;
89:         Ok(Self { selections, plan })
90:     }
91: 
92:     pub(super) fn ancestors(
93:         &self,
94:         selection: &LayerSelection,
95:     ) -> anyhow::Result<Vec<LayerSelection>> {
96:         let index = self
97:             .selections
98:             .binary_search(selection)
99:             .map_err(|_| anyhow::anyhow!("equipment selection is absent from the fitted outfit"))?;
100:         Ok(self
101:             .plan
102:             .ancestors(index)
103:             .into_iter()
104:             .map(|i| self.selections[i])
105:             .collect())
106:     }
107: 
108:     pub(super) fn supports(
109:         &self,
110:         selection: &LayerSelection,
111:     ) -> anyhow::Result<Vec<LayerSelection>> {
112:         let index = self
113:             .selections
114:             .binary_search(selection)
115:             .map_err(|_| anyhow::anyhow!("equipment selection is absent from the fitted outfit"))?;
116:         Ok(self
117:             .plan
118:             .supports(index)
119:             .map(|i| self.selections[i])
120:             .collect())
121:     }
122: }
123: 
124: impl generation::FitKey {
125:     /// Resolve this article's lower garments from the wearer's admitted outfit.
126:     pub(super) fn layers_for_outfit(
127:         &self,
128:         outfit: &Result<OutfitPlan, String>,
129:     ) -> anyhow::Result<Vec<LayerSelection>> {
130:         outfit
131:             .as_ref()
132:             .map_err(|error| anyhow::anyhow!("{error}"))?
133:             .ancestors(&self.selection)
134:     }
135: 
136:     /// Recreate every direct support's full fit key. Its own lower surfaces
137:     /// remain in the key; flat item IDs alone would reuse incorrectly seated
138:     /// geometry after a garment underneath that support changes.
139:     pub(super) fn support_keys(&self) -> anyhow::Result<Vec<Self>> {
140:         let selection = self.selection;
141:         let mut selections = self.layers.clone();
142:         selections.push(selection);
143:         let plan = OutfitPlan::new(selections)?;
144:         plan.supports(&selection)?
145:             .into_iter()
146:             .map(|support| {
147:                 Ok(Self {
148:                     shape: self.shape.clone(),
149:                     layers: plan.ancestors(&support)?,
150:                     selection: support,
151:                 })
152:             })
153:             .collect()
154:     }
155: }
156: 
157: pub(super) fn outfits(
158:     selections: impl Iterator<Item = (Entity, anyhow::Result<LayerSelection>)>,
159: ) -> HashMap<Entity, Result<OutfitPlan, String>> {
160:     let mut owners = HashMap::<Entity, Result<Vec<LayerSelection>, String>>::new();
161:     for (owner, selection) in selections {
162:         let accumulated = owners.entry(owner).or_insert_with(|| Ok(Vec::new()));
163:         if let Ok(selections) = accumulated {
164:             match selection {
165:                 Ok(selection) => selections.push(selection),
166:                 Err(error) => *accumulated = Err(format!("{error:#}")),
167:             }
168:         }
169:     }
170:     owners
171:         .into_iter()
172:         .map(|(owner, selections)| {
173:             (
174:                 owner,
175:                 selections.and_then(|selections| {
176:                     OutfitPlan::new(selections).map_err(|error| format!("{error:#}"))
177:                 }),
178:             )
179:         })
180:         .collect()
181: }
182: 
183: impl RuntimeEquipmentBodyCache {
184:     /// Select an innermost missing support before the requested item. Failure
185:     /// propagates outward instead of silently fitting through a missing layer.
186:     pub(super) fn next_fit(
187:         &mut self,
188:         key: &generation::FitKey,
189:     ) -> anyhow::Result<generation::FitKey> {
190:         for support in key.support_keys()? {
191:             self.last_used.insert(support.clone(), self.use_clock);
192:             match self.models.get(&support) {
193:                 Some(Ok(_)) => {}
194:                 Some(Err(error)) => bail!(
195:                     "lower equipment {} {} failed: {error}",
196:                     support.selection.selection.item().id,
197:                     support.selection.selection.definition().id
198:                 ),
199:                 None => return self.next_fit(&support),
200:             }
201:         }
202:         Ok(key.clone())
203:     }
204: }
