1: //! Presentation attachment and visibility for worn, held, and dropped items.
2: use super::*;
3: 
4: #[expect(
5:     clippy::type_complexity,
6:     reason = "the Bevy queries describe equipment ownership, topology, rig bindings, and placeholder state exactly"
7: )]
8: pub(super) fn update_item_placeholders(
9:     mut commands: Commands,
10:     items: Query<
11:         (
12:             &Transform,
13:             Option<&ItemOf>,
14:             Option<&EquipSlot>,
15:             &EquipmentTopology,
16:             Has<TacticalSceneItem>,
17:         ),
18:         Without<ItemPlaceholder>,
19:     >,
20:     topologies: Query<
21:         (&EquipmentTopology, Option<&EquipmentAttachmentSockets>),
22:         Without<ItemPlaceholder>,
23:     >,
24:     rigs: Query<&HumanoidRig, crate::animation::AnimatedActors>,
25:     bind_nodes: Query<(&AuthoredBindTransform, Option<&ChildOf>)>,
26:     mut placeholders: Query<(
27:         Entity,
28:         &ItemPlaceholder,
29:         &mut Transform,
30:         &mut Visibility,
31:         Option<&ChildOf>,
32:         Has<ProceduralEquipmentResolved>,
33:         Has<ProceduralEquipmentFailed>,
34:     )>,
35: ) {
36:     for (entity, placeholder, mut transform, mut visibility, parent, procedural, failed) in
37:         &mut placeholders
38:     {
39:         let Ok((item_transform, owner, slot, topology, scene)) = items.get(placeholder.0) else {
40:             commands.entity(entity).despawn();
41:             continue;
42:         };
43:         if failed {
44:             *visibility = Visibility::Hidden;
45:             commands.entity(entity).remove::<HeldWeaponConstraint>();
46:             continue;
47:         }
48:         if scene {
49:             if parent.is_some() {
50:                 commands.entity(entity).remove::<ChildOf>();
51:             }
52:             *transform = *item_transform;
53:             *visibility = Visibility::Inherited;
54:             commands.entity(entity).remove::<HeldWeaponConstraint>();
55:         } else if procedural && holding_side(slot).is_none() {
56:             let rig_scene = resolve_character_location(topology, &topologies)
57:                 .and(owner)
58:                 .and_then(|owner| rigs.get(owner.0).ok())
59:                 .and_then(HumanoidRig::rig_scene);
60:             if let Some(rig_scene) = rig_scene {
61:                 if parent.is_none_or(|parent| parent.parent() != rig_scene) {
62:                     commands.entity(entity).insert(ChildOf(rig_scene));
63:                 }
64:                 *transform = Transform::IDENTITY;
65:                 *visibility = Visibility::Inherited;
66:             } else {
67:                 *visibility = Visibility::Hidden;
68:             }
69:             commands.entity(entity).remove::<HeldWeaponConstraint>();
70:         } else if let (Some(owner), Some(primary_hand)) = (owner, holding_side(slot)) {
71:             if parent.is_some() {
72:                 commands.entity(entity).remove::<ChildOf>();
73:             }
74:             let constraint = rigs
75:                 .get(owner.0)
76:                 .ok()
77:                 .and_then(|rig| held_constraint(rig, owner.0, primary_hand));
78:             if let Some(constraint) = constraint {
79:                 *visibility = Visibility::Inherited;
80:                 commands.entity(entity).insert(constraint);
81:             } else {
82:                 *visibility = Visibility::Hidden;
83:                 commands.entity(entity).remove::<HeldWeaponConstraint>();
84:             }
85:         } else if let Some((bone, correction)) = owner.and_then(|owner| {
86:             let rig = rigs.get(owner.0).ok()?;
87:             worn_attachment(topology, &topologies, rig, &bind_nodes)
88:         }) {
89:             if parent.is_none_or(|parent| parent.parent() != bone) {
90:                 commands.entity(entity).insert(ChildOf(bone));
91:             }
92:             *transform = correction;
93:             *visibility = Visibility::Inherited;
94:             commands.entity(entity).remove::<HeldWeaponConstraint>();
95:         } else {
96:             *visibility = Visibility::Hidden;
97:             commands.entity(entity).remove::<HeldWeaponConstraint>();
98:         }
99:     }
100: }
101: 
102: fn held_constraint(
103:     rig: &HumanoidRig,
104:     owner: Entity,
105:     primary_hand: HandSide,
106: ) -> Option<HeldWeaponConstraint> {
107:     let role = match primary_hand {
108:         HandSide::Left => BoneRole::WeaponLeft,
109:         HandSide::Right => BoneRole::WeaponRight,
110:     };
111:     rig.get(&role)?;
112:     Some(HeldWeaponConstraint {
113:         owner,
114:         primary_hand,
115:         secondary_grip_local: None,
116:     })
117: }
118: 
119: fn worn_attachment(
120:     topology: &EquipmentTopology,
121:     topologies: &Query<
122:         (&EquipmentTopology, Option<&EquipmentAttachmentSockets>),
123:         Without<ItemPlaceholder>,
124:     >,
125:     rig: &HumanoidRig,
126:     bind_nodes: &Query<(&AuthoredBindTransform, Option<&ChildOf>)>,
127: ) -> Option<(Entity, Transform)> {
128:     let role = equipment_location_bone(resolve_character_location(topology, topologies)?);
129:     let bone = rig.get(&role).copied()?;
130:     let correction = if let Some(socket) = resolve_equipment_attachment_socket(topology, topologies)
131:     {
132:         // Generated attachment sockets are authored pelvis-local, so
133:         // they can be consumed directly as children of the pelvis.
134:         socket
135:     } else {
136:         equipment_bind_correction(role, rig, bind_nodes)?
137:     };
138:     Some((bone, correction))
139: }

1: //! Capture readiness reads the same resolved meshes and wearer skins as gameplay.
2: use crate::equipment::{
3:     ItemPlaceholder, ProceduralEquipmentFailed, ProceduralEquipmentPart,
4:     ProceduralEquipmentResolved,
5: };
6: use crate::presentation::interior_lighting::InteriorMaterial;
7: use bevy::{
8:     ecs::system::SystemParam,
9:     mesh::{morph::MeshMorphWeights, skinning::SkinnedMesh},
10:     prelude::*,
11: };
12: 
13: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
14: pub(in crate::animation_viewer) enum EquipmentVisualState {
15:     Missing,
16:     Loading,
17:     Ready,
18:     Failed,
19: }
20: 
21: #[derive(Clone, Copy, Default)]
22: pub(in crate::animation_viewer) struct EquipmentVisualRequirements {
23:     pub names: &'static [&'static str],
24:     pub morph_targets: Option<usize>,
25: }
26: 
27: type EquipmentRenderPart = (
28:     &'static ProceduralEquipmentPart,
29:     &'static Mesh3d,
30:     &'static crate::presentation::interior_lighting::InteriorMaterialSource,
31:     Option<&'static SkinnedMesh>,
32:     Option<&'static MeshMorphWeights>,
33:     Option<&'static Name>,
34:     Option<&'static MeshMaterial3d<InteriorMaterial>>,
35: );
36: 
37: /// Readiness requires a resolved procedural mesh, its material and a bound skin.
38: /// Loading cuboid proxies never qualify as captured armor.
39: #[derive(SystemParam)]
40: pub(in crate::animation_viewer) struct EquipmentVisualStatus<'w, 's> {
41:     roots: Query<
42:         'w,
43:         's,
44:         (
45:             &'static ItemPlaceholder,
46:             Has<ProceduralEquipmentResolved>,
47:             Has<ProceduralEquipmentFailed>,
48:         ),
49:     >,
50:     parts: Query<'w, 's, EquipmentRenderPart>,
51:     meshes: Res<'w, Assets<Mesh>>,
52:     materials: Res<'w, Assets<StandardMaterial>>,
53:     images: Res<'w, Assets<Image>>,
54:     render_materials: Option<Res<'w, Assets<InteriorMaterial>>>,
55: }
56: 
57: impl EquipmentVisualStatus<'_, '_> {
58:     pub(in crate::animation_viewer) fn state(
59:         &self,
60:         item: Entity,
61:         required: EquipmentVisualRequirements,
62:     ) -> EquipmentVisualState {
63:         let Some((_, resolved, failed)) = self.roots.iter().find(|(root, _, _)| root.0 == item)
64:         else {
65:             return EquipmentVisualState::Missing;
66:         };
67:         if failed {
68:             return EquipmentVisualState::Failed;
69:         }
70:         if !resolved {
71:             return EquipmentVisualState::Loading;
72:         }
73:         let mut count = 0;
74:         let mut names = std::collections::BTreeSet::new();
75:         for (part, mesh, material, skin, morphs, name, _) in
76:             self.parts.iter().filter(|(part, ..)| part.item == item)
77:         {
78:             count += 1;
79:             if let Some(name) = name {
80:                 names.insert(name.as_str());
81:             }
82:             let Some(mesh) = self.meshes.get(&mesh.0) else {
83:                 return EquipmentVisualState::Loading;
84:             };
85:             if super::skinning::WeightSummary::from_mesh(mesh)
86:                 .is_none_or(|weights| !weights.valid())
87:             {
88:                 return EquipmentVisualState::Failed;
89:             }
90:             if required.morph_targets.is_some_and(|count| {
91:                 mesh.morph_target_names().map_or(0, <[String]>::len) != count
92:                     || match morphs {
93:                         None => count != 0,
94:                         Some(MeshMorphWeights::Value { weights }) => {
95:                             weights.len() != count
96:                                 || weights.iter().any(|weight| !weight.is_finite())
97:                         }
98:                         Some(_) => true,
99:                     }
100:             }) {
101:                 return EquipmentVisualState::Loading;
102:             }
103:             if self.materials.get(&material.0).is_none_or(|material| {
104:                 [
105:                     &material.base_color_texture,
106:                     &material.normal_map_texture,
107:                     &material.occlusion_texture,
108:                 ]
109:                 .into_iter()
110:                 .flatten()
111:                 .any(|texture| self.images.get(texture).is_none())
112:             }) || skin.is_none_or(|skin| {
113:                 skin.joints.is_empty() || skin.joints.len() != part.joint_names.len()
114:             }) || (mesh
115:                 .morph_target_names()
116:                 .is_some_and(|names| !names.is_empty())
117:                 && morphs.is_none())
118:             {
119:                 return EquipmentVisualState::Loading;
120:             }
121:         }
122:         if count == 0
123:             || (!required.names.is_empty()
124:                 && (count != required.names.len()
125:                     || !required.names.iter().all(|name| names.contains(name))))
126:         {
127:             EquipmentVisualState::Loading
128:         } else {
129:             EquipmentVisualState::Ready
130:         }
131:     }
132:     pub(in crate::animation_viewer) fn summary(&self, item: Entity) -> Vec<serde_json::Value> {
133:         self.parts
134:             .iter()
135:             .filter(|(part, ..)| part.item == item)
136:             .map(|(part, mesh, material, skin, morphs, name, rendered)| {
137:                 let mesh = self.meshes.get(&mesh.0);
138:                 let source = self.materials.get(&material.0);
139:                 let rendered = rendered.and_then(|handle| {
140:                     self.render_materials.as_ref()?.get(&handle.0).map(|material| &material.base)
141:                 });
142:                 serde_json::json!({
143:                     "name": name.map(Name::as_str),
144:                     "mesh_loaded": mesh.is_some(),
145:                     "material_loaded": source.is_some(),
146:                     "source_material_textures": source.map(|material| super::material::textures(material, &self.images)),
147:                     "render_material_textures": rendered.map(|material| super::material::textures(material, &self.images)),
148:                     "skin_joints": skin.map(|skin| skin.joints.len()),
149:                     "expected_skin_joints": part.joint_names.len(),
