1: //! Borrowed equipment identities admitted against their owning catalogue.
2: 
3: use crate::item_catalog::{EquipmentPlacement, ItemDefinition};
4: use std::hash::{Hash, Hasher};
5: use std::ops::Deref;
6: use std::sync::Arc;
7: 
8: /// One actual record in an admitted catalogue. Exact-name lookup keeps the
9: /// catalogue's first duplicate; record admission can retain every duplicate.
10: #[derive(Clone, Copy, Debug)]
11: pub struct CatalogItem<'a> {
12:     definition: &'a ItemDefinition,
13: }
14: 
15: /// A placement borrowed from the equipment definition of its actual item.
16: /// Construction proves that relationship without imposing clothing eligibility
17: /// or a fixed set of placement names.
18: #[derive(Clone, Copy, Debug)]
19: pub struct CatalogPlacement<'a> {
20:     item: CatalogItem<'a>,
21:     placement: &'a EquipmentPlacement,
22: }
23: 
24: /// An admitted placement retained beyond an owned catalogue borrow, such as an
25: /// editor exhibit. Every placement of an item shares one immutable snapshot.
26: #[derive(Clone, Debug)]
27: pub struct OwnedCatalogPlacement {
28:     definition: Arc<ItemDefinition>,
29:     placement: RetainedPlacementOrdinal,
30: }
31: 
32: #[derive(Clone, Copy, Debug)]
33: struct RetainedPlacementOrdinal(usize);
34: 
35: impl<'a> CatalogItem<'a> {
36:     pub fn all(catalogue: &'a [ItemDefinition]) -> impl Iterator<Item = Self> {
37:         catalogue.iter().map(|definition| Self { definition })
38:     }
39: 
40:     /// Decode an exact authored, CLI, manifest or replicated item key once.
41:     pub fn find(catalogue: &'a [ItemDefinition], id: &str) -> Option<Self> {
42:         catalogue
43:             .iter()
44:             .find(|definition| definition.id == id)
45:             .map(|definition| Self { definition })
46:     }
47: 
48:     /// Admit an actual catalogue record, preserving duplicate-ID export order.
49:     pub fn admit(catalogue: &'a [ItemDefinition], record: &ItemDefinition) -> Option<Self> {
50:         catalogue
51:             .iter()
52:             .find(|definition| std::ptr::eq(*definition, record))
53:             .map(|definition| Self { definition })
54:     }
55: 
56:     pub fn definition(self) -> &'a ItemDefinition {
57:         self.definition
58:     }
59: 
60:     /// Decode a placement key in this item's own equipment definition.
61:     pub fn placement(self, id: &str) -> Option<CatalogPlacement<'a>> {
62:         self.placements()
63:             .find(|selection| selection.placement.id == id)
64:     }
65: 
66:     /// Authored placement order; consumers may explicitly choose lexical order.
67:     pub fn placements(self) -> impl Iterator<Item = CatalogPlacement<'a>> {
68:         self.definition
69:             .equipment
70:             .iter()
71:             .flat_map(|equipment| &equipment.placements)
72:             .map(move |placement| CatalogPlacement {
73:                 item: self,
74:                 placement,
75:             })
76:     }
77: 
78:     /// Retain the actual authored placements once at a long-lived selection
79:     /// producer. No key is decoded again when the selection is later borrowed.
80:     pub fn retained_placements(self) -> impl Iterator<Item = OwnedCatalogPlacement> {
81:         let count = self
82:             .definition
83:             .equipment
84:             .as_ref()
85:             .map_or(0, |equipment| equipment.placements.len());
86:         let definition = Arc::new((*self.definition).clone());
87:         (0..count).map(move |placement| OwnedCatalogPlacement {
88:             definition: Arc::clone(&definition),
89:             placement: RetainedPlacementOrdinal(placement),
90:         })
91:     }
92: }
93: 
94: impl OwnedCatalogPlacement {
95:     pub fn item(&self) -> CatalogItem<'_> {
96:         CatalogItem {
97:             definition: self.definition.as_ref(),
98:         }
99:     }
100: 
101:     pub fn selection(&self) -> CatalogPlacement<'_> {
102:         // Only retained_placements constructs this record. Its ordinal comes
103:         // from this exact snapshot's present equipment definition and bounds.
104:         let equipment = &self.definition.equipment.as_slice()[0];
105:         CatalogPlacement {
106:             item: self.item(),
107:             placement: &equipment.placements[self.placement.0],
108:         }
109:     }
110: }
111: 
112: impl<'a> CatalogPlacement<'a> {
113:     /// Decode an item/placement pair at an external input boundary.
114:     pub fn find(catalogue: &'a [ItemDefinition], item: &str, placement: &str) -> Option<Self> {
115:         CatalogItem::find(catalogue, item)?.placement(placement)
116:     }
117: 
118:     pub fn item(self) -> CatalogItem<'a> {
119:         self.item
120:     }
121: 
122:     pub fn definition(self) -> &'a EquipmentPlacement {
123:         self.placement
124:     }
125: }
126: 
127: impl PartialEq for CatalogItem<'_> {
128:     fn eq(&self, other: &Self) -> bool {
129:         std::ptr::eq(self.definition, other.definition)
130:     }
131: }
132: 
133: impl Eq for CatalogItem<'_> {}
134: 
135: impl Hash for CatalogItem<'_> {
136:     fn hash<H: Hasher>(&self, state: &mut H) {
137:         std::ptr::hash(self.definition, state);
138:     }
139: }
140: 
141: impl PartialEq for CatalogPlacement<'_> {
142:     fn eq(&self, other: &Self) -> bool {
143:         self.item == other.item && std::ptr::eq(self.placement, other.placement)
144:     }
145: }
146: 
147: impl Eq for CatalogPlacement<'_> {}
148: 
149: impl Hash for CatalogPlacement<'_> {
150:     fn hash<H: Hasher>(&self, state: &mut H) {
151:         self.item.hash(state);
152:         std::ptr::hash(self.placement, state);
153:     }
154: }
155: 
156: impl Deref for CatalogItem<'_> {
157:     type Target = ItemDefinition;
158: 
159:     fn deref(&self) -> &Self::Target {
160:         self.definition
161:     }
162: }
163: 
164: impl Deref for CatalogPlacement<'_> {
165:     type Target = EquipmentPlacement;
166: 
167:     fn deref(&self) -> &Self::Target {
168:         self.placement
169:     }
170: }
