1: //! Runtime equipment generated on the armor device from the canonical rig's
2: //! mesh data, without an intermediate GLB.
3: 
4: use crate::{
5:     armor_frames::{FittingPlacement, Side},
6:     armor_recipes::{self, DedicatedGenerator, ParametricDesign},
7:     bracer::{ForearmSide, ForearmSurfaceInput},
8:     device_body::DeviceBody,
9:     device_fit::{self, FitBody, Fitted, Realization},
10:     device_torso::TorsoSurfaceInput,
11:     device_underlayer::SurfaceDomain,
12:     underlayer_armor::{self, UnderlayerBody},
13: };
14: use adventuresim_core::{
15:     equipment_assets::{CatalogItem, CatalogPlacement},
16:     item_catalog,
17:     item_references::BELT_ID,
18: };
19: use anyhow::{Context, Result, bail};
20: use clothing::RuntimeClothing;
21: use fabelgeist_armor::{ArmorGpu, BracerDesign, BreastplateDesign, GeneratedArmor};
22: use fabelgeist_rig::RigJointName;
23: use std::sync::LazyLock;
24: pub use warmup::{WarmupReport, warm_up};
25: 
26: mod clothing;
27: mod warmup;
28: 
29: static ITEM_CATALOG: LazyLock<Vec<RuntimeCatalogItem>> = LazyLock::new(|| {
30:     item_catalog::authored_document_items()
31:         .into_iter()
32:         .filter_map(|item| CatalogItem::admit(item_catalog::catalog(), item))
33:         .map(RuntimeCatalogItem::from_catalog)
34:         .collect()
35: });
36: 
37: /// A canonical catalogue reference with clothing eligibility classified once.
38: #[derive(Clone, Copy)]
39: struct RuntimeCatalogItem {
40:     definition: CatalogItem<'static>,
41:     clothing_role: RuntimeClothingRole,
42: }
43: 
44: /// One evaluated wearer in its unposed fitting frame. Runtime equipment has no
45: /// body-shape morph targets; a changed body requires a new fit.
46: #[derive(Clone)]
47: pub struct RuntimeBody {
48:     pub domain: String,
49:     pub faces: Vec<[u32; 3]>,
50:     pub positions: Vec<[f32; 3]>,
51:     pub normals: Vec<[f32; 3]>,
52:     /// One surface coordinate per vertex; `texcoord_faces` index them.
53:     pub texcoords: Vec<[f32; 2]>,
54:     pub texcoord_faces: Vec<[u32; 3]>,
55:     pub joint_indices: fabelgeist_rig::PackedRigSkin<8>,
56:     pub joint_weights: Vec<[f32; 8]>,
57:     pub joint_names: fabelgeist_rig::RigJointTable<RigJointName>,
58:     pub global_joint_states: fabelgeist_rig::RigJointTable<[f32; 8]>,
59:     /// This body on the armor device, once a piece has uploaded it.
60:     pub device: DeviceBody,
61: }
62: 
63: #[derive(Clone, Copy, PartialEq, Eq)]
64: enum RuntimeClothingRole {
65:     Fitted,
66:     Unsupported,
67: }
68: 
69: impl RuntimeCatalogItem {
70:     fn from_catalog(item: CatalogItem<'static>) -> Self {
71:         let fitted = matches!(item.kind, crate::item_catalog_schema::ItemKind::Clothing)
72:             || item.id == BELT_ID;
73:         Self {
74:             definition: item,
75:             clothing_role: if fitted {
76:                 RuntimeClothingRole::Fitted
77:             } else {
78:                 RuntimeClothingRole::Unsupported
79:             },
80:         }
81:     }
82: }
83: 
84: impl RuntimeBody {
85:     fn validate(&self) -> Result<()> {
86:         let vertices = self.positions.len();
87:         if self.domain.trim().is_empty()
88:             || vertices == 0
89:             || self.normals.len() != vertices
90:             || self.texcoords.len() != vertices
91:             || self.joint_indices.len() != vertices
92:             || self.joint_weights.len() != vertices
93:             || self.joint_names.len() != self.global_joint_states.len()
94:             || self.joint_indices.joint_count() != self.joint_names.joint_count()
95:             || self.faces.is_empty()
96:             || self.texcoord_faces.len() != self.faces.len()
97:         {
98:             bail!("runtime equipment body data is inconsistent");
99:         }
100:         Ok(())
101:     }
102: 
103:     fn fit_body(&self) -> FitBody<'_> {
104:         FitBody {
105:             faces: &self.faces,
106:             texcoords: &self.texcoords,
107:             joint_indices: &self.joint_indices,
108:             joint_weights: &self.joint_weights,
109:             joint_names: &self.joint_names,
110:         }
111:     }
112: 
113:     fn wearer(&self) -> Realization<'_> {
114:         Realization {
115:             positions: &self.positions,
116:             normals: &self.normals,
117:             joints: &self.global_joint_states,
118:             device: &self.device,
119:         }
120:     }
121: }
122: 
123: /// Generate one fitted equipment item: armor on the armor device, clothing
124: /// offset from the body.
125: pub async fn generate(
126:     body: &RuntimeBody,
127:     selection: CatalogPlacement<'static>,
128:     bracer_design: &BracerDesign,
129:     breastplate_design: &BreastplateDesign,
130:     layers: &[&GeneratedArmor],
131: ) -> Result<GeneratedArmor> {
132:     if armor_recipes::is_parametric(selection.item()) {
133:         generate_runtime_armor(body, selection, bracer_design, breastplate_design, layers).await
134:     } else {
135:         body.validate()?;
136:         catalog_record(selection.item())
137:             .with_context(|| format!("unknown clothing item {}", selection.item().id))?;
138:         RuntimeClothing::new(body, selection).generate()
139:     }
140: }
141: 
142: /// Generate one fitted armor piece on the armor device.
143: ///
144: /// Fits the authored design only to this wearer, without equipment morphs.
145: pub async fn generate_runtime_armor(
146:     body: &RuntimeBody,
147:     selection: CatalogPlacement<'static>,
148:     bracer_design: &BracerDesign,
149:     breastplate_design: &BreastplateDesign,
150:     layers: &[&GeneratedArmor],
151: ) -> Result<GeneratedArmor> {
152:     body.validate()?;
153:     let gpu = crate::armor_gpu::armor_gpu_async().await?;
154:     let item = selection.item();
155:     match DedicatedGenerator::for_item(item) {
156:         Some(DedicatedGenerator::Vambrace) => {
157:             generate_vambrace(gpu, body, selection, bracer_design).await
158:         }
159:         Some(DedicatedGenerator::Breastplate) => {
160:             generate_breastplate(gpu, body, breastplate_design).await
161:         }
162:         None => {
163:             let design = armor_recipes::recipe(item)
164:                 .with_context(|| format!("no runtime armor recipe for {}", item.id))?;
165:             generate_parametric(gpu, body, &design, selection, layers).await
166:         }
167:     }
168: }
169: 
170: /// The material assigned to an authored runtime equipment item.
171: pub fn runtime_equipment_material(
172:     item: CatalogItem<'static>,
173: ) -> Option<crate::item_catalog_schema::EquipmentMaterial> {
174:     catalog_record(item)
175:         .and_then(|item| item.definition.definition().equipment.as_ref())
176:         .and_then(|equipment| equipment.material)
177: }
178: 
179: /// Whether the item has an authored parametric armor runtime path.
180: pub fn is_runtime_armor(item_id: &str) -> bool {
181:     CatalogItem::find(item_catalog::catalog(), item_id).is_some_and(armor_recipes::is_parametric)
182: }
183: 
184: /// Whether the item has an authored fitted clothing runtime path.
185: pub fn is_runtime_clothing(item_id: &str) -> bool {
186:     catalog_item(item_id).is_some_and(|item| {
187:         item.clothing_role == RuntimeClothingRole::Fitted
188:             && !armor_recipes::is_parametric(item.definition)
189:     })
190: }
191: 
192: /// Whether the item should be generated from the loaded body rig.
193: pub fn is_runtime_equipment(item_id: &str) -> bool {
194:     CatalogItem::find(item_catalog::catalog(), item_id).is_some_and(|item| {
195:         armor_recipes::is_parametric(item)
196:             || catalog_record(item)
197:                 .is_some_and(|record| record.clothing_role == RuntimeClothingRole::Fitted)
198:     })
199: }
200:

201: async fn generate_vambrace(
202:     gpu: &ArmorGpu,
203:     body: &RuntimeBody,
204:     placement: CatalogPlacement<'_>,
205:     design: &BracerDesign,
206: ) -> Result<GeneratedArmor> {
207:     let side = match FittingPlacement::from(placement).side()? {
208:         Side::Left => ForearmSide::Left,
209:         Side::Right => ForearmSide::Right,
210:     };
211:     crate::device_bracer::generate_bracer_on_device_async(
212:         gpu,
213:         design,
214:         ForearmSurfaceInput {
215:             domain: &body.domain,
216:             side,
217:             positions: &body.positions,
218:             normals: &body.normals,
219:             faces: &body.faces,
220:             texcoords: &body.texcoords,
221:             texcoord_faces: &body.texcoord_faces,
222:             joint_indices: &body.joint_indices,
223:             joint_weights: &body.joint_weights,
224:             joint_names: &body.joint_names,
225:             global_joint_states: &body.global_joint_states,
226:             morphs: &[],
227:         },
228:     )
229:     .await
230: }
231: 
232: async fn generate_breastplate(
233:     gpu: &ArmorGpu,
234:     body: &RuntimeBody,
235:     design: &BreastplateDesign,
236: ) -> Result<GeneratedArmor> {
237:     crate::device_torso::generate_breastplate_on_device_async(
238:         gpu,
239:         design,
240:         TorsoSurfaceInput {
241:             domain: &body.domain,
242:             positions: &body.positions,
243:             normals: &body.normals,
244:             faces: &body.faces,
245:             texcoords: &body.texcoords,
246:             texcoord_faces: &body.texcoord_faces,
247:             joint_indices: &body.joint_indices,
248:             joint_weights: &body.joint_weights,
249:             joint_names: &body.joint_names,
250:             global_joint_states: &body.global_joint_states,
251:             morphs: &[],
252:         },
253:     )
254:     .await
255: }
256: 
257: async fn generate_parametric(
258:     gpu: &ArmorGpu,
259:     body: &RuntimeBody,
260:     design: &ParametricDesign,
261:     placement: CatalogPlacement<'_>,
262:     layers: &[&GeneratedArmor],
263: ) -> Result<GeneratedArmor> {
264:     let placement = FittingPlacement::from(placement);
265:     match design {
266:         ParametricDesign::Underlayer(_) | ParametricDesign::TrunkHose(_) => {
267:             let wearer = body.wearer().wearer(&body.fit_body());
268:             let cut = UnderlayerBody {
269:                 wearer: &wearer,
270:                 domain: SurfaceDomain {
271:                     uv_faces: &body.texcoord_faces,
272:                     texcoords: &body.texcoords,
273:                 },
274:                 surface_domain: &body.domain,
275:                 proportions: &[],
276:             };
277:             match design {
278:                 ParametricDesign::Underlayer(design) => {
279:                     underlayer_armor::fit_underlayer_async(gpu, design, placement, &cut, &[]).await
280:                 }
281:                 ParametricDesign::TrunkHose(design) => {
282:                     underlayer_armor::fit_trunk_hose_async(gpu, design, placement, &cut, &[]).await
283:                 }
284:                 _ => unreachable!(),
285:             }
286:         }
287:         _ => {
288:             let piece = device_fit::fit_recipe_async(
289:                 gpu,
290:                 &body.fit_body(),
291:                 &body.wearer(),
292:                 &[],
293:                 design,
294:                 placement,
295:                 layers,
296:             )
297:             .await?;
298:             device_fit::assemble_recipe(
299:                 design,
300:                 piece,
301:                 &Fitted {
302:                     placement,
303:                     morphs: &[],
304:                     domain: &body.domain,
305:                     joint_names: &body.joint_names,
306:                     joints: &body.global_joint_states,
307:                 },
308:             )
309:         }
310:     }
311: }
312: 
313: fn catalog_record(item: CatalogItem<'static>) -> Option<RuntimeCatalogItem> {
314:     ITEM_CATALOG
315:         .iter()
316:         .find(|record| record.definition == item)
317:         .copied()
318: }
319: 
320: fn catalog_item(item_id: &str) -> Option<RuntimeCatalogItem> {
321:     let item = CatalogItem::find(item_catalog::catalog(), item_id)?;
322:     catalog_record(item)
323: }
