327:     use super::*;
328: 
329:     #[test]
330:     fn generated_clothing_uses_the_runtime_path() {
331:         for item_id in ["linen_tunic", "linen_breeches", "belt"] {
332:             assert!(is_runtime_clothing(item_id), "{item_id}");
333:             assert!(is_runtime_equipment(item_id), "{item_id}");
334:         }
335:         for item_id in ["leather_boot", "vambrace", "breastplate", "cuirass"] {
336:             assert!(is_runtime_armor(item_id), "{item_id}");
337:             assert!(!is_runtime_clothing(item_id), "{item_id}");
338:         }
339:         assert!(!is_runtime_equipment("arming_sword"));
340:     }
341: }

