1: //! Presentation-only browser boundary. Rectangles are physical canvas pixels.
2: use bevy::prelude::*;
3: use serde::{Deserialize, Serialize};
4: 
5: pub(crate) const FORGE_LAYER: usize = 1;
6: pub(crate) const COMPOSITOR_LAYER: usize = 2;
7: use crate::presentation::ownership::REGIONAL_MAP_LAYER;
8: pub(crate) const FIRST_PERSON_LAYER: usize = REGIONAL_MAP_LAYER + 1;
