1: //! Semantic map commands. Pixel displacements enter only at the canvas port.
2: use adventuresim_building_generator::spatial_geometry::{GeometryError, Radians};
3: use adventuresim_tactical_core::{
4:     regional_environment::RegionalEnvironment,
5:     regional_map::{MapOverlay, MapScaleError, MapSpan, MapZoomRatio},
6: };
7: use adventuresim_world_schema::coordinates::Wgs84CoordinateMicrodegrees;
8: use adventuresim_world_schema::source_package::SourcePackageDigest;
9: use bevy::math::Vec2;
10: use serde::{Deserialize, Serialize};
11: 
12: pub(crate) use crate::strategic_scene::protocol::CanvasRect;
13: 
14: const MAX_BROWSER_OVERLAY_REVISION: u64 = (1_u64 << 53) - 1;
15: 
16: /// Document-local overlay publication ordinal, exactly representable by JS.
17: #[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd, Serialize, Deserialize)]
18: #[serde(try_from = "u64")]
19: pub(crate) struct MapOverlayRevision(u64);
20: 
21: /// Physical canvas pixels, not scene metres or a geographic position.
22: #[derive(Clone, Copy, Debug, Deserialize)]
23: #[serde(try_from = "Vec2")]
24: pub(crate) struct MapPointerDisplacement(Vec2);
25: 
26: #[derive(Debug, Deserialize)]
27: #[serde(tag = "type", rename_all = "kebab-case", deny_unknown_fields)]
28: pub(crate) enum MapCommand {
29:     Open {
30:         source: SourcePackageDigest,
31:         origin: Wgs84CoordinateMicrodegrees,
32:         span: MapSpan,
33:         #[serde(deserialize_with = "viewport")]
34:         rect: CanvasRect,
35:     },
36:     Resize {
37:         #[serde(deserialize_with = "viewport")]
38:         rect: CanvasRect,
39:     },
40:     Pan {
41:         delta: MapPointerDisplacement,
42:     },
43:     Zoom {
44:         ratio: MapZoomRatio,
45:     },
46:     Rotate {
47:         angle: Radians,
48:     },
49:     Reset,
50:     FrameRoute,
51:     Hide,
52:     InstallCity {
53:         document_json: String,
54:         preparation: crate::presentation::generation::PreparationTicket,
55:     },
56:     InstallEnvironment {
57:         environment: Box<RegionalEnvironment>,
58:     },
59:     InstallOverlay {
60:         revision: MapOverlayRevision,
61:         overlay: MapOverlay,
62:     },
63: }
64: 
65: #[derive(Debug, thiserror::Error)]
66: pub(crate) enum MapProtocolError {
67:     #[error(transparent)]
68:     Scale(#[from] MapScaleError),
69:     #[error("map pointer displacement must be finite")]
70:     Pointer,
71:     #[error("map canvas rectangle is invalid")]
72:     Viewport,
73:     #[error("map camera origin is outside WGS84")]
74:     Origin,
75:     #[error("map overlay revision must be a positive exact browser integer")]
76:     OverlayRevision,
77:     #[error(transparent)]
78:     Geometry(#[from] GeometryError),
79: }
80: 
81: impl TryFrom<u64> for MapOverlayRevision {
82:     type Error = MapProtocolError;
83:     fn try_from(revision: u64) -> Result<Self, Self::Error> {
84:         (1..=MAX_BROWSER_OVERLAY_REVISION)
85:             .contains(&revision)
86:             .then_some(Self(revision))
87:             .ok_or(MapProtocolError::OverlayRevision)
88:     }
89: }
90: 
91: impl MapPointerDisplacement {
92:     pub(super) fn pixels(self) -> Vec2 {
93:         self.0
94:     }
95: }
96: 
97: impl TryFrom<Vec2> for MapPointerDisplacement {
98:     type Error = MapProtocolError;
99:     fn try_from(pixels: Vec2) -> Result<Self, Self::Error> {
100:         pixels
101:             .is_finite()
102:             .then_some(Self(pixels))
103:             .ok_or(MapProtocolError::Pointer)
104:     }
105: }
106: 
107: /// CanvasRect is the shared native viewport port. Admit map rectangles here;
108: /// half-visible CSS edges can round outward by at most one physical pixel.
109: fn viewport<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<CanvasRect, D::Error> {
110:     let rect = CanvasRect::deserialize(deserializer)?;
111:     let valid = rect.width > 0
112:         && rect.height > 0
113:         && rect.full_width >= rect.width
114:         && rect.full_height >= rect.height
115:         && rect.offset_x.is_finite()
116:         && rect.offset_y.is_finite()
117:         && rect.offset_x >= 0.0
118:         && rect.offset_y >= 0.0
119:         && f64::from(rect.offset_x) + f64::from(rect.width) <= f64::from(rect.full_width) + 1.0
120:         && f64::from(rect.offset_y) + f64::from(rect.height) <= f64::from(rect.full_height) + 1.0;
121:     if valid {
122:         Ok(rect)
123:     } else {
124:         Err(serde::de::Error::custom(MapProtocolError::Viewport))
125:     }
126: }

