161: impl MapState {
162:     fn terrain(&self) -> Option<&RegionalTerrain> {
163:         self.environment
164:             .as_ref()
165:             .map(|environment| environment.terrain())
166:     }
167: 
168:     fn open(
169:         &mut self,
170:         source: SourcePackageDigest,
171:         origin: Wgs84CoordinateMicrodegrees,
172:         span: MapSpan,
173:         rect: protocol::CanvasRect,
174:     ) {
175:         if let Some(pose) = self.pose.as_mut()
176:             && pose.source == source
177:             && pose.home == origin
178:         {
179:             pose.rect = Some(rect);
180:         } else {
181:             self.pose = Some(MapPose::new(source, origin, span, rect));
182:             self.environment = None;
183:             self.overlay = None;
184:             self.overlay_revision = None;
185:         }
186:     }
187: 
188:     fn pan(&mut self, delta: protocol::MapPointerDisplacement) -> camera::Result<()> {
189:         let Some(pose) = self.pose.as_mut() else {
190:             return Ok(());
191:         };
192:         let frame = self
193:             .presented
194:             .as_ref()
195:             .filter(|surface| surface.source == pose.source)
196:             .map_or(pose.home, |surface| surface.request.origin);
197:         pose.pan(delta, frame)
198:     }
199: 
200:     fn frame_route(&mut self) -> camera::Result<()> {
201:         match (
202:             self.pose.as_mut(),
203:             self.overlay.as_ref().and_then(MapOverlay::route),
204:         ) {
205:             (Some(pose), Some(route)) => pose.frame_route(route),
206:             _ => Ok(()),
207:         }
208:     }
209: }
