14: use serde::Serialize;
15: use std::sync::{Mutex, OnceLock};
16: 
17: static STATUS: OnceLock<Mutex<String>> = OnceLock::new();
18: const SETTLED_RENDER_FRAMES: usize = 4;
19: 
20: #[derive(Serialize)]
21: struct Status<'a> {
22:     ready: bool,
