45: #[derive(Serialize)]
46: #[serde(rename_all = "kebab-case")]
47: enum Failure {
48:     Span,
49:     Zoom,
50:     Pointer,
51:     Viewport,
52:     Origin,
53:     OverlayRevision,
54:     RouteCapacity,
55:     ConnectionCapacity,
56:     Geometry,
57: }
58: 
59: impl From<&MapProtocolError> for Failure {
60:     fn from(error: &MapProtocolError) -> Self {
61:         match error {
62:             MapProtocolError::Scale(MapScaleError::Span { .. }) => Self::Span,
63:             MapProtocolError::Scale(MapScaleError::Zoom { .. }) => Self::Zoom,
64:             MapProtocolError::Scale(MapScaleError::Geometry(_)) => Self::Geometry,
65:             MapProtocolError::Pointer => Self::Pointer,
66:             MapProtocolError::Viewport => Self::Viewport,
67:             MapProtocolError::Origin => Self::Origin,
68:             MapProtocolError::OverlayRevision => Self::OverlayRevision,
69:             MapProtocolError::Geometry(_) => Self::Geometry,
70:         }
71:     }
72: }
