74: impl MapState {
75:     fn requested_window(&mut self) -> Option<RegionalTerrainRequest> {
76:         match self
77:             .pose
78:             .as_ref()
79:             .map(|pose| pose.requested_window())
80:             .transpose()
81:         {
82:             Ok(requested) => requested.flatten(),
83:             Err(error) => {
84:                 self.failure = Some(error);
85:                 None
86:             }
87:         }
88:     }
89: }
90: 
91: pub(super) fn publish(
92:     mut state: ResMut<MapState>,
93:     sky: Res<crate::presentation::AtmosphereIblCache>,
94:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
95:     cameras: Query<(&Camera, &GlobalTransform), With<RegionalMapCamera>>,
96: ) {
97:     let requested = state.requested_window();
98:     let visible = state.pose.as_ref().is_some_and(|pose| pose.rect.is_some());
99:     let matched = state
100:         .pose
101:         .as_ref()
102:         .zip(state.presented.as_ref())
103:         .is_some_and(|(pose, surface)| surface.source == pose.source);
104:     let covered = matched
105:         && state
106:             .presented
107:             .as_ref()
108:             .is_some_and(|surface| matches!(surface.coverage, SurfaceCoverage::Drawn { .. }));
109:     let waiting = crate::presentation::pipeline_readiness::waiting_pipelines();
110:     let environment_ready = sky.is_ready(&settings);
111:     let route_capacity_exceeded = state
112:         .presented_route
113:         .as_ref()
114:         .is_some_and(|route| route.capacity_exceeded());
115:     let connection_capacity_exceeded = state
116:         .presented_connections
117:         .as_ref()
118:         .is_some_and(|connections| connections.capacity_exceeded());
119:     if visible
120:         && matched
121:         && viewport_matches(&state, &cameras)
122:         && environment_ready
123:         && (waiting == 0 || state.settled_frames >= SETTLED_RENDER_FRAMES)
124:         && state.failure.is_none()
125:     {
126:         state.settled_frames = state
127:             .settled_frames
128:             .saturating_add(1)
129:             .min(SETTLED_RENDER_FRAMES);
130:     } else {
131:         state.settled_frames = 0;
132:     }
133:     let pose = state.pose.as_ref();
134:     let status = Status {
135:         ready: state.settled_frames >= SETTLED_RENDER_FRAMES
136:             && !route_capacity_exceeded
137:             && !connection_capacity_exceeded,
138:         presentation_ready: state.settled_frames >= SETTLED_RENDER_FRAMES,
139:         overlay_revision: state.overlay_revision,
140:         rect: pose.and_then(|pose| pose.rect),
141:         visible,
142:         covered,
143:         environment_ready,
144:         source: pose.map(|pose| &pose.source),
145:         home: pose.map(|pose| pose.home),
146:         origin: pose.and_then(|pose| pose.geographic_origin().ok()),
147:         span: pose.map(|pose| pose.span),
148:         yaw: pose.map(|pose| pose.yaw),
149:         requested,
150:         presented: state
151:             .presented
152:             .as_ref()
153:             .filter(|_| matched)
154:             .map(|surface| surface.request),
155:         connection_meshes: state
156:             .presented_connections
157:             .as_ref()
158:             .map_or(0, |connections| connections.mesh_count()),
159:         waiting_pipelines: waiting,
160:         error: state
161:             .failure
162:             .as_ref()
163:             .map(Failure::from)
164:             .or(route_capacity_exceeded.then_some(Failure::RouteCapacity))
165:             .or(connection_capacity_exceeded.then_some(Failure::ConnectionCapacity)),
166:         markers: markers::project(&state, &cameras),
167:         city_requested: state.requested_city(),
168:         city_installation: state.city.status,
169:         city_visible: state.city.visible,
170:     };
171:     match serde_json::to_string(&status) {
172:         Ok(json) => match STATUS.get_or_init(|| Mutex::new(String::new())).lock() {
173:             Ok(mut snapshot) => *snapshot = json,
174:             Err(error) => warn!(%error, "regional map status is unavailable"),
175:         },
176:         Err(error) => warn!(%error, "regional map status could not serialize"),
177:     }
178: }
179: 
180: pub(crate) fn json() -> String {
181:     STATUS
182:         .get_or_init(|| Mutex::new("{\"ready\":false,\"visible\":false}".into()))
183:         .lock()
184:         .map(|snapshot| snapshot.clone())
185:         .unwrap_or_else(|_| "{\"ready\":false,\"error\":\"status-unavailable\"}".into())
186: }
187: 
188: /// Bevy may resize a viewport while processing a display scale-factor event.
189: /// Wait for the actual camera to match the browser's physical-pixel rectangle.
190: fn viewport_matches(
191:     state: &MapState,
192:     cameras: &Query<(&Camera, &GlobalTransform), With<RegionalMapCamera>>,
193: ) -> bool {
194:     let Some(rect) = state.pose.as_ref().and_then(|pose| pose.rect) else {
195:         return false;
196:     };
197:     let Ok((camera, _)) = cameras.single() else {
198:         return false;
199:     };
200:     camera.physical_viewport_rect().is_some_and(|viewport| {
201:         viewport.min == UVec2::new(rect.x, rect.y)
202:             && viewport.size() == UVec2::new(rect.width, rect.height)
203:     })
204: }

