107:     /// Geographic pin/camera adapter: query the actual city triangles in their
108:     /// canonical east/north frame, then apply the same matrix as the renderer.
109:     pub(super) fn city_position(&self, origin: NativeTerrainCoordinate) -> Option<Vec3> {
110:         if !self.city.visible {
111:             return None;
112:         }
113:         let city = self.city.installed.as_ref()?;
114:         let offset =
115:             NativeTerrainCoordinate::from(city.product.document.origin()).offset_to(origin);
116:         let local = ScenePlanPoint::try_from(Vec2::new(
117:             offset.east_metres as f32,
118:             offset.north_metres as f32,
119:         ))
120:         .ok()?;
121:         city.ground
122:             .support
123:             .position(local)
124:             .map(|position| city.frame.world_from_city().transform_point3(position))
