128: impl InstalledCity {
129:     fn covers(&self, state: &MapState) -> bool {
130:         let Some(pose) = state.pose.as_ref() else {
131:             return false;
132:         };
133:         if pose.rect.is_none()
134:             || &pose.source != self.product.document.source()
135:             || state.requested_city() != Some(self.product.document.place())
136:         {
137:             return false;
138:         }
139:         let Some(surface) = state.presented.as_ref() else {
140:             return false;
141:         };
142:         let offset = NativeTerrainCoordinate::from(self.product.document.origin())
143:             .offset_to(surface.request.origin.to_e7().into());
144:         let half = (REGIONAL_TERRAIN_SIDE - 1) as f64
145:             * 0.5
146:             * f64::from(surface.request.scale.spacing_metres());
147:         let frame = NativeTerrainCoordinate::from(self.product.document.origin())
148:             .frame_from(surface.request.origin.to_e7().into());
149:         // Require the entire regional window to fit. The first implementation
150:         // exchanges complete surfaces, avoiding seams between coarse/fine edges.
151:         offset.east_metres.abs() + half * frame.east_scale < f64::from(self.ground.half_extent.x)
152:             && offset.north_metres.abs() + half < f64::from(self.ground.half_extent.y)
153:     }
154: 
155:     fn reanchor(&mut self, world: &mut World, origin: Wgs84CoordinateMicrodegrees) -> Result {
156:         let frame = CityFrame::from_geographic_city(&self.product.document, origin);
157:         if frame == self.frame {
158:             return Ok(());
159:         }
160:         frame.install(world, PresentationOwner::RegionalMap)?;
161:         if let Some(mut transform) = world.get_mut::<Transform>(self.root) {
162:             *transform = Transform::from_matrix(frame.world_from_city());
163:         }
164:         let mut terrain_materials = world.resource_mut::<Assets<TacticalTerrainMaterial>>();
165:         for handle in &self.ground.terrain_materials {
166:             if let Some(mut material) = terrain_materials.get_mut(handle) {
167:                 material.extension.set_geographic_frame(frame);
168:             }
169:         }
170:         let mut materials = world.resource_mut::<Assets<CityGroundMaterial>>();
171:         for handle in &self.ground.paving_materials {
172:             if let Some(mut material) = materials.get_mut(handle) {
173:                 material.extension.set_geographic_frame(frame);
174:             }
175:         }
176:         self.frame = frame;
177:         Ok(())
178:     }
179: }
