181: pub(super) fn sync(world: &mut World) {
182:     world.resource_scope(|world, mut state: Mut<MapState>| {
183:         publish_candidate(world, &mut state.city);
184:         let mut draw_city = state
185:             .city
186:             .installed
187:             .as_ref()
188:             .is_some_and(|city| city.covers(&state));
189:         let origin = state
190:             .presented
191:             .as_ref()
192:             .map(|surface| surface.request.origin);
193:         let replaced = state
194:             .city
195:             .pending
196:             .as_ref()
197:             .is_some_and(|pending| world.get::<CityAssemblyPublished>(pending.root).is_some());
198:         if let (Some(city), Some(origin)) = (state.city.installed.as_mut(), origin) {
199:             // A staged replacement owns its frame once assembly publishes.
200:             // Do not reanchor old ground against the new candidate's buffers.
201:             if replaced {
202:                 draw_city = false;
203:             } else if let Err(error) = city.reanchor(world, origin) {
204:                 warn!(%error, "Could not reanchor map city");
205:                 draw_city = false;
206:             }
207:             if let Some(mut visibility) = world.get_mut::<Visibility>(city.root) {
208:                 *visibility = if draw_city {
209:                     Visibility::Inherited
210:                 } else {
211:                     Visibility::Hidden
212:                 };
213:             }
214:         }
215:         buildings::set_city_visible(world, PresentationOwner::RegionalMap, draw_city);
216:         // Keep the already-settled regional ground underneath while the first
217:         // fine-ground pipelines specialize. Height queries exchange only after
218:         // the candidate has rendered enough settled frames to replace it.
219:         let visible = draw_city && state.city.settled_frames >= SETTLED_CITY_FRAMES;
220:         if let Some(surface) = state.presented.as_ref()
221:             && let SurfaceCoverage::Drawn { entity, .. } = surface.coverage
222:             && let Some(mut visibility) = world.get_mut::<Visibility>(entity)
223:         {
224:             *visibility = if visible {
225:                 Visibility::Hidden
226:             } else {
227:                 Visibility::Inherited
228:             };
229:         }
230:         if state.city.visible != visible {
231:             state.city.visible = visible;
232:             state.settled_frames = 0;
233:         }
234:         if draw_city
235:             && state.city.pending.is_none()
236:             && state.city.installed.is_some()
237:             && crate::presentation::pipeline_readiness::waiting_pipelines() == 0
238:         {
239:             state.city.settled_frames = state
240:                 .city
241:                 .settled_frames
242:                 .saturating_add(1)
243:                 .min(SETTLED_CITY_FRAMES);
244:             if state.city.settled_frames == SETTLED_CITY_FRAMES
245:                 && let Some(status) = &mut state.city.status
246:                 && matches!(status.phase, InstallationPhase::Preparing)
247:             {
248:                 status.phase = InstallationPhase::Ready;
249:             }
250:         } else {
251:             state.city.settled_frames = 0;
252:         }
253:     });
254: }
