11: pub(in crate::presentation::regional_map) fn install(
12:     world: &mut World,
13:     json: &str,
14:     preparation: PreparationTicket,
15: ) {
16:     let result = admit(world, json, preparation);
17:     let retired = {
18:         let mut state = world.resource_mut::<MapState>();
19:         match result {
20:             Ok(Admission::Resident) => {
21:                 state.city.status = Some(InstallationStatus {
22:                     preparation,
23:                     phase: InstallationPhase::Ready,
24:                     error: None,
25:                 });
26:                 None
27:             }
28:             Ok(Admission::Replacement(city)) => {
29:                 let old = state.city.pending.replace(*city);
30:                 state.city.status = Some(InstallationStatus {
31:                     preparation,
32:                     phase: InstallationPhase::Preparing,
33:                     error: None,
34:                 });
35:                 state.city.settled_frames = 0;
36:                 old.map(|old| old.root)
37:             }
38:             Err(error) => {
39:                 state.city.status = Some(InstallationStatus::failed(preparation, error));
40:                 None
41:             }
42:         }
43:     };
44:     if let Some(root) = retired
45:         && let Ok(entity) = world.get_entity_mut(root)
46:     {
47:         entity.despawn();
48:     }
49: }
