91: fn component_index(
92:     part: &Part,
93:     records: &mut Vec<Building>,
94:     components: &mut ComponentTransforms,
95: ) -> AssemblyResult<u32> {
96:     if part.local_transform == Mat4::IDENTITY && part.uv_offset == Vec2::ZERO {
97:         return Ok(0);
98:     }
99:     let key = (
100:         part.local_transform.to_cols_array().map(f32::to_bits),
101:         part.uv_offset.to_array().map(f32::to_bits),
102:     );
103:     if let Some(index) = components.get(&key) {
104:         return Ok(*index);
105:     }
106:     let index = u32::try_from(records.len()).map_err(|_| AssemblyError::ComponentCapacity)?;
107:     if index > u32::MAX >> COMPONENT_INDEX_SHIFT {
108:         return Err(AssemblyError::ComponentCapacity);
109:     }
110:     records.push(Building {
111:         transform: part.local_transform,
112:         bounds: Vec4::ZERO,
113:         levels: UVec4::new(0, COMPONENT_RECORD, 0, 0),
114:         uv_offset: part.uv_offset.extend(0.0).extend(0.0),
115:     });
116:     let component = COMPONENT_FLAG | index << COMPONENT_INDEX_SHIFT;
117:     components.insert(key, component);
118:     Ok(component)
119: }
