85: impl OwnerViews {
86:     fn prepare_views(
87:         &mut self,
88:         scene: &CityGpuScene,
89:         groups: &[(Entity, Vec<Entity>)],
90:         views: &Query<CityView, Without<Camera2d>>,
91:     ) -> Vec<(Entity, u32, u32)> {
92:         let active: HashSet<_> = groups
93:             .iter()
94:             .flat_map(|(_, group)| group.iter())
95:             .filter_map(|entity| views.get(*entity).ok().map(|v| v.view.retained_view_entity))
96:             .collect();
97:         if active.len() > MAX_CITY_VIEWS {
98:             warn!("City level-of-detail history capacity exceeded");
99:             return Vec::new();
100:         }
101:         self.retained_slots.retain(|key, _| active.contains(key));
102:         let mut offsets = Vec::new();
103:         for (root, group) in groups {
104:             let Ok(root_view) = views.get(*root) else {
105:                 continue;
106:             };
107:             for (draw_slot, entity) in group.iter().enumerate() {
108:                 let Ok(item) = views.get(*entity) else {
109:                     continue;
110:                 };
111:                 let view = item.view;
112:                 let previous = self.retained_slots.get(&view.retained_view_entity).copied();
113:                 let Some(history_slot) = previous.or_else(|| {
114:                     (0..MAX_CITY_VIEWS as u32)
115:                         .find(|slot| !self.retained_slots.values().any(|used| used == slot))
116:                 }) else {
117:                     continue;
118:                 };
119:                 self.retained_slots
120:                     .insert(view.retained_view_entity, history_slot);
121:                 self.slots.insert(*entity, draw_slot as u32);
122:                 let clip = view.clip_from_world.unwrap_or_else(|| {
123:                     view.clip_from_view * view.world_from_view.to_matrix().inverse()
124:                 });
125:                 for batch in scene.batches.iter() {
126:                     let offset = self.uniforms.push(&ViewParameters {
127:                         clip_from_world: clip * scene.frame.world_from_city,
128:                         camera: scene
129:                             .frame
130:                             .world_from_city
131:                             .inverse()
132:                             .transform_point3(root_view.view.world_from_view.translation())
133:                             .extend(view.clip_from_view.w_axis.w),
134:                         projection: Vec4::new(
135:                             view.clip_from_view.y_axis.y.abs()
136:                                 * view.viewport.w as f32
137:                                 * 0.5
138:                                 * scene.frame.radius_scale(),
139:                             FACADE_RADIUS_PIXELS,
140:                             DETAIL_RADIUS_PIXELS,
141:                             if previous.is_some() { 1.0 } else { 0.0 },
142:                         ),
143:                         counts: UVec4::new(
144:                             scene.count,
145:                             batch.capacity,
146:                             history_slot,
147:                             draw_slot as u32,
148:                         ),
149:                         // A shadow map needs the enclosure silhouette, not
150:                         // the facade's individual beams and window fittings.
151:                         // Test view role explicitly: orthographic cameras are
152:                         // not shadow views.
153:                         policy: UVec4::new(u32::from(item.shadow), u32::from(root_view.root), 0, 0),
154:                         // Perspective matrices have an infinite far plane.
155:                         // Bevy's camera frustum retains the configured finite
156:                         // distance; shadow caster extrusion must remain separate.
157:                         far_plane: if item.shadow {
158:                             Vec4::ZERO
159:                         } else {
160:                             scene.frame.world_from_city.transpose()
161:                                 * item
162:                                     .frustum
163:                                     .map_or(Vec4::ZERO, |frustum| frustum.half_spaces[5].normal_d())
164:                         },
165:                     });
166:                     offsets.push((*root, offset, draw_slot as u32));
167:                 }
168:             }
169:         }
170:         offsets
171:     }
172: }
