174: impl GpuResources<'_> {
175:     fn prepare_owner(
176:         &self,
177:         owner: PresentationOwner,
178:         scene: &CityGpuScene,
179:         views: &Query<CityView, Without<Camera2d>>,
180:         prepared: &mut OwnerViews,
181:         scratch: &mut scratch::CityScratch,
182:     ) {
183:         prepared.slots.clear();
184:         prepared.dispatches.clear();
185:         prepared.uniforms.clear();
186:         if scene.count == 0 {
187:             *scratch = Default::default();
188:             prepared.retained_slots.clear();
189:             return;
190:         }
191:         let groups = camera_groups(views, owner);
192:         if groups.is_empty() {
193:             return;
194:         }
195:         let slots = groups
196:             .iter()
197:             .map(|(_, group)| group.len())
198:             .max()
199:             .unwrap_or(1);
200:         if !scratch.prepare(
201:             scene,
202:             slots,
203:             self.buffers,
204:             self.device,
205:             self.queue,
206:             self.cache,
207:         ) {
208:             return;
209:         }
210:         let (Some(buildings), Some(selection)) = (
211:             self.buffers.get(&scene.buildings),
212:             self.buffers.get(&scene.selection),
213:         ) else {
214:             return;
215:         };
216:         let offsets = prepared.prepare_views(scene, &groups, views);
217:         prepared.uniforms.write_buffer(self.device, self.queue);
218:         let Some(uniform) = prepared.uniforms.binding() else {
219:             return;
220:         };
221:         let layout = self.cache.get_bind_group_layout(&self.pipelines.layout);
222:         let mut bindings = Vec::new();
223:         for (batch, scratch) in scene.batches.iter().zip(&scratch.batches) {
224:             let (Some(source), Some(owners)) = (
225:                 self.buffers.get(&batch.source),
226:                 self.buffers.get(&batch.owners),
227:             ) else {
228:                 return;
229:             };
230:             bindings.push(self.device.create_bind_group(
231:                 "city GPU buffers",
232:                 &layout,
233:                 &BindGroupEntries::sequential((
234:                     uniform.clone(),
235:                     buildings.buffer.as_entire_binding(),
236:                     selection.buffer.as_entire_binding(),
237:                     source.buffer.as_entire_binding(),
238:                     scratch.visible.as_entire_binding(),
239:                     scratch.indirect.as_entire_binding(),
240:                     owners.buffer.as_entire_binding(),
241:                 )),
242:             ));
243:         }
244:         for (index, (root, offset, slot)) in offsets.into_iter().enumerate() {
245:             let batch = index % bindings.len();
246:             prepared.dispatches.entry(root).or_default().push(Dispatch {
247:                 binding: bindings[batch].clone(),
248:                 view_offset: offset,
249:                 ranges: scene.batches[batch].ranges,
250:                 slot,
251:             });
252:         }
253:     }
254: }
