342:     scenes: Res<CityGpuScenes>,
343:     views: Res<CityViews>,
344:     current: ViewQuery<Entity>,
345:     scratch: Res<scratch::Scratch>,
346: ) {
347:     let (Some(select), Some(compact)) = (
348:         cache.get_compute_pipeline(pipelines.select),
349:         cache.get_compute_pipeline(pipelines.compact),
350:     ) else {
351:         return;
352:     };
353:     let entity = current.into_inner();
354:     for owner in PresentationOwner::ALL {
355:         let scene = scenes.owners.get(owner);
356:         let views = views.owners.get(owner);
357:         let scratch = scratch.owners.get(owner);
358:         let Some(dispatches) = views.dispatches.get(&entity) else {
359:             continue;
360:         };
361:         if dispatches.is_empty() {
362:             continue;
363:         }
364:         // Camera groups execute sequentially. Clear only counters here, in GPU
365:         // command order; queue writes would reset all groups before any draws run.
366:         for (index, dispatch) in dispatches.iter().enumerate() {
367:             let batch = &scratch.batches[index % scene.batches.len()];
368:             context.command_encoder().clear_buffer(
369:                 &batch.indirect,
370:                 u64::from(dispatch.slot) * 16 + 4,
371:                 Some(4),
372:             );
373:         }
374:         {
375:             let mut pass = context
376:                 .command_encoder()
377:                 .begin_compute_pass(&ComputePassDescriptor {
378:                     label: Some("city_building_lod"),
379:                     timestamp_writes: None,
380:                 });
381:             pass.set_pipeline(select);
382:             for dispatch in dispatches.iter().step_by(scene.batches.len()) {
383:                 pass.set_bind_group(0, &dispatch.binding, &[dispatch.view_offset]);
384:                 pass.dispatch_workgroups(scene.count.div_ceil(COMPUTE_WORKGROUP_SIZE), 1, 1);
385:             }
386:         }
387:         let mut pass = context
388:             .command_encoder()
389:             .begin_compute_pass(&ComputePassDescriptor {
390:                 label: Some("city_visible_clusters"),
391:                 timestamp_writes: None,
392:             });
393:         pass.set_pipeline(compact);
394:         for dispatch in dispatches {
395:             pass.set_bind_group(0, &dispatch.binding, &[dispatch.view_offset]);
396:             let workgroups = dispatch.ranges.div_ceil(COMPUTE_WORKGROUP_SIZE);
397:             pass.dispatch_workgroups(
398:                 workgroups.min(WORKGROUPS_PER_ROW),
399:                 workgroups.div_ceil(WORKGROUPS_PER_ROW),
400:                 1,
401:             );
402:         }
403:         READY.get(owner).store(true, Ordering::Relaxed);
404:     }
405: }
406: 
407: fn camera_groups(
408:     views: &Query<CityView, Without<Camera2d>>,
409:     owner: PresentationOwner,
410: ) -> Vec<(Entity, Vec<Entity>)> {
411:     views
412:         .iter()
413:         .filter(|view| {
414:             (view.camera || view.root)
415:                 && view
416:                     .layers
417:                     .cloned()
418:                     .unwrap_or_default()
419:                     .intersects(&owner.render_layers())
420:         })
421:         .map(|view| {
422:             let mut group = vec![view.entity];
423:             if let Some(cascades) = view.cascades {
424:                 group.extend(cascades.lights.iter().copied());
425:             }
426:             group.retain(|entity| views.get(*entity).is_ok());
427:             (view.entity, group)
428:         })
429:         .collect()
430: }

