70: impl MapCommand {
71:     pub(crate) fn apply(self, world: &mut World) {
72:         let command = match self {
73:             Self::InstallCity {
74:                 document_json,
75:                 preparation,
76:             } => {
77:                 city::install(world, &document_json, preparation);
78:                 return;
79:             }
80:             command => command,
81:         };
82:         let mut state = world.resource_mut::<MapState>();
83:         let result = match command {
84:             Self::Open {
85:                 source,
86:                 origin,
87:                 span,
88:                 rect,
89:             } => {
90:                 state.open(source, origin, span, rect);
91:                 Ok(())
92:             }
93:             Self::Resize { rect } => {
94:                 if let Some(pose) = state.pose.as_mut()
95:                     && pose.rect != Some(rect)
96:                 {
97:                     pose.rect = Some(rect);
98:                     state.settled_frames = 0;
99:                 }
100:                 Ok(())
101:             }
102:             Self::Pan { delta } => state.pan(delta),
103:             Self::Zoom { ratio } => state.pose.as_mut().map_or(Ok(()), |pose| {
104:                 if pose.rect.is_some() {
105:                     pose.zoom(ratio)
106:                 } else {
107:                     Ok(())
108:                 }
109:             }),
110:             Self::Rotate { angle } => state.pose.as_mut().map_or(Ok(()), |pose| {
111:                 if pose.rect.is_some() {
112:                     pose.rotate(angle)
113:                 } else {
114:                     Ok(())
115:                 }
116:             }),
117:             Self::Reset => {
118:                 if let Some(pose) = state.pose.as_mut() {
119:                     pose.reset();
120:                 }
121:                 Ok(())
122:             }
123:             Self::FrameRoute => state.frame_route(),
124:             Self::Hide => {
125:                 if let Some(pose) = state.pose.as_mut() {
126:                     pose.rect = None;
127:                 }
128:                 Ok(())
129:             }
130:             Self::InstallCity { .. } => return,
131:             Self::InstallEnvironment { environment } => {
132:                 if state
133:                     .pose
134:                     .as_ref()
135:                     .is_some_and(|pose| pose.source == *environment.terrain().source())
136:                 {
137:                     state.environment = Some(environment);
138:                 }
139:                 Ok(())
140:             }
141:             Self::InstallOverlay { revision, overlay } => {
142:                 if state
143:                     .pose
144:                     .as_ref()
145:                     .is_some_and(|pose| &pose.source == overlay.source())
146:                     && state
147:                         .overlay_revision
148:                         .is_none_or(|current| revision > current)
149:                 {
150:                     state.overlay = Some(overlay);
151:                     state.overlay_revision = Some(revision);
152:                     state.settled_frames = 0;
153:                 }
154:                 Ok(())
155:             }
156:         };
157:         state.failure = result.err();
158:     }
159: }
