676:             CachedPipelineState::Creating(task) => match bevy_tasks::futures::check_ready(task) {
677:                 Some(Ok(pipeline)) => {
678:                     cached_pipeline.state = CachedPipelineState::Ok(pipeline);
679:                     return;
