161:     pub(super) fn observe(&mut self, progress: LoadingProgress, now: Duration) -> RunVerdict {
162:         if progress != self.progress {
163:             self.last_advance = now;
164:         }
165:         self.progress = progress;
166:         let Some(stage) = progress.first_unfinished() else {
167:             self.settled_frames += 1;
168:             return if self.settled_frames >= SETTLED_RENDER_FRAMES {
169:                 RunVerdict::Ready
170:             } else {
171:                 RunVerdict::Waiting
172:             };
173:         };
174:         self.settled_frames = 0;
175:         if now.saturating_sub(self.last_advance) >= STALL_LIMIT {
176:             RunVerdict::Stalled(stage)
177:         } else {
178:             RunVerdict::Waiting
179:         }
180:     }
181: }
