126: /// Recomputes the derived combat hand indexes after an ownership root is
127: /// rebound. Relationship hooks maintain the item list, but changing `ItemOf`
128: /// alone does not rerun the `EquipSlot` hooks that populate these caches.
129: pub fn rebuild_inventory_holding_cache(world: &mut World, root: Entity) {
130:     let mut weapon = None;
131:     let mut shield = None;
132:     let mut query = world.query::<(
133:         Entity,
134:         &ItemOf,
135:         &EquipSlot,
136:         Has<WeaponItem>,
137:         Has<ShieldItem>,
138:     )>();
139:     for (entity, owner, slot, is_weapon, is_shield) in query.iter(world) {
140:         if owner.0 != root || !matches!(slot, EquipSlot::HoldingLeft | EquipSlot::HoldingRight) {
141:             continue;
142:         }
143:         if is_weapon {
144:             weapon = Some(entity);
145:         }
146:         if is_shield {
147:             shield = Some(entity);
148:         }
149:     }
150:     if let Some(mut inventory) = world.get_mut::<InventoryItems>(root) {
151:         inventory.holding_weapon = weapon;
152:         inventory.holding_shield = shield;
153:     }
154: }
