367: fn update_instanced_grass_interaction(
368:     time: Res<Time>,
369:     interactors: Query<&GlobalTransform, With<GrassInteractor>>,
370:     mut state: ResMut<InstancedGrassInteractionState>,
371:     mut materials: ResMut<Assets<TacticalGrassInstancedMaterial>>,
372:     settings: Res<crate::presentation::TacticalGraphicsSettings>,
373: ) {
374:     let Some(position) = interactors.iter().next().map(GlobalTransform::translation) else {
375:         if state.written.take().is_some() {
376:             for (_, material) in materials.iter_mut() {
377:                 material.interaction = Vec4::ZERO;
378:                 material.interaction_motion = Vec4::ZERO;
379:             }
380:         }
381:         state.previous_position = None;
382:         state.smoothed_velocity = Vec3::ZERO;
383:         return;
384:     };
385:     let delta_seconds = time.delta_secs().max(1.0 / 240.0);
386:     let velocity = state
387:         .previous_position
388:         .map(|previous| ((position - previous) / delta_seconds).clamp_length_max(8.0))
389:         .unwrap_or_default();
390:     let response = 1.0 - (-delta_seconds * 10.0).exp();
391:     state.smoothed_velocity = state.smoothed_velocity.lerp(velocity, response);
392:     state.previous_position = Some(position);
393: 
394:     // Idle interactors converge to constants; stop dirtying material assets
395:     // once the written values are close enough that no motion is visible.
396:     if state
397:         .written
398:         .is_some_and(|(written_position, written_velocity)| {
399:             written_position.distance_squared(position) < 1e-6
400:                 && written_velocity.distance_squared(state.smoothed_velocity) < 1e-6
401:         })
402:     {
403:         return;
404:     }
405: 
406:     let speed = state.smoothed_velocity.length();
407:     for (_, material) in materials.iter_mut() {
408:         let interaction = &settings.config.grass.interaction;
409:         material.interaction = position.extend(interaction.radius_m);
410:         material.interaction_motion = Vec4::new(
411:             state.smoothed_velocity.x,
412:             state.smoothed_velocity.y,
413:             state.smoothed_velocity.z,
414:             (interaction.minimum_push + speed * 0.11)
415:                 .clamp(interaction.minimum_push, interaction.maximum_push),
416:         );
417:     }
418:     state.written = Some((position, state.smoothed_velocity));
419: }
