37: pub(super) fn scatter_ground_without_patch(
38:     ground: &SceneGround,
39:     collar: TerrainTransitionCollar,
40: ) -> SceneGround {
41:     let half_size = Vec2::new(ground.width(), ground.depth()) * 0.5;
42:     let mut samples = ground.samples().to_vec();
43:     for z in 0..ground.grid_depth() {
44:         for x in 0..ground.grid_width() {
45:             let point = Vec2::new(x as f32, z as f32) * ground.grid_scale() - half_size;
46:             if adventuresim_tactical_core::scene_coordinates::ScenePlanPoint::try_from(point)
47:                 .is_ok_and(|point| collar.contains(point))
48:             {
49:                 samples[z * ground.grid_width() + x] = GroundSurface {
50:                     substrate: GroundSubstrate::Water,
51:                     cover: GroundCover::Bare,
52:                     cover_density_bps: 0,
53:                     cover_height_cm: 0,
54:                 };
55:             }
56:         }
57:     }
58:     let mut masked = SceneGround::from_samples(
59:         ground.grid_width(),
60:         ground.grid_depth(),
61:         ground.grid_scale(),
62:         samples,
63:     )
64:     .expect("masking scatter preserves the validated ground grid");
65:     masked.urban = ground.urban.clone();
66:     masked
67: }
