37: // The presentation facade is compiled into several binaries, while only the
38: // deterministic scene viewer consumes this review-specimen helper.
39: pub(crate) fn oak_review_terminal_specimen(
40:     root: adventuresim_tactical_core::scene_coordinates::ScenePlanPoint,
41:     canopy_bps: u16,
42: ) -> (Mesh, Mesh, Mesh, Mesh, Vec3, Vec3) {
43:     let seed = obstacle_seed(root);
44:     let variant_seed = crate::presentation::obstacles::tree::specimen::oak_variant_seed(
45:         StreamId::new("visual.tree.preview-variant")
46:             .rng(seed, &[])
47:             .index(4),
48:     );
49:     let branches = procedural_tree_skeleton(variant_seed, canopy_competition(canopy_bps));
50:     let competition = canopy_competition(canopy_bps);
51:     let leaves = procedural_oak_leaves(variant_seed, &branches, competition);
52:     let camera_direction = Vec3::new(1.0, 0.0, 1.0).normalize();
53:     let preferred_height = 2.5;
54:     let (shoot_id, shoot) = branches
55:         .iter()
56:         .filter_map(|branch| branch.foliage.map(|identity| (identity, branch)))
57:         .max_by(|(_, left), (_, right)| {
58:             let score = |branch: &TreeBranchSegment| {
59:                 branch.end.dot(camera_direction) - (branch.end.y - preferred_height).abs() * 0.35
60:             };
61:             score(left).total_cmp(&score(right))
62:         })
63:         .map(|(identity, branch)| (identity, *branch))
64:         .expect("procedural oak has terminal shoots");
65:     let offset = -shoot.start;
66:     let mut specimen_shoot = shoot;
67:     specimen_shoot.start += offset;
68:     specimen_shoot.end += offset;
69:     let specimen_leaves = leaves
70:         .iter()
71:         .filter(|leaf| leaf.shoot_id == shoot_id)
72:         .copied()
73:         .map(|mut leaf| {
74:             leaf.petiole_start += offset;
75:             leaf.center += offset;
76:             leaf
77:         })
78:         .collect::<Vec<_>>();
79:     // Frame the entire biological unit, not merely the leaf centroid: the
80:     // parent junction and terminal bud are both required to judge shoot
81:     // phyllotaxy. Blade length is included as a conservative bound because
82:     // leaves can tilt substantially out of the shoot's local frame.
83:     let mut minimum = specimen_shoot.start.min(specimen_shoot.end);
84:     let mut maximum = specimen_shoot.start.max(specimen_shoot.end);
85:     for leaf in &specimen_leaves {
86:         let extent = Vec3::splat(leaf.length.max(leaf.width) * 0.6);
87:         minimum = minimum.min(leaf.center - extent);
88:         maximum = maximum.max(leaf.center + extent);
89:     }
90:     let focus = (minimum + maximum) * 0.5;
91:     let shoot_direction = (specimen_shoot.end - specimen_shoot.start).normalize();
92:     let mut review_direction = Vec3::Z;
93:     let mut review_score = f32::NEG_INFINITY;
94:     for elevation in [-0.2_f32, 0.1, 0.35] {
95:         for azimuth_index in 0..24 {
96:             let azimuth = azimuth_index as f32 * core::f32::consts::TAU / 24.0;
97:             let candidate = Vec3::new(
98:                 azimuth.cos() * elevation.cos(),
99:                 elevation.sin(),
100:                 azimuth.sin() * elevation.cos(),
101:             );
102:             let face_area = specimen_leaves
103:                 .iter()
104:                 .map(|leaf| leaf.right.cross(leaf.up).normalize().dot(candidate).abs())
105:                 .sum::<f32>();
106:             let axial_penalty =
107:                 shoot_direction.dot(candidate).abs() * specimen_leaves.len() as f32 * 0.55;
108:             let score = face_area - axial_penalty;
109:             if score > review_score {
110:                 review_score = score;
111:                 review_direction = candidate;
112:             }
113:         }
114:     }
115:     (
116:         procedural_tree_branch_mesh(&[specimen_shoot], 3),
117:         procedural_oak_textured_leaf_mesh(&specimen_leaves),
118:         procedural_oak_leaf_card_mesh(&specimen_leaves),
119:         procedural_oak_bud_mesh(&[specimen_shoot]),
120:         focus,
121:         review_direction,
122:     )
123: }
