pub(super) fn install(app: &mut App) {
    app.init_resource::<SceneAssetsReady>()
        .init_resource::<SceneInstallationReady>()
        .init_resource::<SceneAssetFailure>()
        .add_systems(
            Last,
            (
                capture_asset_failures,
                update_status,
                super::render_diagnostics::census,
            )
                .chain(),
        );
}

