    diagnostics: Res<DiagnosticsStore>,
    player: Single<(Ref<Transform>, &CharacterId), With<ClientPlayer>>,
    mut spans: ParamSet<(
        Single<&mut TextSpan, With<PositionSpan>>,
        Single<&mut TextSpan, With<FpsSpan>>,
