42:                         base_seed,
43:                         &[species.index() as u64, lod.tier_index() as u64],
44:                     ),
45:                     grass,
46:                 ),
47:             );
48:             let metadata = culling::metadata(
49:                 meshes.get(&mesh).expect("generated tuft"),
50:                 lod.width_compensation(pigment.density),
51:                 pigment.wind_scale,
52:                 grass.interaction.maximum_push,
53:             );
54:             let mut entity = commands.spawn((
55:                 Name::new(format!(
56:                     "{label} {species:?} {lod:?} tufts ({})",
57:                     instances.len()
58:                 )),
59:                 GroundScatterLayer::Grass,
60:                 triangle_count,
61:                 GpuCullCompute,
62:                 // Batches span the whole scene, so CPU frustum culling can
63:                 // only ever hide them wholesale - and worse, a culled frame
64:                 // drops the batch from `RenderMeshInstances`, which makes
65:                 // eidolon free and re-upload the retained instance buffers
66:                 // every time the camera pitch crosses the horizon. Culling
