63: struct ChunkDraw<'a, M: ChunkInstancedMaterial> {
64:     render_entity: Entity,
65:     main_entity: MainEntity,
66:     material: &'a Handle<M>,
67: }
68: 
69: impl<M> Default for QueuedChunks<M> {
70:     fn default() -> Self {
71:         Self {
72:             views: HashMap::new(),
73:             material: PhantomData,
74:         }
75:     }
