78: impl<M: ChunkInstancedMaterial> ChunkDraw<'_, M> {
79:     /// Bins the chunk into `phase` once its pipeline has compiled.
80:     fn bin(
81:         self,
82:         phase: &mut BinnedRenderPhase<Opaque3d>,
83:         view_key: MeshPipelineKey,
84:         pipelines: &mut ChunkPipelines<'_, M>,
85:         assets: &ChunkAssets<'_, M>,
86:     ) -> bool {
87:         let Some(prepared) = assets.materials.get(self.material) else {
88:             return false;
89:         };
90:         let Some(mesh_id) = assets
91:             .mesh_instances
92:             .render_mesh_queue_data(self.main_entity)
93:             .map(|instance| instance.mesh_asset_id())
94:         else {
95:             return false;
96:         };
97:         let (Some(mesh), Some(slabs)) = (
98:             assets.meshes.get(mesh_id),
99:             assets.mesh_allocator.mesh_slabs(&mesh_id),
100:         ) else {
101:             return false;
102:         };
103:         if slabs.index_slab_id.is_none() {
104:             return false;
105:         }
106:         let key = ChunkPipelineKey::<M> {
107:             mesh_key: view_key
108:                 | MeshPipelineKey::from_primitive_topology_and_strip_index(
109:                     mesh.primitive_topology(),
110:                     mesh.index_format(),
111:                 ),
112:             material_key: prepared.key.clone(),
113:         };
114:         let Some(pipeline) = pipelines
115:             .specialized
116:             .specialize(&pipelines.cache, &pipelines.pipeline, key, &mesh.layout)
117:             .inspect_err(|error| error!("chunk-instanced pipeline: {error}"))
118:             .ok()
119:             .filter(|id| ready(*id, &pipelines.cache))
120:         else {
121:             return false;
122:         };
123:         phase.add(
124:             Opaque3dBatchSetKey {
125:                 pipeline,
126:                 draw_function: prepared.draw_main,
127:                 material_bind_group_index: Some(material_bind_group_index(self.material)),
128:                 slabs: MeshSlabs {
129:                     vertex_slab_id: slabs.vertex_slab_id,
130:                     index_slab_id: slabs.index_slab_id,
131:                     ..default()
132:                 },
133:                 lightmap_slab: None,
134:             },
135:             Opaque3dBinKey {
136:                 asset_id: mesh_id.into(),
137:             },
138:             (self.render_entity, self.main_entity),
139:             InputUniformIndex(0),
140:             BinnedRenderPhaseType::UnbatchableMesh,
141:         );
142:         true
143:     }
144: }
145: 
146: pub(super) fn queue_chunks<M: ChunkInstancedMaterial>(
147:     mut pipelines: ChunkPipelines<M>,
148:     assets: ChunkAssets<M>,
149:     chunks: Query<(Entity, &MainEntity, &ChunkMaterial<M>), With<ChunkGpu>>,
150:     mut phases: ResMut<ViewBinnedRenderPhases<Opaque3d>>,
151:     views: Query<(&ExtractedView, &RenderVisibleEntities)>,
152:     view_key_cache: Res<ViewKeyCache>,
153:     mut queued: ResMut<QueuedChunks<M>>,
154: ) {
155:     for (view, visible) in &views {
156:         let retained = view.retained_view_entity;
157:         let (Some(phase), Some(&view_key), Some(visible)) = (
158:             phases.get_mut(&retained),
159:             view_key_cache.get(&retained),
160:             visible.get::<Mesh3d>(),
161:         ) else {
162:             continue;
163:         };
164:         let previously = queued.views.remove(&retained).unwrap_or_default();
165:         let mut now = HashSet::new();
166:         for (render_entity, &main_entity, material) in &chunks {
167:             // Bevy's own material queue dequeues every visible mesh it did
168:             // not specialize, so a chunk is re-binned every frame it shows.
169:             phase.remove(main_entity);
170:             let is_visible = visible
171:                 .entities_cpu_culling
172:                 .binary_search_by_key(&main_entity, |(_, visible)| *visible)
173:                 .is_ok();
174:             let draw = ChunkDraw {
175:                 render_entity,
176:                 main_entity,
177:                 material: &material.0,
178:             };
179:             if is_visible && draw.bin(phase, view_key, &mut pipelines, &assets) {
180:                 now.insert(main_entity);
181:             }
182:         }
183:         // Chunks despawned since the last frame are no longer in the query.
184:         for gone in previously.difference(&now) {
185:             phase.remove(*gone);
186:         }
187:         queued.views.insert(retained, now);
188:     }
189: }
190: 
191: /// Whether the specialized pipeline has finished compiling.
192: fn ready(id: CachedRenderPipelineId, pipeline_cache: &PipelineCache) -> bool {
193:     pipeline_cache.get_render_pipeline(id).is_some()
194: }
195: 
196: /// Bins chunks that share a material together.
197: fn material_bind_group_index<M: ChunkInstancedMaterial>(material: &Handle<M>) -> u32 {
198:     let mut hasher = DefaultHasher::new();
199:     material.id().hash(&mut hasher);
200:     hasher.finish() as u32
201: }

