410: pub(super) fn update_pose_buffers(
411:     mut commands: Commands,
412:     time: Res<Time>,
413:     procedural_clock: Res<ProceduralAnimationClock>,
414:     catalog: Res<AnimationPackCatalog>,
415:     clips: Res<Assets<AnimationClip>>,
416:     cameras: visibility::AnimationViews,
417:     terrain: Query<&SceneTerrain>,
418:     terrain_ik_enabled: Res<TerrainIkMode>,
419:     owners: Query<(
420:         Entity,
421:         &PresentedSkeleton,
422:         &AnimationPlayback,
423:         &GlobalTransform,
424:         Option<&mut PoseBufferRig>,
425:         Option<&RenderLayers>,
426:     )>,
427:     rig_scenes: Query<(&AnimationRigScene, &Transform)>,
428:     targets: Query<(
429:         Entity,
430:         &AnimationTargetId,
431:         &AuthoredBindTransform,
432:         Option<&AuthoredRigJoint>,
433:         Option<&ChildOf>,
434:     )>,
435:     transforms: Query<&Transform>,
436:     proportion_offsets: Query<&skeletal_proportions::SkeletalJointOffset>,
437:     mut definitions: ResMut<RigDefinitions>,
438:     mut bank: ResMut<BakedClipBank>,
439:     mut metrics: ResMut<PoseBufferMetrics>,
440: ) {
441:     let _spike = crate::animation::diagnostics::SpikeGuard::new("update_pose_buffers");
442:     metrics.culled_character_count = 0;
443: 
444:     for (owner, skeleton, playback, owner_transform, rig, layers) in owners {
445:         let family = catalog
446:             .packs
447:             .get(&skeleton.animation_pack)
448:             .map(|pack| pack.skeleton_family.clone())
449:             .unwrap_or(SkeletonFamily::HUMANOID);
450:         let mut rig = if let Some(rig) = rig {
451:             rig
452:         } else {
453:             let Some(pose_rig) = definitions.bind(owner, family, &targets, &transforms) else {
454:                 continue;
455:             };
456:             commands.entity(owner).insert(pose_rig);
457:             continue;
458:         };
459: 
460:         let delta_seconds = match rig.begin_observation(&procedural_clock, &time) {
461:             Ok(Some(elapsed)) => elapsed,
462:             Ok(None) => continue,
463:             Err(error) => {
464:                 warn!(%error, "Rejected pose-buffer interval");
465:                 continue;
466:             }
467:         };
468: 
469:         if rig.ownership == PoseOwnership::Physics {
470:             // The ragdoll readback owns `previous`/`next`; a culled or
471:             // resampled buffer here would drag driven bones off their
472:             // bodies.
473:             if rig.visibility == PoseVisibility::Frozen {
474:                 commands.entity(owner).remove::<pose_cull::PoseCulled>();
475:             }
476:             rig.visibility = PoseVisibility::Visible;
477:             continue;
478:         }
479: 
480:         let position = owner_transform.translation();
481:         // Initialize retained models before culling so first selection has a pose.
482:         let culled =
483:             rig.has_presented_pose() && visibility::outside_views(position, layers, &cameras);
484:         if pose_cull::cull_pose_rig(&mut rig, owner, culled, &mut commands, &mut metrics) {
485:             continue;
486:         }
487: 
488:         let key = PosePlanKey::from_playback(playback);
489:         let transition = !rig.has_presented_pose() || rig.plan.as_ref() != Some(&key);
490:         rig.sample_accumulator = match rig.sample_accumulator.checked_add(delta_seconds) {
491:             Ok(elapsed) => elapsed,
492:             Err(error) => {
493:                 warn!(%error, "Rejected pose-buffer accumulator");
494:                 continue;
495:             }
496:         };
497:         let Some(mut sampled) = sample_character_plan(
498:             playback,
499:             &rig,
500:             &clips,
501:             &mut bank,
502:             &mut metrics,
503:             &proportion_offsets,
504:         ) else {
505:             continue;
506:         };
507:         let locomotion_ik_owns = procedural::authored_locomotion_ik_owns(skeleton);
508:         let terrain = (terrain_ik_enabled.is_enabled() && locomotion_ik_owns)
509:             .then(|| terrain.single().ok())
510:             .flatten();
511:         if terrain.is_some() || sampled.locomotion_pelvis_rotation.is_some() {
512:             let definition = Arc::clone(&rig.definition);
513:             // Buffered joint poses are relative to the authored scene, not to
514:             // the controller entity. The scene is translated from the
515:             // capsule's centre to the character's visual ground origin.
516:             // Omitting that transform makes every sampled ankle appear about
517:             // one capsule half-height too high and disables terrain contact.
518:             let presentation_transform = rig_scenes
519:                 .iter()
520:                 .find_map(|(scene, local)| {
521:                     (scene.0 == owner).then(|| presentation_world_transform(owner_transform, local))
522:                 })
523:                 .unwrap_or(*owner_transform);
524:             conform_upcoming_pose_to_terrain(
525:                 &definition,
575:             if direct_sampling {
576:                 // The semantic curve supplies the continuous target. Preserve
577:                 // transition inertialization, but do not quantize its normal
578:                 // updates through the authored-clip sampling accumulator.
579:                 rig.previous.clone_from(&target);
580:                 rig.next = target;
581:                 rig.sample_accumulator = AnimationElapsed::ZERO;
582:                 rig.interpolation_alpha = PoseInterpolation::ONE;
583:                 rig.set_target_velocities(&target_velocities);
584:             } else {
585:                 // Terrain IK already owns `next`; interpolate the two solved
586:                 // samples without introducing another contact transition.
587:                 if let Err(error) = rig.advance_buffered_sample(target, pose_sample_interval()) {
588:                     warn!(%error, "Rejected pose-buffer sample clock");
589:                     continue;
590:                 }
591:             }
592:         }
593:     }
594: }
