596: pub(super) fn apply_pose_buffers(
597:     mut rigs: Query<&mut PoseBufferRig>,
598:     mut transforms: Query<&mut Transform, Without<PoseBufferRig>>,
599: ) {
600:     let _spike = crate::animation::diagnostics::SpikeGuard::new("apply_pose_buffers");
601:     for mut rig in &mut rigs {
602:         if !rig.has_presented_pose() || rig.visibility == PoseVisibility::Frozen {
603:             continue;
604:         }
605:         let alpha = rig.interpolation_alpha.amount();
606:         let delta_seconds = rig.decay_delta_seconds;
607:         let rig = &mut *rig;
608:         for joint in rig.entities.ordinals() {
609:             let Some(entity) = rig.entities[joint] else {
610:                 continue;
611:             };
612:             let input = rig.previous[joint].interpolate(rig.next[joint], alpha);
613:             let pose = if rig.inertial_state == InertialState::Settled {
614:                 input
615:             } else if !delta_seconds.is_zero() {
616:                 match rig.offsets[joint].update(input, delta_seconds) {
617:                     Ok(pose) => pose,
618:                     Err(error) => {
619:                         warn!(%error, "Rejected pose inertialization clock");
620:                         continue;
621:                     }
622:                 }
623:             } else {
624:                 rig.offsets[joint].peek(input)
625:             };
626:             if let Ok(mut transform) = transforms.get_mut(entity) {
627:                 transform.translation = pose.translation;
628:                 transform.rotation = pose.rotation;
629:                 transform.scale = pose.scale;
630:             }
631:         }
632:         // Once every quintic has run its full length the offsets are exactly
633:         // zero; clear them so at-rest rigs skip the decay entirely.
634:         if rig.inertial_state != InertialState::Settled
635:             && rig.offsets.iter().all(JointInertialOffset::done)
636:         {
637:             rig.inertial_state = InertialState::Settled;
638:             rig.offsets.fill(JointInertialOffset::default());
639:         }
640:     }

