1: //! Frustum culling of whole trees at the obstacle root.
2: //!
3: //! Every LOD child carries its own `Aabb` and a `VisibilityRange` whose fade
4: //! margins drive the dithered crossfade, so `check_visibility_cpu_culling`
5: //! spends a range lookup and two frustum tests on each of them - and one mature
6: //! tree resolves to a trunk pair plus an entity per crown cluster per leaf
7: //! representation. Hiding the root instead lets that system reject the whole
8: //! subtree on its opening `InheritedVisibility` check, before any of that work.
9: //!
10: //! This deliberately does not mark the children `NoCpuCulling`: that component
11: //! also removes them from `check_visibility_ranges`, which is what selects the
12: //! LOD, so every representation would render at once. Trees in view keep the
13: //! unchanged pipeline; only trees the camera cannot see get cheaper.
14: 
15: use bevy::camera::primitives::{Frustum, Sphere};
16: use bevy::prelude::*;
17: 
18: use super::presentation::StreamedTreePresentation;
19: use crate::presentation::TacticalGameplayCamera;
20: 
21: /// Radius about the obstacle origin that bounds any authored tree.
22: ///
23: /// The tallest species stands 16 m with a 6 m crown radius, so a sphere at the
24: /// base needs about 17 m; the margin beyond that absorbs per-instance scale.
25: /// Erring large costs a few off-screen trees their saving rather than popping a
26: /// crown at the edge of the frustum.
27: const TREE_BOUNDING_RADIUS_METRES: f32 = 24.0;
28: 
29: pub(in crate::presentation) fn cull_tree_roots(
30:     camera: Option<Single<&Frustum, With<TacticalGameplayCamera>>>,
31:     mut trees: Query<(&GlobalTransform, &mut Visibility), With<StreamedTreePresentation>>,
32: ) {
33:     let Some(frustum) = camera else {
34:         return;
35:     };
36:     for (transform, mut visibility) in &mut trees {
37:         let bounds = Sphere {
38:             center: transform.translation().into(),
39:             radius: TREE_BOUNDING_RADIUS_METRES,
40:         };
41:         let desired = if frustum.intersects_sphere(&bounds, false) {
42:             Visibility::Inherited
43:         } else {
44:             Visibility::Hidden
45:         };
46:         // Writing unconditionally would re-dirty every tree each frame and make
47:         // the propagation pass walk subtrees that did not change.
48:         if *visibility != desired {
49:             *visibility = desired;
50:         }
51:     }
52: }

