73: fn weather_occlusion_tree_signature(
74:     scene: Entity,
75:     trees: &Query<(&GlobalTransform, &StreamedTreePresentation)>,
76: ) -> u64 {
77:     let mut records = Vec::new();
78:     for (transform, presentation) in trees {
79:         let translation = transform.translation();
80:         let mut record = [0; 20];
81:         record[..8].copy_from_slice(&presentation.weather_occlusion_cache_key().to_le_bytes());
82:         record[8..12].copy_from_slice(&translation.x.to_bits().to_le_bytes());
83:         record[12..16].copy_from_slice(&translation.y.to_bits().to_le_bytes());
84:         record[16..].copy_from_slice(&translation.z.to_bits().to_le_bytes());
85:         records.push(record);
86:     }
87:     records.sort_unstable();
88:     let fields = records.iter().map(<[u8; 20]>::as_slice).collect::<Vec<_>>();
89:     fabelgeist_determinism::Seed::derive(
90:         &scene.to_bits().to_le_bytes(),
91:         StreamId::new("visual.weather.occlusion-signature"),
92:         &fields,
93:     )
94:     .to_u64()
95: }
