100:     trees: &Query<(&GlobalTransform, &StreamedTreePresentation)>,
101:     tree_cache: &TreePresentationCache,
102: ) -> GeometryResult<Image> {
103:     let pixel_count = WEATHER_OCCLUSION_RESOLUTION as usize * WEATHER_OCCLUSION_RESOLUTION as usize;
104:     let mut shelter_heights = vec![None; pixel_count];
105:     for (transform, presentation) in trees {
106:         let Some(branches) =
107:             tree_cache.weather_occlusion_branches(presentation.weather_occlusion_cache_key())
108:         else {
109:             continue;
110:         };
111:         for branch in branches.iter().filter(|branch| branch.depth <= 2) {
112:             rasterize_weather_branch(&mut shelter_heights, terrain, transform, branch)?;
113:         }
114:     }
115: 
116:     let minimum = bounds.minimum().metres() - 2.0;
117:     let range = PositiveLength::from_metres(bounds.maximum().metres() + 24.0 - minimum)?.metres();
118:     let mut pixels = vec![0; pixel_count * 4];
119:     for (index, height) in shelter_heights.into_iter().enumerate() {
120:         let Some(height) = height else {
121:             continue;
122:         };
123:         let encoded =
124:             (((height.metres() - minimum) / range).clamp(0.0, 1.0) * 65_535.0).round() as u16;
125:         pixels[index * 4] = (encoded & 0xff) as u8;
126:         pixels[index * 4 + 1] = (encoded >> 8) as u8;
127:         pixels[index * 4 + 3] = 255;
128:     }
129:     Ok(Image::new(
130:         Extent3d {
131:             width: WEATHER_OCCLUSION_RESOLUTION,
132:             height: WEATHER_OCCLUSION_RESOLUTION,
133:             depth_or_array_layers: 1,
134:         },
135:         TextureDimension::D2,
136:         pixels,
137:         TextureFormat::Rgba8Unorm,
138:         RenderAssetUsages::RENDER_WORLD,
139:     ))
140: }
141: 
142: fn rasterize_weather_branch(
143:     shelter_heights: &mut [Option<Elevation<Scene>>],
144:     terrain: &SceneTerrain,
145:     transform: &GlobalTransform,
146:     branch: &TreeBranchSegment,
147: ) -> GeometryResult<()> {
148:     let start = transform.transform_point(branch.start);
149:     let end = transform.transform_point(branch.end);
150:     let scale = transform
151:         .to_scale_rotation_translation()
152:         .0
153:         .abs()
154:         .max_element();
155:     let start_radius = branch.start_radius * scale;
156:     let end_radius = branch.end_radius * scale;
157:     let cell_width = terrain.width() / WEATHER_OCCLUSION_RESOLUTION as f32;
158:     let cell_depth = terrain.depth() / WEATHER_OCCLUSION_RESOLUTION as f32;
159:     let footprint_margin = start_radius.max(end_radius) + cell_width.hypot(cell_depth) * 0.5;
160:     let minimum = start.xz().min(end.xz()) - Vec2::splat(footprint_margin);
161:     let maximum = start.xz().max(end.xz()) + Vec2::splat(footprint_margin);
162:     let to_texel = |value: f32, half_extent: f32, span: f32| {
163:         (((value + half_extent) / span) * WEATHER_OCCLUSION_RESOLUTION as f32).floor() as i32
164:     };
165:     let min_x = to_texel(minimum.x, terrain.width() * 0.5, terrain.width())
166:         .clamp(0, WEATHER_OCCLUSION_RESOLUTION as i32 - 1);
167:     let max_x = to_texel(maximum.x, terrain.width() * 0.5, terrain.width())
168:         .clamp(0, WEATHER_OCCLUSION_RESOLUTION as i32 - 1);
169:     let min_z = to_texel(minimum.y, terrain.depth() * 0.5, terrain.depth())
170:         .clamp(0, WEATHER_OCCLUSION_RESOLUTION as i32 - 1);
171:     let max_z = to_texel(maximum.y, terrain.depth() * 0.5, terrain.depth())
172:         .clamp(0, WEATHER_OCCLUSION_RESOLUTION as i32 - 1);
173:     if min_x > max_x || min_z > max_z {
174:         return Ok(());
175:     }
176: 
177:     let axis = end.xz() - start.xz();
178:     let axis_length_squared = axis.length_squared();
179:     let half_diagonal = cell_width.hypot(cell_depth) * 0.5;
180:     for z in min_z..=max_z {
181:         for x in min_x..=max_x {
182:             let point = Vec2::new(
183:                 (x as f32 + 0.5) * cell_width - terrain.width() * 0.5,
184:                 (z as f32 + 0.5) * cell_depth - terrain.depth() * 0.5,
185:             );
186:             let along = if axis_length_squared > 0.000_001 {
187:                 ((point - start.xz()).dot(axis) / axis_length_squared).clamp(0.0, 1.0)
188:             } else {
189:                 0.0
190:             };
191:             let centre = start.xz() + axis * along;
192:             let radius = start_radius + (end_radius - start_radius) * along;
193:             if point.distance_squared(centre) > (radius + half_diagonal).powi(2) {
194:                 continue;
195:             }
196:             let shelter_height =
197:                 Elevation::from_metres(start.y + (end.y - start.y) * along + radius)?;
198:             let index = z as usize * WEATHER_OCCLUSION_RESOLUTION as usize + x as usize;
199:             shelter_heights[index] = Some(
200:                 shelter_heights[index]
201:                     .map_or(shelter_height, |previous| previous.max(shelter_height)),
202:             );
203:         }
204:     }
205:     Ok(())
206: }
