1: // Fast-shaded loose-stone pebble meshes (hero and near LODs).
2: //
3: // The pebble patch meshes previously rendered through a full StandardMaterial
4: // PBR path: image-based lighting, specular, and Fresnel evaluated per fragment
5: // for 3-8 cm rocks that carpet the foreground. This material keeps the shared
6: // patch meshes and their automatic batching but swaps the fragment path for the
7: // same cheap model the distant grass tiers use - flat ambient plus a Lambert
8: // term with one clamped cascade fetch. Directional diffuse matches the PBR
9: // tier's Lambert/pi normalisation exactly (no diffuse transmission on solid
10: // rock), so the swap is energy-neutral on the lit face; `surface.w` scales the
11: // flat ambient in place of the skipped sky IBL.
12: 
13: #import bevy_pbr::{
14:     forward_io::{Vertex, VertexOutput},
15:     mesh_functions,
16:     mesh_view_bindings::{lights, view},
17:     pbr_functions,
18:     shadows,
19:     view_transformations::position_world_to_clip,
20: }
21: 
22: struct TacticalPebbleMaterial {
23:     // Linear albedo in rgb, flat-ambient scale in w.
24:     surface: vec4<f32>,
25: }
26: 
27: @group(#{MATERIAL_BIND_GROUP}) @binding(0)
28: var<uniform> pebble: TacticalPebbleMaterial;
29: 
30: @vertex
31: fn vertex(vertex: Vertex) -> VertexOutput {
32:     var out: VertexOutput;
33:     let world_from_local = mesh_functions::get_world_from_local(vertex.instance_index);
34:     let world_position = mesh_functions::mesh_position_local_to_world(
35:         world_from_local,
36:         vec4<f32>(vertex.position, 1.0),
37:     );
38:     out.world_position = world_position;
39:     out.position = position_world_to_clip(world_position.xyz);
40:     out.world_normal = normalize(mesh_functions::mesh_normal_local_to_world(
41:         vertex.normal,
42:         vertex.instance_index,
43:     ));
44:     out.uv = vertex.uv;
45: #ifdef VERTEX_OUTPUT_INSTANCE_INDEX
46:     out.instance_index = vertex.instance_index;
47: #endif
48: #ifdef VISIBILITY_RANGE_DITHER
49:     out.visibility_range_dither = mesh_functions::get_visibility_range_dither_level(
50:         vertex.instance_index,
51:         world_from_local[3],
52:     );
53: #endif
54:     return out;
55: }
56: 
57: @fragment
58: fn fragment(in: VertexOutput, @builtin(front_facing) is_front: bool) -> @location(0) vec4<f32> {
59: #ifdef VISIBILITY_RANGE_DITHER
60:     pbr_functions::visibility_range_dither(in.position, in.visibility_range_dither);
61: #endif
62:     let normal = normalize(select(-in.world_normal, in.world_normal, is_front));
63:     let albedo = pebble.surface.rgb;
64: 
65:     var lit = albedo * lights.ambient_color.rgb * pebble.surface.w;
66:     let view_z = dot(vec4<f32>(
67:         view.view_from_world[0].z,
68:         view.view_from_world[1].z,
69:         view.view_from_world[2].z,
70:         view.view_from_world[3].z,
71:     ), in.world_position);
72:     for (var light_index = 0u; light_index < lights.n_directional_lights; light_index += 1u) {
73:         let light = lights.directional_lights[light_index];
74:         let n_dot_l = saturate(dot(normal, light.direction_to_light));
75:         let shadow = clamp(
76:             shadows::fetch_directional_shadow(
77:                 light_index,
78:                 in.world_position,
79:                 normal,
80:                 view_z,
81:                 in.position.xy,
82:             ),
83:             0.12,
84:             1.0,
85:         );
86:         lit += albedo * light.color.rgb * (n_dot_l * shadow * 0.3183099);
87:     }
88: 
89:     return vec4<f32>(lit * view.exposure, 1.0);
90: }

