1: //! Chunk-instanced batches for loose-stone pebble patches.
2: //!
3: //! The per-entity renderer spawned two or three entities for every qualifying
4: //! ground sample - one per square metre over the whole playable scene. These
5: //! batches carry the same placements as `ChunkInstance`s instead, so the ECS
6: //! holds one entity per (patch mesh, LOD, ground cell) rather than tens of
7: //! thousands.
8: 
9: use bevy::prelude::{Commands, Handle, Mesh, Name};
10: 
11: use super::{
12:     LooseStonePebblePatch, MESH_VARIANTS, PEBBLE_BATCH_FOOTPRINT_METRES, PebbleMeshLod,
13:     TacticalPebbleBillboardMaterial, TacticalPebbleMaterial, pebble_lod_visibility,
14: };
15: use crate::presentation::{
16:     chunk_instancing::{ChunkInstance, ChunkInstancedMaterial, ChunkSize, FadeBand, InstanceBatch},
17:     ground_scatter::{GroundScatterLayer, instanced_grass::ground_scatter_reach},
18: };
19: 
20: /// Pebbles reach at most ~180 m as billboards; the dense hero and near bands
21: /// end within 24 m, so mid-sized cells keep their culling tight.
22: const PEBBLE_CHUNK_SIZE: ChunkSize = ChunkSize(24.0);
23: 
24: /// The shared meshes and materials every pebble batch draws from.
25: pub(super) struct PebbleBatchAssets<'a> {
26:     pub(super) hero: &'a [Handle<Mesh>],
27:     pub(super) near: &'a [Handle<Mesh>],
28:     pub(super) billboard: &'a [Handle<Mesh>],
29:     pub(super) pebble_counts: &'a [usize],
30:     pub(super) stone: Handle<TacticalPebbleMaterial>,
31:     pub(super) woodland_stone: Handle<TacticalPebbleMaterial>,
32:     pub(super) billboard_material: Handle<TacticalPebbleBillboardMaterial>,
33: }
34: 
35: /// One LOD of one patch variant.
36: struct PebbleBatch<M: ChunkInstancedMaterial> {
37:     name: &'static str,
38:     mesh: Handle<Mesh>,
39:     material: Handle<M>,
40:     lod: PebbleMeshLod,
41:     /// Pebbles per placed patch, or zero for LODs that must not be counted.
42:     pebbles_per_patch: usize,
43: }
44: 
45: pub(super) fn spawn(
46:     commands: &mut Commands<'_, '_>,
47:     assets: PebbleBatchAssets<'_>,
48:     per_variant: Vec<Vec<ChunkInstance>>,
49: ) {
50:     for (variant, instances) in per_variant.into_iter().enumerate() {
51:         if instances.is_empty() {
52:             continue;
53:         }
54:         let woodland = variant < MESH_VARIANTS as usize;
55:         let stone = if woodland {
56:             assets.woodland_stone.clone()
57:         } else {
58:             assets.stone.clone()
59:         };
60:         // Only the hero batch reports a pebble count: the three LODs draw the
61:         // same placements, so summing all of them would treble the scene total
62:         // the review viewer reads back.
63:         PebbleBatch {
64:             name: if woodland {
65:                 "Instanced woodland hero pebble patches"
66:             } else {
67:                 "Instanced loose-stone hero pebble patches"
68:             },
69:             mesh: assets.hero[variant].clone(),
70:             material: stone.clone(),
71:             lod: PebbleMeshLod::Hero,
72:             pebbles_per_patch: assets.pebble_counts[variant],
73:         }
74:         .spawn(commands, &instances);
75:         PebbleBatch {
76:             name: if woodland {
77:                 "Instanced woodland near pebble patches"
78:             } else {
79:                 "Instanced loose-stone near pebble patches"
80:             },
81:             mesh: assets.near[variant].clone(),
82:             material: stone,
83:             lod: PebbleMeshLod::Near,
84:             pebbles_per_patch: 0,
85:         }
86:         .spawn(commands, &instances);
87:         if !woodland {
88:             PebbleBatch {
89:                 name: "Instanced loose-stone billboard pebble patches",
90:                 mesh: assets.billboard[variant].clone(),
91:                 material: assets.billboard_material.clone(),
92:                 lod: PebbleMeshLod::Billboard,
93:                 pebbles_per_patch: 0,
94:             }
95:             .spawn(commands, &instances);
96:         }
97:     }
98: }
99: 
100: impl<M: ChunkInstancedMaterial> PebbleBatch<M> {
101:     fn spawn(self, commands: &mut Commands<'_, '_>, instances: &[ChunkInstance]) {
102:         let range = pebble_lod_visibility(self.lod);
103:         let Self {
104:             name,
105:             pebbles_per_patch,
106:             ..
107:         } = self;
108:         InstanceBatch {
109:             mesh: self.mesh,
110:             material: self.material,
111:             instances: instances.to_vec(),
112:             band: FadeBand::new(range.start_margin, range.end_margin),
113:             reach: ground_scatter_reach(PEBBLE_BATCH_FOOTPRINT_METRES),
114:             chunk_size: PEBBLE_CHUNK_SIZE,
115:         }
116:         .spawn(commands, |chunk| {
117:             (
118:                 Name::new(format!("{name} ({})", chunk.len())),
119:                 GroundScatterLayer::LooseStone,
120:                 LooseStonePebblePatch {
121:                     physical_pebbles: pebbles_per_patch * chunk.len(),
122:                 },
123:             )
124:         });
125:     }
126: }

