47:     let rotation_cos = cos(vertex.i_rotation);
48:     let rotation_sin = sin(vertex.i_rotation);
49:     out.world_normal = normalize(vec3<f32>(
50:         rotation_cos * normal.x + rotation_sin * normal.z,
51:         normal.y,
