20: @group(3) @binding(0) var leaf_opacity: texture_2d<f32>;
21: @group(3) @binding(1) var leaf_opacity_sampler: sampler;
22: @group(3) @binding(2) var front_albedo: texture_2d<f32>;
23: @group(3) @binding(3) var front_albedo_sampler: sampler;
24: @group(3) @binding(4) var back_albedo: texture_2d<f32>;
25: @group(3) @binding(5) var back_albedo_sampler: sampler;
26: @group(3) @binding(6) var front_normal: texture_2d<f32>;
27: @group(3) @binding(7) var front_normal_sampler: sampler;
28: @group(3) @binding(8) var back_normal: texture_2d<f32>;
29: @group(3) @binding(9) var back_normal_sampler: sampler;
30: @group(3) @binding(10) var leaf_arm: texture_2d<f32>;
31: @group(3) @binding(11) var leaf_arm_sampler: sampler;
32: 
33: struct TacticalShrubLeafInstancedUniform {
34:     // Wind direction XZ, strength; w reserved (phase comes from globals).
35:     parameters: vec4<f32>,
36:     // Opacity cutoff, normal strength, canopy AO strength, transmission.
37:     surface_parameters: vec4<f32>,
38:     // Roughness fallback, thickness, litter pigment lane, reserved.
39:     physical_parameters: vec4<f32>,
40:     // y scales the flat ambient term; every representation now shades fast.
41:     shading: vec4<f32>,
42: }
43: 
44: @group(3) @binding(12) var<uniform> leaf: TacticalShrubLeafInstancedUniform;
45: 
46: struct ShrubLeafVertexOutput {
47:     @builtin(position) clip_position: vec4<f32>,
48: #ifdef VISIBILITY_RANGE_DITHER
49:     @location(0) @interpolate(flat) visibility_range_dither: i32,
50: #endif
51:     @location(1) world_position: vec4<f32>,
52:     @location(2) world_normal: vec3<f32>,
53:     @location(3) uv: vec2<f32>,
54:     @location(4) color: vec4<f32>,
55: }
56: 
57: @vertex
58: fn vertex(vertex: Vertex) -> ShrubLeafVertexOutput {
59:     var out: ShrubLeafVertexOutput;
60:     let instance_matrix = instance_world_matrix(vertex.i_pos_scale, vertex.i_rotation);
61:     var world_position = instance_matrix * vec4<f32>(vertex.position, 1.0);
62: 
63:     var uv = vec2<f32>(0.0);
64: #ifdef VERTEX_UVS_A
65:     uv = vertex.uv;
66: #endif
67:     // Same sway as the tree leaf-card shader, driven by the shader clock.
68:     let bend = smoothstep(0.03, 1.0, 1.0 - uv.y);
69:     let wind_direction = normalize(leaf.parameters.xy);
70:     let wind_cross = vec2<f32>(-wind_direction.y, wind_direction.x);
71:     let position_phase = dot(world_position.xz, wind_direction) * 0.31
72:         + world_position.y * 0.17;
73:     let time = globals.time * 1.15;
74:     let gust = 0.7 + 0.3 * sin(time * 0.37 + position_phase * 0.63);
75:     let primary = sin(time + position_phase);
76:     let flutter = sin(time * 3.11 - position_phase * 1.73);
77:     let displacement = (
78:         wind_direction * primary * gust + wind_cross * flutter * 0.22
79:     ) * leaf.parameters.z * bend * bend;
80:     world_position.x += displacement.x;
81:     world_position.z += displacement.y;
82:     world_position.y -= length(displacement) * 0.16 * bend;
83: 
84:     out.world_position = world_position;
85:     out.clip_position = position_world_to_clip(world_position.xyz);
86:     out.uv = uv;
87: 
88:     var normal = vec3<f32>(0.0, 1.0, 0.0);
89: #ifdef VERTEX_NORMALS
90:     normal = vertex.normal;
91: #endif
92:     let rotation_cos = cos(vertex.i_rotation);
93:     let rotation_sin = sin(vertex.i_rotation);
94:     var world_normal = normalize(vec3<f32>(
95:         rotation_cos * normal.x + rotation_sin * normal.z,
96:         normal.y,
97:         -rotation_sin * normal.x + rotation_cos * normal.z,
98:     ));
99:     let normal_bend = smoothstep(0.03, 1.0, 1.0 - uv.y);
100:     out.world_normal = normalize(world_normal + vec3<f32>(0.0, 0.16 * normal_bend, 0.0));
101: 
102:     out.color = vec4<f32>(1.0);
103: #ifdef VERTEX_COLORS
104:     out.color = vertex.color;
105: #endif
106: 
107: #ifdef VISIBILITY_RANGE_DITHER
108:     let instance_origin = instance_matrix * vec4<f32>(0.0, 0.0, 0.0, 1.0);
109:     out.visibility_range_dither =
110:         visibility_range_dither_level(chunk_band.visibility_range, instance_origin.xyz);
111: #endif
112:     return out;
113: }
114: 
115: @fragment
116: fn fragment(
117:     in: ShrubLeafVertexOutput,
118:     @builtin(front_facing) is_front: bool,
119: ) -> @location(0) vec4<f32> {
120: #ifdef VISIBILITY_RANGE_DITHER
121:     // Complementary per-pixel partition between the cambered and card
122:     // representations; see tactical_grass_instanced.wgsl for the rationale.
123:     if in.visibility_range_dither != 0 {
124:         let magnitude = clamp(f32(abs(in.visibility_range_dither)) / 16.0, 0.0, 1.0);
125:         let pixel_hash = fract(
126:             52.9829189
127:                 * fract(dot(floor(in.clip_position.xy), vec2<f32>(0.06711056, 0.00583715))),
128:         );
129:         if in.visibility_range_dither > 0 {
130:             if pixel_hash < magnitude {
131:                 discard;
132:             }
133:         } else if pixel_hash >= 1.0 - magnitude {
134:             discard;
135:         }
136:     }
137: #endif
138:     let opacity = textureSample(leaf_opacity, leaf_opacity_sampler, in.uv).r;
139:     if opacity < leaf.surface_parameters.x {
140:         discard;
141:     }
142: 
143:     let uv_dx = dpdx(in.uv);
144:     let uv_dy = dpdy(in.uv);
145:     var albedo = textureSample(front_albedo, front_albedo_sampler, in.uv).rgb;
146:     if !is_front {
147:         // Face selection can diverge within a fragment quad on WebGPU.
148:         albedo = textureSampleGrad(back_albedo, back_albedo_sampler, in.uv, uv_dx, uv_dy).rgb;
149:     }
150:     // Deterministic per-leaf pigments (berries, senescent tints) ride the
151:     // vertex colour lane, exactly like the tree leaf-card shader.
152:     albedo = mix(albedo, in.color.rgb, leaf.physical_parameters.z);
153:     let arm = textureSample(leaf_arm, leaf_arm_sampler, in.uv).rgb;
154:     let base_normal = normalize(select(-in.world_normal, in.world_normal, is_front));
155:     let canopy_visibility = mix(1.0, in.color.a, leaf.surface_parameters.z);
156:     let occlusion = canopy_visibility * arm.r;
157: 
158:     // Every representation - including the cambered near leaves - shades with
159:     // the fast foliage model: flat ambient + wrapped Lambert translucency +
160:     // one clamped cascade fetch. No screen-space tangent frame, normal map,
161:     // image-based lighting, or specular. The cards already used this model and
162:     // the cambered leaves crossfade into it, so full PBR was pure cost.
163:     var lit = albedo * lights.ambient_color.rgb * leaf.shading.y * occlusion;
164:     let view_z = dot(vec4<f32>(
165:         view.view_from_world[0].z,
166:         view.view_from_world[1].z,
167:         view.view_from_world[2].z,
168:         view.view_from_world[3].z,
169:     ), in.world_position);
170:     let transmission = leaf.surface_parameters.w;
171:     for (var light_index = 0u; light_index < lights.n_directional_lights;
172:         light_index += 1u)
173:     {
174:         let light = lights.directional_lights[light_index];
175:         let alignment = dot(base_normal, light.direction_to_light);
176:         let wrapped = saturate(alignment) * (1.0 - transmission)
177:             + saturate(-alignment) * transmission;
178:         let shadow = clamp(
179:             shadows::fetch_directional_shadow(
180:                 light_index,
181:                 in.world_position,
182:                 base_normal,
183:                 view_z,
184:                 in.clip_position.xy,
185:             ),
186:             0.12,
187:             1.0,
188:         );
189:         lit += albedo * light.color.rgb * (wrapped * shadow * occlusion * 0.3183099);
190:     }
191:     return vec4<f32>(lit * view.exposure, opacity);
192: }

