28:     var world_position = mesh_functions::mesh_position_local_to_world(
29:         world_from_local,
30:         vec4<f32>(vertex.position, 1.0),
31:     );
32:     var world_normal = mesh_functions::mesh_normal_local_to_world(
33:         vertex.normal,
34:         vertex.instance_index,
35:     );
36:     let level = i32(round(tree.parameters.x));
37:     if level == 4 {
38:         let root_world = mesh_functions::mesh_position_local_to_world(
39:             world_from_local,
40:             vec4<f32>(0.0, 0.0, 0.0, 1.0),
41:         ).xyz;
42:         let to_camera = normalize(view.world_position.xz - root_world.xz + vec2<f32>(0.0001, 0.0));
43:         let right = vec3<f32>(to_camera.y, 0.0, -to_camera.x);
44:         // Whole-tree cards face the camera, so they cannot use the model's
45:         // rotated basis directly. They must still inherit its horizontal and
46:         // vertical scale. Dropping these lengths made every level-4 card use
47:         // the full baked-tree dimensions, even under a small tree parent.
48:         let horizontal_scale = length(world_from_local[0].xyz);
49:         let vertical_scale = length(world_from_local[1].xyz);
50:         world_position = vec4<f32>(
51:             root_world
52:                 + right * vertex.position.x * horizontal_scale
53:                 + vec3<f32>(0.0, vertex.position.y * vertical_scale, 0.0),
54:             1.0,
55:         );
56:         world_normal = vec3<f32>(to_camera.x, 0.18, to_camera.y);
57:     }
58:     let height_weight = smoothstep(0.05, 1.0, vertex.uv.y);
59:     let phase = globals.time * tree.parameters.w
60:         + world_position.x * 0.11
61:         + world_position.z * 0.073
62:         + tree.parameters.y * 6.2831853;
63:     let wind = (sin(phase) * 0.72 + sin(phase * 2.17 + 1.3) * 0.28)
64:         * tree.parameters.z
