86: @fragment
87: fn fragment(in: VertexOutput) -> @location(0) vec4<f32> {
88: #ifdef VISIBILITY_RANGE_DITHER
89:     // Switch aggregate tree representations at the midpoint of Bevy's
90:     // complementary visibility interval. A translucent crossfade reads as a
91:     // pale duplicate crown, while Bevy's ordered 4x4 discard reads as a
92:     // screen-door grid. The atlas cutout itself still uses multisample
93:     // coverage; only the LOD handoff is intentionally crisp.
94:     if in.visibility_range_dither <= -8 || in.visibility_range_dither > 8 {
95:         discard;
96:     }
97: #endif
98:     var uv = in.uv;
99:     if i32(round(tree.parameters.x)) == 4 {
100:         let direction = normalize(view.world_position.xz - in.world_position.xz + vec2<f32>(0.0001, 0.0));
101:         let angle = atan2(direction.y, direction.x);
102:         // Bake-card right axes produce view normals one quarter turn behind
103:         // their authored angle. Select by that normal convention rather than
104:         // sampling the orthographic view from the opposite crown quadrant.
105:         let wrapped = fract(angle / 6.2831853 + 1.0 - 0.25);
106:         let view_index = u32(round(wrapped * 8.0)) % 8u;
107:         // The whole-tree atlas is laid out in three columns. Select the
108:         // nearest of eight real orthographic source renders.
109:         let column = view_index % 3u;
110:         let row = view_index / 3u;
111:         uv = vec2<f32>(
112:             (f32(column) + uv.x) / 3.0,
113:             (f32(row) + uv.y) / 3.0,
114:         );
115:     }
116:     let baked = textureSample(baked_color, baked_color_sampler, uv);
117:     if baked.a < 0.2 {
118:         discard;
119:     }
120:     let light_direction = normalize(tree.lighting.xyz);
121:     // The atlas already contains the source tree's small-scale normal and
122:     // occlusion variation. Apply only a broad hemispherical cosine here;
123:     // never add the old 78% direct-light floor on top of the baked response.
124:     // Aggregate cards are intentionally two-sided. Their authored normal
125:     // describes the card plane, not a literal one-sided leaf surface, so use
126:     // symmetric wrap lighting and retain enough diffuse fill for an oblique
127:     // card not to turn an otherwise healthy crown into a black cutout.
128:     let card_light = abs(dot(normalize(in.world_normal), light_direction));
129:     let normal_light = 0.25 + card_light * 0.75;
130:     let ambient_irradiance = tree.ambient.rgb * tree.ambient.w;
131:     let direct_irradiance = normal_light
132:         * tree.lighting.w
133:         * (1.0 - tree.ambient.w);
134:     return vec4<f32>(baked.rgb * (ambient_irradiance + vec3<f32>(direct_irradiance)), baked.a);
135: }

