28:         self.role
29:     }
30: 
31:     pub(crate) fn new(name: RigJointName) -> Self {
32:         let body_region = AnimationBodyRegion::from(&name);
33:         let role = BoneRole::from_name(&name);
34:         Self {
35:             name,
36:             body_region,
37:             role,
38:         }
39:     }
40: }
41: 
42: impl From<&RigJointName> for AnimationBodyRegion {
43:     fn from(name: &RigJointName) -> Self {
44:         if [
45:             RigJointName::SKELETON,
46:             RigJointName::BODY_WORLD,
47:             RigJointName::ROOT,
48:         ]
49:         .iter()
50:         .any(|root| name.eq_ignore_ascii_case(root))
51:             || [
52:                 RigJointPart::Upleg,
53:                 RigJointPart::Lowleg,
54:                 RigJointPart::Foot,
55:                 RigJointPart::Talocrural,
56:                 RigJointPart::Subtalar,
57:                 RigJointPart::Transversetarsal,
58:                 RigJointPart::Ball,
59:             ]
60:             .into_iter()
61:             .any(|part| {
62:                 name.as_ref()
63:                     .to_ascii_lowercase()
64:                     .contains(&format!("_{part}"))
65:             })
66:         {
67:             Self::Lower
68:         } else {
69:             Self::Upper
70:         }
71:     }
72: }
73: 
74: impl AnimationBodyRegion {
75:     pub(super) fn includes(self, layer: ClipLayer, role: Option<BoneRole>) -> bool {
76:         match layer {
77:             ClipLayer::Whole => true,
78:             ClipLayer::Upper => self == Self::Upper,
79:             ClipLayer::Lower | ClipLayer::CombatLower => self == Self::Lower,
80:             ClipLayer::CombatUpper => self == Self::Upper || role == Some(BoneRole::Pelvis),
81:             ClipLayer::MainHand | ClipLayer::Offhand => false,
82:         }
83:     }
84: }

