50:             seed: (streams::INSTANCE.seed(base_seed, &[index as u64]).to_u64() & 0xffff_ffff)
51:                 as u32,
52:         });
53:     }
54:     super::batches::spawn(
55:         commands,
56:         super::batches::PebbleBatchAssets {
57:             hero: &hero_meshes,
58:             near: &near_meshes,
59:             billboard: &billboard_meshes,
60:             pebble_counts: &pebble_counts,
