69: struct PatchAssets {
70:     hero_meshes: Vec<Handle<Mesh>>,
71:     near_meshes: Vec<Handle<Mesh>>,
72:     billboard_meshes: Vec<Handle<Mesh>>,
73:     pebble_counts: Vec<usize>,
74:     stone_material: Handle<TacticalPebbleMaterial>,
75:     woodland_stone_material: Handle<TacticalPebbleMaterial>,
76:     billboard_material: Handle<TacticalPebbleBillboardMaterial>,
77: }
78: impl PatchAssets {
79:     fn new(
80:         meshes: &mut Assets<Mesh>,
81:         pebble_materials: &mut Assets<TacticalPebbleMaterial>,
82:         billboard_materials: &mut Assets<TacticalPebbleBillboardMaterial>,
83:         half_extent: f32,
84:     ) -> Self {
85:         let mut hero_meshes = Vec::new();
86:         let mut near_meshes = Vec::new();
87:         let mut billboard_meshes = Vec::new();
88:         let mut pebble_counts = Vec::new();
89:         for density in PebbleDensity::ALL {
90:             for variant in 0..MESH_VARIANTS {
91:                 let seed = StreamId::new("visual.ground-scatter.loose-stone.variant")
92:                     .seed(0.into(), &[variant]);
93:                 let hero = pebble_patch_mesh(seed, PebbleMeshLod::Hero, half_extent, density);
94:                 pebble_counts.push(hero.count_vertices() / HERO_PEBBLE_VERTICES);
95:                 hero_meshes.push(meshes.add(hero));
96:                 near_meshes.push(meshes.add(pebble_patch_mesh(
97:                     seed,
98:                     PebbleMeshLod::Near,
99:                     half_extent,
100:                     density,
101:                 )));
102:                 billboard_meshes.push(meshes.add(pebble_billboard_patch_mesh(
103:                     seed,
104:                     half_extent,
105:                     density,
106:                 )));
107:             }
108:         }
109:         let stone_material = pebble_materials.add(TacticalPebbleMaterial::new(rock_color(
110:             RockLithology::Granite,
111:         )));
112:         let woodland_stone_material =
113:             pebble_materials.add(TacticalPebbleMaterial::new(Color::srgb_u8(104, 91, 70)));
114:         let billboard_material = billboard_materials.add(TacticalPebbleBillboardMaterial {
115:             color: Vec4::from_array(
116:                 rock_color(RockLithology::Granite)
117:                     .to_linear()
118:                     .to_f32_array(),
119:             ),
120:             lighting: Vec3::new(0.35, 0.86, 0.25).normalize().extend(1.0),
121:             ambient: Vec4::new(1.0, 1.0, 1.0, 0.28),
122:         });
123: 
124:         Self {
125:             hero_meshes,
126:             near_meshes,
127:             billboard_meshes,
128:             pebble_counts,
129:             stone_material,
130:             woodland_stone_material,
131:             billboard_material,
132:         }
133:     }
134: }
135: struct PatchPlacement {
136:     variant: usize,
137:     woodland: bool,
138:     transform: Transform,
139: }
140: impl PatchPlacement {
141:     fn new(
142:         ground: &SceneGround,
143:         terrain: &SceneTerrain,
144:         index: usize,
145:         sample: GroundSurface,
146:         base_seed: Seed,
147:         half_extent: f32,
148:     ) -> Option<Self> {
149:         if !matches!(
150:             sample.cover,
151:             GroundCover::LooseStone | GroundCover::LeafLitter
152:         ) {
153:             return None;
154:         }
155:         let grid_x = index % ground.grid_width();
156:         let grid_z = index / ground.grid_width();
157:         let position = Vec2::new(
158:             grid_x as f32 * ground.grid_scale() - ground.width() * 0.5,
159:             grid_z as f32 * ground.grid_scale() - ground.depth() * 0.5,
160:         );
161:         let position = ScenePlanPoint::from_metres(position)?;
162:         // The patch can rotate and tilt. Exclude its full existing bounds,
163:         // including pebble overhang, from exact managed-ground ownership.
164:         let envelope_radius = Vec3::new(half_extent + 0.3, 0.4, half_extent + 0.3).length();
165:         if ground.urban.overlaps_disk(position, envelope_radius) {
166:             return None;
167:         }
168:         let (Some(height), Some(normal)) =
169:             (terrain.height_at(position), terrain.normal_at(position))
170:         else {
171:             return None;
172:         };
173:         if normal.y < 0.72 {
174:             return None;
175:         }
176:         let hash = StreamId::new("visual.ground-scatter.loose-stone.scatter")
177:             .seed(base_seed, &[index as u64]);
178:         let woodland = sample.cover == GroundCover::LeafLitter;
179:         let density = if woodland {
180:             // Every woodland cell gets a sparse candidate patch. Individual
181:             // survival still leaves irregular gaps, but keeping the patches
182:             // continuous yields roughly one visible 3--8 cm stone per square
183:             // metre instead of making rocks disappear from review frames.
184:             PebbleDensity::Woodland
185:         } else {
186:             let coverage = scree_patch_coverage(base_seed, position, normal);
187:             if coverage >= 0.61 {
188:                 PebbleDensity::Dense
189:             } else if coverage >= 0.34 {
190:                 PebbleDensity::Sparse
191:             } else {
192:                 return None;
193:             }
194:         };
195:         let variant = density.asset_offset()
196:             + StreamId::new("visual.ground-scatter.loose-stone.spawn.mesh-variant")
197:                 .rng(hash, &[])
198:                 .index(MESH_VARIANTS as usize);
199:         let yaw = Quat::from_rotation_y(
200:             StreamId::new("visual.ground-scatter.loose-stone.spawn.yaw")
201:                 .rng(hash, &[])
202:                 .inclusive_unit_f32()
203:                 * core::f32::consts::TAU,
204:         );
205:         let transform = Transform::from_xyz(
206:             position.metres().x,
207:             height.metres() + if woodland { -0.006 } else { 0.006 },
208:             position.metres().y,
209:         )
210:         .with_rotation(Quat::from_rotation_arc(Vec3::Y, *normal) * yaw)
211:         .with_scale(Vec3::splat(if woodland { 0.58 } else { 1.0 }));
212: 
213:         Some(Self {
214:             variant,
215:             woodland,
216:             transform,
217:         })
218:     }
219: }

