7: /// Compact server-queryable description of one ground sample.
8: #[derive(Debug, Clone, Copy, Default, Eq, PartialEq, Serialize, Deserialize, Reflect)]
9: #[serde(deny_unknown_fields)]
10: pub struct GroundSurface {
11:     pub substrate: GroundSubstrate,
12:     pub cover: GroundCover,
13:     pub cover_density_bps: u16,
14:     pub cover_height_cm: u16,
15: }
16: 
17: /// Authoritative spatial ground semantics shared by the tactical server and
18: /// clients. Samples use the same centered row-major grid convention as
19: /// [`SceneTerrain`], allowing presentation and future gameplay systems to ask
20: /// the same world-position question.
21: #[derive(Component, Serialize, Deserialize, Debug, Reflect, Clone, PartialEq)]
22: #[component(immutable)]
23: pub struct SceneGround {
24:     samples: Vec<GroundSurface>,
25:     pub urban: UrbanGroundSurfaces,
26:     width: usize,
27:     scale: f32,
28: }
29: 
30: /// Physical material below a tactical ground-cover layer.
31: ///
32: /// This is authoritative semantic data rather than a render-material index so
33: /// server gameplay can query it without depending on client asset catalogs.
34: #[derive(Debug, Clone, Copy, Default, Eq, PartialEq, Serialize, Deserialize, Reflect)]
35: #[serde(rename_all = "snake_case")]
36: pub enum GroundSubstrate {
37:     #[default]
38:     Soil,
39:     Stone,
40:     Gravel,
41:     Mud,
42:     Road,
43:     Water,
44: }
45: 
46: /// Mutually exclusive ground-cover profile at one tactical surface sample.
47: ///
48: /// A profile can render several compatible details (for example leaves and
49: /// twigs), but a location never simultaneously claims two cover profiles.
50: #[derive(Debug, Clone, Copy, Default, Eq, PartialEq, Serialize, Deserialize, Reflect)]
51: #[serde(rename_all = "snake_case")]
52: pub enum GroundCover {
53:     Bare,
54:     #[default]
55:     TallGrass,
56:     LeafLitter,
57:     LooseStone,
58:     Reeds,
59: }
60: 
61: impl SceneGround {
62:     pub fn uniform_for_terrain(terrain: &SceneTerrain, surface: GroundSurface) -> Self {
63:         Self {
64:             samples: vec![surface; terrain.grid_width() * terrain.grid_depth()],
65:             width: terrain.grid_width(),
66:             scale: terrain.grid_scale(),
67:             urban: UrbanGroundSurfaces::default(),
68:         }
69:     }
70: 
71:     pub fn from_samples(
72:         grid_width: usize,
73:         grid_depth: usize,
74:         scale: f32,
75:         samples: Vec<GroundSurface>,
76:     ) -> Option<Self> {
77:         if grid_width < 2
78:             || grid_depth < 2
79:             || !scale.is_finite()
80:             || scale <= 0.0
81:             || samples.len() != grid_width.checked_mul(grid_depth)?
82:             || samples.iter().any(|sample| {
83:                 sample.cover_density_bps > BASIS_POINTS_PER_WHOLE || sample.cover_height_cm > 1_000
84:             })
85:         {
86:             return None;
87:         }
88:         Some(Self {
89:             samples,
90:             urban: UrbanGroundSurfaces::default(),
91:             width: grid_width,
92:             scale,
93:         })
94:     }
95: 
96:     pub fn grid_width(&self) -> usize {
97:         self.width
98:     }
99: 
100:     pub fn grid_depth(&self) -> usize {
101:         self.samples.len() / self.width
102:     }
103: 
104:     pub fn width(&self) -> f32 {
105:         self.grid_width().saturating_sub(1) as f32 * self.scale
106:     }
107: 
108:     pub fn depth(&self) -> f32 {
109:         self.grid_depth().saturating_sub(1) as f32 * self.scale
110:     }
111: 
112:     pub fn grid_scale(&self) -> f32 {
113:         self.scale
114:     }
115: 
116:     pub fn samples(&self) -> &[GroundSurface] {
117:         &self.samples
118:     }
119: 
120:     /// Returns exact urban ownership, then the natural sample at a world point.
121:     /// Enum values are intentionally not interpolated across boundaries.
122:     pub fn ground_at(&self, point: ScenePlanPoint) -> Option<GroundSurface> {
123:         let grid = (point.metres() + Vec2::new(self.width(), self.depth()) * 0.5) / self.scale;
124:         if grid.x < 0.0
125:             || grid.y < 0.0
126:             || grid.x > (self.grid_width() - 1) as f32
127:             || grid.y > (self.grid_depth() - 1) as f32
128:         {
129:             return None;
130:         }
131:         let x = (grid.x.floor() as usize).min(self.grid_width() - 1);
132:         let z = (grid.y.floor() as usize).min(self.grid_depth() - 1);
133:         self.urban
134:             .surface_at(point)
135:             .or_else(|| self.samples.get(z * self.width + x).copied())
136:     }
137: 
138:     /// Conservatively checks a square scatter footprint. Macro grass patches
139:     /// use this to avoid extending blades across a leaf-litter boundary.
140:     pub fn cover_intersects_square(
141:         &self,
142:         centre: ScenePlanPoint,
143:         half_extent: f32,
144:         cover: GroundCover,
145:     ) -> bool {
146:         if !half_extent.is_finite() || half_extent < 0.0 {
147:             return false;
148:         }
149:         let centre = centre.metres();
150:         let half_size = Vec2::new(self.width(), self.depth()) * 0.5;
151:         let minimum = ((centre - Vec2::splat(half_extent) + half_size) / self.scale)
152:             .floor()
153:             .max(Vec2::ZERO);
154:         let maximum = ((centre + Vec2::splat(half_extent) + half_size) / self.scale)
155:             .ceil()
156:             .min(Vec2::new(
157:                 (self.grid_width() - 1) as f32,
158:                 (self.grid_depth() - 1) as f32,
159:             ));
160:         if minimum.x > maximum.x || minimum.y > maximum.y {
161:             return false;
162:         }
163:         for z in minimum.y as usize..=maximum.y as usize {
164:             for x in minimum.x as usize..=maximum.x as usize {
165:                 if self.samples[z * self.width + x].cover == cover {
166:                     return true;
167:                 }
168:             }
169:         }
170:         false
171:     }
172: 
173:     pub fn cover_count(&self, cover: GroundCover) -> usize {
174:         self.samples
175:             .iter()
176:             .filter(|sample| sample.cover == cover)
177:             .count()
178:     }
179: }
