8:         SceneInputResult, SceneValidationError, TREE_CANOPY_GROUND_RADIUS_METRES,
9:         TREE_DENSE_LEAF_LITTER_RADIUS_METRES, base_ground_surface,
10:     },
11: };
12: 
13: pub(crate) fn build_scene_ground(
14:     environment: &[EnvironmentalSample],
15:     terrain: &SceneTerrain,
16:     obstacles: &[GeneratedObstacle],
17:     obstacle_spacing: f32,
18:     buildings: &[GeneratedBuilding],
19:     streets: &[CityStreetPatch],
20:     yards: &[CityYardPatch],
21: ) -> SceneInputResult<SceneGround> {
22:     let width = terrain.grid_width();
23:     let depth = terrain.grid_depth();
24:     let spacing = terrain.grid_scale();
25:     let mut samples = environment
26:         .iter()
27:         .copied()
28:         .map(base_ground_surface)
29:         .collect::<Vec<_>>();
30:     let half_width = terrain.width() * 0.5;
31:     let half_depth = terrain.depth() * 0.5;
32:     for obstacle in obstacles {
33:         let GeneratedObstacle::Tree { x, z } = *obstacle else {
34:             continue;
35:         };
36:         let tree = bevy::math::Vec2::new(
37:             f32::from(x) * obstacle_spacing - half_width,
38:             f32::from(z) * obstacle_spacing - half_depth,
39:         );
40:         for sample_z in 0..depth {
41:             for sample_x in 0..width {
42:                 let position = bevy::math::Vec2::new(
43:                     sample_x as f32 * spacing - half_width,
44:                     sample_z as f32 * spacing - half_depth,
45:                 );
46:                 let distance = position.distance(tree);
47:                 if distance > TREE_CANOPY_GROUND_RADIUS_METRES {
48:                     continue;
49:                 }
50:                 let sample = &mut samples[sample_z * width + sample_x];
51:                 if matches!(
52:                     sample.substrate,
53:                     GroundSubstrate::Water | GroundSubstrate::Road
54:                 ) {
55:                     continue;
56:                 }
57:                 let litter_roll = StreamId::new("terrain.tree-leaf-litter")
58:                     .rng(
59:                         0.into(),
60:                         &[u64::from(x), u64::from(z), sample_x as u64, sample_z as u64],
61:                     )
62:                     .unit_f32();
63:                 if distance <= TREE_DENSE_LEAF_LITTER_RADIUS_METRES
64:                     || litter_roll < tree_leaf_litter_probability(distance)
65:                 {
66:                     sample.cover = GroundCover::LeafLitter;
67:                     sample.cover_density_bps = 9_200;
68:                     sample.cover_height_cm = 6;
69:                 }
70:             }
71:         }
72:     }
73:     let mut ground = SceneGround::from_samples(width, depth, spacing, samples).ok_or(
74:         SceneInputError::Validation(SceneValidationError::GroundSurface),
75:     )?;
76:     ground.urban = crate::scene::UrbanGroundSurfaces::new(streets, yards, buildings)?;
77:     Ok(ground)
78: }
79: 
80: pub(crate) fn tree_leaf_litter_probability(distance_metres: f32) -> f32 {
81:     if distance_metres <= TREE_DENSE_LEAF_LITTER_RADIUS_METRES {
82:         return 1.0;
83:     }
84:     let crown_fraction = ((distance_metres - TREE_DENSE_LEAF_LITTER_RADIUS_METRES)
85:         / (TREE_CANOPY_GROUND_RADIUS_METRES - TREE_DENSE_LEAF_LITTER_RADIUS_METRES))
86:         .clamp(0.0, 1.0);
87:     0.12 + (1.0 - crown_fraction).powf(1.5) * 0.60
88: }

