207: pub(crate) fn base_ground_surface(sample: EnvironmentalSample) -> GroundSurface {
208:     if sample.crossing_bps >= 5_000 || matches!(sample.surface, TacticalSurface::Road) {
209:         return GroundSurface {
210:             substrate: GroundSubstrate::Road,
211:             cover: GroundCover::Bare,
212:             cover_density_bps: 0,
213:             cover_height_cm: 0,
214:         };
215:     }
216:     if sample.water_bps >= 5_000 || matches!(sample.surface, TacticalSurface::Water) {
217:         return GroundSurface {
218:             substrate: GroundSubstrate::Water,
219:             cover: GroundCover::Bare,
220:             cover_density_bps: 0,
221:             cover_height_cm: 0,
222:         };
223:     }
224:     if sample.wetland_bps >= 5_000 || matches!(sample.surface, TacticalSurface::Wetland) {
225:         return GroundSurface {
226:             substrate: GroundSubstrate::Mud,
227:             cover: GroundCover::Reeds,
228:             cover_density_bps: sample.wetland_bps.max(5_000),
229:             cover_height_cm: 110,
230:         };
231:     }
232:     if sample.hilly_bps >= 6_500 {
233:         return GroundSurface {
234:             substrate: if sample.hilly_bps >= 8_500 {
235:                 GroundSubstrate::Stone
236:             } else {
237:                 GroundSubstrate::Gravel
238:             },
239:             cover: GroundCover::LooseStone,
240:             cover_density_bps: (sample.hilly_bps / 2).clamp(3_250, 5_000),
241:             cover_height_cm: 4,
242:         };
243:     }
244:     GroundSurface {
245:         substrate: GroundSubstrate::Soil,
246:         cover: GroundCover::TallGrass,
247:         cover_density_bps: 9_600u16.saturating_sub(sample.canopy_bps / 5),
248:         cover_height_cm: 82,
249:     }
250: }
