252: fn upsample_playable_grid(
253:     source: &TerrainSampleGrid,
254: ) -> (usize, usize, f32, Vec<f32>, Vec<EnvironmentalSample>) {
255:     const TARGET_SPACING_METRES: f32 = 2.0;
256:     let source_width = usize::from(source.width);
257:     let source_depth = usize::from(source.depth);
258:     if source.spacing_metres <= TARGET_SPACING_METRES {
259:         return (
260:             source_width,
261:             source_depth,
262:             source.spacing_metres,
263:             source.heights_metres.clone(),
264:             source.environment.clone(),
265:         );
266:     }
267:     let largest_source_side = (source_width - 1).max(source_depth - 1);
268:     let maximum_subdivisions = ((MAX_PLAYABLE_SIDE - 1) / largest_source_side).max(1);
269:     let subdivisions = (source.spacing_metres / TARGET_SPACING_METRES)
270:         .ceil()
271:         .max(1.0) as usize;
272:     let subdivisions = subdivisions.min(maximum_subdivisions);
273:     let cells_x = (source_width - 1) * subdivisions;
274:     let cells_z = (source_depth - 1) * subdivisions;
275:     let width = cells_x + 1;
276:     let depth = cells_z + 1;
277:     let spacing = source.spacing_metres / subdivisions as f32;
278:     let mut heights = Vec::with_capacity(width * depth);
279:     let mut environment = Vec::with_capacity(width * depth);
280:     for z in 0..depth {
281:         for x in 0..width {
282:             let source_x = x as f32 / subdivisions as f32;
283:             let source_z = z as f32 / subdivisions as f32;
284:             let x0 = source_x.floor() as usize;
285:             let z0 = source_z.floor() as usize;
286:             let x1 = (x0 + 1).min(source_width - 1);
287:             let z1 = (z0 + 1).min(source_depth - 1);
288:             let tx = source_x - x0 as f32;
289:             let tz = source_z - z0 as f32;
290:             let north = lerp(
291:                 source.heights_metres[z0 * source_width + x0],
292:                 source.heights_metres[z0 * source_width + x1],
293:                 tx,
294:             );
295:             let south = lerp(
296:                 source.heights_metres[z1 * source_width + x0],
297:                 source.heights_metres[z1 * source_width + x1],
298:                 tx,
299:             );
300:             heights.push(lerp(north, south, tz));
301:             let nearest_x = source_x.round() as usize;
302:             let nearest_z = source_z.round() as usize;
303:             environment.push(source.environment[nearest_z * source_width + nearest_x]);
304:         }
305:     }
306:     (width, depth, spacing, heights, environment)
307: }
308: 
309: fn lerp(left: f32, right: f32, amount: f32) -> f32 {
310:     left + (right - left) * amount
311: }
312: 
313: /// Adds sub-source-resolution detail before constructing the shared terrain.
314: /// The result therefore feeds the rendered mesh, height queries, IK, and the
315: /// authoritative server collider instead of becoming client-only displacement.
316: fn add_authoritative_microrelief(
317:     seed: fabelgeist_determinism::Seed,
318:     width: usize,
319:     depth: usize,
320:     spacing: f32,
321:     heights: &mut [f32],
322:     environment: &[EnvironmentalSample],
323: ) -> u32 {
324:     let mut adjusted = 0;
325:     for z in 0..depth {
326:         for x in 0..width {
327:             let index = z * width + x;
328:             let sample = environment[index];
329:             if is_reserved_playability_cell(x, z, width, depth)
330:                 || sample.water_bps >= 5_000
331:                 || sample.crossing_bps >= 5_000
332:                 || matches!(
333:                     sample.surface,
334:                     TacticalSurface::Road | TacticalSurface::Water
335:                 )
336:             {
337:                 continue;
338:             }
339:             let hilly = f32::from(sample.hilly_bps) / f32::from(BASIS_POINTS_PER_WHOLE);
340:             let wetland = f32::from(sample.wetland_bps) / f32::from(BASIS_POINTS_PER_WHOLE);
341:             let amplitude = (0.055 + hilly * 0.22) * (1.0 - wetland * 0.55);
342:             let world_x = x as f32 * spacing;
343:             let world_z = z as f32 * spacing;
344:             let broad = value_noise(seed, world_x, world_z, 6.0);
345:             let fine = value_noise(
346:                 streams::MICRORELIEF_FINE.seed(seed, &[]),
347:                 world_x,
348:                 world_z,
349:                 2.25,
350:             );
351:             let offset = (broad * 0.72 + fine * 0.28) * amplitude;
352:             if offset.abs() > 0.0 {
353:                 heights[index] += offset;
354:                 adjusted += 1;
355:             }
356:         }
357:     }
358:     adjusted
359: }
360: 
361: fn repair_playable_terrain(
362:     width: usize,
363:     depth: usize,
364:     spacing: f32,
365:     heights: &mut [f32],
366:     environment: &mut [EnvironmentalSample],
367: ) -> SceneInputResult<SceneRepairReport> {
368:     let original_heights = heights.to_vec();
369:     crate::scene::grade::constrain(
370:         heights,
371:         width,
372:         depth,
373:         spacing,
374:         crate::scene::TerrainGradeLimit::PLAYABLE.ratio(),
375:     )?;
376: 
377:     let mut repaired_water_samples = 0;
378:     for z in 0..depth {
379:         for x in 0..width {
380:             if is_reserved_playability_cell(x, z, width, depth)
381:                 && environment[z * width + x].water_bps >= 8_000
382:             {
383:                 let sample = &mut environment[z * width + x];
384:                 sample.water_bps = 0;
385:                 sample.wetland_bps = sample.wetland_bps.min(4_000);
386:                 sample.canopy_bps = 0;
387:                 sample.surface = TacticalSurface::Open;
388:                 repaired_water_samples += 1;
389:             }
390:         }
391:     }
392:     Ok(SceneRepairReport {
393:         upsampled_height_samples: 0,
394:         microrelief_adjusted_samples: 0,
395:         adjusted_height_samples: heights
396:             .iter()
397:             .zip(original_heights)
398:             .filter(|(after, before)| (*after - before).abs() > 0.0)
399:             .count() as u32,
400:         repaired_water_samples,
401:         removed_corridor_obstacles: 0,
402:         levelled_building_samples: 0,
403:         removed_building_obstacles: 0,
404:     })
405: }
406: 
407: fn is_reserved_playability_cell(x: usize, z: usize, width: usize, depth: usize) -> bool {
408:     let center_z = depth / 2;
409:     let party_x = width / 4;
410:     let enemy_x = width * 3 / 4;
411:     z == center_z
412:         || [party_x, enemy_x]
413:             .into_iter()
414:             .any(|center_x| x.abs_diff(center_x) <= 1 && z.abs_diff(center_z) <= 1)
415: }
416: 
417: fn is_tree_camera_clearance_cell(_x: usize, z: usize, depth: usize) -> bool {
418:     let center_z = depth / 2;
419:     // Players currently enter within a bounded five-metre square around the
420:     // scene origin. Keep only large tree crowns out of the centre row and its
421:     // immediate neighbours so they cannot enter the production third-person
422:     // camera envelope. Rocks and terrain repair retain the narrower gameplay
423:     // corridor contract above.
424:     z.abs_diff(center_z) <= 1
425: }
