427: fn validate_grid(
428:     grid: &TerrainSampleGrid,
429:     max_side: usize,
430:     grid_kind: SampleGridKind,
431: ) -> SceneInputResult<()> {
432:     let width = usize::from(grid.width);
433:     let depth = usize::from(grid.depth);
434:     if width < 2 || depth < 2 || width > max_side || depth > max_side {
435:         return invalid(SceneValidationError::GridDimensions { grid: grid_kind });
436:     }
437:     if !grid.spacing_metres.is_finite() || !(0.25..=2_000.0).contains(&grid.spacing_metres) {
438:         return invalid(SceneValidationError::GridSpacing { grid: grid_kind });
439:     }
440:     let expected = width.checked_mul(depth).ok_or({
441:         SceneInputError::Validation(SceneValidationError::GridOverflow { grid: grid_kind })
442:     })?;
443:     if grid.heights_metres.len() != expected || grid.environment.len() != expected {
444:         return invalid(SceneValidationError::GridSamples { grid: grid_kind });
445:     }
446:     if grid
447:         .heights_metres
448:         .iter()
449:         .any(|height| !height.is_finite() || !(-12_000.0..=12_000.0).contains(height))
450:     {
451:         return invalid(SceneValidationError::GridHeight { grid: grid_kind });
452:     }
453:     if grid.environment.iter().any(|sample| {
454:         [
455:             sample.canopy_bps,
456:             sample.wetland_bps,
457:             sample.cultivation_bps,
458:             sample.water_bps,
459:             sample.hilly_bps,
460:             sample.crossing_bps,
461:         ]
462:         .into_iter()
463:         .any(|value| value > BASIS_POINTS_PER_WHOLE)
464:     }) {
465:         return invalid(SceneValidationError::GridEnvironment { grid: grid_kind });
466:     }
467:     Ok(())
468: }
469: 
470: fn validate_weather(weather: WeatherSnapshot) -> SceneInputResult<()> {
471:     if weather.rules_version != WEATHER_RULES_VERSION
472:         || weather.wind_speed_bps > BASIS_POINTS_PER_WHOLE
473:         || weather.intensity_bps > BASIS_POINTS_PER_WHOLE
474:         || weather.ground_moisture_bps > BASIS_POINTS_PER_WHOLE
475:         || weather.snow_cover_bps > BASIS_POINTS_PER_WHOLE
476:         || weather.atmosphere.relative_humidity_bps > BASIS_POINTS_PER_WHOLE
477:         || weather.atmosphere.dew_point_deci_c > weather.temperature_deci_c + 5
478:         || !(8_700..=10_850).contains(&weather.atmosphere.sea_level_pressure_deci_hpa)
479:         || weather.atmosphere.wind_direction_degrees >= 360
480:         || weather.atmosphere.wind_shear_bps > BASIS_POINTS_PER_WHOLE
481:         || weather.atmosphere.instability_bps > BASIS_POINTS_PER_WHOLE
482:         || !(-i16::try_from(BASIS_POINTS_PER_WHOLE).unwrap()
483:             ..=i16::try_from(BASIS_POINTS_PER_WHOLE).unwrap())
484:             .contains(&weather.atmosphere.lift_bps)
485:         || weather.cloud_layers().any(|layer| {
486:             layer.coverage_bps > BASIS_POINTS_PER_WHOLE
487:                 || layer.optical_density_bps > BASIS_POINTS_PER_WHOLE
488:                 || layer.top_metres <= layer.base_metres
489:         })
490:         || (matches!(weather.precipitation, Precipitation::Clear) && weather.intensity_bps != 0)
491:         || (!matches!(weather.precipitation, Precipitation::Clear)
492:             && (weather.intensity_bps == 0
493:                 || !weather.cloud_layers().any(|layer| {
494:                     matches!(
495:                         layer.form,
496:                         adventuresim_core::weather::CloudForm::Cumulonimbus
497:                             | adventuresim_core::weather::CloudForm::Nimbostratus
498:                     )
499:                 })))
500:     {

501:         return invalid(SceneValidationError::Weather);
502:     }
503:     Ok(())
504: }
505: 
506: fn invalid<T>(issue: SceneValidationError) -> SceneInputResult<T> {
507:     Err(SceneInputError::Validation(issue))
508: }
