11: impl TacticalSceneInput {
12:     pub fn generate(&self) -> Result<GeneratedTacticalScene, SceneInputError> {
13:         let mut generated = self.generate_unfurnished(GeneratedBuildingRecipes::default())?;
14:         generated
15:             .furniture
16:             .furnish_interiors(&generated.buildings)?;
17:         Ok(generated)
18:     }
19: 
20:     /// Generate terrain and outdoor assets before independent interior jobs.
21:     pub fn generate_unfurnished(
22:         &self,
23:         mut building_recipes: GeneratedBuildingRecipes,
24:     ) -> Result<GeneratedTacticalScene, SceneInputError> {
25:         let SupportedSceneTerrain {
26:             terrain,
27:             ground,
28:             buildings,
29:             obstacles,
30:             repairs,
31:         } = self.prepare_supported_terrain(&mut building_recipes)?;
32:         let terrain_patch = crate::scene_fault::generate(self.landform, &terrain)?;
33:         let furniture = furniture::generate(
34:             self,
35:             &buildings,
36:             &terrain,
37:             &ground,
38:             &obstacles,
39:             &mut building_recipes,
40:         )?;
41:         let gardens = gardens::generate(&self.gardens, &buildings, &terrain)?;
42:         let boundaries = compounds::generate(&self.compounds, &buildings, &terrain)?;
43:         Ok(GeneratedTacticalScene {
44:             digest: self.digest()?,
45:             terrain,
46:             ground,
47:             obstacles,
48:             terrain_patch,
49:             boundaries,
50:             gardens,
51:             buildings,
52:             building_recipes,
53:             furniture,
54:             repairs,
55:         })
56:     }
57: }
58: 
59: fn prepare_terrain(
60:     input: &TacticalSceneInput,
61:     width: usize,
62:     depth: usize,
63:     spacing: f32,
64:     heights: &mut [f32],
65:     environment: &mut [EnvironmentalSample],
66: ) -> Result<SceneRepairReport, SceneInputError> {
67:     let upsampled_height_samples = heights
68:         .len()
69:         .saturating_sub(input.playable.heights_metres.len())
70:         as u32;
71:     let microrelief_adjusted_samples =
72:         add_authoritative_microrelief(input.seed, width, depth, spacing, heights, environment);
73:     let mut repairs = repair_playable_terrain(width, depth, spacing, heights, environment)?;
74:     repairs.upsampled_height_samples = upsampled_height_samples;
75:     repairs.microrelief_adjusted_samples = microrelief_adjusted_samples;
76:     Ok(repairs)
77: }
78: 
79: fn generated_obstacles(input: &TacticalSceneInput) -> Vec<GeneratedObstacle> {
80:     input
81:         .playable
82:         .environment
83:         .iter()
84:         .enumerate()
85:         .filter_map(|(index, sample)| {
86:             let x = (index % usize::from(input.playable.width)) as u16;
87:             let z = (index / usize::from(input.playable.width)) as u16;
88:             let point = (Vec2::new(f32::from(x), f32::from(z))
89:                 - Vec2::new(
90:                     f32::from(input.playable.width - 1),
91:                     f32::from(input.playable.depth - 1),
92:                 ) * 0.5)
93:                 * input.playable.spacing_metres;
94:             if input.landform.is_some_and(|recipe| {
95:                 crate::scene_coordinates::ScenePlanPoint::try_from(point)
96:                     .is_ok_and(|point| recipe.transition_collar().contains(point))
97:             }) {
98:                 return None;
99:             }
100:             let context = [u64::from(x), u64::from(z)];
101:             let tree_roll = StreamId::new("scene.tree-placement")
102:                 .rng(input.seed, &context)
103:                 .index(usize::from(BASIS_POINTS_PER_WHOLE)) as u64;
104:             let rock_seed = StreamId::new("scene.rock-placement").seed(input.seed, &context);
105:             let rock_roll = StreamId::new("scene.rock-presence")
106:                 .rng(rock_seed, &[])
107:                 .index(usize::from(BASIS_POINTS_PER_WHOLE)) as u64;
108:             if tree_roll < u64::from(sample.canopy_bps) / 12 {
109:                 Some(GeneratedObstacle::Tree { x, z })
110:             } else if rock_roll < u64::from(sample.hilly_bps) / 20 && sample.water_bps < 5_000 {
111:                 Some(GeneratedObstacle::Rock {
112:                     x,
113:                     z,
114:                     recipe: rock_recipe(rock_seed),
115:                 })
116:             } else {
117:                 None
118:             }
119:         })
120:         .collect()
121: }
122: 
123: fn remove_reserved_obstacles(
124:     input: &TacticalSceneInput,
125:     obstacles: &mut Vec<GeneratedObstacle>,
126:     repairs: &mut SceneRepairReport,
127: ) {
128:     let before = obstacles.len();
129:     obstacles.retain(|obstacle| {
130:         let width = usize::from(input.playable.width);
131:         let depth = usize::from(input.playable.depth);
132:         match *obstacle {
133:             GeneratedObstacle::Tree { x, z } => {
134:                 !is_tree_camera_clearance_cell(usize::from(x), usize::from(z), depth)
135:             }
136:             GeneratedObstacle::Rock { x, z, .. } => {
137:                 !is_reserved_playability_cell(usize::from(x), usize::from(z), width, depth)
138:             }
139:         }
140:     });
141:     repairs.removed_corridor_obstacles = (before - obstacles.len()) as u32;
142: }
143: 
144: fn remove_building_obstacles(
145:     input: &TacticalSceneInput,
146:     terrain: &SceneTerrain,
147:     reservations: &[buildings::ObstacleReservation],
148:     obstacles: &mut Vec<GeneratedObstacle>,
149:     repairs: &mut SceneRepairReport,
150: ) -> SceneInputResult<()> {
151:     let before = obstacles.len();
152:     let terrain_extent = bevy::math::Vec2::new(terrain.width(), terrain.depth());
153:     let mut retained = Vec::with_capacity(obstacles.len());
154:     for obstacle in obstacles.iter().copied() {
155:         if !buildings::obstacle_intersects_building(
156:             obstacle,
157:             input.playable.spacing_metres,
158:             terrain_extent,
159:             reservations,
160:         )? {
161:             retained.push(obstacle);
162:         }
163:     }
164:     *obstacles = retained;
165:     repairs.removed_building_obstacles = (before - obstacles.len()) as u32;
166:     Ok(())
167: }
