14: /// Type-erased version of [`RuleFns`].
15: ///
16: /// Stored inside [`ReplicationRegistry`](super::ReplicationRegistry) after registration.
17: pub(crate) struct UntypedRuleFns {
18:     type_id: TypeId,
19:     type_name: ShortName<'static>,
20: 
21:     serialize: unsafe fn(),
22:     deserialize: unsafe fn(),
23:     deserialize_in_place: unsafe fn(),
24:     consume: unsafe fn(),
25: }
26: 
27: impl UntypedRuleFns {
28:     /// Restores the original [`RuleFns`] from which this type was created.
29:     ///
30:     /// # Safety
31:     ///
32:     /// The caller must ensure that the function is called with the same `C` with which this instance was created.
33:     pub(super) unsafe fn typed<C: Component>(&self) -> RuleFns<C> {
34:         debug_assert_eq!(
35:             self.type_id,
36:             TypeId::of::<C>(),
37:             "trying to call rule functions with `{}`, but they were created with `{}`",
38:             ShortName::of::<C>(),
39:             self.type_name,
40:         );
41: 
42:         RuleFns {
43:             serialize: unsafe { mem::transmute::<unsafe fn(), SerializeFn<C>>(self.serialize) },
44:             deserialize: unsafe {
45:                 mem::transmute::<unsafe fn(), DeserializeFn<C>>(self.deserialize)
46:             },
47:             deserialize_in_place: unsafe {
48:                 mem::transmute::<unsafe fn(), DeserializeInPlaceFn<C>>(self.deserialize_in_place)
49:             },
50:             consume: unsafe { mem::transmute::<unsafe fn(), ConsumeFn<C>>(self.consume) },
51:         }
52:     }
53: }
