55: impl<C: Component> From<RuleFns<C>> for UntypedRuleFns {
56:     fn from(value: RuleFns<C>) -> Self {
57:         // SAFETY: these functions won't be called until the type is restored.
58:         Self {
59:             type_id: TypeId::of::<C>(),
60:             type_name: ShortName::of::<C>(),
61:             serialize: unsafe { mem::transmute::<SerializeFn<C>, unsafe fn()>(value.serialize) },
62:             deserialize: unsafe {
63:                 mem::transmute::<DeserializeFn<C>, unsafe fn()>(value.deserialize)
64:             },
65:             deserialize_in_place: unsafe {
66:                 mem::transmute::<DeserializeInPlaceFn<C>, unsafe fn()>(value.deserialize_in_place)
67:             },
68:             consume: unsafe { mem::transmute::<ConsumeFn<C>, unsafe fn()>(value.consume) },
