73: /// Serialization and deserialization functions for a component.
74: ///
75: /// See also [`AppRuleExt`]
76: /// and [`ReplicationRule`](crate::shared::replication::rules::ReplicationRule).
77: pub struct RuleFns<C> {
78:     serialize: SerializeFn<C>,
79:     deserialize: DeserializeFn<C>,
80:     deserialize_in_place: DeserializeInPlaceFn<C>,
81:     consume: ConsumeFn<C>,
82: }
83: 
84: impl<C: Component> RuleFns<C> {
85:     /// Creates a new instance.
86:     ///
87:     /// For more details see [`AppRuleExt::replicate_with`].
88:     pub fn new(serialize: SerializeFn<C>, deserialize: DeserializeFn<C>) -> Self {
89:         Self {
90:             serialize,
91:             deserialize,
92:             deserialize_in_place: in_place_as_deserialize::<C>,
93:             consume: consume_as_deserialize,
94:         }
95:     }
96: 
97:     /// Like [`Self::default`], but converts the component into `T` before serialization
98:     /// and back into `C` after deserialization.
99:     ///
100:     /// For more details see [`AppRuleExt::replicate_as`].
101:     pub fn new_as<T>() -> Self
102:     where
103:         T: Serialize + DeserializeOwned,
104:         C: Clone + Into<T> + From<T>,
105:     {
106:         Self::new(serialize_as, deserialize_as)
107:     }
108: 
109:     /// Replaces default [`in_place_as_deserialize`] with a custom function.
110:     ///
111:     /// This function will be called when a component is already present on an entity.
112:     /// For insertion [`Self::deserialize`] will be called instead.
113:     pub fn with_in_place(mut self, deserialize_in_place: DeserializeInPlaceFn<C>) -> Self {
114:         self.deserialize_in_place = deserialize_in_place;
115:         self
116:     }
117: 
118:     /// Replaces the default [`consume_as_deserialize`] with a custom function.
119:     ///
120:     /// This function will be called to handle stale component updates for entities
121:     /// with a marker that indicates the entity's history should be consumed instead of discarded.
122:     ///
123:     /// If no markers on an entity request history, then stale updates will be skipped entirely
124:     /// by just advancing the cursor (without calling any consume functions).
125:     ///
126:     /// If you want to ignore a component, just use its expected size to advance the cursor
127:     /// without deserializing (but be careful if the component is dynamically sized).
128:     ///
129:     /// See [`MarkerConfig::need_history`](crate::shared::replication::receive_markers::MarkerConfig::need_history)
130:     /// for details.
131:     pub fn with_consume(mut self, consume: ConsumeFn<C>) -> Self {
132:         self.consume = consume;
133:         self
134:     }
135: 
136:     /// Serializes a component into a message.
137:     pub(super) fn serialize(
138:         &self,
139:         ctx: &mut SerializeCtx,
140:         component: &C,
141:         message: &mut Vec<u8>,
142:     ) -> Result<()> {
143:         (self.serialize)(ctx, component, message)
144:     }
145: 
146:     /// Deserializes a component from a message.
147:     ///
148:     /// Use this function when inserting a new component.
149:     pub fn deserialize(&self, ctx: &mut WriteCtx, message: &mut Bytes) -> Result<C> {
150:         (self.deserialize)(ctx, message)
151:     }
152: 
153:     /// Same as [`Self::deserialize`], but instead of returning a component, it updates the passed reference.
154:     ///
155:     /// Use this function for updating an existing component.
156:     pub fn deserialize_in_place(
157:         &self,
158:         ctx: &mut WriteCtx,
159:         component: &mut C,
160:         message: &mut Bytes,
161:     ) -> Result<()> {
162:         (self.deserialize_in_place)(self.deserialize, ctx, component, message)
163:     }
164: 
165:     /// Consumes a component from a message.
166:     pub(super) fn consume(&self, ctx: &mut WriteCtx, message: &mut Bytes) -> Result<()> {
167:         (self.consume)(self.deserialize, ctx, message)
168:     }
169: }
