179: impl<C: Component + Serialize + DeserializeOwned> Default for RuleFns<C> {
180:     /// Creates a new instance with default functions for a component.
181:     ///
182:     /// See also [`default_serialize`], [`default_deserialize`] and [`in_place_as_deserialize`].
183:     fn default() -> Self {
