188: /// Signature of component serialization functions.
189: pub type SerializeFn<C> = fn(&mut SerializeCtx, &C, &mut Vec<u8>) -> Result<()>;
190: 
191: /// Signature of component deserialization functions.
192: pub type DeserializeFn<C> = fn(&mut WriteCtx, &mut Bytes) -> Result<C>;
193: 
194: /// Signature of component in-place deserialization functions.
195: pub type DeserializeInPlaceFn<C> =
196:     fn(DeserializeFn<C>, &mut WriteCtx, &mut C, &mut Bytes) -> Result<()>;
197: 
198: /// Signature of component consume functions.
199: pub type ConsumeFn<C> = fn(DeserializeFn<C>, &mut WriteCtx, &mut Bytes) -> Result<()>;
200: 
201: /// Default component serialization function.
202: pub fn default_serialize<C: Component + Serialize>(
203:     _ctx: &mut SerializeCtx,
204:     component: &C,
205:     message: &mut Vec<u8>,
206: ) -> Result<()> {
207:     postcard_utils::to_extend_mut(component, message)?;
208:     Ok(())
209: }
210: 
211: /// Default component deserialization function.
212: pub fn default_deserialize<C: Component + DeserializeOwned>(
213:     ctx: &mut WriteCtx,
214:     message: &mut Bytes,
215: ) -> Result<C> {
216:     let mut component: C = postcard_utils::from_buf(message)?;
217:     C::map_entities(&mut component, ctx);
218:     Ok(component)
219: }
220: 
221: /// Default component in-place deserialization function.
222: ///
223: /// This implementation just assigns the value from the passed deserialization function.
224: pub fn in_place_as_deserialize<C: Component>(
225:     deserialize: DeserializeFn<C>,
226:     ctx: &mut WriteCtx,
227:     component: &mut C,
228:     message: &mut Bytes,
229: ) -> Result<()> {
230:     *component = (deserialize)(ctx, message)?;
231:     Ok(())
232: }
233: 
234: /// Default component consume function.
235: ///
236: /// This implementation just calls deserialization function and ignores its result.
237: pub fn consume_as_deserialize<C: Component>(
238:     deserialize: DeserializeFn<C>,
239:     ctx: &mut WriteCtx,
240:     message: &mut Bytes,
241: ) -> Result<()> {
242:     ctx.ignore_mapping = true;
243:     (deserialize)(ctx, message)?;
244:     ctx.ignore_mapping = false;
245:     Ok(())
246: }
247: 
248: /// Converts `C` into `T` and serializes it.
249: pub fn serialize_as<C: Component + Clone + Into<T>, T: Serialize>(
250:     _ctx: &mut SerializeCtx,

251:     component: &C,
252:     message: &mut Vec<u8>,
253: ) -> Result<()> {
254:     let serializable = component.clone().into();
255:     postcard_utils::to_extend_mut(&serializable, message)?;
256:     Ok(())
257: }
258: 
259: /// Deserializes `T` and converts it into `C`.
260: pub fn deserialize_as<C: Component + From<T>, T: DeserializeOwned>(
261:     ctx: &mut WriteCtx,
262:     message: &mut Bytes,
263: ) -> Result<C> {
264:     let deserialized: T = postcard_utils::from_buf(message)?;
265:     let mut component = deserialized.into();
266:     C::map_entities(&mut component, ctx);
267:     Ok(component)
268: }
269: 
270: /// Serializes a component diff.
271: pub fn serialize_diff<C: Diffable>(
272:     ctx: &mut SerializeCtx,
273:     component: &C,
274:     message: &mut Vec<u8>,
275: ) -> Result<()> {
276:     let last_changed = ctx.last_changed;
277:     let diff_cursor = ctx.diff_cursor;
278:     let history = ctx.get_or_default::<DiffHistory<C>>();
279: 
280:     let (index, diffs) = history.diffs_after(diff_cursor, last_changed);
281:     let delta = if diffs.len() == 0 {
282:         ComponentDeltaRef::Snapshot { index, component }
283:     } else {
284:         ComponentDeltaRef::Diffs { index, diffs }
285:     };
286: 
287:     postcard_utils::to_extend_mut(&delta, message)?;
288: 
289:     ctx.diff_cursor = Some(index);
290: 
291:     Ok(())
292: }
293: 
294: /// Deserializes a component diff.
295: ///
296: /// Deserializes only snapshots because it's called only when the component is missing.
297: pub fn deserialize_diff<C: Diffable>(ctx: &mut WriteCtx, message: &mut Bytes) -> Result<C> {
298:     match postcard_utils::from_buf(message)? {
299:         ComponentDelta::Snapshot {
300:             index,
301:             mut component,
302:         } => {
303:             let buffer = ctx.get_or_default::<DiffBuffer<C>>();
304:             buffer.set_last_applied(index);
305: 
306:             C::map_entities(&mut component, ctx);
307:             Ok(component)
308:         }
309:         ComponentDelta::Diffs { .. } => Err(format!(
310:             "cannot apply diffs to `{}` that is not present on the entity",
311:             ShortName::of::<C>()
312:         )
313:         .into()),
314:     }
315: }
316: /// Deserializes a component diff and applies it to the passed component.
317: ///
318: /// Snapshots replace the current component value and reset the diff buffer to
319: /// the snapshot's diff cursor. Diffs are buffered and applied only when
320: /// all preceding diffs have been received, ensuring diffs are applied once
321: /// and in order.
322: pub fn deserialize_diff_in_place<C: Diffable>(
323:     _deserialize: DeserializeFn<C>,
324:     ctx: &mut WriteCtx,
325:     component: &mut C,
326:     message: &mut Bytes,
327: ) -> Result<()> {
328:     match postcard_utils::from_buf(message)? {
329:         ComponentDelta::<C>::Snapshot {
330:             index,
331:             component: new_component,
332:         } => {
333:             let buffer = ctx.get_or_default::<DiffBuffer<C>>();
334:             buffer.set_last_applied(index);
335: 
336:             *component = new_component;
337:             C::map_entities(component, ctx);
338:         }
339:         ComponentDelta::<C>::Diffs { index, diffs } => {
340:             let buffer = ctx.get_or_default::<DiffBuffer<C>>();
341:             buffer.push(index, diffs);
342:             for diff in buffer.drain_ready() {
343:                 component.apply_diff(&diff)?;
344:             }
345:         }
346:     }
347:     Ok(())
348: }

