643: fn on_server_started(
644:     args: Res<Args>,
645:     scene_input: Res<LoadedSceneInput>,
646:     conn: Option<Res<SpacetimeDb>>,
647:     mut commands: Commands,
648:     server_addr: Single<&LocalAddr, With<AdventureSimulatorServer>>,
649: ) -> Result {
650:     info!("Server opened on {:?}", **server_addr);
651: 
652:     #[cfg(feature = "debug")]
653:     let generate_terrain = args.world_dump.is_none();
654:     #[cfg(not(feature = "debug"))]
655:     let generate_terrain = true;
656: 
657:     let input = &scene_input.0;
658:     // World-bounds walls are a pure function of the scene input's playable
659:     // area, so they're always (re)created rather than carried by a dump.
660:     let scene_width =
661:         f32::from(input.playable.width.saturating_sub(1)) * input.playable.spacing_metres;
662:     let scene_depth =
663:         f32::from(input.playable.depth.saturating_sub(1)) * input.playable.spacing_metres;
664: 
665:     if generate_terrain {
666:         info!("Creating a game scene for {}", args.scene_key);
667:         let generated = input.generate()?;
668:         info!(
669:             scene_digest = %generated.digest,
670:             schema_version = input.schema_version,
671:             generation_version = input.generation_version,
672:             source = ?input.source,
673:             obstacles = generated.obstacles.len(),
674:             upsampled_height_samples = generated.repairs.upsampled_height_samples,
675:             microrelief_adjusted_samples = generated.repairs.microrelief_adjusted_samples,
676:             adjusted_height_samples = generated.repairs.adjusted_height_samples,
677:             repaired_water_samples = generated.repairs.repaired_water_samples,
678:             removed_corridor_obstacles = generated.repairs.removed_corridor_obstacles,
679:             levelled_building_samples = generated.repairs.levelled_building_samples,
680:             removed_building_obstacles = generated.repairs.removed_building_obstacles,
681:             "Loaded deterministic tactical scene input"
682:         );
683:         let terrain = generated.terrain;
684:         let terrain_patch = generated.terrain_patch;
685:         let environment = input.environment_snapshot(generated.digest);
686:         scene_obstacles::spawn(
687:             &mut commands,
688:             generated.obstacles,
689:             &terrain,
690:             input.playable.spacing_metres,
691:         )?;
692:         openings::spawn_generated_buildings(
693:             &mut commands,
694:             generated.buildings,
695:             &input.establishments,
696:         )?;
697:         openings::spawn_generated_boundaries(&mut commands, generated.boundaries);
698:         for garden in generated.gardens {
699:             commands.spawn((garden, Transform::default()));
700:         }
701:         furniture::spawn(&mut commands, generated.furniture);
702:         terrain_collision::spawn_scene(
703:             &mut commands,
704:             input.scene_key.clone(),
705:             terrain,
706:             generated.ground,
707:             environment,
708:             terrain_patch.as_ref(),
709:             input.landform,
710:         );
711:     }
712:     scene_setup::spawn_world_bounds(&mut commands, scene_width, scene_depth);
713:     if let Some(conn) = conn {
714:         info!("Creating tactical server in stdb...");
715:         conn.reducers().create_tactical_server_for_request(
716:             args.mission_id.clone(),
717:             args.tactical_claim.clone(),
718:             args.addr.to_string(),
719:             default(),
720:         )?;
721:         // Strategic authority enrolls the mission's exact durable enemy
722:         // roster as part of server creation. ConnectedPlayer delivery
723:         // spawns those rows.
724:     }
725:     Ok(())
726: }

