5: pub(super) fn colliders(
6:     terrain: &SceneTerrain,
7:     recipe: Option<&TerrainLandformRecipe>,
8:     prepared: Option<&SceneTerrainPatch>,
9: ) -> Result<Vec<Collider>> {
10:     if let Some(patch) = prepared {
11:         return Ok(patch.colliders_with_terrain(terrain)?);
12:     }
13:     let Some(recipe) = recipe else {
14:         return Ok(terrain.colliders()?);
15:     };
16:     let patch = terrain_landform_patch(terrain, *recipe)?;
17:     Ok(patch.colliders_with_terrain(terrain)?)
18: }
19: 
20: pub(super) fn spawn_scene(
21:     commands: &mut Commands,
22:     scene_id: String,
23:     terrain: SceneTerrain,
24:     ground: SceneGround,
25:     environment: SceneEnvironment,
26:     terrain_patch: Option<&SceneTerrainPatch>,
27:     landform: Option<TerrainLandformRecipe>,
28: ) {
29:     let mut scene = commands.spawn((Replicated, SceneId(scene_id), ground, Transform::default()));
30:     scene.insert(environment);
31:     if let Some(recipe) = landform {
32:         scene.insert(recipe);
33:     }
34:     if let Some(patch) = terrain_patch {
35:         scene.insert(patch.clone());
36:     }
37:     // The observer receives the prepared patch and its recipe before it builds
38:     // independent collision bodies. Dump restoration regenerates that same
39:     // immutable product when no prepared patch is present.
40:     scene.insert(terrain);
41: }
42: 
43: /// Fires whenever `SceneTerrain` lands on any entity - via fresh procedural
44: /// generation in `on_server_started` or a loaded world dump
45: /// (`load_world_dump`). Derives independent static collision bodies from the
46: /// immutable terrain and adds the replication marker. Colliders aren't reflectable
47: /// and so never survives a dump on its own; a dump only needs to carry the
48: /// "core" `SceneId`/`SceneTerrain`/`Transform`.
49: pub(crate) fn on_scene_terrain_added(
50:     event: On<Add, SceneTerrain>,
51:     mut commands: Commands,
52:     query: Query<(
53:         &SceneTerrain,
54:         Option<&TerrainLandformRecipe>,
55:         Option<&SceneTerrainPatch>,
56:     )>,
57: ) -> Result {
58:     let (terrain, recipe, prepared) = query.get(event.entity)?;
59:     let colliders = terrain_collision::colliders(terrain, recipe, prepared)?;
60:     commands
61:         .entity(event.entity)
62:         .insert(Replicated)
63:         .remove::<SceneTerrainPatch>()
64:         .with_children(|parent| {
65:             for collider in colliders {
66:                 parent.spawn((
67:                     RigidBody::Static,
68:                     CollisionLayers::new(TACTICAL_TERRAIN_LAYER, LayerMask::ALL),
69:                     collider,
70:                     Transform::IDENTITY,
71:                 ));
72:             }
73:         });
74:     Ok(())
75: }

