593:             .find(|(_, _, properties)| properties.id == "sword")
594:             .expect("loaded world should contain the dumped inventory item");
595:         assert_eq!(
596:             item_of.0, loaded_entity,
597:             "the item's owner reference should point at the loaded character"
598:         );
599: 
600:         // Scene loading applies components with relationship hooks
601:         // silenced, so nothing rebuilds `InventoryItems` on load - the dump
602:         // must carry it, entity-mapped, like bevy's own `Children`. A
603:         // character loaded without it is silently naked and unarmed.
604:         let inventory = load_app
605:             .world()
606:             .entity(loaded_entity)
607:             .get::<InventoryItems>()
608:             .expect("the dumped character's InventoryItems should round-trip");
609:         assert!(
610:             inventory.iter().any(|item| item == loaded_item),
611:             "the loaded InventoryItems should reference the loaded (remapped) item entity"
612:         );
613:         assert_eq!(
614:             inventory.holding_weapon(),
615:             Some(loaded_item),
616:             "holding_weapon should round-trip and be remapped to the loaded item entity"
617:         );
618: 
619:         std::fs::remove_file(dump_path).ok();
620:     }
621: }
