80: pub(in crate::presentation) fn present_pending_terrain(
81:     mut commands: Commands,
82:     query: volumetric::PendingScenes,
83:     presentations: Query<
84:         (
85:             &ScenePresentationOf,
86:             &MeshMaterial3d<TacticalTerrainMaterial>,
87:         ),
88:         With<TerrainMaterialPresentation>,
89:     >,
90:     mut detail_presentations: Query<
91:         (
92:             &ScenePresentationOf,
93:             &MeshMaterial3d<TacticalTerrainMaterial>,
94:             &mut TerrainDetailPatch,
95:             &Mesh3d,
96:             &mut TerrainTriangleCount,
97:         ),
98:         With<TerrainDetailPatch>,
99:     >,
100:     mut meshes: ResMut<Assets<Mesh>>,
101:     mut materials: ResMut<Assets<TacticalTerrainMaterial>>,
102:     mut images: ResMut<Assets<Image>>,
103:     procedural_assets: Res<ProceduralTextureAssets>,
104:     graphics: Res<TacticalGraphicsSettings>,
105:     vista: Res<ActiveVistaSurface>,
106:     mut startup: Option<ResMut<crate::presentation::ClientStartupTiming>>,
107: ) {
108:     let mut prepared_first_terrain = false;
109:     for (entity, id, terrain, environment, ground, landform, prepared) in &query {
110:         let transition_collar = landform.map(|recipe| recipe.transition_collar());
111:         let presented = if let (
112:             Some((_, handle)),
113:             Some((_, detail_handle, mut patch, mesh_handle, mut triangle_count)),
114:         ) = (
115:             presentations.iter().find(|(source, _)| source.0 == entity),
116:             detail_presentations
117:                 .iter_mut()
118:                 .find(|(source, _, _, _, _)| source.0 == entity),
119:         ) {
120:             volumetric::refresh_presentation(
121:                 terrain,
122:                 environment,
123:                 ground,
124:                 &procedural_assets,
125:                 &graphics,
126:                 &vista,
127:                 transition_collar,
128:                 handle,
129:                 detail_handle,
130:                 &mut patch,
131:                 mesh_handle,
132:                 &mut triangle_count,
133:                 &mut meshes,
134:                 &mut materials,
135:                 &mut images,
136:             )
137:         } else {
138:             info!(?entity, "Spawning a scene {id:?}");
139:             volumetric::spawn_presentation(
140:                 &mut commands,
141:                 &mut meshes,
142:                 &mut materials,
143:                 &mut images,
144:                 &procedural_assets,
145:                 &graphics,
146:                 &vista,
147:                 entity,
148:                 id,
149:                 terrain,
150:                 environment,
151:                 ground,
152:                 landform,
153:                 prepared,
154:             )
155:             .map(|()| true)
156:         };
157:         match presented {
158:             Ok(true) => {
159:                 prepared_first_terrain = true;
160:                 commands
161:                     .entity(entity)
162:                     .remove::<PendingTerrainPresentation>();
163:             }
164:             Ok(false) => {}
165:             Err(error) => warn!(%error, ?entity, "Invalid terrain ground texture"),
166:         }
167:     }
168:     if prepared_first_terrain && let Some(startup) = startup.as_mut() {
169:         startup.mark_terrain_prepared_once();
170:     }
171: }
