1: //! Chunk-instanced rendering for dense scatter: grass, shrubs, loose stones
2: //! and distant tree cards.
3: //!
4: //! A batch is one mesh drawn many times. It is split into ground chunks, and
5: //! each chunk is an ordinary entity: Bevy's CPU frustum and range culling
6: //! decide which chunks a camera sees, and each visible chunk is one instanced
7: //! `draw_indexed` over its own instance buffer, uploaded once. Instances fade
8: //! in and out per instance in the shader, so crossfading distance bands hand
9: //! over pixel-exactly however the chunks fall. Chunks draw in the main pass
10: //! only, never in prepass or shadow passes.
11: mod draw;
12: mod instance;
13: mod material;
14: mod pipeline;
15: mod queue;
16: mod spawn;
17: 
18: use std::marker::PhantomData;
19: 
20: use bevy::{
21:     core_pipeline::core_3d::Opaque3d,
22:     pbr::MeshPipelineSystems,
23:     prelude::*,
24:     render::{
25:         Render, RenderApp, RenderStartup, RenderSystems,
26:         extract_component::ExtractComponentPlugin,
27:         render_asset::RenderAssetPlugin,
28:         render_phase::AddRenderCommand,
29:         render_resource::{BindGroupLayoutDescriptor, SpecializedMeshPipelines},
30:     },
31:     shader::load_shader_library,
32: };
33: 
34: pub(in crate::presentation) use instance::ChunkMaterial;
35: pub(crate) use instance::{ChunkInstance, FadeBand, InstanceChunk};
36: pub(in crate::presentation) use material::{ChunkInstancedMaterial, enable_alpha_to_coverage};
37: pub(in crate::presentation) use spawn::{ChunkSize, InstanceBatch, InstanceReach};
