39: /// The renderer shared by every chunk-instanced material; each
40: /// [`ChunkMaterialPlugin`] adds it once.
41: pub(in crate::presentation) struct ChunkInstancingPlugin;
42: 
43: /// Draws chunks whose [`ChunkMaterial`] is an `M`.
