29: fn compositor_camera(active: bool) -> Camera {
30:     Camera {
31:         order: COMPOSITOR_ORDER,
32:         is_active: active,
33:         clear_color: ClearColorConfig::Custom(Color::NONE),
34:         // 2D and HDR 3D views have separate intermediate textures. Preserve the
35:         // live view already written to the window when compositing captured images.
36:         output_mode: CameraOutputMode::Write {
37:             blend_state: Some(BlendState::PREMULTIPLIED_ALPHA_BLENDING),
