113:     app.init_resource::<CachedViews>().add_systems(
114:         PostUpdate,
115:         // Capture cameras are spawned here. Apply their final environment before
116:         // camera preparation/extraction can specialize transient default pipelines.
117:         (settle, super::views::sync_environment)
118:             .chain()
