124: #[derive(SystemParam)]
125: pub(super) struct CacheWorld<'w> {
126:     retained: ResMut<'w, CachedViews>,
127:     images: ResMut<'w, Assets<Image>>,
128: }
129: impl CacheWorld<'_> {
130:     pub(super) fn sync(
131:         &mut self,
132:         commands: &mut Commands,
133:         specs: &[ViewSpec],
134:         scene: &RetainedScene,
135:         view: Option<&StrategicView>,
136:         window: &Window,
137:     ) {
138:         let compositor = *self.retained.compositor.get_or_insert_with(|| {
139:             commands
140:                 .spawn((
141:                     Camera2d,
142:                     compositor_camera(view.is_some()),
143:                     Msaa::Off,
144:                     RenderLayers::layer(super::protocol::COMPOSITOR_LAYER),
145:                 ))
146:                 .id()
147:         });
148:         if self.retained.scene != scene.root {
149:             self.retained.change_scene(commands, scene);
150:         }
151:         for frame in self.retained.frames.values_mut() {
152:             commands.entity(frame.sprite).insert(Visibility::Hidden);
153:         }
154:         for spec in specs {
155:             let Some(key) = &spec.cache else {
156:                 continue;
157:             };
158:             let signature = Signature::new(spec, view);
159:             let changed = self
160:                 .retained
161:                 .frames
162:                 .get(key)
163:                 .is_none_or(|frame| frame.signature != signature);
164:             if changed {
165:                 if let Some(previous) = self.retained.frames.remove(key) {
166:                     if let Some(camera) = previous.camera {
167:                         deactivate(commands, camera);
168:                         self.retained.free_cameras.push(camera);
169:                     }
170:                     commands.entity(previous.sprite).despawn();
171:                 }
172:                 let frame = self.create(commands, spec, signature);
173:                 self.retained.frames.insert(key.clone(), frame);
174:             }
175:             let frame = self.retained.frames.get_mut(key).expect("created snapshot");
176:             frame.show(commands, spec, window);
177:         }
178:         let active = view.is_some();
179:         // Replacing Camera would erase its computed render-target metadata.
180:         // Bevy only recomputes that metadata on target/projection changes.
181:         commands.queue(move |world: &mut World| {
182:             if let Some(mut camera) = world.get_mut::<Camera>(compositor) {
183:                 camera.is_active = active;
184:             }
185:         });
186:     }
187: 
188:     fn create(&mut self, commands: &mut Commands, spec: &ViewSpec, signature: Signature) -> Frame {
189:         let rect = signature.rect;
190:         let image = self.images.add(Image::new_target_texture(
191:             rect.width.max(1),
192:             rect.height.max(1),
193:             TextureFormat::Rgba8UnormSrgb,
194:             None,
195:         ));
196:         let sprite = commands
197:             .spawn((
198:                 Sprite {
199:                     image: image.clone(),
200:                     custom_size: Some(Vec2::new(rect.width as f32, rect.height as f32)),
201:                     ..default()
202:                 },
203:                 RenderLayers::layer(super::protocol::COMPOSITOR_LAYER),
204:                 Visibility::Hidden,
205:             ))
206:             .id();
207:         Frame {
208:             camera: None,
209:             image,
210:             projection: spec.projection.clone(),
211:             layers: spec.layers.clone(),
212:             sprite,
213:             signature,
214:             remaining: CAPTURE_SETTLED_FRAMES,
215:         }
216:     }
217: }
218: 
219: impl Frame {
220:     fn start_capture(&mut self, commands: &mut Commands, reusable: Option<Entity>) {
221:         let rect = self.signature.rect;
222:         let mut camera = Camera {
223:             order: -1,
224:             clear_color: ClearColorConfig::Custom(Color::srgb(0.13, 0.16, 0.19)),
225:             ..default()
226:         };
227:         rect.apply(&mut camera, UVec2::new(rect.width, rect.height));
228:         let mut entity = match reusable {
229:             Some(camera) => commands.entity(camera),
230:             None => commands.spawn_empty(),
231:         };
232:         self.camera = Some(
233:             entity
234:                 .insert((
235:                     StrategicCamera,
236:                     crate::presentation::interior_lighting::FixedViewExposure,
237:                     SnapshotCamera,
238:                     Camera3d::default(),
239:                     camera,
240:                     RenderTarget::Image(self.image.clone().into()),
241:                     self.signature.transform,
242:                     self.projection.clone(),
243:                     self.layers.clone(),
244:                     Msaa::Off,
245:                     bevy::camera::Exposure::SUNLIGHT,
246:                 ))
247:                 .id(),
248:         );
249:     }
250: 
251:     fn show(&mut self, commands: &mut Commands, spec: &ViewSpec, window: &Window) {
252:         let scale = window.scale_factor();
253:         let rect = spec.rect;
254:         commands.entity(self.sprite).insert((
255:             Visibility::Inherited,
256:             Transform::from_xyz(
257:                 (rect.x as f32 + rect.width as f32 * 0.5) / scale - window.width() * 0.5,
258:                 window.height() * 0.5 - (rect.y as f32 + rect.height as f32 * 0.5) / scale,
259:                 0.0,
260:             )
261:             .with_scale(Vec3::splat(scale.recip())),
262:         ));
263:         if matches!(spec.cache, Some(ViewKey::Street)) {
264:             let sprite = self.sprite;
265:             commands.queue(move |world: &mut World| {
266:                 if let Some(mut sprite) = world.get_mut::<Sprite>(sprite) {
267:                     sprite.rect = Some(Rect::new(
268:                         rect.offset_x,
269:                         rect.offset_y,
270:                         rect.offset_x + rect.width as f32,
271:                         rect.offset_y + rect.height as f32,
272:                     ));
273:                     sprite.custom_size = Some(Vec2::new(rect.width as f32, rect.height as f32));
274:                 }
275:             });
276:         }
277:     }
278: }
279: 
280: fn deactivate(commands: &mut Commands, camera: Entity) {
281:     commands.queue(move |world: &mut World| {
282:         if let Some(mut camera) = world.get_mut::<Camera>(camera) {
283:             camera.is_active = false;
284:         }
285:     });
286: }
287: 
288: fn settle(
289:     mut commands: Commands,
290:     mut cached: ResMut<CachedViews>,
291:     ready: Res<super::status::SceneAssetsReady>,
292:     installed: Res<super::status::SceneInstallationReady>,
293:     mut previous_scene: Local<Option<Entity>>,
294:     mut cameras: Query<
295:         (&mut Camera, &bevy::camera::visibility::VisibleEntities),
296:         With<SnapshotCamera>,
297:     >,
298: ) {
299:     // Inactive Camera entities still consume Bevy's limited distance-visibility
300:     // slots. Reuse a bounded set for captures, retaining completed images.
301:     let cached = &mut *cached;
302:     // Installation status is published in Last. On city replacement it still
303:     // belongs to the prior root until that publication; defer warming one frame.
304:     let scene_changed = *previous_scene != cached.scene;
305:     *previous_scene = cached.scene;
306:     let may_prepare = installed.0 && !scene_changed;
307:     let mut active = 0;
308:     for frame in cached.frames.values_mut() {
309:         if frame.remaining == 0 {
310:             if let Some(camera) = frame.camera.take() {
311:                 if let Ok((mut view, _)) = cameras.get_mut(camera) {
312:                     view.is_active = false;
313:                 }
314:                 cached.free_cameras.push(camera);
315:             }
316:             continue;
317:         }
318:         let Some(camera) = frame.camera else {
319:             continue;
320:         };
321:         active += 1;
322:         if !ready.0 && frame.remaining > 0 {
323:             frame.remaining = CAPTURE_SETTLED_FRAMES;
324:         }
325:         if let Ok((mut camera, visible)) = cameras.get_mut(camera) {
326:             // Final geometry and lighting can warm these exact view pipelines
327:             // while equipment fits. Only complete assets advance the capture.
328:             camera.is_active = may_prepare;
329:             if camera.is_active && ready.0 {
330:                 if frame.remaining == 1 {
331:                     info!(
332:                         meshes = visible.len(std::any::TypeId::of::<Mesh3d>()),
333:                         "strategic snapshot captured"
334:                     );
335:                 }
336:                 frame.remaining = frame.remaining.saturating_sub(1);
337:             }
338:         }
339:     }
340:     if may_prepare {
341:         for frame in cached
342:             .frames
343:             .values_mut()
344:             .filter(|frame| frame.remaining > 0 && frame.camera.is_none())
345:             .take(CONCURRENT_CAPTURES.saturating_sub(active))
346:         {
347:             frame.start_capture(&mut commands, cached.free_cameras.pop());
348:         }
349:     }
350: }
