1: //! Multiple clipped camera views, all targeting the single game canvas.
2: use super::{
3:     RetainedScene,
4:     buildings::ROOM_LAYER,
5:     protocol::{CanvasRect, StrategicView},
6: };
7: pub(crate) use crate::presentation::canvas_view::StrategicCamera;
8: use adventuresim_building_generator::spatial_geometry::Position;
9: use adventuresim_tactical_core::scene_coordinates::Scene;
10: use bevy::{camera::visibility::RenderLayers, prelude::*};
11: 
12: #[derive(Resource, Default)]
13: pub(super) struct ViewCameras(Vec<Entity>);
14: 
15: const HEAD_HEIGHT_METRES: f32 = 1.65;
16: const PORTRAIT_DISTANCE_METRES: f32 = 0.30;
17: // Actor views retain nearby room/street context. The header alone needs the
18: // distant skyline; drawing that entire city behind an interior wastes GPU work.
19: const ACTOR_VIEW_DISTANCE_METRES: f32 = 128.0;
20: use super::staging::CONVERSATION_DISTANCE_METRES;
21: 
22: pub(super) struct ViewSpec {
23:     pub cache: Option<super::cached_views::ViewKey>,
24:     pub rect: CanvasRect,
25:     pub transform: Transform,
26:     pub projection: Projection,
27:     pub layers: RenderLayers,
28: }
29: 
30: pub(super) fn person_view(
31:     rect: CanvasRect,
32:     anchor: Position<Scene>,
33:     facing: Quat,
34:     portrait: bool,
35:     layers: RenderLayers,
36: ) -> ViewSpec {
37:     let target = anchor.metres() + Vec3::Y * if portrait { HEAD_HEIGHT_METRES } else { 1.2 };
38:     let distance = if portrait {
39:         PORTRAIT_DISTANCE_METRES
40:     } else {
41:         CONVERSATION_DISTANCE_METRES
42:     };
43:     ViewSpec {
44:         cache: None,
45:         rect,
46:         transform: Transform::from_translation(target + facing * Vec3::Z * distance)
47:             .looking_at(target, Vec3::Y),
48:         projection: PerspectiveProjection {
49:             fov: crate::presentation::TacticalCameraSetup::default()
50:                 .vertical_fov_degrees
51:                 .to_radians(),
52:             near: 0.05,
53:             far: ACTOR_VIEW_DISTANCE_METRES,
54:             ..default()
55:         }
56:         .into(),
57:         layers,
58:     }
59: }
60: 
61: pub(super) fn sync_views(
62:     mut commands: Commands,
63:     requested: Option<Res<StrategicView>>,
64:     scene: Res<RetainedScene>,
65:     mut retained: ResMut<ViewCameras>,
66:     mut cache: super::cached_views::CacheWorld,
67:     windows: Query<&Window>,
68:     mut cameras: Query<
69:         (
70:             &mut Camera,
71:             &mut Transform,
72:             &mut Projection,
73:             &mut RenderLayers,
74:         ),
75:         With<StrategicCamera>,
76:     >,
77: ) {
78:     let Some(window) = windows.iter().next() else {
79:         return;
80:     };
81:     if requested.as_ref().is_some_and(|view| !view.is_changed()) && !scene.is_changed() {
82:         return;
83:     }
84:     let size = window.resolution.physical_size();
85:     let specs = view_specs(requested.as_deref(), &scene);
86:     cache.sync(&mut commands, &specs, &scene, requested.as_deref(), window);
87:     let live = specs
88:         .iter()
89:         .filter(|spec| spec.cache.is_none())
90:         .collect::<Vec<_>>();
91:     for (index, spec) in live.iter().enumerate() {
92:         if let Some(entity) = retained.0.get(index)
93:             && let Ok((mut camera, mut transform, mut projection, mut layers)) =
94:                 cameras.get_mut(*entity)
95:         {
96:             spec.rect.apply(&mut camera, size);
97:             *transform = spec.transform;
98:             *projection = spec.projection.clone();
99:             *layers = spec.layers.clone();
100:         } else {
101:             let mut camera = Camera {
102:                 order: index as isize + 1,
103:                 clear_color: ClearColorConfig::Custom(Color::srgb(0.13, 0.16, 0.19)),
104:                 ..default()
105:             };
106:             spec.rect.apply(&mut camera, size);
107:             retained.0.push(
108:                 commands
109:                     .spawn((
110:                         StrategicCamera,
111:                         crate::presentation::interior_lighting::FixedViewExposure,
112:                         Camera3d::default(),
113:                         camera,
114:                         spec.transform,
115:                         spec.projection.clone(),
116:                         spec.layers.clone(),
117:                         Msaa::Off,
118:                         bevy::camera::Exposure::SUNLIGHT,
119:                     ))
120:                     .id(),
121:             );
122:         }
123:     }
124:     for entity in retained.0.iter().skip(live.len()) {
125:         if let Ok((mut camera, ..)) = cameras.get_mut(*entity) {
126:             camera.is_active = false;
127:         }
128:     }
129: }
130: 
131: fn view_specs(view: Option<&StrategicView>, scene: &RetainedScene) -> Vec<ViewSpec> {
132:     let mut specs = Vec::new();
133:     if let Some(view) = view {
134:         if let Some(rect) = view.street
135:             && let Some(street) = &scene.street
136:         {
137:             specs.push(ViewSpec {
138:                 cache: Some(super::cached_views::ViewKey::Street),
139:                 rect,
140:                 transform: street.camera(),
141:                 projection: PerspectiveProjection {
142:                     near: 0.1,
143:                     fov: street.vertical_fov(),
144:                     far: 60_000.0,
145:                     ..default()
146:                 }
147:                 .into(),
148:                 layers: RenderLayers::default(),
149:             });
150:         }
151:         if let Some(rect) = view.stage {
152:             let subject = view.stage_subject();
153:             let anchor = subject
154:                 .and_then(|id| scene.people.get(&id).map(|person| person.anchor))
155:                 .or_else(|| {
156:                     view.active_place
157:                         .as_ref()
158:                         .and_then(|id| scene.venues.get(id))
159:                         .map(|v| v.anchor)
160:                 });
161:             if let Some(anchor) = anchor {
162:                 let layers = focused_layers(scene, subject);
163:                 let facing = subject
164:                     .and_then(|id| scene.people.get(&id))
165:                     .map_or(Quat::IDENTITY, |person| person.facing);
166:                 specs.push(person_view(rect, anchor, facing, false, layers));
167:             }
168:         }
169:         let mut portrait_slots = std::collections::HashMap::new();
170:         for portrait in &view.portraits {
171:             if let Some(person) = scene.people.get(&portrait.id) {
172:                 let mut spec = person_view(
173:                     portrait.rect,
174:                     person.anchor,
175:                     person.facing,
176:                     true,
177:                     focused_layers(scene, Some(portrait.id)),
178:                 );
179:                 let slot = portrait_slots.entry(portrait.id).or_insert(0);
180:                 spec.cache = Some(super::cached_views::ViewKey::Portrait {
181:                     person: portrait.id,
182:                     slot: *slot,
183:                 });
184:                 *slot += 1;
185:                 specs.push(spec);
186:             }
187:         }
188:     }
189:     specs
190: }
191: 
192: pub(super) fn focused_layers(
193:     scene: &RetainedScene,
194:     selected: Option<super::protocol::PortraitId>,
195: ) -> RenderLayers {
196:     let mut layers = RenderLayers::layer(ROOM_LAYER);
197:     for (id, person) in &scene.people {
198:         if selected.is_none_or(|selected| selected == *id) {
199:             layers = layers.with(person.layer);
200:         }
201:     }
202:     layers
203: }
204: 
205: /// Copy the tactical camera's actual sky, exposure and post-processing state.
206: /// The gameplay marker remains unique for input and environment bake systems.
207: #[expect(
208:     clippy::type_complexity,
209:     reason = "Camera appearance is inherited from the single tactical camera"
210: )]
211: pub(super) fn sync_environment(
212:     mut commands: Commands,
213:     source: Query<
214:         (
215:             Ref<bevy::camera::Exposure>,
216:             Ref<bevy::core_pipeline::tonemapping::Tonemapping>,
217:             Ref<bevy::pbr::DistanceFog>,
218:             Ref<Msaa>,
219:             Ref<bevy::light::ShadowFilteringMethod>,
220:             Option<Ref<EnvironmentMapLight>>,
221:             Option<Ref<bevy::pbr::AtmosphereSettings>>,
222:         ),
223:         With<crate::presentation::TacticalGameplayCamera>,
224:     >,
225:     targets: Query<(
226:         Entity,
227:         Ref<StrategicCamera>,
228:         Option<&crate::presentation::RegionalMapCamera>,
229:     )>,
230: ) {
231:     let Ok((exposure, tone, fog, msaa, shadows, environment, atmosphere)) = source.single() else {
232:         return;
233:     };
234:     let changed = exposure.is_changed()
235:         || tone.is_changed()
236:         || fog.is_changed()
237:         || msaa.is_changed()
238:         || shadows.is_changed()
239:         || environment.as_ref().is_some_and(|value| value.is_changed())
240:         || atmosphere.as_ref().is_some_and(|value| value.is_changed());
241:     for (entity, marker, map) in &targets {
242:         // A reused snapshot camera reinserts its marker and camera defaults.
243:         // Restore the final settings before extraction, just as for a new view.
244:         if !changed && !marker.is_changed() {
245:             continue;
246:         }
247:         let mut target = commands.entity(entity);
248:         target.insert((*exposure, *tone, *msaa, *shadows));
249:         // Continental views must not inherit the street camera's fog reach or
250:         // atmosphere depth reconstruction. Lighting and asset residency are shared.
251:         if map.is_some() {
252:             target.remove::<(bevy::pbr::DistanceFog, bevy::pbr::AtmosphereSettings)>();
253:         } else {
254:             target.insert((*fog).clone());
255:             if let Some(atmosphere) = &atmosphere {
256:                 target.insert((**atmosphere).clone());
257:             }
258:         }
259:         if let Some(environment) = &environment {
260:             target.insert((**environment).clone());
261:         }
262:     }
263: }
