 98 fn retain_people(
 99     mut commands: Commands,
100     requested: Option<Res<StrategicView>>,
101     mut scene: ResMut<RetainedScene>,
102 ) {
103     let Some(view) = requested else {
104         return;
105     };
106     if !view.is_changed() && !scene.is_changed() {
107         return;
108     }
109     let Some(root) = scene.root else {
110         return;
111     };
112     scene.people.retain(|id, person| {
113         let keep = view.people.iter().any(|person| person.id == *id);
114         if !keep {
115             commands.entity(person.entity).despawn();
116         }
117         keep
118     });
119     for person in &view.people {
120         let Some(venue) = scene.venues.get(&person.place) else {
121             continue;
122         };
123         // Each resident has a stable position within their venue, shared by all views.
124         let rank = view
125             .people
126             .iter()
127             .filter(|other| {
128                 other.place == person.place && other.presentation == person.presentation
129             })
130             .position(|other| other.id == person.id)
131             .unwrap_or(0);
132         let pose = venue.positions[rank % venue.positions.len()];
133         let anchor = pose.anchor;
134         let facing = pose.facing;
135         if let Some(current) = scene.people.get_mut(&person.id) {
136             if current.anchor != anchor || current.facing != facing {
137                 current.anchor = anchor;
138                 current.facing = facing;
139                 commands
140                     .entity(current.entity)
141                     .insert(model_transform(anchor).with_rotation(facing));
142             }
143             continue;
144         }
145         // A selected ID alone has no visible camera on map or forge pages.
146         // Keep visited actors, but only install a new rig and wardrobe when
147         // a requested stage or portrait can actually show it.
148         if !view.requires_person(person.id) {
149             continue;
150         }
151         let layer = protocol::FIRST_PERSON_LAYER + scene.next_person_layer;
152         scene.next_person_layer += 1;
153         let entity = commands
154             .spawn((
155                 StrategicModel,
156                 SceneModel(layer),
157                 CharacterId(person.id.0),
158                 SkeletonState::default(),
159                 model_transform(anchor).with_rotation(facing),
160                 Visibility::Inherited,
161                 RenderLayers::none().with(layer),
162                 ChildOf(root),
163             ))
164             .id();
165         scene.people.insert(
166             person.id,
167             RetainedPerson {
168                 entity,
169                 anchor,
170                 facing,
171                 layer,
172             },
173         );
174     }
175 }
