203 fn inherit_model_layers(
204     mut commands: Commands,
205     added: Query<Entity, (With<Mesh3d>, Without<RenderLayers>)>,
206     parents: Query<&ChildOf>,
207     models: Query<&SceneModel>,
208     equipment_roots: Query<&crate::equipment::ItemPlaceholder>,
209     owners: Query<&adventuresim_tactical_core::prelude::ItemOf>,
210 ) {
211     for entity in &added {
212         let mut current = entity;
213         while let Ok(parent) = parents.get(current) {
214             current = parent.parent();
215             let equipment_owner = equipment_roots
216                 .get(current)
217                 .ok()
218                 .and_then(|item| owners.get(item.0).ok())
219                 .map(|owner| owner.0);
220             if let Ok(model) = models
221                 .get(current)
222                 .or_else(|_| models.get(equipment_owner.unwrap_or(current)))
223             {
224                 commands
225                     .entity(entity)
226                     .insert((RenderLayers::none().with(model.0), SceneMesh));
227                 break;
228             }
229         }
230     }
231 }
