234     clippy::type_complexity,
235     reason = "Bevy query selects strategic meshes that need initial culling bounds"
236 )]
237 fn cull_equipment(
238     mut commands: Commands,
239     meshes: Res<Assets<Mesh>>,
240     equipment: Query<
241         (Entity, &Mesh3d),
242         (
243             With<SceneMesh>,
244             With<bevy::camera::visibility::NoFrustumCulling>,
245         ),
246     >,
247 ) {
248     // Strategic actors only idle in place. A conservative margin covers the
249     // idle motion and identity morphs while excluding other venues' equipment.
250     const IDLE_BOUNDS_MARGIN_METRES: f32 = 0.4;
251     use bevy::camera::{primitives::MeshAabb, visibility::NoAutoAabb};
252     for (entity, mesh) in &equipment {
253         let Some(mut bounds) = meshes.get(&mesh.0).and_then(MeshAabb::compute_aabb) else {
254             continue;
255         };
256         bounds.half_extents += bevy::math::Vec3A::splat(IDLE_BOUNDS_MARGIN_METRES);
257         commands
258             .entity(entity)
259             .insert((bounds, NoAutoAabb))
260             .remove::<bevy::camera::visibility::NoFrustumCulling>();
261     }
262 }
