268 fn sync_room_lights(
269     mut commands: Commands,
270     scene: Res<RetainedScene>,
271     lights: Query<(Entity, Option<&RenderLayers>), Or<(With<DirectionalLight>, With<PointLight>)>>,
272 ) {
273     let layers = RenderLayers::from_iter(
274         std::iter::once(buildings::ROOM_LAYER)
275             .chain(scene.people.values().map(|person| person.layer)),
276     );
277     for (entity, current) in &lights {
278         if current.is_none_or(|current| current.iter().any(|layer| layer == buildings::ROOM_LAYER))
279             && current != Some(&layers)
280         {
281             commands.entity(entity).insert(layers.clone());
282         }
283     }
284 }
