 15 const HEAD_HEIGHT_METRES: f32 = 1.65;
 16 const PORTRAIT_DISTANCE_METRES: f32 = 0.30;
 17 // Actor views retain nearby room/street context. The header alone needs the
 18 // distant skyline; drawing that entire city behind an interior wastes GPU work.
 19 const ACTOR_VIEW_DISTANCE_METRES: f32 = 128.0;
 20 use super::staging::CONVERSATION_DISTANCE_METRES;
