131 fn view_specs(view: Option<&StrategicView>, scene: &RetainedScene) -> Vec<ViewSpec> {
132     let mut specs = Vec::new();
133     if let Some(view) = view {
134         if let Some(rect) = view.street
135             && let Some(street) = &scene.street
136         {
137             specs.push(ViewSpec {
138                 cache: Some(super::cached_views::ViewKey::Street),
139                 rect,
140                 transform: street.camera(),
141                 projection: PerspectiveProjection {
142                     near: 0.1,
143                     fov: street.vertical_fov(),
144                     far: 60_000.0,
145                     ..default()
146                 }
147                 .into(),
148                 layers: RenderLayers::default(),
149             });
150         }
151         if let Some(rect) = view.stage {
152             let subject = view.stage_subject();
153             let anchor = subject
154                 .and_then(|id| scene.people.get(&id).map(|person| person.anchor))
155                 .or_else(|| {
156                     view.active_place
157                         .as_ref()
158                         .and_then(|id| scene.venues.get(id))
159                         .map(|v| v.anchor)
160                 });
161             if let Some(anchor) = anchor {
162                 let layers = focused_layers(scene, subject);
163                 let facing = subject
164                     .and_then(|id| scene.people.get(&id))
165                     .map_or(Quat::IDENTITY, |person| person.facing);
166                 specs.push(person_view(rect, anchor, facing, false, layers));
167             }
168         }
169         let mut portrait_slots = std::collections::HashMap::new();
170         for portrait in &view.portraits {
171             if let Some(person) = scene.people.get(&portrait.id) {
172                 let mut spec = person_view(
173                     portrait.rect,
174                     person.anchor,
175                     person.facing,
176                     true,
177                     focused_layers(scene, Some(portrait.id)),
178                 );
179                 let slot = portrait_slots.entry(portrait.id).or_insert(0);
180                 spec.cache = Some(super::cached_views::ViewKey::Portrait {
181                     person: portrait.id,
182                     slot: *slot,
183                 });
184                 *slot += 1;
185                 specs.push(spec);
186             }
187         }
188     }
189     specs
190 }
