192 pub(super) fn focused_layers(
193     scene: &RetainedScene,
194     selected: Option<super::protocol::PortraitId>,
195 ) -> RenderLayers {
196     let mut layers = RenderLayers::layer(ROOM_LAYER);
197     for (id, person) in &scene.people {
198         if selected.is_none_or(|selected| selected == *id) {
199             layers = layers.with(person.layer);
200         }
201     }
202     layers
203 }
