125 pub(super) struct CacheWorld<'w> {
126     retained: ResMut<'w, CachedViews>,
127     images: ResMut<'w, Assets<Image>>,
128 }
129 impl CacheWorld<'_> {
130     pub(super) fn sync(
131         &mut self,
132         commands: &mut Commands,
133         specs: &[ViewSpec],
134         scene: &RetainedScene,
135         view: Option<&StrategicView>,
136         window: &Window,
137     ) {
138         let compositor = *self.retained.compositor.get_or_insert_with(|| {
139             commands
140                 .spawn((
141                     Camera2d,
142                     compositor_camera(view.is_some()),
143                     Msaa::Off,
144                     RenderLayers::layer(super::protocol::COMPOSITOR_LAYER),
145                 ))
146                 .id()
147         });
148         if self.retained.scene != scene.root {
149             self.retained.change_scene(commands, scene);
150         }
151         for frame in self.retained.frames.values_mut() {
152             commands.entity(frame.sprite).insert(Visibility::Hidden);
153         }
154         for spec in specs {
155             let Some(key) = &spec.cache else {
156                 continue;
157             };
158             let signature = Signature::new(spec, view);
159             let changed = self
160                 .retained
161                 .frames
162                 .get(key)
163                 .is_none_or(|frame| frame.signature != signature);
164             if changed {
165                 if let Some(previous) = self.retained.frames.remove(key) {
166                     if let Some(camera) = previous.camera {
167                         deactivate(commands, camera);
168                         self.retained.free_cameras.push(camera);
169                     }
170                     commands.entity(previous.sprite).despawn();
171                 }
172                 let frame = self.create(commands, spec, signature);
173                 self.retained.frames.insert(key.clone(), frame);
174             }
175             let frame = self.retained.frames.get_mut(key).expect("created snapshot");
176             frame.show(commands, spec, window);
177         }
178         let active = view.is_some();
179         // Replacing Camera would erase its computed render-target metadata.
180         // Bevy only recomputes that metadata on target/projection changes.
181         commands.queue(move |world: &mut World| {
182             if let Some(mut camera) = world.get_mut::<Camera>(compositor) {
183                 camera.is_active = active;
184             }
185         });
186     }
187 
188     fn create(&mut self, commands: &mut Commands, spec: &ViewSpec, signature: Signature) -> Frame {
189         let rect = signature.rect;
190         let image = self.images.add(Image::new_target_texture(
191             rect.width.max(1),
192             rect.height.max(1),
193             TextureFormat::Rgba8UnormSrgb,
194             None,
195         ));
196         let sprite = commands
197             .spawn((
198                 Sprite {
199                     image: image.clone(),
200                     custom_size: Some(Vec2::new(rect.width as f32, rect.height as f32)),
201                     ..default()
202                 },
203                 RenderLayers::layer(super::protocol::COMPOSITOR_LAYER),
204                 Visibility::Hidden,
205             ))
206             .id();
207         Frame {
208             camera: None,
209             image,
210             projection: spec.projection.clone(),
211             layers: spec.layers.clone(),
212             sprite,
213             signature,
214             remaining: CAPTURE_SETTLED_FRAMES,
215         }
216     }
217 }
