 80 pub(super) fn on_scene_vista_bundle(
 81     bundle: On<SceneVistaBundle>,
 82     mut commands: Commands,
 83     mut active_surface: ResMut<ActiveVistaSurface>,
 84     mut pending: ResMut<pending::PendingVista>,
 85     existing: Query<Entity, With<VistaTerrain>>,
 86     playable_scenes: Query<(
 87         &SceneTerrain,
 88         &SceneGround,
 89         &SceneEnvironment,
 90         Option<&TerrainLandformRecipe>,
 91     )>,
 92     settings: Res<TacticalGraphicsSettings>,
 93     mut meshes: ResMut<Assets<Mesh>>,
 94     mut materials: ResMut<Assets<TacticalVistaMaterial>>,
 95     mut grass_materials: ResMut<Assets<TacticalGrassInstancedMaterial>>,
 96     mut standard_materials: ResMut<Assets<StandardMaterial>>,
 97     mut tree_materials: tree_cards::VistaTreeMaterials,
 98     mut images: ResMut<Assets<Image>>,
 99     mut vista_tree_cache: ResMut<VistaTreePresentationCache>,
100     prepared_tree_impostors: PreparedTreeImpostors,
101     mut city_ground: streets::CityGroundAssets,
102 ) {
103     let playable_scene = playable_scenes
104         .iter()
105         .find(|(_, _, environment, _)| environment.scene_digest == bundle.scene_digest);
106     if !pending.accept(&bundle, playable_scene.iter().map(|scene| scene.2)) {
107         return;
108     }
109     let Some((terrain, ground, environment, landform)) = playable_scene else {
110         return;
111     };
112     let started = web_time::Instant::now();
113     let mut presented_chunk_count = 0_usize;
114     info!("Generating tactical vista presentation");
115     let visible_lods = bundle
116         .lods
117         .iter()
118         .take(settings.config.rendering.vista.maximum_lods)
119         .collect::<Vec<_>>();
120     let prepared = match PreparedVistaLod::prepare_all(
121         &visible_lods,
122         bundle.playable_half_extent_metres,
123         terrain,
124         environment,
125         landform,
126     ) {
127         Ok(prepared) => prepared,
128         Err(error) => {
129             warn!(%error, "Rejected tactical vista preparation");
130             return;
131         }
132     };
133     active_surface.update(&bundle);
134     for entity in &existing {
135         commands.entity(entity).despawn();
136     }
137     active_surface.retain_playable(terrain, landform);
138     let weather = environment.weather;
139     let vista_grass_color = grass_terminal_pigment(environment);
140     let material = materials.add(vista_material(weather, vista_grass_color));
141     for prepared in prepared {
142         let lod = prepared.lod;
143         for (chunk, mesh) in prepared.meshes.into_iter().enumerate() {
144             presented_chunk_count += 1;
145             active_surface.present_chunk(
146                 &mut commands,
147                 &mut meshes,
148                 material.clone(),
149                 mesh,
150                 lod,
151                 chunk,
152             );
153         }
154         if prepared.scenery == VistaSceneryRange::Near {
155             spawn_vista_trees(
156                 &mut commands,
157                 lod,
158                 prepared.coarser,
159                 prepared.inner_half_extent,
160                 &bundle.scene_digest,
161                 Some(environment),
162                 terrain,
163                 &mut meshes,
164                 &mut tree_materials,
165                 &mut images,
166                 &mut vista_tree_cache,
167                 prepared_tree_impostors.get(),
168             );
169         }
170     }
171     if let Some(lod) = visible_lods.first().copied() {
172         spawn_near_vista_details(
173             &mut commands,
174             &bundle,
175             &active_surface,
176             lod,
177             visible_lods.get(1).copied(),
178             terrain,
179             ground,
180             environment,
181             &mut meshes,
182             &mut grass_materials,
183             &mut standard_materials,
184             &mut images,
185             &settings.config.grass,
186             &mut city_ground,
187         );
188     }
189     log_vista_generation(presented_chunk_count, visible_lods.len(), started);
190 }
