 75     pub(crate) fn height_at(&self, point: ScenePlanPoint) -> Option<SupportElevation> {
 76         if let Some(height) = self.terrain.height_at(point) {
 77             return Some(height);
 78         }
 79         let mut inner = Vec2::new(self.terrain.width(), self.terrain.depth()) * 0.5;
 80         for (index, lod) in self.lods.iter().enumerate() {
 81             let height = adventuresim_tactical_core::vista_surface::sampled_vista_triangle_height(
 82                 lod,
 83                 self.lods.get(index + 1),
 84                 (index == 0).then_some(&self.terrain),
 85                 inner,
 86                 point,
 87             );
 88             if height.is_some() {
 89                 return height;
 90             }
 91             inner = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
 92                 * lod.spacing_metres
 93                 * 0.5;
 94         }
 95         None
 96     }
