 99 impl PreparedBackdrop {
100     pub(crate) fn new(
101         backdrop: StrategicBackdrop,
102         environment: SceneEnvironment,
103     ) -> BackdropResult<Self> {
104         let mut chunks = Vec::new();
105         let mut mesh = backdrop.terrain.mesh();
106         mesh.remove_attribute(Mesh::ATTRIBUTE_UV_0);
107         let foreground = backdrop
108             .foreground
109             .iter()
110             .map(|sample| pigment::vista_sample_color(*sample, environment.weather).to_array())
111             .collect::<Vec<_>>();
112         mesh.insert_attribute(Mesh::ATTRIBUTE_COLOR, foreground.clone());
113         chunks.push(BackdropChunk {
114             mesh,
115             origin: Vec3::ZERO,
116         });
117         let lods = backdrop.lods.iter().collect::<Vec<_>>();
118         let mut inner = Vec2::new(backdrop.terrain.width(), backdrop.terrain.depth()) * 0.5;
119         for (index, lod) in lods.iter().copied().enumerate() {
120             for mut mesh in natural::sampled_vista_lod_meshes_with_morph(
121                 lod,
122                 inner,
123                 lods.get(index + 1).copied(),
124                 (index == 0).then_some(&backdrop.terrain),
125                 None,
126                 environment.weather,
127             )? {
128                 if index == 0 {
129                     backdrop.stitch_colors(&mut mesh, &foreground, lod.spacing_metres);
130                 }
131                 let origin = Vec3::new(
132                     lod.origin_east_metres as f32,
133                     0.0,
134                     lod.origin_north_metres as f32,
135                 );
136                 chunks.push(BackdropChunk { mesh, origin });
137             }
138             inner = Vec2::new(f32::from(lod.width - 1), f32::from(lod.depth - 1))
139                 * lod.spacing_metres
140                 * 0.5;
141         }
142         Ok(Self {
143             backdrop,
144             environment,
145             chunks,
146         })
147     }
