163                     .resource_mut::<Assets<TacticalVistaMaterial>>()
164                     .add(vista_material(
165                         environment.weather,
166                         grass_terminal_pigment(&environment),
167                     ));
168             for chunk in chunks {
169                 spawn_mesh(world, root, chunk.mesh, material.clone(), chunk.origin);
170             }
171         });
172     }
