1060         // Map Frustum type to shader array<vec4<f32>, 6>
1061         let frustum = frustum
1062             .map(|frustum| frustum.half_spaces.map(|h| h.normal_d()))
1063             .unwrap_or([Vec4::ZERO; 6]);
