   1 //! A minimal read-only zip archive reader.
   2 //!
   3 //! Stored and deflated members, zip64 included. Lives here because `.npz` is a
   4 //! zip of `.npy` members, and is public because PyTorch archives are zips too:
   5 //! `burn-torch-storage` reads `.pt`/`.ckpt` through this same code rather than
   6 //! carrying a second copy of the central-directory parser.
   7 //!
   8 //! Stored members are handed back as borrowed slices of the mapping, so reading
   9 //! a multi-gigabyte tensor storage costs no copy.
  10 
  11 use std::borrow::Cow;
  12 use std::io::Read;
  13 use std::path::Path;
  14 
  15 use anyhow::{Context, Result, bail};
  16 use flate2::read::DeflateDecoder;
  17 use memmap2::Mmap;
  18 
  19 enum ArchiveData {
  20     Mapped(Mmap),
  21     Owned(Vec<u8>),
  22 }
  23 
  24 impl AsRef<[u8]> for ArchiveData {
  25     fn as_ref(&self) -> &[u8] {
  26         match self {
  27             Self::Mapped(data) => data,
  28             Self::Owned(data) => data,
  29         }
  30     }
  31 }
  32 
  33 impl std::ops::Deref for ArchiveData {
  34     type Target = [u8];
  35 
  36     fn deref(&self) -> &Self::Target {
  37         self.as_ref()
  38     }
  39 }
  40 
  41 const END_OF_CENTRAL_DIRECTORY: u32 = 0x0605_4b50;
  42 const CENTRAL_FILE_HEADER: u32 = 0x0201_4b50;
  43 const LOCAL_FILE_HEADER: u32 = 0x0403_4b50;
  44 const ZIP64_END_OF_CENTRAL_DIRECTORY: u32 = 0x0606_4b50;
  45 const ZIP64_LOCATOR: u32 = 0x0706_4b50;
  46 
  47 pub(crate) struct Entry {
  48     pub name: String,
  49     compression: u16,
  50     compressed_size: u64,
  51     uncompressed_size: u64,
  52     local_header_offset: u64,
  53 }
