  8 /// The NumPy element types this crate decodes.
  9 #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 10 pub enum Dtype {
 11     F32,
 12     F64,
 13     I32,
 14     I64,
 15     U8,
 16     Bool,
 17 }
 18 
 19 impl Dtype {
 20     fn parse(descr: &str) -> Result<Self> {
 21         Ok(match descr.trim_matches(['\'', '"']) {
 22             "<f4" | "=f4" | "f4" => Dtype::F32,
 23             "<f8" | "=f8" | "f8" => Dtype::F64,
 24             "<i4" | "=i4" | "i4" => Dtype::I32,
 25             "<i8" | "=i8" | "i8" => Dtype::I64,
 26             "|u1" | "u1" => Dtype::U8,
 27             "|b1" | "b1" => Dtype::Bool,
 28             other => bail!("unsupported NumPy dtype {other:?}"),
 29         })
 30     }
 31 
 32     pub fn size(self) -> usize {
 33         match self {
 34             Dtype::U8 | Dtype::Bool => 1,
 35             Dtype::F32 | Dtype::I32 => 4,
 36             Dtype::F64 | Dtype::I64 => 8,
 37         }
 38     }
 39 }
