 41 /// One decoded array: shape, element type, and the raw little-endian payload.
 42 pub struct NpyArray {
 43     pub shape: Vec<usize>,
 44     pub dtype: Dtype,
 45     pub(crate) bytes: Vec<u8>,
 46 }
 47 
 48 impl NpyArray {
 49     pub fn len(&self) -> usize {
 50         self.shape.iter().product()
 51     }
 52 
 53     pub fn is_empty(&self) -> bool {
 54         self.len() == 0
 55     }
 56 
 57     /// Element bytes, exactly as stored.
 58     pub fn bytes(&self) -> &[u8] {
 59         &self.bytes
 60     }
 61 
 62     /// Values widened to `f32`, whatever the stored element type.
 63     pub fn to_f32(&self) -> Vec<f32> {
 64         match self.dtype {
 65             Dtype::F32 => self.map_chunks(4, |b| f32::from_le_bytes(b.try_into().unwrap())),
 66             Dtype::F64 => self.map_chunks(8, |b| f64::from_le_bytes(b.try_into().unwrap()) as f32),
 67             Dtype::I32 => self.map_chunks(4, |b| i32::from_le_bytes(b.try_into().unwrap()) as f32),
 68             Dtype::I64 => self.map_chunks(8, |b| i64::from_le_bytes(b.try_into().unwrap()) as f32),
 69             Dtype::U8 | Dtype::Bool => self.bytes.iter().map(|b| *b as f32).collect(),
 70         }
 71     }
 72 
 73     /// Values widened to `i64`, whatever the stored element type.
 74     pub fn to_i64(&self) -> Vec<i64> {
 75         match self.dtype {
 76             Dtype::F32 => self.map_chunks(4, |b| f32::from_le_bytes(b.try_into().unwrap()) as i64),
 77             Dtype::F64 => self.map_chunks(8, |b| f64::from_le_bytes(b.try_into().unwrap()) as i64),
 78             Dtype::I32 => self.map_chunks(4, |b| i32::from_le_bytes(b.try_into().unwrap()) as i64),
 79             Dtype::I64 => self.map_chunks(8, |b| i64::from_le_bytes(b.try_into().unwrap())),
 80             Dtype::U8 | Dtype::Bool => self.bytes.iter().map(|b| *b as i64).collect(),
 81         }
 82     }
 83 
 84     pub fn to_bool(&self) -> Vec<bool> {
 85         self.bytes.iter().map(|b| *b != 0).collect()
 86     }
 87 
 88     fn map_chunks<T>(&self, width: usize, convert: impl Fn(&[u8]) -> T) -> Vec<T> {
 89         self.bytes.chunks_exact(width).map(convert).collect()
 90     }
 91 
 92     fn dims<const D: usize>(&self) -> Result<[usize; D]> {
 93         self.shape
 94             .as_slice()
 95             .try_into()
 96             .with_context(|| format!("array has {} dimensions, expected {D}", self.shape.len()))
 97     }
 98 
 99     /// Uploads the array to a device as a float tensor.
100     pub fn to_tensor<const D: usize>(&self, device: &Device) -> Result<Tensor<D>> {
101         Ok(Tensor::from_data(
102             TensorData::new(self.to_f32(), self.dims::<D>()?),
103             device,
104         ))
105     }
106 
107     /// Uploads the array to a device as an integer tensor.
108     pub fn to_int_tensor<const D: usize>(&self, device: &Device) -> Result<Tensor<D, Int>> {
109         Ok(Tensor::from_data(
110             TensorData::new(self.to_i64(), self.dims::<D>()?),
111             device,
112         ))
113     }
114 }
