   9 pub(super) struct NpyHeader<'a> {
  10     pub(super) dtype: Dtype,
  11     pub(super) shape: NpyShape,
  12     /// Serialized element bytes borrowed until the admitted array takes ownership.
  13     pub(super) payload: &'a [u8],
  14 }
  15 
  16 enum HeaderField {
  17     Descriptor,
  18     Order,
  19     Shape,
  20 }
  21 
  22 enum StorageOrder {
  23     RowMajor,
  24     Fortran,
  25 }
  26 
  27 impl<'a> NpyHeader<'a> {
  28     fn from_dictionary(header: &str, payload: &'a [u8]) -> Result<Self> {
  29         let mut cursor = header;
  30         take(&mut cursor, "{")?;
  31         // These remain lexical fields only until every required key is present.
  32         // Dtype/order rejection deliberately precedes parsing shape products.
  33         let mut descriptor = None;
  34         let mut order = None;
  35         let mut dimensions = None;
  36         loop {
  37             cursor = cursor.trim_start();
  38             if let Some(rest) = cursor.strip_prefix('}') {
  39                 ensure!(rest.trim().is_empty(), "trailing .npy header text");
  40                 break;
  41             }
  42             let key = quoted(&mut cursor)?;
  43             take(&mut cursor, ":")?;
  44             let field = HeaderField::parse(key)?;
  45             match field {
  46                 HeaderField::Descriptor => ensure!(
  47                     descriptor.replace(quoted(&mut cursor)?).is_none(),
  48                     "duplicate 'descr' in .npy header"
  49                 ),
  50                 HeaderField::Order => ensure!(
  51                     order.replace(StorageOrder::parse(&mut cursor)?).is_none(),
  52                     "duplicate 'fortran_order' in .npy header"
  53                 ),
  54                 HeaderField::Shape => {
  55                     take(&mut cursor, "(")?;
  56                     let end = cursor.find(')').context("bad .npy shape")?;
  57                     ensure!(
  58                         dimensions.replace(&cursor[..end]).is_none(),
  59                         "duplicate 'shape' in .npy header"
  60                     );
  61                     cursor = &cursor[end + 1..];
  62                 }
  63             }
  64             cursor = cursor.trim_start();
  65             if let Some(rest) = cursor.strip_prefix(',') {
  66                 cursor = rest;
  67             } else {
  68                 ensure!(cursor.starts_with('}'), "missing .npy header separator");
  69             }
  70         }
  71         let descriptor = descriptor.context("missing 'descr' in .npy header")?;
  72         let order = order.context("missing 'fortran_order' in .npy header")?;
  73         let dimensions = dimensions.context("missing 'shape' in .npy header")?;
  74         let dtype = Dtype::parse(descriptor)?;
  75         if let StorageOrder::Fortran = order {
  76             bail!("Fortran-ordered .npy arrays are not supported");
  77         }
  78         let shape = NpyShape::from_header_tuple(dimensions)?;
  79         let payload = shape
  80             .element_count()
  81             .payload_length(dtype)?
  82             .admit(payload)?;
  83         Ok(Self {
  84             dtype,
  85             shape,
  86             payload,
  87         })
  88     }
  89 }
  90 
  91 impl HeaderField {
  92     fn parse(key: &str) -> Result<Self> {
  93         match key {
  94             "descr" => Ok(Self::Descriptor),
  95             "fortran_order" => Ok(Self::Order),
  96             "shape" => Ok(Self::Shape),
  97             _ => bail!("unsupported .npy header field {key:?}"),
  98         }
  99     }
 100 }
 101 
 102 impl StorageOrder {
 103     fn parse(cursor: &mut &str) -> Result<Self> {
 104         let text = cursor.trim_start();
 105         if let Some(rest) = text.strip_prefix("True") {
 106             *cursor = rest;
 107             Ok(Self::Fortran)
 108         } else if let Some(rest) = text.strip_prefix("False") {
 109             *cursor = rest;
 110             Ok(Self::RowMajor)
 111         } else {
 112             bail!("bad 'fortran_order' in .npy header")
 113         }
 114     }
 115 }
 116 
 117 impl NpyShape {
 118     fn from_header_tuple(text: &str) -> Result<Self> {
 119         let text = text.trim();
 120         let dimensions = if text.is_empty() {
 121             Vec::new()
 122         } else {
 123             ensure!(text.contains(','), "bad .npy shape: expected a tuple");
 124             text.strip_suffix(',')
 125                 .unwrap_or(text)
 126                 .split(',')
 127                 .map(|token| {
 128                     token
 129                         .trim()
 130                         .parse::<usize>()
 131                         .map(NpyDimension::from)
 132                         .context("bad .npy shape")
 133                 })
 134                 .collect::<Result<_>>()?
 135         };
 136         Ok(Self::try_from(dimensions)?)
 137     }
 138 }
 139 
 140 fn take(cursor: &mut &str, token: &str) -> Result<()> {
 141     *cursor = cursor
 142         .trim_start()
 143         .strip_prefix(token)
 144         .with_context(|| format!("bad .npy header: expected {token:?}"))?;
 145     Ok(())
 146 }
 147 
 148 fn quoted<'a>(cursor: &mut &'a str) -> Result<&'a str> {
 149     let text = cursor.trim_start();
 150     let quote = text.chars().next().context("truncated .npy string")?;
 151     ensure!(matches!(quote, '\'' | '"'), "expected a .npy string");
 152     let end = text[1..].find(quote).context("unterminated .npy string")?;
 153     let value = &text[1..end + 1];
 154     ensure!(
 155         !value.contains('\\'),
 156         "escaped .npy strings are not supported"
 157     );
 158     *cursor = &text[end + 2..];
 159     Ok(value)
 160 }

