  52     Integer64(std::slice::Iter<'a, [u8; 8]>),
  53     Byte(std::slice::Iter<'a, u8>),
  54 }
  55 
  56 impl From<&NpyArray> for NpyFloat32Values {
  57     fn from(array: &NpyArray) -> Self {
  58         Self(
  59             StoredValues::from(array)
  60                 .map(StoredValue::floating)
  61                 .collect(),
  62         )
  63     }
  64 }
