#[test]
fn directory_and_zip64_records_use_checked_admission_and_selected_counts() {
    let cases = [
        DirectoryCase {
            label: "stored-deflated",
            names: Some(&["values.npy", "second.npy"]),
        },
        DirectoryCase {
            label: "nearest-end-is-empty",
            names: Some(&[]),
        },
        DirectoryCase {
            label: "nearest-end-selects-second",
            names: Some(&["second.npy"]),
        },
        DirectoryCase {
            label: "end-with-comment-candidate",
            names: Some(&[]),
        },
        DirectoryCase {
            label: "end-window-inclusive",
            names: Some(&["values.npy", "second.npy"]),
        },
        DirectoryCase {
            label: "unknown-central-3735928559",
            names: None,
        },
        DirectoryCase {
            label: "central-second-is-local",
            names: None,
        },
        DirectoryCase {
            label: "zip64-count-saturated",
            names: None,
        },
        DirectoryCase {
            label: "zip64-offset-saturated",
            names: None,
        },
        DirectoryCase {
            label: "zip64-locator-mismatch",
            names: None,
        },
        DirectoryCase {
            label: "zip64-end-mismatch",
            names: None,
        },
        DirectoryCase {
            label: "zip64-locator-known-wrong",
            names: None,
        },
        DirectoryCase {
            label: "zip64-end-known-wrong",
            names: None,
        },
        DirectoryCase {
            label: "zip64-record-outside",
            names: None,
        },
        DirectoryCase {
            label: "zip64-not-triggered",
            names: Some(&["values.npy", "second.npy"]),
        },
        DirectoryCase {
            label: "short-end-no-locator",
            names: Some(&[]),
        },
    ];
    for case in cases {
        let archive = ZipArchive::from_bytes(fixture(case.label).to_vec());
        assert_eq!(
            archive
                .map(|archive| archive
                    .names()
                    .map(|name| name.to_string())
                    .collect::<Vec<_>>())
                .map_err(|error| matches!(
                    error,
                    fabelgeist_numpy_storage::zip::ZipReadError::Archive { .. }
                )),
            case.names
                .map(|names| names
                    .iter()
                    .map(|name| name.to_string())
                    .collect::<Vec<_>>())
                .ok_or(true),
            "{}",
            case.label
        );
    }
    let error = ZipArchive::from_bytes(fixture("end-window-excluded").to_vec())
        .err()
        .unwrap();
    assert_eq!(
        error.to_string(),
        "not a zip archive: no end-of-central-directory record"
    );
}

#[test]
fn wrong_local_signatures_retain_entry_errors() {
    for label in ["unknown-local-3735928559", "local-is-central"] {
        let archive = ZipArchive::from_bytes(fixture(label).to_vec()).unwrap();
        assert!(archive.contains(&ArchiveMemberName::from("values.npy")));
        assert_eq!(
            archive
                .bytes(&ArchiveMemberName::from("values.npy"))
                .unwrap_err()
                .to_string(),
            "corrupt zip entry values.npy"
        );
        let npz = Npz::from_bytes(fixture(label).to_vec()).unwrap();
        assert_eq!(
            npz.array(&NpzArrayName::new("values"))
                .err()
                .unwrap()
                .to_string(),
            "corrupt zip entry values.npy"
        );
    }
}

fn assert_member_storage_and_values(archive: &ZipArchive, npz: &Npz) {
    let stored = archive
        .bytes(&ArchiveMemberName::from("values.npy"))
        .unwrap();
    assert!(matches!(&stored, Cow::Borrowed(_)));
    assert_eq!(
        stored.as_ptr(),
        archive
            .bytes(&ArchiveMemberName::from("values.npy"))
            .unwrap()
            .as_ptr()
    );
    assert!(matches!(
        archive
            .bytes(&ArchiveMemberName::from("second.npy"))
            .unwrap(),
        Cow::Owned(_)
    ));
    assert_eq!(
        npz.keys().map(|name| name.to_string()).collect::<Vec<_>>(),
        ["values", "second"]
    );
    assert_eq!(
        npz.array(&NpzArrayName::new("values"))
            .unwrap()
            .shape()
            .dimensions(),
        [fabelgeist_numpy_storage::NpyDimension::from(4)]
    );
    assert_eq!(
        Vec::<f32>::from(fabelgeist_numpy_storage::NpyFloat32Values::from(
            &npz.array(&NpzArrayName::new("values")).unwrap()
        ))
        .iter()
        .map(|v| v.to_bits())
        .collect::<Vec<_>>(),
        [0x3f800000, 0x80000000, 0x7fc01234, 0x40200000]
    );
    assert_eq!(
        Vec::<f32>::from(fabelgeist_numpy_storage::NpyFloat32Values::from(
            &npz.array(&NpzArrayName::new("second")).unwrap()
        )),
        [5.0, 6.0, 7.0, 8.0]
    );
}

#[test]
fn owned_and_mapped_archives_keep_borrowed_and_decoded_members() {
    let bytes = fixture("stored-deflated");
    assert_member_storage_and_values(
        &ZipArchive::from_bytes(bytes.to_vec()).unwrap(),
        &Npz::from_bytes(bytes.to_vec()).unwrap(),
    );
    let path = std::env::temp_dir().join(format!(
        "zip-record-kinds-test-{}-{}.zip",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos(),
    ));
    std::fs::write(&path, bytes).unwrap();
    assert_member_storage_and_values(
        &ZipArchive::open(&path).unwrap(),
        &Npz::open(&path).unwrap(),
    );
    std::fs::remove_file(path).unwrap();
}

#[test]
fn duplicate_and_disagreeing_headers_keep_member_semantics() {
    let bytes = fixture("duplicate-members");
    let archive = ZipArchive::from_bytes(bytes.to_vec()).unwrap();
    assert_eq!(
        archive
            .names()
            .map(|name| name.to_string())
            .collect::<Vec<_>>(),
        ["values.npy", "values.npy"]
    );
    assert!(matches!(
        archive
            .bytes(&ArchiveMemberName::from("values.npy"))
            .unwrap(),
        Cow::Borrowed(_)
    ));
    let npz = Npz::from_bytes(bytes.to_vec()).unwrap();
    assert_eq!(
        Vec::<f32>::from(fabelgeist_numpy_storage::NpyFloat32Values::from(
            &npz.array(&NpzArrayName::new("values")).unwrap()
        ))[0],
        1.0
    );
    for label in [
        "stored-central-deflate-local",
        "deflate-central-stored-local",
        "different-local-name-extra",
        "zip64-entry-extra",
    ] {
        let archive = ZipArchive::from_bytes(fixture(label).to_vec()).unwrap();
        assert_eq!(
            archive.uncompressed_size(&ArchiveMemberName::from("values.npy")),
            Some(DeclaredUncompressedByteLength::from_bytes(96))
        );
        assert_eq!(
            matches!(
                archive
                    .bytes(&ArchiveMemberName::from("values.npy"))
                    .unwrap(),
                Cow::Owned(_)
            ),
            label == "deflate-central-stored-local"
        );
        let npz = Npz::from_bytes(fixture(label).to_vec()).unwrap();
        assert_eq!(
            Vec::<f32>::from(fabelgeist_numpy_storage::NpyFloat32Values::from(
                &npz.array(&NpzArrayName::new("values")).unwrap()
            ))[0],
            1.0,
            "{label}"
        );
    }
}

