    assert!(matches!(
        ZipArchive::from_bytes(fixture("central-name-overrun").to_vec()),
        Err(fabelgeist_numpy_storage::zip::ZipReadError::Archive { .. })
    ));
}

use fabelgeist_numpy_storage::ArchiveMemberName;
use fabelgeist_numpy_storage::ZipArchive;
use flate2::{Compression, write::DeflateEncoder};
use std::{borrow::Cow, io::Write};

fn put16(out: &mut Vec<u8>, value: u16) {
    out.extend(value.to_le_bytes());
}
fn put32(out: &mut Vec<u8>, value: u32) {
    out.extend(value.to_le_bytes());
}

// These are intentionally serialized ZIP fixture fields, not admitted entries.
fn archive(method: u16, local_method: u16, raw: &[u8], declared: u32) -> Vec<u8> {
    let name = b"entry";
    let mut out = Vec::new();
    put32(&mut out, 0x0403_4b50);
    for value in [20, 0, local_method, 0, 0] {
        put16(&mut out, value);
    }
    for value in [0, raw.len() as u32, 17] {
        put32(&mut out, value);
    }
    put16(&mut out, name.len() as u16);
    put16(&mut out, 0);
    out.extend(name);
    out.extend(raw);
    let central = out.len() as u32;
    put32(&mut out, 0x0201_4b50);
    for value in [20, 20, 0, method, 0, 0] {
        put16(&mut out, value);
    }
    for value in [0, declared, 17] {
        put32(&mut out, value);
    }
    for value in [name.len() as u16, 0, 0, 0, 0] {
        put16(&mut out, value);
    }
    for value in [0, 0] {
        put32(&mut out, value);
    }
    out.extend(name);
    let directory_size = out.len() as u32 - central;
    put32(&mut out, 0x0605_4b50);
    for value in [0, 0, 1, 1] {
        put16(&mut out, value);
    }
    for value in [directory_size, central] {
        put32(&mut out, value);
    }
    put16(&mut out, 0);
    out
}

fn snapshot(zip: &ZipArchive) -> String {
    let mut out = format!(
        "names={:?};contains={};size={:?};missing={:?};",
        zip.names().map(|name| name.to_string()).collect::<Vec<_>>(),
        zip.contains(&ArchiveMemberName::from("entry")),
        zip.uncompressed_size(&ArchiveMemberName::from("entry")),
        zip.uncompressed_size(&ArchiveMemberName::from("missing"))
    );
    for key in ["entry", "missing"] {
        let result = match zip.bytes(&ArchiveMemberName::from(key)) {
            Ok(Cow::Borrowed(data)) => format!("borrowed:{data:?}"),
            Ok(Cow::Owned(data)) => format!("owned:{data:?}"),
            Err(error) => format!("error:{error:#}"),
        };
        out.push_str(&format!("{key}={result};"));
    }
    out.push('\n');
    out
}

fn observe() -> String {
    let payload = b"compression-proof";
    let mut deflater = DeflateEncoder::new(Vec::new(), Compression::default());
    deflater.write_all(payload).unwrap();
    let deflated = deflater.finish().unwrap();
    let mut out = String::new();
    let mut cases = vec![
        ("stored", archive(0, 0, payload, payload.len() as u32)),
        ("deflated", archive(8, 8, &deflated, deflated.len() as u32)),
        (
            "stored-central-deflate-local",
            archive(0, 8, payload, payload.len() as u32),
        ),
        (
            "deflate-central-stored-local",
            archive(8, 0, &deflated, deflated.len() as u32),
        ),
        ("corrupt-deflate", archive(8, 8, &[0xff, 0xff], 2)),
        ("empty-stored", archive(0, 0, &[], 0)),
    ];
    for method in [1, 12, 99, u16::MAX] {
        let bytes = archive(method, method, payload, payload.len() as u32);
        out.push_str(&format!(
            "unknown-{method}:{}",
            snapshot(&ZipArchive::from_bytes(bytes).unwrap())
        ));
    }
    let mut corrupt = archive(99, 99, payload, payload.len() as u32);
    corrupt[0] = 0;
    cases.push(("unknown-corrupt-local", corrupt));
    cases.push(("unknown-past-end", archive(99, 99, payload, 65536)));
    for (label, bytes) in cases {
        let zip = ZipArchive::from_bytes(bytes.clone()).unwrap();
        out.push_str(&format!("owned-{label}:{}", snapshot(&zip)));
        let path = std::env::temp_dir().join(format!(
            "zip-compression-726-{}-{label}.zip",
            std::process::id()
        ));
        std::fs::write(&path, bytes).unwrap();
        let mapped = ZipArchive::open(&path).unwrap();
        out.push_str(&format!("mapped-{label}:{}", snapshot(&mapped)));
        drop(mapped);
        std::fs::remove_file(path).unwrap();
    }
    out
}

#[test]
fn member_decoding_preserves_actual_main_compression_behavior() {
    assert_eq!(
        observe(),
        include_str!("../src/zip/fixtures/compression.txt")
    );
}

//! The non-linear pose-corrective network.
//!
//! Joint rotations are turned into a 6D rotation feature per joint, pushed
//! through a sparse 750 -> 3000 layer, a ReLU, and a dense 3000 -> `3 * V`
//! layer, giving a per-vertex offset applied before skinning.

use std::path::Path;

use anyhow::{Context, Result, bail};
use burn::tensor::{Device, Tensor, TensorData, activation};
use fabelgeist_numpy_storage::Npz;

/// The first two joints do not define a local pose, so they carry no feature.
pub const SKIPPED_JOINTS: usize = 2;
/// Hidden units per posed joint.
const HIDDEN_PER_JOINT: usize = 24;
/// Feature channels per posed joint (a 6D rotation).
const FEATURES_PER_JOINT: usize = 6;

/// Names of the arrays MHR stores the network in.
const BASIS_ARRAY: &str = "corrective_blendshapes";
const SPARSE_INDICES_ARRAY: &str = "0.sparse_indices";
const SPARSE_WEIGHT_ARRAY: &str = "0.sparse_weight";

pub struct PoseCorrectives {
    /// Sparse activation layer, densified and transposed: `[posed * 6, hidden]`.
    activation: Tensor<2>,
    /// Corrective basis: `[hidden, vertices * 3]`.
    basis: Tensor<2>,
    posed_joints: usize,
    num_vertices: usize,
}

impl PoseCorrectives {
    /// Loads the corrective network for one level of detail, or `None` when the
    /// LOD ships no corrective basis.
    ///
    /// `activation_path` holds the sparse mask and weights shared by every LOD;
    /// `basis_path` holds this LOD's corrective basis.
    pub fn load(
        activation_path: &Path,
        basis_path: &Path,
        num_joints: usize,
        num_vertices: usize,
        device: &Device,
    ) -> Result<Option<Self>> {
        let archive = Npz::open(basis_path)?;
        let activation = Npz::open(activation_path)?;
        Self::from_archives(activation, archive, num_joints, num_vertices, device)
    }

    /// Loads corrective archives already held in memory (for web/streamed assets).
    pub fn from_bytes(
        activation: Vec<u8>,
        basis: Vec<u8>,
        num_joints: usize,
        num_vertices: usize,
        device: &Device,
    ) -> Result<Option<Self>> {
        Self::from_archives(
            Npz::from_bytes(activation)?,
            Npz::from_bytes(basis)?,
            num_joints,
            num_vertices,
            device,
        )
    }

    fn from_archives(
        activation: Npz,
        archive: Npz,
        num_joints: usize,
        num_vertices: usize,
        device: &Device,
    ) -> Result<Option<Self>> {
        if !archive.contains(BASIS_ARRAY) {
            return Ok(None);
        }
        let basis = archive
            .array(BASIS_ARRAY)
            .context("reading the corrective basis")?;
        let (components, basis_vertices) = match basis.shape[..] {
            [components, vertices, 3] => (components, vertices),
            _ => bail!(
                "{BASIS_ARRAY} has shape {:?}, expected [components, vertices, 3]",
                basis.shape
            ),
        };
        if basis_vertices != num_vertices {
            bail!(
                "corrective basis covers {basis_vertices} vertices but the mesh has {num_vertices}"
            );
        }

        let posed_joints = num_joints - SKIPPED_JOINTS;
        let hidden = posed_joints * HIDDEN_PER_JOINT;
        if components != hidden {
            bail!("corrective basis has {components} components, expected {hidden}");
        }

        let indices = activation
            .array(SPARSE_INDICES_ARRAY)
            .context("reading the sparse activation indices")?
            .to_i64();
        let values = activation
            .array(SPARSE_WEIGHT_ARRAY)
            .context("reading the sparse activation weights")?
            .to_f32();
        if indices.len() != 2 * values.len() {
            bail!(
                "sparse activation has {} indices for {} weights",
                indices.len(),
                values.len()
            );
        }

        // Densify straight into the transposed layout the matmul wants. The
        // layer is 4% dense, so a dense matmul beats a sparse gather on GPU.
        let inputs = posed_joints * FEATURES_PER_JOINT;
        let mut dense = vec![0.0f32; inputs * hidden];
        for (slot, value) in values.iter().enumerate() {
            let row = indices[slot] as usize;
            let column = indices[values.len() + slot] as usize;
            if row >= hidden || column >= inputs {
                bail!("sparse activation index ({row}, {column}) is out of bounds");
            }
            dense[column * hidden + row] = *value;
        }

        Ok(Some(Self {
            activation: Tensor::from_data(TensorData::new(dense, [inputs, hidden]), device),
            basis: Tensor::from_data(
                TensorData::new(basis.to_f32(), [components, num_vertices * 3]),
                device,
            ),
            posed_joints,
            num_vertices,
        }))
    }

    pub fn num_vertices(&self) -> usize {
        self.num_vertices
    }

    /// Per-vertex corrective offsets `[batch, vertices, 3]`, from joint
    /// parameters shaped `[batch, joints, 7]`.
    pub fn forward(&self, joint_parameters: Tensor<3>) -> Tensor<3> {
        let batch = joint_parameters.dims()[0];
        let features = self.pose_features(joint_parameters);
        let hidden = activation::relu(features.matmul(self.activation.clone()));
        hidden
            .matmul(self.basis.clone())
            .reshape([batch, self.num_vertices, 3])
    }

    /// The 6D rotation feature per posed joint, flattened to `[batch, posed * 6]`.
    ///
    /// A 6D feature is the first two columns of the joint's rotation matrix,
    /// with 1 subtracted from the two diagonal entries so a rest pose is zero.
    fn pose_features(&self, joint_parameters: Tensor<3>) -> Tensor<2> {
        let batch = joint_parameters.dims()[0];
        let euler = joint_parameters
            .narrow(1, SKIPPED_JOINTS, self.posed_joints)
            .narrow(2, 3, 3);

        let (sx, cx) = axis_sin_cos(&euler, 0);
        let (sy, cy) = axis_sin_cos(&euler, 1);
        let (sz, cz) = axis_sin_cos(&euler, 2);

        let feature = Tensor::cat(
            vec![
                (cy.clone() * cz.clone()).sub_scalar(1.0),
                cy.clone() * sz.clone(),
                sy.clone().neg(),
                cx.clone().neg() * sz.clone() + sx.clone() * sy.clone() * cz.clone(),
                (cx * cz + sx.clone() * sy * sz).sub_scalar(1.0),
                sx * cy,
            ],
            2,
        );
        feature.reshape([batch, self.posed_joints * FEATURES_PER_JOINT])
    }
}

fn axis_sin_cos(euler: &Tensor<3>, axis: usize) -> (Tensor<3>, Tensor<3>) {
    let angle = euler.clone().narrow(2, axis, 1);
    (angle.clone().sin(), angle.cos())
}

//! The non-linear pose-corrective network.
//!
//! Joint rotations are turned into a 6D rotation feature per joint, pushed
//! through a sparse 750 -> 3000 layer, a ReLU, and a dense 3000 -> `3 * V`
//! layer, giving a per-vertex offset applied before skinning.

use std::path::Path;

use anyhow::Result;
use burn::tensor::{Device, Tensor, activation};
use fabelgeist_numpy_storage::NpyDimension;
use fabelgeist_rig::RigJointCount;

use crate::character::MeshVertexCount;

pub use archive::CorrectiveArchiveBytes;
use archive::CorrectiveArchives;
use import::{CorrectiveBasis, CorrectiveLayout};
pub use import::{
    CorrectiveExtent, CorrectiveFeatureIndex, CorrectiveHiddenIndex, CorrectiveImportError,
};
pub use input::CorrectiveForwardError;
use input::CorrectiveInput;

mod archive;
mod import;
mod input;

/// The first two joints do not define a local pose, so they carry no feature.
pub const SKIPPED_JOINTS: NpyDimension = NpyDimension::new(2);

pub struct PoseCorrectives {
    /// Sparse activation layer, densified and transposed: `[posed * 6, hidden]`.
    activation: Tensor<2>,
    /// Corrective basis: `[hidden, vertices * 3]`.
    basis: Tensor<2>,
    layout: CorrectiveLayout,
}

impl PoseCorrectives {
    /// Loads the corrective network for one level of detail, or `None` when the
    /// LOD ships no corrective basis.
    ///
    /// `activation_path` holds the sparse mask and weights shared by every LOD;
    /// `basis_path` holds this LOD's corrective basis.
    pub fn load(
        activation_path: &Path,
        basis_path: &Path,
        num_joints: RigJointCount,
        num_vertices: MeshVertexCount,
        device: &Device,
    ) -> Result<Option<Self>> {
        Self::from_archives(
            CorrectiveArchives::open(activation_path, basis_path)?,
            num_joints,
            num_vertices,
            device,
        )
    }

    /// Loads corrective archives already held in memory (for web/streamed assets).
    pub fn from_bytes(
        archives: CorrectiveArchiveBytes,
        num_joints: RigJointCount,
        num_vertices: MeshVertexCount,
        device: &Device,
    ) -> Result<Option<Self>> {
        Self::from_archives(
            CorrectiveArchives::from_bytes(archives)?,
            num_joints,
            num_vertices,
            device,
        )
    }

    fn from_archives(
        archives: CorrectiveArchives,
        num_joints: RigJointCount,
        num_vertices: MeshVertexCount,
        device: &Device,
    ) -> Result<Option<Self>> {
        let Some(array) = archives.basis()? else {
            return Ok(None);
        };
        let basis = CorrectiveBasis::new(array, num_joints, num_vertices)?;
        let activation = archives.activation(basis.layout())?.into_tensor(device);
        let tensor = basis.to_tensor(device)?;
        Ok(Some(Self {
            activation,
            basis: tensor,
            layout: basis.into_layout(),
        }))
    }

    pub fn num_vertices(&self) -> MeshVertexCount {
        self.layout.vertices()
    }

    /// Per-vertex corrective offsets `[batch, vertices, 3]`, from joint
    /// parameters in the model's seven-channel order. Joint count and channel
    /// width must match the admitted network before any tensor operation.
    /// Batch-dependent products remain fallible layout admissions.
    pub fn forward(
        &self,
        joint_parameters: Tensor<3>,
    ) -> std::result::Result<Tensor<3>, CorrectiveForwardError> {
        let input = CorrectiveInput::new(joint_parameters, &self.layout)?;
        let output_dimensions = input.output_dimensions()?;
        let features = input.into_features()?;
        let hidden = activation::relu(features.matmul(self.activation.clone()));
        Ok(hidden.matmul(self.basis.clone()).reshape(output_dimensions))
    }
}

