//! The MHR body model: identity, pose and expression parameters in, posed
//! mesh vertices and a skeleton state out.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use burn::tensor::ops::IndexingUpdateOp;
use burn::tensor::{Device, Int, Tensor};

use crate::character::{Character, MeshVertexCount, PARAMETERS_PER_JOINT};
use crate::correctives::{CorrectiveArchiveBytes, PoseCorrectives};
use crate::model_def::{ParameterTransform, append_blend_shape_parameters, parse_model_definition};
use crate::skel_state;
use fabelgeist_numpy_storage::NpyDimension;
use fabelgeist_rig::RigJointCount;

mod rig;
mod upload;

/// Shape coefficients: 20 body, 20 head, 5 hands.
pub const NUM_IDENTITY_BLEND_SHAPES: usize = 45;
/// Facial expression coefficients.
pub const NUM_FACE_EXPRESSION_BLEND_SHAPES: usize = 72;
/// Total blend shapes carried by an MHR rig.
pub const NUM_BLEND_SHAPES: usize = NUM_IDENTITY_BLEND_SHAPES + NUM_FACE_EXPRESSION_BLEND_SHAPES;

/// Supported runtime body detail, 4 (densest) through 6.
pub const MIN_LOD: u8 = 4;
pub const MAX_LOD: u8 = 6;

const MODEL_DEFINITION: &str = "compact_v6_1.model";
const CORRECTIVE_ACTIVATION: &str = "corrective_activation.npz";

/// How to load a model.
#[derive(Debug, Clone, Copy)]
pub struct MhrConfig {
    pub lod: u8,
    /// Load the pose-corrective network. It dominates both load time and
    /// memory (2.5 GiB of coefficients at LOD 0), so it can be turned off.
    pub pose_correctives: bool,
}

impl Default for MhrConfig {
    fn default() -> Self {
        Self {
            lod: MIN_LOD,
            pose_correctives: true,
        }
    }
}

/// One forward pass.
pub struct MhrOutput {
    /// Posed vertices in centimetres, `[batch, vertices, 3]`.
    pub vertices: Tensor<3>,
    /// Unit vertex normals of the posed mesh, `[batch, vertices, 3]`.
    ///
    /// Recomputed from the deformed vertices rather than skinned from the rest
    /// pose, because blend shapes and the pose correctives change the surface
    /// itself, not just its rigid frame.
    pub normals: Tensor<3>,
    /// Global joint transforms `[tx, ty, tz, qx, qy, qz, qw, s]`, `[batch, joints, 8]`.
    pub skeleton_state: Tensor<3>,
}

/// The MHR body model.
pub struct Mhr {
    /// Topology and names, kept on the host for lookups and the normal pass.
    pub character: Character,
    pub parameter_transform: ParameterTransform,
    device: Device,

    /// `[model parameters, joints * 7]`, transposed for a right-hand matmul.
    transform: Tensor<2>,
    /// Constant joint-parameter offsets, or `None` when the rig has none.
    offsets: Option<Tensor<2>>,
    num_model_parameters: NpyDimension,

    /// `[1, joints, 3]` and `[1, joints, 4]`.
    joint_translation_offsets: Tensor<3>,
    joint_prerotations: Tensor<3>,
    /// `[1, joints, 8]`.
    inverse_bind_pose: Tensor<3>,
    /// Levels of the forward-kinematics prefix scan.
    fk_levels: Vec<rig::FkTensorLevel>,

    /// `[45, vertices * 3]` and `[72, vertices * 3]`.
    identity_basis: Tensor<2>,
    expression_basis: Tensor<2>,
    /// `[1, vertices * 3]`.
    base_shape: Tensor<2>,

    /// The three corners of every triangle, flattened, `[faces * 3]`.
    face_corners: Tensor<1, Int>,

    /// Flattened non-zero skinning influences.
    skin_joint_indices: Tensor<1, Int>,
    skin_vertex_indices: Tensor<1, Int>,
    /// `[1, influences, 1]`.
    skin_weights: Tensor<3>,

    correctives: Option<PoseCorrectives>,
}

/// Accepts either the asset directory itself or its parent.
fn resolve_asset_dir(path: &Path) -> Result<PathBuf> {
    if path.join(MODEL_DEFINITION).is_file() {
        return Ok(path.to_path_buf());
    }
    let nested = path.join("assets");
    if nested.join(MODEL_DEFINITION).is_file() {
        return Ok(nested);
    }
    bail!(
        "no MHR assets in {}: expected {MODEL_DEFINITION} there or under assets/",
        path.display()
    )
}

impl Mhr {
    /// Loads MHR through `fabelgeist-fs`, including `prism://project`, HTTP/blob,
    /// browser File System Access handles, and native filesystem paths.
    pub async fn from_uri(asset_dir: &str, config: MhrConfig, device: &Device) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let base = asset_dir.trim_end_matches(['/', '\\']);
        let read_asset = |name: String| async move {
            let direct = format!("{base}/{name}");
            match fabelgeist_fs::read_bytes(&direct).await {
                Ok(bytes) => Ok(bytes),
                Err(direct_error) => {
                    let nested = format!("{base}/assets/{name}");
                    fabelgeist_fs::read_bytes(&nested).await.map_err(|nested_error| {
                        anyhow::anyhow!(
                            "could not read MHR asset {name:?} from {direct} ({direct_error:#}) or {nested} ({nested_error:#})"
                        )
                    })
                }
            }
        };

        let fbx = read_asset(format!("lod{}.fbx", config.lod)).await?;
        let definition = String::from_utf8(read_asset(MODEL_DEFINITION.into()).await?)
            .map_err(|error| anyhow::anyhow!("MHR model definition is not UTF-8: {error}"))?;
        let corrective_archives = if config.pose_correctives {
            Some(CorrectiveArchiveBytes {
                activation: read_asset(CORRECTIVE_ACTIVATION.into()).await?,
                basis: read_asset(format!("corrective_blendshapes_lod{}.npz", config.lod)).await?,
            })
        } else {
            None
        };

        Self::from_asset_bytes(&fbx, &definition, corrective_archives, config, device)
    }

    /// Loads a model from an MHR asset directory (the unpacked `assets.zip`).
    pub fn from_files(
        asset_dir: impl AsRef<Path>,
        config: MhrConfig,
        device: &Device,
    ) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let dir = resolve_asset_dir(asset_dir.as_ref())?;

        let fbx_path = dir.join(format!("lod{}.fbx", config.lod));
        let fbx =
            std::fs::read(&fbx_path).with_context(|| format!("reading {}", fbx_path.display()))?;
        let character = Character::from_fbx_bytes(&fbx, true)
            .with_context(|| format!("loading {}", fbx_path.display()))?;
        let definition_path = dir.join(MODEL_DEFINITION);
        let definition = std::fs::read_to_string(&definition_path)
            .with_context(|| format!("reading {}", definition_path.display()))?;
        let correctives = if config.pose_correctives {
            PoseCorrectives::load(
                &dir.join(CORRECTIVE_ACTIVATION),
                &dir.join(format!("corrective_blendshapes_lod{}.npz", config.lod)),
                character.skeleton.names.joint_count(),
                character.mesh.vertex_count(),
                device,
            )
            .context("loading the pose-corrective network")?
        } else {
            None
        };
        Self::from_loaded_assets(character, &definition, correctives, device)
    }

    /// Loads MHR from asset bytes, allowing browsers and virtual filesystems to
    /// provide the same FBX/model/NPZ inputs as the native filesystem loader.
    pub fn from_asset_bytes(
        fbx: &[u8],
        definition: &str,
        corrective_archives: Option<CorrectiveArchiveBytes>,
        config: MhrConfig,
        device: &Device,
    ) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let character = Character::from_fbx_bytes(fbx, true).context("loading the MHR FBX")?;
        let correctives = if config.pose_correctives {
            let archives = corrective_archives
                .context("pose correctives requested but their NPZ archives were not provided")?;
            PoseCorrectives::from_bytes(
                archives,
                character.skeleton.names.joint_count(),
                character.mesh.vertex_count(),
                device,
            )
            .context("loading the pose-corrective network")?
        } else {
            None
        };

        Self::from_loaded_assets(character, definition, correctives, device)
    }

    fn from_loaded_assets(
        character: Character,
        definition: &str,
        correctives: Option<PoseCorrectives>,
        device: &Device,
    ) -> Result<Self> {
        let mut parameter_transform = parse_model_definition(definition, &character.skeleton)
            .context("parsing the MHR model definition")?;
        let num_model_parameters = parameter_transform.num_parameters();
        // momentum appends one model parameter per identity blend shape when a
        // blend shape is attached to the character.
        append_blend_shape_parameters(
            &mut parameter_transform,
            NpyDimension::from(NUM_IDENTITY_BLEND_SHAPES),
        )?;
        Self::new(
            character,
            parameter_transform,
            num_model_parameters,
            correctives,
            device,
        )
    }

    pub fn num_joints(&self) -> RigJointCount {
        self.character.skeleton.names.joint_count()
    }

    pub fn num_vertices(&self) -> MeshVertexCount {
        self.character.mesh.vertex_count()
    }

    /// Number of pose/scale parameters the model takes, excluding the blend
    /// shape coefficients momentum appends to the parameter vector.
    pub fn num_model_parameters(&self) -> NpyDimension {
        self.num_model_parameters
    }

    pub fn has_pose_correctives(&self) -> bool {
        self.correctives.is_some()
    }

    pub fn device(&self) -> &Device {
        &self.device
    }

    /// Zero parameters for a batch, i.e. the rest pose.
    pub fn zero_parameters(&self, batch: usize) -> Tensor<2> {
        Tensor::zeros(
            [batch, usize::from(self.num_model_parameters)],
            &self.device,
        )
    }

    /// Runs the model.
    ///
    /// * `identity` — `[batch, 45]` shape coefficients (a single row is broadcast).
    /// * `model_parameters` — `[batch, 204]` pose and scale parameters.
    /// * `expression` — `[batch, 72]` facial expression coefficients, optional.
    pub fn forward(
        &self,
        identity: Tensor<2>,
        model_parameters: Tensor<2>,
        expression: Option<Tensor<2>>,
    ) -> Result<MhrOutput> {
        self.forward_with(identity, model_parameters, expression, true)
    }

    /// As [`Mhr::forward`], but able to skip the pose correctives.
    pub fn forward_with(
        &self,
        identity: Tensor<2>,
        model_parameters: Tensor<2>,
        expression: Option<Tensor<2>>,
        apply_correctives: bool,
    ) -> Result<MhrOutput> {
        let batch = model_parameters.dims()[0];
        let joints = self.num_joints();
        let vertices = self.num_vertices();

        let [identity_rows, identity_columns] = identity.dims();
        if identity_columns != NUM_IDENTITY_BLEND_SHAPES {
            bail!(
                "identity coefficients have {identity_columns} columns, expected {NUM_IDENTITY_BLEND_SHAPES}"
            );
        }
        if identity_rows != batch && identity_rows != 1 {
            bail!("identity coefficients have {identity_rows} rows, expected {batch} or 1");
        }
        if NpyDimension::from(model_parameters.dims()[1]) != self.num_model_parameters {
            bail!(
                "model parameters have {} columns, expected {}",
                model_parameters.dims()[1],
                self.num_model_parameters
            );
        }

        // Rest shape: mean plus identity and expression offsets.
        let identity = if identity_rows == batch {
            identity
        } else {
            identity.expand([batch, NUM_IDENTITY_BLEND_SHAPES])
        };
        let mut rest = self.base_shape.clone() + identity.matmul(self.identity_basis.clone());
        if let Some(expression) = expression {
            let [rows, columns] = expression.dims();
            if columns != NUM_FACE_EXPRESSION_BLEND_SHAPES {
                bail!(
                    "expression coefficients have {columns} columns, expected {NUM_FACE_EXPRESSION_BLEND_SHAPES}"
                );
            }
            if rows != batch {
                bail!("expression coefficients have {rows} rows, expected {batch}");
            }
            rest = rest + expression.matmul(self.expression_basis.clone());
        }

        // Model parameters drive joint parameters, seven channels per joint.
        //
        // Deliberately a broadcast product and reduction rather than a matmul:
        // the CUDA backend promotes f32 matmuls to tf32, whose 10-bit mantissa
        // costs about 2e-4 relative accuracy. That is invisible in a blend
        // shape but not here, where every joint angle and translation is
        // amplified along the kinematic chain. The tensor is 204 x 889, so the
        // exact form is cheap.
        let mut joint_parameters = (model_parameters.unsqueeze_dim::<3>(2)
            * self.transform.clone().unsqueeze::<3>())
        .sum_dim(1)
        .reshape([batch, joints.native_joint_count() * PARAMETERS_PER_JOINT]);
        if let Some(offsets) = &self.offsets {
            joint_parameters = joint_parameters + offsets.clone();
        }
        let joint_parameters =
            joint_parameters.reshape([batch, joints.native_joint_count(), PARAMETERS_PER_JOINT]);

        let skeleton_state = self.skeleton_state(joint_parameters.clone());

        let mut rest = rest.reshape([batch, vertices.native_vertex_count(), 3]);
        if apply_correctives && let Some(correctives) = &self.correctives {
            rest = rest + correctives.forward(joint_parameters)?;
        }

        let vertices = self.skin(skeleton_state.clone(), rest);

        Ok(MhrOutput {
            normals: self.vertex_normals(vertices.clone()),
            vertices,
            skeleton_state,
        })
    }

    /// Joint parameters `[batch, joints, 7]` to global skeleton states.
    fn skeleton_state(&self, joint_parameters: Tensor<3>) -> Tensor<3> {
        let translation =
            joint_parameters.clone().narrow(2, 0, 3) + self.joint_translation_offsets.clone();
        let rotation = skel_state::quaternion_multiply(
            self.joint_prerotations.clone(),
            skel_state::euler_xyz_to_quaternion(joint_parameters.clone().narrow(2, 3, 3)),
        );
        // momentum stores scale as a power of two.
        let scale = (joint_parameters.narrow(2, 6, 1) * std::f32::consts::LN_2).exp();

        let mut state = Tensor::cat(vec![translation, rotation, scale], 2);
        for (source, target) in &self.fk_levels {
            let parent = state.clone().select(1, target.clone());
            let child = state.clone().select(1, source.clone());
            // An overwrite expressed as an accumulation: source indices are
            // unique within a level, and `Assign` has no backend kernel here.
            let delta = skel_state::multiply(parent, child.clone()) - child;
            state = state.select_assign(1, source.clone(), delta, IndexingUpdateOp::Add);
        }
        state
    }

    /// Area-weighted vertex normals of a posed mesh, `[batch, vertices, 3]`.
    ///
    /// Each triangle contributes its unnormalized cross product, whose length
    /// is twice the triangle's area, to all three of its corners. That is the
    /// weighting `THREE.BufferGeometry.computeVertexNormals` uses, which is
    /// what the reference web viewer shades MHR with.
    fn vertex_normals(&self, vertices: Tensor<3>) -> Tensor<3> {
        let batch = vertices.dims()[0];
        let faces = self.character.mesh.faces.len();

        let corners = vertices
            .select(1, self.face_corners.clone())
            .reshape([batch, faces, 3, 3]);
        let corner = |index: usize| {
            corners
                .clone()
                .narrow(2, index, 1)
                .reshape([batch, faces, 3])
        };
        let (first, second, third) = (corner(0), corner(1), corner(2));
        let (u, v) = (second - first.clone(), third - first);

        let axis = |t: &Tensor<3>, index: usize| t.clone().narrow(2, index, 1);
        let cross = Tensor::cat(
            vec![
                axis(&u, 1) * axis(&v, 2) - axis(&u, 2) * axis(&v, 1),
                axis(&u, 2) * axis(&v, 0) - axis(&u, 0) * axis(&v, 2),
                axis(&u, 0) * axis(&v, 1) - axis(&u, 1) * axis(&v, 0),
            ],
            2,
        );

        // The same face normal lands on each of the face's three corners.
        let contribution = cross
            .unsqueeze_dim::<4>(2)
            .expand([batch, faces, 3, 3])
            .reshape([batch, faces * 3, 3]);
        let accumulated = Tensor::zeros(
            [batch, self.num_vertices().native_vertex_count(), 3],
            &self.device,
        )
        .select_assign(
            1,
            self.face_corners.clone(),
            contribution,
            IndexingUpdateOp::Add,
        );

        // A vertex no triangle references keeps a zero normal, as it does in
        // three.js; nothing rasterizes it, so there is no direction to invent.
        let length = accumulated
            .clone()
            .powi_scalar(2)
            .sum_dim(2)
            .sqrt()
            .clamp_min(1e-12);
        accumulated / length
    }

    /// Linear blend skinning of `rest` `[batch, vertices, 3]`.
    fn skin(&self, skeleton_state: Tensor<3>, rest: Tensor<3>) -> Tensor<3> {
        let batch = rest.dims()[0];
        let joint_state = skel_state::multiply(skeleton_state, self.inverse_bind_pose.clone());

        let transforms = joint_state.select(1, self.skin_joint_indices.clone());
        let points = rest.clone().select(1, self.skin_vertex_indices.clone());
        let deformed =
            skel_state::transform_points(&transforms, points) * self.skin_weights.clone();

        Tensor::zeros(rest.dims(), &self.device)
            .select_assign(
                1,
                self.skin_vertex_indices.clone(),
                deformed,
                IndexingUpdateOp::Add,
            )
            .reshape([batch, self.num_vertices().native_vertex_count(), 3])
    }
}

//! Native tensor construction from the admitted MHR host aggregates.

use super::{
    Mhr, NUM_BLEND_SHAPES, NUM_FACE_EXPRESSION_BLEND_SHAPES, NUM_IDENTITY_BLEND_SHAPES, rig,
};
use crate::character::{Character, PARAMETERS_PER_JOINT};
use crate::correctives::PoseCorrectives;
use crate::model_def::ParameterTransform;
use anyhow::{Result, bail};
use burn::tensor::{Device, Tensor, TensorData};
use fabelgeist_numpy_storage::NpyDimension;

/// Sparse i32 index words and coefficients for Burn's influence kernel.
struct SparseSkinUpload {
    joints: Vec<i32>,
    vertices: Vec<i32>,
    weights: Vec<f32>,
}

struct RestRigTensors {
    translations: Tensor<3>,
    prerotations: Tensor<3>,
    inverse_bind_pose: Tensor<3>,
    base_shape: Tensor<2>,
}

struct BlendBasisTensors {
    identity: Tensor<2>,
    expression: Tensor<2>,
}

impl Mhr {
    pub(super) fn new(
        character: Character,
        parameter_transform: ParameterTransform,
        num_model_parameters: NpyDimension,
        correctives: Option<PoseCorrectives>,
        device: &Device,
    ) -> Result<Self> {
        let joints = character.skeleton.names.joint_count();
        if character.blend_shapes.len() != NUM_BLEND_SHAPES {
            bail!(
                "rig has {} blend shapes, expected {NUM_IDENTITY_BLEND_SHAPES} identity plus \
                 {NUM_FACE_EXPRESSION_BLEND_SHAPES} expression",
                character.blend_shapes.len()
            );
        }

        // Transposed so a forward pass is `parameters @ transform`.
        let transform = parameter_transform
            .transform
            .tensor_transpose(num_model_parameters)?;

        let offsets = parameter_transform
            .offsets
            .iter()
            .any(|offset| *offset != 0.0)
            .then(|| {
                Tensor::from_data(
                    TensorData::new(
                        parameter_transform.offsets.tensor_values(),
                        [1, joints.native_joint_count() * PARAMETERS_PER_JOINT],
                    ),
                    device,
                )
            });

        let fk_levels = rig::fk_level_tensors(&character, device)?;

        let basis = BlendBasisTensors::from_character(&character, device);

        let skin = SparseSkinUpload::from_character(&character)?;
        let influences = skin.weights.len();

        let face_corners: Vec<i32> = character
            .mesh
            .faces
            .iter()
            .flatten()
            .map(|corner| i32::try_from(*corner))
            .collect::<Result<_, _>>()?;
        let num_corners = face_corners.len();

        let rest = RestRigTensors::from_character(&character, device);
        Ok(Self {
            device: device.clone(),
            transform: Tensor::from_data(
                TensorData::new(
                    transform,
                    [
                        usize::from(num_model_parameters),
                        joints.native_joint_count() * PARAMETERS_PER_JOINT,
                    ],
                ),
                device,
            ),
            offsets,
            num_model_parameters,
            joint_translation_offsets: rest.translations,
            joint_prerotations: rest.prerotations,
            inverse_bind_pose: rest.inverse_bind_pose,
            fk_levels,
            identity_basis: basis.identity,
            expression_basis: basis.expression,
            base_shape: rest.base_shape,
            face_corners: Tensor::from_data(TensorData::new(face_corners, [num_corners]), device),
            skin_joint_indices: Tensor::from_data(
                TensorData::new(skin.joints, [influences]),
                device,
            ),
            skin_vertex_indices: Tensor::from_data(
                TensorData::new(skin.vertices, [influences]),
                device,
            ),
            skin_weights: Tensor::from_data(
                TensorData::new(skin.weights, [1, influences, 1]),
                device,
            ),
            correctives,
            character,
            parameter_transform,
        })
    }
}

impl SparseSkinUpload {
    fn from_character(character: &Character) -> Result<Self> {
        // Retain influences whose weight exceeds 1e-5.
        let mut skin_joint_indices = Vec::new();
        let mut skin_vertex_indices = Vec::new();
        let mut skin_weights = Vec::new();
        // Encode the admitted vertex/joint roles into Burn's sparse i32 buffers.
        for (vertex, influences) in character.skin_weights.indexed() {
            for (joint, weight) in influences.joints.into_iter().zip(influences.weights) {
                if weight > 1e-5 {
                    skin_joint_indices.push(i32::try_from(usize::from(joint))?);
                    skin_vertex_indices.push(i32::try_from(vertex.native_vertex_index())?);
                    skin_weights.push(weight);
                }
            }
        }
        Ok(Self {
            joints: skin_joint_indices,
            vertices: skin_vertex_indices,
            weights: skin_weights,
        })
    }
}

impl BlendBasisTensors {
    fn from_character(character: &Character, device: &Device) -> Self {
        let vertices = character.mesh.vertex_count();
        let basis = &character.blend_shapes.vectors;
        let identity_basis = Tensor::from_data(
            TensorData::new(
                basis[..NUM_IDENTITY_BLEND_SHAPES * vertices.native_vertex_count() * 3].to_vec(),
                [
                    NUM_IDENTITY_BLEND_SHAPES,
                    vertices.native_vertex_count() * 3,
                ],
            ),
            device,
        );
        let expression_basis = Tensor::from_data(
            TensorData::new(
                basis[NUM_IDENTITY_BLEND_SHAPES * vertices.native_vertex_count() * 3..].to_vec(),
                [
                    NUM_FACE_EXPRESSION_BLEND_SHAPES,
                    vertices.native_vertex_count() * 3,
                ],
            ),
            device,
        );

        Self {
            identity: identity_basis,
            expression: expression_basis,
        }
    }
}

impl RestRigTensors {
    fn from_character(character: &Character, device: &Device) -> Self {
        let joints = character.skeleton.names.joint_count();
        let vertices = character.mesh.vertex_count();
        Self {
            translations: Tensor::from_data(
                TensorData::new(
                    character
                        .skeleton
                        .translation_offsets
                        .as_native_slice()
                        .concat(),
                    [1, joints.native_joint_count(), 3],
                ),
                device,
            ),
            prerotations: Tensor::from_data(
                TensorData::new(
                    character.skeleton.prerotations.as_native_slice().concat(),
                    [1, joints.native_joint_count(), 4],
                ),
                device,
            ),
            inverse_bind_pose: Tensor::from_data(
                TensorData::new(
                    character.inverse_bind_pose.as_native_slice().concat(),
                    [1, joints.native_joint_count(), 8],
                ),
                device,
            ),
            base_shape: Tensor::from_data(
                TensorData::new(
                    character.mesh.vertices.as_native_slice().concat(),
                    [1, vertices.native_vertex_count() * 3],
                ),
                device,
            ),
        }
    }
}

//! The MHR body model: identity, pose and expression parameters in, posed
//! mesh vertices and a skeleton state out.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use burn::tensor::ops::IndexingUpdateOp;
use burn::tensor::{Device, Int, Tensor, TensorData};

use crate::character::{Character, PARAMETERS_PER_JOINT};
use crate::correctives::PoseCorrectives;
use crate::model_def::{ParameterTransform, append_blend_shape_parameters, parse_model_definition};
use crate::skel_state;

mod rig;

/// Shape coefficients: 20 body, 20 head, 5 hands.
pub const NUM_IDENTITY_BLEND_SHAPES: usize = 45;
/// Facial expression coefficients.
pub const NUM_FACE_EXPRESSION_BLEND_SHAPES: usize = 72;
/// Total blend shapes carried by an MHR rig.
pub const NUM_BLEND_SHAPES: usize = NUM_IDENTITY_BLEND_SHAPES + NUM_FACE_EXPRESSION_BLEND_SHAPES;

/// Supported runtime body detail, 4 (densest) through 6.
pub const MIN_LOD: u8 = 4;
pub const MAX_LOD: u8 = 6;

const MODEL_DEFINITION: &str = "compact_v6_1.model";
const CORRECTIVE_ACTIVATION: &str = "corrective_activation.npz";

/// How to load a model.
#[derive(Debug, Clone, Copy)]
pub struct MhrConfig {
    pub lod: u8,
    /// Load the pose-corrective network. It dominates both load time and
    /// memory (2.5 GiB of coefficients at LOD 0), so it can be turned off.
    pub pose_correctives: bool,
}

impl Default for MhrConfig {
    fn default() -> Self {
        Self {
            lod: MIN_LOD,
            pose_correctives: true,
        }
    }
}

/// One forward pass.
pub struct MhrOutput {
    /// Posed vertices in centimetres, `[batch, vertices, 3]`.
    pub vertices: Tensor<3>,
    /// Unit vertex normals of the posed mesh, `[batch, vertices, 3]`.
    ///
    /// Recomputed from the deformed vertices rather than skinned from the rest
    /// pose, because blend shapes and the pose correctives change the surface
    /// itself, not just its rigid frame.
    pub normals: Tensor<3>,
    /// Global joint transforms `[tx, ty, tz, qx, qy, qz, qw, s]`, `[batch, joints, 8]`.
    pub skeleton_state: Tensor<3>,
}

/// The MHR body model.
pub struct Mhr {
    /// Topology and names, kept on the host for lookups and the normal pass.
    pub character: Character,
    pub parameter_transform: ParameterTransform,
    device: Device,

    /// `[model parameters, joints * 7]`, transposed for a right-hand matmul.
    transform: Tensor<2>,
    /// Constant joint-parameter offsets, or `None` when the rig has none.
    offsets: Option<Tensor<2>>,
    num_model_parameters: usize,

    /// `[1, joints, 3]` and `[1, joints, 4]`.
    joint_translation_offsets: Tensor<3>,
    joint_prerotations: Tensor<3>,
    /// `[1, joints, 8]`.
    inverse_bind_pose: Tensor<3>,
    /// Levels of the forward-kinematics prefix scan.
    fk_levels: Vec<rig::FkTensorLevel>,

    /// `[45, vertices * 3]` and `[72, vertices * 3]`.
    identity_basis: Tensor<2>,
    expression_basis: Tensor<2>,
    /// `[1, vertices * 3]`.
    base_shape: Tensor<2>,

    /// The three corners of every triangle, flattened, `[faces * 3]`.
    face_corners: Tensor<1, Int>,

    /// Flattened non-zero skinning influences.
    skin_joint_indices: Tensor<1, Int>,
    skin_vertex_indices: Tensor<1, Int>,
    /// `[1, influences, 1]`.
    skin_weights: Tensor<3>,

    correctives: Option<PoseCorrectives>,
}

/// Accepts either the asset directory itself or its parent.
fn resolve_asset_dir(path: &Path) -> Result<PathBuf> {
    if path.join(MODEL_DEFINITION).is_file() {
        return Ok(path.to_path_buf());
    }
    let nested = path.join("assets");
    if nested.join(MODEL_DEFINITION).is_file() {
        return Ok(nested);
    }
    bail!(
        "no MHR assets in {}: expected {MODEL_DEFINITION} there or under assets/",
        path.display()
    )
}

impl Mhr {
    /// Loads MHR through `fabelgeist-fs`, including `prism://project`, HTTP/blob,
    /// browser File System Access handles, and native filesystem paths.
    pub async fn from_uri(asset_dir: &str, config: MhrConfig, device: &Device) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let base = asset_dir.trim_end_matches(['/', '\\']);
        let read_asset = |name: String| async move {
            let direct = format!("{base}/{name}");
            match fabelgeist_fs::read_bytes(&direct).await {
                Ok(bytes) => Ok(bytes),
                Err(direct_error) => {
                    let nested = format!("{base}/assets/{name}");
                    fabelgeist_fs::read_bytes(&nested).await.map_err(|nested_error| {
                        anyhow::anyhow!(
                            "could not read MHR asset {name:?} from {direct} ({direct_error:#}) or {nested} ({nested_error:#})"
                        )
                    })
                }
            }
        };

        let fbx = read_asset(format!("lod{}.fbx", config.lod)).await?;
        let definition = String::from_utf8(read_asset(MODEL_DEFINITION.into()).await?)
            .map_err(|error| anyhow::anyhow!("MHR model definition is not UTF-8: {error}"))?;
        let corrective_archives = if config.pose_correctives {
            Some((
                read_asset(CORRECTIVE_ACTIVATION.into()).await?,
                read_asset(format!("corrective_blendshapes_lod{}.npz", config.lod)).await?,
            ))
        } else {
            None
        };

        Self::from_asset_bytes(&fbx, &definition, corrective_archives, config, device)
    }

    /// Loads a model from an MHR asset directory (the unpacked `assets.zip`).
    pub fn from_files(
        asset_dir: impl AsRef<Path>,
        config: MhrConfig,
        device: &Device,
    ) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let dir = resolve_asset_dir(asset_dir.as_ref())?;

        let fbx_path = dir.join(format!("lod{}.fbx", config.lod));
        let fbx =
            std::fs::read(&fbx_path).with_context(|| format!("reading {}", fbx_path.display()))?;
        let character = Character::from_fbx_bytes(&fbx, true)
            .with_context(|| format!("loading {}", fbx_path.display()))?;
        let definition_path = dir.join(MODEL_DEFINITION);
        let definition = std::fs::read_to_string(&definition_path)
            .with_context(|| format!("reading {}", definition_path.display()))?;
        let correctives = if config.pose_correctives {
            PoseCorrectives::load(
                &dir.join(CORRECTIVE_ACTIVATION),
                &dir.join(format!("corrective_blendshapes_lod{}.npz", config.lod)),
                character.skeleton.len(),
                character.mesh.vertices.len(),
                device,
            )
            .context("loading the pose-corrective network")?
        } else {
            None
        };
        Self::from_loaded_assets(character, &definition, correctives, device)
    }

    /// Loads MHR from asset bytes, allowing browsers and virtual filesystems to
    /// provide the same FBX/model/NPZ inputs as the native filesystem loader.
    pub fn from_asset_bytes(
        fbx: &[u8],
        definition: &str,
        corrective_archives: Option<(Vec<u8>, Vec<u8>)>,
        config: MhrConfig,
        device: &Device,
    ) -> Result<Self> {
        if !(MIN_LOD..=MAX_LOD).contains(&config.lod) {
            bail!("LOD {} is out of range {MIN_LOD}..={MAX_LOD}", config.lod);
        }
        let character = Character::from_fbx_bytes(fbx, true).context("loading the MHR FBX")?;
        let correctives = if config.pose_correctives {
            let (activation, basis) = corrective_archives
                .context("pose correctives requested but their NPZ archives were not provided")?;
            PoseCorrectives::from_bytes(
                activation,
                basis,
                character.skeleton.len(),
                character.mesh.vertices.len(),
                device,
            )
            .context("loading the pose-corrective network")?
        } else {
            None
        };

        Self::from_loaded_assets(character, definition, correctives, device)
    }

    fn from_loaded_assets(
        character: Character,
        definition: &str,
        correctives: Option<PoseCorrectives>,
        device: &Device,
    ) -> Result<Self> {
        let mut parameter_transform = parse_model_definition(definition, &character.skeleton)
            .context("parsing the MHR model definition")?;
        let num_model_parameters = parameter_transform.num_parameters();
        // momentum appends one model parameter per identity blend shape when a
        // blend shape is attached to the character.
        append_blend_shape_parameters(&mut parameter_transform, NUM_IDENTITY_BLEND_SHAPES);
        Self::new(
            character,
            parameter_transform,
            num_model_parameters,
            correctives,
            device,
        )
    }

    fn new(
        character: Character,
        parameter_transform: ParameterTransform,
        num_model_parameters: usize,
        correctives: Option<PoseCorrectives>,
        device: &Device,
    ) -> Result<Self> {
        let joints = character.skeleton.len();
        let vertices = character.mesh.vertices.len();

        if character.blend_shapes.len() != NUM_BLEND_SHAPES {
            bail!(
                "rig has {} blend shapes, expected {NUM_IDENTITY_BLEND_SHAPES} identity plus \
                 {NUM_FACE_EXPRESSION_BLEND_SHAPES} expression",
                character.blend_shapes.len()
            );
        }

        // Transposed so a forward pass is `parameters @ transform`.
        let transform = parameter_transform
            .transform
            .tensor_transpose(num_model_parameters);

        let offsets = parameter_transform
            .offsets
            .iter()
            .any(|offset| *offset != 0.0)
            .then(|| {
                Tensor::from_data(
                    TensorData::new(
                        parameter_transform.offsets.tensor_values(),
                        [1, joints * PARAMETERS_PER_JOINT],
                    ),
                    device,
                )
            });

        let fk_levels = rig::fk_level_tensors(&character, device)?;

        let basis = &character.blend_shapes.vectors;
        let identity_basis = Tensor::from_data(
            TensorData::new(
                basis[..NUM_IDENTITY_BLEND_SHAPES * vertices * 3].to_vec(),
                [NUM_IDENTITY_BLEND_SHAPES, vertices * 3],
            ),
            device,
        );
        let expression_basis = Tensor::from_data(
            TensorData::new(
                basis[NUM_IDENTITY_BLEND_SHAPES * vertices * 3..].to_vec(),
                [NUM_FACE_EXPRESSION_BLEND_SHAPES, vertices * 3],
            ),
            device,
        );

        // Drop zero influences: MHR averages under three joints per vertex.
        let mut skin_joint_indices = Vec::new();
        let mut skin_vertex_indices = Vec::new();
        let mut skin_weights = Vec::new();
        for (vertex, (indices, weights)) in character
            .skin_weights
            .index
            .iter()
            .zip(&character.skin_weights.weight)
            .enumerate()
        {
            for (joint, weight) in indices.into_iter().zip(weights) {
                if *weight > 1e-5 {
                    skin_joint_indices.push(i32::try_from(usize::from(joint))?);
                    skin_vertex_indices.push(i32::try_from(vertex)?);
                    skin_weights.push(*weight);
                }
            }
        }
        let influences = skin_weights.len();

        let face_corners: Vec<i32> = character
            .mesh
            .faces
            .iter()
            .flatten()
            .map(|corner| i32::try_from(*corner))
            .collect::<Result<_, _>>()?;
        let num_corners = face_corners.len();

        Ok(Self {
            device: device.clone(),
            transform: Tensor::from_data(
                TensorData::new(
                    transform,
                    [num_model_parameters, joints * PARAMETERS_PER_JOINT],
                ),
                device,
            ),
            offsets,
            num_model_parameters,
            joint_translation_offsets: Tensor::from_data(
                TensorData::new(
                    character
                        .skeleton
                        .translation_offsets
                        .as_native_slice()
                        .concat(),
                    [1, joints, 3],
                ),
                device,
            ),
            joint_prerotations: Tensor::from_data(
                TensorData::new(
                    character.skeleton.prerotations.as_native_slice().concat(),
                    [1, joints, 4],
                ),
                device,
            ),
            inverse_bind_pose: Tensor::from_data(
                TensorData::new(
                    character.inverse_bind_pose.as_native_slice().concat(),
                    [1, joints, 8],
                ),
                device,
            ),
            fk_levels,
            identity_basis,
            expression_basis,
            base_shape: Tensor::from_data(
                TensorData::new(character.mesh.vertices.concat(), [1, vertices * 3]),
                device,
            ),
            face_corners: Tensor::from_data(TensorData::new(face_corners, [num_corners]), device),
            skin_joint_indices: Tensor::from_data(
                TensorData::new(skin_joint_indices, [influences]),
                device,
            ),
            skin_vertex_indices: Tensor::from_data(
                TensorData::new(skin_vertex_indices, [influences]),
                device,
            ),
            skin_weights: Tensor::from_data(
                TensorData::new(skin_weights, [1, influences, 1]),
                device,
            ),
            correctives,
            character,
            parameter_transform,
        })
    }

    pub fn num_joints(&self) -> usize {
        self.character.skeleton.len()
    }

    pub fn num_vertices(&self) -> usize {
        self.character.mesh.vertices.len()
    }

    /// Number of pose/scale parameters the model takes, excluding the blend
    /// shape coefficients momentum appends to the parameter vector.
    pub fn num_model_parameters(&self) -> usize {
        self.num_model_parameters
    }

    pub fn has_pose_correctives(&self) -> bool {
        self.correctives.is_some()
    }

    pub fn device(&self) -> &Device {
        &self.device
    }

    /// Zero parameters for a batch, i.e. the rest pose.
    pub fn zero_parameters(&self, batch: usize) -> Tensor<2> {
        Tensor::zeros([batch, self.num_model_parameters], &self.device)
    }

    /// Runs the model.
    ///
    /// * `identity` — `[batch, 45]` shape coefficients (a single row is broadcast).
    /// * `model_parameters` — `[batch, 204]` pose and scale parameters.
    /// * `expression` — `[batch, 72]` facial expression coefficients, optional.
    pub fn forward(
        &self,
        identity: Tensor<2>,
        model_parameters: Tensor<2>,
        expression: Option<Tensor<2>>,
    ) -> Result<MhrOutput> {
        self.forward_with(identity, model_parameters, expression, true)
    }

    /// As [`Mhr::forward`], but able to skip the pose correctives.
    pub fn forward_with(
        &self,
        identity: Tensor<2>,
        model_parameters: Tensor<2>,
        expression: Option<Tensor<2>>,
        apply_correctives: bool,
    ) -> Result<MhrOutput> {
        let batch = model_parameters.dims()[0];
        let joints = self.num_joints();
        let vertices = self.num_vertices();

        let [identity_rows, identity_columns] = identity.dims();
        if identity_columns != NUM_IDENTITY_BLEND_SHAPES {
            bail!(
                "identity coefficients have {identity_columns} columns, expected {NUM_IDENTITY_BLEND_SHAPES}"
            );
        }
        if identity_rows != batch && identity_rows != 1 {
            bail!("identity coefficients have {identity_rows} rows, expected {batch} or 1");
        }
        if model_parameters.dims()[1] != self.num_model_parameters {
            bail!(
                "model parameters have {} columns, expected {}",
                model_parameters.dims()[1],
                self.num_model_parameters
            );
        }

        // Rest shape: mean plus identity and expression offsets.
        let identity = if identity_rows == batch {
            identity
        } else {
            identity.expand([batch, NUM_IDENTITY_BLEND_SHAPES])
        };
        let mut rest = self.base_shape.clone() + identity.matmul(self.identity_basis.clone());
        if let Some(expression) = expression {
            let [rows, columns] = expression.dims();
            if columns != NUM_FACE_EXPRESSION_BLEND_SHAPES {
                bail!(
                    "expression coefficients have {columns} columns, expected {NUM_FACE_EXPRESSION_BLEND_SHAPES}"
                );
            }
            if rows != batch {
                bail!("expression coefficients have {rows} rows, expected {batch}");
            }
            rest = rest + expression.matmul(self.expression_basis.clone());
        }

        // Model parameters drive joint parameters, seven channels per joint.
        //
        // Deliberately a broadcast product and reduction rather than a matmul:
        // the CUDA backend promotes f32 matmuls to tf32, whose 10-bit mantissa
        // costs about 2e-4 relative accuracy. That is invisible in a blend
        // shape but not here, where every joint angle and translation is
        // amplified along the kinematic chain. The tensor is 204 x 889, so the
        // exact form is cheap.
        let mut joint_parameters = (model_parameters.unsqueeze_dim::<3>(2)
            * self.transform.clone().unsqueeze::<3>())
        .sum_dim(1)
        .reshape([batch, joints * PARAMETERS_PER_JOINT]);
        if let Some(offsets) = &self.offsets {
            joint_parameters = joint_parameters + offsets.clone();
        }
        let joint_parameters = joint_parameters.reshape([batch, joints, PARAMETERS_PER_JOINT]);

        let skeleton_state = self.skeleton_state(joint_parameters.clone());

        let mut rest = rest.reshape([batch, vertices, 3]);
        if apply_correctives && let Some(correctives) = &self.correctives {
            rest = rest + correctives.forward(joint_parameters);
        }

        let vertices = self.skin(skeleton_state.clone(), rest);

        Ok(MhrOutput {
            normals: self.vertex_normals(vertices.clone()),
            vertices,
            skeleton_state,
        })
    }

    /// Joint parameters `[batch, joints, 7]` to global skeleton states.
    fn skeleton_state(&self, joint_parameters: Tensor<3>) -> Tensor<3> {
        let translation =
            joint_parameters.clone().narrow(2, 0, 3) + self.joint_translation_offsets.clone();
        let rotation = skel_state::quaternion_multiply(
            self.joint_prerotations.clone(),
            skel_state::euler_xyz_to_quaternion(joint_parameters.clone().narrow(2, 3, 3)),
        );
        // momentum stores scale as a power of two.
        let scale = (joint_parameters.narrow(2, 6, 1) * std::f32::consts::LN_2).exp();

        let mut state = Tensor::cat(vec![translation, rotation, scale], 2);
        for (source, target) in &self.fk_levels {
            let parent = state.clone().select(1, target.clone());
            let child = state.clone().select(1, source.clone());
            // An overwrite expressed as an accumulation: source indices are
            // unique within a level, and `Assign` has no backend kernel here.
            let delta = skel_state::multiply(parent, child.clone()) - child;
            state = state.select_assign(1, source.clone(), delta, IndexingUpdateOp::Add);
        }
        state
    }

    /// Area-weighted vertex normals of a posed mesh, `[batch, vertices, 3]`.
    ///
    /// Each triangle contributes its unnormalized cross product, whose length
    /// is twice the triangle's area, to all three of its corners. That is the
    /// weighting `THREE.BufferGeometry.computeVertexNormals` uses, which is
    /// what the reference web viewer shades MHR with.
    fn vertex_normals(&self, vertices: Tensor<3>) -> Tensor<3> {
        let batch = vertices.dims()[0];
        let faces = self.character.mesh.faces.len();

        let corners = vertices
            .select(1, self.face_corners.clone())
            .reshape([batch, faces, 3, 3]);
        let corner = |index: usize| {
            corners
                .clone()
                .narrow(2, index, 1)
                .reshape([batch, faces, 3])
        };
        let (first, second, third) = (corner(0), corner(1), corner(2));
        let (u, v) = (second - first.clone(), third - first);

        let axis = |t: &Tensor<3>, index: usize| t.clone().narrow(2, index, 1);
        let cross = Tensor::cat(
            vec![
                axis(&u, 1) * axis(&v, 2) - axis(&u, 2) * axis(&v, 1),
                axis(&u, 2) * axis(&v, 0) - axis(&u, 0) * axis(&v, 2),
                axis(&u, 0) * axis(&v, 1) - axis(&u, 1) * axis(&v, 0),
            ],
            2,
        );

        // The same face normal lands on each of the face's three corners.
        let contribution = cross
            .unsqueeze_dim::<4>(2)
            .expand([batch, faces, 3, 3])
            .reshape([batch, faces * 3, 3]);
        let accumulated = Tensor::zeros([batch, self.num_vertices(), 3], &self.device)
            .select_assign(
                1,
                self.face_corners.clone(),
                contribution,
                IndexingUpdateOp::Add,
            );

        // A vertex no triangle references keeps a zero normal, as it does in
        // three.js; nothing rasterizes it, so there is no direction to invent.
        let length = accumulated
            .clone()
            .powi_scalar(2)
            .sum_dim(2)
            .sqrt()
            .clamp_min(1e-12);
        accumulated / length
    }

    /// Linear blend skinning of `rest` `[batch, vertices, 3]`.
    fn skin(&self, skeleton_state: Tensor<3>, rest: Tensor<3>) -> Tensor<3> {
        let batch = rest.dims()[0];
        let joint_state = skel_state::multiply(skeleton_state, self.inverse_bind_pose.clone());

        let transforms = joint_state.select(1, self.skin_joint_indices.clone());
        let points = rest.clone().select(1, self.skin_vertex_indices.clone());
        let deformed =
            skel_state::transform_points(&transforms, points) * self.skin_weights.clone();

        Tensor::zeros(rest.dims(), &self.device)
            .select_assign(
                1,
                self.skin_vertex_indices.clone(),
                deformed,
                IndexingUpdateOp::Add,
            )
            .reshape([batch, self.num_vertices(), 3])
    }
}

//! Translate the pinned MHR parameter definition into the portable skeleton basis.

use adventuresim_core::character_proportions::{
    BODY_PROPORTION_COUNT, BodyProportion, CharacterProportions, JointProportionBasis,
};
use anyhow::{Context, Result, ensure};
use fabelgeist_mhr::{
    Mhr,
    model_def::{JointChannel, ModelParameterName, ModelParameterTable},
};
use fabelgeist_rig::RigJointTable;

const CENTIMETRES_PER_METRE: f32 = 100.0;

pub fn model_parameters(
    model: &Mhr,
    proportions: CharacterProportions,
) -> Result<ModelParameterTable<f32>> {
    let mut parameters = ModelParameterTable::filled(model.num_model_parameters(), 0.0);
    for proportion in BodyProportion::ALL {
        let column = model
            .parameter_transform
            .parameter_index(&ModelParameterName::from(proportion.mhr_parameter()))
            .with_context(|| format!("MHR is missing {}", proportion.mhr_parameter()))?;
        parameters[column] = proportions.get(proportion);
    }
    Ok(parameters)
}

pub fn joint_bases(
    model: &Mhr,
    reference: CharacterProportions,
) -> Result<RigJointTable<JointProportionBasis>> {
    let transform = &model.parameter_transform;
    let mut bases: RigJointTable<_> = transform
        .joints()
        .map(|_| JointProportionBasis {
            reference,
            translation_metres: [[0.0; 3]; BODY_PROPORTION_COUNT],
        })
        .collect();
    for proportion in BodyProportion::ALL {
        let column = transform
            .parameter_index(&ModelParameterName::from(proportion.mhr_parameter()))
            .with_context(|| format!("MHR is missing {}", proportion.mhr_parameter()))?;
        let limits = transform
            .limits()
            .iter()
            .find(|limit| limit.parameter == column)
            .context("MHR body proportion has no limits")?;
        ensure!(
            limits.min == -proportion.limit() && limits.max == proportion.limit(),
            "MHR body proportion limits differ from the shared contract"
        );
        for (joint, basis) in transform.joints().zip(bases.iter_mut()) {
            for (axis, channel) in JointChannel::TRANSLATIONS.into_iter().enumerate() {
                basis.translation_metres[proportion.index()][axis] = *joint
                    .channel(channel)
                    .get(column)
                    .context("MHR translation row is missing its parameter column")?
                    / CENTIMETRES_PER_METRE;
            }
            let mut translation_only = true;
            for channel in JointChannel::ROTATION_AND_SCALE {
                translation_only &= *joint
                    .channel(channel)
                    .get(column)
                    .context("MHR rotation/scale row is missing its parameter column")?
                    == 0.0;
            }
            ensure!(
                translation_only,
                "skeletal translation basis cannot encode rotation or scale for {}",
                proportion.mhr_parameter()
            );
        }
    }
    Ok(bases)
}

//! Spawn generated clothing and armor into the studio preview.

use super::*;
use adventuresim_character_creator::clothing::ClothingShell;

/// How a piece is shaded: its plate, and the band along its edges.
pub(super) struct ArmorShading<'a> {
    pub plate: StandardMaterial,
    pub trim: Option<TrimPreview<'a>>,
}

/// The band along a piece's edges, as the preview shades it.
pub(super) struct TrimPreview<'a> {
    pub texcoords: &'a [[f32; 2]],
    pub material: StandardMaterial,
}

pub(super) fn spawn_clothing(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    walk: &WalkPreview,
    model: &BodyModel,
    shells: Vec<ClothingShell>,
) -> Result<()> {
    for shell in shells {
        let specification = shell.specification;
        let indices = shell
            .faces
            .iter()
            .flat_map(|face| face.iter().copied())
            .collect::<Vec<_>>();
        let mut mesh = Mesh::new(
            PrimitiveTopology::TriangleList,
            RenderAssetUsages::default(),
        )
        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, shell.positions)
        .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, shell.normals)
        .with_inserted_indices(Indices::U32(indices));
        animation_preview::skin_mesh(
            &mut mesh,
            model.mhr.character.skin_weights.indices(),
            model.mhr.character.skin_weights.weights().as_native_slice(),
        )?;
        let [red, green, blue, alpha] = specification.base_color;
        commands.spawn((
            CharacterMesh,
            animation_preview::skin(walk).context("animation preview has no rebuilt rig")?,
            Name::new(specification.name.as_ref().to_owned()),
            Mesh3d(meshes.add(mesh)),
            MeshMaterial3d(materials.add(StandardMaterial {
                base_color: Color::srgba(red, green, blue, alpha),
                metallic: specification.metallic,
                perceptual_roughness: specification.roughness,
                ..default()
            })),
        ));
    }
    Ok(())
}

/// The cord lacing a piece's small plates, as the preview shades it.
pub(super) fn lacing_material(cord: &fabelgeist_armor::Lacing) -> StandardMaterial {
    let [red, green, blue] = cord.color;
    StandardMaterial {
        base_color: Color::srgb(red, green, blue),
        metallic: 0.0,
        perceptual_roughness: cord.roughness,
        ..default()
    }
}

/// Spawn each surface of a piece, and its trim band when it has one.
#[expect(
    clippy::too_many_arguments,
    reason = "Bevy asset stores and spawn context are borrowed independently"
)]
pub(super) fn spawn_armor(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    images: &mut Assets<Image>,
    armor: &GeneratedArmor,
    name: String,
    shading: ArmorShading<'_>,
    marker: impl Bundle + Clone,
) -> Result<()> {
    let ArmorShading {
        plate: material,
        trim,
    } = shading;
    for surface in armor.surfaces() {
        let part_name = match surface.component {
            Some(index) => format!("{name}.{}", armor.components[index].role.name()),
            None => name.clone(),
        };
        // A component with its own material, such as leather straps, is not
        // shaded as the piece's plate.
        let mut own = surface
            .component
            .and_then(|index| armor.components[index].material)
            .map(|surface| {
                let [r, g, b, a] = surface.base_color;
                StandardMaterial {
                    base_color: Color::srgba(r, g, b, a),
                    metallic: surface.metallic,
                    perceptual_roughness: surface.roughness,
                    ..default()
                }
            });
        if let Some(textile) = surface
            .component
            .and_then(|index| armor.components[index].textile.as_ref())
        {
            own = Some(adventuresim_character_creator::textile_surface::material(
                textile, images,
            )?);
        }
        let mut parts = vec![(
            part_name.clone(),
            surface.plate,
            armor.texcoords.as_slice(),
            own.as_ref().unwrap_or(&material),
        )];
        if let Some(trim) = trim.as_ref().filter(|_| !surface.trim.is_empty()) {
            parts.push((
                format!("{part_name}.trim"),
                surface.trim,
                trim.texcoords,
                &trim.material,
            ));
        }
        for (part_name, indices, texcoords, material) in parts {
            let mut mesh = Mesh::new(
                PrimitiveTopology::TriangleList,
                RenderAssetUsages::default(),
            )
            .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, armor.positions.clone())
            .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, armor.normals.clone())
            .with_inserted_attribute(Mesh::ATTRIBUTE_UV_0, texcoords.to_vec())
            .with_inserted_indices(Indices::U32(armor.indices[indices].to_vec()));
            if material.normal_map_texture.is_some() {
                mesh.generate_tangents()
                    .context("generating tangents for textured armor preview")?;
            }
            commands.spawn((
                marker.clone(),
                Name::new(part_name),
                Mesh3d(meshes.add(mesh)),
                MeshMaterial3d(materials.add(material.clone())),
            ));
        }
    }
    Ok(())
}

/// The previewed body's skin colour, sRGB.
pub(super) const SKIN_COLOR: Color = Color::srgb(0.64, 0.39, 0.30);

pub(super) fn spawn_body(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    walk: &WalkPreview,
    model: &BodyModel,
    generated: &GeneratedCharacter,
    mut mesh: Mesh,
) -> Result<()> {
    animation_preview::skin_mesh(
        &mut mesh,
        model.mhr.character.skin_weights.indices(),
        model.mhr.character.skin_weights.weights().as_native_slice(),
    )?;
    commands.spawn((
        CharacterMesh,
        animation_preview::BodySkin {
            positions: generated.positions.clone(),
            faces: model.mhr.character.mesh.faces.clone(),
            indices: model.mhr.character.skin_weights.indices().clone(),
            weights: model
                .mhr
                .character
                .skin_weights
                .weights()
                .as_native_slice()
                .to_vec(),
        },
        animation_preview::skin(walk).context("animation preview has no rebuilt rig")?,
        Mesh3d(meshes.add(mesh)),
        MeshMaterial3d(materials.add(skin_material())),
    ));
    Ok(())
}

/// The previewed skin: of the body, and of the scalp cap under hair.
pub(super) fn skin_material() -> StandardMaterial {
    StandardMaterial {
        // Skin is a rough dielectric with a small amount of diffuse
        // transmission. This keeps thin features such as the nose, ears,
        // and fingers warm instead of crushing them to black.
        base_color: SKIN_COLOR,
        metallic: 0.0,
        perceptual_roughness: 0.52,
        reflectance: 0.46,
        specular_tint: Color::srgb(1.0, 0.93, 0.89),
        // A small back-diffuse lobe is Bevy's inexpensive approximation
        // of the short scattering distance seen in skin. Kept subtle so
        // the body remains opaque and shadowed rather than wax-like.
        diffuse_transmission: 0.045,
        ..default()
    }
}

//! Sample MHR identity and refit clothing with fixed vertex correspondence.

use super::*;
use adventuresim_character_creator::clothing::ClothingShell;
use adventuresim_core::character_morph::{IDENTITY_MORPH_STEP, IdentityMorph};
use adventuresim_core::skeletal_fit::SkeletalFitMorph;
use fabelgeist_mhr::character::{MeshVertexIndex, MeshVertexTable};

mod draped;
mod hair;

pub(super) struct MorphDelta {
    name: String,
    positions: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
}

pub(super) struct CharacterMorphs {
    pub samples: Vec<ForearmMorphSample>,
    pub body: Vec<MorphDelta>,
    reference_joints: fabelgeist_rig::RigJointTable<[f32; 8]>,
    joint_indices: fabelgeist_rig::PackedRigSkin<8>,
    joint_weights: MeshVertexTable<[f32; 8]>,
}

/// A piece's shells: its plates, and the bands along their edges.
pub(super) struct RiggedArmor<'a> {
    pub plate: Vec<RiggedShell<'a>>,
    pub trim: Vec<RiggedShell<'a>>,
}

impl MorphDelta {
    fn between(
        name: String,
        base_positions: &[[f32; 3]],
        base_normals: &[[f32; 3]],
        positions: &[[f32; 3]],
        normals: &[[f32; 3]],
    ) -> Result<Self> {
        anyhow::ensure!(
            base_positions.len() == positions.len() && base_normals.len() == normals.len(),
            "morph sample changed vertex correspondence"
        );
        let subtract = |base: &[[f32; 3]], sample: &[[f32; 3]]| {
            base.iter()
                .zip(sample)
                .map(|(base, sample)| std::array::from_fn(|axis| sample[axis] - base[axis]))
                .collect()
        };
        Ok(Self {
            name,
            positions: subtract(base_positions, positions),
            normals: subtract(base_normals, normals),
        })
    }

    pub(super) fn rigged(&self) -> RiggedMorphTarget<'_> {
        RiggedMorphTarget {
            name: &self.name,
            position_deltas: &self.positions,
            normal_deltas: &self.normals,
        }
    }
}

impl CharacterMorphs {
    pub(super) fn generate(
        model: &BodyModel,
        recipe: &CharacterRecipe,
        base: &GeneratedCharacter,
    ) -> Result<Self> {
        let mut samples = Vec::new();
        let mut body = Vec::new();
        for target in IdentityMorph::all() {
            let mut sample_recipe = recipe.clone();
            sample_recipe.identity[target.index()] += IDENTITY_MORPH_STEP;
            let sample = generate_character(model, &sample_recipe)?;
            body.push(MorphDelta::between(
                target.name(),
                &base.positions,
                &base.normals,
                &sample.positions,
                &sample.normals,
            )?);
            samples.push(ForearmMorphSample {
                name: target.name(),
                positions: sample.positions,
                normals: sample.normals,
                global_joint_states: sample.global_joint_states,
                device: Default::default(),
            });
        }
        for target in SkeletalFitMorph::ALL {
            let mut sample_recipe = recipe.clone();
            sample_recipe
                .proportions
                .set(target.proportion(), target.endpoint())
                .map_err(anyhow::Error::msg)?;
            let sample = generate_character(model, &sample_recipe)?;
            body.push(MorphDelta {
                name: target.name().into(),
                positions: vec![[0.0; 3]; base.positions.len()],
                normals: vec![[0.0; 3]; base.normals.len()],
            });
            samples.push(ForearmMorphSample {
                name: target.name().into(),
                positions: sample.positions,
                normals: sample.normals,
                global_joint_states: sample.global_joint_states,
                device: Default::default(),
            });
        }
        Ok(Self {
            samples,
            body,
            reference_joints: base.global_joint_states.clone(),
            joint_indices: model.mhr.character.skin_weights.indices().clone(),
            joint_weights: model.mhr.character.skin_weights.weights().clone(),
        })
    }

    pub(super) fn clothing(&self, shells: &[ClothingShell]) -> Result<Vec<Vec<MorphDelta>>> {
        shells
            .iter()
            .map(|base| {
                self.samples
                    .iter()
                    .map(|sample| {
                        let fitted = base
                            .refit(&sample.positions, &sample.normals)
                            .map_err(anyhow::Error::from)?;
                        let mut delta = MorphDelta::between(
                            sample.name.clone(),
                            &base.positions,
                            &base.normals,
                            &fitted.positions,
                            &fitted.normals,
                        )?;
                        remove_skeletal_translation(
                            &mut delta.positions,
                            sample,
                            &self.reference_joints,
                            &self.joint_indices,
                            self.joint_weights
                                .indexed()
                                .map(|(vertex, weights)| (vertex, *weights)),
                        );
                        Ok(delta)
                    })
                    .collect()
            })
            .collect()
    }
}

pub(super) fn correct_armor_fit(
    mut armor: GeneratedArmor,
    reference: &GeneratedCharacter,
    samples: &[ForearmMorphSample],
) -> GeneratedArmor {
    for target in &mut armor.morphs {
        if let Some(sample) = samples.iter().find(|sample| sample.name == target.name) {
            remove_skeletal_translation(
                &mut target.position_deltas,
                sample,
                &reference.global_joint_states,
                &armor.joint_indices,
                armor
                    .joint_weights
                    .iter()
                    .enumerate()
                    .map(|(vertex, weights)| {
                        (MeshVertexIndex::from_native_vertex_index(vertex), *weights)
                    }),
            );
        }
    }
    armor
}

