/// The shells of a piece, one per component, or `name` for the whole piece
/// and `trim_name` for its band.
pub(super) fn rigged_armor<'a>(
    name: &'a str,
    trim_name: &'a str,
    armor: &'a GeneratedArmor,
    faces: &'a [[u32; 3]],
    targets: &'a [RiggedMorphTarget<'a>],
) -> RiggedArmor<'a> {
    let shell = |name, faces, hinge| RiggedShell {
        textile_finish: None,
        plate_edges: &[],
        surface: None,
        textures: None,
        texcoords: Some(&armor.texcoords),
        name,
        hinge,
        positions: &armor.positions,
        normals: &armor.normals,
        faces,
        joint_indices: Some(&armor.joint_indices),
        joint_weights: Some(&armor.joint_weights),
        morph_targets: targets,
        base_color: [0.769, 0.776, 0.776, 1.0],
        metallic: 1.0,
        roughness: 0.20,
    };
    let triangles = |range: std::ops::Range<usize>| &faces[range.start / 3..range.end / 3];
    let mut rigged = RiggedArmor {
        plate: Vec::new(),
        trim: Vec::new(),
    };
    for surface in armor.surfaces() {
        let component = surface.component.map(|index| &armor.components[index]);
        let hinge = component.and_then(|component| component.hinge);
        rigged.plate.push(shell(
            component.map_or(name, |component| component.role.name()),
            triangles(surface.plate),
            hinge,
        ));
        if !surface.trim.is_empty() {
            rigged.trim.push(shell(
                component.map_or(trim_name, |component| component.role.trim_name()),
                triangles(surface.trim),
                hinge,
            ));
        }
    }
    rigged
}

/// Fit targets contain only the displacement not already produced by the bones.
fn remove_skeletal_translation(
    deltas: &mut [[f32; 3]],
    sample: &ForearmMorphSample,
    reference: &fabelgeist_rig::RigJointTable<[f32; 8]>,
    indices: &fabelgeist_rig::PackedRigSkin<8>,
    weights: impl IntoIterator<Item = (MeshVertexIndex, [f32; 8])>,
) {
    if SkeletalFitMorph::from_name(&sample.name).is_none() {
        return;
    }
    for (delta, (vertex, weights)) in deltas.iter_mut().zip(weights) {
        let skin = indices
            .weighted_vertex(vertex.native_vertex_index(), weights)
            .strongest_four();
        for (joint, weight) in skin.joints.into_iter().zip(skin.weights) {
            if weight == 0.0 {
                continue;
            }
            for (axis, value) in delta.iter_mut().enumerate() {
                *value -=
                    weight * (sample.global_joint_states[joint][axis] - reference[joint][axis]);
            }
        }
    }
}

