//! Translate the pinned MHR parameter definition into the portable skeleton basis.

use adventuresim_core::character_proportions::{
    BODY_PROPORTION_COUNT, BodyProportion, CharacterProportions, JointProportionBasis,
};
use anyhow::{Context, Result, ensure};
use fabelgeist_mhr::{
    Mhr,
    model_def::{JointChannel, JointParameterRow, ModelParameterName},
};
use fabelgeist_rig::RigJointTable;

const CENTIMETRES_PER_METRE: f32 = 100.0;

pub fn model_parameters(model: &Mhr, proportions: CharacterProportions) -> Result<Vec<f32>> {
    let mut parameters = vec![0.0; model.num_model_parameters()];
    for proportion in BodyProportion::ALL {
        let column = model
            .parameter_transform
            .parameter_index(&ModelParameterName::from(proportion.mhr_parameter()))
            .with_context(|| format!("MHR is missing {}", proportion.mhr_parameter()))?;
        parameters[column.native_index()] = proportions.get(proportion);
    }
    Ok(parameters)
}

pub fn joint_bases(
    model: &Mhr,
    reference: CharacterProportions,
) -> Result<RigJointTable<JointProportionBasis>> {
    let transform = &model.parameter_transform;
    let mut bases: RigJointTable<JointProportionBasis> = vec![
        JointProportionBasis {
            reference,
            translation_metres: [[0.0; 3]; BODY_PROPORTION_COUNT],
        };
        model.num_joints()
    ]
    .into();
    for proportion in BodyProportion::ALL {
        let column = transform
            .parameter_index(&ModelParameterName::from(proportion.mhr_parameter()))
            .with_context(|| format!("MHR is missing {}", proportion.mhr_parameter()))?;
        let limits = transform
            .limits
            .iter()
            .find(|limit| limit.parameter == column)
            .context("MHR body proportion has no limits")?;
        ensure!(
            limits.min == -proportion.limit() && limits.max == proportion.limit(),
            "MHR body proportion limits differ from the shared contract"
        );
        for joint in bases.ordinals() {
            let basis = &mut bases[joint];
            for (axis, channel) in JointChannel::TRANSLATIONS.into_iter().enumerate() {
                basis.translation_metres[proportion.index()][axis] = transform
                    .row(JointParameterRow::new(joint, channel))[column]
                    / CENTIMETRES_PER_METRE;
            }
            ensure!(
                JointChannel::ROTATION_AND_SCALE
                    .into_iter()
                    .all(
                        |channel| transform.row(JointParameterRow::new(joint, channel))[column]
                            == 0.0
                    ),
                "skeletal translation basis cannot encode rotation or scale for {}",
                proportion.mhr_parameter()
            );
        }
    }
    Ok(bases)
}

//! Spawn generated clothing and armor into the studio preview.

use super::*;
use adventuresim_character_creator::clothing::ClothingShell;

/// How a piece is shaded: its plate, and the band along its edges.
pub(super) struct ArmorShading<'a> {
    pub plate: StandardMaterial,
    pub trim: Option<TrimPreview<'a>>,
}

/// The band along a piece's edges, as the preview shades it.
pub(super) struct TrimPreview<'a> {
    pub texcoords: &'a [[f32; 2]],
    pub material: StandardMaterial,
}

pub(super) fn spawn_clothing(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    walk: &WalkPreview,
    model: &BodyModel,
    shells: Vec<ClothingShell>,
) -> Result<()> {
    for shell in shells {
        let specification = shell.specification;
        let indices = shell
            .faces
            .iter()
            .flat_map(|face| face.iter().copied())
            .collect::<Vec<_>>();
        let mut mesh = Mesh::new(
            PrimitiveTopology::TriangleList,
            RenderAssetUsages::default(),
        )
        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, shell.positions)
        .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, shell.normals)
        .with_inserted_indices(Indices::U32(indices));
        animation_preview::skin_mesh(
            &mut mesh,
            &model.mhr.character.skin_weights.index,
            &model.mhr.character.skin_weights.weight,
        )?;
        let [red, green, blue, alpha] = specification.base_color;
        commands.spawn((
            CharacterMesh,
            animation_preview::skin(walk).context("animation preview has no rebuilt rig")?,
            Name::new(specification.name.as_ref().to_owned()),
            Mesh3d(meshes.add(mesh)),
            MeshMaterial3d(materials.add(StandardMaterial {
                base_color: Color::srgba(red, green, blue, alpha),
                metallic: specification.metallic,
                perceptual_roughness: specification.roughness,
                ..default()
            })),
        ));
    }
    Ok(())
}

/// The cord lacing a piece's small plates, as the preview shades it.
pub(super) fn lacing_material(cord: &fabelgeist_armor::Lacing) -> StandardMaterial {
    let [red, green, blue] = cord.color;
    StandardMaterial {
        base_color: Color::srgb(red, green, blue),
        metallic: 0.0,
        perceptual_roughness: cord.roughness,
        ..default()
    }
}

/// Spawn each surface of a piece, and its trim band when it has one.
#[expect(
    clippy::too_many_arguments,
    reason = "Bevy asset stores and spawn context are borrowed independently"
)]
pub(super) fn spawn_armor(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    images: &mut Assets<Image>,
    armor: &GeneratedArmor,
    name: String,
    shading: ArmorShading<'_>,
    marker: impl Bundle + Clone,
) -> Result<()> {
    let ArmorShading {
        plate: material,
        trim,
    } = shading;
    for surface in armor.surfaces() {
        let part_name = match surface.component {
            Some(index) => format!("{name}.{}", armor.components[index].role.name()),
            None => name.clone(),
        };
        // A component with its own material, such as leather straps, is not
        // shaded as the piece's plate.
        let mut own = surface
            .component
            .and_then(|index| armor.components[index].material)
            .map(|surface| {
                let [r, g, b, a] = surface.base_color;
                StandardMaterial {
                    base_color: Color::srgba(r, g, b, a),
                    metallic: surface.metallic,
                    perceptual_roughness: surface.roughness,
                    ..default()
                }
            });
        if let Some(textile) = surface
            .component
            .and_then(|index| armor.components[index].textile.as_ref())
        {
            own = Some(adventuresim_character_creator::textile_surface::material(
                textile, images,
            )?);
        }
        let mut parts = vec![(
            part_name.clone(),
            surface.plate,
            armor.texcoords.as_slice(),
            own.as_ref().unwrap_or(&material),
        )];
        if let Some(trim) = trim.as_ref().filter(|_| !surface.trim.is_empty()) {
            parts.push((
                format!("{part_name}.trim"),
                surface.trim,
                trim.texcoords,
                &trim.material,
            ));
        }
        for (part_name, indices, texcoords, material) in parts {
            let mut mesh = Mesh::new(
                PrimitiveTopology::TriangleList,
                RenderAssetUsages::default(),
            )
            .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, armor.positions.clone())
            .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, armor.normals.clone())
            .with_inserted_attribute(Mesh::ATTRIBUTE_UV_0, texcoords.to_vec())
            .with_inserted_indices(Indices::U32(armor.indices[indices].to_vec()));
            if material.normal_map_texture.is_some() {
                mesh.generate_tangents()
                    .context("generating tangents for textured armor preview")?;
            }
            commands.spawn((
                marker.clone(),
                Name::new(part_name),
                Mesh3d(meshes.add(mesh)),
                MeshMaterial3d(materials.add(material.clone())),
            ));
        }
    }
    Ok(())
}

/// The previewed body's skin colour, sRGB.
pub(super) const SKIN_COLOR: Color = Color::srgb(0.64, 0.39, 0.30);

pub(super) fn spawn_body(
    commands: &mut Commands,
    meshes: &mut Assets<Mesh>,
    materials: &mut Assets<StandardMaterial>,
    walk: &WalkPreview,
    model: &BodyModel,
    generated: &GeneratedCharacter,
    mut mesh: Mesh,
) -> Result<()> {
    animation_preview::skin_mesh(
        &mut mesh,
        &model.mhr.character.skin_weights.index,
        &model.mhr.character.skin_weights.weight,
    )?;
    commands.spawn((
        CharacterMesh,
        animation_preview::BodySkin {
            positions: generated.positions.clone(),
            faces: model.mhr.character.mesh.faces.clone(),
            indices: model.mhr.character.skin_weights.index.clone(),
            weights: model.mhr.character.skin_weights.weight.clone(),
        },
        animation_preview::skin(walk).context("animation preview has no rebuilt rig")?,
        Mesh3d(meshes.add(mesh)),
        MeshMaterial3d(materials.add(skin_material())),
    ));
    Ok(())
}

/// The previewed skin: of the body, and of the scalp cap under hair.
pub(super) fn skin_material() -> StandardMaterial {
    StandardMaterial {
        // Skin is a rough dielectric with a small amount of diffuse
        // transmission. This keeps thin features such as the nose, ears,
        // and fingers warm instead of crushing them to black.
        base_color: SKIN_COLOR,
        metallic: 0.0,
        perceptual_roughness: 0.52,
        reflectance: 0.46,
        specular_tint: Color::srgb(1.0, 0.93, 0.89),
        // A small back-diffuse lobe is Bevy's inexpensive approximation
        // of the short scattering distance seen in skin. Kept subtle so
        // the body remains opaque and shadowed rather than wax-like.
        diffuse_transmission: 0.045,
        ..default()
    }
}

