        .map(|targets| targets.iter().map(MorphDelta::rigged).collect::<Vec<_>>())
        .collect::<Vec<_>>();
    let (plate_faces, plate_targets) = piece_geometry(&armor, |piece| Some(&piece.generated));
    let (lacing_faces, lacing_targets) =
        piece_geometry(&armor, |piece| piece.lacing.as_ref().map(|l| &l.generated));
    let mut shells = clothed
        .shells
        .iter()
        .zip(&clothing_targets)
        .map(|(shell, targets)| rigged_clothing(shell, targets))
        .collect::<Vec<_>>();
    let metals = catalog_metals(&armor)?;
    shells.extend(catalog_shells(
        &armor,
        CatalogGeometry {
            faces: &plate_faces,
            targets: &plate_targets,
        },
        CatalogGeometry {
            faces: &lacing_faces,
            targets: &lacing_targets,
        },
        &metals,
    )?);
    let draped_morphs = morphs.draped(&generated, &character.mesh.faces, &fitted)?;
    let draped_targets: Vec<_> = draped_morphs
        .iter()
        .map(|targets| targets.iter().map(MorphDelta::rigged).collect::<Vec<_>>())
        .collect();
    let mail_surfaces = mail_surfaces(&loadout, &fitted)?;
    for ((garment, targets), mail) in fitted.iter().zip(&draped_targets).zip(&mail_surfaces) {
        shells.push(garment.rigged(targets, mail.as_ref()));
    }
    let hair = recipe
        .hair
        .map(|design| hair::ExportedHair::grow(model, &generated, &morphs, design))
        .transpose()?;
    let hair_targets = hair
        .as_ref()
        .map(hair::ExportedHair::targets)
        .unwrap_or_default();
    shells.extend(hair.as_ref().map(|hair| hair.shell(&hair_targets)));
    export_rigged_glb(
        GlbOutput::Standalone(path),
        &recipe.name,
        recipe.version,
        model.lod,
        &RiggedMesh {
            joint_proportions: &generated.joint_proportions,
            morph_targets: &body_targets,
            positions: &generated.positions,
            normals: &generated.normals,
            faces: &clothed.visible_body_faces,
            export_body: true,
            joint_indices: &character.skin_weights.index,
            joint_weights: &character.skin_weights.weight,
            joint_names: &character.skeleton.names,
            joint_parents: &character.skeleton.parents,
            global_joint_states: &generated.global_joint_states,
        },
        &shells,
        &[],
    )?;
    Ok(warnings)
}

type CatalogMetals = Vec<(
    fabelgeist_armor::material::Metal,
    adventuresim_character_creator::export::ShellTextures,
)>;

/// Maps for each distinct catalog steel and trim worn, engraving included,
/// baked once.
fn catalog_metals(armor: &[parametric_equipment::SelectedArmor<'_>]) -> Result<CatalogMetals> {
    let mut metals: CatalogMetals = Vec::new();
    for piece in armor {
        let material = equipment_catalog::material(piece.piece.piece.selection.item())?;
        let plate = adventuresim_character_creator::armor_metal::metal(
            material,
            piece.piece.decoration.engraving.as_ref(),
        );
        let trim = piece.trim.as_ref().map(|trim| trim.metal.clone());
        for metal in plate.into_iter().chain(trim) {
            if metals.iter().any(|(known, _)| *known == metal) {
                continue;
            }
            let textures = adventuresim_character_creator::export::ShellTextures::armor(&metal)?;
            metals.push((metal, textures));
        }
    }
    Ok(metals)
}

/// Each worn piece's triangles and morph targets for the mesh `mesh` picks
/// of it; empty where it has none.
fn piece_geometry<'a>(
    armor: &'a [parametric_equipment::SelectedArmor<'_>],
    mesh: impl Fn(&'a parametric_equipment::SelectedArmor<'_>) -> Option<&'a GeneratedArmor>,
) -> (Vec<Vec<[u32; 3]>>, Vec<Vec<RiggedMorphTarget<'a>>>) {
    armor
        .iter()
        .map(|piece| {
            mesh(piece).map_or_else(Default::default, |mesh| {
                (
                    mesh.indices.as_chunks::<3>().0.to_vec(),
                    armor_targets(mesh),
                )
            })
        })
        .unzip()
}

/// Each worn piece's triangles and morph targets, for one of its meshes.
struct CatalogGeometry<'a> {
    faces: &'a [Vec<[u32; 3]>],
    targets: &'a [Vec<RiggedMorphTarget<'a>>],
}

fn catalog_shells<'a>(
    armor: &'a [parametric_equipment::SelectedArmor<'_>],
    plates: CatalogGeometry<'a>,
    lacing: CatalogGeometry<'a>,
    metals: &'a CatalogMetals,
) -> Result<Vec<RiggedShell<'a>>> {
    let mut shells = Vec::new();
    for (i, piece) in armor.iter().enumerate() {
        let trim_name = piece.trim.as_ref().map_or(&piece.name, |trim| &trim.name);
        let rigged = rigged_armor(
            &piece.name,
            trim_name,
            &piece.generated,
            &plates.faces[i],
            &plates.targets[i],
        );
        let mut parts = rigged.plate;
        let material = equipment_catalog::material(piece.piece.piece.selection.item())?;
        let (color, metallic, roughness) = adventuresim_character_creator::equipment_pbr(material);
        let metal = adventuresim_character_creator::armor_metal::metal(
            material,
            piece.piece.decoration.engraving.as_ref(),
        )
        .and_then(|metal| metals.iter().find(|(known, _)| *known == metal))
        .map(|(_, textures)| (piece.generated.texcoords.as_slice(), textures));
        for shell in &mut parts {
            shell.base_color = color;
            shell.metallic = metallic;
            shell.roughness = roughness;
            shell.textures = adventuresim_character_creator::underlayer_material::textures(
                piece.piece.design.recipe(),
            );
            shell.surface = metal;
        }
        crate::character_morphs::component_materials(&piece.generated, &mut parts)?;
        shells.extend(parts);
        if let Some(trim) = &piece.trim {
            let textures = metals
                .iter()
                .find(|(known, _)| *known == trim.metal)
                .map(|(_, textures)| textures)
                .context("trim metal was not baked")?;
            let [red, green, blue] = trim.metal.color;
            for mut shell in rigged.trim {
                shell.base_color = [red, green, blue, 1.0];
                shell.metallic = 1.0;
                shell.roughness = trim.metal.roughness;
                // The band's own coordinates run along each edge.
                shell.texcoords = Some(&trim.texcoords);
                shell.surface = Some((&trim.texcoords, textures));
                shells.push(shell);
            }
        }
        if let Some(laced) = &piece.lacing {
            let [red, green, blue] = laced.cord.color;
            let rigged = rigged_armor(
                &laced.name,
                &laced.name,
                &laced.generated,
                &lacing.faces[i],
                &lacing.targets[i],
            );
            for mut shell in rigged.plate {
                shell.base_color = [red, green, blue, 1.0];
                shell.metallic = 0.0;
                shell.roughness = laced.cord.roughness;
                shells.push(shell);
            }
        }
    }
    Ok(shells)
}

/// Chainmail appearance comes from the current recipe, not the drape.
fn mail_surfaces(
    loadout: &adventuresim_character_creator::inventory::Loadout<'_>,
    fitted: &[adventuresim_character_creator::garment::DrapedGarment],
) -> Result<Vec<Option<adventuresim_character_creator::garment_material::MailSurface>>> {
    fitted
        .iter()
        .enumerate()
        .map(|(index, garment)| {
            let selection = loadout
                .draped
                .get(index)
                .context("draped garment has no worn inventory article")?
                .selection;
            (garment.fabric == FabricPreset::Chainmail)
                .then(|| {
                    adventuresim_character_creator::garment_material::MailSurface::new(
                        &selection.mail,
                        &garment.texcoords,
                    )
                })
                .transpose()
        })
        .collect()
}

use super::character_morphs::{
    CharacterMorphs, MorphDelta, armor_targets, rigged_armor, rigged_clothing,
};
use super::*;
use adventuresim_character_creator::{
    equipment_catalog::{CatalogItem, CatalogPlacement, EquipmentItemSelection},
    item_design::ItemDesign,
};
use adventuresim_core::equipment_assets::{
    EQUIPMENT_MANIFEST_SCHEMA_VERSION, EQUIPMENT_MHR_RELEASE, GLB_EXTENSION,
    ProceduralEquipmentAsset, ProceduralEquipmentManifest,
};

struct EquipmentExporter<'a> {
    model: &'a BodyModel,
    recipe: &'a CharacterRecipe,
    generated: &'a GeneratedCharacter,
    morphs: &'a CharacterMorphs,
}

impl EquipmentExporter<'_> {
    fn mesh(&self) -> RiggedMesh<'_> {
        let character = &self.model.mhr.character;
        RiggedMesh {
            joint_proportions: &self.generated.joint_proportions,
            morph_targets: &[],
            positions: &self.generated.positions,
            normals: &self.generated.normals,
            faces: &character.mesh.faces,
            export_body: false,
            joint_indices: character.skin_weights.indices(),
            joint_weights: character.skin_weights.weights().as_native_slice(),
            joint_names: &character.skeleton.names,
            joint_parents: &character.skeleton.parents,
            global_joint_states: &self.generated.global_joint_states,
        }
    }
    fn armor(
        &self,
        output: &std::path::Path,
        selection: CatalogPlacement<'_>,
        design: &ItemDesign,
    ) -> Result<ProceduralEquipmentAsset> {
        let model = self.model;
        let recipe = self.recipe;
        let item = selection.item();
        let placement = selection.definition();
        let equipment = item
            .equipment
            .as_ref()
            .context("filtered equipment is missing its definition")?;
        let armor = parametric_equipment::fitted_catalog_item(
            model,
            self.generated,
            selection,
            design,
            &self.morphs.samples,
            &[],
        )?;
        let parametric_coverage = match design {
            ItemDesign::Vambrace(design) => design.coverage.unit(),
            ItemDesign::Recipe(_) | ItemDesign::Breastplate(_) => placement_coverage(placement),
        };
        let faces = armor.indices.as_chunks::<3>().0.to_vec();
        let morph_targets = armor_targets(&armor);
        let file_name = format!("{}--{}.glb", item.id, placement.id);
        let path = output.join(&file_name);
        let material = equipment.material.context("armor material missing")?;
        let metal = adventuresim_character_creator::armor_metal::metal(material, None)
            .map(|metal| adventuresim_character_creator::export::ShellTextures::armor(&metal))
            .transpose()?;
        // Catalog defaults carry no trim; that is an article's own finish.
        let mut rigged_shells = rigged_armor(
            &item.display_name,
            &item.display_name,
            &armor,
            &faces,
            &morph_targets,
        )
        .plate;
        let (color, metallic, roughness) = adventuresim_character_creator::equipment_pbr(material);
        for shell in &mut rigged_shells {
            shell.base_color = color;
            shell.metallic = metallic;
            shell.roughness = roughness;
            shell.textures =
                adventuresim_character_creator::underlayer_material::textures(design.recipe());
            shell.surface = metal
                .as_ref()
                .map(|textures| (armor.texcoords.as_slice(), textures));
        }
        crate::character_morphs::component_materials(&armor, &mut rigged_shells)?;
        export_rigged_glb(
            GlbOutput::SharedTextures(&path),
            &item.id,
            recipe.version,
            model.lod,
            &self.mesh(),
            &rigged_shells,
            &[],
        )?;
        Ok(ProceduralEquipmentAsset {
            item_id: item.id.clone(),
            placement_id: placement.id.clone(),
            file: file_name,
            coverage: parametric_coverage,
            material: equipment.material,
            triangles: faces.len(),
            armor_generator_version: Some(fabelgeist_armor::GENERATOR_VERSION),
            armor_design_hash: Some(
                armor
                    .design_hash
                    .iter()
                    .map(|byte| format!("{byte:02x}"))
                    .collect(),
            ),
            morph_targets: armor.morphs.len(),
            surface_uv_domain: Some(armor.surface_domain.clone()),
        })
    }
    fn garment(
        &self,
        output: &std::path::Path,
        selection: CatalogPlacement<'_>,
    ) -> Result<ProceduralEquipmentAsset> {
        let model = self.model;
        let recipe = self.recipe;
        let item = selection.item();
        let placement = selection.definition();
        let generated = self.generated;
        let morphs = self.morphs;
        let character = &model.mhr.character;
        let equipment = item
            .equipment
            .as_ref()
            .context("filtered equipment is missing its definition")?;
        let specification = GarmentSpecification::from_catalog(
            format!("{} · {}", item.display_name, placement.id).into(),
            selection,
        )?;
        let clothed = generate_clothing_shells(
            &[specification],
            &generated.positions,
            &generated.normals,
            &character.mesh.faces,
            character.skin_weights.indices(),
            character.skin_weights.weights().as_native_slice(),
            &character.skeleton.names,
            &generated.global_joint_states,
        )
        .map_err(anyhow::Error::msg)?;
        let targets = morphs.clothing(&clothed.shells)?;
        let targets = targets[0]
            .iter()
            .map(MorphDelta::rigged)
            .collect::<Vec<_>>();
        let shell = &clothed.shells[0];
        let file_name = format!("{}--{}.glb", item.id, placement.id);
        let path = output.join(&file_name);
        let rigged_shell = rigged_clothing(shell, &targets);
        let rigged_mesh = self.mesh();
        let sockets = self.sockets(item, &rigged_mesh, &rigged_shell)?;
        export_rigged_glb(
            GlbOutput::SharedTextures(&path),
            &item.id,
            recipe.version,
            model.lod,
            &rigged_mesh,
            &[rigged_shell],
            &sockets,
        )?;
        Ok(ProceduralEquipmentAsset {
            item_id: item.id.clone(),
            placement_id: placement.id.clone(),
            file: file_name,
            coverage: placement_coverage(placement),
            material: equipment.material,
            triangles: shell.faces.len(),
            morph_targets: targets.len(),
            armor_generator_version: None,
            armor_design_hash: None,
            surface_uv_domain: None,
        })
    }
    fn sockets<'a>(
        &self,
        item: CatalogItem<'a>,
        rigged_mesh: &RiggedMesh<'_>,
        rigged_shell: &RiggedShell<'_>,
    ) -> Result<Vec<RiggedSocket<'a>>> {
        let character = &self.model.mhr.character;
        let equipment = item
            .definition()
            .equipment
            .as_ref()
            .context("filtered equipment is missing its definition")?;
        let surface_uv_layout = SurfaceUvLayout {
            domain: MHR_ANATOMICAL_UV_DOMAIN,
            texcoords: &character.mesh.texcoords,
            texcoord_faces: &character.mesh.texcoord_faces,
        };
        equipment
            .attachment_points
            .iter()
            .filter(|point| point.tangent_direction.is_some())
            .map(|point| {
                let tangent = point
                    .tangent_direction
                    .context("filtered attachment tangent is missing")?;
                let outward = point
                    .locations
                    .iter()
                    .copied()
                    .find_map(belt_mount_outward)
                    .with_context(|| {
                        format!(
                            "item {} attachment point {} has a tangent but no belt location",
                            item.id, point.id
                        )
                    })?;
                let surface = point.surface_uv.as_ref().with_context(|| {
                    format!(
                        "item {} attachment point {} has a tangent but no anatomical surface UV",
                        item.id, point.id
                    )
                })?;
                if surface.domain != surface_uv_layout.domain {
                    anyhow::bail!(
                        "item {} attachment point {} uses unsupported anatomical UV domain {}",
                        item.id,
                        point.id,
                        surface.domain
                    );
                }
                fitted_equipment_socket_from_uv(
                    rigged_mesh,
                    rigged_shell,
                    &surface_uv_layout,
                    surface.uv,
                    outward,
                    tangent,
                )
                .with_context(|| {
                    format!(
                        "could not fit item {} attachment point {}",
                        item.id, point.id
                    )
                })
                .map(|transform| RiggedSocket {
                    attachment_point_id: &point.id,
                    surface_uv_domain: &surface.domain,
                    surface_uv: surface.uv,
                    transform,
                })
            })
            .collect::<Result<Vec<_>>>()
    }
}

pub(super) fn generate_equipment_assets(
    output: &std::path::Path,
    model: &BodyModel,
    recipe: &CharacterRecipe,
    catalog: &EquipmentCatalog,
    selection: &EquipmentItemSelection<'_>,
) -> Result<()> {
    if selection.is_filtered()
        && output.exists()
        && std::fs::read_dir(output)
            .with_context(|| format!("reading equipment output {}", output.display()))?
            .next()
            .is_some()
    {
        anyhow::bail!(
            "filtered equipment export requires a new or empty staging directory: {}",
            output.display()
        );
    }
    std::fs::create_dir_all(output)
        .with_context(|| format!("creating equipment output {}", output.display()))?;
    let generated = generate_character(model, recipe)?;
    let morphs = CharacterMorphs::generate(model, recipe, &generated)?;
    let exporter = EquipmentExporter {
        model,
        recipe,
        generated: &generated,
        morphs: &morphs,
    };
    let mut assets = Vec::new();
    let mut generated_files = std::collections::BTreeSet::new();
    for item in catalog.wearable() {
        if !selection.includes(item) {
            continue;
        }
        for placement in item.placements() {
            if placement.surface.is_empty() {
                continue;
            }
            let asset = if let Some(design) = catalog.placed_design(placement) {
                exporter
                    .armor(output, placement, &design)
                    .with_context(|| format!("exporting armor {} ({})", item.id, placement.id))?
            } else {
                anyhow::ensure!(
                    !matches!(
                        item.kind,
                        adventuresim_character_creator::item_catalog_schema::ItemKind::Armor { .. }
                    ),
                    "armor {} has no parametric generator",
                    item.id
                );
                exporter.garment(output, placement)?
            };
            generated_files.insert(format!("{}--{}.glb", item.id, placement.id));
            assets.push(asset);
        }
    }
    for entry in std::fs::read_dir(output)? {
        let path = entry?.path();
        if path
            .extension()
            .is_some_and(|extension| extension == GLB_EXTENSION)
            && path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| !generated_files.contains(name))
        {
            std::fs::remove_file(&path)
                .with_context(|| format!("removing stale generated asset {}", path.display()))?;
        }
    }
    let manifest = ProceduralEquipmentManifest {
        schema_version: EQUIPMENT_MANIFEST_SCHEMA_VERSION,
        mhr_release: EQUIPMENT_MHR_RELEASE.to_owned(),
        lod: model.lod,
        assets,
    };
    std::fs::write(
        output.join("manifest.json"),
        serde_json::to_vec_pretty(&serde_json::to_value(&manifest)?)?,
    )?;
    Ok(())
}

