#[derive(Resource, Default)]
pub struct WalkPreview {
    requested: Handle<Gltf>,
    graph: Option<Handle<AnimationGraph>>,
    node: Option<AnimationNodeIndex>,
    pub player: Option<Entity>,
    skeleton: Option<Entity>,
    pub joints: fabelgeist_rig::RigJointTable<Entity>,
    pub inverse_bindposes: Handle<SkinnedMeshInverseBindposes>,
    pub playing: bool,
    pub physics: bool,
    pub ignore_cloth_weights: bool,
    pub simulation: SimulationSettings,
}

#[derive(Clone, Debug)]
pub struct SimulationSettings {
    pub self_collision: bool,
    pub cloth_thickness: f32,
    pub contact_iterations: u32,
    pub gravity: f32,
    pub damping: f32,
    pub stretch_stiffness: f32,
    pub follow_strength: f32,
    pub collision_margin: f32,
    pub collision_distance: f32,
    pub substeps: u32,
    pub iterations: u32,
}

#[derive(Component)]
struct PreviewSkeleton;

// Preserve all eight exported influences. Reducing each vertex independently
// to four can discard the opposite leg precisely at the centre transition.
#[derive(Component)]
pub struct BodySkin {
    pub positions: Vec<[f32; 3]>,
    pub faces: Vec<[u32; 3]>,
    pub indices: fabelgeist_rig::PackedRigSkin<8>,
    pub weights: Vec<[f32; 8]>,
}

#[derive(Component)]
pub struct ClothSkin {
    render_vertices: Option<Vec<usize>>,
    form: GarmentForm,
    positions: Vec<[f32; 3]>,
    faces: Vec<[u32; 3]>,
    edges: Vec<[u32; 2]>,
    binding: ClothBinding,
    current: Vec<Vec3>,
    previous: Vec<Vec3>,
    motion: ClothMotion,
}

#[derive(Default)]
pub struct BodyMotion {
    rig: Option<Entity>,
    positions: Vec<Vec3>,
}

impl Default for SimulationSettings {
    fn default() -> Self {
        Self {
            self_collision: true,
            cloth_thickness: 0.004,
            contact_iterations: 3,
            gravity: 9.81,
            damping: 0.015,
            stretch_stiffness: 0.96,
            follow_strength: 1.0,
            collision_margin: 0.006,
            collision_distance: 0.08,
            substeps: 2,
            iterations: 3,
        }
    }
}

impl WalkPreview {
    pub fn ready(&self) -> bool {
        self.player.is_some() && self.graph.is_some() && self.node.is_some()
    }

    pub fn start_or_resume(&self, player: &mut AnimationPlayer) {
        if player.playing_animations().next().is_none() {
            player
                .play(self.node.expect("ready walk preview has a graph node"))
                .repeat();
        } else {
            player.resume_all();
        }
    }
}

impl ClothSkin {
    pub fn new(
        form: GarmentForm,
        positions: Vec<[f32; 3]>,
        _normals: Vec<[f32; 3]>,
        faces: Vec<[u32; 3]>,
        binding: ClothBinding,
    ) -> Result<Self> {
        if let ClothBinding::Weighted { indices, weights } = &binding {
            anyhow::ensure!(
                indices.len() == positions.len() && weights.len() == positions.len(),
                "cloth skin rows and positions have different vertex counts"
            );
        }
        let mut edges = std::collections::BTreeSet::new();
        for face in &faces {
            for [a, b] in [[face[0], face[1]], [face[1], face[2]], [face[2], face[0]]] {
                edges.insert(if a < b { [a, b] } else { [b, a] });
            }
        }
        let current: Vec<Vec3> = positions.iter().copied().map(Vec3::from_array).collect();
        Ok(Self {
            render_vertices: None,
            form,
            positions,
            faces,
            edges: edges.into_iter().collect(),
            binding,
            previous: current.clone(),
            current,
            motion: ClothMotion::Skinned,
        })
    }
}

pub fn request(mut preview: ResMut<WalkPreview>, assets: Res<AssetServer>) {
    preview.requested = assets.load("animations/biped/unarmed/walk.glb");
}

pub fn prepare(
    mut commands: Commands,
    mut preview: ResMut<WalkPreview>,
    gltfs: Res<Assets<Gltf>>,
    mut graphs: ResMut<Assets<AnimationGraph>>,
) {
    if preview.graph.is_none()
        && let Some(gltf) = gltfs.get(&preview.requested)
        && let Some(clip) = gltf.animations.first()
    {
        let (graph, node) = AnimationGraph::from_clip(clip.clone());
        preview.graph = Some(graphs.add(graph));
        preview.node = Some(node);
    }
    let (Some(player), Some(graph)) = (preview.player, preview.graph.clone()) else {
        return;
    };
    if let Ok(mut entity) = commands.get_entity(player) {
        entity.try_insert(AnimationGraphHandle(graph));
    }
}

pub fn rebuild(
    preview: &mut WalkPreview,
    commands: &mut Commands,
    inverse_bindposes: &mut Assets<SkinnedMeshInverseBindposes>,
    model: &BodyModel,
    generated: &GeneratedCharacter,
) {
    if let Some(root) = preview.skeleton.take() {
        commands.entity(root).despawn();
    }
    if let Some(player) = preview.player.take() {
        commands.entity(player).despawn();
    }
    preview.playing = false;

    let player = commands
        .spawn((
            Name::new("Character walk player"),
            AnimationPlayer::default(),
        ))
        .id();
    if let Some(graph) = preview.graph.clone() {
        commands.entity(player).insert(AnimationGraphHandle(graph));
    }
    let skeleton_name = Name::new("Skeleton");
    let skeleton = commands
        .spawn((
            PreviewSkeleton,
            skeleton_name.clone(),
            Transform::default(),
            AnimationTargetId::from_names([&skeleton_name].into_iter()),
            AnimatedBy(player),
            Visibility::Hidden,
        ))
        .id();

    let character = &model.mhr.character;
    let globals: fabelgeist_rig::RigJointTable<_> = generated
        .global_joint_states
        .iter()
        .copied()
        .map(mhr_state)
        .collect();
    let mut joints = fabelgeist_rig::RigJointTable::default();
    for (index, name) in character.skeleton.names.indexed() {
        let parent = character.skeleton.parents[index];
        let local = match parent {
            None => globals[index],
            Some(parent) => globals[parent].inverse().compose(&globals[index]),
        };
        let mut path = vec![skeleton_name.clone()];
        let mut lineage = vec![index];
        let mut ancestor = parent;
        while let Some(joint) = ancestor {
            lineage.push(joint);
            ancestor = character.skeleton.parents[joint];
        }
        for joint in lineage.into_iter().rev() {
            path.push(bevy_joint_name(&character.skeleton.names[joint]));
        }
        let entity = commands
            .spawn((
                bevy_joint_name(name),
                bevy_transform(local),
                AnimationTargetId::from_names(path.iter()),
                AnimatedBy(player),
            ))
            .id();
        let parent_entity = parent.map_or(skeleton, |parent| joints[parent]);
        commands.entity(parent_entity).add_child(entity);
        joints.push(entity);
    }
    let matrices = globals
        .into_iter()
        .map(|state| {
            let inverse = state.inverse();
            Mat4::from_scale_rotation_translation(
                Vec3::splat(inverse.scale as f32),
                Quat::from_xyzw(
                    inverse.rotation[0] as f32,
                    inverse.rotation[1] as f32,
                    inverse.rotation[2] as f32,
                    inverse.rotation[3] as f32,
                ),
                Vec3::new(
                    inverse.translation[0] as f32,
                    inverse.translation[1] as f32,
                    inverse.translation[2] as f32,
                ),
            )
        })
        .collect::<Vec<_>>();
    preview.inverse_bindposes = inverse_bindposes.add(SkinnedMeshInverseBindposes::from(matrices));
    preview.player = Some(player);
    preview.skeleton = Some(skeleton);
    preview.joints = joints;
}

#[expect(
    clippy::too_many_arguments,
    reason = "Bevy injects these system parameters independently"
)]
pub fn deform_cloth(
    preview: Res<WalkPreview>,
    time: Res<Time>,
    binds: Res<Assets<SkinnedMeshInverseBindposes>>,
    joints: Query<&GlobalTransform>,
    bodies: Query<&BodySkin>,
    armor: Query<&ArmorSkin>,
    mut cloth: Query<(&Mesh3d, &mut ClothSkin)>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut body_motion: Local<BodyMotion>,
) {
    if !preview.playing {
        return;
    }
    let Some(bind) = binds.get(&preview.inverse_bindposes) else {
        return;
    };
    let Some(matrices) = preview
        .joints
        .iter()
        .zip(bind.iter())
        .map(|(entity, inverse)| {
            joints
                .get(*entity)
                .ok()
                .map(|global| global.to_matrix() * *inverse)
        })
        .collect::<Option<fabelgeist_rig::RigJointTable<_>>>()
    else {
        return;
    };
    let rig = preview.joints.first().copied();
    let body = bodies.iter().next().map(|body| {
        let (rest, end, faces) = colliders::posed_colliders(body, &armor, &matrices);
        let start = if body_motion.rig == rig && body_motion.positions.len() == end.len() {
            body_motion.positions.clone()
        } else {
            rest
        };
        (start, end, faces)
    });
    let targets = cloth
        .iter()
        .map(|(_, skin)| {
            if preview.physics && preview.ignore_cloth_weights {
                return Some(None);
            }
            let ClothBinding::Weighted { indices, weights } = &skin.binding else {
                return None;
            };
            if indices.joint_count().len() != matrices.len() {
                return None;
            }
            Some(Some(skinned_positions(
                &skin.positions,
                indices,
                weights,
                &matrices,
            )))
        })
        .collect::<Option<Vec<_>>>();
    let Some(targets) = targets else {
        // Weighted playback cannot evaluate unbound cloth. Keep its last
        // geometry until a binding or unweighted physics is selected.
        return;
    };

    if preview.physics {
        cloth_motion::simulate_outfit(
            &mut cloth,
            &body,

            &targets,
            time.delta_secs(),
            &preview.simulation,
        );
    } else {
        for (index, (_, mut skin)) in cloth.iter_mut().enumerate() {
            let Some(target) = targets[index].as_ref() else {
                return;
            };
            skin.current.clone_from(target);
            skin.previous.clone_from(target);
            skin.motion = ClothMotion::Skinned;
        }
    }
    if let Some((_, end, _)) = body {
        body_motion.rig = rig;
        body_motion.positions = end;
    } else {
        body_motion.positions.clear();
        body_motion.rig = None;
    }
    for (handle, skin) in &cloth {
        if let Some(mut mesh) = meshes.get_mut(handle) {
            skin.update_render_mesh(&mut mesh);
        }
    }
}

/// Native Bevy naming boundary. A `From` implementation here is forbidden by
/// orphan rules: both `Name` and `RigJointName` belong to other crates. Keeping
/// this adapter here also keeps the shared rig owner independent of Bevy.
fn bevy_joint_name(name: &fabelgeist_rig::RigJointName) -> Name {
    Name::new(std::borrow::Cow::from(name.clone()))
}

fn mhr_state(value: [f32; 8]) -> fabelgeist_mhr::math::Transform {
    fabelgeist_mhr::math::Transform {
        translation: [value[0] as f64, value[1] as f64, value[2] as f64],
        rotation: [
            value[3] as f64,
            value[4] as f64,
            value[5] as f64,
            value[6] as f64,
        ],
        scale: value[7] as f64,
    }
}

fn bevy_transform(value: fabelgeist_mhr::math::Transform) -> Transform {
    Transform {
        translation: Vec3::new(
            value.translation[0] as f32,
            value.translation[1] as f32,
            value.translation[2] as f32,
        ),
        rotation: Quat::from_xyzw(
            value.rotation[0] as f32,
            value.rotation[1] as f32,
            value.rotation[2] as f32,
            value.rotation[3] as f32,
        ),
        scale: Vec3::splat(value.scale as f32),
    }
}

fn collision_vector(p: Vec3) -> fabelgeist_math::Vec3 {
    fabelgeist_math::Vec3::new(p.x, p.y, p.z)
}

fn skinned_positions(
    positions: &[[f32; 3]],
    indices: &fabelgeist_rig::PackedRigSkin<8>,
    weights: &[[f32; 8]],
    matrices: &fabelgeist_rig::RigJointTable<Mat4>,
) -> Vec<Vec3> {
    positions
        .iter()
        .enumerate()
        .map(|(v, p)| {
            blend_point(
                Vec3::from_array(*p),
                indices.vertex(v),
                weights[v],
                matrices,
            )
        })
        .collect()
}

fn surface_normals(positions: &[Vec3], faces: &[[u32; 3]]) -> Vec<Vec3> {
    let mut normals = vec![Vec3::ZERO; positions.len()];
    for face in faces {
        let [a, b, c] = face.map(|v| v as usize);
        let normal = (positions[b] - positions[a]).cross(positions[c] - positions[a]);
        normals[a] += normal;
        normals[b] += normal;
        normals[c] += normal;
    }
    normals.into_iter().map(|n| n.normalize_or_zero()).collect()
}

fn blend_point(
    point: Vec3,
    indices: [fabelgeist_rig::RigJointOrdinal; 8],
    weights: [f32; 8],
    matrices: &fabelgeist_rig::RigJointTable<Mat4>,
) -> Vec3 {
    indices
        .into_iter()
        .zip(weights)
        .filter(|(_, w)| *w > 0.0)
        .fold(Vec3::ZERO, |sum, (joint, weight)| {
            sum + matrices[joint].transform_point3(point) * weight
        })
}

#[cfg(test)]
