        strength: physical,
        agility: physical,
    };
    let skills = StartingSkills {
        sword: hours,
        polearm: hours,
        bludgeon: hours,
        knife: hours,
        dodge: hours,
        block: hours,
        will: hours,
        balance: hours,
        ..StartingSkills::default()
    };
    let spec = StartingCharacterSpec {
        id: stable_id(key),
        name_identity: PersonalNameIdentity::authored(name, Culture::German),
        age_years: 28,
        background: description.into(),
        personality: crate::starting_character::default_character(key).personality,
        attributes,
        skills,
        currency: 0,
        settlement_selector: fabelgeist_determinism::Seed::from_u64(0),
        inventory: Vec::new(),
        age_tier: crate::starting_character::StartingAgeTier::Adult,
        profession: None,
        organization: None,
        religion_id: None,
    };
    build_from_spec(
        key,
