        description,
        equipment_description,
        &spec,
        weapon,
        armor,
        shield,
    )
}

fn stable_id(value: &str) -> u64 {
    value.bytes().fold(0xcbf2_9ce4_8422_2325, |hash, byte| {
        (hash ^ u64::from(byte)).wrapping_mul(0x100_0000_01b3)
    })
}

