149:     /// Refines every coarse cell by an integer factor and evaluates one
150:     /// authoritative height function at the resulting vertices. The original
151:     /// grid remains implicit as the coarse render LOD through `coarse_stride`.
152:     pub fn refined(
153:         &self,
154:         target_spacing: f32,
155:         height_at: impl Fn(ScenePlanPoint, SupportElevation) -> Option<SupportElevation>,
156:     ) -> Option<Self> {
157:         if !matches!(self.geometry, TerrainGeometry::Sampled)
158:             || !target_spacing.is_finite()
159:             || target_spacing <= 0.0
160:         {
161:             return None;
162:         }
163:         let subdivisions = (self.scale / target_spacing).ceil().max(1.0) as usize;
164:         let cells_x = self
165:             .grid_width()
166:             .checked_sub(1)?
167:             .checked_mul(subdivisions)?;
168:         let cells_z = self
169:             .grid_depth()
170:             .checked_sub(1)?
171:             .checked_mul(subdivisions)?;
172:         let width = cells_x.checked_add(1)?;
173:         let depth = cells_z.checked_add(1)?;
174:         let scale = self.scale / subdivisions as f32;
175:         admission::validate_dimensions(width, depth, scale, subdivisions).ok()?;
176:         let half_extent = Vec2::new(self.width(), self.depth()) * 0.5;
177:         let mut heights = Vec::with_capacity(width.checked_mul(depth)?);
178:         for z in 0..depth {
179:             for x in 0..width {
180:                 let point = ScenePlanPoint::from_metres(
181:                     Vec2::new(x as f32 * scale, z as f32 * scale) - half_extent,
182:                 )?;
183:                 let base_height = self.height_at(point)?;
184:                 let height = height_at(point, base_height)?;
185:                 heights.push(height.metres());
186:             }
187:         }
188:         let terrain = Self {
189:             heightmap: heights,
190:             width,
191:             scale,
192:             coarse_stride: subdivisions,
193:             geometry: TerrainGeometry::Sampled,
194:         };
195:         terrain.validate().ok()?;
196:         Some(terrain)
197:     }
