287:         // traversal iterative, including for a deeply nested decoded tree.
288:         // A balanced compiler tree fits within address-bit depth. SmallVec
289:         // still grows for encoded trees, junction owners and extra candidates.
290:         let mut pending = SmallVec::<[usize; usize::BITS as usize]>::new();
291:         pending.push(index);
292:         while let Some(index) = pending.pop() {
293:             let node = &self.0[index];
294:             if point.cmplt(node.minimum - tolerance).any()
295:                 || point.cmpgt(node.maximum + tolerance).any()
296:             {
297:                 continue;
298:             }
299:             match &node.children {
300:                 QueryChildren::Branch { left, right } => pending.extend([*right, *left]),
301:                 QueryChildren::Leaf(triangles) => {
302:                     for reference in triangles {
