 47 impl PropertySupportSurface {
 48     pub(crate) fn validate_encoded(&self) -> Result<(), SupportSurfaceIssue> {
 49         let members = &self.mesh.member_building_ids;
 50         if self.property_id().0 == 0
 51             || self.property_id().0 > crate::city_layout::MAX_CITY_LOTS as u64
 52             || members.is_empty()
 53             || members.len() > 2
 54             || members.iter().any(|id| id.0 == 0)
 55             || members
 56                 .iter()
 57                 .enumerate()
 58                 .any(|(i, id)| members[..i].contains(id))
 59         {
 60             return Err(SupportSurfaceIssue::Members);
 61         }
 62         let treatment_matches_members = match self.treatment {
 63             SupportGradingAttempt::SingleBuildingFloorAndEntrances => members.len() == 1,
 64             SupportGradingAttempt::Compound(_) => members.len() == 2,
 65             SupportGradingAttempt::NotSelected => false,
 66         };
 67         if !treatment_matches_members {
 68             return Err(SupportSurfaceIssue::Treatment);
 69         }
 70         if self.mesh.contact_tolerance_metres != self.limits.contact_tolerance_metres.metres()
 71             || self.regions.is_empty()
 72             || self.regions.len() != self.clipping_outlines.len()
 73             || self.regions.iter().any(|region| !region.is_valid())
 74             || self
 75                 .clipping_outlines
 76                 .iter()
 77                 .any(|outline| !valid_outline(outline))
 78             || self
 79                 .regions
 80                 .iter()
 81                 .zip(&self.clipping_outlines)
 82                 .any(|(region, outline)| {
 83                     outline
 84                         .iter()
 85                         .any(|point| !region.contains(point.as_vec2()))
 86                 })
 87         {
 88             return Err(SupportSurfaceIssue::Bounds);
 89         }
 90         if self.mesh.positions.is_empty()
 91             || self.mesh.positions.iter().any(|p| !p.is_finite())
 92             || self.mesh.support_triangles.is_empty()
 93             || self
 94                 .mesh
 95                 .support_triangles
 96                 .iter()
 97                 .chain(&self.mesh.retaining_triangles)
 98                 .any(|indices| {
 99                     indices
100                         .iter()
101                         .any(|i| *i as usize >= self.mesh.positions.len())
102                         || indices[0] == indices[1]
103                         || indices[1] == indices[2]
104                         || indices[2] == indices[0]
105                 })
106             || self.mesh.support_triangles.iter().any(|indices| {
107                 let [a, b, c] = indices.map(|i| self.mesh.positions[i as usize]);
108                 let normal = (b - a).cross(c - a);
109                 !normal.is_finite() || normal.y == 0.0
110             })
111         {
112             return Err(SupportSurfaceIssue::Topology);
113         }
114         if self.mesh.positions.iter().any(|point| {
115             !self
116                 .clipping_outlines
117                 .iter()
118                 .any(|outline| contains(outline, Vec2::new(point.x, point.z)))
119         }) {
120             return Err(SupportSurfaceIssue::Bounds);
121         }
122         let measured_grade = self.mesh.maximum_grade();
123         if measured_grade > self.limits.maximum_grade.ratio() {
124             return Err(SupportSurfaceIssue::Grade {
125                 measured_grade: GeographicGrade::from_ratio(f64::from(measured_grade))
126                     .ok_or(SupportSurfaceIssue::Topology)?,
127                 permitted_grade: self.limits.maximum_grade,
128             });
129         }
130         self.validate_floors()
131     }
132 }
133 
134 fn valid_outline(outline: &[bevy::math::DVec2]) -> bool {
135     outline.len() >= 3
136         && outline.iter().all(|p| p.is_finite())
137         && planar::signed_area(outline) > 0.0
138         && (0..outline.len()).all(|i| {
139             let a = outline[i];
140             let edge = outline[(i + 1) % outline.len()] - a;
141             edge.length_squared() > 0.0
142                 && outline.iter().all(|point| {
143                     edge.perp_dot(*point - a)
144                         >= -edge.length() * CityPlotBounds::COORDINATE_TOLERANCE_METRES
145                 })
146         })
147 }
148 
149 fn contains(outline: &[bevy::math::DVec2], point: Vec2) -> bool {
150     (0..outline.len()).all(|i| {
151         let a = outline[i];
152         let edge = outline[(i + 1) % outline.len()] - a;
153         edge.perp_dot(point.as_dvec2() - a)
154             >= -edge.length() * CityPlotBounds::COORDINATE_TOLERANCE_METRES
155     })
156 }
