20     pub fn new(mut points: [Vec3; 3]) -> Option<Self> {
21         if points.iter().any(|p| !p.is_finite()) {
22             return None;
23         }
24         let first = (0..3).min_by(|a, b| compare_point(points[*a], points[*b]))?;
25         points.rotate_left(first);
26         let ab = points[1].xz().as_dvec2() - points[0].xz().as_dvec2();
27         let ac = points[2].xz().as_dvec2() - points[0].xz().as_dvec2();
28         let signed_area = ab.perp_dot(ac);
29         // Bound the coordinate differences, products and subtraction in the
30         // stored order used by height_f64. Clipping slivers whose determinant
31         // is lost to cancellation cannot define a measurable affine plane.
32         // This bound has area units and scales quadratically with the face.
33         let determinant_roundoff = 8.0 * f64::EPSILON * ((ab.x * ac.y).abs() + (ab.y * ac.x).abs());
34         if signed_area.abs() <= determinant_roundoff {
35             return None;
36         }
37         if signed_area < 0.0 {
38             points.swap(1, 2);
39         }
40         let [a, b, c] = points;
41         use adventuresim_building_generator::spatial_geometry::Position;
42         Some(Self([
43             Position::from_metres(a).ok()?,
44             Position::from_metres(b).ok()?,
45             Position::from_metres(c).ok()?,
46         ]))
47     }
