49     /// Offset all three half-planes by a distance. The resulting triangle is
50     /// homothetic about its incenter; the farthest vertex displacement bounds
51     /// both coordinate expansions, including acute corners.
52     pub fn boundary_extension_factor(&self) -> f64 {
53         let points = self.points().map(|p| p.xz().as_dvec2());
54         let lengths = [
55             points[1].distance(points[2]),
56             points[2].distance(points[0]),
57             points[0].distance(points[1]),
58         ];
59         let perimeter = lengths.iter().sum::<f64>();
60         let incenter = (0..3)
61             .map(|i| points[i] * lengths[i])
62             .sum::<bevy::math::DVec2>()
63             / perimeter;
64         let inradius = self.area() * 2.0 / perimeter;
65         points
66             .into_iter()
67             .map(|p| p.distance(incenter) / inradius)
68             .fold(0.0, f64::max)
69     }
