122     /// A float query denotes its rounding cell. Admit that cell at a declared
123     /// edge without extending ownership by an architectural contact margin.
124     /// This matters when a represented midpoint rounds just outside its face.
125     /// The rounding-cell diagonal is independent of triangle geometry, so a
126     /// multi-face query computes it once while retaining the same edge rule.
127     pub fn represented_point_tolerance(point: Vec2) -> f32 {
128         let half_quantum = |coordinate: f32| {
129             let upper = f64::from(coordinate.next_up()) - f64::from(coordinate);
130             let lower = f64::from(coordinate) - f64::from(coordinate.next_down());
131             upper.max(lower) * 0.5
132         };
133         let uncertainty = half_quantum(point.x).hypot(half_quantum(point.y));
134         (uncertainty as f32).next_up()
135     }

