55 pub(super) fn signed_area(polygon: &[bevy::math::DVec2]) -> f64 {
56     let Some(origin) = polygon.first() else {
57         return 0.0;
58     };
59     polygon
60         .iter()
61         .zip(polygon.iter().cycle().skip(1))
62         .take(polygon.len())
63         .map(|(a, b)| (*a - *origin).perp_dot(*b - *origin))
64         .sum::<f64>()
65         * 0.5
66 }
