68 /// Distance to the complete convex outline; an interior point is supported.
69 pub(super) fn distance_outside(point: bevy::math::DVec2, outline: &[bevy::math::DVec2]) -> f64 {
70     if (0..outline.len()).all(|i| {
71         (outline[(i + 1) % outline.len()] - outline[i]).perp_dot(point - outline[i]) >= 0.0
72     }) {
73         return 0.0;
74     }
75     (0..outline.len())
76         .map(|i| {
77             let a = outline[i];
78             let edge = outline[(i + 1) % outline.len()] - a;
79             let fraction = ((point - a).dot(edge) / edge.length_squared()).clamp(0.0, 1.0);
80             point.distance(a + edge * fraction)
81         })
82         .fold(f64::INFINITY, f64::min)
83 }

